window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["EZK"]={"book":"EZK","editions":{"hbo-source":[[1,1,"וַ⁠יְהִ֣י ׀ בִּ⁠שְׁלֹשִׁ֣ים שָׁנָ֗ה בָּֽ⁠רְבִיעִי֙ בַּ⁠חֲמִשָּׁ֣ה לַ⁠חֹ֔דֶשׁ וַ⁠אֲנִ֥י בְ⁠תֽוֹךְ־הַ⁠גּוֹלָ֖ה עַל־נְהַר־כְּבָ֑ר נִפְתְּחוּ֙ הַ⁠שָּׁמַ֔יִם וָ⁠אֶרְאֶ֖ה מַרְא֥וֹת אֱלֹהִֽים׃","wa⁠yĕhi֣y ׀ bi̇⁠şĕ̌lòşǐ֣ym şá̌ná֗h báֽ̇⁠rĕbiyʻiy֙ bȧ⁠ẖàmişá֣̇̌h la⁠ẖò֔deş̌ wa⁠ʼàni֥y bĕ⁠ţֽwòkĕ-ha⁠ġwòlá֖h ʻal-nĕhar-kĕ̇bá֑r nipĕţĕ̇ẖẇ֙ ha⁠şá̇̌ma֔yim wá⁠ʼerĕʼe֖h marĕʼ֥wòţ ʼèlòhiֽym׃"],[1,2,"בַּ⁠חֲמִשָּׁ֖ה לַ⁠חֹ֑דֶשׁ הִ֚יא הַ⁠שָּׁנָ֣ה הַ⁠חֲמִישִׁ֔ית לְ⁠גָל֖וּת הַ⁠מֶּ֥לֶךְ יוֹיָכִֽין׃","bȧ⁠ẖàmişá֖̇̌h la⁠ẖò֑deş̌ hi֚yʼ ha⁠şá̇̌ná֣h ha⁠ẖàmiyşǐ֔yţ lĕ⁠gál֖ẇţ ha⁠mė֥lekĕ ywòyákiֽyn׃"],[1,3,"הָיֹ֣ה הָיָ֣ה דְבַר־יְ֠הוָה אֶל־יְחֶזְקֵ֨אל בֶּן־בּוּזִ֧י הַ⁠כֹּהֵ֛ן בְּ⁠אֶ֥רֶץ כַּשְׂדִּ֖ים עַל־נְהַר־כְּבָ֑ר וַ⁠תְּהִ֥י עָלָ֛י⁠ו שָׁ֖ם יַד־יְהוָֽה׃","háyò֣h háyá֣h dĕbar-yĕ֠hwáh ʼel-yĕẖezĕqé֨ʼl bėn-ḃẇzi֧y ha⁠kò̇hé֛n bĕ̇⁠ʼe֥reẕ kȧşĕ̂di֖̇ym ʻal-nĕhar-kĕ̇bá֑r wa⁠ţĕ̇hi֥y ʻálá֛y⁠w şá֖̌m yad-yĕhwáֽh׃"],[1,4,"וָ⁠אֵ֡רֶא וְ⁠הִנֵּה֩ ר֨וּחַ סְעָרָ֜ה בָּאָ֣ה מִן־הַ⁠צָּפ֗וֹן עָנָ֤ן גָּדוֹל֙ וְ⁠אֵ֣שׁ מִתְלַקַּ֔חַת וְ⁠נֹ֥גַֽהּ ל֖⁠וֹ סָבִ֑יב וּ⁠מִ֨⁠תּוֹכָ֔⁠הּ כְּ⁠עֵ֥ין הַ⁠חַשְׁמַ֖ל מִ⁠תּ֥וֹךְ הָ⁠אֵֽשׁ׃","wá⁠ʼé֡reʼ wĕ⁠hiné̇h֩ r֨ẇẖa sĕʻárá֜h bá̇ʼá֣h min-ha⁠ẕá̇p֗wòn ʻáná֤n gá̇dwòl֙ wĕ⁠ʼé֣ş̌ miţĕlaqȧ֔ẖaţ wĕ⁠nò֥gaֽḣ l֖⁠wò sábi֑yb ẇ⁠mi֨⁠ţ̇wòká֔⁠ḣ kĕ̇⁠ʻé֥yn ha⁠ẖaşĕ̌ma֖l mi⁠ţ֥̇wòkĕ há⁠ʼéֽş̌׃"],[1,5,"וּ⁠מִ֨⁠תּוֹכָ֔⁠הּ דְּמ֖וּת אַרְבַּ֣ע חַיּ֑וֹת וְ⁠זֶה֙ מַרְאֵֽי⁠הֶ֔ן דְּמ֥וּת אָדָ֖ם לָ⁠הֵֽנָּה׃","ẇ⁠mi֨⁠ţ̇wòká֔⁠ḣ dĕ̇m֖ẇţ ʼarĕbȧ֣ʻ ẖaẏ֑wòţ wĕ⁠zeh֙ marĕʼéֽy⁠he֔n dĕ̇m֥ẇţ ʼádá֖m lá⁠héֽná̇h׃"],[1,6,"וְ⁠אַרְבָּעָ֥ה פָנִ֖ים לְ⁠אֶחָ֑ת וְ⁠אַרְבַּ֥ע כְּנָפַ֖יִם לְ⁠אַחַ֥ת לָ⁠הֶֽם׃","wĕ⁠ʼarĕbá̇ʻá֥h páni֖ym lĕ⁠ʼeẖá֑ţ wĕ⁠ʼarĕbȧ֥ʻ kĕ̇nápa֖yim lĕ⁠ʼaẖa֥ţ lá⁠heֽm׃"],[1,7,"וְ⁠רַגְלֵי⁠הֶ֖ם רֶ֣גֶל יְשָׁרָ֑ה וְ⁠כַ֣ף רַגְלֵי⁠הֶ֗ם כְּ⁠כַף֙ רֶ֣גֶל עֵ֔גֶל וְ⁠נֹ֣צְצִ֔ים כְּ⁠עֵ֖ין נְחֹ֥שֶׁת קָלָֽל׃","wĕ⁠ragĕléy⁠he֖m re֣gel yĕşá̌rá֑h wĕ⁠ka֣p ragĕléy⁠he֗m kĕ̇⁠kap֙ re֣gel ʻé֔gel wĕ⁠nò֣ẕĕẕi֔ym kĕ̇⁠ʻé֖yn nĕẖò֥şěţ qáláֽl׃"],[1,8,"ו⁠יד⁠ו אָדָ֗ם מִ⁠תַּ֨חַת֙ כַּנְפֵי⁠הֶ֔ם עַ֖ל אַרְבַּ֣עַת רִבְעֵי⁠הֶ֑ם וּ⁠פְנֵי⁠הֶ֥ם וְ⁠כַנְפֵי⁠הֶ֖ם לְ⁠אַרְבַּעְתָּֽ⁠ם׃","w⁠yd⁠w ʼádá֗m mi⁠ţȧ֨ẖaţ֙ kȧnĕpéy⁠he֔m ʻa֖l ʼarĕbȧ֣ʻaţ ribĕʻéy⁠he֑m ẇ⁠pĕnéy⁠he֥m wĕ⁠kanĕpéy⁠he֖m lĕ⁠ʼarĕbȧʻĕţáֽ̇⁠m׃"],[1,9,"חֹֽבְרֹ֛ת אִשָּׁ֥ה אֶל־אֲחוֹתָ֖⁠הּ כַּנְפֵי⁠הֶ֑ם לֹא־יִסַּ֣בּוּ בְ⁠לֶכְתָּ֔⁠ן אִ֛ישׁ אֶל־עֵ֥בֶר פָּנָ֖י⁠ו יֵלֵֽכוּ׃","ẖòֽbĕrò֛ţ ʼişá֥̇̌h ʼel-ʼàẖwòţá֖⁠ḣ kȧnĕpéy⁠he֑m lòʼ-yisȧ֣ḃẇ bĕ⁠lekĕţá̇֔⁠n ʼi֛yş̌ ʼel-ʻé֥ber pá̇ná֖y⁠w yéléֽkẇ׃"],[1,10,"וּ⁠דְמ֣וּת פְּנֵי⁠הֶם֮ פְּנֵ֣י אָדָם֒ וּ⁠פְנֵ֨י אַרְיֵ֤ה אֶל־הַ⁠יָּמִין֙ לְ⁠אַרְבַּעְתָּ֔⁠ם וּ⁠פְנֵי־שׁ֥וֹר מֵֽ⁠הַ⁠שְּׂמֹ֖אול לְ⁠אַרְבַּעְתָּ֑⁠ן וּ⁠פְנֵי־נֶ֖שֶׁר לְ⁠אַרְבַּעְתָּֽ⁠ן׃","ẇ⁠dĕm֣ẇţ pĕ̇néy⁠hem֮ pĕ̇né֣y ʼádám֒ ẇ⁠pĕné֨y ʼarĕyé֤h ʼel-ha⁠yá̇miyn֙ lĕ⁠ʼarĕbȧʻĕţá̇֔⁠m ẇ⁠pĕnéy-ş֥̌wòr méֽ⁠ha⁠şĕ̇̂mò֖ʼwl lĕ⁠ʼarĕbȧʻĕţá֑̇⁠n ẇ⁠pĕnéy-ne֖şěr lĕ⁠ʼarĕbȧʻĕţáֽ̇⁠n׃"],[1,11,"וּ⁠פְנֵי⁠הֶ֕ם וְ⁠כַנְפֵי⁠הֶ֥ם פְּרֻד֖וֹת מִ⁠לְ⁠מָ֑עְלָ⁠ה לְ⁠אִ֗ישׁ שְׁ֚תַּיִם חֹבְר֣וֹת אִ֔ישׁ וּ⁠שְׁתַּ֣יִם מְכַסּ֔וֹת אֵ֖ת גְּוִיֹתֵי⁠הֶֽנָה׃","ẇ⁠pĕnéy⁠he֕m wĕ⁠kanĕpéy⁠he֥m pĕ̇rud֖wòţ mi⁠lĕ⁠má֑ʻĕlá⁠h lĕ⁠ʼi֗yş̌ şĕ֚̌ţȧyim ẖòbĕr֣wòţ ʼi֔yş̌ ẇ⁠şĕ̌ţȧ֣yim mĕkaṡ֔wòţ ʼé֖ţ gĕ̇wiyòţéy⁠heֽnáh׃"],[1,12,"וְ⁠אִ֛ישׁ אֶל־עֵ֥בֶר פָּנָ֖י⁠ו יֵלֵ֑כוּ אֶ֣ל אֲשֶׁר֩ יִֽהְיֶה־שָׁ֨מָּ⁠ה הָ⁠ר֤וּחַ לָ⁠לֶ֨כֶת֙ יֵלֵ֔כוּ לֹ֥א יִסַּ֖בּוּ בְּ⁠לֶכְתָּֽ⁠ן׃","wĕ⁠ʼi֛yş̌ ʼel-ʻé֥ber pá̇ná֖y⁠w yélé֑kẇ ʼe֣l ʼàşěr֩ yiֽhĕyeh-şá̌֨má̇⁠h há⁠r֤ẇẖa lá⁠le֨keţ֙ yélé֔kẇ lò֥ʼ yisȧ֖ḃẇ bĕ̇⁠lekĕţáֽ̇⁠n׃"],[1,13,"וּ⁠דְמ֨וּת הַ⁠חַיּ֜וֹת מַרְאֵי⁠הֶ֣ם כְּ⁠גַחֲלֵי־אֵ֗שׁ בֹּֽעֲרוֹת֙ כְּ⁠מַרְאֵ֣ה הַ⁠לַּפִּדִ֔ים הִ֕יא מִתְהַלֶּ֖כֶת בֵּ֣ין הַ⁠חַיּ֑וֹת וְ⁠נֹ֣גַהּ לָ⁠אֵ֔שׁ וּ⁠מִן־הָ⁠אֵ֖שׁ יוֹצֵ֥א בָרָֽק׃","ẇ⁠dĕm֨ẇţ ha⁠ẖaẏ֜wòţ marĕʼéy⁠he֣m kĕ̇⁠gaẖàléy-ʼé֗ş̌ bòֽ̇ʻàrwòţ֙ kĕ̇⁠marĕʼé֣h ha⁠lȧpi̇di֔ym hi֕yʼ miţĕhalė֖keţ bé֣̇yn ha⁠ẖaẏ֑wòţ wĕ⁠nò֣gaḣ lá⁠ʼé֔ş̌ ẇ⁠min-há⁠ʼé֖ş̌ ywòẕé֥ʼ báráֽq׃"],[1,14,"וְ⁠הַ⁠חַיּ֖וֹת רָצ֣וֹא וָ⁠שׁ֑וֹב כְּ⁠מַרְאֵ֖ה הַ⁠בָּזָֽק׃","wĕ⁠ha⁠ẖaẏ֖wòţ ráẕ֣wòʼ wá⁠ş֑̌wòb kĕ̇⁠marĕʼé֖h ha⁠bá̇záֽq׃"],[1,15,"וָ⁠אֵ֖רֶא הַ⁠חַיּ֑וֹת וְ⁠הִנֵּה֩ אוֹפַ֨ן אֶחָ֥ד בָּ⁠אָ֛רֶץ אֵ֥צֶל הַ⁠חַיּ֖וֹת לְ⁠אַרְבַּ֥עַת פָּנָֽי⁠ו׃","wá⁠ʼé֖reʼ ha⁠ẖaẏ֑wòţ wĕ⁠hiné̇h֩ ʼwòpa֨n ʼeẖá֥d bá̇⁠ʼá֛reẕ ʼé֥ẕel ha⁠ẖaẏ֖wòţ lĕ⁠ʼarĕbȧ֥ʻaţ pá̇náֽy⁠w׃"],[1,16,"מַרְאֵ֨ה הָ⁠אוֹפַנִּ֤ים וּ⁠מַעֲשֵׂי⁠הֶם֙ כְּ⁠עֵ֣ין תַּרְשִׁ֔ישׁ וּ⁠דְמ֥וּת אֶחָ֖ד לְ⁠אַרְבַּעְתָּ֑⁠ן וּ⁠מַרְאֵי⁠הֶם֙ וּ⁠מַ֣עֲשֵׂי⁠הֶ֔ם כַּ⁠אֲשֶׁ֛ר יִהְיֶ֥ה הָ⁠אוֹפַ֖ן בְּ⁠ת֥וֹךְ הָ⁠אוֹפָֽן׃","marĕʼé֨h há⁠ʼwòpani֤̇ym ẇ⁠maʻàşé̂y⁠hem֙ kĕ̇⁠ʻé֣yn ţȧrĕşǐ֔yş̌ ẇ⁠dĕm֥ẇţ ʼeẖá֖d lĕ⁠ʼarĕbȧʻĕţá֑̇⁠n ẇ⁠marĕʼéy⁠hem֙ ẇ⁠ma֣ʻàşé̂y⁠he֔m kȧ⁠ʼàşě֛r yihĕye֥h há⁠ʼwòpa֖n bĕ̇⁠ţ֥wòkĕ há⁠ʼwòpáֽn׃"],[1,17,"עַל־אַרְבַּ֥עַת רִבְעֵי⁠הֶ֖ן בְּ⁠לֶכְתָּ֣⁠ם יֵלֵ֑כוּ לֹ֥א יִסַּ֖בּוּ בְּ⁠לֶכְתָּֽ⁠ן׃","ʻal-ʼarĕbȧ֥ʻaţ ribĕʻéy⁠he֖n bĕ̇⁠lekĕţá֣̇⁠m yélé֑kẇ lò֥ʼ yisȧ֖ḃẇ bĕ̇⁠lekĕţáֽ̇⁠n׃"],[1,18,"וְ⁠גַ֨בֵּי⁠הֶ֔ן וְ⁠גֹ֥בַהּ לָ⁠הֶ֖ם וְ⁠יִרְאָ֣ה לָ⁠הֶ֑ם וְ⁠גַבֹּתָ֗⁠ם מְלֵאֹ֥ת עֵינַ֛יִם סָבִ֖יב לְ⁠אַרְבַּעְתָּֽ⁠ן׃","wĕ⁠ga֨bé̇y⁠he֔n wĕ⁠gò֥baḣ lá⁠he֖m wĕ⁠yirĕʼá֣h lá⁠he֑m wĕ⁠gabò̇ţá֗⁠m mĕléʼò֥ţ ʻéyna֛yim sábi֖yb lĕ⁠ʼarĕbȧʻĕţáֽ̇⁠n׃"],[1,19,"וּ⁠בְ⁠לֶ֨כֶת֙ הַֽ⁠חַיּ֔וֹת יֵלְכ֥וּ הָ⁠אוֹפַנִּ֖ים אֶצְלָ֑⁠ם וּ⁠בְ⁠הִנָּשֵׂ֤א הַֽ⁠חַיּוֹת֙ מֵ⁠עַ֣ל הָ⁠אָ֔רֶץ יִנָּשְׂא֖וּ הָ⁠אוֹפַנִּֽים׃","ẇ⁠bĕ⁠le֨keţ֙ haֽ⁠ẖaẏ֔wòţ yélĕk֥ẇ há⁠ʼwòpani֖̇ym ʼeẕĕlá֑⁠m ẇ⁠bĕ⁠hiná̇şé֤̂ʼ haֽ⁠ẖaẏwòţ֙ mé⁠ʻa֣l há⁠ʼá֔reẕ yiná̇şĕ̂ʼ֖ẇ há⁠ʼwòpaniֽ̇ym׃"],[1,20,"עַ֣ל אֲשֶׁר֩ יִֽהְיֶה־שָּׁ֨ם הָ⁠ר֤וּחַ לָ⁠לֶ֨כֶת֙ יֵלֵ֔כוּ שָׁ֥מָּ⁠ה הָ⁠ר֖וּחַ לָ⁠לֶ֑כֶת וְ⁠הָ⁠אוֹפַנִּ֗ים יִנָּשְׂאוּ֙ לְ⁠עֻמָּתָ֔⁠ם כִּ֛י ר֥וּחַ הַ⁠חַיָּ֖ה בָּ⁠אוֹפַנִּֽים׃","ʻa֣l ʼàşěr֩ yiֽhĕyeh-şá̇̌֨m há⁠r֤ẇẖa lá⁠le֨keţ֙ yélé֔kẇ şá֥̌má̇⁠h há⁠r֖ẇẖa lá⁠le֑keţ wĕ⁠há⁠ʼwòpani̇֗ym yiná̇şĕ̂ʼẇ֙ lĕ⁠ʻumá̇ţá֔⁠m ki֛̇y r֥ẇẖa ha⁠ẖayá֖̇h bá̇⁠ʼwòpaniֽ̇ym׃"],[1,21,"בְּ⁠לֶכְתָּ֣⁠ם יֵלֵ֔כוּ וּ⁠בְ⁠עָמְדָ֖⁠ם יַֽעֲמֹ֑דוּ וּֽ⁠בְ⁠הִנָּשְׂאָ֞⁠ם מֵ⁠עַ֣ל הָ⁠אָ֗רֶץ יִנָּשְׂא֤וּ הָ⁠אֽוֹפַנִּים֙ לְ⁠עֻמָּתָ֔⁠ם כִּ֛י ר֥וּחַ הַ⁠חַיָּ֖ה בָּ⁠אוֹפַנִּֽים׃","bĕ̇⁠lekĕţá֣̇⁠m yélé֔kẇ ẇ⁠bĕ⁠ʻámĕdá֖⁠m yֽaʻàmò֑dẇ ẇֽ⁠bĕ⁠hiná̇şĕ̂ʼá֞⁠m mé⁠ʻa֣l há⁠ʼá֗reẕ yiná̇şĕ̂ʼ֤ẇ há⁠ʼֽwòpani̇ym֙ lĕ⁠ʻumá̇ţá֔⁠m ki֛̇y r֥ẇẖa ha⁠ẖayá֖̇h bá̇⁠ʼwòpaniֽ̇ym׃"],[1,22,"וּ⁠דְמ֞וּת עַל־רָאשֵׁ֤י הַ⁠חַיָּה֙ רָקִ֔יעַ כְּ⁠עֵ֖ין הַ⁠קֶּ֣רַח הַ⁠נּוֹרָ֑א נָט֥וּי עַל־רָאשֵׁי⁠הֶ֖ם מִ⁠לְ⁠מָֽעְלָ⁠ה׃","ẇ⁠dĕm֞ẇţ ʻal-ráʼşé֤̌y ha⁠ẖayá̇h֙ ráqi֔yʻa kĕ̇⁠ʻé֖yn ha⁠qė֣raẖ ha⁠ṅwòrá֑ʼ nát֥ẇy ʻal-ráʼşé̌y⁠he֖m mi⁠lĕ⁠máֽʻĕlá⁠h׃"],[1,23,"וְ⁠תַ֨חַת֙ הָ⁠רָקִ֔יעַ כַּנְפֵי⁠הֶ֣ם יְשָׁר֔וֹת אִשָּׁ֖ה אֶל־אֲחוֹתָ֑⁠הּ לְ⁠אִ֗ישׁ שְׁתַּ֤יִם מְכַסּוֹת֙ לָ⁠הֵ֔נָּה וּ⁠לְ⁠אִ֗ישׁ שְׁתַּ֤יִם מְכַסּוֹת֙ לָ⁠הֵ֔נָּה אֵ֖ת גְּוִיֹּתֵי⁠הֶֽם׃","wĕ⁠ţa֨ẖaţ֙ há⁠ráqi֔yʻa kȧnĕpéy⁠he֣m yĕşá̌r֔wòţ ʼişá֖̇̌h ʼel-ʼàẖwòţá֑⁠ḣ lĕ⁠ʼi֗yş̌ şĕ̌ţȧ֤yim mĕkaṡwòţ֙ lá⁠hé֔ná̇h ẇ⁠lĕ⁠ʼi֗yş̌ şĕ̌ţȧ֤yim mĕkaṡwòţ֙ lá⁠hé֔ná̇h ʼé֖ţ gĕ̇wiyò̇ţéy⁠heֽm׃"],[1,24,"וָ⁠אֶשְׁמַ֣ע אֶת־ק֣וֹל כַּנְפֵי⁠הֶ֡ם כְּ⁠קוֹל֩ מַ֨יִם רַבִּ֤ים כְּ⁠קוֹל־שַׁדַּי֙ בְּ⁠לֶכְתָּ֔⁠ם ק֥וֹל הֲמֻלָּ֖ה כְּ⁠ק֣וֹל מַחֲנֶ֑ה בְּ⁠עָמְדָ֖⁠ם תְּרַפֶּ֥ינָה כַנְפֵי⁠הֶֽן׃","wá⁠ʼeşĕ̌ma֣ʻ ʼeţ-q֣wòl kȧnĕpéy⁠he֡m kĕ̇⁠qwòl֩ ma֨yim rabi֤̇ym kĕ̇⁠qwòl-şǎdȧy֙ bĕ̇⁠lekĕţá̇֔⁠m q֥wòl hàmulá֖̇h kĕ̇⁠q֣wòl maẖàne֑h bĕ̇⁠ʻámĕdá֖⁠m ţĕ̇rapė֥ynáh kanĕpéy⁠heֽn׃"],[1,25,"וַ⁠יְהִי־ק֕וֹל מֵ⁠עַ֕ל לָ⁠רָקִ֖יעַ אֲשֶׁ֣ר עַל־רֹאשָׁ֑⁠ם בְּ⁠עָמְדָ֖⁠ם תְּרַפֶּ֥ינָה כַנְפֵי⁠הֶֽן׃","wa⁠yĕhiy-q֕wòl mé⁠ʻa֕l lá⁠ráqi֖yʻa ʼàşě֣r ʻal-ròʼşá֑̌⁠m bĕ̇⁠ʻámĕdá֖⁠m ţĕ̇rapė֥ynáh kanĕpéy⁠heֽn׃"],[1,26,"וּ⁠מִ⁠מַּ֗עַל לָ⁠רָקִ֨יעַ֙ אֲשֶׁ֣ר עַל־רֹאשָׁ֔⁠ם כְּ⁠מַרְאֵ֥ה אֶֽבֶן־סַפִּ֖יר דְּמ֣וּת כִּסֵּ֑א וְ⁠עַל֙ דְּמ֣וּת הַ⁠כִּסֵּ֔א דְּמ֞וּת כְּ⁠מַרְאֵ֥ה אָדָ֛ם עָלָ֖י⁠ו מִ⁠לְ⁠מָֽעְלָ⁠ה׃","ẇ⁠mi⁠mȧ֗ʻal lá⁠ráqi֨yʻa֙ ʼàşě֣r ʻal-ròʼşá̌֔⁠m kĕ̇⁠marĕʼé֥h ʼeֽben-sapi֖̇yr dĕ̇m֣ẇţ ki̇sé֑̇ʼ wĕ⁠ʻal֙ dĕ̇m֣ẇţ ha⁠ki̇sé̇֔ʼ dĕ̇m֞ẇţ kĕ̇⁠marĕʼé֥h ʼádá֛m ʻálá֖y⁠w mi⁠lĕ⁠máֽʻĕlá⁠h׃"],[1,27,"וָ⁠אֵ֣רֶא ׀ כְּ⁠עֵ֣ין חַשְׁמַ֗ל כְּ⁠מַרְאֵה־אֵ֤שׁ בֵּֽית־לָ⁠הּ֙ סָבִ֔יב מִ⁠מַּרְאֵ֥ה מָתְנָ֖י⁠ו וּ⁠לְ⁠מָ֑עְלָ⁠ה וּ⁠מִ⁠מַּרְאֵ֤ה מָתְנָי⁠ו֙ וּ⁠לְ⁠מַ֔טָּה רָאִ֨יתִי֙ כְּ⁠מַרְאֵה־אֵ֔שׁ וְ⁠נֹ֥גַֽהּ ל֖⁠וֹ סָבִֽיב׃","wá⁠ʼé֣reʼ ׀ kĕ̇⁠ʻé֣yn ẖaşĕ̌ma֗l kĕ̇⁠marĕʼéh-ʼé֤ş̌ béֽ̇yţ-lá⁠ḣ֙ sábi֔yb mi⁠mȧrĕʼé֥h máţĕná֖y⁠w ẇ⁠lĕ⁠má֑ʻĕlá⁠h ẇ⁠mi⁠mȧrĕʼé֤h máţĕnáy⁠w֙ ẇ⁠lĕ⁠ma֔tá̇h ráʼi֨yţiy֙ kĕ̇⁠marĕʼéh-ʼé֔ş̌ wĕ⁠nò֥gaֽḣ l֖⁠wò sábiֽyb׃"],[1,28,"כְּ⁠מַרְאֵ֣ה הַ⁠קֶּ֡שֶׁת אֲשֶׁר֩ יִֽהְיֶ֨ה בֶ⁠עָנָ֜ן בְּ⁠י֣וֹם הַ⁠גֶּ֗שֶׁם כֵּ֣ן מַרְאֵ֤ה הַ⁠נֹּ֨גַהּ֙ סָבִ֔יב ה֕וּא מַרְאֵ֖ה דְּמ֣וּת כְּבוֹד־יְהוָ֑ה וָֽ⁠אֶרְאֶה֙ וָ⁠אֶפֹּ֣ל עַל־פָּנַ֔⁠י וָ⁠אֶשְׁמַ֖ע ק֥וֹל מְדַבֵּֽר׃ס","kĕ̇⁠marĕʼé֣h ha⁠qė֡şěţ ʼàşěr֩ yiֽhĕye֨h be⁠ʻáná֜n bĕ̇⁠y֣wòm ha⁠gė֗şěm ké֣̇n marĕʼé֤h ha⁠nò̇֨gaḣ֙ sábi֔yb h֕ẇʼ marĕʼé֖h dĕ̇m֣ẇţ kĕ̇bwòd-yĕhwá֑h wáֽ⁠ʼerĕʼeh֙ wá⁠ʼepò֣̇l ʻal-pá̇na֔⁠y wá⁠ʼeşĕ̌ma֖ʻ q֥wòl mĕdabéֽ̇r׃s"],[2,1,"וַ⁠יֹּ֖אמֶר אֵלָ֑⁠י בֶּן־אָדָם֙ עֲמֹ֣ד עַל־רַגְלֶ֔י⁠ךָ וַ⁠אֲדַבֵּ֖ר אֹתָֽ⁠ךְ׃","wa⁠yò֖̇ʼmer ʼélá֑⁠y bėn-ʼádám֙ ʻàmò֣d ʻal-ragĕle֔y⁠ká wa⁠ʼàdabé֖̇r ʼòţáֽ⁠kĕ׃"],[2,2,"וַ⁠תָּ֧בֹא בִ֣⁠י ר֗וּחַ כַּֽ⁠אֲשֶׁר֙ דִּבֶּ֣ר אֵלַ֔⁠י וַ⁠תַּעֲמִדֵ֖⁠נִי עַל־רַגְלָ֑⁠י וָ⁠אֶשְׁמַ֕ע אֵ֖ת מִדַּבֵּ֥ר אֵלָֽ⁠י׃פ","wa⁠ţá֧̇bòʼ bi֣⁠y r֗ẇẖa kȧֽ⁠ʼàşěr֙ di̇bė֣r ʼéla֔⁠y wa⁠ţȧʻàmidé֖⁠niy ʻal-ragĕlá֑⁠y wá⁠ʼeşĕ̌ma֕ʻ ʼé֖ţ midȧbé֥̇r ʼéláֽ⁠y׃p"],[2,3,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י בֶּן־אָדָם֙ שׁוֹלֵ֨חַ אֲנִ֤י אֽוֹתְ⁠ךָ֙ אֶל־בְּנֵ֣י יִשְׂרָאֵ֔ל אֶל־גּוֹיִ֥ם הַ⁠מּוֹרְדִ֖ים אֲשֶׁ֣ר מָרְדוּ־בִ֑⁠י הֵ֤מָּה וַ⁠אֲבוֹתָ⁠ם֙ פָּ֣שְׁעוּ בִ֔⁠י עַד־עֶ֖צֶם הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y bėn-ʼádám֙ ş̌wòlé֨ẖa ʼàni֤y ʼֽwòţĕ⁠ká֙ ʼel-bĕ̇né֣y yişĕ̂ráʼé֔l ʼel-ġwòyi֥m ha⁠ṁwòrĕdi֖ym ʼàşě֣r márĕdẇ-bi֑⁠y hé֤má̇h wa⁠ʼàbwòţá⁠m֙ pá֣̇şĕ̌ʻẇ bi֔⁠y ʻad-ʻe֖ẕem ha⁠ẏ֥wòm ha⁠zėֽh׃"],[2,4,"וְ⁠הַ⁠בָּנִ֗ים קְשֵׁ֤י פָנִים֙ וְ⁠חִזְקֵי־לֵ֔ב אֲנִ֛י שׁוֹלֵ֥חַ אוֹתְ⁠ךָ֖ אֲלֵי⁠הֶ֑ם וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם כֹּ֥ה אָמַ֖ר אֲדֹנָ֥⁠י יְהֹוִֽה׃","wĕ⁠ha⁠bá̇ni֗ym qĕşé֤̌y pániym֙ wĕ⁠ẖizĕqéy-lé֔b ʼàni֛y ş̌wòlé֥ẖa ʼwòţĕ⁠ká֖ ʼàléy⁠he֑m wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m kò֥̇h ʼáma֖r ʼàdòná֥⁠y yĕhòwiֽh׃"],[2,5,"וְ⁠הֵ֨מָּה֙ אִם־יִשְׁמְע֣וּ וְ⁠אִם־יֶחְדָּ֔לוּ כִּ֛י בֵּ֥ית מְרִ֖י הֵ֑מָּה וְ⁠יָ֣דְע֔וּ כִּ֥י נָבִ֖יא הָיָ֥ה בְ⁠תוֹכָֽ⁠ם׃פ","wĕ⁠hé֨má̇h֙ ʼim-yişĕ̌mĕʻ֣ẇ wĕ⁠ʼim-yeẖĕdá̇֔lẇ ki֛̇y bé֥̇yţ mĕri֖y hé֑má̇h wĕ⁠yá֣dĕʻ֔ẇ ki֥̇y nábi֖yʼ háyá֥h bĕ⁠ţwòkáֽ⁠m׃p"],[2,6,"וְ⁠אַתָּ֣ה בֶן־אָ֠דָם אַל־תִּירָ֨א מֵ⁠הֶ֜ם וּ⁠מִ⁠דִּבְרֵי⁠הֶ֣ם אַל־תִּירָ֗א כִּ֣י סָרָבִ֤ים וְ⁠סַלּוֹנִים֙ אוֹתָ֔⁠ךְ וְ⁠אֶל־עַקְרַבִּ֖ים אַתָּ֣ה יוֹשֵׁ֑ב מִ⁠דִּבְרֵי⁠הֶ֤ם אַל־תִּירָא֙ וּ⁠מִ⁠פְּנֵי⁠הֶ֣ם אַל־תֵּחָ֔ת כִּ֛י בֵּ֥ית מְרִ֖י הֵֽמָּה׃","wĕ⁠ʼaţá֣̇h ben-ʼá֠dám ʼal-ţi̇yrá֨ʼ mé⁠he֜m ẇ⁠mi⁠di̇bĕréy⁠he֣m ʼal-ţi̇yrá֗ʼ ki֣̇y sárábi֤ym wĕ⁠sal̇wòniym֙ ʼwòţá֔⁠kĕ wĕ⁠ʼel-ʻaqĕrabi֖̇ym ʼaţá֣̇h ywòşé֑̌b mi⁠di̇bĕréy⁠he֤m ʼal-ţi̇yráʼ֙ ẇ⁠mi⁠pĕ̇néy⁠he֣m ʼal-ţé̇ẖá֔ţ ki֛̇y bé֥̇yţ mĕri֖y héֽmá̇h׃"],[2,7,"וְ⁠דִבַּרְתָּ֤ אֶת־דְּבָרַ⁠י֙ אֲלֵי⁠הֶ֔ם אִֽם־יִשְׁמְע֖וּ וְ⁠אִם־יֶחְדָּ֑לוּ כִּ֥י מְרִ֖י הֵֽמָּה׃פ","wĕ⁠dibȧrĕţá֤̇ ʼeţ-dĕ̇bára⁠y֙ ʼàléy⁠he֔m ʼiֽm-yişĕ̌mĕʻ֖ẇ wĕ⁠ʼim-yeẖĕdá֑̇lẇ ki֥̇y mĕri֖y héֽmá̇h׃p"],[2,8,"וְ⁠אַתָּ֣ה בֶן־אָדָ֗ם שְׁמַע֙ אֵ֤ת אֲשֶׁר־אֲנִי֙ מְדַבֵּ֣ר אֵלֶ֔י⁠ךָ אַל־תְּהִי־מֶ֖רִי כְּ⁠בֵ֣ית הַ⁠מֶּ֑רִי פְּצֵ֣ה פִ֔י⁠ךָ וֶ⁠אֱכֹ֕ל אֵ֥ת אֲשֶׁר־אֲנִ֖י נֹתֵ֥ן אֵלֶֽי⁠ךָ׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֗m şĕ̌maʻ֙ ʼé֤ţ ʼàşěr-ʼàniy֙ mĕdabé֣̇r ʼéle֔y⁠ká ʼal-ţĕ̇hiy-me֖riy kĕ̇⁠bé֣yţ ha⁠mė֑riy pĕ̇ẕé֣h pi֔y⁠ká we⁠ʼèkò֕l ʼé֥ţ ʼàşěr-ʼàni֖y nòţé֥n ʼéleֽy⁠ká׃"],[2,9,"וָ⁠אֶרְאֶ֕ה וְ⁠הִנֵּה־יָ֖ד שְׁלוּחָ֣ה אֵלָ֑⁠י וְ⁠הִנֵּה־ב֖⁠וֹ מְגִלַּת־סֵֽפֶר׃","wá⁠ʼerĕʼe֕h wĕ⁠hiné̇h-yá֖d şĕ̌lẇẖá֣h ʼélá֑⁠y wĕ⁠hiné̇h-b֖⁠wò mĕgilȧţ-séֽper׃"],[2,10,"וַ⁠יִּפְרֹ֤שׂ אוֹתָ⁠הּ֙ לְ⁠פָנַ֔⁠י וְ⁠הִ֥יא כְתוּבָ֖ה פָּנִ֣ים וְ⁠אָח֑וֹר וְ⁠כָת֣וּב אֵלֶ֔י⁠הָ קִנִ֥ים וָ⁠הֶ֖גֶה וָ⁠הִֽי׃ס","wa⁠yi̇pĕrò֤ş̂ ʼwòţá⁠ḣ֙ lĕ⁠pána֔⁠y wĕ⁠hi֥yʼ kĕţẇbá֖h pá̇ni֣ym wĕ⁠ʼáẖ֑wòr wĕ⁠káţ֣ẇb ʼéle֔y⁠há qini֥ym wá⁠he֖geh wá⁠hiֽy׃s"],[3,1,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י בֶּן־אָדָ֕ם אֵ֥ת אֲשֶׁר־תִּמְצָ֖א אֱכ֑וֹל אֱכוֹל֙ אֶת־הַ⁠מְּגִלָּ֣ה הַ⁠זֹּ֔את וְ⁠לֵ֥ךְ דַּבֵּ֖ר אֶל־בֵּ֥ית יִשְׂרָאֵֽל׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y bėn-ʼádá֕m ʼé֥ţ ʼàşěr-ţi̇mĕẕá֖ʼ ʼèk֑wòl ʼèkwòl֙ ʼeţ-ha⁠mĕ̇gilá֣̇h ha⁠zò̇֔ʼţ wĕ⁠lé֥kĕ dȧbé֖̇r ʼel-bé֥̇yţ yişĕ̂ráʼéֽl׃"],[3,2,"וָ⁠אֶפְתַּ֖ח אֶת־פִּ֑⁠י וַ⁠יַּ֣אֲכִלֵ֔⁠נִי אֵ֖ת הַ⁠מְּגִלָּ֥ה הַ⁠זֹּֽאת׃","wá⁠ʼepĕţȧ֖ẖ ʼeţ-pi֑̇⁠y wa⁠yȧ֣ʼàkilé֔⁠niy ʼé֖ţ ha⁠mĕ̇gilá֥̇h ha⁠zòֽ̇ʼţ׃"],[3,3,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י בֶּן־אָדָם֙ בִּטְנְ⁠ךָ֤ תַֽאֲכֵל֙ וּ⁠מֵעֶ֣י⁠ךָ תְמַלֵּ֔א אֵ֚ת הַ⁠מְּגִלָּ֣ה הַ⁠זֹּ֔את אֲשֶׁ֥ר אֲנִ֖י נֹתֵ֣ן אֵלֶ֑י⁠ךָ וָ⁠אֹ֣כְלָ֔⁠ה וַ⁠תְּהִ֥י בְּ⁠פִ֖⁠י כִּ⁠דְבַ֥שׁ לְ⁠מָתֽוֹק׃פ","wa⁠yò֣̇ʼmer ʼéla֗⁠y bėn-ʼádám֙ bi̇tĕnĕ⁠ká֤ ţaֽʼàkél֙ ẇ⁠méʻe֣y⁠ká ţĕmalé̇֔ʼ ʼé֚ţ ha⁠mĕ̇gilá֣̇h ha⁠zò̇֔ʼţ ʼàşě֥r ʼàni֖y nòţé֣n ʼéle֑y⁠ká wá⁠ʼò֣kĕlá֔⁠h wa⁠ţĕ̇hi֥y bĕ̇⁠pi֖⁠y ki̇⁠dĕba֥ş̌ lĕ⁠máţֽwòq׃p"],[3,4,"וַ⁠יֹּ֖אמֶר אֵלָ֑⁠י בֶּן־אָדָ֗ם לֶךְ־בֹּא֙ אֶל־בֵּ֣ית יִשְׂרָאֵ֔ל וְ⁠דִבַּרְתָּ֥ בִ⁠דְבָרַ֖⁠י אֲלֵי⁠הֶֽם׃","wa⁠yò֖̇ʼmer ʼélá֑⁠y bėn-ʼádá֗m lekĕ-bò̇ʼ֙ ʼel-bé֣̇yţ yişĕ̂ráʼé֔l wĕ⁠dibȧrĕţá֥̇ bi⁠dĕbára֖⁠y ʼàléy⁠heֽm׃"],[3,5,"כִּ֡י לֹא֩ אֶל־עַ֨ם עִמְקֵ֥י שָׂפָ֛ה וְ⁠כִבְדֵ֥י לָשׁ֖וֹן אַתָּ֣ה שָׁל֑וּחַ אֶל־בֵּ֖ית יִשְׂרָאֵֽל׃","ki̇֡y lòʼ֩ ʼel-ʻa֨m ʻimĕqé֥y şá̂pá֛h wĕ⁠kibĕdé֥y láş֖̌wòn ʼaţá֣̇h şá̌l֑ẇẖa ʼel-bé֖̇yţ yişĕ̂ráʼéֽl׃"],[3,6,"לֹ֣א ׀ אֶל־עַמִּ֣ים רַבִּ֗ים עִמְקֵ֤י שָׂפָה֙ וְ⁠כִבְדֵ֣י לָשׁ֔וֹן אֲשֶׁ֥ר לֹֽא־תִשְׁמַ֖ע דִּבְרֵי⁠הֶ֑ם אִם־לֹ֤א אֲלֵי⁠הֶם֙ שְׁלַחְתִּ֔י⁠ךָ הֵ֖מָּה יִשְׁמְע֥וּ אֵלֶֽי⁠ךָ׃","lò֣ʼ ׀ ʼel-ʻami֣̇ym rabi̇֗ym ʻimĕqé֤y şá̂páh֙ wĕ⁠kibĕdé֣y láş̌֔wòn ʼàşě֥r lòֽʼ-ţişĕ̌ma֖ʻ di̇bĕréy⁠he֑m ʼim-lò֤ʼ ʼàléy⁠hem֙ şĕ̌laẖĕţi̇֔y⁠ká hé֖má̇h yişĕ̌mĕʻ֥ẇ ʼéleֽy⁠ká׃"],[3,7,"וּ⁠בֵ֣ית יִשְׂרָאֵ֗ל לֹ֤א יֹאבוּ֙ לִ⁠שְׁמֹ֣עַ אֵלֶ֔י⁠ךָ כִּֽי־אֵינָ֥⁠ם אֹבִ֖ים לִ⁠שְׁמֹ֣עַ אֵלָ֑⁠י כִּ֚י כָּל־בֵּ֣ית יִשְׂרָאֵ֔ל חִזְקֵי־מֵ֥צַח וּ⁠קְשֵׁי־לֵ֖ב הֵֽמָּה׃","ẇ⁠bé֣yţ yişĕ̂ráʼé֗l lò֤ʼ yòʼbẇ֙ li⁠şĕ̌mò֣ʻa ʼéle֔y⁠ká kiֽ̇y-ʼéyná֥⁠m ʼòbi֖ym li⁠şĕ̌mò֣ʻa ʼélá֑⁠y ki֚̇y ká̇l-bé֣̇yţ yişĕ̂ráʼé֔l ẖizĕqéy-mé֥ẕaẖ ẇ⁠qĕşé̌y-lé֖b héֽmá̇h׃"],[3,8,"הִנֵּ֨ה נָתַ֧תִּי אֶת־פָּנֶ֛י⁠ךָ חֲזָקִ֖ים לְ⁠עֻמַּ֣ת פְּנֵי⁠הֶ֑ם וְ⁠אֶֽת־מִצְחֲ⁠ךָ֥ חָזָ֖ק לְ⁠עֻמַּ֥ת מִצְחָֽ⁠ם׃","hiné̇֨h náţa֧ţi̇y ʼeţ-pá̇ne֛y⁠ká ẖàzáqi֖ym lĕ⁠ʻumȧ֣ţ pĕ̇néy⁠he֑m wĕ⁠ʼeֽţ-miẕĕẖà⁠ká֥ ẖázá֖q lĕ⁠ʻumȧ֥ţ miẕĕẖáֽ⁠m׃"],[3,9,"כְּ⁠שָׁמִ֛יר חָזָ֥ק מִ⁠צֹּ֖ר נָתַ֣תִּי מִצְחֶ֑⁠ךָ לֹֽא־תִירָ֤א אוֹתָ⁠ם֙ וְ⁠לֹא־תֵחַ֣ת מִ⁠פְּנֵי⁠הֶ֔ם כִּ֛י בֵּֽית־מְרִ֖י הֵֽמָּה׃פ","kĕ̇⁠şá̌mi֛yr ẖázá֥q mi⁠ẕò֖̇r náţa֣ţi̇y miẕĕẖe֑⁠ká lòֽʼ-ţiyrá֤ʼ ʼwòţá⁠m֙ wĕ⁠lòʼ-ţéẖa֣ţ mi⁠pĕ̇néy⁠he֔m ki֛̇y béֽ̇yţ-mĕri֖y héֽmá̇h׃p"],[3,10,"וַ⁠יֹּ֖אמֶר אֵלָ֑⁠י בֶּן־אָדָ֕ם אֶת־כָּל־דְּבָרַ⁠י֙ אֲשֶׁ֣ר אֲדַבֵּ֣ר אֵלֶ֔י⁠ךָ קַ֥ח בִּֽ⁠לְבָבְ⁠ךָ֖ וּ⁠בְ⁠אָזְנֶ֥י⁠ךָ שְׁמָֽע׃","wa⁠yò֖̇ʼmer ʼélá֑⁠y bėn-ʼádá֕m ʼeţ-ká̇l-dĕ̇bára⁠y֙ ʼàşě֣r ʼàdabé֣̇r ʼéle֔y⁠ká qa֥ẖ biֽ̇⁠lĕbábĕ⁠ká֖ ẇ⁠bĕ⁠ʼázĕne֥y⁠ká şĕ̌máֽʻ׃"],[3,11,"וְ⁠לֵ֨ךְ בֹּ֤א אֶל־הַ⁠גּוֹלָה֙ אֶל־בְּנֵ֣י עַמֶּ֔⁠ךָ וְ⁠דִבַּרְתָּ֤ אֲלֵי⁠הֶם֙ וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהֹוִ֑ה אִֽם־יִשְׁמְע֖וּ וְ⁠אִם־יֶחְדָּֽלוּ׃","wĕ⁠lé֨kĕ bò֤̇ʼ ʼel-ha⁠ġwòláh֙ ʼel-bĕ̇né֣y ʻamė֔⁠ká wĕ⁠dibȧrĕţá֤̇ ʼàléy⁠hem֙ wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhòwi֑h ʼiֽm-yişĕ̌mĕʻ֖ẇ wĕ⁠ʼim-yeẖĕdáֽ̇lẇ׃"],[3,12,"וַ⁠תִּשָּׂאֵ֣⁠נִי ר֔וּחַ וָ⁠אֶשְׁמַ֣ע אַחֲרַ֔⁠י ק֖וֹל רַ֣עַשׁ גָּד֑וֹל בָּר֥וּךְ כְּבוֹד־יְהוָ֖ה מִ⁠מְּקוֹמֽ⁠וֹ׃","wa⁠ţi̇şá̇̂ʼé֣⁠niy r֔ẇẖa wá⁠ʼeşĕ̌ma֣ʻ ʼaẖàra֔⁠y q֖wòl ra֣ʻaş̌ gá̇d֑wòl bá̇r֥ẇkĕ kĕ̇bwòd-yĕhwá֖h mi⁠mĕ̇qwòmֽ⁠wò׃"],[3,13,"וְ⁠ק֣וֹל ׀ כַּנְפֵ֣י הַ⁠חַיּ֗וֹת מַשִּׁיקוֹת֙ אִשָּׁ֣ה אֶל־אֲחוֹתָ֔⁠הּ וְ⁠ק֥וֹל הָ⁠אוֹפַנִּ֖ים לְ⁠עֻמָּתָ֑⁠ם וְ⁠ק֖וֹל רַ֥עַשׁ גָּדֽוֹל׃","wĕ⁠q֣wòl ׀ kȧnĕpé֣y ha⁠ẖaẏ֗wòţ maşi̇̌yqwòţ֙ ʼişá֣̇̌h ʼel-ʼàẖwòţá֔⁠ḣ wĕ⁠q֥wòl há⁠ʼwòpani֖̇ym lĕ⁠ʻumá̇ţá֑⁠m wĕ⁠q֖wòl ra֥ʻaş̌ gá̇dֽwòl׃"],[3,14,"וְ⁠ר֥וּחַ נְשָׂאַ֖תְ⁠נִי וַ⁠תִּקָּחֵ֑⁠נִי וָ⁠אֵלֵ֥ךְ מַר֙ בַּ⁠חֲמַ֣ת רוּחִ֔⁠י וְ⁠יַד־יְהוָ֥ה עָלַ֖⁠י חָזָֽקָה׃","wĕ⁠r֥ẇẖa nĕşá̂ʼa֖ţĕ⁠niy wa⁠ţi̇qá̇ẖé֑⁠niy wá⁠ʼélé֥kĕ mar֙ bȧ⁠ẖàma֣ţ rẇẖi֔⁠y wĕ⁠yad-yĕhwá֥h ʻála֖⁠y ẖázáֽqáh׃"],[3,15,"וָ⁠אָב֨וֹא אֶל־הַ⁠גּוֹלָ֜ה תֵּ֣ל אָ֠בִיב הַ⁠יֹּשְׁבִ֤ים אֶֽל־נְהַר־כְּבָר֙ ו⁠אשר הֵ֖מָּה יוֹשְׁבִ֣ים שָׁ֑ם וָ⁠אֵשֵׁ֥ב שָׁ֛ם שִׁבְעַ֥ת יָמִ֖ים מַשְׁמִ֥ים בְּ⁠תוֹכָֽ⁠ם׃","wá⁠ʼáb֨wòʼ ʼel-ha⁠ġwòlá֜h ţé֣̇l ʼá֠biyb ha⁠yò̇şĕ̌bi֤ym ʼeֽl-nĕhar-kĕ̇bár֙ w⁠ʼşr hé֖má̇h ywòşĕ̌bi֣ym şá֑̌m wá⁠ʼéşé֥̌b şá֛̌m şǐbĕʻa֥ţ yámi֖ym maşĕ̌mi֥ym bĕ̇⁠ţwòkáֽ⁠m׃"],[3,16,"וַ⁠יְהִ֕י מִ⁠קְצֵ֖ה שִׁבְעַ֣ת יָמִ֑ים פ וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֕y mi⁠qĕẕé֖h şǐbĕʻa֣ţ yámi֑ym p wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[3,17,"בֶּן־אָדָ֕ם צֹפֶ֥ה נְתַתִּ֖י⁠ךָ לְ⁠בֵ֣ית יִשְׂרָאֵ֑ל וְ⁠שָׁמַעְתָּ֤ מִ⁠פִּ⁠י֙ דָּבָ֔ר וְ⁠הִזְהַרְתָּ֥ אוֹתָ֖⁠ם מִמֶּֽ⁠נִּי׃","bėn-ʼádá֕m ẕòpe֥h nĕţaţi֖̇y⁠ká lĕ⁠bé֣yţ yişĕ̂ráʼé֑l wĕ⁠şá̌maʻĕţá֤̇ mi⁠pi̇⁠y֙ dá̇bá֔r wĕ⁠hizĕharĕţá֥̇ ʼwòţá֖⁠m mimėֽ⁠ni̇y׃"],[3,18,"בְּ⁠אָמְרִ֤⁠י לָֽ⁠רָשָׁע֙ מ֣וֹת תָּמ֔וּת וְ⁠לֹ֣א הִזְהַרְתּ֗⁠וֹ וְ⁠לֹ֥א דִבַּ֛רְתָּ לְ⁠הַזְהִ֥יר רָשָׁ֛ע מִ⁠דַּרְכּ֥⁠וֹ הָ⁠רְשָׁעָ֖ה לְ⁠חַיֹּת֑⁠וֹ ה֤וּא רָשָׁע֙ בַּ⁠עֲוֺנ֣⁠וֹ יָמ֔וּת וְ⁠דָמ֖⁠וֹ מִ⁠יָּדְ⁠ךָ֥ אֲבַקֵּֽשׁ׃","bĕ̇⁠ʼámĕri֤⁠y láֽ⁠ráşá̌ʻ֙ m֣wòţ ţá̇m֔ẇţ wĕ⁠lò֣ʼ hizĕharĕţ̇֗⁠wò wĕ⁠lò֥ʼ dibȧ֛rĕţá̇ lĕ⁠hazĕhi֥yr ráşá֛̌ʻ mi⁠dȧrĕk֥̇⁠wò há⁠rĕşá̌ʻá֖h lĕ⁠ẖayò̇ţ֑⁠wò h֤ẇʼ ráşá̌ʻ֙ bȧ⁠ʻàwֺn֣⁠wò yám֔ẇţ wĕ⁠dám֖⁠wò mi⁠yá̇dĕ⁠ká֥ ʼàbaqéֽ̇ş̌׃"],[3,19,"וְ⁠אַתָּה֙ כִּֽי־הִזְהַ֣רְתָּ רָשָׁ֔ע וְ⁠לֹא־שָׁב֙ מֵֽ⁠רִשְׁע֔⁠וֹ וּ⁠מִ⁠דַּרְכּ֖⁠וֹ הָ⁠רְשָׁעָ֑ה ה֚וּא בַּ⁠עֲוֺנ֣⁠וֹ יָמ֔וּת וְ⁠אַתָּ֖ה אֶֽת־נַפְשְׁ⁠ךָ֥ הִצַּֽלְתָּ׃ס","wĕ⁠ʼaţá̇h֙ kiֽ̇y-hizĕha֣rĕţá̇ ráşá̌֔ʻ wĕ⁠lòʼ-şá̌b֙ méֽ⁠rişĕ̌ʻ֔⁠wò ẇ⁠mi⁠dȧrĕk֖̇⁠wò há⁠rĕşá̌ʻá֑h h֚ẇʼ bȧ⁠ʻàwֺn֣⁠wò yám֔ẇţ wĕ⁠ʼaţá֖̇h ʼeֽţ-napĕşĕ̌⁠ká֥ hiẕȧֽlĕţá̇׃s"],[3,20,"וּ⁠בְ⁠שׁ֨וּב צַדִּ֤יק מִ⁠צִּדְק⁠וֹ֙ וְ⁠עָ֣שָׂה עָ֔וֶל וְ⁠נָתַתִּ֥י מִכְשׁ֛וֹל לְ⁠פָנָ֖י⁠ו ה֣וּא יָמ֑וּת כִּ֣י לֹ֤א הִזְהַרְתּ⁠וֹ֙ בְּ⁠חַטָּאת֣⁠וֹ יָמ֔וּת וְ⁠לֹ֣א תִזָּכַ֗רְןָ צִדְקֹתָ⁠ו֙ אֲשֶׁ֣ר עָשָׂ֔ה וְ⁠דָמ֖⁠וֹ מִ⁠יָּדְ⁠ךָ֥ אֲבַקֵּֽשׁ׃","ẇ⁠bĕ⁠ş̌֨ẇb ẕadi֤̇yq mi⁠ẕi̇dĕq⁠wò֙ wĕ⁠ʻá֣şá̂h ʻá֔wel wĕ⁠náţaţi֥̇y mikĕş֛̌wòl lĕ⁠páná֖y⁠w h֣ẇʼ yám֑ẇţ ki֣̇y lò֤ʼ hizĕharĕţ̇⁠wò֙ bĕ̇⁠ẖatá̇ʼţ֣⁠wò yám֔ẇţ wĕ⁠lò֣ʼ ţizá̇ka֗rĕná ẕidĕqòţá⁠w֙ ʼàşě֣r ʻáşá̂֔h wĕ⁠dám֖⁠wò mi⁠yá̇dĕ⁠ká֥ ʼàbaqéֽ̇ş̌׃"],[3,21,"וְ⁠אַתָּ֞ה כִּ֧י הִזְהַרְתּ֣⁠וֹ צַדִּ֗יק לְ⁠בִלְתִּ֥י חֲטֹ֛א צַדִּ֖יק וְ⁠ה֣וּא לֹא־חָטָ֑א חָי֤וֹ יִֽחְיֶה֙ כִּ֣י נִזְהָ֔ר וְ⁠אַתָּ֖ה אֶֽת־נַפְשְׁ⁠ךָ֥ הִצַּֽלְתָּ׃ס","wĕ⁠ʼaţá̇֞h ki֧̇y hizĕharĕţ֣̇⁠wò ẕadi̇֗yq lĕ⁠bilĕţi֥̇y ẖàtò֛ʼ ẕadi֖̇yq wĕ⁠h֣ẇʼ lòʼ-ẖátá֑ʼ ẖáy֤wò yiֽẖĕyeh֙ ki֣̇y nizĕhá֔r wĕ⁠ʼaţá֖̇h ʼeֽţ-napĕşĕ̌⁠ká֥ hiẕȧֽlĕţá̇׃s"],[3,22,"וַ⁠תְּהִ֥י עָלַ֛⁠י שָׁ֖ם יַד־יְהוָ֑ה וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י ק֥וּם צֵא֙ אֶל־הַ⁠בִּקְעָ֔ה וְ⁠שָׁ֖ם אֲדַבֵּ֥ר אוֹתָֽ⁠ךְ׃","wa⁠ţĕ̇hi֥y ʻála֛⁠y şá֖̌m yad-yĕhwá֑h wa⁠yò֣̇ʼmer ʼéla֗⁠y q֥ẇm ẕéʼ֙ ʼel-ha⁠bi̇qĕʻá֔h wĕ⁠şá֖̌m ʼàdabé֥̇r ʼwòţáֽ⁠kĕ׃"],[3,23,"וָ⁠אָקוּם֮ וָ⁠אֵצֵ֣א אֶל־הַ⁠בִּקְעָה֒ וְ⁠הִנֵּה־שָׁ֤ם כְּבוֹד־יְהוָה֙ עֹמֵ֔ד כַּ⁠כָּב֕וֹד אֲשֶׁ֥ר רָאִ֖יתִי עַל־נְהַר־כְּבָ֑ר וָ⁠אֶפֹּ֖ל עַל־פָּנָֽ⁠י׃","wá⁠ʼáqẇm֮ wá⁠ʼéẕé֣ʼ ʼel-ha⁠bi̇qĕʻáh֒ wĕ⁠hiné̇h-şá֤̌m kĕ̇bwòd-yĕhwáh֙ ʻòmé֔d kȧ⁠ká̇b֕wòd ʼàşě֥r ráʼi֖yţiy ʻal-nĕhar-kĕ̇bá֑r wá⁠ʼepò֖̇l ʻal-pá̇náֽ⁠y׃"],[3,24,"וַ⁠תָּבֹא־בִ֣⁠י ר֔וּחַ וַ⁠תַּעֲמִדֵ֖⁠נִי עַל־רַגְלָ֑⁠י וַ⁠יְדַבֵּ֤ר אֹתִ⁠י֙ וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י בֹּ֥א הִסָּגֵ֖ר בְּ⁠ת֥וֹךְ בֵּיתֶֽ⁠ךָ׃","wa⁠ţá̇bòʼ-bi֣⁠y r֔ẇẖa wa⁠ţȧʻàmidé֖⁠niy ʻal-ragĕlá֑⁠y wa⁠yĕdabé֤̇r ʼòţi⁠y֙ wa⁠yò֣̇ʼmer ʼéla֔⁠y bò֥̇ʼ hisá̇gé֖r bĕ̇⁠ţ֥wòkĕ bé̇yţeֽ⁠ká׃"],[3,25,"וְ⁠אַתָּ֣ה בֶן־אָדָ֗ם הִנֵּ֨ה נָתְנ֤וּ עָלֶ֨י⁠ךָ֙ עֲבוֹתִ֔ים וַ⁠אֲסָר֖וּ⁠ךָ בָּ⁠הֶ֑ם וְ⁠לֹ֥א תֵצֵ֖א בְּ⁠תוֹכָֽ⁠ם׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֗m hiné̇֨h náţĕn֤ẇ ʻále֨y⁠ká֙ ʻàbwòţi֔ym wa⁠ʼàsár֖ẇ⁠ká bá̇⁠he֑m wĕ⁠lò֥ʼ ţéẕé֖ʼ bĕ̇⁠ţwòkáֽ⁠m׃"],[3,26,"וּ⁠לְשֽׁוֹנְ⁠ךָ֙ אַדְבִּ֣יק אֶל־חִכֶּ֔⁠ךָ וְ⁠נֶֽאֱלַ֔מְתָּ וְ⁠לֹא־תִֽהְיֶ֥ה לָ⁠הֶ֖ם לְ⁠אִ֣ישׁ מוֹכִ֑יחַ כִּ֛י בֵּ֥ית מְרִ֖י הֵֽמָּה׃","ẇ⁠lĕşֽ̌wònĕ⁠ká֙ ʼadĕbi֣̇yq ʼel-ẖikė֔⁠ká wĕ⁠neֽʼèla֔mĕţá̇ wĕ⁠lòʼ-ţiֽhĕye֥h lá⁠he֖m lĕ⁠ʼi֣yş̌ mwòki֑yẖa ki֛̇y bé֥̇yţ mĕri֖y héֽmá̇h׃"],[3,27,"וּֽ⁠בְ⁠דַבְּרִ֤⁠י אֽוֹתְ⁠ךָ֙ אֶפְתַּ֣ח אֶת־פִּ֔י⁠ךָ וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהֹוִ֑ה הַ⁠שֹּׁמֵ֤עַ ׀ יִשְׁמָע֙ וְ⁠הֶ⁠חָדֵ֣ל ׀ יֶחְדָּ֔ל כִּ֛י בֵּ֥ית מְרִ֖י הֵֽמָּה׃ס","ẇֽ⁠bĕ⁠dabĕ̇ri֤⁠y ʼֽwòţĕ⁠ká֙ ʼepĕţȧ֣ẖ ʼeţ-pi̇֔y⁠ká wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhòwi֑h ha⁠şò̇̌mé֤ʻa ׀ yişĕ̌máʻ֙ wĕ⁠he⁠ẖádé֣l ׀ yeẖĕdá̇֔l ki֛̇y bé֥̇yţ mĕri֖y héֽmá̇h׃s"],[4,1,"וְ⁠אַתָּ֤ה בֶן־אָדָם֙ קַח־לְ⁠ךָ֣ לְבֵנָ֔ה וְ⁠נָתַתָּ֥ה אוֹתָ֖⁠הּ לְ⁠פָנֶ֑י⁠ךָ וְ⁠חַקּוֹתָ֥ עָלֶ֛י⁠הָ עִ֖יר אֶת־יְרוּשָׁלִָֽם׃","wĕ⁠ʼaţá֤̇h ben-ʼádám֙ qaẖ-lĕ⁠ká֣ lĕbéná֔h wĕ⁠náţaţá֥̇h ʼwòţá֖⁠ḣ lĕ⁠páne֑y⁠ká wĕ⁠ẖaq̇wòţá֥ ʻále֛y⁠há ʻi֖yr ʼeţ-yĕrẇşá̌liáֽm׃"],[4,2,"וְ⁠נָתַתָּ֨ה עָלֶ֜י⁠הָ מָצ֗וֹר וּ⁠בָנִ֤יתָ עָלֶ֨י⁠הָ֙ דָּיֵ֔ק וְ⁠שָׁפַכְתָּ֥ עָלֶ֖י⁠הָ סֹֽלְלָ֑ה וְ⁠נָתַתָּ֨ה עָלֶ֧י⁠הָ מַחֲנ֛וֹת וְ⁠שִׂים־עָלֶ֥י⁠הָ כָּרִ֖ים סָבִֽיב׃","wĕ⁠náţaţá̇֨h ʻále֜y⁠há máẕ֗wòr ẇ⁠báni֤yţá ʻále֨y⁠há֙ dá̇yé֔q wĕ⁠şá̌pakĕţá֥̇ ʻále֖y⁠há sòֽlĕlá֑h wĕ⁠náţaţá̇֨h ʻále֧y⁠há maẖàn֛wòţ wĕ⁠şîym-ʻále֥y⁠há ká̇ri֖ym sábiֽyb׃"],[4,3,"וְ⁠אַתָּ֤ה קַח־לְ⁠ךָ֙ מַחֲבַ֣ת בַּרְזֶ֔ל וְ⁠נָתַתָּ֤ה אוֹתָ⁠הּ֙ קִ֣יר בַּרְזֶ֔ל בֵּינְ⁠ךָ֖ וּ⁠בֵ֣ין הָ⁠עִ֑יר וַ⁠הֲכִינֹתָה֩ אֶת־פָּנֶ֨י⁠ךָ אֵלֶ֜י⁠הָ וְ⁠הָיְתָ֤ה בַ⁠מָּצוֹר֙ וְ⁠צַרְתָּ֣ עָלֶ֔י⁠הָ א֥וֹת הִ֖יא לְ⁠בֵ֥ית יִשְׂרָאֵֽל׃ס","wĕ⁠ʼaţá֤̇h qaẖ-lĕ⁠ká֙ maẖàba֣ţ bȧrĕze֔l wĕ⁠náţaţá֤̇h ʼwòţá⁠ḣ֙ qi֣yr bȧrĕze֔l bé̇ynĕ⁠ká֖ ẇ⁠bé֣yn há⁠ʻi֑yr wa⁠hàkiynòţáh֩ ʼeţ-pá̇ne֨y⁠ká ʼéle֜y⁠há wĕ⁠háyĕţá֤h ba⁠má̇ẕwòr֙ wĕ⁠ẕarĕţá֣̇ ʻále֔y⁠há ʼ֥wòţ hi֖yʼ lĕ⁠bé֥yţ yişĕ̂ráʼéֽl׃s"],[4,4,"וְ⁠אַתָּ֤ה שְׁכַב֙ עַל־צִדְּ⁠ךָ֣ הַ⁠שְּׂמָאלִ֔י וְ⁠שַׂמְתָּ֛ אֶת־עֲוֺ֥ן בֵּֽית־יִשְׂרָאֵ֖ל עָלָ֑י⁠ו מִסְפַּ֤ר הַ⁠יָּמִים֙ אֲשֶׁ֣ר תִּשְׁכַּ֣ב עָלָ֔י⁠ו תִּשָּׂ֖א אֶת־עֲוֺנָֽ⁠ם׃","wĕ⁠ʼaţá֤̇h şĕ̌kab֙ ʻal-ẕidĕ̇⁠ká֣ ha⁠şĕ̇̂máʼli֔y wĕ⁠şâmĕţá֛̇ ʼeţ-ʻàwֺ֥n béֽ̇yţ-yişĕ̂ráʼé֖l ʻálá֑y⁠w misĕpȧ֤r ha⁠yá̇miym֙ ʼàşě֣r ţi̇şĕ̌kȧ֣b ʻálá֔y⁠w ţi̇şá֖̇̂ʼ ʼeţ-ʻàwֺnáֽ⁠m׃"],[4,5,"וַ⁠אֲנִ֗י נָתַ֤תִּֽי לְ⁠ךָ֙ אֶת־שְׁנֵ֣י עֲוֺנָ֔⁠ם לְ⁠מִסְפַּ֣ר יָמִ֔ים שְׁלֹשׁ־מֵא֥וֹת וְ⁠תִשְׁעִ֖ים י֑וֹם וְ⁠נָשָׂ֖אתָ עֲוֺ֥ן בֵּֽית־יִשְׂרָאֵֽל׃","wa⁠ʼàni֗y náţa֤ţiֽ̇y lĕ⁠ká֙ ʼeţ-şĕ̌né֣y ʻàwֺná֔⁠m lĕ⁠misĕpȧ֣r yámi֔ym şĕ̌lòş̌-méʼ֥wòţ wĕ⁠ţişĕ̌ʻi֖ym y֑wòm wĕ⁠náşá֖̂ʼţá ʻàwֺ֥n béֽ̇yţ-yişĕ̂ráʼéֽl׃"],[4,6,"וְ⁠כִלִּיתָ֣ אֶת־אֵ֗לֶּה וְ⁠שָׁ֨כַבְתָּ֜ עַל־צִדְּ⁠ךָ֤ ה⁠ימיני שֵׁנִ֔ית וְ⁠נָשָׂ֖אתָ אֶת־עֲוֺ֣ן בֵּית־יְהוּדָ֑ה אַרְבָּעִ֣ים י֔וֹם י֧וֹם לַ⁠שָּׁנָ֛ה י֥וֹם לַ⁠שָּׁנָ֖ה נְתַתִּ֥י⁠ו לָֽ⁠ךְ׃","wĕ⁠kili̇yţá֣ ʼeţ-ʼé֗lėh wĕ⁠şá̌֨kabĕţá̇֜ ʻal-ẕidĕ̇⁠ká֤ h⁠ymyny şé̌ni֔yţ wĕ⁠náşá֖̂ʼţá ʼeţ-ʻàwֺ֣n bé̇yţ-yĕhẇdá֑h ʼarĕbá̇ʻi֣ym y֔wòm y֧wòm la⁠şá̇̌ná֛h y֥wòm la⁠şá̇̌ná֖h nĕţaţi֥̇y⁠w láֽ⁠kĕ׃"],[4,7,"וְ⁠אֶל־מְצ֤וֹר יְרוּשָׁלִַ֨ם֙ תָּכִ֣ין פָּנֶ֔י⁠ךָ וּֽ⁠זְרֹעֲ⁠ךָ֖ חֲשׂוּפָ֑ה וְ⁠נִבֵּאתָ֖ עָלֶֽי⁠הָ׃","wĕ⁠ʼel-mĕẕ֤wòr yĕrẇşá̌lia֨m֙ ţá̇ki֣yn pá̇ne֔y⁠ká ẇֽ⁠zĕròʻà⁠ká֖ ẖàş̂ẇpá֑h wĕ⁠nibé̇ʼţá֖ ʻáleֽy⁠há׃"],[4,8,"וְ⁠הִנֵּ֛ה נָתַ֥תִּי עָלֶ֖י⁠ךָ עֲבוֹתִ֑ים וְ⁠לֹֽא־תֵהָפֵ֤ךְ מִֽ⁠צִּדְּ⁠ךָ֙ אֶל־צִדֶּ֔⁠ךָ עַד־כַּלּוֹתְ⁠ךָ֖ יְמֵ֥י מְצוּרֶֽ⁠ךָ׃","wĕ⁠hiné֛̇h náţa֥ţi̇y ʻále֖y⁠ká ʻàbwòţi֑ym wĕ⁠lòֽʼ-ţéhápé֤kĕ miֽ⁠ẕi̇dĕ̇⁠ká֙ ʼel-ẕidė֔⁠ká ʻad-kȧl̇wòţĕ⁠ká֖ yĕmé֥y mĕẕẇreֽ⁠ká׃"],[4,9,"וְ⁠אַתָּ֣ה קַח־לְ⁠ךָ֡ חִטִּ֡ין וּ֠⁠שְׂעֹרִים וּ⁠פ֨וֹל וַ⁠עֲדָשִׁ֜ים וְ⁠דֹ֣חַן וְ⁠כֻסְּמִ֗ים וְ⁠נָתַתָּ֤ה אוֹתָ⁠ם֙ בִּ⁠כְלִ֣י אֶחָ֔ד וְ⁠עָשִׂ֧יתָ אוֹתָ֛⁠ם לְ⁠ךָ֖ לְ⁠לָ֑חֶם מִסְפַּ֨ר הַ⁠יָּמִ֜ים אֲשֶׁר־אַתָּ֣ה ׀ שׁוֹכֵ֣ב עַֽל־צִדְּ⁠ךָ֗ שְׁלֹשׁ־מֵא֧וֹת וְ⁠תִשְׁעִ֛ים י֖וֹם תֹּאכֲלֶֽ⁠נּוּ׃","wĕ⁠ʼaţá֣̇h qaẖ-lĕ⁠ká֡ ẖiti̇֡yn ẇ֠⁠şĕ̂ʻòriym ẇ⁠p֨wòl wa⁠ʻàdáşǐ֜ym wĕ⁠dò֣ẖan wĕ⁠kusĕ̇mi֗ym wĕ⁠náţaţá֤̇h ʼwòţá⁠m֙ bi̇⁠kĕli֣y ʼeẖá֔d wĕ⁠ʻáşî֧yţá ʼwòţá֛⁠m lĕ⁠ká֖ lĕ⁠lá֑ẖem misĕpȧ֨r ha⁠yá̇mi֜ym ʼàşěr-ʼaţá֣̇h ׀ ş̌wòké֣b ʻaֽl-ẕidĕ̇⁠ká֗ şĕ̌lòş̌-méʼ֧wòţ wĕ⁠ţişĕ̌ʻi֛ym y֖wòm ţò̇ʼkàleֽ⁠ṅẇ׃"],[4,10,"וּ⁠מַאֲכָֽלְ⁠ךָ֙ אֲשֶׁ֣ר תֹּאכֲלֶ֔⁠נּוּ בְּ⁠מִשְׁק֕וֹל עֶשְׂרִ֥ים שֶׁ֖קֶל לַ⁠יּ֑וֹם מֵ⁠עֵ֥ת עַד־עֵ֖ת תֹּאכֲלֶֽ⁠נּוּ׃","ẇ⁠maʼàkáֽlĕ⁠ká֙ ʼàşě֣r ţò̇ʼkàle֔⁠ṅẇ bĕ̇⁠mişĕ̌q֕wòl ʻeşĕ̂ri֥ym şě֖qel la⁠ẏ֑wòm mé⁠ʻé֥ţ ʻad-ʻé֖ţ ţò̇ʼkàleֽ⁠ṅẇ׃"],[4,11,"וּ⁠מַ֛יִם בִּ⁠מְשׂוּרָ֥ה תִשְׁתֶּ֖ה שִׁשִּׁ֣ית הַ⁠הִ֑ין מֵ⁠עֵ֥ת עַד־עֵ֖ת תִּשְׁתֶּֽה׃","ẇ⁠ma֛yim bi̇⁠mĕş̂ẇrá֥h ţişĕ̌ţė֖h şǐşi֣̇̌yţ ha⁠hi֑yn mé⁠ʻé֥ţ ʻad-ʻé֖ţ ţi̇şĕ̌ţėֽh׃"],[4,12,"וְ⁠עֻגַ֥ת שְׂעֹרִ֖ים תֹּֽאכֲלֶ֑⁠נָּה וְ⁠הִ֗יא בְּ⁠גֶֽלְלֵי֙ צֵאַ֣ת הָֽ⁠אָדָ֔ם תְּעֻגֶ֖⁠נָה לְ⁠עֵינֵי⁠הֶֽם׃ס","wĕ⁠ʻuga֥ţ şĕ̂ʻòri֖ym ţòֽ̇ʼkàle֑⁠ná̇h wĕ⁠hi֗yʼ bĕ̇⁠geֽlĕléy֙ ẕéʼa֣ţ háֽ⁠ʼádá֔m ţĕ̇ʻuge֖⁠náh lĕ⁠ʻéynéy⁠heֽm׃s"],[4,13,"וַ⁠יֹּ֣אמֶר יְהוָ֔ה כָּ֣כָה יֹאכְל֧וּ בְנֵֽי־יִשְׂרָאֵ֛ל אֶת־לַחְמָ֖⁠ם טָמֵ֑א בַּ⁠גּוֹיִ֕ם אֲשֶׁ֥ר אַדִּיחֵ֖⁠ם שָֽׁם׃","wa⁠yò֣̇ʼmer yĕhwá֔h ká֣̇káh yòʼkĕl֧ẇ bĕnéֽy-yişĕ̂ráʼé֛l ʼeţ-laẖĕmá֖⁠m támé֑ʼ bȧ⁠ġwòyi֕m ʼàşě֥r ʼadi̇yẖé֖⁠m şáֽ̌m׃"],[4,14,"וָ⁠אֹמַ֗ר אֲהָהּ֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנֵּ֥ה נַפְשִׁ֖⁠י לֹ֣א מְטֻמָּאָ֑ה וּ⁠נְבֵלָ֨ה וּ⁠טְרֵפָ֤ה לֹֽא־אָכַ֨לְתִּי֙ מִ⁠נְּעוּרַ֣⁠י וְ⁠עַד־עַ֔תָּה וְ⁠לֹא־בָ֥א בְּ⁠פִ֖⁠י בְּשַׂ֥ר פִּגּֽוּל׃ס","wá⁠ʼòma֗r ʼàháḣ֙ ʼàdòná֣⁠y yĕhwi֔h hiné֥̇h napĕşǐ֖⁠y lò֣ʼ mĕtumá̇ʼá֑h ẇ⁠nĕbélá֨h ẇ⁠tĕrépá֤h lòֽʼ-ʼáka֨lĕţi̇y֙ mi⁠nĕ̇ʻẇra֣⁠y wĕ⁠ʻad-ʻa֔ţá̇h wĕ⁠lòʼ-bá֥ʼ bĕ̇⁠pi֖⁠y bĕ̇şâ֥r pi̇ġֽẇl׃s"],[4,15,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י רְאֵ֗ה נָתַ֤תִּֽי לְ⁠ךָ֙ אֶת־צפועי הַ⁠בָּקָ֔ר תַּ֖חַת גֶּלְלֵ֣י הָֽ⁠אָדָ֑ם וְ⁠עָשִׂ֥יתָ אֶֽת־לַחְמְ⁠ךָ֖ עֲלֵי⁠הֶֽם׃ס","wa⁠yò֣̇ʼmer ʼéla֔⁠y rĕʼé֗h náţa֤ţiֽ̇y lĕ⁠ká֙ ʼeţ-ẕpwʻy ha⁠bá̇qá֔r ţȧ֖ẖaţ gėlĕlé֣y háֽ⁠ʼádá֑m wĕ⁠ʻáşî֥yţá ʼeֽţ-laẖĕmĕ⁠ká֖ ʻàléy⁠heֽm׃s"],[4,16,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י בֶּן־אָדָם֙ הִנְ⁠נִ֨י שֹׁבֵ֤ר מַטֵּה־לֶ֨חֶם֙ בִּ⁠יר֣וּשָׁלִַ֔ם וְ⁠אָכְלוּ־לֶ֥חֶם בְּ⁠מִשְׁקָ֖ל וּ⁠בִ⁠דְאָגָ֑ה וּ⁠מַ֕יִם בִּ⁠מְשׂוּרָ֥ה וּ⁠בְ⁠שִׁמָּמ֖וֹן יִשְׁתּֽוּ׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y bėn-ʼádám֙ hinĕ⁠ni֨y şò̌bé֤r maté̇h-le֨ẖem֙ bi̇⁠yr֣ẇşá̌lia֔m wĕ⁠ʼákĕlẇ-le֥ẖem bĕ̇⁠mişĕ̌qá֖l ẇ⁠bi⁠dĕʼágá֑h ẇ⁠ma֕yim bi̇⁠mĕş̂ẇrá֥h ẇ⁠bĕ⁠şǐmá̇m֖wòn yişĕ̌ţֽ̇ẇ׃"],[4,17,"לְמַ֥עַן יַחְסְר֖וּ לֶ֣חֶם וָ⁠מָ֑יִם וְ⁠נָשַׁ֨מּוּ֙ אִ֣ישׁ וְ⁠אָחִ֔י⁠ו וְ⁠נָמַ֖קּוּ בַּ⁠עֲוֺנָֽ⁠ם׃פ","lĕma֥ʻan yaẖĕsĕr֖ẇ le֣ẖem wá⁠má֑yim wĕ⁠náşǎ֨ṁẇ֙ ʼi֣yş̌ wĕ⁠ʼáẖi֔y⁠w wĕ⁠náma֖q̇ẇ bȧ⁠ʻàwֺnáֽ⁠m׃p"],[5,1,"וְ⁠אַתָּ֨ה בֶן־אָדָ֜ם קַח־לְ⁠ךָ֣ ׀ חֶ֣רֶב חַדָּ֗ה תַּ֤עַר הַ⁠גַּלָּבִים֙ תִּקָּחֶ֣⁠נָּה לָּ֔⁠ךְ וְ⁠הַעֲבַרְתָּ֥ עַל־רֹאשְׁ⁠ךָ֖ וְ⁠עַל־זְקָנֶ֑⁠ךָ וְ⁠לָקַחְתָּ֥ לְ⁠ךָ֛ מֹאזְנֵ֥י מִשְׁקָ֖ל וְ⁠חִלַּקְתָּֽ⁠ם׃","wĕ⁠ʼaţá̇֨h ben-ʼádá֜m qaẖ-lĕ⁠ká֣ ׀ ẖe֣reb ẖadá̇֗h ţȧ֤ʻar ha⁠gȧlá̇biym֙ ţi̇qá̇ẖe֣⁠ná̇h lá̇֔⁠kĕ wĕ⁠haʻàbarĕţá֥̇ ʻal-ròʼşĕ̌⁠ká֖ wĕ⁠ʻal-zĕqáne֑⁠ká wĕ⁠láqaẖĕţá֥̇ lĕ⁠ká֛ mòʼzĕné֥y mişĕ̌qá֖l wĕ⁠ẖilȧqĕţáֽ̇⁠m׃"],[5,2,"שְׁלִשִׁ֗ית בָּ⁠א֤וּר תַּבְעִיר֙ בְּ⁠ת֣וֹךְ הָ⁠עִ֔יר כִּ⁠מְלֹ֖את יְמֵ֣י הַ⁠מָּצ֑וֹר וְ⁠לָֽקַחְתָּ֣ אֶת־הַ⁠שְּׁלִשִׁ֗ית תַּכֶּ֤ה בַ⁠חֶ֨רֶב֙ סְבִ֣יבוֹתֶ֔י⁠הָ וְ⁠הַ⁠שְּׁלִשִׁית֙ תִּזְרֶ֣ה לָ⁠ר֔וּחַ וְ⁠חֶ֖רֶב אָרִ֥יק אַחֲרֵי⁠הֶֽם׃","şĕ̌lişǐ֗yţ bá̇⁠ʼ֤ẇr ţȧbĕʻiyr֙ bĕ̇⁠ţ֣wòkĕ há⁠ʻi֔yr ki̇⁠mĕlò֖ʼţ yĕmé֣y ha⁠má̇ẕ֑wòr wĕ⁠lֽáqaẖĕţá֣̇ ʼeţ-ha⁠şĕ̇̌lişǐ֗yţ ţȧkė֤h ba⁠ẖe֨reb֙ sĕbi֣ybwòţe֔y⁠há wĕ⁠ha⁠şĕ̇̌lişǐyţ֙ ţi̇zĕre֣h lá⁠r֔ẇẖa wĕ⁠ẖe֖reb ʼári֥yq ʼaẖàréy⁠heֽm׃"],[5,3,"וְ⁠לָקַחְתָּ֥ מִ⁠שָּׁ֖ם מְעַ֣ט בְּ⁠מִסְפָּ֑ר וְ⁠צַרְתָּ֥ אוֹתָ֖⁠ם בִּ⁠כְנָפֶֽי⁠ךָ׃","wĕ⁠láqaẖĕţá֥̇ mi⁠şá֖̇̌m mĕʻa֣t bĕ̇⁠misĕpá֑̇r wĕ⁠ẕarĕţá֥̇ ʼwòţá֖⁠m bi̇⁠kĕnápeֽy⁠ká׃"],[5,4,"וּ⁠מֵ⁠הֶם֙ ע֣וֹד תִּקָּ֔ח וְ⁠הִשְׁלַכְתָּ֤ אוֹתָ⁠ם֙ אֶל־תּ֣וֹךְ הָ⁠אֵ֔שׁ וְ⁠שָׂרַפְתָּ֥ אֹתָ֖⁠ם בָּ⁠אֵ֑שׁ מִמֶּ֥⁠נּוּ תֵצֵא־אֵ֖שׁ אֶל־כָּל־בֵּ֥ית יִשְׂרָאֵֽל׃פ","ẇ⁠mé⁠hem֙ ʻ֣wòd ţi̇qá̇֔ẖ wĕ⁠hişĕ̌lakĕţá֤̇ ʼwòţá⁠m֙ ʼel-ţ֣̇wòkĕ há⁠ʼé֔ş̌ wĕ⁠şá̂rapĕţá֥̇ ʼòţá֖⁠m bá̇⁠ʼé֑ş̌ mimė֥⁠ṅẇ ţéẕéʼ-ʼé֖ş̌ ʼel-ká̇l-bé֥̇yţ yişĕ̂ráʼéֽl׃p"],[5,5,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהֹוִ֔ה זֹ֚את יְר֣וּשָׁלִַ֔ם בְּ⁠ת֥וֹךְ הַ⁠גּוֹיִ֖ם שַׂמְתִּ֑י⁠הָ וּ⁠סְבִיבוֹתֶ֖י⁠הָ אֲרָצֽוֹת׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhòwi֔h zò֚ʼţ yĕr֣ẇşá̌lia֔m bĕ̇⁠ţ֥wòkĕ ha⁠ġwòyi֖m şâmĕţi֑̇y⁠há ẇ⁠sĕbiybwòţe֖y⁠há ʼàráẕֽwòţ׃"],[5,6,"וַ⁠תֶּ֨מֶר אֶת־מִשְׁפָּטַ֤⁠י לְ⁠רִשְׁעָה֙ מִן־הַ⁠גּוֹיִ֔ם וְ⁠אֶ֨ת־חֻקּוֹתַ֔⁠י מִן־הָ⁠אֲרָצ֖וֹת אֲשֶׁ֣ר סְבִיבוֹתֶ֑י⁠הָ כִּ֤י בְ⁠מִשְׁפָּטַ⁠י֙ מָאָ֔סוּ וְ⁠חֻקּוֹתַ֖⁠י לֹא־הָלְכ֥וּ בָ⁠הֶֽם׃ס","wa⁠ţė֨mer ʼeţ-mişĕ̌pá̇ta֤⁠y lĕ⁠rişĕ̌ʻáh֙ min-ha⁠ġwòyi֔m wĕ⁠ʼe֨ţ-ẖuq̇wòţa֔⁠y min-há⁠ʼàráẕ֖wòţ ʼàşě֣r sĕbiybwòţe֑y⁠há ki֤̇y bĕ⁠mişĕ̌pá̇ta⁠y֙ máʼá֔sẇ wĕ⁠ẖuq̇wòţa֖⁠y lòʼ-hálĕk֥ẇ bá⁠heֽm׃s"],[5,7,"לָ⁠כֵ֞ן כֹּֽה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה יַ֤עַן הֲמָנְ⁠כֶם֙ מִן־הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר סְבִיבֽוֹתֵי⁠כֶ֔ם בְּ⁠חֻקּוֹתַ⁠י֙ לֹ֣א הֲלַכְתֶּ֔ם וְ⁠אֶת־מִשְׁפָּטַ֖⁠י לֹ֣א עֲשִׂיתֶ֑ם וּֽ⁠כְ⁠מִשְׁפְּטֵ֧י הַ⁠גּוֹיִ֛ם אֲשֶׁ֥ר סְבִיבוֹתֵי⁠כֶ֖ם לֹ֥א עֲשִׂיתֶֽם׃ס","lá⁠ké֞n kòֽ̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h ya֤ʻan hàmánĕ⁠kem֙ min-ha⁠ġwòyim֙ ʼàşě֣r sĕbiybֽwòţéy⁠ke֔m bĕ̇⁠ẖuq̇wòţa⁠y֙ lò֣ʼ hàlakĕţė֔m wĕ⁠ʼeţ-mişĕ̌pá̇ta֖⁠y lò֣ʼ ʻàşîyţe֑m ẇֽ⁠kĕ⁠mişĕ̌pĕ̇té֧y ha⁠ġwòyi֛m ʼàşě֥r sĕbiybwòţéy⁠ke֖m lò֥ʼ ʻàşîyţeֽm׃s"],[5,8,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִ֥י עָלַ֖יִ⁠ךְ גַּם־אָ֑נִי וְ⁠עָשִׂ֧יתִי בְ⁠תוֹכֵ֛⁠ךְ מִשְׁפָּטִ֖ים לְ⁠עֵינֵ֥י הַ⁠גּוֹיִֽם׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠ni֥y ʻála֖yi⁠kĕ gȧm-ʼá֑niy wĕ⁠ʻáşî֧yţiy bĕ⁠ţwòké֛⁠kĕ mişĕ̌pá̇ti֖ym lĕ⁠ʻéyné֥y ha⁠ġwòyiֽm׃"],[5,9,"וְ⁠עָשִׂ֣יתִי בָ֗⁠ךְ אֵ֚ת אֲשֶׁ֣ר לֹֽא־עָשִׂ֔יתִי וְ⁠אֵ֛ת אֲשֶֽׁר־לֹֽא־אֶעֱשֶׂ֥ה כָמֹ֖⁠הוּ ע֑וֹד יַ֖עַן כָּל־תּוֹעֲבֹתָֽיִ⁠ךְ׃ס","wĕ⁠ʻáşî֣yţiy bá֗⁠kĕ ʼé֚ţ ʼàşě֣r lòֽʼ-ʻáşî֔yţiy wĕ⁠ʼé֛ţ ʼàşěֽr-lòֽʼ-ʼeʻèşê֥h kámò֖⁠hẇ ʻ֑wòd ya֖ʻan ká̇l-ţ̇wòʻàbòţáֽyi⁠kĕ׃s"],[5,10,"לָ⁠כֵ֗ן אָב֞וֹת יֹאכְל֤וּ בָנִים֙ בְּ⁠תוֹכֵ֔⁠ךְ וּ⁠בָנִ֖ים יֹאכְל֣וּ אֲבוֹתָ֑⁠ם וְ⁠עָשִׂ֤יתִי בָ⁠ךְ֙ שְׁפָטִ֔ים וְ⁠זֵרִיתִ֥י אֶת־כָּל־שְׁאֵרִיתֵ֖⁠ךְ לְ⁠כָל־רֽוּחַ׃פ","lá⁠ké֗n ʼáb֞wòţ yòʼkĕl֤ẇ bániym֙ bĕ̇⁠ţwòké֔⁠kĕ ẇ⁠báni֖ym yòʼkĕl֣ẇ ʼàbwòţá֑⁠m wĕ⁠ʻáşî֤yţiy bá⁠kĕ֙ şĕ̌páti֔ym wĕ⁠zériyţi֥y ʼeţ-ká̇l-şĕ̌ʼériyţé֖⁠kĕ lĕ⁠kál-rֽẇẖa׃p"],[5,11,"לָ⁠כֵ֣ן חַי־אָ֗נִי נְאֻם֮ אֲדֹנָ֣⁠י יְהוִה֒ אִם־לֹ֗א יַ֚עַן אֶת־מִקְדָּשִׁ֣⁠י טִמֵּ֔את בְּ⁠כָל־שִׁקּוּצַ֖יִ⁠ךְ וּ⁠בְ⁠כָל־תּוֹעֲבֹתָ֑יִ⁠ךְ וְ⁠גַם־אֲנִ֤י אֶגְרַע֙ וְ⁠לֹא־תָח֣וֹס עֵינִ֔⁠י וְ⁠גַם־אֲנִ֖י לֹ֥א אֶחְמֽוֹל׃","lá⁠ké֣n ẖay-ʼá֗niy nĕʼum֮ ʼàdòná֣⁠y yĕhwih֒ ʼim-lò֗ʼ ya֚ʻan ʼeţ-miqĕdá̇şǐ֣⁠y timé̇֔ʼţ bĕ̇⁠kál-şǐq̇ẇẕa֖yi⁠kĕ ẇ⁠bĕ⁠kál-ţ̇wòʻàbòţá֑yi⁠kĕ wĕ⁠gam-ʼàni֤y ʼegĕraʻ֙ wĕ⁠lòʼ-ţáẖ֣wòs ʻéyni֔⁠y wĕ⁠gam-ʼàni֖y lò֥ʼ ʼeẖĕmֽwòl׃"],[5,12,"שְׁלִשִׁתֵ֞⁠יךְ בַּ⁠דֶּ֣בֶר יָמ֗וּתוּ וּ⁠בָֽ⁠רָעָב֙ יִכְל֣וּ בְ⁠תוֹכֵ֔⁠ךְ וְ⁠הַ֨⁠שְּׁלִשִׁ֔ית בַּ⁠חֶ֖רֶב יִפְּל֣וּ סְבִיבוֹתָ֑יִ⁠ךְ וְ⁠הַ⁠שְּׁלִישִׁית֙ לְ⁠כָל־ר֣וּחַ אֱזָרֶ֔ה וְ⁠חֶ֖רֶב אָרִ֥יק אַחֲרֵי⁠הֶֽם׃","şĕ̌lişǐţé֞⁠ykĕ bȧ⁠dė֣ber yám֗ẇţẇ ẇ⁠báֽ⁠ráʻáb֙ yikĕl֣ẇ bĕ⁠ţwòké֔⁠kĕ wĕ⁠ha֨⁠şĕ̇̌lişǐ֔yţ bȧ⁠ẖe֖reb yipĕ̇l֣ẇ sĕbiybwòţá֑yi⁠kĕ wĕ⁠ha⁠şĕ̇̌liyşǐyţ֙ lĕ⁠kál-r֣ẇẖa ʼèzáre֔h wĕ⁠ẖe֖reb ʼári֥yq ʼaẖàréy⁠heֽm׃"],[5,13,"וְ⁠כָלָ֣ה אַפִּ֗⁠י וַ⁠הֲנִחוֹתִ֧י חֲמָתִ֛⁠י בָּ֖⁠ם וְ⁠הִנֶּחָ֑מְתִּי וְֽ⁠יָדְע֞וּ כִּי־אֲנִ֣י יְהוָ֗ה דִּבַּ֨רְתִּי֙ בְּ⁠קִנְאָתִ֔⁠י בְּ⁠כַלּוֹתִ֥⁠י חֲמָתִ֖⁠י בָּֽ⁠ם׃","wĕ⁠kálá֣h ʼapi̇֗⁠y wa⁠hàniẖwòţi֧y ẖàmáţi֛⁠y bá֖̇⁠m wĕ⁠hinėẖá֑mĕţi̇y wĕֽ⁠yádĕʻ֞ẇ ki̇y-ʼàni֣y yĕhwá֗h di̇bȧ֨rĕţi̇y֙ bĕ̇⁠qinĕʼáţi֔⁠y bĕ̇⁠kal̇wòţi֥⁠y ẖàmáţi֖⁠y báֽ̇⁠m׃"],[5,14,"וְ⁠אֶתְּנֵ⁠ךְ֙ לְ⁠חָרְבָּ֣ה וּ⁠לְ⁠חֶרְפָּ֔ה בַּ⁠גּוֹיִ֖ם אֲשֶׁ֣ר סְבִיבוֹתָ֑יִ⁠ךְ לְ⁠עֵינֵ֖י כָּל־עוֹבֵֽר׃","wĕ⁠ʼeţĕ̇né⁠kĕ֙ lĕ⁠ẖárĕbá֣̇h ẇ⁠lĕ⁠ẖerĕpá̇֔h bȧ⁠ġwòyi֖m ʼàşě֣r sĕbiybwòţá֑yi⁠kĕ lĕ⁠ʻéyné֖y ká̇l-ʻwòbéֽr׃"],[5,15,"וְֽ⁠הָ֨יְתָ֜ה חֶרְפָּ֤ה וּ⁠גְדוּפָה֙ מוּסָ֣ר וּ⁠מְשַׁמָּ֔ה לַ⁠גּוֹיִ֖ם אֲשֶׁ֣ר סְבִיבוֹתָ֑יִ⁠ךְ בַּ⁠עֲשׂוֹתִ⁠י֩ בָ֨⁠ךְ שְׁפָטִ֜ים בְּ⁠אַ֤ף וּ⁠בְ⁠חֵמָה֙ וּ⁠בְ⁠תֹכְח֣וֹת חֵמָ֔ה אֲנִ֥י יְהוָ֖ה דִּבַּֽרְתִּי׃","wĕֽ⁠há֨yĕţá֜h ẖerĕpá֤̇h ẇ⁠gĕdẇpáh֙ mẇsá֣r ẇ⁠mĕşǎmá̇֔h la⁠ġwòyi֖m ʼàşě֣r sĕbiybwòţá֑yi⁠kĕ bȧ⁠ʻàş̂wòţi⁠y֩ bá֨⁠kĕ şĕ̌páti֜ym bĕ̇⁠ʼa֤p ẇ⁠bĕ⁠ẖémáh֙ ẇ⁠bĕ⁠ţòkĕẖ֣wòţ ẖémá֔h ʼàni֥y yĕhwá֖h di̇bȧֽrĕţi̇y׃"],[5,16,"בְּֽ⁠שַׁלְּחִ֡⁠י אֶת־חִצֵּי֩ הָ⁠רָעָ֨ב הָ⁠רָעִ֤ים בָּ⁠הֶם֙ אֲשֶׁ֣ר הָי֣וּ לְ⁠מַשְׁחִ֔ית אֲשֶׁר־אֲשַׁלַּ֥ח אוֹתָ֖⁠ם לְ⁠שַֽׁחֶתְ⁠כֶ֑ם וְ⁠רָעָב֙ אֹסֵ֣ף עֲלֵי⁠כֶ֔ם וְ⁠שָׁבַרְתִּ֥י לָ⁠כֶ֖ם מַטֵּה־לָֽחֶם׃","bĕֽ̇⁠şǎlĕ̇ẖi֡⁠y ʼeţ-ẖiẕé̇y֩ há⁠ráʻá֨b há⁠ráʻi֤ym bá̇⁠hem֙ ʼàşě֣r háy֣ẇ lĕ⁠maşĕ̌ẖi֔yţ ʼàşěr-ʼàşǎlȧ֥ẖ ʼwòţá֖⁠m lĕ⁠şǎֽẖeţĕ⁠ke֑m wĕ⁠ráʻáb֙ ʼòsé֣p ʻàléy⁠ke֔m wĕ⁠şá̌barĕţi֥̇y lá⁠ke֖m maté̇h-láֽẖem׃"],[5,17,"וְ⁠שִׁלַּחְתִּ֣י עֲ֠לֵי⁠כֶם רָעָ֞ב וְ⁠חַיָּ֤ה רָעָה֙ וְ⁠שִׁכְּלֻ֔⁠ךְ וְ⁠דֶ֥בֶר וָ⁠דָ֖ם יַעֲבָר־בָּ֑⁠ךְ וְ⁠חֶ֨רֶב֙ אָבִ֣יא עָלַ֔יִ⁠ךְ אֲנִ֥י יְהוָ֖ה דִּבַּֽרְתִּי׃פ","wĕ⁠şǐlȧẖĕţi֣̇y ʻà֠léy⁠kem ráʻá֞b wĕ⁠ẖayá֤̇h ráʻáh֙ wĕ⁠şǐkĕ̇lu֔⁠kĕ wĕ⁠de֥ber wá⁠dá֖m yaʻàbár-bá֑̇⁠kĕ wĕ⁠ẖe֨reb֙ ʼábi֣yʼ ʻála֔yi⁠kĕ ʼàni֥y yĕhwá֖h di̇bȧֽrĕţi̇y׃p"],[6,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[6,2,"בֶּן־אָדָ֕ם שִׂ֥ים פָּנֶ֖י⁠ךָ אֶל־הָרֵ֣י יִשְׂרָאֵ֑ל וְ⁠הִנָּבֵ֖א אֲלֵי⁠הֶֽם׃","bėn-ʼádá֕m şî֥ym pá̇ne֖y⁠ká ʼel-háré֣y yişĕ̂ráʼé֑l wĕ⁠hiná̇bé֖ʼ ʼàléy⁠heֽm׃"],[6,3,"וְ⁠אָ֣מַרְתָּ֔ הָרֵי֙ יִשְׂרָאֵ֔ל שִׁמְע֖וּ דְּבַר־אֲדֹנָ֣⁠י יְהוִ֑ה כֹּה־אָמַ֣ר אֲדֹנָ֣⁠י יְ֠הוִה לֶ⁠הָרִ֨ים וְ⁠לַ⁠גְּבָע֜וֹת לָ⁠אֲפִיקִ֣ים ו⁠ל⁠גאית הִנְ⁠נִ֨י אֲנִ֜י מֵבִ֤יא עֲלֵי⁠כֶם֙ חֶ֔רֶב וְ⁠אִבַּדְתִּ֖י בָּמֽוֹתֵי⁠כֶֽם׃","wĕ⁠ʼá֣marĕţá̇֔ háréy֙ yişĕ̂ráʼé֔l şǐmĕʻ֖ẇ dĕ̇bar-ʼàdòná֣⁠y yĕhwi֑h kò̇h-ʼáma֣r ʼàdòná֣⁠y yĕ֠hwih le⁠hári֨ym wĕ⁠la⁠gĕ̇báʻ֜wòţ lá⁠ʼàpiyqi֣ym w⁠l⁠gʼyţ hinĕ⁠ni֨y ʼàni֜y mébi֤yʼ ʻàléy⁠kem֙ ẖe֔reb wĕ⁠ʼibȧdĕţi֖̇y bá̇mֽwòţéy⁠keֽm׃"],[6,4,"וְ⁠נָשַׁ֨מּוּ֙ מִזְבְּח֣וֹתֵי⁠כֶ֔ם וְ⁠נִשְׁבְּר֖וּ חַמָּֽנֵי⁠כֶ֑ם וְ⁠הִפַּלְתִּי֙ חַלְלֵי⁠כֶ֔ם לִ⁠פְנֵ֖י גִּלּוּלֵי⁠כֶֽם׃","wĕ⁠náşǎ֨ṁẇ֙ mizĕbĕ̇ẖ֣wòţéy⁠ke֔m wĕ⁠nişĕ̌bĕ̇r֖ẇ ẖamáֽ̇néy⁠ke֑m wĕ⁠hipȧlĕţi̇y֙ ẖalĕléy⁠ke֔m li⁠pĕné֖y gi̇l̇ẇléy⁠keֽm׃"],[6,5,"וְ⁠נָתַתִּ֗י אֶת־פִּגְרֵי֙ בְּנֵ֣י יִשְׂרָאֵ֔ל לִ⁠פְנֵ֖י גִּלּֽוּלֵי⁠הֶ֑ם וְ⁠זֵרִיתִי֙ אֶת־עַצְמ֣וֹתֵי⁠כֶ֔ם סְבִיב֖וֹת מִזְבְּחוֹתֵי⁠כֶֽם׃","wĕ⁠náţaţi̇֗y ʼeţ-pi̇gĕréy֙ bĕ̇né֣y yişĕ̂ráʼé֔l li⁠pĕné֖y gi̇lֽ̇ẇléy⁠he֑m wĕ⁠zériyţiy֙ ʼeţ-ʻaẕĕm֣wòţéy⁠ke֔m sĕbiyb֖wòţ mizĕbĕ̇ẖwòţéy⁠keֽm׃"],[6,6,"בְּ⁠כֹל֙ מוֹשְׁב֣וֹתֵי⁠כֶ֔ם הֶ⁠עָרִ֣ים תֶּחֱרַ֔בְנָה וְ⁠הַ⁠בָּמ֖וֹת תִּישָׁ֑מְנָה לְמַעַן֩ יֶחֶרְב֨וּ וְ⁠יֶאְשְׁמ֜וּ מִזְבְּחֽוֹתֵי⁠כֶ֗ם וְ⁠נִשְׁבְּר֤וּ וְ⁠נִשְׁבְּתוּ֙ גִּלּ֣וּלֵי⁠כֶ֔ם וְ⁠נִגְדְּעוּ֙ חַמָּ֣נֵי⁠כֶ֔ם וְ⁠נִמְח֖וּ מַעֲשֵׂי⁠כֶֽם׃","bĕ̇⁠kòl֙ mwòşĕ̌b֣wòţéy⁠ke֔m he⁠ʻári֣ym ţėẖèra֔bĕnáh wĕ⁠ha⁠bá̇m֖wòţ ţi̇yşá֑̌mĕnáh lĕmaʻan֩ yeẖerĕb֨ẇ wĕ⁠yeʼĕşĕ̌m֜ẇ mizĕbĕ̇ẖֽwòţéy⁠ke֗m wĕ⁠nişĕ̌bĕ̇r֤ẇ wĕ⁠nişĕ̌bĕ̇ţẇ֙ gi̇l֣̇ẇléy⁠ke֔m wĕ⁠nigĕdĕ̇ʻẇ֙ ẖamá֣̇néy⁠ke֔m wĕ⁠nimĕẖ֖ẇ maʻàşé̂y⁠keֽm׃"],[6,7,"וְ⁠נָפַ֥ל חָלָ֖ל בְּ⁠תֽוֹכְ⁠כֶ֑ם וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃","wĕ⁠nápa֥l ẖálá֖l bĕ̇⁠ţֽwòkĕ⁠ke֑m wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[6,8,"וְ⁠הוֹתַרְתִּ֗י בִּ⁠הְי֥וֹת לָ⁠כֶ֛ם פְּלִ֥יטֵי חֶ֖רֶב בַּ⁠גּוֹיִ֑ם בְּ⁠הִזָּרֽוֹתֵי⁠כֶ֖ם בָּ⁠אֲרָצֽוֹת׃","wĕ⁠hwòţarĕţi̇֗y bi̇⁠hĕy֥wòţ lá⁠ke֛m pĕ̇li֥ytéy ẖe֖reb bȧ⁠ġwòyi֑m bĕ̇⁠hizá̇rֽwòţéy⁠ke֖m bá̇⁠ʼàráẕֽwòţ׃"],[6,9,"וְ⁠זָכְר֨וּ פְלִֽיטֵי⁠כֶ֜ם אוֹתִ֗⁠י בַּ⁠גּוֹיִם֮ אֲשֶׁ֣ר נִשְׁבּוּ־שָׁם֒ אֲשֶׁ֨ר נִשְׁבַּ֜רְתִּי אֶת־לִבָּ֣⁠ם הַ⁠זּוֹנֶ֗ה אֲשֶׁר־סָר֙ מֵֽ⁠עָלַ֔⁠י וְ⁠אֵת֙ עֵֽינֵי⁠הֶ֔ם הַ⁠זֹּנ֕וֹת אַחֲרֵ֖י גִּלּֽוּלֵי⁠הֶ֑ם וְ⁠נָקֹ֨טּוּ֙ בִּ⁠פְנֵי⁠הֶ֔ם אֶל־הָֽ⁠רָעוֹת֙ אֲשֶׁ֣ר עָשׂ֔וּ לְ⁠כֹ֖ל תּוֹעֲבֹתֵי⁠הֶֽם׃","wĕ⁠zákĕr֨ẇ pĕliֽytéy⁠ke֜m ʼwòţi֗⁠y bȧ⁠ġwòyim֮ ʼàşě֣r nişĕ̌ḃẇ-şá̌m֒ ʼàşě֨r nişĕ̌bȧ֜rĕţi̇y ʼeţ-libá֣̇⁠m ha⁠żwòne֗h ʼàşěr-sár֙ méֽ⁠ʻála֔⁠y wĕ⁠ʼéţ֙ ʻéֽynéy⁠he֔m ha⁠zò̇n֕wòţ ʼaẖàré֖y gi̇lֽ̇ẇléy⁠he֑m wĕ⁠náqò֨ṫẇ֙ bi̇⁠pĕnéy⁠he֔m ʼel-háֽ⁠ráʻwòţ֙ ʼàşě֣r ʻáş̂֔ẇ lĕ⁠kò֖l ţ̇wòʻàbòţéy⁠heֽm׃"],[6,10,"וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֣י יְהוָ֑ה לֹ֤א אֶל־חִנָּם֙ דִּבַּ֔רְתִּי לַ⁠עֲשׂ֥וֹת לָ⁠הֶ֖ם הָ⁠רָעָ֥ה הַ⁠זֹּֽאת׃פ","wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֣y yĕhwá֑h lò֤ʼ ʼel-ẖiná̇m֙ di̇bȧ֔rĕţi̇y la⁠ʻàş֥̂wòţ lá⁠he֖m há⁠ráʻá֥h ha⁠zòֽ̇ʼţ׃p"],[6,11,"כֹּֽה־אָמַ֞ר אֲדֹנָ֣⁠י יְהוִ֗ה הַכֵּ֨ה בְ⁠כַפְּ⁠ךָ֜ וּ⁠רְקַ֤ע בְּ⁠רַגְלְ⁠ךָ֙ וֶֽ⁠אֱמָר־אָ֔ח אֶ֛ל כָּל־תּוֹעֲב֥וֹת רָע֖וֹת בֵּ֣ית יִשְׂרָאֵ֑ל אֲשֶׁ֗ר בַּ⁠חֶ֛רֶב בָּ⁠רָעָ֥ב וּ⁠בַ⁠דֶּ֖בֶר יִפֹּֽלוּ׃","kòֽ̇h-ʼáma֞r ʼàdòná֣⁠y yĕhwi֗h haké̇֨h bĕ⁠kapĕ̇⁠ká֜ ẇ⁠rĕqa֤ʻ bĕ̇⁠ragĕlĕ⁠ká֙ weֽ⁠ʼèmár-ʼá֔ẖ ʼe֛l ká̇l-ţ̇wòʻàb֥wòţ ráʻ֖wòţ bé֣̇yţ yişĕ̂ráʼé֑l ʼàşě֗r bȧ⁠ẖe֛reb bá̇⁠ráʻá֥b ẇ⁠ba⁠dė֖ber yipòֽ̇lẇ׃"],[6,12,"הָ⁠רָח֞וֹק בַּ⁠דֶּ֣בֶר יָמ֗וּת וְ⁠הַ⁠קָּרוֹב֙ בַּ⁠חֶ֣רֶב יִפּ֔וֹל וְ⁠הַ⁠נִּשְׁאָר֙ וְ⁠הַ⁠נָּצ֔וּר בָּ⁠רָעָ֖ב יָמ֑וּת וְ⁠כִלֵּיתִ֥י חֲמָתִ֖⁠י בָּֽ⁠ם׃","há⁠ráẖ֞wòq bȧ⁠dė֣ber yám֗ẇţ wĕ⁠ha⁠qá̇rwòb֙ bȧ⁠ẖe֣reb yiṗ֔wòl wĕ⁠ha⁠ni̇şĕ̌ʼár֙ wĕ⁠ha⁠ná̇ẕ֔ẇr bá̇⁠ráʻá֖b yám֑ẇţ wĕ⁠kilé̇yţi֥y ẖàmáţi֖⁠y báֽ̇⁠m׃"],[6,13,"וִֽ⁠ידַעְתֶּם֙ כִּֽי־אֲנִ֣י יְהוָ֔ה בִּֽ⁠הְי֣וֹת חַלְלֵי⁠הֶ֗ם בְּ⁠תוֹךְ֙ גִּלּ֣וּלֵי⁠הֶ֔ם סְבִיב֖וֹת מִזְבְּחֽוֹתֵי⁠הֶ֑ם אֶל֩ כָּל־גִּבְעָ֨ה רָמָ֜ה בְּ⁠כֹ֣ל ׀ רָאשֵׁ֣י הֶ⁠הָרִ֗ים וְ⁠תַ֨חַת כָּל־עֵ֤ץ רַֽעֲנָן֙ וְ⁠תַ֨חַת֙ כָּל־אֵלָ֣ה עֲבֻתָּ֔ה מְק֗וֹם אֲשֶׁ֤ר נָֽתְנוּ־שָׁם֙ רֵ֣יחַ נִיחֹ֔חַ לְ⁠כֹ֖ל גִּלּוּלֵי⁠הֶֽם׃","wiֽ⁠ydaʻĕţėm֙ kiֽ̇y-ʼàni֣y yĕhwá֔h biֽ̇⁠hĕy֣wòţ ẖalĕléy⁠he֗m bĕ̇⁠ţwòkĕ֙ gi̇l֣̇ẇléy⁠he֔m sĕbiyb֖wòţ mizĕbĕ̇ẖֽwòţéy⁠he֑m ʼel֩ ká̇l-gi̇bĕʻá֨h rámá֜h bĕ̇⁠kò֣l ׀ ráʼşé֣̌y he⁠hári֗ym wĕ⁠ţa֨ẖaţ ká̇l-ʻé֤ẕ raֽʻànán֙ wĕ⁠ţa֨ẖaţ֙ ká̇l-ʼélá֣h ʻàbuţá̇֔h mĕq֗wòm ʼàşě֤r náֽţĕnẇ-şá̌m֙ ré֣yẖa niyẖò֔ẖa lĕ⁠kò֖l gi̇l̇ẇléy⁠heֽm׃"],[6,14,"וְ⁠נָטִ֤יתִי אֶת־יָדִ⁠י֙ עֲלֵי⁠הֶ֔ם וְ⁠נָתַתִּ֨י אֶת־הָ⁠אָ֜רֶץ שְׁמָמָ֤ה וּ⁠מְשַׁמָּה֙ מִ⁠מִּדְבַּ֣ר דִּבְלָ֔תָ⁠ה בְּ⁠כֹ֖ל מוֹשְׁבֽוֹתֵי⁠הֶ֑ם וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃פ","wĕ⁠náti֤yţiy ʼeţ-yádi⁠y֙ ʻàléy⁠he֔m wĕ⁠náţaţi̇֨y ʼeţ-há⁠ʼá֜reẕ şĕ̌mámá֤h ẇ⁠mĕşǎmá̇h֙ mi⁠mi̇dĕbȧ֣r di̇bĕlá֔ţá⁠h bĕ̇⁠kò֖l mwòşĕ̌bֽwòţéy⁠he֑m wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃p"],[7,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[7,2,"וְ⁠אַתָּ֣ה בֶן־אָדָ֗ם כֹּה־אָמַ֞ר אֲדֹנָ֧⁠י יְהוִ֛ה לְ⁠אַדְמַ֥ת יִשְׂרָאֵ֖ל קֵ֑ץ בָּ֣א הַ⁠קֵּ֔ץ עַל־ארבעת כַּנְפ֥וֹת הָ⁠אָֽרֶץ׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֗m kò̇h-ʼáma֞r ʼàdòná֧⁠y yĕhwi֛h lĕ⁠ʼadĕma֥ţ yişĕ̂ráʼé֖l qé֑ẕ bá֣̇ʼ ha⁠qé̇֔ẕ ʻal-ʼrbʻţ kȧnĕp֥wòţ há⁠ʼáֽreẕ׃"],[7,3,"עַתָּה֙ הַ⁠קֵּ֣ץ עָלַ֔יִ⁠ךְ וְ⁠שִׁלַּחְתִּ֤י אַפִּ⁠י֙ בָּ֔⁠ךְ וּ⁠שְׁפַטְתִּ֖י⁠ךְ כִּ⁠דְרָכָ֑יִ⁠ךְ וְ⁠נָתַתִּ֣י עָלַ֔יִ⁠ךְ אֵ֖ת כָּל־תּוֹעֲבֹתָֽיִ⁠ךְ׃","ʻaţá̇h֙ ha⁠qé֣̇ẕ ʻála֔yi⁠kĕ wĕ⁠şǐlȧẖĕţi֤̇y ʼapi̇⁠y֙ bá̇֔⁠kĕ ẇ⁠şĕ̌patĕţi֖̇y⁠kĕ ki̇⁠dĕráká֑yi⁠kĕ wĕ⁠náţaţi֣̇y ʻála֔yi⁠kĕ ʼé֖ţ ká̇l-ţ̇wòʻàbòţáֽyi⁠kĕ׃"],[7,4,"וְ⁠לֹא־תָח֥וֹס עֵינִ֛⁠י עָלַ֖יִ⁠ךְ וְ⁠לֹ֣א אֶחְמ֑וֹל כִּ֣י דְרָכַ֜יִ⁠ךְ עָלַ֣יִ⁠ךְ אֶתֵּ֗ן וְ⁠תוֹעֲבוֹתַ֨יִ⁠ךְ֙ בְּ⁠תוֹכֵ֣⁠ךְ תִּֽהְיֶ֔יןָ וִ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃פ","wĕ⁠lòʼ-ţáẖ֥wòs ʻéyni֛⁠y ʻála֖yi⁠kĕ wĕ⁠lò֣ʼ ʼeẖĕm֑wòl ki֣̇y dĕráka֜yi⁠kĕ ʻála֣yi⁠kĕ ʼeţé̇֗n wĕ⁠ţwòʻàbwòţa֨yi⁠kĕ֙ bĕ̇⁠ţwòké֣⁠kĕ ţiֽ̇hĕye֔yná wi⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃p"],[7,5,"כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה רָעָ֛ה אַחַ֥ת רָעָ֖ה הִנֵּ֥ה בָאָֽה׃","kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h ráʻá֛h ʼaẖa֥ţ ráʻá֖h hiné֥̇h báʼáֽh׃"],[7,6,"קֵ֣ץ בָּ֔א בָּ֥א הַ⁠קֵּ֖ץ הֵקִ֣יץ אֵלָ֑יִ⁠ךְ הִנֵּ֖ה בָּאָֽה׃","qé֣ẕ bá̇֔ʼ bá֥̇ʼ ha⁠qé֖̇ẕ héqi֣yẕ ʼélá֑yi⁠kĕ hiné֖̇h bá̇ʼáֽh׃"],[7,7,"בָּ֧אָה הַ⁠צְּפִירָ֛ה אֵלֶ֖י⁠ךָ יוֹשֵׁ֣ב הָ⁠אָ֑רֶץ בָּ֣א הָ⁠עֵ֗ת קָר֛וֹב הַ⁠יּ֥וֹם מְהוּמָ֖ה וְ⁠לֹא־הֵ֥ד הָרִֽים׃","bá֧̇ʼáh ha⁠ẕĕ̇piyrá֛h ʼéle֖y⁠ká ywòşé֣̌b há⁠ʼá֑reẕ bá֣̇ʼ há⁠ʻé֗ţ qár֛wòb ha⁠ẏ֥wòm mĕhẇmá֖h wĕ⁠lòʼ-hé֥d háriֽym׃"],[7,8,"עַתָּ֣ה מִ⁠קָּר֗וֹב אֶשְׁפּ֤וֹךְ חֲמָתִ⁠י֙ עָלַ֔יִ⁠ךְ וְ⁠כִלֵּיתִ֤י אַפִּ⁠י֙ בָּ֔⁠ךְ וּ⁠שְׁפַטְתִּ֖י⁠ךְ כִּ⁠דְרָכָ֑יִ⁠ךְ וְ⁠נָתַתִּ֣י עָלַ֔יִ⁠ךְ אֵ֖ת כָּל־תּוֹעֲבוֹתָֽיִ⁠ךְ׃","ʻaţá֣̇h mi⁠qá̇r֗wòb ʼeşĕ̌ṗ֤wòkĕ ẖàmáţi⁠y֙ ʻála֔yi⁠kĕ wĕ⁠kilé̇yţi֤y ʼapi̇⁠y֙ bá̇֔⁠kĕ ẇ⁠şĕ̌patĕţi֖̇y⁠kĕ ki̇⁠dĕráká֑yi⁠kĕ wĕ⁠náţaţi֣̇y ʻála֔yi⁠kĕ ʼé֖ţ ká̇l-ţ̇wòʻàbwòţáֽyi⁠kĕ׃"],[7,9,"וְ⁠לֹא־תָח֥וֹס עֵינִ֖⁠י וְ⁠לֹ֣א אֶחְמ֑וֹל כִּ⁠דְרָכַ֜יִ⁠ךְ עָלַ֣יִ⁠ךְ אֶתֵּ֗ן וְ⁠תוֹעֲבוֹתַ֨יִ⁠ךְ֙ בְּ⁠תוֹכֵ֣⁠ךְ תִּֽהְיֶ֔יןָ וִֽ⁠ידַעְתֶּ֕ם כִּ֛י אֲנִ֥י יְהוָ֖ה מַכֶּֽה׃","wĕ⁠lòʼ-ţáẖ֥wòs ʻéyni֖⁠y wĕ⁠lò֣ʼ ʼeẖĕm֑wòl ki̇⁠dĕráka֜yi⁠kĕ ʻála֣yi⁠kĕ ʼeţé̇֗n wĕ⁠ţwòʻàbwòţa֨yi⁠kĕ֙ bĕ̇⁠ţwòké֣⁠kĕ ţiֽ̇hĕye֔yná wiֽ⁠ydaʻĕţė֕m ki֛̇y ʼàni֥y yĕhwá֖h makėֽh׃"],[7,10,"הִנֵּ֥ה הַ⁠יּ֖וֹם הִנֵּ֣ה בָאָ֑ה יָֽצְאָה֙ הַ⁠צְּפִרָ֔ה צָ֚ץ הַ⁠מַּטֶּ֔ה פָּרַ֖ח הַ⁠זָּדֽוֹן׃","hiné֥̇h ha⁠ẏ֖wòm hiné֣̇h báʼá֑h yáֽẕĕʼáh֙ ha⁠ẕĕ̇pirá֔h ẕá֚ẕ ha⁠mȧtė֔h pá̇ra֖ẖ ha⁠zá̇dֽwòn׃"],[7,11,"הֶ⁠חָמָ֥ס ׀ קָ֖ם לְ⁠מַטֵּה־רֶ֑שַׁע לֹא־מֵ⁠הֶ֞ם וְ⁠לֹ֧א מֵ⁠הֲמוֹנָ֛⁠ם וְ⁠לֹ֥א מֶ⁠הֱמֵ⁠הֶ֖ם וְ⁠לֹא־נֹ֥הַּ בָּ⁠הֶֽם׃","he⁠ẖámá֥s ׀ qá֖m lĕ⁠maté̇h-re֑şǎʻ lòʼ-mé⁠he֞m wĕ⁠lò֧ʼ mé⁠hàmwòná֛⁠m wĕ⁠lò֥ʼ me⁠hèmé⁠he֖m wĕ⁠lòʼ-nò֥hȧ bá̇⁠heֽm׃"],[7,12,"בָּ֤א הָ⁠עֵת֙ הִגִּ֣יעַ הַ⁠יּ֔וֹם הַ⁠קּוֹנֶה֙ אַל־יִשְׂמָ֔ח וְ⁠הַ⁠מּוֹכֵ֖ר אַל־יִתְאַבָּ֑ל כִּ֥י חָר֖וֹן אֶל־כָּל־הֲמוֹנָֽ⁠הּ׃","bá֤̇ʼ há⁠ʻéţ֙ higi֣̇yʻa ha⁠ẏ֔wòm ha⁠q̇wòneh֙ ʼal-yişĕ̂má֔ẖ wĕ⁠ha⁠ṁwòké֖r ʼal-yiţĕʼabá֑̇l ki֥̇y ẖár֖wòn ʼel-ká̇l-hàmwònáֽ⁠ḣ׃"],[7,13,"כִּ֣י הַ⁠מּוֹכֵ֗ר אֶל־הַ⁠מִּמְכָּר֙ לֹ֣א יָשׁ֔וּב וְ⁠ע֥וֹד בַּ⁠חַיִּ֖ים חַיָּתָ֑⁠ם כִּֽי־חָז֤וֹן אֶל־כָּל־הֲמוֹנָ⁠הּ֙ לֹ֣א יָשׁ֔וּב וְ⁠אִ֧ישׁ בַּ⁠עֲוֺנ֛⁠וֹ חַיָּת֖⁠וֹ לֹ֥א יִתְחַזָּֽקוּ׃","ki֣̇y ha⁠ṁwòké֗r ʼel-ha⁠mi̇mĕká̇r֙ lò֣ʼ yáş̌֔ẇb wĕ⁠ʻ֥wòd bȧ⁠ẖayi֖̇ym ẖayá̇ţá֑⁠m kiֽ̇y-ẖáz֤wòn ʼel-ká̇l-hàmwòná⁠ḣ֙ lò֣ʼ yáş̌֔ẇb wĕ⁠ʼi֧yş̌ bȧ⁠ʻàwֺn֛⁠wò ẖayá̇ţ֖⁠wò lò֥ʼ yiţĕẖazáֽ̇qẇ׃"],[7,14,"תָּקְע֤וּ בַ⁠תָּק֨וֹעַ֙ וְ⁠הָכִ֣ין הַ⁠כֹּ֔ל וְ⁠אֵ֥ין הֹלֵ֖ךְ לַ⁠מִּלְחָמָ֑ה כִּ֥י חֲרוֹנִ֖⁠י אֶל־כָּל־הֲמוֹנָֽ⁠הּ׃","ţá̇qĕʻ֤ẇ ba⁠ţá̇q֨wòʻa֙ wĕ⁠háki֣yn ha⁠kò̇֔l wĕ⁠ʼé֥yn hòlé֖kĕ la⁠mi̇lĕẖámá֑h ki֥̇y ẖàrwòni֖⁠y ʼel-ká̇l-hàmwònáֽ⁠ḣ׃"],[7,15,"הַ⁠חֶ֣רֶב בַּ⁠ח֔וּץ וְ⁠הַ⁠דֶּ֥בֶר וְ⁠הָ⁠רָעָ֖ב מִ⁠בָּ֑יִת אֲשֶׁ֤ר בַּ⁠שָּׂדֶה֙ בַּ⁠חֶ֣רֶב יָמ֔וּת וַ⁠אֲשֶׁ֣ר בָּ⁠עִ֔יר רָעָ֥ב וָ⁠דֶ֖בֶר יֹאכֲלֶֽ⁠נּוּ׃","ha⁠ẖe֣reb bȧ⁠ẖ֔ẇẕ wĕ⁠ha⁠dė֥ber wĕ⁠há⁠ráʻá֖b mi⁠bá֑̇yiţ ʼàşě֤r bȧ⁠şá̇̂deh֙ bȧ⁠ẖe֣reb yám֔ẇţ wa⁠ʼàşě֣r bá̇⁠ʻi֔yr ráʻá֥b wá⁠de֖ber yòʼkàleֽ⁠ṅẇ׃"],[7,16,"וּ⁠פָֽלְטוּ֙ פְּלִ֣יטֵי⁠הֶ֔ם וְ⁠הָי֣וּ אֶל־הֶ⁠הָרִ֗ים כְּ⁠יוֹנֵ֧י הַ⁠גֵּאָי֛וֹת כֻּלָּ֖⁠ם הֹמ֑וֹת אִ֖ישׁ בַּ⁠עֲוֺנֽ⁠וֹ׃","ẇ⁠páֽlĕtẇ֙ pĕ̇li֣ytéy⁠he֔m wĕ⁠háy֣ẇ ʼel-he⁠hári֗ym kĕ̇⁠ywòné֧y ha⁠gé̇ʼáy֛wòţ ku̇lá֖̇⁠m hòm֑wòţ ʼi֖yş̌ bȧ⁠ʻàwֺnֽ⁠wò׃"],[7,17,"כָּל־הַ⁠יָּדַ֖יִם תִּרְפֶּ֑ינָה וְ⁠כָל־בִּרְכַּ֖יִם תֵּלַ֥כְנָה מָּֽיִם׃","ká̇l-ha⁠yá̇da֖yim ţi̇rĕpė֑ynáh wĕ⁠kál-bi̇rĕkȧ֖yim ţé̇la֥kĕnáh máֽ̇yim׃"],[7,18,"וְ⁠חָגְר֣וּ שַׂקִּ֔ים וְ⁠כִסְּתָ֥ה אוֹתָ֖⁠ם פַּלָּצ֑וּת וְ⁠אֶ֤ל כָּל־פָּנִים֙ בּוּשָׁ֔ה וּ⁠בְ⁠כָל־רָאשֵׁי⁠הֶ֖ם קָרְחָֽה׃","wĕ⁠ẖágĕr֣ẇ şâqi̇֔ym wĕ⁠kisĕ̇ţá֥h ʼwòţá֖⁠m pȧlá̇ẕ֑ẇţ wĕ⁠ʼe֤l ká̇l-pá̇niym֙ ḃẇşá̌֔h ẇ⁠bĕ⁠kál-ráʼşé̌y⁠he֖m qárĕẖáֽh׃"],[7,19,"כַּסְפָּ֞⁠ם בַּ⁠חוּצ֣וֹת יַשְׁלִ֗יכוּ וּ⁠זְהָבָ⁠ם֮ לְ⁠נִדָּ֣ה יִֽהְיֶה֒ כַּסְפָּ֨⁠ם וּ⁠זְהָבָ֜⁠ם לֹֽא־יוּכַ֣ל לְ⁠הַצִּילָ֗⁠ם בְּ⁠יוֹם֙ עֶבְרַ֣ת יְהוָ֔ה נַפְשָׁ⁠ם֙ לֹ֣א יְשַׂבֵּ֔עוּ וּ⁠מֵעֵי⁠הֶ֖ם לֹ֣א יְמַלֵּ֑אוּ כִּֽי־מִכְשׁ֥וֹל עֲוֺנָ֖⁠ם הָיָֽה׃","kȧsĕpá̇֞⁠m bȧ⁠ẖẇẕ֣wòţ yaşĕ̌li֗ykẇ ẇ⁠zĕhábá⁠m֮ lĕ⁠nidá֣̇h yiֽhĕyeh֒ kȧsĕpá̇֨⁠m ẇ⁠zĕhábá֜⁠m lòֽʼ-yẇka֣l lĕ⁠haẕi̇ylá֗⁠m bĕ̇⁠ywòm֙ ʻebĕra֣ţ yĕhwá֔h napĕşá̌⁠m֙ lò֣ʼ yĕşâbé̇֔ʻẇ ẇ⁠méʻéy⁠he֖m lò֣ʼ yĕmalé֑̇ʼẇ kiֽ̇y-mikĕş֥̌wòl ʻàwֺná֖⁠m háyáֽh׃"],[7,20,"וּ⁠צְבִ֤י עֶדְי⁠וֹ֙ לְ⁠גָא֣וֹן שָׂמָ֔⁠הוּ וְ⁠צַלְמֵ֧י תוֹעֲבֹתָ֛⁠ם שִׁקּוּצֵי⁠הֶ֖ם עָ֣שׂוּ ב֑⁠וֹ עַל־כֵּ֛ן נְתַתִּ֥י⁠ו לָ⁠הֶ֖ם לְ⁠נִדָּֽה׃","ẇ⁠ẕĕbi֤y ʻedĕy⁠wò֙ lĕ⁠gáʼ֣wòn şá̂má֔⁠hẇ wĕ⁠ẕalĕmé֧y ţwòʻàbòţá֛⁠m şǐq̇ẇẕéy⁠he֖m ʻá֣ş̂ẇ b֑⁠wò ʻal-ké֛̇n nĕţaţi֥̇y⁠w lá⁠he֖m lĕ⁠nidáֽ̇h׃"],[7,21,"וּ⁠נְתַתִּ֤י⁠ו בְּ⁠יַֽד־הַ⁠זָּרִים֙ לָ⁠בַ֔ז וּ⁠לְ⁠רִשְׁעֵ֥י הָ⁠אָ֖רֶץ לְ⁠שָׁלָ֑ל ו⁠חלל⁠ה׃","ẇ⁠nĕţaţi֤̇y⁠w bĕ̇⁠yaֽd-ha⁠zá̇riym֙ lá⁠ba֔z ẇ⁠lĕ⁠rişĕ̌ʻé֥y há⁠ʼá֖reẕ lĕ⁠şá̌lá֑l w⁠ẖll⁠h׃"],[7,22,"וַ⁠הֲסִבּוֹתִ֤י פָנַ⁠י֙ מֵ⁠הֶ֔ם וְ⁠חִלְּל֖וּ אֶת־צְפוּנִ֑⁠י וּ⁠בָאוּ־בָ֥⁠הּ פָּרִיצִ֖ים וְ⁠חִלְּלֽוּ⁠הָ׃פ","wa⁠hàsiḃwòţi֤y pána⁠y֙ mé⁠he֔m wĕ⁠ẖilĕ̇l֖ẇ ʼeţ-ẕĕpẇni֑⁠y ẇ⁠báʼẇ-bá֥⁠ḣ pá̇riyẕi֖ym wĕ⁠ẖilĕ̇lֽẇ⁠há׃p"],[7,23,"עֲשֵׂ֖ה הָֽ⁠רַתּ֑וֹק כִּ֣י הָ⁠אָ֗רֶץ מָֽלְאָה֙ מִשְׁפַּ֣ט דָּמִ֔ים וְ⁠הָ⁠עִ֖יר מָלְאָ֥ה חָמָֽס׃","ʻàşé֖̂h háֽ⁠raţ֑̇wòq ki֣̇y há⁠ʼá֗reẕ máֽlĕʼáh֙ mişĕ̌pȧ֣t dá̇mi֔ym wĕ⁠há⁠ʻi֖yr málĕʼá֥h ẖámáֽs׃"],[7,24,"וְ⁠הֵֽבֵאתִי֙ רָעֵ֣י גוֹיִ֔ם וְ⁠יָרְשׁ֖וּ אֶת־בָּֽתֵּי⁠הֶ֑ם וְ⁠הִשְׁבַּתִּי֙ גְּא֣וֹן עַזִּ֔ים וְ⁠נִחֲל֖וּ מְקַֽדְשֵׁי⁠הֶֽם׃","wĕ⁠héֽbéʼţiy֙ ráʻé֣y gwòyi֔m wĕ⁠yárĕş֖̌ẇ ʼeţ-báֽ̇ţé̇y⁠he֑m wĕ⁠hişĕ̌bȧţi̇y֙ gĕ̇ʼ֣wòn ʻazi̇֔ym wĕ⁠niẖàl֖ẇ mĕqaֽdĕşé̌y⁠heֽm׃"],[7,25,"קְפָ֖דָה־בָ֑א וּ⁠בִקְשׁ֥וּ שָׁל֖וֹם וָ⁠אָֽיִן׃","qĕpá֖dáh-bá֑ʼ ẇ⁠biqĕş֥̌ẇ şá̌l֖wòm wá⁠ʼáֽyin׃"],[7,26,"הֹוָ֤ה עַל־הֹוָה֙ תָּב֔וֹא וּ⁠שְׁמֻעָ֥ה אֶל־שְׁמוּעָ֖ה תִּֽהְיֶ֑ה וּ⁠בִקְשׁ֤וּ חָזוֹן֙ מִ⁠נָּבִ֔יא וְ⁠תוֹרָה֙ תֹּאבַ֣ד מִ⁠כֹּהֵ֔ן וְ⁠עֵצָ֖ה מִ⁠זְּקֵנִֽים׃","hòwá֤h ʻal-hòwáh֙ ţá̇b֔wòʼ ẇ⁠şĕ̌muʻá֥h ʼel-şĕ̌mẇʻá֖h ţiֽ̇hĕye֑h ẇ⁠biqĕş֤̌ẇ ẖázwòn֙ mi⁠ná̇bi֔yʼ wĕ⁠ţwòráh֙ ţò̇ʼba֣d mi⁠kò̇hé֔n wĕ⁠ʻéẕá֖h mi⁠zĕ̇qéniֽym׃"],[7,27,"הַ⁠מֶּ֣לֶךְ יִתְאַבָּ֗ל וְ⁠נָשִׂיא֙ יִלְבַּ֣שׁ שְׁמָמָ֔ה וִ⁠ידֵ֥י עַם־הָ⁠אָ֖רֶץ תִּבָּהַ֑לְנָה מִ⁠דַּרְכָּ֞⁠ם אֶעֱשֶׂ֤ה אוֹתָ⁠ם֙ וּ⁠בְ⁠מִשְׁפְּטֵי⁠הֶ֣ם אֶשְׁפְּטֵ֔⁠ם וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃פ","ha⁠mė֣lekĕ yiţĕʼabá̇֗l wĕ⁠náşîyʼ֙ yilĕbȧ֣ş̌ şĕ̌mámá֔h wi⁠ydé֥y ʻam-há⁠ʼá֖reẕ ţi̇bá̇ha֑lĕnáh mi⁠dȧrĕká̇֞⁠m ʼeʻèşê֤h ʼwòţá⁠m֙ ẇ⁠bĕ⁠mişĕ̌pĕ̇téy⁠he֣m ʼeşĕ̌pĕ̇té֔⁠m wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃p"],[8,1,"וַ⁠יְהִ֣י ׀ בַּ⁠שָּׁנָ֣ה הַ⁠שִּׁשִּׁ֗ית בַּ⁠שִּׁשִּׁי֙ בַּ⁠חֲמִשָּׁ֣ה לַ⁠חֹ֔דֶשׁ אֲנִי֙ יוֹשֵׁ֣ב בְּ⁠בֵיתִ֔⁠י וְ⁠זִקְנֵ֥י יְהוּדָ֖ה יוֹשְׁבִ֣ים לְ⁠פָנָ֑⁠י וַ⁠תִּפֹּ֤ל עָלַ⁠י֙ שָׁ֔ם יַ֖ד אֲדֹנָ֥⁠י יְהֹוִֽה׃","wa⁠yĕhi֣y ׀ bȧ⁠şá̇̌ná֣h ha⁠şi̇̌şi̇̌֗yţ bȧ⁠şi̇̌şi̇̌y֙ bȧ⁠ẖàmişá֣̇̌h la⁠ẖò֔deş̌ ʼàniy֙ ywòşé֣̌b bĕ̇⁠béyţi֔⁠y wĕ⁠ziqĕné֥y yĕhẇdá֖h ywòşĕ̌bi֣ym lĕ⁠páná֑⁠y wa⁠ţi̇pò֤̇l ʻála⁠y֙ şá̌֔m ya֖d ʼàdòná֥⁠y yĕhòwiֽh׃"],[8,2,"וָ⁠אֶרְאֶ֗ה וְ⁠הִנֵּ֤ה דְמוּת֙ כְּ⁠מַרְאֵה־אֵ֔שׁ מִ⁠מַּרְאֵ֥ה מָתְנָ֛י⁠ו וּ⁠לְ⁠מַ֖טָּה אֵ֑שׁ וּ⁠מִ⁠מָּתְנָ֣י⁠ו וּ⁠לְ⁠מַ֔עְלָ⁠ה כְּ⁠מַרְאֵה־זֹ֖הַר כְּ⁠עֵ֥ין הַ⁠חַשְׁמַֽלָ⁠ה׃","wá⁠ʼerĕʼe֗h wĕ⁠hiné֤̇h dĕmẇţ֙ kĕ̇⁠marĕʼéh-ʼé֔ş̌ mi⁠mȧrĕʼé֥h máţĕná֛y⁠w ẇ⁠lĕ⁠ma֖tá̇h ʼé֑ş̌ ẇ⁠mi⁠má̇ţĕná֣y⁠w ẇ⁠lĕ⁠ma֔ʻĕlá⁠h kĕ̇⁠marĕʼéh-zò֖har kĕ̇⁠ʻé֥yn ha⁠ẖaşĕ̌maֽlá⁠h׃"],[8,3,"וַ⁠יִּשְׁלַח֙ תַּבְנִ֣ית יָ֔ד וַ⁠יִּקָּחֵ֖⁠נִי בְּ⁠צִיצִ֣ת רֹאשִׁ֑⁠י וַ⁠תִּשָּׂ֣א אֹתִ֣⁠י ר֣וּחַ ׀ בֵּֽין־הָ⁠אָ֣רֶץ וּ⁠בֵ֣ין הַ⁠שָּׁמַ֡יִם וַ⁠תָּבֵא֩ אֹתִ֨⁠י יְרוּשָׁלְַ֜מָ⁠ה בְּ⁠מַרְא֣וֹת אֱלֹהִ֗ים אֶל־פֶּ֜תַח שַׁ֤עַר הַ⁠פְּנִימִית֙ הַ⁠פּוֹנֶ֣ה צָפ֔וֹנָ⁠ה אֲשֶׁר־שָׁ֣ם מוֹשַׁ֔ב סֵ֖מֶל הַ⁠קִּנְאָ֥ה הַ⁠מַּקְנֶֽה׃","wa⁠yi̇şĕ̌laẖ֙ ţȧbĕni֣yţ yá֔d wa⁠yi̇qá̇ẖé֖⁠niy bĕ̇⁠ẕiyẕi֣ţ ròʼşǐ֑⁠y wa⁠ţi̇şá֣̇̂ʼ ʼòţi֣⁠y r֣ẇẖa ׀ béֽ̇yn-há⁠ʼá֣reẕ ẇ⁠bé֣yn ha⁠şá̇̌ma֡yim wa⁠ţá̇béʼ֩ ʼòţi֨⁠y yĕrẇşá̌lĕa֜má⁠h bĕ̇⁠marĕʼ֣wòţ ʼèlòhi֗ym ʼel-pė֜ţaẖ şǎ֤ʻar ha⁠pĕ̇niymiyţ֙ ha⁠ṗwòne֣h ẕáp֔wòná⁠h ʼàşěr-şá֣̌m mwòşǎ֔b sé֖mel ha⁠qi̇nĕʼá֥h ha⁠mȧqĕneֽh׃"],[8,4,"וְ⁠הִ֨נֵּה־שָׁ֔ם כְּב֖וֹד אֱלֹהֵ֣י יִשְׂרָאֵ֑ל כַּ⁠מַּרְאֶ֕ה אֲשֶׁ֥ר רָאִ֖יתִי בַּ⁠בִּקְעָֽה׃","wĕ⁠hi֨né̇h-şá̌֔m kĕ̇b֖wòd ʼèlòhé֣y yişĕ̂ráʼé֑l kȧ⁠mȧrĕʼe֕h ʼàşě֥r ráʼi֖yţiy bȧ⁠bi̇qĕʻáֽh׃"],[8,5,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י בֶּן־אָדָ֕ם שָׂא־נָ֥א עֵינֶ֖י⁠ךָ דֶּ֣רֶךְ צָפ֑וֹנָ⁠ה וָ⁠אֶשָּׂ֤א עֵינַ⁠י֙ דֶּ֣רֶךְ צָפ֔וֹנָ⁠ה וְ⁠הִנֵּ֤ה מִ⁠צָּפוֹן֙ לְ⁠שַׁ֣עַר הַ⁠מִּזְבֵּ֔חַ סֵ֛מֶל הַ⁠קִּנְאָ֥ה הַ⁠זֶּ֖ה בַּ⁠בִּאָֽה׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y bėn-ʼádá֕m şá̂ʼ-ná֥ʼ ʻéyne֖y⁠ká dė֣rekĕ ẕáp֑wòná⁠h wá⁠ʼeşá֤̇̂ʼ ʻéyna⁠y֙ dė֣rekĕ ẕáp֔wòná⁠h wĕ⁠hiné֤̇h mi⁠ẕá̇pwòn֙ lĕ⁠şǎ֣ʻar ha⁠mi̇zĕbé̇֔ẖa sé֛mel ha⁠qi̇nĕʼá֥h ha⁠zė֖h bȧ⁠bi̇ʼáֽh׃"],[8,6,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י בֶּן־אָדָ֕ם הֲ⁠רֹאֶ֥ה אַתָּ֖ה מ⁠הם עֹשִׂ֑ים תּוֹעֵב֨וֹת גְּדֹל֜וֹת אֲשֶׁ֥ר בֵּֽית־יִשְׂרָאֵ֣ל ׀ עֹשִׂ֣ים פֹּ֗ה לְ⁠רָֽחֳקָה֙ מֵ⁠עַ֣ל מִקְדָּשִׁ֔⁠י וְ⁠עוֹד֙ תָּשׁ֣וּב תִּרְאֶ֔ה תּוֹעֵב֖וֹת גְּדֹלֽוֹת׃ס","wa⁠yò֣̇ʼmer ʼéla֔⁠y bėn-ʼádá֕m hà⁠ròʼe֥h ʼaţá֖̇h m⁠hm ʻòşî֑ym ţ̇wòʻéb֨wòţ gĕ̇dòl֜wòţ ʼàşě֥r béֽ̇yţ-yişĕ̂ráʼé֣l ׀ ʻòşî֣ym pò̇֗h lĕ⁠ráֽẖoqáh֙ mé⁠ʻa֣l miqĕdá̇şǐ֔⁠y wĕ⁠ʻwòd֙ ţá̇ş֣̌ẇb ţi̇rĕʼe֔h ţ̇wòʻéb֖wòţ gĕ̇dòlֽwòţ׃s"],[8,7,"וַ⁠יָּבֵ֥א אֹתִ֖⁠י אֶל־פֶּ֣תַח הֶֽ⁠חָצֵ֑ר וָ⁠אֶרְאֶ֕ה וְ⁠הִנֵּ֥ה חֹר־אֶחָ֖ד בַּ⁠קִּֽיר׃","wa⁠yá̇bé֥ʼ ʼòţi֖⁠y ʼel-pė֣ţaẖ heֽ⁠ẖáẕé֑r wá⁠ʼerĕʼe֕h wĕ⁠hiné֥̇h ẖòr-ʼeẖá֖d bȧ⁠qiֽ̇yr׃"],[8,8,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י בֶּן־אָדָ֖ם חֲתָר־נָ֣א בַ⁠קִּ֑יר וָ⁠אֶחְתֹּ֣ר בַּ⁠קִּ֔יר וְ⁠הִנֵּ֖ה פֶּ֥תַח אֶחָֽד׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y bėn-ʼádá֖m ẖàţár-ná֣ʼ ba⁠qi֑̇yr wá⁠ʼeẖĕţò֣̇r bȧ⁠qi̇֔yr wĕ⁠hiné֖̇h pė֥ţaẖ ʼeẖáֽd׃"],[8,9,"וַ⁠יֹּ֖אמֶר אֵלָ֑⁠י בֹּ֤א וּ⁠רְאֵה֙ אֶת־הַ⁠תּוֹעֵב֣וֹת הָ⁠רָע֔וֹת אֲשֶׁ֛ר הֵ֥ם עֹשִׂ֖ים פֹּֽה׃","wa⁠yò֖̇ʼmer ʼélá֑⁠y bò֤̇ʼ ẇ⁠rĕʼéh֙ ʼeţ-ha⁠ţ̇wòʻéb֣wòţ há⁠ráʻ֔wòţ ʼàşě֛r hé֥m ʻòşî֖ym pòֽ̇h׃"],[8,10,"וָ⁠אָבוֹא֮ וָֽ⁠אֶרְאֶה֒ וְ⁠הִנֵּ֨ה כָל־תַּבְנִ֜ית רֶ֤מֶשׂ וּ⁠בְהֵמָה֙ שֶׁ֔קֶץ וְ⁠כָל־גִּלּוּלֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל מְחֻקֶּ֥ה עַל־הַ⁠קִּ֖יר סָבִ֥יב ׀ סָבִֽיב׃","wá⁠ʼábwòʼ֮ wáֽ⁠ʼerĕʼeh֒ wĕ⁠hiné̇֨h kál-ţȧbĕni֜yţ re֤meş̂ ẇ⁠bĕhémáh֙ şě֔qeẕ wĕ⁠kál-gi̇l̇ẇlé֖y bé֣̇yţ yişĕ̂ráʼé֑l mĕẖuqė֥h ʻal-ha⁠qi֖̇yr sábi֥yb ׀ sábiֽyb׃"],[8,11,"וְ⁠שִׁבְעִ֣ים אִ֣ישׁ מִ⁠זִּקְנֵ֣י בֵֽית־יִ֠שְׂרָאֵל וְ⁠יַאֲזַנְיָ֨הוּ בֶן־שָׁפָ֜ן עֹמֵ֤ד בְּ⁠תוֹכָ⁠ם֙ עֹמְדִ֣ים לִ⁠פְנֵי⁠הֶ֔ם וְ⁠אִ֥ישׁ מִקְטַרְתּ֖⁠וֹ בְּ⁠יָד֑⁠וֹ וַ⁠עֲתַ֥ר עֲנַֽן־הַ⁠קְּטֹ֖רֶת עֹלֶֽה׃","wĕ⁠şǐbĕʻi֣ym ʼi֣yş̌ mi⁠zi̇qĕné֣y béֽyţ-yi֠şĕ̂ráʼél wĕ⁠yaʼàzanĕyá֨hẇ ben-şá̌pá֜n ʻòmé֤d bĕ̇⁠ţwòká⁠m֙ ʻòmĕdi֣ym li⁠pĕnéy⁠he֔m wĕ⁠ʼi֥yş̌ miqĕtarĕţ֖̇⁠wò bĕ̇⁠yád֑⁠wò wa⁠ʻàţa֥r ʻànaֽn-ha⁠qĕ̇tò֖reţ ʻòleֽh׃"],[8,12,"וַ⁠יֹּ֣אמֶר אֵלַ⁠י֮ הֲ⁠רָאִ֣יתָ בֶן־אָדָם֒ אֲשֶׁ֨ר זִקְנֵ֤י בֵֽית־יִשְׂרָאֵל֙ עֹשִׂ֣ים בַּ⁠חֹ֔שֶׁךְ אִ֖ישׁ בְּ⁠חַדְרֵ֣י מַשְׂכִּית֑⁠וֹ כִּ֣י אֹמְרִ֗ים אֵ֤ין יְהוָה֙ רֹאֶ֣ה אֹתָ֔⁠נוּ עָזַ֥ב יְהוָ֖ה אֶת־הָ⁠אָֽרֶץ׃","wa⁠yò֣̇ʼmer ʼéla⁠y֮ hà⁠ráʼi֣yţá ben-ʼádám֒ ʼàşě֨r ziqĕné֤y béֽyţ-yişĕ̂ráʼél֙ ʻòşî֣ym bȧ⁠ẖò֔şěkĕ ʼi֖yş̌ bĕ̇⁠ẖadĕré֣y maşĕ̂ki̇yţ֑⁠wò ki֣̇y ʼòmĕri֗ym ʼé֤yn yĕhwáh֙ ròʼe֣h ʼòţá֔⁠nẇ ʻáza֥b yĕhwá֖h ʼeţ-há⁠ʼáֽreẕ׃"],[8,13,"וַ⁠יֹּ֖אמֶר אֵלָ֑⁠י ע֣וֹד תָּשׁ֥וּב תִּרְאֶ֛ה תּוֹעֵב֥וֹת גְּדֹל֖וֹת אֲשֶׁר־הֵ֥מָּה עֹשִֽׂים׃","wa⁠yò֖̇ʼmer ʼélá֑⁠y ʻ֣wòd ţá̇ş֥̌ẇb ţi̇rĕʼe֛h ţ̇wòʻéb֥wòţ gĕ̇dòl֖wòţ ʼàşěr-hé֥má̇h ʻòşîֽym׃"],[8,14,"וַ⁠יָּבֵ֣א אֹתִ֗⁠י אֶל־פֶּ֨תַח֙ שַׁ֣עַר בֵּית־יְהוָ֔ה אֲשֶׁ֖ר אֶל־הַ⁠צָּפ֑וֹנָ⁠ה וְ⁠הִנֵּה־שָׁם֙ הַ⁠נָּשִׁ֣ים יֹֽשְׁב֔וֹת מְבַכּ֖וֹת אֶת־הַ⁠תַּמּֽוּז׃ס","wa⁠yá̇bé֣ʼ ʼòţi֗⁠y ʼel-pė֨ţaẖ֙ şǎ֣ʻar bé̇yţ-yĕhwá֔h ʼàşě֖r ʼel-ha⁠ẕá̇p֑wòná⁠h wĕ⁠hiné̇h-şá̌m֙ ha⁠ná̇şǐ֣ym yòֽşĕ̌b֔wòţ mĕbak֖̇wòţ ʼeţ-ha⁠ţȧṁֽẇz׃s"],[8,15,"וַ⁠יֹּ֥אמֶר אֵלַ֖⁠י הֲ⁠רָאִ֣יתָ בֶן־אָדָ֑ם ע֣וֹד תָּשׁ֥וּב תִּרְאֶ֛ה תּוֹעֵב֥וֹת גְּדֹל֖וֹת מֵ⁠אֵֽלֶּה׃","wa⁠yò֥̇ʼmer ʼéla֖⁠y hà⁠ráʼi֣yţá ben-ʼádá֑m ʻ֣wòd ţá̇ş֥̌ẇb ţi̇rĕʼe֛h ţ̇wòʻéb֥wòţ gĕ̇dòl֖wòţ mé⁠ʼéֽlėh׃"],[8,16,"וַ⁠יָּבֵ֣א אֹתִ֗⁠י אֶל־חֲצַ֣ר בֵּית־יְהוָה֮ הַ⁠פְּנִימִית֒ וְ⁠הִנֵּה־פֶ֜תַח הֵיכַ֣ל יְהוָ֗ה בֵּ֤ין הָֽ⁠אוּלָם֙ וּ⁠בֵ֣ין הַ⁠מִּזְבֵּ֔חַ כְּ⁠עֶשְׂרִ֥ים וַ⁠חֲמִשָּׁ֖ה אִ֑ישׁ אֲחֹ֨רֵי⁠הֶ֜ם אֶל־הֵיכַ֤ל יְהוָה֙ וּ⁠פְנֵי⁠הֶ֣ם קֵ֔דְמָ⁠ה וְ⁠הֵ֛מָּה מִשְׁתַּחֲוִיתֶ֥ם קֵ֖דְמָ⁠ה לַ⁠שָּֽׁמֶשׁ׃","wa⁠yá̇bé֣ʼ ʼòţi֗⁠y ʼel-ẖàẕa֣r bé̇yţ-yĕhwáh֮ ha⁠pĕ̇niymiyţ֒ wĕ⁠hiné̇h-pe֜ţaẖ héyka֣l yĕhwá֗h bé֤̇yn háֽ⁠ʼẇlám֙ ẇ⁠bé֣yn ha⁠mi̇zĕbé̇֔ẖa kĕ̇⁠ʻeşĕ̂ri֥ym wa⁠ẖàmişá֖̇̌h ʼi֑yş̌ ʼàẖò֨réy⁠he֜m ʼel-héyka֤l yĕhwáh֙ ẇ⁠pĕnéy⁠he֣m qé֔dĕmá⁠h wĕ⁠hé֛má̇h mişĕ̌ţȧẖàwiyţe֥m qé֖dĕmá⁠h la⁠şáֽ̇̌meş̌׃"],[8,17,"וַ⁠יֹּ֣אמֶר אֵלַ⁠י֮ הֲ⁠רָאִ֣יתָ בֶן־אָדָם֒ הֲ⁠נָקֵל֙ לְ⁠בֵ֣ית יְהוּדָ֔ה מֵ⁠עֲשׂ֕וֹת אֶת־הַ⁠תּוֹעֵב֖וֹת אֲשֶׁ֣ר עָֽשׂוּ־פֹ֑ה כִּֽי־מָלְא֨וּ אֶת־הָ⁠אָ֜רֶץ חָמָ֗ס וַ⁠יָּשֻׁ֨בוּ֙ לְ⁠הַכְעִיסֵ֔⁠נִי וְ⁠הִנָּ֛⁠ם שֹׁלְחִ֥ים אֶת־הַ⁠זְּמוֹרָ֖ה אֶל־אַפָּֽ⁠ם׃","wa⁠yò֣̇ʼmer ʼéla⁠y֮ hà⁠ráʼi֣yţá ben-ʼádám֒ hà⁠náqél֙ lĕ⁠bé֣yţ yĕhẇdá֔h mé⁠ʻàş̂֕wòţ ʼeţ-ha⁠ţ̇wòʻéb֖wòţ ʼàşě֣r ʻáֽş̂ẇ-pò֑h kiֽ̇y-málĕʼ֨ẇ ʼeţ-há⁠ʼá֜reẕ ẖámá֗s wa⁠yá̇şǔ֨bẇ֙ lĕ⁠hakĕʻiysé֔⁠niy wĕ⁠hiná֛̇⁠m şò̌lĕẖi֥ym ʼeţ-ha⁠zĕ̇mwòrá֖h ʼel-ʼapáֽ̇⁠m׃"],[8,18,"וְ⁠גַם־אֲנִי֙ אֶעֱשֶׂ֣ה בְ⁠חֵמָ֔ה לֹֽא־תָח֥וֹס עֵינִ֖⁠י וְ⁠לֹ֣א אֶחְמֹ֑ל וְ⁠קָרְא֤וּ בְ⁠אָזְנַ⁠י֙ ק֣וֹל גָּד֔וֹל וְ⁠לֹ֥א אֶשְׁמַ֖ע אוֹתָֽ⁠ם׃","wĕ⁠gam-ʼàniy֙ ʼeʻèşê֣h bĕ⁠ẖémá֔h lòֽʼ-ţáẖ֥wòs ʻéyni֖⁠y wĕ⁠lò֣ʼ ʼeẖĕmò֑l wĕ⁠qárĕʼ֤ẇ bĕ⁠ʼázĕna⁠y֙ q֣wòl gá̇d֔wòl wĕ⁠lò֥ʼ ʼeşĕ̌ma֖ʻ ʼwòţáֽ⁠m׃"],[9,1,"וַ⁠יִּקְרָ֣א בְ⁠אָזְנַ֗⁠י ק֤וֹל גָּדוֹל֙ לֵ⁠אמֹ֔ר קָרְב֖וּ פְּקֻדּ֣וֹת הָ⁠עִ֑יר וְ⁠אִ֛ישׁ כְּלִ֥י מַשְׁחֵת֖⁠וֹ בְּ⁠יָדֽ⁠וֹ׃","wa⁠yi̇qĕrá֣ʼ bĕ⁠ʼázĕna֗⁠y q֤wòl gá̇dwòl֙ lé⁠ʼmò֔r qárĕb֖ẇ pĕ̇quḋ֣wòţ há⁠ʻi֑yr wĕ⁠ʼi֛yş̌ kĕ̇li֥y maşĕ̌ẖéţ֖⁠wò bĕ̇⁠yádֽ⁠wò׃"],[9,2,"וְ⁠הִנֵּ֣ה שִׁשָּׁ֣ה אֲנָשִׁ֡ים בָּאִ֣ים ׀ מִ⁠דֶּרֶךְ־שַׁ֨עַר הָ⁠עֶלְי֜וֹן אֲשֶׁ֣ר ׀ מָפְנֶ֣ה צָפ֗וֹנָ⁠ה וְ⁠אִ֨ישׁ כְּלִ֤י מַפָּצ⁠וֹ֙ בְּ⁠יָד֔⁠וֹ וְ⁠אִישׁ־אֶחָ֤ד בְּ⁠תוֹכָ⁠ם֙ לָבֻ֣שׁ בַּדִּ֔ים וְ⁠קֶ֥סֶת הַ⁠סֹּפֵ֖ר בְּ⁠מָתְנָ֑י⁠ו וַ⁠יָּבֹ֨אוּ֙ וַ⁠יַּ֣עַמְד֔וּ אֵ֖צֶל מִזְבַּ֥ח הַ⁠נְּחֹֽשֶׁת׃","wĕ⁠hiné֣̇h şǐşá֣̇̌h ʼànáşǐ֡ym bá̇ʼi֣ym ׀ mi⁠dėrekĕ-şǎ֨ʻar há⁠ʻelĕy֜wòn ʼàşě֣r ׀ mápĕne֣h ẕáp֗wòná⁠h wĕ⁠ʼi֨yş̌ kĕ̇li֤y mapá̇ẕ⁠wò֙ bĕ̇⁠yád֔⁠wò wĕ⁠ʼiyş̌-ʼeẖá֤d bĕ̇⁠ţwòká⁠m֙ lábu֣ş̌ bȧdi̇֔ym wĕ⁠qe֥seţ ha⁠sò̇pé֖r bĕ̇⁠máţĕná֑y⁠w wa⁠yá̇bò֨ʼẇ֙ wa⁠yȧ֣ʻamĕd֔ẇ ʼé֖ẕel mizĕbȧ֥ẖ ha⁠nĕ̇ẖòֽşěţ׃"],[9,3,"וּ⁠כְב֣וֹד ׀ אֱלֹהֵ֣י יִשְׂרָאֵ֗ל נַעֲלָה֙ מֵ⁠עַ֤ל הַ⁠כְּרוּב֙ אֲשֶׁ֣ר הָיָ֣ה עָלָ֔י⁠ו אֶ֖ל מִפְתַּ֣ן הַ⁠בָּ֑יִת וַ⁠יִּקְרָ֗א אֶל־הָ⁠אִישׁ֙ הַ⁠לָּבֻ֣שׁ הַ⁠בַּדִּ֔ים אֲשֶׁ֛ר קֶ֥סֶת הַ⁠סֹּפֵ֖ר בְּ⁠מָתְנָֽי⁠ו׃ס","ẇ⁠kĕb֣wòd ׀ ʼèlòhé֣y yişĕ̂ráʼé֗l naʻàláh֙ mé⁠ʻa֤l ha⁠kĕ̇rẇb֙ ʼàşě֣r háyá֣h ʻálá֔y⁠w ʼe֖l mipĕţȧ֣n ha⁠bá֑̇yiţ wa⁠yi̇qĕrá֗ʼ ʼel-há⁠ʼiyş̌֙ ha⁠lá̇bu֣ş̌ ha⁠bȧdi̇֔ym ʼàşě֛r qe֥seţ ha⁠sò̇pé֖r bĕ̇⁠máţĕnáֽy⁠w׃s"],[9,4,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אל⁠ו עֲבֹר֙ בְּ⁠ת֣וֹךְ הָ⁠עִ֔יר בְּ⁠ת֖וֹךְ יְרֽוּשָׁלִָ֑ם וְ⁠הִתְוִ֨יתָ תָּ֜ו עַל־מִצְח֣וֹת הָ⁠אֲנָשִׁ֗ים הַ⁠נֶּֽאֱנָחִים֙ וְ⁠הַ⁠נֶּ֣אֱנָקִ֔ים עַ֚ל כָּל־הַ⁠תּ֣וֹעֵב֔וֹת הַֽ⁠נַּעֲשׂ֖וֹת בְּ⁠תוֹכָֽ⁠הּ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼl⁠w ʻàbòr֙ bĕ̇⁠ţ֣wòkĕ há⁠ʻi֔yr bĕ̇⁠ţ֖wòkĕ yĕrֽẇşá̌liá֑m wĕ⁠hiţĕwi֨yţá ţá̇֜w ʻal-miẕĕẖ֣wòţ há⁠ʼànáşǐ֗ym ha⁠nėֽʼènáẖiym֙ wĕ⁠ha⁠nė֣ʼènáqi֔ym ʻa֚l ká̇l-ha⁠ţ֣̇wòʻéb֔wòţ haֽ⁠nȧʻàş֖̂wòţ bĕ̇⁠ţwòkáֽ⁠ḣ׃"],[9,5,"וּ⁠לְ⁠אֵ֨לֶּה֙ אָמַ֣ר בְּ⁠אָזְנַ֔⁠י עִבְר֥וּ בָ⁠עִ֛יר אַחֲרָ֖י⁠ו וְ⁠הַכּ֑וּ על־תָּחֹ֥ס עיני⁠כם וְ⁠אַל־תַּחְמֹֽלוּ׃","ẇ⁠lĕ⁠ʼé֨lėh֙ ʼáma֣r bĕ̇⁠ʼázĕna֔⁠y ʻibĕr֥ẇ bá⁠ʻi֛yr ʼaẖàrá֖y⁠w wĕ⁠hak֑̇ẇ ʻl-ţá̇ẖò֥s ʻyny⁠km wĕ⁠ʼal-ţȧẖĕmòֽlẇ׃"],[9,6,"זָקֵ֡ן בָּח֣וּר וּ⁠בְתוּלָה֩ וְ⁠טַ֨ף וְ⁠נָשִׁ֜ים תַּהַרְג֣וּ לְ⁠מַשְׁחִ֗ית וְ⁠עַל־כָּל־אִ֨ישׁ אֲשֶׁר־עָלָ֤י⁠ו הַ⁠תָּו֙ אַל־תִּגַּ֔שׁוּ וּ⁠מִ⁠מִּקְדָּשִׁ֖⁠י תָּחֵ֑לּוּ וַ⁠יָּחֵ֨לּוּ֙ בָּ⁠אֲנָשִׁ֣ים הַ⁠זְּקֵנִ֔ים אֲשֶׁ֖ר לִ⁠פְנֵ֥י הַ⁠בָּֽיִת׃","záqé֡n bá̇ẖ֣ẇr ẇ⁠bĕţẇláh֩ wĕ⁠ta֨p wĕ⁠náşǐ֜ym ţȧharĕg֣ẇ lĕ⁠maşĕ̌ẖi֗yţ wĕ⁠ʻal-ká̇l-ʼi֨yş̌ ʼàşěr-ʻálá֤y⁠w ha⁠ţá̇w֙ ʼal-ţi̇gȧ֔ş̌ẇ ẇ⁠mi⁠mi̇qĕdá̇şǐ֖⁠y ţá̇ẖé֑l̇ẇ wa⁠yá̇ẖé֨l̇ẇ֙ bá̇⁠ʼànáşǐ֣ym ha⁠zĕ̇qéni֔ym ʼàşě֖r li⁠pĕné֥y ha⁠báֽ̇yiţ׃"],[9,7,"וַ⁠יֹּ֨אמֶר אֲלֵי⁠הֶ֜ם טַמְּא֣וּ אֶת־הַ⁠בַּ֗יִת וּ⁠מַלְא֧וּ אֶת־הַ⁠חֲצֵר֛וֹת חֲלָלִ֖ים צֵ֑אוּ וְ⁠יָצְא֖וּ וְ⁠הִכּ֥וּ בָ⁠עִֽיר׃","wa⁠yò̇֨ʼmer ʼàléy⁠he֜m tamĕ̇ʼ֣ẇ ʼeţ-ha⁠bȧ֗yiţ ẇ⁠malĕʼ֧ẇ ʼeţ-ha⁠ẖàẕér֛wòţ ẖàláli֖ym ẕé֑ʼẇ wĕ⁠yáẕĕʼ֖ẇ wĕ⁠hik֥̇ẇ bá⁠ʻiֽyr׃"],[9,8,"וַֽ⁠יְהִי֙ כְּ⁠הַכּוֹתָ֔⁠ם וְ⁠נֵֽאשֲׁאַ֖ר אָ֑נִי וָ⁠אֶפְּלָ֨⁠ה עַל־פָּנַ֜⁠י וָ⁠אֶזְעַ֗ק וָֽ⁠אֹמַר֙ אֲהָהּ֙ אֲדֹנָ֣⁠י יְהוִ֔ה הֲ⁠מַשְׁחִ֣ית אַתָּ֗ה אֵ֚ת כָּל־שְׁאֵרִ֣ית יִשְׂרָאֵ֔ל בְּ⁠שָׁפְכְּ⁠ךָ֥ אֶת־חֲמָתְ⁠ךָ֖ עַל־יְרוּשָׁלִָֽם׃","waֽ⁠yĕhiy֙ kĕ̇⁠hak̇wòţá֔⁠m wĕ⁠néֽʼşà̌ʼa֖r ʼá֑niy wá⁠ʼepĕ̇lá֨⁠h ʻal-pá̇na֜⁠y wá⁠ʼezĕʻa֗q wáֽ⁠ʼòmar֙ ʼàháḣ֙ ʼàdòná֣⁠y yĕhwi֔h hà⁠maşĕ̌ẖi֣yţ ʼaţá̇֗h ʼé֚ţ ká̇l-şĕ̌ʼéri֣yţ yişĕ̂ráʼé֔l bĕ̇⁠şá̌pĕkĕ̇⁠ká֥ ʼeţ-ẖàmáţĕ⁠ká֖ ʻal-yĕrẇşá̌liáֽm׃"],[9,9,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י עֲוֺ֨ן בֵּֽית־יִשְׂרָאֵ֤ל וִֽ⁠יהוּדָה֙ גָּדוֹל֙ בִּ⁠מְאֹ֣ד מְאֹ֔ד וַ⁠תִּמָּלֵ֤א הָ⁠אָ֨רֶץ֙ דָּמִ֔ים וְ⁠הָ⁠עִ֖יר מָלְאָ֣ה מֻטֶּ֑ה כִּ֣י אָמְר֗וּ עָזַ֤ב יְהוָה֙ אֶת־הָ⁠אָ֔רֶץ וְ⁠אֵ֥ין יְהוָ֖ה רֹאֶֽה׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y ʻàwֺ֨n béֽ̇yţ-yişĕ̂ráʼé֤l wiֽ⁠yhẇdáh֙ gá̇dwòl֙ bi̇⁠mĕʼò֣d mĕʼò֔d wa⁠ţi̇má̇lé֤ʼ há⁠ʼá֨reẕ֙ dá̇mi֔ym wĕ⁠há⁠ʻi֖yr málĕʼá֣h mutė֑h ki֣̇y ʼámĕr֗ẇ ʻáza֤b yĕhwáh֙ ʼeţ-há⁠ʼá֔reẕ wĕ⁠ʼé֥yn yĕhwá֖h ròʼeֽh׃"],[9,10,"וְ⁠גַ֨ם־אֲנִ֔י לֹא־תָח֥וֹס עֵינִ֖⁠י וְ⁠לֹ֣א אֶחְמֹ֑ל דַּרְכָּ֖⁠ם בְּ⁠רֹאשָׁ֥⁠ם נָתָֽתִּי׃","wĕ⁠ga֨m-ʼàni֔y lòʼ-ţáẖ֥wòs ʻéyni֖⁠y wĕ⁠lò֣ʼ ʼeẖĕmò֑l dȧrĕká֖̇⁠m bĕ̇⁠ròʼşá֥̌⁠m náţáֽţi̇y׃"],[9,11,"וְ⁠הִנֵּ֞ה הָ⁠אִ֣ישׁ ׀ לְבֻ֣שׁ הַ⁠בַּדִּ֗ים אֲשֶׁ֤ר הַ⁠קֶּ֨סֶת֙ בְּ⁠מָתְנָ֔י⁠ו מֵשִׁ֥יב דָּבָ֖ר לֵ⁠אמֹ֑ר עָשִׂ֕יתִי כ⁠אשר צִוִּיתָֽ⁠נִי׃ס","wĕ⁠hiné̇֞h há⁠ʼi֣yş̌ ׀ lĕbu֣ş̌ ha⁠bȧdi̇֗ym ʼàşě֤r ha⁠qė֨seţ֙ bĕ̇⁠máţĕná֔y⁠w méşǐ֥yb dá̇bá֖r lé⁠ʼmò֑r ʻáşî֕yţiy k⁠ʼşr ẕiwi̇yţáֽ⁠niy׃s"],[10,1,"וָ⁠אֶרְאֶ֗ה וְ⁠הִנֵּ֤ה אֶל־הָ⁠רָקִ֨יעַ֙ אֲשֶׁר֙ עַל־רֹ֣אשׁ הַ⁠כְּרֻבִ֔ים כְּ⁠אֶ֣בֶן סַפִּ֔יר כְּ⁠מַרְאֵ֖ה דְּמ֣וּת כִּסֵּ֑א נִרְאָ֖ה עֲלֵי⁠הֶֽם׃","wá⁠ʼerĕʼe֗h wĕ⁠hiné֤̇h ʼel-há⁠ráqi֨yʻa֙ ʼàşěr֙ ʻal-rò֣ʼş̌ ha⁠kĕ̇rubi֔ym kĕ̇⁠ʼe֣ben sapi̇֔yr kĕ̇⁠marĕʼé֖h dĕ̇m֣ẇţ ki̇sé֑̇ʼ nirĕʼá֖h ʻàléy⁠heֽm׃"],[10,2,"וַ⁠יֹּ֜אמֶר אֶל־הָ⁠אִ֣ישׁ ׀ לְבֻ֣שׁ הַ⁠בַּדִּ֗ים וַ⁠יֹּ֡אמֶר בֹּא֩ אֶל־בֵּינ֨וֹת לַ⁠גַּלְגַּ֜ל אֶל־תַּ֣חַת לַ⁠כְּר֗וּב וּ⁠מַלֵּ֨א חָפְנֶ֤י⁠ךָ גַֽחֲלֵי־אֵשׁ֙ מִ⁠בֵּינ֣וֹת לַ⁠כְּרֻבִ֔ים וּ⁠זְרֹ֖ק עַל־הָ⁠עִ֑יר וַ⁠יָּבֹ֖א לְ⁠עֵינָֽ⁠י׃","wa⁠yò̇֜ʼmer ʼel-há⁠ʼi֣yş̌ ׀ lĕbu֣ş̌ ha⁠bȧdi̇֗ym wa⁠yò̇֡ʼmer bò̇ʼ֩ ʼel-bé̇yn֨wòţ la⁠gȧlĕgȧ֜l ʼel-ţȧ֣ẖaţ la⁠kĕ̇r֗ẇb ẇ⁠malé̇֨ʼ ẖápĕne֤y⁠ká gaֽẖàléy-ʼéş̌֙ mi⁠bé̇yn֣wòţ la⁠kĕ̇rubi֔ym ẇ⁠zĕrò֖q ʻal-há⁠ʻi֑yr wa⁠yá̇bò֖ʼ lĕ⁠ʻéynáֽ⁠y׃"],[10,3,"וְ⁠הַ⁠כְּרֻבִ֗ים עֹֽמְדִ֛ים מִ⁠ימִ֥ין לַ⁠בַּ֖יִת בְּ⁠בֹא֣⁠וֹ הָ⁠אִ֑ישׁ וְ⁠הֶ⁠עָנָ֣ן מָלֵ֔א אֶת־הֶ⁠חָצֵ֖ר הַ⁠פְּנִימִֽית׃","wĕ⁠ha⁠kĕ̇rubi֗ym ʻòֽmĕdi֛ym mi⁠ymi֥yn la⁠bȧ֖yiţ bĕ̇⁠bòʼ֣⁠wò há⁠ʼi֑yş̌ wĕ⁠he⁠ʻáná֣n málé֔ʼ ʼeţ-he⁠ẖáẕé֖r ha⁠pĕ̇niymiֽyţ׃"],[10,4,"וַ⁠יָּ֤רָם כְּבוֹד־יְהוָה֙ מֵ⁠עַ֣ל הַ⁠כְּר֔וּב עַ֖ל מִפְתַּ֣ן הַ⁠בָּ֑יִת וַ⁠יִּמָּלֵ֤א הַ⁠בַּ֨יִת֙ אֶת־הֶ֣⁠עָנָ֔ן וְ⁠הֶֽ⁠חָצֵר֙ מָֽלְאָ֔ה אֶת־נֹ֖גַהּ כְּב֥וֹד יְהוָֽה׃","wa⁠yá֤̇rám kĕ̇bwòd-yĕhwáh֙ mé⁠ʻa֣l ha⁠kĕ̇r֔ẇb ʻa֖l mipĕţȧ֣n ha⁠bá֑̇yiţ wa⁠yi̇má̇lé֤ʼ ha⁠bȧ֨yiţ֙ ʼeţ-he֣⁠ʻáná֔n wĕ⁠heֽ⁠ẖáẕér֙ máֽlĕʼá֔h ʼeţ-nò֖gaḣ kĕ̇b֥wòd yĕhwáֽh׃"],[10,5,"וְ⁠קוֹל֙ כַּנְפֵ֣י הַ⁠כְּרוּבִ֔ים נִשְׁמַ֕ע עַד־הֶ⁠חָצֵ֖ר הַ⁠חִיצֹנָ֑ה כְּ⁠ק֥וֹל אֵל־שַׁדַּ֖י בְּ⁠דַבְּרֽ⁠וֹ׃","wĕ⁠qwòl֙ kȧnĕpé֣y ha⁠kĕ̇rẇbi֔ym nişĕ̌ma֕ʻ ʻad-he⁠ẖáẕé֖r ha⁠ẖiyẕòná֑h kĕ̇⁠q֥wòl ʼél-şǎdȧ֖y bĕ̇⁠dabĕ̇rֽ⁠wò׃"],[10,6,"וַ⁠יְהִ֗י בְּ⁠צַוֺּת⁠וֹ֙ אֶת־הָ⁠אִ֤ישׁ לְבֻֽשׁ־הַ⁠בַּדִּים֙ לֵ⁠אמֹ֔ר קַ֥ח אֵשׁ֙ מִ⁠בֵּינ֣וֹת לַ⁠גַּלְגַּ֔ל מִ⁠בֵּינ֖וֹת לַ⁠כְּרוּבִ֑ים וַ⁠יָּבֹא֙ וַֽ⁠יַּעֲמֹ֔ד אֵ֖צֶל הָ⁠אוֹפָֽן׃","wa⁠yĕhi֗y bĕ̇⁠ẕaẇֺţ⁠wò֙ ʼeţ-há⁠ʼi֤yş̌ lĕbuֽş̌-ha⁠bȧdi̇ym֙ lé⁠ʼmò֔r qa֥ẖ ʼéş̌֙ mi⁠bé̇yn֣wòţ la⁠gȧlĕgȧ֔l mi⁠bé̇yn֖wòţ la⁠kĕ̇rẇbi֑ym wa⁠yá̇bòʼ֙ waֽ⁠yȧʻàmò֔d ʼé֖ẕel há⁠ʼwòpáֽn׃"],[10,7,"וַ⁠יִּשְׁלַח֩ הַ⁠כְּר֨וּב אֶת־יָד֜⁠וֹ מִ⁠בֵּינ֣וֹת לַ⁠כְּרוּבִ֗ים אֶל־הָ⁠אֵשׁ֙ אֲשֶׁר֙ בֵּינ֣וֹת הַ⁠כְּרֻבִ֔ים וַ⁠יִּשָּׂא֙ וַ⁠יִּתֵּ֔ן אֶל־חָפְנֵ֖י לְבֻ֣שׁ הַ⁠בַּדִּ֑ים וַ⁠יִּקַּ֖ח וַ⁠יֵּצֵֽא׃","wa⁠yi̇şĕ̌laẖ֩ ha⁠kĕ̇r֨ẇb ʼeţ-yád֜⁠wò mi⁠bé̇yn֣wòţ la⁠kĕ̇rẇbi֗ym ʼel-há⁠ʼéş̌֙ ʼàşěr֙ bé̇yn֣wòţ ha⁠kĕ̇rubi֔ym wa⁠yi̇şá̇̂ʼ֙ wa⁠yi̇ţé̇֔n ʼel-ẖápĕné֖y lĕbu֣ş̌ ha⁠bȧdi֑̇ym wa⁠yi̇qȧ֖ẖ wa⁠yé̇ẕéֽʼ׃"],[10,8,"וַ⁠יֵּרָ֖א לַ⁠כְּרֻבִ֑ים תַּבְנִית֙ יַד־אָדָ֔ם תַּ֖חַת כַּנְפֵי⁠הֶֽם׃","wa⁠yé̇rá֖ʼ la⁠kĕ̇rubi֑ym ţȧbĕniyţ֙ yad-ʼádá֔m ţȧ֖ẖaţ kȧnĕpéy⁠heֽm׃"],[10,9,"וָ⁠אֶרְאֶ֗ה וְ⁠הִנֵּ֨ה אַרְבָּעָ֣ה אוֹפַנִּים֮ אֵ֣צֶל הַ⁠כְּרוּבִים֒ אוֹפַ֣ן אֶחָ֗ד אֵ֚צֶל הַ⁠כְּר֣וּב אֶחָ֔ד וְ⁠אוֹפַ֣ן אֶחָ֔ד אֵ֖צֶל הַ⁠כְּר֣וּב אֶחָ֑ד וּ⁠מַרְאֵה֙ הָ⁠א֣וֹפַנִּ֔ים כְּ⁠עֵ֖ין אֶ֥בֶן תַּרְשִֽׁישׁ׃","wá⁠ʼerĕʼe֗h wĕ⁠hiné̇֨h ʼarĕbá̇ʻá֣h ʼwòpani̇ym֮ ʼé֣ẕel ha⁠kĕ̇rẇbiym֒ ʼwòpa֣n ʼeẖá֗d ʼé֚ẕel ha⁠kĕ̇r֣ẇb ʼeẖá֔d wĕ⁠ʼwòpa֣n ʼeẖá֔d ʼé֖ẕel ha⁠kĕ̇r֣ẇb ʼeẖá֑d ẇ⁠marĕʼéh֙ há⁠ʼ֣wòpani̇֔ym kĕ̇⁠ʻé֖yn ʼe֥ben ţȧrĕşǐֽyş̌׃"],[10,10,"וּ⁠מַ֨רְאֵי⁠הֶ֔ם דְּמ֥וּת אֶחָ֖ד לְ⁠אַרְבַּעְתָּ֑⁠ם כַּ⁠אֲשֶׁ֛ר יִהְיֶ֥ה הָ⁠אוֹפַ֖ן בְּ⁠ת֥וֹךְ הָ⁠אוֹפָֽן׃","ẇ⁠ma֨rĕʼéy⁠he֔m dĕ̇m֥ẇţ ʼeẖá֖d lĕ⁠ʼarĕbȧʻĕţá֑̇⁠m kȧ⁠ʼàşě֛r yihĕye֥h há⁠ʼwòpa֖n bĕ̇⁠ţ֥wòkĕ há⁠ʼwòpáֽn׃"],[10,11,"בְּ⁠לֶכְתָּ֗⁠ם אֶל־אַרְבַּ֤עַת רִבְעֵי⁠הֶם֙ יֵלֵ֔כוּ לֹ֥א יִסַּ֖בּוּ בְּ⁠לֶכְתָּ֑⁠ם כִּ֣י הַ⁠מָּק֞וֹם אֲשֶׁר־יִפְנֶ֤ה הָ⁠רֹאשׁ֙ אַחֲרָ֣י⁠ו יֵלֵ֔כוּ לֹ֥א יִסַּ֖בּוּ בְּ⁠לֶכְתָּֽ⁠ם׃","bĕ̇⁠lekĕţá̇֗⁠m ʼel-ʼarĕbȧ֤ʻaţ ribĕʻéy⁠hem֙ yélé֔kẇ lò֥ʼ yisȧ֖ḃẇ bĕ̇⁠lekĕţá֑̇⁠m ki֣̇y ha⁠má̇q֞wòm ʼàşěr-yipĕne֤h há⁠ròʼş̌֙ ʼaẖàrá֣y⁠w yélé֔kẇ lò֥ʼ yisȧ֖ḃẇ bĕ̇⁠lekĕţáֽ̇⁠m׃"],[10,12,"וְ⁠כָל־בְּשָׂרָ⁠ם֙ וְ⁠גַבֵּ⁠הֶ֔ם וִֽ⁠ידֵי⁠הֶ֖ם וְ⁠כַנְפֵי⁠הֶ֑ם וְ⁠הָ⁠אֽוֹפַנִּ֗ים מְלֵאִ֤ים עֵינַ֨יִם֙ סָבִ֔יב לְ⁠אַרְבַּעְתָּ֖⁠ם אוֹפַנֵּי⁠הֶֽם׃","wĕ⁠kál-bĕ̇şá̂rá⁠m֙ wĕ⁠gabé̇⁠he֔m wiֽ⁠ydéy⁠he֖m wĕ⁠kanĕpéy⁠he֑m wĕ⁠há⁠ʼֽwòpani̇֗ym mĕléʼi֤ym ʻéyna֨yim֙ sábi֔yb lĕ⁠ʼarĕbȧʻĕţá֖̇⁠m ʼwòpané̇y⁠heֽm׃"],[10,13,"לָ⁠א֖וֹפַנִּ֑ים לָ⁠הֶ֛ם קוֹרָ֥א הַ⁠גַּלְגַּ֖ל בְּ⁠אָזְנָֽ⁠י׃","lá⁠ʼ֖wòpani֑̇ym lá⁠he֛m qwòrá֥ʼ ha⁠gȧlĕgȧ֖l bĕ̇⁠ʼázĕnáֽ⁠y׃"],[10,14,"וְ⁠אַרְבָּעָ֥ה פָנִ֖ים לְ⁠אֶחָ֑ד פְּנֵ֨י הָ⁠אֶחָ֜ד פְּנֵ֣י הַ⁠כְּר֗וּב וּ⁠פְנֵ֤י הַ⁠שֵּׁנִי֙ פְּנֵ֣י אָדָ֔ם וְ⁠הַ⁠שְּׁלִישִׁי֙ פְּנֵ֣י אַרְיֵ֔ה וְ⁠הָ⁠רְבִיעִ֖י פְּנֵי־נָֽשֶׁר׃","wĕ⁠ʼarĕbá̇ʻá֥h páni֖ym lĕ⁠ʼeẖá֑d pĕ̇né֨y há⁠ʼeẖá֜d pĕ̇né֣y ha⁠kĕ̇r֗ẇb ẇ⁠pĕné֤y ha⁠şé̇̌niy֙ pĕ̇né֣y ʼádá֔m wĕ⁠ha⁠şĕ̇̌liyşǐy֙ pĕ̇né֣y ʼarĕyé֔h wĕ⁠há⁠rĕbiyʻi֖y pĕ̇néy-náֽşěr׃"],[10,15,"וַ⁠יֵּרֹ֖מּוּ הַ⁠כְּרוּבִ֑ים הִ֣יא הַ⁠חַיָּ֔ה אֲשֶׁ֥ר רָאִ֖יתִי בִּֽ⁠נְהַר־כְּבָֽר׃","wa⁠yé̇rò֖ṁẇ ha⁠kĕ̇rẇbi֑ym hi֣yʼ ha⁠ẖayá̇֔h ʼàşě֥r ráʼi֖yţiy biֽ̇⁠nĕhar-kĕ̇báֽr׃"],[10,16,"וּ⁠בְ⁠לֶ֨כֶת֙ הַ⁠כְּרוּבִ֔ים יֵלְכ֥וּ הָ⁠אוֹפַנִּ֖ים אֶצְלָ֑⁠ם וּ⁠בִ⁠שְׂאֵ֨ת הַ⁠כְּרוּבִ֜ים אֶת־כַּנְפֵי⁠הֶ֗ם לָ⁠רוּם֙ מֵ⁠עַ֣ל הָ⁠אָ֔רֶץ לֹא־יִסַּ֧בּוּ הָ⁠אוֹפַנִּ֛ים גַּם־הֵ֖ם מֵ⁠אֶצְלָֽ⁠ם׃","ẇ⁠bĕ⁠le֨keţ֙ ha⁠kĕ̇rẇbi֔ym yélĕk֥ẇ há⁠ʼwòpani֖̇ym ʼeẕĕlá֑⁠m ẇ⁠bi⁠şĕ̂ʼé֨ţ ha⁠kĕ̇rẇbi֜ym ʼeţ-kȧnĕpéy⁠he֗m lá⁠rẇm֙ mé⁠ʻa֣l há⁠ʼá֔reẕ lòʼ-yisȧ֧ḃẇ há⁠ʼwòpani֛̇ym gȧm-hé֖m mé⁠ʼeẕĕláֽ⁠m׃"],[10,17,"בְּ⁠עָמְדָ֣⁠ם יַעֲמֹ֔דוּ וּ⁠בְ⁠רוֹמָ֖⁠ם יֵר֣וֹמּוּ אוֹתָ֑⁠ם כִּ֛י ר֥וּחַ הַ⁠חַיָּ֖ה בָּ⁠הֶֽם׃","bĕ̇⁠ʻámĕdá֣⁠m yaʻàmò֔dẇ ẇ⁠bĕ⁠rwòmá֖⁠m yér֣wòṁẇ ʼwòţá֑⁠m ki֛̇y r֥ẇẖa ha⁠ẖayá֖̇h bá̇⁠heֽm׃"],[10,18,"וַ⁠יֵּצֵא֙ כְּב֣וֹד יְהוָ֔ה מֵ⁠עַ֖ל מִפְתַּ֣ן הַ⁠בָּ֑יִת וַֽ⁠יַּעֲמֹ֖ד עַל־הַ⁠כְּרוּבִֽים׃","wa⁠yé̇ẕéʼ֙ kĕ̇b֣wòd yĕhwá֔h mé⁠ʻa֖l mipĕţȧ֣n ha⁠bá֑̇yiţ waֽ⁠yȧʻàmò֖d ʻal-ha⁠kĕ̇rẇbiֽym׃"],[10,19,"וַ⁠יִּשְׂא֣וּ הַ⁠כְּרוּבִ֣ים אֶת־כַּ֠נְפֵי⁠הֶם וַ⁠יֵּר֨וֹמּוּ מִן־הָ⁠אָ֤רֶץ לְ⁠עֵינַ⁠י֙ בְּ⁠צֵאתָ֔⁠ם וְ⁠הָ⁠אֽוֹפַנִּ֖ים לְ⁠עֻמָּתָ֑⁠ם וַֽ⁠יַּעֲמֹ֗ד פֶּ֣תַח שַׁ֤עַר בֵּית־יְהוָה֙ הַ⁠קַּדְמוֹנִ֔י וּ⁠כְב֧וֹד אֱלֹהֵֽי־יִשְׂרָאֵ֛ל עֲלֵי⁠הֶ֖ם מִ⁠לְ⁠מָֽעְלָ⁠ה׃","wa⁠yi̇şĕ̂ʼ֣ẇ ha⁠kĕ̇rẇbi֣ym ʼeţ-kȧ֠nĕpéy⁠hem wa⁠yé̇r֨wòṁẇ min-há⁠ʼá֤reẕ lĕ⁠ʻéyna⁠y֙ bĕ̇⁠ẕéʼţá֔⁠m wĕ⁠há⁠ʼֽwòpani֖̇ym lĕ⁠ʻumá̇ţá֑⁠m waֽ⁠yȧʻàmò֗d pė֣ţaẖ şǎ֤ʻar bé̇yţ-yĕhwáh֙ ha⁠qȧdĕmwòni֔y ẇ⁠kĕb֧wòd ʼèlòhéֽy-yişĕ̂ráʼé֛l ʻàléy⁠he֖m mi⁠lĕ⁠máֽʻĕlá⁠h׃"],[10,20,"הִ֣יא הַ⁠חַיָּ֗ה אֲשֶׁ֥ר רָאִ֛יתִי תַּ֥חַת אֱלֹהֵֽי־יִשְׂרָאֵ֖ל בִּֽ⁠נְהַר־כְּבָ֑ר וָ⁠אֵדַ֕ע כִּ֥י כְרוּבִ֖ים הֵֽמָּה׃","hi֣yʼ ha⁠ẖayá̇֗h ʼàşě֥r ráʼi֛yţiy ţȧ֥ẖaţ ʼèlòhéֽy-yişĕ̂ráʼé֖l biֽ̇⁠nĕhar-kĕ̇bá֑r wá⁠ʼéda֕ʻ ki֥̇y kĕrẇbi֖ym héֽmá̇h׃"],[10,21,"אַרְבָּעָ֨ה אַרְבָּעָ֤ה פָנִים֙ לְ⁠אֶחָ֔ד וְ⁠אַרְבַּ֥ע כְּנָפַ֖יִם לְ⁠אֶחָ֑ד וּ⁠דְמוּת֙ יְדֵ֣י אָדָ֔ם תַּ֖חַת כַּנְפֵי⁠הֶֽם׃","ʼarĕbá̇ʻá֨h ʼarĕbá̇ʻá֤h pániym֙ lĕ⁠ʼeẖá֔d wĕ⁠ʼarĕbȧ֥ʻ kĕ̇nápa֖yim lĕ⁠ʼeẖá֑d ẇ⁠dĕmẇţ֙ yĕdé֣y ʼádá֔m ţȧ֖ẖaţ kȧnĕpéy⁠heֽm׃"],[10,22,"וּ⁠דְמ֣וּת פְּנֵי⁠הֶ֔ם הֵ֣מָּה הַ⁠פָּנִ֗ים אֲשֶׁ֤ר רָאִ֨יתִי֙ עַל־נְהַר־כְּבָ֔ר מַרְאֵי⁠הֶ֖ם וְ⁠אוֹתָ֑⁠ם אִ֛ישׁ אֶל־עֵ֥בֶר פָּנָ֖י⁠ו יֵלֵֽכוּ׃","ẇ⁠dĕm֣ẇţ pĕ̇néy⁠he֔m hé֣má̇h ha⁠pá̇ni֗ym ʼàşě֤r ráʼi֨yţiy֙ ʻal-nĕhar-kĕ̇bá֔r marĕʼéy⁠he֖m wĕ⁠ʼwòţá֑⁠m ʼi֛yş̌ ʼel-ʻé֥ber pá̇ná֖y⁠w yéléֽkẇ׃"],[11,1,"וַ⁠תִּשָּׂ֨א אֹתִ֜⁠י ר֗וּחַ וַ⁠תָּבֵ֣א אֹ֠תִ⁠י אֶל־שַׁ֨עַר בֵּית־יְהוָ֤ה הַ⁠קַּדְמוֹנִי֙ הַ⁠פּוֹנֶ֣ה קָדִ֔ימָ⁠ה וְ⁠הִנֵּה֙ בְּ⁠פֶ֣תַח הַ⁠שַּׁ֔עַר עֶשְׂרִ֥ים וַ⁠חֲמִשָּׁ֖ה אִ֑ישׁ וָ⁠אֶרְאֶ֨ה בְ⁠תוֹכָ֜⁠ם אֶת־יַאֲזַנְיָ֧ה בֶן־עַזֻּ֛ר וְ⁠אֶת־פְּלַטְיָ֥הוּ בֶן־בְּנָיָ֖הוּ שָׂרֵ֖י הָ⁠עָֽם׃פ","wa⁠ţi̇şá̇̂֨ʼ ʼòţi֜⁠y r֗ẇẖa wa⁠ţá̇bé֣ʼ ʼò֠ţi⁠y ʼel-şǎ֨ʻar bé̇yţ-yĕhwá֤h ha⁠qȧdĕmwòniy֙ ha⁠ṗwòne֣h qádi֔ymá⁠h wĕ⁠hiné̇h֙ bĕ̇⁠pe֣ţaẖ ha⁠şȧ̌֔ʻar ʻeşĕ̂ri֥ym wa⁠ẖàmişá֖̇̌h ʼi֑yş̌ wá⁠ʼerĕʼe֨h bĕ⁠ţwòká֜⁠m ʼeţ-yaʼàzanĕyá֧h ben-ʻazu֛̇r wĕ⁠ʼeţ-pĕ̇latĕyá֥hẇ ben-bĕ̇náyá֖hẇ şá̂ré֖y há⁠ʻáֽm׃p"],[11,2,"וַ⁠יֹּ֖אמֶר אֵלָ֑⁠י בֶּן־אָדָ֕ם אֵ֣לֶּה הָ⁠אֲנָשִׁ֞ים הַ⁠חֹשְׁבִ֥ים אָ֛וֶן וְ⁠הַ⁠יֹּעֲצִ֥ים עֲצַת־רָ֖ע בָּ⁠עִ֥יר הַ⁠זֹּֽאת׃","wa⁠yò֖̇ʼmer ʼélá֑⁠y bėn-ʼádá֕m ʼé֣lėh há⁠ʼànáşǐ֞ym ha⁠ẖòşĕ̌bi֥ym ʼá֛wen wĕ⁠ha⁠yò̇ʻàẕi֥ym ʻàẕaţ-rá֖ʻ bá̇⁠ʻi֥yr ha⁠zòֽ̇ʼţ׃"],[11,3,"הָ⁠אֹ֣מְרִ֔ים לֹ֥א בְ⁠קָר֖וֹב בְּנ֣וֹת בָּתִּ֑ים הִ֣יא הַ⁠סִּ֔יר וַ⁠אֲנַ֖חְנוּ הַ⁠בָּשָֽׂר׃","há⁠ʼò֣mĕri֔ym lò֥ʼ bĕ⁠qár֖wòb bĕ̇n֣wòţ bá̇ţi֑̇ym hi֣yʼ ha⁠si̇֔yr wa⁠ʼàna֖ẖĕnẇ ha⁠bá̇şáֽ̂r׃"],[11,4,"לָ⁠כֵ֖ן הִנָּבֵ֣א עֲלֵי⁠הֶ֑ם הִנָּבֵ֖א בֶּן־אָדָֽם׃","lá⁠ké֖n hiná̇bé֣ʼ ʻàléy⁠he֑m hiná̇bé֖ʼ bėn-ʼádáֽm׃"],[11,5,"וַ⁠תִּפֹּ֣ל עָלַ⁠י֮ ר֣וּחַ יְהוָה֒ וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י אֱמֹר֙ כֹּה־אָמַ֣ר יְהוָ֔ה כֵּ֥ן אֲמַרְתֶּ֖ם בֵּ֣ית יִשְׂרָאֵ֑ל וּ⁠מַעֲל֥וֹת רֽוּחֲ⁠כֶ֖ם אֲנִ֥י יְדַעְתִּֽי⁠הָ׃","wa⁠ţi̇pò֣̇l ʻála⁠y֮ r֣ẇẖa yĕhwáh֒ wa⁠yò֣̇ʼmer ʼéla֗⁠y ʼèmòr֙ kò̇h-ʼáma֣r yĕhwá֔h ké֥̇n ʼàmarĕţė֖m bé֣̇yţ yişĕ̂ráʼé֑l ẇ⁠maʻàl֥wòţ rֽẇẖà⁠ke֖m ʼàni֥y yĕdaʻĕţiֽ̇y⁠há׃"],[11,6,"הִרְבֵּיתֶ֥ם חַלְלֵי⁠כֶ֖ם בָּ⁠עִ֣יר הַ⁠זֹּ֑את וּ⁠מִלֵּאתֶ֥ם חוּצֹתֶ֖י⁠הָ חָלָֽל׃פ","hirĕbé̇yţe֥m ẖalĕléy⁠ke֖m bá̇⁠ʻi֣yr ha⁠zò֑̇ʼţ ẇ⁠milé̇ʼţe֥m ẖẇẕòţe֖y⁠há ẖáláֽl׃p"],[11,7,"לָ⁠כֵ֗ן כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ חַלְלֵי⁠כֶם֙ אֲשֶׁ֣ר שַׂמְתֶּ֣ם בְּ⁠תוֹכָ֔⁠הּ הֵ֥מָּה הַ⁠בָּשָׂ֖ר וְ⁠הִ֣יא הַ⁠סִּ֑יר וְ⁠אֶתְ⁠כֶ֖ם הוֹצִ֥יא מִ⁠תּוֹכָֽ⁠הּ׃","lá⁠ké֗n kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ ẖalĕléy⁠kem֙ ʼàşě֣r şâmĕţė֣m bĕ̇⁠ţwòká֔⁠ḣ hé֥má̇h ha⁠bá̇şá֖̂r wĕ⁠hi֣yʼ ha⁠si֑̇yr wĕ⁠ʼeţĕ⁠ke֖m hwòẕi֥yʼ mi⁠ţ̇wòkáֽ⁠ḣ׃"],[11,8,"חֶ֖רֶב יְרֵאתֶ֑ם וְ⁠חֶ֨רֶב֙ אָבִ֣יא עֲלֵי⁠כֶ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","ẖe֖reb yĕréʼţe֑m wĕ⁠ẖe֨reb֙ ʼábi֣yʼ ʻàléy⁠ke֔m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[11,9,"וְ⁠הוֹצֵאתִ֤י אֶתְ⁠כֶם֙ מִ⁠תּוֹכָ֔⁠הּ וְ⁠נָתַתִּ֥י אֶתְ⁠כֶ֖ם בְּ⁠יַד־זָרִ֑ים וְ⁠עָשִׂ֛יתִי בָ⁠כֶ֖ם שְׁפָטִֽים׃","wĕ⁠hwòẕéʼţi֤y ʼeţĕ⁠kem֙ mi⁠ţ̇wòká֔⁠ḣ wĕ⁠náţaţi֥̇y ʼeţĕ⁠ke֖m bĕ̇⁠yad-zári֑ym wĕ⁠ʻáşî֛yţiy bá⁠ke֖m şĕ̌pátiֽym׃"],[11,10,"בַּ⁠חֶ֣רֶב תִּפֹּ֔לוּ עַל־גְּב֥וּל יִשְׂרָאֵ֖ל אֶשְׁפּ֣וֹט אֶתְ⁠כֶ֑ם וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃","bȧ⁠ẖe֣reb ţi̇pò̇֔lẇ ʻal-gĕ̇b֥ẇl yişĕ̂ráʼé֖l ʼeşĕ̌ṗ֣wòt ʼeţĕ⁠ke֑m wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[11,11,"הִ֗יא לֹֽא־תִהְיֶ֤ה לָ⁠כֶם֙ לְ⁠סִ֔יר וְ⁠אַתֶּ֛ם תִּהְי֥וּ בְ⁠תוֹכָ֖⁠הּ לְ⁠בָשָׂ֑ר אֶל־גְּב֥וּל יִשְׂרָאֵ֖ל אֶשְׁפֹּ֥ט אֶתְ⁠כֶֽם׃","hi֗yʼ lòֽʼ-ţihĕye֤h lá⁠kem֙ lĕ⁠si֔yr wĕ⁠ʼaţė֛m ţi̇hĕy֥ẇ bĕ⁠ţwòká֖⁠ḣ lĕ⁠báşá֑̂r ʼel-gĕ̇b֥ẇl yişĕ̂ráʼé֖l ʼeşĕ̌pò֥̇t ʼeţĕ⁠keֽm׃"],[11,12,"וִֽ⁠ידַעְתֶּם֙ כִּֽי־אֲנִ֣י יְהוָ֔ה אֲשֶׁ֤ר בְּ⁠חֻקַּ⁠י֙ לֹ֣א הֲלַכְתֶּ֔ם וּ⁠מִשְׁפָּטַ֖⁠י לֹ֣א עֲשִׂיתֶ֑ם וּֽ⁠כְ⁠מִשְׁפְּטֵ֧י הַ⁠גּוֹיִ֛ם אֲשֶׁ֥ר סְבִיבוֹתֵי⁠כֶ֖ם עֲשִׂיתֶֽם׃","wiֽ⁠ydaʻĕţėm֙ kiֽ̇y-ʼàni֣y yĕhwá֔h ʼàşě֤r bĕ̇⁠ẖuqȧ⁠y֙ lò֣ʼ hàlakĕţė֔m ẇ⁠mişĕ̌pá̇ta֖⁠y lò֣ʼ ʻàşîyţe֑m ẇֽ⁠kĕ⁠mişĕ̌pĕ̇té֧y ha⁠ġwòyi֛m ʼàşě֥r sĕbiybwòţéy⁠ke֖m ʻàşîyţeֽm׃"],[11,13,"וַֽ⁠יְהִי֙ כְּ⁠הִנָּ֣בְאִ֔⁠י וּ⁠פְלַטְיָ֥הוּ בֶן־בְּנָיָ֖ה מֵ֑ת וָ⁠אֶפֹּ֨ל עַל־פָּנַ֜⁠י וָ⁠אֶזְעַ֣ק קוֹל־גָּד֗וֹל וָ⁠אֹמַר֙ אֲהָהּ֙ אֲדֹנָ֣⁠י יְהוִ֔ה כָּלָה֙ אַתָּ֣ה עֹשֶׂ֔ה אֵ֖ת שְׁאֵרִ֥ית יִשְׂרָאֵֽל׃פ","waֽ⁠yĕhiy֙ kĕ̇⁠hiná֣̇bĕʼi֔⁠y ẇ⁠pĕlatĕyá֥hẇ ben-bĕ̇náyá֖h mé֑ţ wá⁠ʼepò̇֨l ʻal-pá̇na֜⁠y wá⁠ʼezĕʻa֣q qwòl-gá̇d֗wòl wá⁠ʼòmar֙ ʼàháḣ֙ ʼàdòná֣⁠y yĕhwi֔h ká̇láh֙ ʼaţá֣̇h ʻòşê֔h ʼé֖ţ şĕ̌ʼéri֥yţ yişĕ̂ráʼéֽl׃p"],[11,14,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[11,15,"בֶּן־אָדָ֗ם אַחֶ֤י⁠ךָ אַחֶ֨י⁠ךָ֙ אַנְשֵׁ֣י גְאֻלָּתֶ֔⁠ךָ וְ⁠כָל־בֵּ֥ית יִשְׂרָאֵ֖ל כֻּלֹּ֑⁠ה אֲשֶׁר֩ אָמְר֨וּ לָ⁠הֶ֜ם יֹשְׁבֵ֣י יְרוּשָׁלִַ֗ם רַֽחֲקוּ֙ מֵ⁠עַ֣ל יְהוָ֔ה לָ֥⁠נוּ הִ֛יא נִתְּנָ֥ה הָ⁠אָ֖רֶץ לְ⁠מוֹרָשָֽׁה׃ס","bėn-ʼádá֗m ʼaẖe֤y⁠ká ʼaẖe֨y⁠ká֙ ʼanĕşé֣̌y gĕʼulá̇ţe֔⁠ká wĕ⁠kál-bé֥̇yţ yişĕ̂ráʼé֖l ku̇lò֑̇⁠h ʼàşěr֩ ʼámĕr֨ẇ lá⁠he֜m yòşĕ̌bé֣y yĕrẇşá̌lia֗m raֽẖàqẇ֙ mé⁠ʻa֣l yĕhwá֔h lá֥⁠nẇ hi֛yʼ niţĕ̇ná֥h há⁠ʼá֖reẕ lĕ⁠mwòráşáֽ̌h׃s"],[11,16,"לָ⁠כֵ֣ן אֱמֹ֗ר כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ כִּ֤י הִרְחַקְתִּי⁠ם֙ בַּ⁠גּוֹיִ֔ם וְ⁠כִ֥י הֲפִֽיצוֹתִ֖י⁠ם בָּ⁠אֲרָצ֑וֹת וָ⁠אֱהִ֤י לָ⁠הֶם֙ לְ⁠מִקְדָּ֣שׁ מְעַ֔ט בָּ⁠אֲרָצ֖וֹת אֲשֶׁר־בָּ֥אוּ שָֽׁם׃ס","lá⁠ké֣n ʼèmò֗r kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ ki֤̇y hirĕẖaqĕţi̇y⁠m֙ bȧ⁠ġwòyi֔m wĕ⁠ki֥y hàpiֽyẕwòţi֖y⁠m bá̇⁠ʼàráẕ֑wòţ wá⁠ʼèhi֤y lá⁠hem֙ lĕ⁠miqĕdá֣̇ş̌ mĕʻa֔t bá̇⁠ʼàráẕ֖wòţ ʼàşěr-bá֥̇ʼẇ şáֽ̌m׃s"],[11,17,"לָ⁠כֵ֣ן אֱמֹ֗ר כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ וְ⁠קִבַּצְתִּ֤י אֶתְ⁠כֶם֙ מִן־הָ֣⁠עַמִּ֔ים וְ⁠אָסַפְתִּ֣י אֶתְ⁠כֶ֔ם מִן־הָ֣⁠אֲרָצ֔וֹת אֲשֶׁ֥ר נְפֹצוֹתֶ֖ם בָּ⁠הֶ֑ם וְ⁠נָתַתִּ֥י לָ⁠כֶ֖ם אֶת־אַדְמַ֥ת יִשְׂרָאֵֽל׃","lá⁠ké֣n ʼèmò֗r kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ wĕ⁠qibȧẕĕţi֤̇y ʼeţĕ⁠kem֙ min-há֣⁠ʻami̇֔ym wĕ⁠ʼásapĕţi֣̇y ʼeţĕ⁠ke֔m min-há֣⁠ʼàráẕ֔wòţ ʼàşě֥r nĕpòẕwòţe֖m bá̇⁠he֑m wĕ⁠náţaţi֥̇y lá⁠ke֖m ʼeţ-ʼadĕma֥ţ yişĕ̂ráʼéֽl׃"],[11,18,"וּ⁠בָ֖אוּ־שָׁ֑מָּ⁠ה וְ⁠הֵסִ֜ירוּ אֶת־כָּל־שִׁקּוּצֶ֛י⁠הָ וְ⁠אֶת־כָּל־תּוֹעֲבוֹתֶ֖י⁠הָ מִמֶּֽ⁠נָּה׃","ẇ⁠bá֖ʼẇ-şá֑̌má̇⁠h wĕ⁠hési֜yrẇ ʼeţ-ká̇l-şǐq̇ẇẕe֛y⁠há wĕ⁠ʼeţ-ká̇l-ţ̇wòʻàbwòţe֖y⁠há mimėֽ⁠ná̇h׃"],[11,19,"וְ⁠נָתַתִּ֤י לָ⁠הֶם֙ לֵ֣ב אֶחָ֔ד וְ⁠ר֥וּחַ חֲדָשָׁ֖ה אֶתֵּ֣ן בְּ⁠קִרְבְּ⁠כֶ֑ם וַ⁠הֲסִ֨רֹתִ֜י לֵ֤ב הָ⁠אֶ֨בֶן֙ מִ⁠בְּשָׂרָ֔⁠ם וְ⁠נָתַתִּ֥י לָ⁠הֶ֖ם לֵ֥ב בָּשָֽׂר׃","wĕ⁠náţaţi֤̇y lá⁠hem֙ lé֣b ʼeẖá֔d wĕ⁠r֥ẇẖa ẖàdáşá֖̌h ʼeţé֣̇n bĕ̇⁠qirĕbĕ̇⁠ke֑m wa⁠hàsi֨ròţi֜y lé֤b há⁠ʼe֨ben֙ mi⁠bĕ̇şá̂rá֔⁠m wĕ⁠náţaţi֥̇y lá⁠he֖m lé֥b bá̇şáֽ̂r׃"],[11,20,"לְמַ֨עַן֙ בְּ⁠חֻקֹּתַ֣⁠י יֵלֵ֔כוּ וְ⁠אֶת־מִשְׁפָּטַ֥⁠י יִשְׁמְר֖וּ וְ⁠עָשׂ֣וּ אֹתָ֑⁠ם וְ⁠הָיוּ־לִ֣⁠י לְ⁠עָ֔ם וַ⁠אֲנִ֕י אֶהְיֶ֥ה לָ⁠הֶ֖ם לֵ⁠אלֹהִֽים׃","lĕma֨ʻan֙ bĕ̇⁠ẖuqò̇ţa֣⁠y yélé֔kẇ wĕ⁠ʼeţ-mişĕ̌pá̇ta֥⁠y yişĕ̌mĕr֖ẇ wĕ⁠ʻáş֣̂ẇ ʼòţá֑⁠m wĕ⁠háyẇ-li֣⁠y lĕ⁠ʻá֔m wa⁠ʼàni֕y ʼehĕye֥h lá⁠he֖m lé⁠ʼlòhiֽym׃"],[11,21,"וְ⁠אֶל־לֵ֧ב שִׁקּוּצֵי⁠הֶ֛ם וְ⁠תוֹעֲבוֹתֵי⁠הֶ֖ם לִבָּ֣⁠ם הֹלֵ֑ךְ דַּרְכָּ⁠ם֙ בְּ⁠רֹאשָׁ֣⁠ם נָתַ֔תִּי נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wĕ⁠ʼel-lé֧b şǐq̇ẇẕéy⁠he֛m wĕ⁠ţwòʻàbwòţéy⁠he֖m libá֣̇⁠m hòlé֑kĕ dȧrĕká̇⁠m֙ bĕ̇⁠ròʼşá֣̌⁠m náţa֔ţi̇y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[11,22,"וַ⁠יִּשְׂא֤וּ הַ⁠כְּרוּבִים֙ אֶת־כַּנְפֵי⁠הֶ֔ם וְ⁠הָ⁠אֽוֹפַנִּ֖ים לְ⁠עֻמָּתָ֑⁠ם וּ⁠כְב֧וֹד אֱלֹהֵֽי־יִשְׂרָאֵ֛ל עֲלֵי⁠הֶ֖ם מִ⁠לְ⁠מָֽעְלָ⁠ה׃","wa⁠yi̇şĕ̂ʼ֤ẇ ha⁠kĕ̇rẇbiym֙ ʼeţ-kȧnĕpéy⁠he֔m wĕ⁠há⁠ʼֽwòpani֖̇ym lĕ⁠ʻumá̇ţá֑⁠m ẇ⁠kĕb֧wòd ʼèlòhéֽy-yişĕ̂ráʼé֛l ʻàléy⁠he֖m mi⁠lĕ⁠máֽʻĕlá⁠h׃"],[11,23,"וַ⁠יַּ֨עַל֙ כְּב֣וֹד יְהוָ֔ה מֵ⁠עַ֖ל תּ֣וֹךְ הָ⁠עִ֑יר וַֽ⁠יַּעֲמֹד֙ עַל־הָ⁠הָ֔ר אֲשֶׁ֖ר מִ⁠קֶּ֥דֶם לָ⁠עִֽיר׃","wa⁠yȧ֨ʻal֙ kĕ̇b֣wòd yĕhwá֔h mé⁠ʻa֖l ţ֣̇wòkĕ há⁠ʻi֑yr waֽ⁠yȧʻàmòd֙ ʻal-há⁠há֔r ʼàşě֖r mi⁠qė֥dem lá⁠ʻiֽyr׃"],[11,24,"וְ⁠ר֣וּחַ נְשָׂאַ֗תְ⁠נִי וַ⁠תְּבִיאֵ֤⁠נִי כַשְׂדִּ֨ימָ⁠ה֙ אֶל־הַ⁠גּוֹלָ֔ה בַּ⁠מַּרְאֶ֖ה בְּ⁠ר֣וּחַ אֱלֹהִ֑ים וַ⁠יַּ֨עַל֙ מֵֽ⁠עָלַ֔⁠י הַ⁠מַּרְאֶ֖ה אֲשֶׁ֥ר רָאִֽיתִי׃","wĕ⁠r֣ẇẖa nĕşá̂ʼa֗ţĕ⁠niy wa⁠ţĕ̇biyʼé֤⁠niy kaşĕ̂di̇֨ymá⁠h֙ ʼel-ha⁠ġwòlá֔h bȧ⁠mȧrĕʼe֖h bĕ̇⁠r֣ẇẖa ʼèlòhi֑ym wa⁠yȧ֨ʻal֙ méֽ⁠ʻála֔⁠y ha⁠mȧrĕʼe֖h ʼàşě֥r ráʼiֽyţiy׃"],[11,25,"וָ⁠אֲדַבֵּ֖ר אֶל־הַ⁠גּוֹלָ֑ה אֵ֛ת כָּל־דִּבְרֵ֥י יְהוָ֖ה אֲשֶׁ֥ר הֶרְאָֽ⁠נִי׃פ","wá⁠ʼàdabé֖̇r ʼel-ha⁠ġwòlá֑h ʼé֛ţ ká̇l-di̇bĕré֥y yĕhwá֖h ʼàşě֥r herĕʼáֽ⁠niy׃p"],[12,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[12,2,"בֶּן־אָדָ֕ם בְּ⁠ת֥וֹךְ בֵּית־הַ⁠מֶּ֖רִי אַתָּ֣ה יֹשֵׁ֑ב אֲשֶׁ֣ר עֵינַיִם֩ לָ⁠הֶ֨ם לִ⁠רְא֜וֹת וְ⁠לֹ֣א רָא֗וּ אָזְנַ֨יִם לָ⁠הֶ֤ם לִ⁠שְׁמֹ֨עַ֙ וְ⁠לֹ֣א שָׁמֵ֔עוּ כִּ֛י בֵּ֥ית מְרִ֖י הֵֽם׃","bėn-ʼádá֕m bĕ̇⁠ţ֥wòkĕ bé̇yţ-ha⁠mė֖riy ʼaţá֣̇h yòşé֑̌b ʼàşě֣r ʻéynayim֩ lá⁠he֨m li⁠rĕʼ֜wòţ wĕ⁠lò֣ʼ ráʼ֗ẇ ʼázĕna֨yim lá⁠he֤m li⁠şĕ̌mò֨ʻa֙ wĕ⁠lò֣ʼ şá̌mé֔ʻẇ ki֛̇y bé֥̇yţ mĕri֖y héֽm׃"],[12,3,"וְ⁠אַתָּ֣ה בֶן־אָדָ֗ם עֲשֵׂ֤ה לְ⁠ךָ֙ כְּלֵ֣י גוֹלָ֔ה וּ⁠גְלֵ֥ה יוֹמָ֖ם לְ⁠עֵֽינֵי⁠הֶ֑ם וְ⁠גָלִ֨יתָ מִ⁠מְּקוֹמְ⁠ךָ֜ אֶל־מָק֤וֹם אַחֵר֙ לְ⁠עֵ֣ינֵי⁠הֶ֔ם אוּלַ֣י יִרְא֔וּ כִּ֛י בֵּ֥ית מְרִ֖י הֵֽמָּה׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֗m ʻàşé֤̂h lĕ⁠ká֙ kĕ̇lé֣y gwòlá֔h ẇ⁠gĕlé֥h ywòmá֖m lĕ⁠ʻéֽynéy⁠he֑m wĕ⁠gáli֨yţá mi⁠mĕ̇qwòmĕ⁠ká֜ ʼel-máq֤wòm ʼaẖér֙ lĕ⁠ʻé֣ynéy⁠he֔m ʼẇla֣y yirĕʼ֔ẇ ki֛̇y bé֥̇yţ mĕri֖y héֽmá̇h׃"],[12,4,"וְ⁠הוֹצֵאתָ֨ כֵלֶ֜י⁠ךָ כִּ⁠כְלֵ֥י גוֹלָ֛ה יוֹמָ֖ם לְ⁠עֵֽינֵי⁠הֶ֑ם וְ⁠אַתָּ֗ה תֵּצֵ֤א בָ⁠עֶ֨רֶב֙ לְ⁠עֵ֣ינֵי⁠הֶ֔ם כְּ⁠מוֹצָאֵ֖י גּוֹלָֽה׃","wĕ⁠hwòẕéʼţá֨ kéle֜y⁠ká ki̇⁠kĕlé֥y gwòlá֛h ywòmá֖m lĕ⁠ʻéֽynéy⁠he֑m wĕ⁠ʼaţá̇֗h ţé̇ẕé֤ʼ bá⁠ʻe֨reb֙ lĕ⁠ʻé֣ynéy⁠he֔m kĕ̇⁠mwòẕáʼé֖y ġwòláֽh׃"],[12,5,"לְ⁠עֵינֵי⁠הֶ֖ם חֲתָר־לְ⁠ךָ֣ בַ⁠קִּ֑יר וְ⁠הוֹצֵאתָ֖ בּֽ⁠וֹ׃","lĕ⁠ʻéynéy⁠he֖m ẖàţár-lĕ⁠ká֣ ba⁠qi֑̇yr wĕ⁠hwòẕéʼţá֖ ḃֽ⁠wò׃"],[12,6,"לְ⁠עֵ֨ינֵי⁠הֶ֜ם עַל־כָּתֵ֤ף תִּשָּׂא֙ בָּ⁠עֲלָטָ֣ה תוֹצִ֔יא פָּנֶ֣י⁠ךָ תְכַסֶּ֔ה וְ⁠לֹ֥א תִרְאֶ֖ה אֶת־הָ⁠אָ֑רֶץ כִּֽי־מוֹפֵ֥ת נְתַתִּ֖י⁠ךָ לְ⁠בֵ֥ית יִשְׂרָאֵֽל׃","lĕ⁠ʻé֨ynéy⁠he֜m ʻal-ká̇ţé֤p ţi̇şá̇̂ʼ֙ bá̇⁠ʻàlátá֣h ţwòẕi֔yʼ pá̇ne֣y⁠ká ţĕkasė֔h wĕ⁠lò֥ʼ ţirĕʼe֖h ʼeţ-há⁠ʼá֑reẕ kiֽ̇y-mwòpé֥ţ nĕţaţi֖̇y⁠ká lĕ⁠bé֥yţ yişĕ̂ráʼéֽl׃"],[12,7,"וָ⁠אַ֣עַשׂ כֵּן֮ כַּ⁠אֲשֶׁ֣ר צֻוֵּיתִי֒ כֵּ֠לַ⁠י הוֹצֵ֜אתִי כִּ⁠כְלֵ֤י גוֹלָה֙ יוֹמָ֔ם וּ⁠בָ⁠עֶ֛רֶב חָתַֽרְתִּי־לִ֥⁠י בַ⁠קִּ֖יר בְּ⁠יָ֑ד בָּ⁠עֲלָטָ֥ה הוֹצֵ֛אתִי עַל־כָּתֵ֥ף נָשָׂ֖אתִי לְ⁠עֵינֵי⁠הֶֽם׃פ","wá⁠ʼa֣ʻaş̂ ké̇n֮ kȧ⁠ʼàşě֣r ẕuwé̇yţiy֒ ké̇֠la⁠y hwòẕé֜ʼţiy ki̇⁠kĕlé֤y gwòláh֙ ywòmá֔m ẇ⁠bá⁠ʻe֛reb ẖáţaֽrĕţi̇y-li֥⁠y ba⁠qi֖̇yr bĕ̇⁠yá֑d bá̇⁠ʻàlátá֥h hwòẕé֛ʼţiy ʻal-ká̇ţé֥p náşá֖̂ʼţiy lĕ⁠ʻéynéy⁠heֽm׃p"],[12,8,"וַ⁠יְהִ֧י דְבַר־יְהוָ֛ה אֵלַ֖⁠י בַּ⁠בֹּ֥קֶר לֵ⁠אמֹֽר׃","wa⁠yĕhi֧y dĕbar-yĕhwá֛h ʼéla֖⁠y bȧ⁠bò֥̇qer lé⁠ʼmòֽr׃"],[12,9,"בֶּן־אָדָ֕ם הֲ⁠לֹ֨א אָמְר֥וּ אֵלֶ֛י⁠ךָ בֵּ֥ית יִשְׂרָאֵ֖ל בֵּ֣ית הַ⁠מֶּ֑רִי מָ֖ה אַתָּ֥ה עֹשֶֽׂה׃","bėn-ʼádá֕m hà⁠lò֨ʼ ʼámĕr֥ẇ ʼéle֛y⁠ká bé֥̇yţ yişĕ̂ráʼé֖l bé֣̇yţ ha⁠mė֑riy má֖h ʼaţá֥̇h ʻòşêֽh׃"],[12,10,"אֱמֹ֣ר אֲלֵי⁠הֶ֔ם כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהֹוִ֑ה הַ⁠נָּשִׂ֞יא הַ⁠מַּשָּׂ֤א הַ⁠זֶּה֙ בִּ⁠יר֣וּשָׁלִַ֔ם וְ⁠כָל־בֵּ֥ית יִשְׂרָאֵ֖ל אֲשֶׁר־הֵ֥מָּה בְ⁠תוֹכָֽ⁠ם׃","ʼèmò֣r ʼàléy⁠he֔m kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhòwi֑h ha⁠ná̇şî֞yʼ ha⁠mȧşá֤̇̂ʼ ha⁠zėh֙ bi̇⁠yr֣ẇşá̌lia֔m wĕ⁠kál-bé֥̇yţ yişĕ̂ráʼé֖l ʼàşěr-hé֥má̇h bĕ⁠ţwòkáֽ⁠m׃"],[12,11,"אֱמֹ֖ר אֲנִ֣י מֽוֹפֶתְ⁠כֶ֑ם כַּ⁠אֲשֶׁ֣ר עָשִׂ֗יתִי כֵּ֚ן יֵעָשֶׂ֣ה לָ⁠הֶ֔ם בַּ⁠גּוֹלָ֥ה בַ⁠שְּׁבִ֖י יֵלֵֽכוּ׃","ʼèmò֖r ʼàni֣y mֽwòpeţĕ⁠ke֑m kȧ⁠ʼàşě֣r ʻáşî֗yţiy ké֚̇n yéʻáşê֣h lá⁠he֔m bȧ⁠ġwòlá֥h ba⁠şĕ̇̌bi֖y yéléֽkẇ׃"],[12,12,"וְ⁠הַ⁠נָּשִׂ֨יא אֲשֶׁר־בְּ⁠תוֹכָ֜⁠ם אֶל־כָּתֵ֤ף יִשָּׂא֙ בָּ⁠עֲלָטָ֣ה וְ⁠יֵצֵ֔א בַּ⁠קִּ֥יר יַחְתְּר֖וּ לְ⁠ה֣וֹצִיא ב֑⁠וֹ פָּנָ֣י⁠ו יְכַסֶּ֔ה יַ֗עַן אֲשֶׁ֨ר לֹא־יִרְאֶ֥ה לַ⁠עַ֛יִן ה֖וּא אֶת־הָ⁠אָֽרֶץ׃","wĕ⁠ha⁠ná̇şî֨yʼ ʼàşěr-bĕ̇⁠ţwòká֜⁠m ʼel-ká̇ţé֤p yişá̇̂ʼ֙ bá̇⁠ʻàlátá֣h wĕ⁠yéẕé֔ʼ bȧ⁠qi֥̇yr yaẖĕţĕ̇r֖ẇ lĕ⁠h֣wòẕiyʼ b֑⁠wò pá̇ná֣y⁠w yĕkasė֔h ya֗ʻan ʼàşě֨r lòʼ-yirĕʼe֥h la⁠ʻa֛yin h֖ẇʼ ʼeţ-há⁠ʼáֽreẕ׃"],[12,13,"וּ⁠פָרַשְׂתִּ֤י אֶת־רִשְׁתִּ⁠י֙ עָלָ֔י⁠ו וְ⁠נִתְפַּ֖שׂ בִּ⁠מְצֽוּדָתִ֑⁠י וְ⁠הֵבֵאתִ֨י אֹת֤⁠וֹ בָבֶ֨לָ⁠ה֙ אֶ֣רֶץ כַּשְׂדִּ֔ים וְ⁠אוֹתָ֥⁠הּ לֹֽא־יִרְאֶ֖ה וְ⁠שָׁ֥ם יָמֽוּת׃","ẇ⁠páraşĕ̂ţi֤̇y ʼeţ-rişĕ̌ţi̇⁠y֙ ʻálá֔y⁠w wĕ⁠niţĕpȧ֖ş̂ bi̇⁠mĕẕֽẇdáţi֑⁠y wĕ⁠hébéʼţi֨y ʼòţ֤⁠wò bábe֨lá⁠h֙ ʼe֣reẕ kȧşĕ̂di̇֔ym wĕ⁠ʼwòţá֥⁠ḣ lòֽʼ-yirĕʼe֖h wĕ⁠şá֥̌m yámֽẇţ׃"],[12,14,"וְ⁠כֹל֩ אֲשֶׁ֨ר סְבִיבֹתָ֥י⁠ו עזר⁠ה וְ⁠כָל־אֲגַפָּ֖י⁠ו אֱזָרֶ֣ה לְ⁠כָל־ר֑וּחַ וְ⁠חֶ֖רֶב אָרִ֥יק אַחֲרֵי⁠הֶֽם׃","wĕ⁠kòl֩ ʼàşě֨r sĕbiybòţá֥y⁠w ʻzr⁠h wĕ⁠kál-ʼàgapá֖̇y⁠w ʼèzáre֣h lĕ⁠kál-r֑ẇẖa wĕ⁠ẖe֖reb ʼári֥yq ʼaẖàréy⁠heֽm׃"],[12,15,"וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֣י יְהוָ֑ה בַּ⁠הֲפִיצִ֤⁠י אוֹתָ⁠ם֙ בַּ⁠גּוֹיִ֔ם וְ⁠זֵרִיתִ֥י אוֹתָ֖⁠ם בָּ⁠אֲרָצֽוֹת׃","wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֣y yĕhwá֑h bȧ⁠hàpiyẕi֤⁠y ʼwòţá⁠m֙ bȧ⁠ġwòyi֔m wĕ⁠zériyţi֥y ʼwòţá֖⁠m bá̇⁠ʼàráẕֽwòţ׃"],[12,16,"וְ⁠הוֹתַרְתִּ֤י מֵ⁠הֶם֙ אַנְשֵׁ֣י מִסְפָּ֔ר מֵ⁠חֶ֖רֶב מֵ⁠רָעָ֣ב וּ⁠מִ⁠דָּ֑בֶר לְמַ֨עַן יְסַפְּר֜וּ אֶת־כָּל־תּוֹעֲבֽוֹתֵי⁠הֶ֗ם בַּ⁠גּוֹיִם֙ אֲשֶׁר־בָּ֣אוּ שָׁ֔ם וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃פ","wĕ⁠hwòţarĕţi֤̇y mé⁠hem֙ ʼanĕşé֣̌y misĕpá̇֔r mé⁠ẖe֖reb mé⁠ráʻá֣b ẇ⁠mi⁠dá֑̇ber lĕma֨ʻan yĕsapĕ̇r֜ẇ ʼeţ-ká̇l-ţ̇wòʻàbֽwòţéy⁠he֗m bȧ⁠ġwòyim֙ ʼàşěr-bá֣̇ʼẇ şá̌֔m wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃p"],[12,17,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[12,18,"בֶּן־אָדָ֕ם לַחְמְ⁠ךָ֖ בְּ⁠רַ֣עַשׁ תֹּאכֵ֑ל וּ⁠מֵימֶ֕י⁠ךָ בְּ⁠רָגְזָ֥ה וּ⁠בִ⁠דְאָגָ֖ה תִּשְׁתֶּֽה׃","bėn-ʼádá֕m laẖĕmĕ⁠ká֖ bĕ̇⁠ra֣ʻaş̌ ţò̇ʼké֑l ẇ⁠méyme֕y⁠ká bĕ̇⁠rágĕzá֥h ẇ⁠bi⁠dĕʼágá֖h ţi̇şĕ̌ţėֽh׃"],[12,19,"וְ⁠אָמַרְתָּ֣ אֶל־עַ֣ם הָ⁠אָ֡רֶץ כֹּֽה־אָמַר֩ אֲדֹנָ֨⁠י יְהוִ֜ה לְ⁠יוֹשְׁבֵ֤י יְרוּשָׁלִַ֨ם֙ אֶל־אַדְמַ֣ת יִשְׂרָאֵ֔ל לַחְמָ⁠ם֙ בִּ⁠דְאָגָ֣ה יֹאכֵ֔לוּ וּ⁠מֵֽימֵי⁠הֶ֖ם בְּ⁠שִׁמָּמ֣וֹן יִשְׁתּ֑וּ לְמַ֜עַן תֵּשַׁ֤ם אַרְצָ⁠הּ֙ מִ⁠מְּלֹאָ֔⁠הּ מֵ⁠חֲמַ֖ס כָּֽל־הַ⁠יֹּשְׁבִ֥ים בָּֽ⁠הּ׃","wĕ⁠ʼámarĕţá֣̇ ʼel-ʻa֣m há⁠ʼá֡reẕ kòֽ̇h-ʼámar֩ ʼàdòná֨⁠y yĕhwi֜h lĕ⁠ywòşĕ̌bé֤y yĕrẇşá̌lia֨m֙ ʼel-ʼadĕma֣ţ yişĕ̂ráʼé֔l laẖĕmá⁠m֙ bi̇⁠dĕʼágá֣h yòʼké֔lẇ ẇ⁠méֽyméy⁠he֖m bĕ̇⁠şǐmá̇m֣wòn yişĕ̌ţ֑̇ẇ lĕma֜ʻan ţé̇şǎ֤m ʼarĕẕá⁠ḣ֙ mi⁠mĕ̇lòʼá֔⁠ḣ mé⁠ẖàma֖s káֽ̇l-ha⁠yò̇şĕ̌bi֥ym báֽ̇⁠ḣ׃"],[12,20,"וְ⁠הֶ⁠עָרִ֤ים הַ⁠נּֽוֹשָׁבוֹת֙ תֶּחֱרַ֔בְנָה וְ⁠הָ⁠אָ֖רֶץ שְׁמָמָ֣ה תִֽהְיֶ֑ה וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃פ","wĕ⁠he⁠ʻári֤ym ha⁠ṅֽwòşá̌bwòţ֙ ţėẖèra֔bĕnáh wĕ⁠há⁠ʼá֖reẕ şĕ̌mámá֣h ţiֽhĕye֑h wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃p"],[12,21,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[12,22,"בֶּן־אָדָ֗ם מָֽה־הַ⁠מָּשָׁ֤ל הַ⁠זֶּה֙ לָ⁠כֶ֔ם עַל־אַדְמַ֥ת יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר יַֽאַרְכוּ֙ הַ⁠יָּמִ֔ים וְ⁠אָבַ֖ד כָּל־חָזֽוֹן׃","bėn-ʼádá֗m máֽh-ha⁠má̇şá֤̌l ha⁠zėh֙ lá⁠ke֔m ʻal-ʼadĕma֥ţ yişĕ̂ráʼé֖l lé⁠ʼmò֑r yaֽʼarĕkẇ֙ ha⁠yá̇mi֔ym wĕ⁠ʼába֖d ká̇l-ẖázֽwòn׃"],[12,23,"לָ⁠כֵ֞ן אֱמֹ֣ר אֲלֵי⁠הֶ֗ם כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ הִשְׁבַּ֨תִּי֙ אֶת־הַ⁠מָּשָׁ֣ל הַ⁠זֶּ֔ה וְ⁠לֹֽא־יִמְשְׁל֥וּ אֹת֛⁠וֹ ע֖וֹד בְּ⁠יִשְׂרָאֵ֑ל כִּ֚י אִם־דַּבֵּ֣ר אֲלֵי⁠הֶ֔ם קָֽרְבוּ֙ הַ⁠יָּמִ֔ים וּ⁠דְבַ֖ר כָּל־חָזֽוֹן׃","lá⁠ké֞n ʼèmò֣r ʼàléy⁠he֗m kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ hişĕ̌bȧ֨ţi̇y֙ ʼeţ-ha⁠má̇şá֣̌l ha⁠zė֔h wĕ⁠lòֽʼ-yimĕşĕ̌l֥ẇ ʼòţ֛⁠wò ʻ֖wòd bĕ̇⁠yişĕ̂ráʼé֑l ki֚̇y ʼim-dȧbé֣̇r ʼàléy⁠he֔m qáֽrĕbẇ֙ ha⁠yá̇mi֔ym ẇ⁠dĕba֖r ká̇l-ẖázֽwòn׃"],[12,24,"כִּ֠י לֹ֣א יִֽהְיֶ֥ה ע֛וֹד כָּל־חֲז֥וֹן שָׁ֖וְא וּ⁠מִקְסַ֣ם חָלָ֑ק בְּ⁠ת֖וֹךְ בֵּ֥ית יִשְׂרָאֵֽל׃","ki̇֠y lò֣ʼ yiֽhĕye֥h ʻ֛wòd ká̇l-ẖàz֥wòn şá֖̌wĕʼ ẇ⁠miqĕsa֣m ẖálá֑q bĕ̇⁠ţ֖wòkĕ bé֥̇yţ yişĕ̂ráʼéֽl׃"],[12,25,"כִּ֣י ׀ אֲנִ֣י יְהוָ֗ה אֲדַבֵּר֙ אֵת֩ אֲשֶׁ֨ר אֲדַבֵּ֤ר דָּבָר֙ וְ⁠יֵ֣עָשֶׂ֔ה לֹ֥א תִמָּשֵׁ֖ךְ ע֑וֹד כִּ֣י בִֽ⁠ימֵי⁠כֶ֞ם בֵּ֣ית הַ⁠מֶּ֗רִי אֲדַבֵּ֤ר דָּבָר֙ וַ⁠עֲשִׂיתִ֔י⁠ו נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","ki֣̇y ׀ ʼàni֣y yĕhwá֗h ʼàdabé̇r֙ ʼéţ֩ ʼàşě֨r ʼàdabé֤̇r dá̇bár֙ wĕ⁠yé֣ʻáşê֔h lò֥ʼ ţimá̇şé֖̌kĕ ʻ֑wòd ki֣̇y biֽ⁠yméy⁠ke֞m bé֣̇yţ ha⁠mė֗riy ʼàdabé֤̇r dá̇bár֙ wa⁠ʻàşîyţi֔y⁠w nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[12,26,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[12,27,"בֶּן־אָדָ֗ם הִנֵּ֤ה בֵֽית־יִשְׂרָאֵל֙ אֹֽמְרִ֔ים הֶ⁠חָז֛וֹן אֲשֶׁר־ה֥וּא חֹזֶ֖ה לְ⁠יָמִ֣ים רַבִּ֑ים וּ⁠לְ⁠עִתִּ֥ים רְחוֹק֖וֹת ה֥וּא נִבָּֽא׃","bėn-ʼádá֗m hiné֤̇h béֽyţ-yişĕ̂ráʼél֙ ʼòֽmĕri֔ym he⁠ẖáz֛wòn ʼàşěr-h֥ẇʼ ẖòze֖h lĕ⁠yámi֣ym rabi֑̇ym ẇ⁠lĕ⁠ʻiţi֥̇ym rĕẖwòq֖wòţ h֥ẇʼ nibáֽ̇ʼ׃"],[12,28,"לָ⁠כֵ֞ן אֱמֹ֣ר אֲלֵי⁠הֶ֗ם כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה לֹא־תִמָּשֵׁ֥ךְ ע֖וֹד כָּל־דְּבָרָ֑⁠י אֲשֶׁ֨ר אֲדַבֵּ֤ר דָּבָר֙ וְ⁠יֵ֣עָשֶׂ֔ה נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","lá⁠ké֞n ʼèmò֣r ʼàléy⁠he֗m kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h lòʼ-ţimá̇şé֥̌kĕ ʻ֖wòd ká̇l-dĕ̇bárá֑⁠y ʼàşě֨r ʼàdabé֤̇r dá̇bár֙ wĕ⁠yé֣ʻáşê֔h nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[13,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[13,2,"בֶּן־אָדָ֕ם הִנָּבֵ֛א אֶל־נְבִיאֵ֥י יִשְׂרָאֵ֖ל הַ⁠נִּבָּאִ֑ים וְ⁠אָֽמַרְתָּ֙ לִ⁠נְבִיאֵ֣י מִ⁠לִּבָּ֔⁠ם שִׁמְע֖וּ דְּבַר־יְהוָֽה׃","bėn-ʼádá֕m hiná̇bé֛ʼ ʼel-nĕbiyʼé֥y yişĕ̂ráʼé֖l ha⁠ni̇bá̇ʼi֑ym wĕ⁠ʼáֽmarĕţá̇֙ li⁠nĕbiyʼé֣y mi⁠li̇bá̇֔⁠m şǐmĕʻ֖ẇ dĕ̇bar-yĕhwáֽh׃"],[13,3,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה ה֖וֹי עַל־הַ⁠נְּבִיאִ֣ים הַ⁠נְּבָלִ֑ים אֲשֶׁ֥ר הֹלְכִ֛ים אַחַ֥ר רוּחָ֖⁠ם וּ⁠לְ⁠בִלְתִּ֥י רָאֽוּ׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h h֖wòy ʻal-ha⁠nĕ̇biyʼi֣ym ha⁠nĕ̇báli֑ym ʼàşě֥r hòlĕki֛ym ʼaẖa֥r rẇẖá֖⁠m ẇ⁠lĕ⁠bilĕţi֥̇y ráʼֽẇ׃"],[13,4,"כְּ⁠שֻׁעָלִ֖ים בָּ⁠חֳרָב֑וֹת נְבִיאֶ֥י⁠ךָ יִשְׂרָאֵ֖ל הָיֽוּ׃","kĕ̇⁠şǔʻáli֖ym bá̇⁠ẖoráb֑wòţ nĕbiyʼe֥y⁠ká yişĕ̂ráʼé֖l háyֽẇ׃"],[13,5,"לֹ֤א עֲלִיתֶם֙ בַּ⁠פְּרָצ֔וֹת וַ⁠תִּגְדְּר֥וּ גָדֵ֖ר עַל־בֵּ֣ית יִשְׂרָאֵ֑ל לַ⁠עֲמֹ֥ד בַּ⁠מִּלְחָמָ֖ה בְּ⁠י֥וֹם יְהוָֽה׃","lò֤ʼ ʻàliyţem֙ bȧ⁠pĕ̇ráẕ֔wòţ wa⁠ţi̇gĕdĕ̇r֥ẇ gádé֖r ʻal-bé֣̇yţ yişĕ̂ráʼé֑l la⁠ʻàmò֥d bȧ⁠mi̇lĕẖámá֖h bĕ̇⁠y֥wòm yĕhwáֽh׃"],[13,6,"חָ֤זוּ שָׁוְא֙ וְ⁠קֶ֣סֶם כָּזָ֔ב הָ⁠אֹֽמְרִים֙ נְאֻם־יְהוָ֔ה וַֽ⁠יהוָ֖ה לֹ֣א שְׁלָחָ֑⁠ם וְ⁠יִֽחֲל֖וּ לְ⁠קַיֵּ֥ם דָּבָֽר׃","ẖá֤zẇ şá̌wĕʼ֙ wĕ⁠qe֣sem ká̇zá֔b há⁠ʼòֽmĕriym֙ nĕʼum-yĕhwá֔h waֽ⁠yhwá֖h lò֣ʼ şĕ̌láẖá֑⁠m wĕ⁠yiֽẖàl֖ẇ lĕ⁠qayé֥̇m dá̇báֽr׃"],[13,7,"הֲ⁠ל֤וֹא מַֽחֲזֵה־שָׁוְא֙ חֲזִיתֶ֔ם וּ⁠מִקְסַ֥ם כָּזָ֖ב אֲמַרְתֶּ֑ם וְ⁠אֹֽמְרִים֙ נְאֻם־יְהוָ֔ה וַ⁠אֲנִ֖י לֹ֥א דִבַּֽרְתִּי׃ס","hà⁠l֤wòʼ maֽẖàzéh-şá̌wĕʼ֙ ẖàziyţe֔m ẇ⁠miqĕsa֥m ká̇zá֖b ʼàmarĕţė֑m wĕ⁠ʼòֽmĕriym֙ nĕʼum-yĕhwá֔h wa⁠ʼàni֖y lò֥ʼ dibȧֽrĕţi̇y׃s"],[13,8,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה יַ֚עַן דַּבֶּרְ⁠כֶ֣ם שָׁ֔וְא וַ⁠חֲזִיתֶ֖ם כָּזָ֑ב לָ⁠כֵן֙ הִנְ⁠נִ֣י אֲלֵי⁠כֶ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ya֚ʻan dȧbėrĕ⁠ke֣m şá̌֔wĕʼ wa⁠ẖàziyţe֖m ká̇zá֑b lá⁠kén֙ hinĕ⁠ni֣y ʼàléy⁠ke֔m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[13,9,"וְ⁠הָיְתָ֣ה יָדִ֗⁠י אֶֽל־הַ⁠נְּבִיאִ֞ים הַ⁠חֹזִ֣ים שָׁוְא֮ וְ⁠הַ⁠קֹּסְמִ֣ים כָּזָב֒ בְּ⁠ס֧וֹד עַמִּ֣⁠י לֹֽא־יִהְי֗וּ וּ⁠בִ⁠כְתָ֤ב בֵּֽית־יִשְׂרָאֵל֙ לֹ֣א יִכָּתֵ֔בוּ וְ⁠אֶל־אַדְמַ֥ת יִשְׂרָאֵ֖ל לֹ֣א יָבֹ֑אוּ וִ⁠ידַעְתֶּ֕ם כִּ֥י אֲנִ֖י אֲדֹנָ֥⁠י יְהוִֽה׃","wĕ⁠háyĕţá֣h yádi֗⁠y ʼeֽl-ha⁠nĕ̇biyʼi֞ym ha⁠ẖòzi֣ym şá̌wĕʼ֮ wĕ⁠ha⁠qò̇sĕmi֣ym ká̇záb֒ bĕ̇⁠s֧wòd ʻami֣̇⁠y lòֽʼ-yihĕy֗ẇ ẇ⁠bi⁠kĕţá֤b béֽ̇yţ-yişĕ̂ráʼél֙ lò֣ʼ yiká̇ţé֔bẇ wĕ⁠ʼel-ʼadĕma֥ţ yişĕ̂ráʼé֖l lò֣ʼ yábò֑ʼẇ wi⁠ydaʻĕţė֕m ki֥̇y ʼàni֖y ʼàdòná֥⁠y yĕhwiֽh׃"],[13,10,"יַ֣עַן וּ⁠בְ⁠יַ֜עַן הִטְע֧וּ אֶת־עַמִּ֛⁠י לֵ⁠אמֹ֥ר שָׁל֖וֹם וְ⁠אֵ֣ין שָׁל֑וֹם וְ⁠הוּא֙ בֹּ֣נֶה חַ֔יִץ וְ⁠הִנָּ֛⁠ם טָחִ֥ים אֹת֖⁠וֹ תָּפֵֽל׃","ya֣ʻan ẇ⁠bĕ⁠ya֜ʻan hitĕʻ֧ẇ ʼeţ-ʻami֛̇⁠y lé⁠ʼmò֥r şá̌l֖wòm wĕ⁠ʼé֣yn şá̌l֑wòm wĕ⁠hẇʼ֙ bò֣̇neh ẖa֔yiẕ wĕ⁠hiná֛̇⁠m táẖi֥ym ʼòţ֖⁠wò ţá̇péֽl׃"],[13,11,"אֱמֹ֛ר אֶל־טָחֵ֥י תָפֵ֖ל וְ⁠יִפֹּ֑ל הָיָ֣ה ׀ גֶּ֣שֶׁם שׁוֹטֵ֗ף וְ⁠אַתֵּ֜נָה אַבְנֵ֤י אֶלְגָּבִישׁ֙ תִּפֹּ֔לְנָה וְ⁠ר֥וּחַ סְעָר֖וֹת תְּבַקֵּֽעַ׃","ʼèmò֛r ʼel-táẖé֥y ţápé֖l wĕ⁠yipò֑̇l háyá֣h ׀ gė֣şěm ş̌wòté֗p wĕ⁠ʼaţé̇֜náh ʼabĕné֤y ʼelĕgá̇biyş̌֙ ţi̇pò̇֔lĕnáh wĕ⁠r֥ẇẖa sĕʻár֖wòţ ţĕ̇baqéֽ̇ʻa׃"],[13,12,"וְ⁠הִנֵּ֖ה נָפַ֣ל הַ⁠קִּ֑יר הֲ⁠לוֹא֙ יֵאָמֵ֣ר אֲלֵי⁠כֶ֔ם אַיֵּ֥ה הַ⁠טִּ֖יחַ אֲשֶׁ֥ר טַחְתֶּֽם׃ס","wĕ⁠hiné֖̇h nápa֣l ha⁠qi֑̇yr hà⁠lwòʼ֙ yéʼámé֣r ʼàléy⁠ke֔m ʼayé֥̇h ha⁠ti֖̇yẖa ʼàşě֥r taẖĕţėֽm׃s"],[13,13,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה וּ⁠בִקַּעְתִּ֥י רֽוּחַ־סְעָר֖וֹת בַּֽ⁠חֲמָתִ֑⁠י וְ⁠גֶ֤שֶׁם שֹׁטֵף֙ בְּ⁠אַפִּ֣⁠י יִֽהְיֶ֔ה וְ⁠אַבְנֵ֥י אֶלְגָּבִ֖ישׁ בְּ⁠חֵמָ֥ה לְ⁠כָלָֽה׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ẇ⁠biqȧʻĕţi֥̇y rֽẇẖa-sĕʻár֖wòţ bȧֽ⁠ẖàmáţi֑⁠y wĕ⁠ge֤şěm şò̌tép֙ bĕ̇⁠ʼapi֣̇⁠y yiֽhĕye֔h wĕ⁠ʼabĕné֥y ʼelĕgá̇bi֖yş̌ bĕ̇⁠ẖémá֥h lĕ⁠káláֽh׃"],[13,14,"וְ⁠הָ֨רַסְתִּ֜י אֶת־הַ⁠קִּ֨יר אֲשֶׁר־טַחְתֶּ֥ם תָּפֵ֛ל וְ⁠הִגַּעְתִּ֥י⁠הוּ אֶל־הָ⁠אָ֖רֶץ וְ⁠נִגְלָ֣ה יְסֹד֑⁠וֹ וְ⁠נָֽפְלָה֙ וּ⁠כְלִיתֶ֣ם בְּ⁠תוֹכָ֔⁠הּ וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃","wĕ⁠há֨rasĕţi̇֜y ʼeţ-ha⁠qi̇֨yr ʼàşěr-taẖĕţė֥m ţá̇pé֛l wĕ⁠higȧʻĕţi֥̇y⁠hẇ ʼel-há⁠ʼá֖reẕ wĕ⁠nigĕlá֣h yĕsòd֑⁠wò wĕ⁠náֽpĕláh֙ ẇ⁠kĕliyţe֣m bĕ̇⁠ţwòká֔⁠ḣ wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[13,15,"וְ⁠כִלֵּיתִ֤י אֶת־חֲמָתִ⁠י֙ בַּ⁠קִּ֔יר וּ⁠בַ⁠טָּחִ֥ים אֹת֖⁠וֹ תָּפֵ֑ל וְ⁠אֹמַ֤ר לָ⁠כֶם֙ אֵ֣ין הַ⁠קִּ֔יר וְ⁠אֵ֖ין הַ⁠טָּחִ֥ים אֹתֽ⁠וֹ׃","wĕ⁠kilé̇yţi֤y ʼeţ-ẖàmáţi⁠y֙ bȧ⁠qi̇֔yr ẇ⁠ba⁠tá̇ẖi֥ym ʼòţ֖⁠wò ţá̇pé֑l wĕ⁠ʼòma֤r lá⁠kem֙ ʼé֣yn ha⁠qi̇֔yr wĕ⁠ʼé֖yn ha⁠tá̇ẖi֥ym ʼòţֽ⁠wò׃"],[13,16,"נְבִיאֵ֣י יִשְׂרָאֵ֗ל הַֽ⁠נִבְּאִים֙ אֶל־יְר֣וּשָׁלִַ֔ם וְ⁠הַ⁠חֹזִ֥ים לָ֖⁠הּ חֲז֣וֹן שָׁלֹ֑ם וְ⁠אֵ֣ין שָׁלֹ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהֹוִֽה׃פ","nĕbiyʼé֣y yişĕ̂ráʼé֗l haֽ⁠nibĕ̇ʼiym֙ ʼel-yĕr֣ẇşá̌lia֔m wĕ⁠ha⁠ẖòzi֥ym lá֖⁠ḣ ẖàz֣wòn şá̌lò֑m wĕ⁠ʼé֣yn şá̌lò֔m nĕʼu֖m ʼàdòná֥⁠y yĕhòwiֽh׃p"],[13,17,"וְ⁠אַתָּ֣ה בֶן־אָדָ֗ם שִׂ֤ים פָּנֶ֨י⁠ךָ֙ אֶל־בְּנ֣וֹת עַמְּ⁠ךָ֔ הַ⁠מִּֽתְנַבְּא֖וֹת מִֽ⁠לִּבְּ⁠הֶ֑ן וְ⁠הִנָּבֵ֖א עֲלֵי⁠הֶֽן׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֗m şî֤ym pá̇ne֨y⁠ká֙ ʼel-bĕ̇n֣wòţ ʻamĕ̇⁠ká֔ ha⁠miֽ̇ţĕnabĕ̇ʼ֖wòţ miֽ⁠li̇bĕ̇⁠he֑n wĕ⁠hiná̇bé֖ʼ ʻàléy⁠heֽn׃"],[13,18,"וְ⁠אָמַרְתָּ֞ כֹּה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה הוֹי֩ לִֽ⁠מְתַפְּר֨וֹת כְּסָת֜וֹת עַ֣ל ׀ כָּל־אַצִּילֵ֣י יָדַ֗⁠י וְ⁠עֹשׂ֧וֹת הַ⁠מִּסְפָּח֛וֹת עַל־רֹ֥אשׁ כָּל־קוֹמָ֖ה לְ⁠צוֹדֵ֣ד נְפָשׁ֑וֹת הַ⁠נְּפָשׁוֹת֙ תְּצוֹדֵ֣דְנָה לְ⁠עַמִּ֔⁠י וּ⁠נְפָשׁ֖וֹת לָ⁠כֶ֥נָה תְחַיֶּֽינָה׃","wĕ⁠ʼámarĕţá̇֞ kò̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h hwòy֩ liֽ⁠mĕţapĕ̇r֨wòţ kĕ̇sáţ֜wòţ ʻa֣l ׀ ká̇l-ʼaẕi̇ylé֣y yáda֗⁠y wĕ⁠ʻòş֧̂wòţ ha⁠mi̇sĕpá̇ẖ֛wòţ ʻal-rò֥ʼş̌ ká̇l-qwòmá֖h lĕ⁠ẕwòdé֣d nĕpáş֑̌wòţ ha⁠nĕ̇páş̌wòţ֙ ţĕ̇ẕwòdé֣dĕnáh lĕ⁠ʻami̇֔⁠y ẇ⁠nĕpáş֖̌wòţ lá⁠ke֥náh ţĕẖayėֽynáh׃"],[13,19,"וַ⁠תְּחַלֶּלְ֨נָה אֹתִ֜⁠י אֶל־עַמִּ֗⁠י בְּ⁠שַׁעֲלֵ֣י שְׂעֹרִים֮ וּ⁠בִ⁠פְת֣וֹתֵי לֶחֶם֒ לְ⁠הָמִ֤ית נְפָשׁוֹת֙ אֲשֶׁ֣ר לֹֽא־תְמוּתֶ֔נָה וּ⁠לְ⁠חַיּ֥וֹת נְפָשׁ֖וֹת אֲשֶׁ֣ר לֹא־תִֽחְיֶ֑ינָה בְּ⁠כַ֨זֶּבְ⁠כֶ֔ם לְ⁠עַמִּ֖⁠י שֹׁמְעֵ֥י כָזָֽב׃ס","wa⁠ţĕ̇ẖalėlĕ֨náh ʼòţi֜⁠y ʼel-ʻami̇֗⁠y bĕ̇⁠şǎʻàlé֣y şĕ̂ʻòriym֮ ẇ⁠bi⁠pĕţ֣wòţéy leẖem֒ lĕ⁠hámi֤yţ nĕpáş̌wòţ֙ ʼàşě֣r lòֽʼ-ţĕmẇţe֔náh ẇ⁠lĕ⁠ẖaẏ֥wòţ nĕpáş֖̌wòţ ʼàşě֣r lòʼ-ţiֽẖĕye֑ynáh bĕ̇⁠ka֨zėbĕ⁠ke֔m lĕ⁠ʻami֖̇⁠y şò̌mĕʻé֥y kázáֽb׃s"],[13,20,"לָ⁠כֵ֞ן כֹּה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה הִנְ⁠נִ֤י אֶל־כִּסְּתוֹתֵי⁠כֶ֨נָה֙ אֲשֶׁ֣ר אַ֠תֵּנָה מְצֹדְד֨וֹת שָׁ֤ם אֶת־הַ⁠נְּפָשׁוֹת֙ לְ⁠פֹ֣רְח֔וֹת וְ⁠קָרַעְתִּ֣י אֹתָ֔⁠ם מֵ⁠עַ֖ל זְרוֹעֹֽתֵי⁠כֶ֑ם וְ⁠שִׁלַּחְתִּי֙ אֶת־הַ⁠נְּפָשׁ֔וֹת אֲשֶׁ֥ר אַתֶּ֛ם מְצֹדְד֥וֹת אֶת־נְפָשִׁ֖ים לְ⁠פֹרְחֹֽת׃","lá⁠ké֞n kò̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h hinĕ⁠ni֤y ʼel-ki̇sĕ̇ţwòţéy⁠ke֨náh֙ ʼàşě֣r ʼa֠ţé̇náh mĕẕòdĕd֨wòţ şá֤̌m ʼeţ-ha⁠nĕ̇páş̌wòţ֙ lĕ⁠pò֣rĕẖ֔wòţ wĕ⁠qáraʻĕţi֣̇y ʼòţá֔⁠m mé⁠ʻa֖l zĕrwòʻòֽţéy⁠ke֑m wĕ⁠şǐlȧẖĕţi̇y֙ ʼeţ-ha⁠nĕ̇páş̌֔wòţ ʼàşě֥r ʼaţė֛m mĕẕòdĕd֥wòţ ʼeţ-nĕpáşǐ֖ym lĕ⁠pòrĕẖòֽţ׃"],[13,21,"וְ⁠קָרַעְתִּ֞י אֶת־מִסְפְּחֹֽתֵי⁠כֶ֗ם וְ⁠הִצַּלְתִּ֤י אֶת־עַמִּ⁠י֙ מִ⁠יֶּדְ⁠כֶ֔ן וְ⁠לֹֽא־יִהְי֥וּ ע֛וֹד בְּ⁠יֶדְ⁠כֶ֖ן לִ⁠מְצוּדָ֑ה וִֽ⁠ידַעְתֶּ֖ן כִּֽי־אֲנִ֥י יְהוָֽה׃","wĕ⁠qáraʻĕţi̇֞y ʼeţ-misĕpĕ̇ẖòֽţéy⁠ke֗m wĕ⁠hiẕȧlĕţi֤̇y ʼeţ-ʻami̇⁠y֙ mi⁠yėdĕ⁠ke֔n wĕ⁠lòֽʼ-yihĕy֥ẇ ʻ֛wòd bĕ̇⁠yedĕ⁠ke֖n li⁠mĕẕẇdá֑h wiֽ⁠ydaʻĕţė֖n kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[13,22,"יַ֣עַן הַכְא֤וֹת לֵב־צַדִּיק֙ שֶׁ֔קֶר וַ⁠אֲנִ֖י לֹ֣א הִכְאַבְתִּ֑י⁠ו וּ⁠לְ⁠חַזֵּק֙ יְדֵ֣י רָשָׁ֔ע לְ⁠בִלְתִּי־שׁ֛וּב מִ⁠דַּרְכּ֥⁠וֹ הָ⁠רָ֖ע לְ⁠הַחֲיֹתֽ⁠וֹ׃","ya֣ʻan hakĕʼ֤wòţ léb-ẕadi̇yq֙ şě֔qer wa⁠ʼàni֖y lò֣ʼ hikĕʼabĕţi֑̇y⁠w ẇ⁠lĕ⁠ẖazé̇q֙ yĕdé֣y ráşá̌֔ʻ lĕ⁠bilĕţi̇y-ş֛̌ẇb mi⁠dȧrĕk֥̇⁠wò há⁠rá֖ʻ lĕ⁠haẖàyòţֽ⁠wò׃"],[13,23,"לָ⁠כֵ֗ן שָׁ֚וְא לֹ֣א תֶחֱזֶ֔ינָה וְ⁠קֶ֖סֶם לֹא־תִקְסַ֣מְנָה ע֑וֹד וְ⁠הִצַּלְתִּ֤י אֶת־עַמִּ⁠י֙ מִ⁠יֶּדְ⁠כֶ֔ן וִֽ⁠ידַעְתֶּ֖ן כִּֽי־אֲנִ֥י יְהוָֽה׃","lá⁠ké֗n şá֚̌wĕʼ lò֣ʼ ţeẖèze֔ynáh wĕ⁠qe֖sem lòʼ-ţiqĕsa֣mĕnáh ʻ֑wòd wĕ⁠hiẕȧlĕţi֤̇y ʼeţ-ʻami̇⁠y֙ mi⁠yėdĕ⁠ke֔n wiֽ⁠ydaʻĕţė֖n kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[14,1,"וַ⁠יָּב֤וֹא אֵלַ⁠י֙ אֲנָשִׁ֔ים מִ⁠זִּקְנֵ֖י יִשְׂרָאֵ֑ל וַ⁠יֵּשְׁב֖וּ לְ⁠פָנָֽ⁠י׃פ","wa⁠yá̇b֤wòʼ ʼéla⁠y֙ ʼànáşǐ֔ym mi⁠zi̇qĕné֖y yişĕ̂ráʼé֑l wa⁠yé̇şĕ̌b֖ẇ lĕ⁠pánáֽ⁠y׃p"],[14,2,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[14,3,"בֶּן־אָדָ֗ם הָ⁠אֲנָשִׁ֤ים הָ⁠אֵ֨לֶּה֙ הֶעֱל֤וּ גִלּֽוּלֵי⁠הֶם֙ עַל־לִבָּ֔⁠ם וּ⁠מִכְשׁ֣וֹל עֲוֺנָ֔⁠ם נָתְנ֖וּ נֹ֣כַח פְּנֵי⁠הֶ֑ם הַ⁠אִדָּרֹ֥שׁ אִדָּרֵ֖שׁ לָ⁠הֶֽם׃ס","bėn-ʼádá֗m há⁠ʼànáşǐ֤ym há⁠ʼé֨lėh֙ heʻèl֤ẇ gilֽ̇ẇléy⁠hem֙ ʻal-libá̇֔⁠m ẇ⁠mikĕş֣̌wòl ʻàwֺná֔⁠m náţĕn֖ẇ nò֣kaẖ pĕ̇néy⁠he֑m ha⁠ʼidá̇rò֥ş̌ ʼidá̇ré֖ş̌ lá⁠heֽm׃s"],[14,4,"לָ⁠כֵ֣ן דַּבֵּר־א֠וֹתָ⁠ם וְ⁠אָמַרְתָּ֨ אֲלֵי⁠הֶ֜ם כֹּה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה אִ֣ישׁ אִ֣ישׁ מִ⁠בֵּ֣ית יִשְׂרָאֵ֡ל אֲשֶׁר֩ יַעֲלֶ֨ה אֶת־גִּלּוּלָ֜י⁠ו אֶל־לִבּ֗⁠וֹ וּ⁠מִכְשׁ֤וֹל עֲוֺנ⁠וֹ֙ יָשִׂים֙ נֹ֣כַח פָּנָ֔י⁠ו וּ⁠בָ֖א אֶל־הַ⁠נָּבִ֑יא אֲנִ֣י יְהוָ֗ה נַעֲנֵ֧יתִי ל֦⁠וֹ ב⁠ה בְּ⁠רֹ֥ב גִּלּוּלָֽי⁠ו׃","lá⁠ké֣n dȧbé̇r-ʼ֠wòţá⁠m wĕ⁠ʼámarĕţá̇֨ ʼàléy⁠he֜m kò̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h ʼi֣yş̌ ʼi֣yş̌ mi⁠bé֣̇yţ yişĕ̂ráʼé֡l ʼàşěr֩ yaʻàle֨h ʼeţ-gi̇l̇ẇlá֜y⁠w ʼel-liḃ֗⁠wò ẇ⁠mikĕş֤̌wòl ʻàwֺn⁠wò֙ yáşîym֙ nò֣kaẖ pá̇ná֔y⁠w ẇ⁠bá֖ʼ ʼel-ha⁠ná̇bi֑yʼ ʼàni֣y yĕhwá֗h naʻàné֧yţiy l֦⁠wò b⁠h bĕ̇⁠rò֥b gi̇l̇ẇláֽy⁠w׃"],[14,5,"לְמַ֛עַן תְּפֹ֥שׂ אֶת־בֵּֽית־יִשְׂרָאֵ֖ל בְּ⁠לִבָּ֑⁠ם אֲשֶׁ֤ר נָזֹ֨רוּ֙ מֵֽ⁠עָלַ֔⁠י בְּ⁠גִלּֽוּלֵי⁠הֶ֖ם כֻּלָּֽ⁠ם׃ס","lĕma֛ʻan ţĕ̇pò֥ş̂ ʼeţ-béֽ̇yţ-yişĕ̂ráʼé֖l bĕ̇⁠libá֑̇⁠m ʼàşě֤r názò֨rẇ֙ méֽ⁠ʻála֔⁠y bĕ̇⁠gilֽ̇ẇléy⁠he֖m ku̇láֽ̇⁠m׃s"],[14,6,"לָ⁠כֵ֞ן אֱמֹ֣ר ׀ אֶל־בֵּ֣ית יִשְׂרָאֵ֗ל כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה שׁ֣וּבוּ וְ⁠הָשִׁ֔יבוּ מֵ⁠עַ֖ל גִּלּֽוּלֵי⁠כֶ֑ם וּ⁠מֵ⁠עַ֥ל כָּל־תּוֹעֲבֹתֵי⁠כֶ֖ם הָשִׁ֥יבוּ פְנֵי⁠כֶֽם׃","lá⁠ké֞n ʼèmò֣r ׀ ʼel-bé֣̇yţ yişĕ̂ráʼé֗l kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ş֣̌ẇbẇ wĕ⁠háşǐ֔ybẇ mé⁠ʻa֖l gi̇lֽ̇ẇléy⁠ke֑m ẇ⁠mé⁠ʻa֥l ká̇l-ţ̇wòʻàbòţéy⁠ke֖m háşǐ֥ybẇ pĕnéy⁠keֽm׃"],[14,7,"כִּי֩ אִ֨ישׁ אִ֜ישׁ מִ⁠בֵּ֣ית יִשְׂרָאֵ֗ל וּ⁠מֵ⁠הַ⁠גֵּר֮ אֲשֶׁר־יָג֣וּר בְּ⁠יִשְׂרָאֵל֒ וְ⁠יִנָּזֵ֣ר מֵֽ⁠אַחֲרַ֗⁠י וְ⁠יַ֤עַל גִּלּוּלָי⁠ו֙ אֶל־לִבּ֔⁠וֹ וּ⁠מִכְשׁ֣וֹל עֲוֺנ֔⁠וֹ יָשִׂ֖ים נֹ֣כַח פָּנָ֑י⁠ו וּ⁠בָ֤א אֶל־הַ⁠נָּבִיא֙ לִ⁠דְרָשׁ־ל֣⁠וֹ בִ֔⁠י אֲנִ֣י יְהוָ֔ה נַֽעֲנֶה־לּ֖⁠וֹ בִּֽ⁠י׃","ki̇y֩ ʼi֨yş̌ ʼi֜yş̌ mi⁠bé֣̇yţ yişĕ̂ráʼé֗l ẇ⁠mé⁠ha⁠gé̇r֮ ʼàşěr-yág֣ẇr bĕ̇⁠yişĕ̂ráʼél֒ wĕ⁠yiná̇zé֣r méֽ⁠ʼaẖàra֗⁠y wĕ⁠ya֤ʻal gi̇l̇ẇláy⁠w֙ ʼel-liḃ֔⁠wò ẇ⁠mikĕş֣̌wòl ʻàwֺn֔⁠wò yáşî֖ym nò֣kaẖ pá̇ná֑y⁠w ẇ⁠bá֤ʼ ʼel-ha⁠ná̇biyʼ֙ li⁠dĕráş̌-l֣⁠wò bi֔⁠y ʼàni֣y yĕhwá֔h naֽʻàneh-l֖̇⁠wò biֽ̇⁠y׃"],[14,8,"וְ⁠נָתַתִּ֨י פָנַ֜⁠י בָּ⁠אִ֣ישׁ הַ⁠ה֗וּא וַ⁠הֲשִֽׂמֹתִ֨י⁠הוּ֙ לְ⁠א֣וֹת וְ⁠לִ⁠מְשָׁלִ֔ים וְ⁠הִכְרַתִּ֖י⁠ו מִ⁠תּ֣וֹךְ עַמִּ֑⁠י וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃ס","wĕ⁠náţaţi̇֨y pána֜⁠y bá̇⁠ʼi֣yş̌ ha⁠h֗ẇʼ wa⁠hàşîֽmòţi֨y⁠hẇ֙ lĕ⁠ʼ֣wòţ wĕ⁠li⁠mĕşá̌li֔ym wĕ⁠hikĕraţi֖̇y⁠w mi⁠ţ֣̇wòkĕ ʻami֑̇⁠y wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃s"],[14,9,"וְ⁠הַ⁠נָּבִ֤יא כִֽי־יְפֻתֶּה֙ וְ⁠דִבֶּ֣ר דָּבָ֔ר אֲנִ֤י יְהוָה֙ פִּתֵּ֔יתִי אֵ֖ת הַ⁠נָּבִ֣יא הַ⁠ה֑וּא וְ⁠נָטִ֤יתִי אֶת־יָדִ⁠י֙ עָלָ֔י⁠ו וְ⁠הִ֨שְׁמַדְתִּ֔י⁠ו מִ⁠תּ֖וֹךְ עַמִּ֥⁠י יִשְׂרָאֵֽל׃","wĕ⁠ha⁠ná̇bi֤yʼ kiֽy-yĕpuţėh֙ wĕ⁠dibė֣r dá̇bá֔r ʼàni֤y yĕhwáh֙ pi̇ţé̇֔yţiy ʼé֖ţ ha⁠ná̇bi֣yʼ ha⁠h֑ẇʼ wĕ⁠náti֤yţiy ʼeţ-yádi⁠y֙ ʻálá֔y⁠w wĕ⁠hi֨şĕ̌madĕţi̇֔y⁠w mi⁠ţ֖̇wòkĕ ʻami֥̇⁠y yişĕ̂ráʼéֽl׃"],[14,10,"וְ⁠נָשְׂא֖וּ עֲוֺנָ֑⁠ם כַּֽ⁠עֲוֺן֙ הַ⁠דֹּרֵ֔שׁ כַּ⁠עֲוֺ֥ן הַ⁠נָּבִ֖יא יִֽהְיֶֽה׃","wĕ⁠náşĕ̂ʼ֖ẇ ʻàwֺná֑⁠m kȧֽ⁠ʻàwֺn֙ ha⁠dò̇ré֔ş̌ kȧ⁠ʻàwֺ֥n ha⁠ná̇bi֖yʼ yiֽhĕyeֽh׃"],[14,11,"לְ֠מַעַן לֹֽא־יִתְע֨וּ ע֤וֹד בֵּֽית־יִשְׂרָאֵל֙ מֵ⁠אַֽחֲרַ֔⁠י וְ⁠לֹֽא־יִטַּמְּא֥וּ ע֖וֹד בְּ⁠כָל־פִּשְׁעֵי⁠הֶ֑ם וְ⁠הָ֥יוּ לִ֣⁠י לְ⁠עָ֗ם וַֽ⁠אֲנִי֙ אֶהְיֶ֤ה לָ⁠הֶם֙ לֵֽ⁠אלֹהִ֔ים נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","lĕ֠maʻan lòֽʼ-yiţĕʻ֨ẇ ʻ֤wòd béֽ̇yţ-yişĕ̂ráʼél֙ mé⁠ʼaֽẖàra֔⁠y wĕ⁠lòֽʼ-yitȧmĕ̇ʼ֥ẇ ʻ֖wòd bĕ̇⁠kál-pi̇şĕ̌ʻéy⁠he֑m wĕ⁠há֥yẇ li֣⁠y lĕ⁠ʻá֗m waֽ⁠ʼàniy֙ ʼehĕye֤h lá⁠hem֙ léֽ⁠ʼlòhi֔ym nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[14,12,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[14,13,"בֶּן־אָדָ֗ם אֶ֚רֶץ כִּ֤י תֶחֱטָא־לִ⁠י֙ לִ⁠מְעָל־מַ֔עַל וְ⁠נָטִ֤יתִי יָדִ⁠י֙ עָלֶ֔י⁠הָ וְ⁠שָׁבַ֥רְתִּי לָ֖⁠הּ מַטֵּה־לָ֑חֶם וְ⁠הִשְׁלַחְתִּי־בָ֣⁠הּ רָעָ֔ב וְ⁠הִכְרַתִּ֥י מִמֶּ֖⁠נָּה אָדָ֥ם וּ⁠בְהֵמָֽה׃","bėn-ʼádá֗m ʼe֚reẕ ki֤̇y ţeẖètáʼ-li⁠y֙ li⁠mĕʻál-ma֔ʻal wĕ⁠náti֤yţiy yádi⁠y֙ ʻále֔y⁠há wĕ⁠şá̌ba֥rĕţi̇y lá֖⁠ḣ maté̇h-lá֑ẖem wĕ⁠hişĕ̌laẖĕţi̇y-bá֣⁠ḣ ráʻá֔b wĕ⁠hikĕraţi֥̇y mimė֖⁠ná̇h ʼádá֥m ẇ⁠bĕhémáֽh׃"],[14,14,"וְ֠⁠הָיוּ שְׁלֹ֨שֶׁת הָ⁠אֲנָשִׁ֤ים הָ⁠אֵ֨לֶּה֙ בְּ⁠תוֹכָ֔⁠הּ נֹ֖חַ דנאל וְ⁠אִיּ֑וֹב הֵ֤מָּה בְ⁠צִדְקָתָ⁠ם֙ יְנַצְּל֣וּ נַפְשָׁ֔⁠ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wĕ֠⁠háyẇ şĕ̌lò֨şěţ há⁠ʼànáşǐ֤ym há⁠ʼé֨lėh֙ bĕ̇⁠ţwòká֔⁠ḣ nò֖ẖa dnʼl wĕ⁠ʼiẏ֑wòb hé֤má̇h bĕ⁠ẕidĕqáţá⁠m֙ yĕnaẕĕ̇l֣ẇ napĕşá̌֔⁠m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[14,15,"לֽוּ־חַיָּ֥ה רָעָ֛ה אַעֲבִ֥יר בָּ⁠אָ֖רֶץ וְ⁠שִׁכְּלָ֑תָּ⁠ה וְ⁠הָיְתָ֤ה שְׁמָמָה֙ מִ⁠בְּלִ֣י עוֹבֵ֔ר מִ⁠פְּנֵ֖י הַ⁠חַיָּֽה׃","lֽẇ-ẖayá֥̇h ráʻá֛h ʼaʻàbi֥yr bá̇⁠ʼá֖reẕ wĕ⁠şǐkĕ̇lá֑ţá̇⁠h wĕ⁠háyĕţá֤h şĕ̌mámáh֙ mi⁠bĕ̇li֣y ʻwòbé֔r mi⁠pĕ̇né֖y ha⁠ẖayáֽ̇h׃"],[14,16,"שְׁלֹ֨שֶׁת הָ⁠אֲנָשִׁ֣ים הָ⁠אֵלֶּה֮ בְּ⁠תוֹכָ⁠הּ֒ חַי־אָ֗נִי נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה אִם־בָּנִ֥ים וְ⁠אִם־בָּנ֖וֹת יַצִּ֑ילוּ הֵ֤מָּה לְ⁠בַדָּ⁠ם֙ יִנָּצֵ֔לוּ וְ⁠הָ⁠אָ֖רֶץ תִּהְיֶ֥ה שְׁמָמָֽה׃","şĕ̌lò֨şěţ há⁠ʼànáşǐ֣ym há⁠ʼélėh֮ bĕ̇⁠ţwòká⁠ḣ֒ ẖay-ʼá֗niy nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h ʼim-bá̇ni֥ym wĕ⁠ʼim-bá̇n֖wòţ yaẕi֑̇ylẇ hé֤má̇h lĕ⁠badá̇⁠m֙ yiná̇ẕé֔lẇ wĕ⁠há⁠ʼá֖reẕ ţi̇hĕye֥h şĕ̌mámáֽh׃"],[14,17,"א֛וֹ חֶ֥רֶב אָבִ֖יא עַל־הָ⁠אָ֣רֶץ הַ⁠הִ֑יא וְ⁠אָמַרְתִּ֗י חֶ֚רֶב תַּעֲבֹ֣ר בָּ⁠אָ֔רֶץ וְ⁠הִכְרַתִּ֥י מִמֶּ֖⁠נָּה אָדָ֥ם וּ⁠בְהֵמָֽה׃","ʼ֛wò ẖe֥reb ʼábi֖yʼ ʻal-há⁠ʼá֣reẕ ha⁠hi֑yʼ wĕ⁠ʼámarĕţi̇֗y ẖe֚reb ţȧʻàbò֣r bá̇⁠ʼá֔reẕ wĕ⁠hikĕraţi֥̇y mimė֖⁠ná̇h ʼádá֥m ẇ⁠bĕhémáֽh׃"],[14,18,"וּ⁠שְׁלֹ֨שֶׁת הָ⁠אֲנָשִׁ֣ים הָ⁠אֵלֶּה֮ בְּ⁠תוֹכָ⁠הּ֒ חַי־אָ֗נִי נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה לֹ֥א יַצִּ֖ילוּ בָּנִ֣ים וּ⁠בָנ֑וֹת כִּ֛י הֵ֥ם לְ⁠בַדָּ֖⁠ם יִנָּצֵֽלוּ׃","ẇ⁠şĕ̌lò֨şěţ há⁠ʼànáşǐ֣ym há⁠ʼélėh֮ bĕ̇⁠ţwòká⁠ḣ֒ ẖay-ʼá֗niy nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h lò֥ʼ yaẕi֖̇ylẇ bá̇ni֣ym ẇ⁠bán֑wòţ ki֛̇y hé֥m lĕ⁠badá֖̇⁠m yiná̇ẕéֽlẇ׃"],[14,19,"א֛וֹ דֶּ֥בֶר אֲשַׁלַּ֖ח אֶל־הָ⁠אָ֣רֶץ הַ⁠הִ֑יא וְ⁠שָׁפַכְתִּ֨י חֲמָתִ֤⁠י עָלֶ֨י⁠הָ֙ בְּ⁠דָ֔ם לְ⁠הַכְרִ֥ית מִמֶּ֖⁠נָּה אָדָ֥ם וּ⁠בְהֵמָֽה׃","ʼ֛wò dė֥ber ʼàşǎlȧ֖ẖ ʼel-há⁠ʼá֣reẕ ha⁠hi֑yʼ wĕ⁠şá̌pakĕţi̇֨y ẖàmáţi֤⁠y ʻále֨y⁠há֙ bĕ̇⁠dá֔m lĕ⁠hakĕri֥yţ mimė֖⁠ná̇h ʼádá֥m ẇ⁠bĕhémáֽh׃"],[14,20,"וְ⁠נֹ֨חַ דנאל וְ⁠אִיּוֹב֮ בְּ⁠תוֹכָ⁠הּ֒ חַי־אָ֗נִי נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה אִם־בֵּ֥ן אִם־בַּ֖ת יַצִּ֑ילוּ הֵ֥מָּה בְ⁠צִדְקָתָ֖⁠ם יַצִּ֥ילוּ נַפְשָֽׁ⁠ם׃פ","wĕ⁠nò֨ẖa dnʼl wĕ⁠ʼiẏwòb֮ bĕ̇⁠ţwòká⁠ḣ֒ ẖay-ʼá֗niy nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h ʼim-bé֥̇n ʼim-bȧ֖ţ yaẕi֑̇ylẇ hé֥má̇h bĕ⁠ẕidĕqáţá֖⁠m yaẕi֥̇ylẇ napĕşáֽ̌⁠m׃p"],[14,21,"כִּי֩ כֹ֨ה אָמַ֜ר אֲדֹנָ֣⁠י יְהֹוִ֗ה אַ֣ף כִּֽי־אַרְבַּ֣עַת שְׁפָטַ֣⁠י ׀ הָ⁠רָעִ֡ים חֶ֠רֶב וְ⁠רָעָ֞ב וְ⁠חַיָּ֤ה רָעָה֙ וָ⁠דֶ֔בֶר שִׁלַּ֖חְתִּי אֶל־יְרוּשָׁלִָ֑ם לְ⁠הַכְרִ֥ית מִמֶּ֖⁠נָּה אָדָ֥ם וּ⁠בְהֵמָֽה׃","ki̇y֩ kò֨h ʼáma֜r ʼàdòná֣⁠y yĕhòwi֗h ʼa֣p kiֽ̇y-ʼarĕbȧ֣ʻaţ şĕ̌páta֣⁠y ׀ há⁠ráʻi֡ym ẖe֠reb wĕ⁠ráʻá֞b wĕ⁠ẖayá֤̇h ráʻáh֙ wá⁠de֔ber şǐlȧ֖ẖĕţi̇y ʼel-yĕrẇşá̌liá֑m lĕ⁠hakĕri֥yţ mimė֖⁠ná̇h ʼádá֥m ẇ⁠bĕhémáֽh׃"],[14,22,"וְ⁠הִנֵּ֨ה נֽוֹתְרָה־בָּ֜⁠הּ פְּלֵטָ֗ה הַֽ⁠מּוּצָאִים֮ בָּנִ֣ים וּ⁠בָנוֹת֒ הִנָּ⁠ם֙ יוֹצְאִ֣ים אֲלֵי⁠כֶ֔ם וּ⁠רְאִיתֶ֥ם אֶת־דַּרְכָּ֖⁠ם וְ⁠אֶת־עֲלִֽילוֹתָ֑⁠ם וְ⁠נִחַמְתֶּ֗ם עַל־הָֽ⁠רָעָה֙ אֲשֶׁ֤ר הֵבֵ֨אתִי֙ עַל־יְר֣וּשָׁלִַ֔ם אֵ֛ת כָּל־אֲשֶׁ֥ר הֵבֵ֖אתִי עָלֶֽי⁠הָ׃","wĕ⁠hiné̇֨h nֽwòţĕráh-bá̇֜⁠ḣ pĕ̇létá֗h haֽ⁠ṁẇẕáʼiym֮ bá̇ni֣ym ẇ⁠bánwòţ֒ hiná̇⁠m֙ ywòẕĕʼi֣ym ʼàléy⁠ke֔m ẇ⁠rĕʼiyţe֥m ʼeţ-dȧrĕká֖̇⁠m wĕ⁠ʼeţ-ʻàliֽylwòţá֑⁠m wĕ⁠niẖamĕţė֗m ʻal-háֽ⁠ráʻáh֙ ʼàşě֤r hébé֨ʼţiy֙ ʻal-yĕr֣ẇşá̌lia֔m ʼé֛ţ ká̇l-ʼàşě֥r hébé֖ʼţiy ʻáleֽy⁠há׃"],[14,23,"וְ⁠נִחֲמ֣וּ אֶתְ⁠כֶ֔ם כִּֽי־תִרְא֥וּ אֶת־דַּרְכָּ֖⁠ם וְ⁠אֶת־עֲלִֽילוֹתָ֑⁠ם וִֽ⁠ידַעְתֶּ֗ם כִּי֩ לֹ֨א חִנָּ֤ם עָשִׂ֨יתִי֙ אֵ֣ת כָּל־אֲשֶׁר־עָשִׂ֣יתִי בָ֔⁠הּ נְאֻ֖ם אֲדֹנָ֥⁠י יְהֹוִֽה׃פ","wĕ⁠niẖàm֣ẇ ʼeţĕ⁠ke֔m kiֽ̇y-ţirĕʼ֥ẇ ʼeţ-dȧrĕká֖̇⁠m wĕ⁠ʼeţ-ʻàliֽylwòţá֑⁠m wiֽ⁠ydaʻĕţė֗m ki̇y֩ lò֨ʼ ẖiná֤̇m ʻáşî֨yţiy֙ ʼé֣ţ ká̇l-ʼàşěr-ʻáşî֣yţiy bá֔⁠ḣ nĕʼu֖m ʼàdòná֥⁠y yĕhòwiֽh׃p"],[15,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[15,2,"בֶּן־אָדָ֕ם מַה־יִּֽהְיֶ֥ה עֵץ־הַ⁠גֶּ֖פֶן מִ⁠כָּל־עֵ֑ץ הַ⁠זְּמוֹרָ֕ה אֲשֶׁ֥ר הָיָ֖ה בַּ⁠עֲצֵ֥י הַ⁠יָּֽעַר׃","bėn-ʼádá֕m mah-yiֽ̇hĕye֥h ʻéẕ-ha⁠gė֖pen mi⁠ká̇l-ʻé֑ẕ ha⁠zĕ̇mwòrá֕h ʼàşě֥r háyá֖h bȧ⁠ʻàẕé֥y ha⁠yáֽ̇ʻar׃"],[15,3,"הֲ⁠יֻקַּ֤ח מִמֶּ֨⁠נּוּ֙ עֵ֔ץ לַ⁠עֲשׂ֖וֹת לִ⁠מְלָאכָ֑ה אִם־יִקְח֤וּ מִמֶּ֨⁠נּוּ֙ יָתֵ֔ד לִ⁠תְל֥וֹת עָלָ֖י⁠ו כָּל־כֶּֽלִי׃","hà⁠yuqȧ֤ẖ mimė֨⁠ṅẇ֙ ʻé֔ẕ la⁠ʻàş֖̂wòţ li⁠mĕláʼká֑h ʼim-yiqĕẖ֤ẇ mimė֨⁠ṅẇ֙ yáţé֔d li⁠ţĕl֥wòţ ʻálá֖y⁠w ká̇l-kėֽliy׃"],[15,4,"הִנֵּ֥ה לָ⁠אֵ֖שׁ נִתַּ֣ן לְ⁠אָכְלָ֑ה אֵת֩ שְׁנֵ֨י קְצוֹתָ֜י⁠ו אָכְלָ֤ה הָ⁠אֵשׁ֙ וְ⁠תוֹכ֣⁠וֹ נָחָ֔ר הֲ⁠יִצְלַ֖ח לִ⁠מְלָאכָֽה׃","hiné֥̇h lá⁠ʼé֖ş̌ niţȧ֣n lĕ⁠ʼákĕlá֑h ʼéţ֩ şĕ̌né֨y qĕẕwòţá֜y⁠w ʼákĕlá֤h há⁠ʼéş̌֙ wĕ⁠ţwòk֣⁠wò náẖá֔r hà⁠yiẕĕla֖ẖ li⁠mĕláʼkáֽh׃"],[15,5,"הִנֵּה֙ בִּֽ⁠הְיוֹת֣⁠וֹ תָמִ֔ים לֹ֥א יֵֽעָשֶׂ֖ה לִ⁠מְלָאכָ֑ה אַ֣ף כִּי־אֵ֤שׁ אֲכָלַ֨תְ⁠הוּ֙ וַ⁠יֵּחָ֔ר וְ⁠נַעֲשָׂ֥ה ע֖וֹד לִ⁠מְלָאכָֽה׃ס","hiné̇h֙ biֽ̇⁠hĕywòţ֣⁠wò ţámi֔ym lò֥ʼ yéֽʻáşê֖h li⁠mĕláʼká֑h ʼa֣p ki̇y-ʼé֤ş̌ ʼàkála֨ţĕ⁠hẇ֙ wa⁠yé̇ẖá֔r wĕ⁠naʻàşá֥̂h ʻ֖wòd li⁠mĕláʼkáֽh׃s"],[15,6,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה כַּ⁠אֲשֶׁ֤ר עֵץ־הַ⁠גֶּ֨פֶן֙ בְּ⁠עֵ֣ץ הַ⁠יַּ֔עַר אֲשֶׁר־נְתַתִּ֥י⁠ו לָ⁠אֵ֖שׁ לְ⁠אָכְלָ֑ה כֵּ֣ן נָתַ֔תִּי אֶת־יֹשְׁבֵ֖י יְרוּשָׁלִָֽם׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h kȧ⁠ʼàşě֤r ʻéẕ-ha⁠gė֨pen֙ bĕ̇⁠ʻé֣ẕ ha⁠yȧ֔ʻar ʼàşěr-nĕţaţi֥̇y⁠w lá⁠ʼé֖ş̌ lĕ⁠ʼákĕlá֑h ké֣̇n náţa֔ţi̇y ʼeţ-yòşĕ̌bé֖y yĕrẇşá̌liáֽm׃"],[15,7,"וְ⁠נָתַתִּ֤י אֶת־פָּנַ⁠י֙ בָּ⁠הֶ֔ם מֵ⁠הָ⁠אֵ֣שׁ יָצָ֔אוּ וְ⁠הָ⁠אֵ֖שׁ תֹּֽאכְלֵ֑⁠ם וִֽ⁠ידַעְתֶּם֙ כִּֽי־אֲנִ֣י יְהוָ֔ה בְּ⁠שׂוּמִ֥⁠י אֶת־פָּנַ֖⁠י בָּ⁠הֶֽם׃","wĕ⁠náţaţi֤̇y ʼeţ-pá̇na⁠y֙ bá̇⁠he֔m mé⁠há⁠ʼé֣ş̌ yáẕá֔ʼẇ wĕ⁠há⁠ʼé֖ş̌ ţòֽ̇ʼkĕlé֑⁠m wiֽ⁠ydaʻĕţėm֙ kiֽ̇y-ʼàni֣y yĕhwá֔h bĕ̇⁠ş̂ẇmi֥⁠y ʼeţ-pá̇na֖⁠y bá̇⁠heֽm׃"],[15,8,"וְ⁠נָתַתִּ֥י אֶת־הָ⁠אָ֖רֶץ שְׁמָמָ֑ה יַ֚עַן מָ֣עֲלוּ מַ֔עַל נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","wĕ⁠náţaţi֥̇y ʼeţ-há⁠ʼá֖reẕ şĕ̌mámá֑h ya֚ʻan má֣ʻàlẇ ma֔ʻal nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[16,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[16,2,"בֶּן־אָדָ֕ם הוֹדַ֥ע אֶת־יְרוּשָׁלִַ֖ם אֶת־תּוֹעֲבֹתֶֽי⁠הָ׃","bėn-ʼádá֕m hwòda֥ʻ ʼeţ-yĕrẇşá̌lia֖m ʼeţ-ţ̇wòʻàbòţeֽy⁠há׃"],[16,3,"וְ⁠אָמַרְתָּ֞ כֹּה־אָמַ֨ר אֲדֹנָ֤⁠י יְהוִה֙ לִ⁠יר֣וּשָׁלִַ֔ם מְכֹרֹתַ֨יִ⁠ךְ֙ וּ⁠מֹ֣לְדֹתַ֔יִ⁠ךְ מֵ⁠אֶ֖רֶץ הַֽ⁠כְּנַעֲנִ֑י אָבִ֥י⁠ךְ הָ⁠אֱמֹרִ֖י וְ⁠אִמֵּ֥⁠ךְ חִתִּֽית׃","wĕ⁠ʼámarĕţá̇֞ kò̇h-ʼáma֨r ʼàdòná֤⁠y yĕhwih֙ li⁠yr֣ẇşá̌lia֔m mĕkòròţa֨yi⁠kĕ֙ ẇ⁠mò֣lĕdòţa֔yi⁠kĕ mé⁠ʼe֖reẕ haֽ⁠kĕ̇naʻàni֑y ʼábi֥y⁠kĕ há⁠ʼèmòri֖y wĕ⁠ʼimé֥̇⁠kĕ ẖiţiֽ̇yţ׃"],[16,4,"וּ⁠מוֹלְדוֹתַ֗יִ⁠ךְ בְּ⁠י֨וֹם הוּלֶּ֤דֶת אֹתָ⁠ךְ֙ לֹֽא־כָרַּ֣ת שָׁרֵּ֔⁠ךְ וּ⁠בְ⁠מַ֥יִם לֹֽא־רֻחַ֖צְתְּ לְ⁠מִשְׁעִ֑י וְ⁠הָמְלֵ֨חַ֙ לֹ֣א הֻמְלַ֔חַתְּ וְ⁠הָחְתֵּ֖ל לֹ֥א חֻתָּֽלְתְּ׃","ẇ⁠mwòlĕdwòţa֗yi⁠kĕ bĕ̇⁠y֨wòm hẇlė֤deţ ʼòţá⁠kĕ֙ lòֽʼ-kárȧ֣ţ şá̌ré̇֔⁠kĕ ẇ⁠bĕ⁠ma֥yim lòֽʼ-ruẖa֖ẕĕţĕ̇ lĕ⁠mişĕ̌ʻi֑y wĕ⁠hámĕlé֨ẖa֙ lò֣ʼ humĕla֔ẖaţĕ̇ wĕ⁠háẖĕţé֖̇l lò֥ʼ ẖuţáֽ̇lĕţĕ̇׃"],[16,5,"לֹא־חָ֨סָה עָלַ֜יִ⁠ךְ עַ֗יִן לַ⁠עֲשׂ֥וֹת לָ֛⁠ךְ אַחַ֥ת מֵ⁠אֵ֖לֶּה לְ⁠חֻמְלָ֣ה עָלָ֑יִ⁠ךְ וַֽ⁠תֻּשְׁלְכִ֞י אֶל־פְּנֵ֤י הַ⁠שָּׂדֶה֙ בְּ⁠גֹ֣עַל נַפְשֵׁ֔⁠ךְ בְּ⁠י֖וֹם הֻלֶּ֥דֶת אֹתָֽ⁠ךְ׃","lòʼ-ẖá֨sáh ʻála֜yi⁠kĕ ʻa֗yin la⁠ʻàş֥̂wòţ lá֛⁠kĕ ʼaẖa֥ţ mé⁠ʼé֖lėh lĕ⁠ẖumĕlá֣h ʻálá֑yi⁠kĕ waֽ⁠ţu̇şĕ̌lĕki֞y ʼel-pĕ̇né֤y ha⁠şá̇̂deh֙ bĕ̇⁠gò֣ʻal napĕşé̌֔⁠kĕ bĕ̇⁠y֖wòm hulė֥deţ ʼòţáֽ⁠kĕ׃"],[16,6,"וָ⁠אֶעֱבֹ֤ר עָלַ֨יִ⁠ךְ֙ וָֽ⁠אֶרְאֵ֔⁠ךְ מִתְבּוֹסֶ֖סֶת בְּ⁠דָמָ֑יִ⁠ךְ וָ⁠אֹ֤מַר לָ⁠ךְ֙ בְּ⁠דָמַ֣יִ⁠ךְ חֲיִ֔י וָ⁠אֹ֥מַר לָ֖⁠ךְ בְּ⁠דָמַ֥יִ⁠ךְ חֲיִֽי׃","wá⁠ʼeʻèbò֤r ʻála֨yi⁠kĕ֙ wáֽ⁠ʼerĕʼé֔⁠kĕ miţĕḃwòse֖seţ bĕ̇⁠dámá֑yi⁠kĕ wá⁠ʼò֤mar lá⁠kĕ֙ bĕ̇⁠dáma֣yi⁠kĕ ẖàyi֔y wá⁠ʼò֥mar lá֖⁠kĕ bĕ̇⁠dáma֥yi⁠kĕ ẖàyiֽy׃"],[16,7,"רְבָבָ֗ה כְּ⁠צֶ֤מַח הַ⁠שָּׂדֶה֙ נְתַתִּ֔י⁠ךְ וַ⁠תִּרְבִּי֙ וַֽ⁠תִּגְדְּלִ֔י וַ⁠תָּבֹ֖אִי בַּ⁠עֲדִ֣י עֲדָיִ֑ים שָׁדַ֤יִם נָכֹ֨נוּ֙ וּ⁠שְׂעָרֵ֣⁠ךְ צִמֵּ֔חַ וְ⁠אַ֖תְּ עֵרֹ֥ם וְ⁠עֶרְיָֽה׃","rĕbábá֗h kĕ̇⁠ẕe֤maẖ ha⁠şá̇̂deh֙ nĕţaţi̇֔y⁠kĕ wa⁠ţi̇rĕbi̇y֙ waֽ⁠ţi̇gĕdĕ̇li֔y wa⁠ţá̇bò֖ʼiy bȧ⁠ʻàdi֣y ʻàdáyi֑ym şá̌da֤yim nákò֨nẇ֙ ẇ⁠şĕ̂ʻáré֣⁠kĕ ẕimé̇֔ẖa wĕ⁠ʼa֖ţĕ̇ ʻérò֥m wĕ⁠ʻerĕyáֽh׃"],[16,8,"וָ⁠אֶעֱבֹ֨ר עָלַ֜יִ⁠ךְ וָ⁠אֶרְאֵ֗⁠ךְ וְ⁠הִנֵּ֤ה עִתֵּ⁠ךְ֙ עֵ֣ת דֹּדִ֔ים וָ⁠אֶפְרֹ֤שׂ כְּנָפִ⁠י֙ עָלַ֔יִ⁠ךְ וָ⁠אֲכַסֶּ֖ה עֶרְוָתֵ֑⁠ךְ וָ⁠אֶשָּׁ֣בַֽע לָ֠⁠ךְ וָ⁠אָב֨וֹא בִ⁠בְרִ֜ית אֹתָ֗⁠ךְ נְאֻ֛ם אֲדֹנָ֥⁠י יְהוִ֖ה וַ⁠תִּ֥הְיִי לִֽ⁠י׃","wá⁠ʼeʻèbò֨r ʻála֜yi⁠kĕ wá⁠ʼerĕʼé֗⁠kĕ wĕ⁠hiné֤̇h ʻiţé̇⁠kĕ֙ ʻé֣ţ dò̇di֔ym wá⁠ʼepĕrò֤ş̂ kĕ̇nápi⁠y֙ ʻála֔yi⁠kĕ wá⁠ʼàkasė֖h ʻerĕwáţé֑⁠kĕ wá⁠ʼeşá֣̇̌baֽʻ lá֠⁠kĕ wá⁠ʼáb֨wòʼ bi⁠bĕri֜yţ ʼòţá֗⁠kĕ nĕʼu֛m ʼàdòná֥⁠y yĕhwi֖h wa⁠ţi֥̇hĕyiy liֽ⁠y׃"],[16,9,"וָ⁠אֶרְחָצֵ֣⁠ךְ בַּ⁠מַּ֔יִם וָ⁠אֶשְׁטֹ֥ף דָּמַ֖יִ⁠ךְ מֵֽ⁠עָלָ֑יִ⁠ךְ וָ⁠אֲסֻכֵ֖⁠ךְ בַּ⁠שָּֽׁמֶן׃","wá⁠ʼerĕẖáẕé֣⁠kĕ bȧ⁠mȧ֔yim wá⁠ʼeşĕ̌tò֥p dá̇ma֖yi⁠kĕ méֽ⁠ʻálá֑yi⁠kĕ wá⁠ʼàsuké֖⁠kĕ bȧ⁠şáֽ̇̌men׃"],[16,10,"וָ⁠אַלְבִּישֵׁ֣⁠ךְ רִקְמָ֔ה וָ⁠אֶנְעֲלֵ֖⁠ךְ תָּ֑חַשׁ וָ⁠אֶחְבְּשֵׁ֣⁠ךְ בַּ⁠שֵּׁ֔שׁ וַ⁠אֲכַסֵּ֖⁠ךְ מֶֽשִׁי׃","wá⁠ʼalĕbi̇yşé֣̌⁠kĕ riqĕmá֔h wá⁠ʼenĕʻàlé֖⁠kĕ ţá֑̇ẖaş̌ wá⁠ʼeẖĕbĕ̇şé֣̌⁠kĕ bȧ⁠şé̇̌֔ş̌ wa⁠ʼàkasé֖̇⁠kĕ meֽşǐy׃"],[16,11,"וָ⁠אֶעְדֵּ֖⁠ךְ עֶ֑דִי וָ⁠אֶתְּנָ֤⁠ה צְמִידִים֙ עַל־יָדַ֔יִ⁠ךְ וְ⁠רָבִ֖יד עַל־גְּרוֹנֵֽ⁠ךְ׃","wá⁠ʼeʻĕdé֖̇⁠kĕ ʻe֑diy wá⁠ʼeţĕ̇ná֤⁠h ẕĕmiydiym֙ ʻal-yáda֔yi⁠kĕ wĕ⁠rábi֖yd ʻal-gĕ̇rwònéֽ⁠kĕ׃"],[16,12,"וָ⁠אֶתֵּ֥ן נֶ֨זֶם֙ עַל־אַפֵּ֔⁠ךְ וַ⁠עֲגִילִ֖ים עַל־אָזְנָ֑יִ⁠ךְ וַ⁠עֲטֶ֥רֶת תִּפְאֶ֖רֶת בְּ⁠רֹאשֵֽׁ⁠ךְ׃","wá⁠ʼeţé֥̇n ne֨zem֙ ʻal-ʼapé̇֔⁠kĕ wa⁠ʻàgiyli֖ym ʻal-ʼázĕná֑yi⁠kĕ wa⁠ʻàte֥reţ ţi̇pĕʼe֖reţ bĕ̇⁠ròʼşéֽ̌⁠kĕ׃"],[16,13,"וַ⁠תַּעְדִּ֞י זָהָ֣ב וָ⁠כֶ֗סֶף וּ⁠מַלְבּוּשֵׁ⁠ךְ֙ ששי וָ⁠מֶ֨שִׁי֙ וְ⁠רִקְמָ֔ה סֹ֧לֶת וּ⁠דְבַ֛שׁ וָ⁠שֶׁ֖מֶן אכלתי וַ⁠תִּ֨יפִי֙ בִּ⁠מְאֹ֣ד מְאֹ֔ד וַֽ⁠תִּצְלְחִ֖י לִ⁠מְלוּכָֽה׃","wa⁠ţȧʻĕdi̇֞y záhá֣b wá⁠ke֗sep ẇ⁠malĕḃẇşé̌⁠kĕ֙ şşy wá⁠me֨şǐy֙ wĕ⁠riqĕmá֔h sò֧leţ ẇ⁠dĕba֛ş̌ wá⁠şě֖men ʼklţy wa⁠ţi̇֨ypiy֙ bi̇⁠mĕʼò֣d mĕʼò֔d waֽ⁠ţi̇ẕĕlĕẖi֖y li⁠mĕlẇkáֽh׃"],[16,14,"וַ⁠יֵּ֨צֵא לָ֥⁠ךְ שֵׁ֛ם בַּ⁠גּוֹיִ֖ם בְּ⁠יָפְיֵ֑⁠ךְ כִּ֣י ׀ כָּלִ֣יל ה֗וּא בַּֽ⁠הֲדָרִ⁠י֙ אֲשֶׁר־שַׂ֣מְתִּי עָלַ֔יִ⁠ךְ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wa⁠yé̇֨ẕéʼ lá֥⁠kĕ şé֛̌m bȧ⁠ġwòyi֖m bĕ̇⁠yápĕyé֑⁠kĕ ki֣̇y ׀ ká̇li֣yl h֗ẇʼ bȧֽ⁠hàdári⁠y֙ ʼàşěr-şâ֣mĕţi̇y ʻála֔yi⁠kĕ nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[16,15,"וַ⁠תִּבְטְחִ֣י בְ⁠יָפְיֵ֔⁠ךְ וַ⁠תִּזְנִ֖י עַל־שְׁמֵ֑⁠ךְ וַ⁠תִּשְׁפְּכִ֧י אֶת־תַּזְנוּתַ֛יִ⁠ךְ עַל־כָּל־עוֹבֵ֖ר ל⁠וֹ־יֶֽהִי׃","wa⁠ţi̇bĕtĕẖi֣y bĕ⁠yápĕyé֔⁠kĕ wa⁠ţi̇zĕni֖y ʻal-şĕ̌mé֑⁠kĕ wa⁠ţi̇şĕ̌pĕ̇ki֧y ʼeţ-ţȧzĕnẇţa֛yi⁠kĕ ʻal-ká̇l-ʻwòbé֖r l⁠wò-yeֽhiy׃"],[16,16,"וַ⁠תִּקְחִ֣י מִ⁠בְּגָדַ֗יִ⁠ךְ וַ⁠תַּֽעֲשִׂי־לָ⁠ךְ֙ בָּמ֣וֹת טְלֻא֔וֹת וַ⁠תִּזְנִ֖י עֲלֵי⁠הֶ֑ם לֹ֥א בָא֖וֹת וְ⁠לֹ֥א יִהְיֶֽה׃","wa⁠ţi̇qĕẖi֣y mi⁠bĕ̇gáda֗yi⁠kĕ wa⁠ţȧֽʻàşîy-lá⁠kĕ֙ bá̇m֣wòţ tĕluʼ֔wòţ wa⁠ţi̇zĕni֖y ʻàléy⁠he֑m lò֥ʼ báʼ֖wòţ wĕ⁠lò֥ʼ yihĕyeֽh׃"],[16,17,"וַ⁠תִּקְחִ֞י כְּלֵ֣י תִפְאַרְתֵּ֗⁠ךְ מִ⁠זְּהָבִ֤⁠י וּ⁠מִ⁠כַּסְפִּ⁠י֙ אֲשֶׁ֣ר נָתַ֣תִּי לָ֔⁠ךְ וַ⁠תַּעֲשִׂי־לָ֖⁠ךְ צַלְמֵ֣י זָכָ֑ר וַ⁠תִּזְנִי־בָֽ⁠ם׃","wa⁠ţi̇qĕẖi֞y kĕ̇lé֣y ţipĕʼarĕţé̇֗⁠kĕ mi⁠zĕ̇hábi֤⁠y ẇ⁠mi⁠kȧsĕpi̇⁠y֙ ʼàşě֣r náţa֣ţi̇y lá֔⁠kĕ wa⁠ţȧʻàşîy-lá֖⁠kĕ ẕalĕmé֣y záká֑r wa⁠ţi̇zĕniy-báֽ⁠m׃"],[16,18,"וַ⁠תִּקְחִ֛י אֶת־בִּגְדֵ֥י רִקְמָתֵ֖⁠ךְ וַ⁠תְּכַסִּ֑י⁠ם וְ⁠שַׁמְנִ⁠י֙ וּ⁠קְטָרְתִּ֔⁠י נתתי לִ⁠פְנֵי⁠הֶֽם׃","wa⁠ţi̇qĕẖi֛y ʼeţ-bi̇gĕdé֥y riqĕmáţé֖⁠kĕ wa⁠ţĕ̇kasi֑̇y⁠m wĕ⁠şǎmĕni⁠y֙ ẇ⁠qĕtárĕţi̇֔⁠y nţţy li⁠pĕnéy⁠heֽm׃"],[16,19,"וְ⁠לַחְמִ⁠י֩ אֲשֶׁר־נָתַ֨תִּי לָ֜⁠ךְ סֹ֣לֶת וָ⁠שֶׁ֤מֶן וּ⁠דְבַשׁ֙ הֶֽאֱכַלְתִּ֔י⁠ךְ וּ⁠נְתַתִּ֧י⁠הוּ לִ⁠פְנֵי⁠הֶ֛ם לְ⁠רֵ֥יחַ נִיחֹ֖חַ וַ⁠יֶּ֑הִי נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wĕ⁠laẖĕmi⁠y֩ ʼàşěr-náţa֨ţi̇y lá֜⁠kĕ sò֣leţ wá⁠şě֤men ẇ⁠dĕbaş̌֙ heֽʼèkalĕţi̇֔y⁠kĕ ẇ⁠nĕţaţi֧̇y⁠hẇ li⁠pĕnéy⁠he֛m lĕ⁠ré֥yẖa niyẖò֖ẖa wa⁠yė֑hiy nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[16,20,"וַ⁠תִּקְחִ֞י אֶת־בָּנַ֤יִ⁠ךְ וְ⁠אֶת־בְּנוֹתַ֨יִ⁠ךְ֙ אֲשֶׁ֣ר יָלַ֣דְתְּ לִ֔⁠י וַ⁠תִּזְבָּחִ֥י⁠ם לָ⁠הֶ֖ם לֶ⁠אֱכ֑וֹל הַ⁠מְעַ֖ט מ⁠תזנת⁠ך׃","wa⁠ţi̇qĕẖi֞y ʼeţ-bá̇na֤yi⁠kĕ wĕ⁠ʼeţ-bĕ̇nwòţa֨yi⁠kĕ֙ ʼàşě֣r yála֣dĕţĕ̇ li֔⁠y wa⁠ţi̇zĕbá̇ẖi֥y⁠m lá⁠he֖m le⁠ʼèk֑wòl ha⁠mĕʻa֖t m⁠ţznţ⁠k׃"],[16,21,"וַֽ⁠תִּשְׁחֲטִ֖י אֶת־בָּנָ֑⁠י וַֽ⁠תִּתְּנִ֔י⁠ם בְּ⁠הַעֲבִ֥יר אוֹתָ֖⁠ם לָ⁠הֶֽם׃","waֽ⁠ţi̇şĕ̌ẖàti֖y ʼeţ-bá̇ná֑⁠y waֽ⁠ţi̇ţĕ̇ni֔y⁠m bĕ̇⁠haʻàbi֥yr ʼwòţá֖⁠m lá⁠heֽm׃"],[16,22,"וְ⁠אֵ֤ת כָּל־תּוֹעֲבֹתַ֨יִ⁠ךְ֙ וְ⁠תַזְנֻתַ֔יִ⁠ךְ לֹ֥א זכרתי אֶת־יְמֵ֣י נְעוּרָ֑יִ⁠ךְ בִּֽ⁠הְיוֹתֵ⁠ךְ֙ עֵרֹ֣ם וְ⁠עֶרְיָ֔ה מִתְבּוֹסֶ֥סֶת בְּ⁠דָמֵ֖⁠ךְ הָיִֽית׃","wĕ⁠ʼé֤ţ ká̇l-ţ̇wòʻàbòţa֨yi⁠kĕ֙ wĕ⁠ţazĕnuţa֔yi⁠kĕ lò֥ʼ zkrţy ʼeţ-yĕmé֣y nĕʻẇrá֑yi⁠kĕ biֽ̇⁠hĕywòţé⁠kĕ֙ ʻérò֣m wĕ⁠ʻerĕyá֔h miţĕḃwòse֥seţ bĕ̇⁠dámé֖⁠kĕ háyiֽyţ׃"],[16,23,"וַ⁠יְהִ֕י אַחֲרֵ֖י כָּל־רָעָתֵ֑⁠ךְ א֣וֹי א֣וֹי לָ֔⁠ךְ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wa⁠yĕhi֕y ʼaẖàré֖y ká̇l-ráʻáţé֑⁠kĕ ʼ֣wòy ʼ֣wòy lá֔⁠kĕ nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[16,24,"וַ⁠תִּבְנִי־לָ֖⁠ךְ גֶּ֑ב וַ⁠תַּעֲשִׂי־לָ֥⁠ךְ רָמָ֖ה בְּ⁠כָל־רְחֽוֹב׃","wa⁠ţi̇bĕniy-lá֖⁠kĕ gė֑b wa⁠ţȧʻàşîy-lá֥⁠kĕ rámá֖h bĕ̇⁠kál-rĕẖֽwòb׃"],[16,25,"אֶל־כָּל־רֹ֣אשׁ דֶּ֗רֶךְ בָּנִית֙ רָֽמָתֵ֔⁠ךְ וַ⁠תְּתַֽעֲבִי֙ אֶת־יָפְיֵ֔⁠ךְ וַ⁠תְּפַשְּׂקִ֥י אֶת־רַגְלַ֖יִ⁠ךְ לְ⁠כָל־עוֹבֵ֑ר וַ⁠תַּרְבִּ֖י אֶת־תזנת⁠ך׃","ʼel-ká̇l-rò֣ʼş̌ dė֗rekĕ bá̇niyţ֙ ráֽmáţé֔⁠kĕ wa⁠ţĕ̇ţaֽʻàbiy֙ ʼeţ-yápĕyé֔⁠kĕ wa⁠ţĕ̇paşĕ̇̂qi֥y ʼeţ-ragĕla֖yi⁠kĕ lĕ⁠kál-ʻwòbé֑r wa⁠ţȧrĕbi֖̇y ʼeţ-ţznţ⁠k׃"],[16,26,"וַ⁠תִּזְנִ֧י אֶל־בְּנֵֽי־מִצְרַ֛יִם שְׁכֵנַ֖יִ⁠ךְ גִּדְלֵ֣י בָשָׂ֑ר וַ⁠תַּרְבִּ֥י אֶת־תַּזְנֻתֵ֖⁠ךְ לְ⁠הַכְעִיסֵֽ⁠נִי׃","wa⁠ţi̇zĕni֧y ʼel-bĕ̇néֽy-miẕĕra֛yim şĕ̌kéna֖yi⁠kĕ gi̇dĕlé֣y báşá֑̂r wa⁠ţȧrĕbi֥̇y ʼeţ-ţȧzĕnuţé֖⁠kĕ lĕ⁠hakĕʻiyséֽ⁠niy׃"],[16,27,"וְ⁠הִנֵּ֨ה נָטִ֤יתִי יָדִ⁠י֙ עָלַ֔יִ⁠ךְ וָ⁠אֶגְרַ֖ע חֻקֵּ֑⁠ךְ וָ⁠אֶתְּנֵ֞⁠ךְ בְּ⁠נֶ֤פֶשׁ שֹׂנְאוֹתַ֨יִ⁠ךְ֙ בְּנ֣וֹת פְּלִשְׁתִּ֔ים הַ⁠נִּכְלָמ֖וֹת מִ⁠דַּרְכֵּ֥⁠ךְ זִמָּֽה׃","wĕ⁠hiné̇֨h náti֤yţiy yádi⁠y֙ ʻála֔yi⁠kĕ wá⁠ʼegĕra֖ʻ ẖuqé֑̇⁠kĕ wá⁠ʼeţĕ̇né֞⁠kĕ bĕ̇⁠ne֤peş̌ şò̂nĕʼwòţa֨yi⁠kĕ֙ bĕ̇n֣wòţ pĕ̇lişĕ̌ţi̇֔ym ha⁠ni̇kĕlám֖wòţ mi⁠dȧrĕké֥̇⁠kĕ zimáֽ̇h׃"],[16,28,"וַ⁠תִּזְנִי֙ אֶל־בְּנֵ֣י אַשּׁ֔וּר מִ⁠בִּלְתִּ֖י שָׂבְעָתֵ֑⁠ךְ וַ⁠תִּזְנִ֕י⁠ם וְ⁠גַ֖ם לֹ֥א שָׂבָֽעַתְּ׃","wa⁠ţi̇zĕniy֙ ʼel-bĕ̇né֣y ʼaş̇̌֔ẇr mi⁠bi̇lĕţi֖̇y şá̂bĕʻáţé֑⁠kĕ wa⁠ţi̇zĕni֕y⁠m wĕ⁠ga֖m lò֥ʼ şá̂báֽʻaţĕ̇׃"],[16,29,"וַ⁠תַּרְבִּ֧י אֶת־תַּזְנוּתֵ֛⁠ךְ אֶל־אֶ֥רֶץ כְּנַ֖עַן כַּשְׂדִּ֑ימָ⁠ה וְ⁠גַם־בְּ⁠זֹ֖את לֹ֥א שָׂבָֽעַתְּ׃","wa⁠ţȧrĕbi֧̇y ʼeţ-ţȧzĕnẇţé֛⁠kĕ ʼel-ʼe֥reẕ kĕ̇na֖ʻan kȧşĕ̂di֑̇ymá⁠h wĕ⁠gam-bĕ̇⁠zò֖ʼţ lò֥ʼ şá̂báֽʻaţĕ̇׃"],[16,30,"מָ֤ה אֲמֻלָה֙ לִבָּתֵ֔⁠ךְ נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה בַּ⁠עֲשׂוֹתֵ⁠ךְ֙ אֶת־כָּל־אֵ֔לֶּה מַעֲשֵׂ֥ה אִשָּֽׁה־זוֹנָ֖ה שַׁלָּֽטֶת׃","má֤h ʼàmuláh֙ libá̇ţé֔⁠kĕ nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h bȧ⁠ʻàş̂wòţé⁠kĕ֙ ʼeţ-ká̇l-ʼé֔lėh maʻàşé֥̂h ʼişáֽ̇̌h-zwòná֖h şǎláֽ̇teţ׃"],[16,31,"בִּ⁠בְנוֹתַ֤יִ⁠ךְ גַּבֵּ⁠ךְ֙ בְּ⁠רֹ֣אשׁ כָּל־דֶּ֔רֶךְ וְ⁠רָמָתֵ֥⁠ךְ עשיתי בְּ⁠כָל־רְח֑וֹב וְ⁠לֹא־הייתי כַּ⁠זּוֹנָ֖ה לְ⁠קַלֵּ֥ס אֶתְנָֽן׃","bi̇⁠bĕnwòţa֤yi⁠kĕ gȧbé̇⁠kĕ֙ bĕ̇⁠rò֣ʼş̌ ká̇l-dė֔rekĕ wĕ⁠rámáţé֥⁠kĕ ʻşyţy bĕ̇⁠kál-rĕẖ֑wòb wĕ⁠lòʼ-hyyţy kȧ⁠żwòná֖h lĕ⁠qalé֥̇s ʼeţĕnáֽn׃"],[16,32,"הָ⁠אִשָּׁ֖ה הַ⁠מְּנָאָ֑פֶת תַּ֣חַת אִישָׁ֔⁠הּ תִּקַּ֖ח אֶת־זָרִֽים׃","há⁠ʼişá֖̇̌h ha⁠mĕ̇náʼá֑peţ ţȧ֣ẖaţ ʼiyşá̌֔⁠ḣ ţi̇qȧ֖ẖ ʼeţ-záriֽym׃"],[16,33,"לְ⁠כָל־זֹנ֖וֹת יִתְּנוּ־נֵ֑דֶה וְ⁠אַ֨תְּ נָתַ֤תְּ אֶת־נְדָנַ֨יִ⁠ךְ֙ לְ⁠כָל־מְאַֽהֲבַ֔יִ⁠ךְ וַ⁠תִּשְׁחֳדִ֣י אוֹתָ֗⁠ם לָ⁠ב֥וֹא אֵלַ֛יִ⁠ךְ מִ⁠סָּבִ֖יב בְּ⁠תַזְנוּתָֽיִ⁠ךְ׃","lĕ⁠kál-zòn֖wòţ yiţĕ̇nẇ-né֑deh wĕ⁠ʼa֨ţĕ̇ náţa֤ţĕ̇ ʼeţ-nĕdána֨yi⁠kĕ֙ lĕ⁠kál-mĕʼaֽhàba֔yi⁠kĕ wa⁠ţi̇şĕ̌ẖodi֣y ʼwòţá֗⁠m lá⁠b֥wòʼ ʼéla֛yi⁠kĕ mi⁠sá̇bi֖yb bĕ̇⁠ţazĕnẇţáֽyi⁠kĕ׃"],[16,34,"וַ⁠יְהִי־בָ֨⁠ךְ הֵ֤פֶךְ מִן־הַ⁠נָּשִׁים֙ בְּ⁠תַזְנוּתַ֔יִ⁠ךְ וְ⁠אַחֲרַ֖יִ⁠ךְ לֹ֣א זוּנָּ֑ה וּ⁠בְ⁠תִתֵּ֣⁠ךְ אֶתְנָ֗ן וְ⁠אֶתְנַ֛ן לֹ֥א נִתַּן־לָ֖⁠ךְ וַ⁠תְּהִ֥י לְ⁠הֶֽפֶךְ׃","wa⁠yĕhiy-bá֨⁠kĕ hé֤pekĕ min-ha⁠ná̇şǐym֙ bĕ̇⁠ţazĕnẇţa֔yi⁠kĕ wĕ⁠ʼaẖàra֖yi⁠kĕ lò֣ʼ zẇná֑̇h ẇ⁠bĕ⁠ţiţé֣̇⁠kĕ ʼeţĕná֗n wĕ⁠ʼeţĕna֛n lò֥ʼ niţȧn-lá֖⁠kĕ wa⁠ţĕ̇hi֥y lĕ⁠heֽpekĕ׃"],[16,35,"לָ⁠כֵ֣ן זוֹנָ֔ה שִׁמְעִ֖י דְּבַר־יְהוָֽה׃פ","lá⁠ké֣n zwòná֔h şǐmĕʻi֖y dĕ̇bar-yĕhwáֽh׃p"],[16,36,"כֹּֽה־אָמַ֞ר אֲדֹנָ֣⁠י יְהֹוִ֗ה יַ֣עַן הִשָּׁפֵ֤ךְ נְחֻשְׁתֵּ⁠ךְ֙ וַ⁠תִּגָּלֶ֣ה עֶרְוָתֵ֔⁠ךְ בְּ⁠תַזְנוּתַ֖יִ⁠ךְ עַל־מְאַהֲבָ֑יִ⁠ךְ וְ⁠עַל֙ כָּל־גִּלּוּלֵ֣י תוֹעֲבוֹתַ֔יִ⁠ךְ וְ⁠כִ⁠דְמֵ֣י בָנַ֔יִ⁠ךְ אֲשֶׁ֥ר נָתַ֖תְּ לָ⁠הֶֽם׃","kòֽ̇h-ʼáma֞r ʼàdòná֣⁠y yĕhòwi֗h ya֣ʻan hişá̇̌pé֤kĕ nĕẖuşĕ̌ţé̇⁠kĕ֙ wa⁠ţi̇gá̇le֣h ʻerĕwáţé֔⁠kĕ bĕ̇⁠ţazĕnẇţa֖yi⁠kĕ ʻal-mĕʼahàbá֑yi⁠kĕ wĕ⁠ʻal֙ ká̇l-gi̇l̇ẇlé֣y ţwòʻàbwòţa֔yi⁠kĕ wĕ⁠ki⁠dĕmé֣y bána֔yi⁠kĕ ʼàşě֥r náţa֖ţĕ̇ lá⁠heֽm׃"],[16,37,"לָ֠⁠כֵן הִנְ⁠נִ֨י מְקַבֵּ֤ץ אֶת־כָּל־מְאַהֲבַ֨יִ⁠ךְ֙ אֲשֶׁ֣ר עָרַ֣בְתְּ עֲלֵי⁠הֶ֔ם וְ⁠אֵת֙ כָּל־אֲשֶׁ֣ר אָהַ֔בְתְּ עַ֖ל כָּל־אֲשֶׁ֣ר שָׂנֵ֑את וְ⁠קִבַּצְתִּי֩ אֹתָ֨⁠ם עָלַ֜יִ⁠ךְ מִ⁠סָּבִ֗יב וְ⁠גִלֵּיתִ֤י עֶרְוָתֵ⁠ךְ֙ אֲלֵ⁠הֶ֔ם וְ⁠רָא֖וּ אֶת־כָּל־עֶרְוָתֵֽ⁠ךְ׃","lá֠⁠kén hinĕ⁠ni֨y mĕqabé֤̇ẕ ʼeţ-ká̇l-mĕʼahàba֨yi⁠kĕ֙ ʼàşě֣r ʻára֣bĕţĕ̇ ʻàléy⁠he֔m wĕ⁠ʼéţ֙ ká̇l-ʼàşě֣r ʼáha֔bĕţĕ̇ ʻa֖l ká̇l-ʼàşě֣r şá̂né֑ʼţ wĕ⁠qibȧẕĕţi̇y֩ ʼòţá֨⁠m ʻála֜yi⁠kĕ mi⁠sá̇bi֗yb wĕ⁠gilé̇yţi֤y ʻerĕwáţé⁠kĕ֙ ʼàlé⁠he֔m wĕ⁠ráʼ֖ẇ ʼeţ-ká̇l-ʻerĕwáţéֽ⁠kĕ׃"],[16,38,"וּ⁠שְׁפַטְתִּי⁠ךְ֙ מִשְׁפְּטֵ֣י נֹאֲפ֔וֹת וְ⁠שֹׁפְכֹ֖ת דָּ֑ם וּ⁠נְתַתִּ֕י⁠ךְ דַּ֥ם חֵמָ֖ה וְ⁠קִנְאָֽה׃","ẇ⁠şĕ̌patĕţi̇y⁠kĕ֙ mişĕ̌pĕ̇té֣y nòʼàp֔wòţ wĕ⁠şò̌pĕkò֖ţ dá֑̇m ẇ⁠nĕţaţi̇֕y⁠kĕ dȧ֥m ẖémá֖h wĕ⁠qinĕʼáֽh׃"],[16,39,"וְ⁠נָתַתִּ֨י אוֹתָ֜⁠ךְ בְּ⁠יָדָ֗⁠ם וְ⁠הָרְס֤וּ גַבֵּ⁠ךְ֙ וְ⁠נִתְּצ֣וּ רָמֹתַ֔יִ⁠ךְ וְ⁠הִפְשִׁ֤יטוּ אוֹתָ⁠ךְ֙ בְּגָדַ֔יִ⁠ךְ וְ⁠לָקְח֖וּ כְּלֵ֣י תִפְאַרְתֵּ֑⁠ךְ וְ⁠הִנִּיח֖וּ⁠ךְ עֵירֹ֥ם וְ⁠עֶרְיָֽה׃","wĕ⁠náţaţi̇֨y ʼwòţá֜⁠kĕ bĕ̇⁠yádá֗⁠m wĕ⁠hárĕs֤ẇ gabé̇⁠kĕ֙ wĕ⁠niţĕ̇ẕ֣ẇ rámòţa֔yi⁠kĕ wĕ⁠hipĕşǐ֤ytẇ ʼwòţá⁠kĕ֙ bĕ̇gáda֔yi⁠kĕ wĕ⁠láqĕẖ֖ẇ kĕ̇lé֣y ţipĕʼarĕţé֑̇⁠kĕ wĕ⁠hini̇yẖ֖ẇ⁠kĕ ʻéyrò֥m wĕ⁠ʻerĕyáֽh׃"],[16,40,"וְ⁠הֶעֱל֤וּ עָלַ֨יִ⁠ךְ֙ קָהָ֔ל וְ⁠רָגְמ֥וּ אוֹתָ֖⁠ךְ בָּ⁠אָ֑בֶן וּ⁠בִתְּק֖וּ⁠ךְ בְּ⁠חַרְבוֹתָֽ⁠ם׃","wĕ⁠heʻèl֤ẇ ʻála֨yi⁠kĕ֙ qáhá֔l wĕ⁠rágĕm֥ẇ ʼwòţá֖⁠kĕ bá̇⁠ʼá֑ben ẇ⁠biţĕ̇q֖ẇ⁠kĕ bĕ̇⁠ẖarĕbwòţáֽ⁠m׃"],[16,41,"וְ⁠שָׂרְפ֤וּ בָתַּ֨יִ⁠ךְ֙ בָּ⁠אֵ֔שׁ וְ⁠עָשׂוּ־בָ֣⁠ךְ שְׁפָטִ֔ים לְ⁠עֵינֵ֖י נָשִׁ֣ים רַבּ֑וֹת וְ⁠הִשְׁבַּתִּי⁠ךְ֙ מִ⁠זּוֹנָ֔ה וְ⁠גַם־אֶתְנַ֖ן לֹ֥א תִתְּנִי־עֽוֹד׃","wĕ⁠şá̂rĕp֤ẇ báţȧ֨yi⁠kĕ֙ bá̇⁠ʼé֔ş̌ wĕ⁠ʻáş̂ẇ-bá֣⁠kĕ şĕ̌páti֔ym lĕ⁠ʻéyné֖y náşǐ֣ym raḃ֑wòţ wĕ⁠hişĕ̌bȧţi̇y⁠kĕ֙ mi⁠żwòná֔h wĕ⁠gam-ʼeţĕna֖n lò֥ʼ ţiţĕ̇niy-ʻֽwòd׃"],[16,42,"וַ⁠הֲנִחֹתִ֤י חֲמָתִ⁠י֙ בָּ֔⁠ךְ וְ⁠סָ֥רָה קִנְאָתִ֖⁠י מִמֵּ֑⁠ךְ וְ⁠שָׁ֣קַטְתִּ֔י וְ⁠לֹ֥א אֶכְעַ֖ס עֽוֹד׃","wa⁠hàniẖòţi֤y ẖàmáţi⁠y֙ bá̇֔⁠kĕ wĕ⁠sá֥ráh qinĕʼáţi֖⁠y mimé֑̇⁠kĕ wĕ⁠şá֣̌qatĕţi̇֔y wĕ⁠lò֥ʼ ʼekĕʻa֖s ʻֽwòd׃"],[16,43,"יַ֗עַן אֲשֶׁ֤ר לֹֽא־זכרתי אֶת־יְמֵ֣י נְעוּרַ֔יִ⁠ךְ וַ⁠תִּרְגְּזִי־לִ֖⁠י בְּ⁠כָל־אֵ֑לֶּה וְ⁠גַם־אֲנִ֨י הֵ֜א דַּרְכֵּ֣⁠ךְ ׀ בְּ⁠רֹ֣אשׁ נָתַ֗תִּי נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה וְ⁠לֹ֤א עשיתי אֶת־הַ⁠זִּמָּ֔ה עַ֖ל כָּל־תּוֹעֲבֹתָֽיִ⁠ךְ׃","ya֗ʻan ʼàşě֤r lòֽʼ-zkrţy ʼeţ-yĕmé֣y nĕʻẇra֔yi⁠kĕ wa⁠ţi̇rĕgĕ̇ziy-li֖⁠y bĕ̇⁠kál-ʼé֑lėh wĕ⁠gam-ʼàni֨y hé֜ʼ dȧrĕké֣̇⁠kĕ ׀ bĕ̇⁠rò֣ʼş̌ náţa֗ţi̇y nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h wĕ⁠lò֤ʼ ʻşyţy ʼeţ-ha⁠zi̇má̇֔h ʻa֖l ká̇l-ţ̇wòʻàbòţáֽyi⁠kĕ׃"],[16,44,"הִנֵּה֙ כָּל־הַ⁠מֹּשֵׁ֔ל עָלַ֥יִ⁠ךְ יִמְשֹׁ֖ל לֵ⁠אמֹ֑ר כְּ⁠אִמָּ֖⁠ה בִּתָּֽ⁠הּ׃","hiné̇h֙ ká̇l-ha⁠mò̇şé̌֔l ʻála֥yi⁠kĕ yimĕşò֖̌l lé⁠ʼmò֑r kĕ̇⁠ʼimá֖̇⁠h bi̇ţáֽ̇⁠ḣ׃"],[16,45,"בַּת־אִמֵּ֣⁠ךְ אַ֔תְּ גֹּעֶ֥לֶת אִישָׁ֖⁠הּ וּ⁠בָנֶ֑י⁠הָ וַ⁠אֲח֨וֹת אֲחוֹתֵ֜⁠ךְ אַ֗תְּ אֲשֶׁ֤ר גָּֽעֲ֨לוּ֙ אַנְשֵׁי⁠הֶ֣ן וּ⁠בְנֵי⁠הֶ֔ן אִמְּ⁠כֶ֣ן חִתִּ֔ית וַ⁠אֲבִי⁠כֶ֖ן אֱמֹרִֽי׃","bȧţ-ʼimé֣̇⁠kĕ ʼa֔ţĕ̇ gò̇ʻe֥leţ ʼiyşá֖̌⁠ḣ ẇ⁠báne֑y⁠há wa⁠ʼàẖ֨wòţ ʼàẖwòţé֜⁠kĕ ʼa֗ţĕ̇ ʼàşě֤r gáֽ̇ʻà֨lẇ֙ ʼanĕşé̌y⁠he֣n ẇ⁠bĕnéy⁠he֔n ʼimĕ̇⁠ke֣n ẖiţi̇֔yţ wa⁠ʼàbiy⁠ke֖n ʼèmòriֽy׃"],[16,46,"וַ⁠אֲחוֹתֵ֨⁠ךְ הַ⁠גְּדוֹלָ֤ה שֹֽׁמְרוֹן֙ הִ֣יא וּ⁠בְנוֹתֶ֔י⁠הָ הַ⁠יּוֹשֶׁ֖בֶת עַל־שְׂמֹאולֵ֑⁠ךְ וַ⁠אֲחוֹתֵ֞⁠ךְ הַ⁠קְּטַנָּ֣ה מִמֵּ֗⁠ךְ הַ⁠יּוֹשֶׁ֨בֶת֙ מִֽ⁠ימִינֵ֔⁠ךְ סְדֹ֖ם וּ⁠בְנוֹתֶֽי⁠הָ׃","wa⁠ʼàẖwòţé֨⁠kĕ ha⁠gĕ̇dwòlá֤h şòֽ̌mĕrwòn֙ hi֣yʼ ẇ⁠bĕnwòţe֔y⁠há ha⁠ẏwòşě֖beţ ʻal-şĕ̂mòʼwlé֑⁠kĕ wa⁠ʼàẖwòţé֞⁠kĕ ha⁠qĕ̇taná֣̇h mimé̇֗⁠kĕ ha⁠ẏwòşě֨beţ֙ miֽ⁠ymiyné֔⁠kĕ sĕdò֖m ẇ⁠bĕnwòţeֽy⁠há׃"],[16,47,"וְ⁠לֹ֤א בְ⁠דַרְכֵי⁠הֶן֙ הָלַ֔כְתְּ וּ⁠בְ⁠תוֹעֲבֽוֹתֵי⁠הֶ֖ן עשיתי כִּ⁠מְעַ֣ט קָ֔ט וַ⁠תַּשְׁחִ֥תִי מֵ⁠הֵ֖ן בְּ⁠כָל־דְּרָכָֽיִ⁠ךְ׃","wĕ⁠lò֤ʼ bĕ⁠darĕkéy⁠hen֙ hála֔kĕţĕ̇ ẇ⁠bĕ⁠ţwòʻàbֽwòţéy⁠he֖n ʻşyţy ki̇⁠mĕʻa֣t qá֔t wa⁠ţȧşĕ̌ẖi֥ţiy mé⁠hé֖n bĕ̇⁠kál-dĕ̇rákáֽyi⁠kĕ׃"],[16,48,"חַי־אָ֗נִי נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה אִם־עָֽשְׂתָה֙ סְדֹ֣ם אֲחוֹתֵ֔⁠ךְ הִ֖יא וּ⁠בְנוֹתֶ֑י⁠הָ כַּ⁠אֲשֶׁ֣ר עָשִׂ֔ית אַ֖תְּ וּ⁠בְנוֹתָֽיִ⁠ךְ׃","ẖay-ʼá֗niy nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h ʼim-ʻáֽşĕ̂ţáh֙ sĕdò֣m ʼàẖwòţé֔⁠kĕ hi֖yʼ ẇ⁠bĕnwòţe֑y⁠há kȧ⁠ʼàşě֣r ʻáşî֔yţ ʼa֖ţĕ̇ ẇ⁠bĕnwòţáֽyi⁠kĕ׃"],[16,49,"הִנֵּה־זֶ֣ה הָיָ֔ה עֲוֺ֖ן סְדֹ֣ם אֲחוֹתֵ֑⁠ךְ גָּא֨וֹן שִׂבְעַת־לֶ֜חֶם וְ⁠שַׁלְוַ֣ת הַשְׁקֵ֗ט הָ֤יָה לָ⁠הּ֙ וְ⁠לִ⁠בְנוֹתֶ֔י⁠הָ וְ⁠יַד־עָנִ֥י וְ⁠אֶבְי֖וֹן לֹ֥א הֶחֱזִֽיקָה׃","hiné̇h-ze֣h háyá֔h ʻàwֺ֖n sĕdò֣m ʼàẖwòţé֑⁠kĕ gá̇ʼ֨wòn şîbĕʻaţ-le֜ẖem wĕ⁠şǎlĕwa֣ţ haşĕ̌qé֗t há֤yáh lá⁠ḣ֙ wĕ⁠li⁠bĕnwòţe֔y⁠há wĕ⁠yad-ʻáni֥y wĕ⁠ʼebĕy֖wòn lò֥ʼ heẖèziֽyqáh׃"],[16,50,"וַֽ⁠תִּגְבְּהֶ֔ינָה וַ⁠תַּעֲשֶׂ֥ינָה תוֹעֵבָ֖ה לְ⁠פָנָ֑⁠י וָ⁠אָסִ֥יר אֶתְ⁠הֶ֖ן כַּ⁠אֲשֶׁ֥ר רָאִֽיתִי׃ס","waֽ⁠ţi̇gĕbĕ̇he֔ynáh wa⁠ţȧʻàşê֥ynáh ţwòʻébá֖h lĕ⁠páná֑⁠y wá⁠ʼási֥yr ʼeţĕ⁠he֖n kȧ⁠ʼàşě֥r ráʼiֽyţiy׃s"],[16,51,"וְ⁠שֹׁ֣מְר֔וֹן כַּ⁠חֲצִ֥י חַטֹּאתַ֖יִ⁠ךְ לֹ֣א חָטָ֑אָה וַ⁠תַּרְבִּ֤י אֶת־תּוֹעֲבוֹתַ֨יִ⁠ךְ֙ מֵ⁠הֵ֔נָּה וַ⁠תְּצַדְּקִי֙ אֶת־אחות⁠ך בְּ⁠כָל־תּוֹעֲבוֹתַ֖יִ⁠ךְ אֲשֶׁ֥ר עשיתי׃","wĕ⁠şò֣̌mĕr֔wòn kȧ⁠ẖàẕi֥y ẖatò̇ʼţa֖yi⁠kĕ lò֣ʼ ẖátá֑ʼáh wa⁠ţȧrĕbi֤̇y ʼeţ-ţ̇wòʻàbwòţa֨yi⁠kĕ֙ mé⁠hé֔ná̇h wa⁠ţĕ̇ẕadĕ̇qiy֙ ʼeţ-ʼẖwţ⁠k bĕ̇⁠kál-ţ̇wòʻàbwòţa֖yi⁠kĕ ʼàşě֥r ʻşyţy׃"],[16,52,"גַּם־אַ֣תְּ ׀ שְׂאִ֣י כְלִמָּתֵ֗⁠ךְ אֲשֶׁ֤ר פִּלַּלְתְּ֙ לַֽ⁠אֲחוֹתֵ֔⁠ךְ בְּ⁠חַטֹּאתַ֛יִ⁠ךְ אֲשֶׁר־הִתְעַ֥בְתְּ מֵ⁠הֵ֖ן תִּצְדַּ֣קְנָה מִמֵּ֑⁠ךְ וְ⁠גַם־אַ֥תְּ בּ֨וֹשִׁי֙ וּ⁠שְׂאִ֣י כְלִמָּתֵ֔⁠ךְ בְּ⁠צַדֶּקְתֵּ֖⁠ךְ אַחְיוֹתֵֽ⁠ךְ׃","gȧm-ʼa֣ţĕ̇ ׀ şĕ̂ʼi֣y kĕlimá̇ţé֗⁠kĕ ʼàşě֤r pi̇lȧlĕţĕ̇֙ laֽ⁠ʼàẖwòţé֔⁠kĕ bĕ̇⁠ẖatò̇ʼţa֛yi⁠kĕ ʼàşěr-hiţĕʻa֥bĕţĕ̇ mé⁠hé֖n ţi̇ẕĕdȧ֣qĕnáh mimé֑̇⁠kĕ wĕ⁠gam-ʼa֥ţĕ̇ ḃ֨wòşǐy֙ ẇ⁠şĕ̂ʼi֣y kĕlimá̇ţé֔⁠kĕ bĕ̇⁠ẕadėqĕţé֖̇⁠kĕ ʼaẖĕywòţéֽ⁠kĕ׃"],[16,53,"וְ⁠שַׁבְתִּי֙ אֶת־שְׁבִ֣יתְ⁠הֶ֔ן אֶת־שבית סְדֹם֙ וּ⁠בְנוֹתֶ֔י⁠הָ וְ⁠אֶת־שבית שֹׁמְר֖וֹן וּ⁠בְנוֹתֶ֑י⁠הָ ו⁠שבית שְׁבִיתַ֖יִ⁠ךְ בְּ⁠תוֹכָֽ⁠הְנָה׃","wĕ⁠şǎbĕţi̇y֙ ʼeţ-şĕ̌bi֣yţĕ⁠he֔n ʼeţ-şbyţ sĕdòm֙ ẇ⁠bĕnwòţe֔y⁠há wĕ⁠ʼeţ-şbyţ şò̌mĕr֖wòn ẇ⁠bĕnwòţe֑y⁠há w⁠şbyţ şĕ̌biyţa֖yi⁠kĕ bĕ̇⁠ţwòkáֽ⁠hĕnáh׃"],[16,54,"לְמַ֨עַן֙ תִּשְׂאִ֣י כְלִמָּתֵ֔⁠ךְ וְ⁠נִכְלַ֕מְתְּ מִ⁠כֹּ֖ל אֲשֶׁ֣ר עָשִׂ֑ית בְּ⁠נַחֲמֵ֖⁠ךְ אֹתָֽ⁠ן׃","lĕma֨ʻan֙ ţi̇şĕ̂ʼi֣y kĕlimá̇ţé֔⁠kĕ wĕ⁠nikĕla֕mĕţĕ̇ mi⁠kò֖̇l ʼàşě֣r ʻáşî֑yţ bĕ̇⁠naẖàmé֖⁠kĕ ʼòţáֽ⁠n׃"],[16,55,"וַ⁠אֲחוֹתַ֗יִ⁠ךְ סְדֹ֤ם וּ⁠בְנוֹתֶ֨י⁠הָ֙ תָּשֹׁ֣בְןָ לְ⁠קַדְמָתָ֔⁠ן וְ⁠שֹֽׁמְרוֹן֙ וּ⁠בְנוֹתֶ֔י⁠הָ תָּשֹׁ֖בְןָ לְ⁠קַדְמָתָ֑⁠ן וְ⁠אַתְּ֙ וּ⁠בְנוֹתַ֔יִ⁠ךְ תְּשֻׁבֶ֖ינָה לְ⁠קַדְמַתְ⁠כֶֽן׃","wa⁠ʼàẖwòţa֗yi⁠kĕ sĕdò֤m ẇ⁠bĕnwòţe֨y⁠há֙ ţá̇şò֣̌bĕná lĕ⁠qadĕmáţá֔⁠n wĕ⁠şòֽ̌mĕrwòn֙ ẇ⁠bĕnwòţe֔y⁠há ţá̇şò֖̌bĕná lĕ⁠qadĕmáţá֑⁠n wĕ⁠ʼaţĕ̇֙ ẇ⁠bĕnwòţa֔yi⁠kĕ ţĕ̇şǔbe֖ynáh lĕ⁠qadĕmaţĕ⁠keֽn׃"],[16,56,"וְ⁠ל֤וֹא הָֽיְתָה֙ סְדֹ֣ם אֲחוֹתֵ֔⁠ךְ לִ⁠שְׁמוּעָ֖ה בְּ⁠פִ֑י⁠ךְ בְּ⁠י֖וֹם גְּאוֹנָֽיִ⁠ךְ׃","wĕ⁠l֤wòʼ háֽyĕţáh֙ sĕdò֣m ʼàẖwòţé֔⁠kĕ li⁠şĕ̌mẇʻá֖h bĕ̇⁠pi֑y⁠kĕ bĕ̇⁠y֖wòm gĕ̇ʼwònáֽyi⁠kĕ׃"],[16,57,"בְּ⁠טֶרֶם֮ תִּגָּלֶ֣ה רָעָתֵ⁠ךְ֒ כְּמ֗וֹ עֵ֚ת חֶרְפַּ֣ת בְּנוֹת־אֲרָ֔ם וְ⁠כָל־סְבִיבוֹתֶ֖י⁠הָ בְּנ֣וֹת פְּלִשְׁתִּ֑ים הַ⁠שָּׁאט֥וֹת אוֹתָ֖⁠ךְ מִ⁠סָּבִֽיב׃","bĕ̇⁠terem֮ ţi̇gá̇le֣h ráʻáţé⁠kĕ֒ kĕ̇m֗wò ʻé֚ţ ẖerĕpȧ֣ţ bĕ̇nwòţ-ʼàrá֔m wĕ⁠kál-sĕbiybwòţe֖y⁠há bĕ̇n֣wòţ pĕ̇lişĕ̌ţi֑̇ym ha⁠şá̇̌ʼt֥wòţ ʼwòţá֖⁠kĕ mi⁠sá̇biֽyb׃"],[16,58,"אֶת־זִמָּתֵ֥⁠ךְ וְ⁠אֶת־תּוֹעֲבוֹתַ֖יִ⁠ךְ אַ֣תְּ נְשָׂאתִ֑י⁠ם נְאֻ֖ם יְהוָֽה׃ס","ʼeţ-zimá̇ţé֥⁠kĕ wĕ⁠ʼeţ-ţ̇wòʻàbwòţa֖yi⁠kĕ ʼa֣ţĕ̇ nĕşá̂ʼţi֑y⁠m nĕʼu֖m yĕhwáֽh׃s"],[16,59,"כִּ֣י כֹ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה ו⁠עשית אוֹתָ֖⁠ךְ כַּ⁠אֲשֶׁ֣ר עָשִׂ֑ית אֲשֶׁר־בָּזִ֥ית אָלָ֖ה לְ⁠הָפֵ֥ר בְּרִֽית׃","ki֣̇y kò֤h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h w⁠ʻşyţ ʼwòţá֖⁠kĕ kȧ⁠ʼàşě֣r ʻáşî֑yţ ʼàşěr-bá̇zi֥yţ ʼálá֖h lĕ⁠hápé֥r bĕ̇riֽyţ׃"],[16,60,"וְ⁠זָכַרְתִּ֨י אֲנִ֧י אֶת־בְּרִיתִ֛⁠י אוֹתָ֖⁠ךְ בִּ⁠ימֵ֣י נְעוּרָ֑יִ⁠ךְ וַ⁠הֲקִמוֹתִ֥י לָ֖⁠ךְ בְּרִ֥ית עוֹלָֽם׃","wĕ⁠zákarĕţi̇֨y ʼàni֧y ʼeţ-bĕ̇riyţi֛⁠y ʼwòţá֖⁠kĕ bi̇⁠ymé֣y nĕʻẇrá֑yi⁠kĕ wa⁠hàqimwòţi֥y lá֖⁠kĕ bĕ̇ri֥yţ ʻwòláֽm׃"],[16,61,"וְ⁠זָכַ֣רְתְּ אֶת־דְּרָכַיִ⁠ךְ֮ וְ⁠נִכְלַמְתְּ֒ בְּ⁠קַחְתֵּ֗⁠ךְ אֶת־אֲחוֹתַ֨יִ⁠ךְ֙ הַ⁠גְּדֹל֣וֹת מִמֵּ֔⁠ךְ אֶל־הַ⁠קְּטַנּ֖וֹת מִמֵּ֑⁠ךְ וְ⁠נָתַתִּ֨י אֶתְ⁠הֶ֥ן לָ֛⁠ךְ לְ⁠בָנ֖וֹת וְ⁠לֹ֥א מִ⁠בְּרִיתֵֽ⁠ךְ׃","wĕ⁠záka֣rĕţĕ̇ ʼeţ-dĕ̇rákayi⁠kĕ֮ wĕ⁠nikĕlamĕţĕ̇֒ bĕ̇⁠qaẖĕţé̇֗⁠kĕ ʼeţ-ʼàẖwòţa֨yi⁠kĕ֙ ha⁠gĕ̇dòl֣wòţ mimé̇֔⁠kĕ ʼel-ha⁠qĕ̇taṅ֖wòţ mimé֑̇⁠kĕ wĕ⁠náţaţi̇֨y ʼeţĕ⁠he֥n lá֛⁠kĕ lĕ⁠bán֖wòţ wĕ⁠lò֥ʼ mi⁠bĕ̇riyţéֽ⁠kĕ׃"],[16,62,"וַ⁠הֲקִימוֹתִ֥י אֲנִ֛י אֶת־בְּרִיתִ֖⁠י אִתָּ֑⁠ךְ וְ⁠יָדַ֖עַתְּ כִּֽי־אֲנִ֥י יְהוָֽה׃","wa⁠hàqiymwòţi֥y ʼàni֛y ʼeţ-bĕ̇riyţi֖⁠y ʼiţá֑̇⁠kĕ wĕ⁠yáda֖ʻaţĕ̇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[16,63,"לְמַ֤עַן תִּזְכְּרִי֙ וָ⁠בֹ֔שְׁתְּ וְ⁠לֹ֨א יִֽהְיֶה־לָּ֥⁠ךְ עוֹד֙ פִּתְח֣וֹן פֶּ֔ה מִ⁠פְּנֵ֖י כְּלִמָּתֵ֑⁠ךְ בְּ⁠כַפְּרִ⁠י־לָ⁠ךְ֙ לְ⁠כָל־אֲשֶׁ֣ר עָשִׂ֔ית נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","lĕma֤ʻan ţi̇zĕkĕ̇riy֙ wá⁠bò֔şĕ̌ţĕ̇ wĕ⁠lò֨ʼ yiֽhĕyeh-lá֥̇⁠kĕ ʻwòd֙ pi̇ţĕẖ֣wòn pė֔h mi⁠pĕ̇né֖y kĕ̇limá̇ţé֑⁠kĕ bĕ̇⁠kapĕ̇ri⁠y-lá⁠kĕ֙ lĕ⁠kál-ʼàşě֣r ʻáşî֔yţ nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[17,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[17,2,"בֶּן־אָדָ֕ם ח֥וּד חִידָ֖ה וּ⁠מְשֹׁ֣ל מָשָׁ֑ל אֶל־בֵּ֖ית יִשְׂרָאֵֽל׃","bėn-ʼádá֕m ẖ֥ẇd ẖiydá֖h ẇ⁠mĕşò֣̌l máşá֑̌l ʼel-bé֖̇yţ yişĕ̂ráʼéֽl׃"],[17,3,"וְ⁠אָמַרְתָּ֞ כֹּה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה הַ⁠נֶּ֤שֶׁר הַ⁠גָּדוֹל֙ גְּד֤וֹל הַ⁠כְּנָפַ֨יִם֙ אֶ֣רֶךְ הָ⁠אֵ֔בֶר מָלֵא֙ הַ⁠נּוֹצָ֔ה אֲשֶׁר־ל֖⁠וֹ הָֽ⁠רִקְמָ֑ה בָּ֚א אֶל־הַ⁠לְּבָנ֔וֹן וַ⁠יִּקַּ֖ח אֶת־צַמֶּ֥רֶת הָ⁠אָֽרֶז׃","wĕ⁠ʼámarĕţá̇֞ kò̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h ha⁠nė֤şěr ha⁠gá̇dwòl֙ gĕ̇d֤wòl ha⁠kĕ̇nápa֨yim֙ ʼe֣rekĕ há⁠ʼé֔ber máléʼ֙ ha⁠ṅwòẕá֔h ʼàşěr-l֖⁠wò háֽ⁠riqĕmá֑h bá֚̇ʼ ʼel-ha⁠lĕ̇bán֔wòn wa⁠yi̇qȧ֖ẖ ʼeţ-ẕamė֥reţ há⁠ʼáֽrez׃"],[17,4,"אֵ֛ת רֹ֥אשׁ יְנִֽיקוֹתָ֖י⁠ו קָטָ֑ף וַ⁠יְבִיאֵ֨⁠הוּ֙ אֶל־אֶ֣רֶץ כְּנַ֔עַן בְּ⁠עִ֥יר רֹכְלִ֖ים שָׂמֽ⁠וֹ׃","ʼé֛ţ rò֥ʼş̌ yĕniֽyqwòţá֖y⁠w qátá֑p wa⁠yĕbiyʼé֨⁠hẇ֙ ʼel-ʼe֣reẕ kĕ̇na֔ʻan bĕ̇⁠ʻi֥yr ròkĕli֖ym şá̂mֽ⁠wò׃"],[17,5,"וַ⁠יִּקַּח֙ מִ⁠זֶּ֣רַע הָ⁠אָ֔רֶץ וַֽ⁠יִּתְּנֵ֖⁠הוּ בִּ⁠שְׂדֵה־זָ֑רַע קָ֚ח עַל־מַ֣יִם רַבִּ֔ים צַפְצָפָ֖ה שָׂמֽ⁠וֹ׃","wa⁠yi̇qȧẖ֙ mi⁠zė֣raʻ há⁠ʼá֔reẕ waֽ⁠yi̇ţĕ̇né֖⁠hẇ bi̇⁠şĕ̂déh-zá֑raʻ qá֚ẖ ʻal-ma֣yim rabi̇֔ym ẕapĕẕápá֖h şá̂mֽ⁠wò׃"],[17,6,"וַ⁠יִּצְמַ֡ח וַ⁠יְהִי֩ לְ⁠גֶ֨פֶן סֹרַ֜חַת שִׁפְלַ֣ת קוֹמָ֗ה לִ⁠פְנ֤וֹת דָּלִיּוֹתָי⁠ו֙ אֵלָ֔י⁠ו וְ⁠שָׁרָשָׁ֖י⁠ו תַּחְתָּ֣י⁠ו יִֽהְי֑וּ וַ⁠תְּהִ֣י לְ⁠גֶ֔פֶן וַ⁠תַּ֣עַשׂ בַּדִּ֔ים וַ⁠תְּשַׁלַּ֖ח פֹּארֽוֹת׃","wa⁠yi̇ẕĕma֡ẖ wa⁠yĕhiy֩ lĕ⁠ge֨pen sòra֜ẖaţ şǐpĕla֣ţ qwòmá֗h li⁠pĕn֤wòţ dá̇liẏwòţáy⁠w֙ ʼélá֔y⁠w wĕ⁠şá̌ráşá֖̌y⁠w ţȧẖĕţá֣̇y⁠w yiֽhĕy֑ẇ wa⁠ţĕ̇hi֣y lĕ⁠ge֔pen wa⁠ţȧ֣ʻaş̂ bȧdi̇֔ym wa⁠ţĕ̇şǎlȧ֖ẖ pò̇ʼrֽwòţ׃"],[17,7,"וַ⁠יְהִ֤י נֶֽשֶׁר־אֶחָד֙ גָּד֔וֹל גְּד֥וֹל כְּנָפַ֖יִם וְ⁠רַב־נוֹצָ֑ה וְ⁠הִנֵּה֩ הַ⁠גֶּ֨פֶן הַ⁠זֹּ֜את כָּֽפְנָ֧ה שָׁרֳשֶׁ֣י⁠הָ עָלָ֗י⁠ו וְ⁠דָֽלִיּוֹתָי⁠ו֙ שִׁלְחָה־לּ֔⁠וֹ לְ⁠הַשְׁק֣וֹת אוֹתָ֔⁠הּ מֵ⁠עֲרֻג֖וֹת מַטָּעָֽ⁠הּ׃","wa⁠yĕhi֤y neֽşěr-ʼeẖád֙ gá̇d֔wòl gĕ̇d֥wòl kĕ̇nápa֖yim wĕ⁠rab-nwòẕá֑h wĕ⁠hiné̇h֩ ha⁠gė֨pen ha⁠zò̇֜ʼţ káֽ̇pĕná֧h şá̌roşě֣y⁠há ʻálá֗y⁠w wĕ⁠dáֽliẏwòţáy⁠w֙ şǐlĕẖáh-l̇֔⁠wò lĕ⁠haşĕ̌q֣wòţ ʼwòţá֔⁠ḣ mé⁠ʻàrug֖wòţ matá̇ʻáֽ⁠ḣ׃"],[17,8,"אֶל־שָׂ֥דֶה טּ֛וֹב אֶל־מַ֥יִם רַבִּ֖ים הִ֣יא שְׁתוּלָ֑ה לַ⁠עֲשׂ֤וֹת עָנָף֙ וְ⁠לָ⁠שֵׂ֣את פֶּ֔רִי לִ⁠הְי֖וֹת לְ⁠גֶ֥פֶן אַדָּֽרֶת׃ס","ʼel-şá֥̂deh ṫ֛wòb ʼel-ma֥yim rabi֖̇ym hi֣yʼ şĕ̌ţẇlá֑h la⁠ʻàş֤̂wòţ ʻánáp֙ wĕ⁠lá⁠şé֣̂ʼţ pė֔riy li⁠hĕy֖wòţ lĕ⁠ge֥pen ʼadáֽ̇reţ׃s"],[17,9,"אֱמֹ֗ר כֹּ֥ה אָמַ֛ר אֲדֹנָ֥⁠י יְהֹוִ֖ה תִּצְלָ֑ח הֲ⁠לוֹא֩ אֶת־שָׁרָשֶׁ֨י⁠הָ יְנַתֵּ֜ק וְ⁠אֶת־פִּרְיָ֣⁠הּ ׀ יְקוֹסֵ֣ס וְ⁠יָבֵ֗שׁ כָּל־טַרְפֵּ֤י צִמְחָ⁠הּ֙ תִּיבָ֔שׁ וְ⁠לֹֽא־בִ⁠זְרֹ֤עַ גְּדוֹלָה֙ וּ⁠בְ⁠עַם־רָ֔ב לְ⁠מַשְׂא֥וֹת אוֹתָ֖⁠הּ מִ⁠שָּׁרָשֶֽׁי⁠הָ׃","ʼèmò֗r kò֥̇h ʼáma֛r ʼàdòná֥⁠y yĕhòwi֖h ţi̇ẕĕlá֑ẖ hà⁠lwòʼ֩ ʼeţ-şá̌ráşě֨y⁠há yĕnaţé̇֜q wĕ⁠ʼeţ-pi̇rĕyá֣⁠ḣ ׀ yĕqwòsé֣s wĕ⁠yábé֗ş̌ ká̇l-tarĕpé֤̇y ẕimĕẖá⁠ḣ֙ ţi̇ybá֔ş̌ wĕ⁠lòֽʼ-bi⁠zĕrò֤ʻa gĕ̇dwòláh֙ ẇ⁠bĕ⁠ʻam-rá֔b lĕ⁠maşĕ̂ʼ֥wòţ ʼwòţá֖⁠ḣ mi⁠şá̇̌ráşěֽy⁠há׃"],[17,10,"וְ⁠הִנֵּ֥ה שְׁתוּלָ֖ה הֲ⁠תִצְלָ֑ח הֲ⁠לוֹא֩ כְ⁠גַ֨עַת בָּ֜⁠הּ ר֤וּחַ הַ⁠קָּדִים֙ תִּיבַ֣שׁ יָבֹ֔שׁ עַל־עֲרֻגֹ֥ת צִמְחָ֖⁠הּ תִּיבָֽשׁ׃פ","wĕ⁠hiné֥̇h şĕ̌ţẇlá֖h hà⁠ţiẕĕlá֑ẖ hà⁠lwòʼ֩ kĕ⁠ga֨ʻaţ bá̇֜⁠ḣ r֤ẇẖa ha⁠qá̇diym֙ ţi̇yba֣ş̌ yábò֔ş̌ ʻal-ʻàrugò֥ţ ẕimĕẖá֖⁠ḣ ţi̇ybáֽş̌׃p"],[17,11,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[17,12,"אֱמָר־נָא֙ לְ⁠בֵ֣ית הַ⁠מֶּ֔רִי הֲ⁠לֹ֥א יְדַעְתֶּ֖ם מָה־אֵ֑לֶּה אֱמֹ֗ר הִנֵּה־בָ֨א מֶֽלֶךְ־בָּבֶ֤ל יְרוּשָׁלִַ֨ם֙ וַ⁠יִּקַּ֤ח אֶת־מַלְכָּ⁠הּ֙ וְ⁠אֶת־שָׂרֶ֔י⁠הָ וַ⁠יָּבֵ֥א אוֹתָ֛⁠ם אֵלָ֖י⁠ו בָּבֶֽלָ⁠ה׃","ʼèmár-náʼ֙ lĕ⁠bé֣yţ ha⁠mė֔riy hà⁠lò֥ʼ yĕdaʻĕţė֖m máh-ʼé֑lėh ʼèmò֗r hiné̇h-bá֨ʼ meֽlekĕ-bá̇be֤l yĕrẇşá̌lia֨m֙ wa⁠yi̇qȧ֤ẖ ʼeţ-malĕká̇⁠ḣ֙ wĕ⁠ʼeţ-şá̂re֔y⁠há wa⁠yá̇bé֥ʼ ʼwòţá֛⁠m ʼélá֖y⁠w bá̇beֽlá⁠h׃"],[17,13,"וַ⁠יִּקַּח֙ מִ⁠זֶּ֣רַע הַ⁠מְּלוּכָ֔ה וַ⁠יִּכְרֹ֥ת אִתּ֖⁠וֹ בְּרִ֑ית וַ⁠יָּבֵ֤א אֹת⁠וֹ֙ בְּ⁠אָלָ֔ה וְ⁠אֶת־אֵילֵ֥י הָ⁠אָ֖רֶץ לָקָֽח׃","wa⁠yi̇qȧẖ֙ mi⁠zė֣raʻ ha⁠mĕ̇lẇká֔h wa⁠yi̇kĕrò֥ţ ʼiţ֖̇⁠wò bĕ̇ri֑yţ wa⁠yá̇bé֤ʼ ʼòţ⁠wò֙ bĕ̇⁠ʼálá֔h wĕ⁠ʼeţ-ʼéylé֥y há⁠ʼá֖reẕ láqáֽẖ׃"],[17,14,"לִֽ⁠הְיוֹת֙ מַמְלָכָ֣ה שְׁפָלָ֔ה לְ⁠בִלְתִּ֖י הִתְנַשֵּׂ֑א לִ⁠שְׁמֹ֥ר אֶת־בְּרִית֖⁠וֹ לְ⁠עָמְדָֽ⁠הּ׃","liֽ⁠hĕywòţ֙ mamĕláká֣h şĕ̌pálá֔h lĕ⁠bilĕţi֖̇y hiţĕnaşé֑̇̂ʼ li⁠şĕ̌mò֥r ʼeţ-bĕ̇riyţ֖⁠wò lĕ⁠ʻámĕdáֽ⁠ḣ׃"],[17,15,"וַ⁠יִּמְרָד־בּ֗⁠וֹ לִ⁠שְׁלֹ֤חַ מַלְאָכָי⁠ו֙ מִצְרַ֔יִם לָֽ⁠תֶת־ל֥⁠וֹ סוּסִ֖ים וְ⁠עַם־רָ֑ב הֲ⁠יִצְלָ֤ח הֲ⁠יִמָּלֵט֙ הָ⁠עֹשֵׂ֣ה אֵ֔לֶּה וְ⁠הֵפֵ֥ר בְּרִ֖ית וְ⁠נִמְלָֽט׃","wa⁠yi̇mĕrád-ḃ֗⁠wò li⁠şĕ̌lò֤ẖa malĕʼákáy⁠w֙ miẕĕra֔yim láֽ⁠ţeţ-l֥⁠wò sẇsi֖ym wĕ⁠ʻam-rá֑b hà⁠yiẕĕlá֤ẖ hà⁠yimá̇lét֙ há⁠ʻòşé֣̂h ʼé֔lėh wĕ⁠hépé֥r bĕ̇ri֖yţ wĕ⁠nimĕláֽt׃"],[17,16,"חַי־אָ֗נִי נְאֻם֮ אֲדֹנָ֣⁠י יְהוִה֒ אִם־לֹ֗א בִּ⁠מְקוֹם֙ הַ⁠מֶּ֨לֶךְ֙ הַ⁠מַּמְלִ֣יךְ אֹת֔⁠וֹ אֲשֶׁ֤ר בָּזָה֙ אֶת־אָ֣לָת֔⁠וֹ וַ⁠אֲשֶׁ֥ר הֵפֵ֖ר אֶת־בְּרִית֑⁠וֹ אִתּ֥⁠וֹ בְ⁠תוֹךְ־בָּבֶ֖ל יָמֽוּת׃","ẖay-ʼá֗niy nĕʼum֮ ʼàdòná֣⁠y yĕhwih֒ ʼim-lò֗ʼ bi̇⁠mĕqwòm֙ ha⁠mė֨lekĕ֙ ha⁠mȧmĕli֣ykĕ ʼòţ֔⁠wò ʼàşě֤r bá̇záh֙ ʼeţ-ʼá֣láţ֔⁠wò wa⁠ʼàşě֥r hépé֖r ʼeţ-bĕ̇riyţ֑⁠wò ʼiţ֥̇⁠wò bĕ⁠ţwòkĕ-bá̇be֖l yámֽẇţ׃"],[17,17,"וְ⁠לֹא֩ בְ⁠חַ֨יִל גָּד֜וֹל וּ⁠בְ⁠קָהָ֣ל רָ֗ב יַעֲשֶׂ֨ה אוֹת֤⁠וֹ פַרְעֹה֙ בַּ⁠מִּלְחָמָ֔ה בִּ⁠שְׁפֹּ֥ךְ סֹלְלָ֖ה וּ⁠בִ⁠בְנ֣וֹת דָּיֵ֑ק לְ⁠הַכְרִ֖ית נְפָשׁ֥וֹת רַבּֽוֹת׃","wĕ⁠lòʼ֩ bĕ⁠ẖa֨yil gá̇d֜wòl ẇ⁠bĕ⁠qáhá֣l rá֗b yaʻàşê֨h ʼwòţ֤⁠wò parĕʻòh֙ bȧ⁠mi̇lĕẖámá֔h bi̇⁠şĕ̌pò֥̇kĕ sòlĕlá֖h ẇ⁠bi⁠bĕn֣wòţ dá̇yé֑q lĕ⁠hakĕri֖yţ nĕpáş֥̌wòţ raḃֽwòţ׃"],[17,18,"וּ⁠בָזָ֥ה אָלָ֖ה לְ⁠הָפֵ֣ר בְּרִ֑ית וְ⁠הִנֵּ֨ה נָתַ֥ן יָד֛⁠וֹ וְ⁠כָל־אֵ֥לֶּה עָשָׂ֖ה לֹ֥א יִמָּלֵֽט׃ס","ẇ⁠bázá֥h ʼálá֖h lĕ⁠hápé֣r bĕ̇ri֑yţ wĕ⁠hiné̇֨h náţa֥n yád֛⁠wò wĕ⁠kál-ʼé֥lėh ʻáşá֖̂h lò֥ʼ yimá̇léֽt׃s"],[17,19,"לָ⁠כֵ֞ן כֹּה־אָמַ֨ר אֲדֹנָ֣⁠י יְהוִה֮ חַי־אָנִי֒ אִם־לֹ֗א אָֽלָתִ⁠י֙ אֲשֶׁ֣ר בָּזָ֔ה וּ⁠בְרִיתִ֖⁠י אֲשֶׁ֣ר הֵפִ֑יר וּ⁠נְתַתִּ֖י⁠ו בְּ⁠רֹאשֽׁ⁠וֹ׃","lá⁠ké֞n kò̇h-ʼáma֨r ʼàdòná֣⁠y yĕhwih֮ ẖay-ʼániy֒ ʼim-lò֗ʼ ʼáֽláţi⁠y֙ ʼàşě֣r bá̇zá֔h ẇ⁠bĕriyţi֖⁠y ʼàşě֣r hépi֑yr ẇ⁠nĕţaţi֖̇y⁠w bĕ̇⁠ròʼşֽ̌⁠wò׃"],[17,20,"וּ⁠פָרַשְׂתִּ֤י עָלָי⁠ו֙ רִשְׁתִּ֔⁠י וְ⁠נִתְפַּ֖שׂ בִּ⁠מְצֽוּדָתִ֑⁠י וַ⁠הֲבִיאוֹתִ֣י⁠הוּ בָבֶ֗לָ⁠ה וְ⁠נִשְׁפַּטְתִּ֤י אִתּ⁠וֹ֙ שָׁ֔ם מַעֲל֖⁠וֹ אֲשֶׁ֥ר מָֽעַל־בִּֽ⁠י׃","ẇ⁠páraşĕ̂ţi֤̇y ʻáláy⁠w֙ rişĕ̌ţi̇֔⁠y wĕ⁠niţĕpȧ֖ş̂ bi̇⁠mĕẕֽẇdáţi֑⁠y wa⁠hàbiyʼwòţi֣y⁠hẇ bábe֗lá⁠h wĕ⁠nişĕ̌pȧtĕţi֤̇y ʼiţ̇⁠wò֙ şá̌֔m maʻàl֖⁠wò ʼàşě֥r máֽʻal-biֽ̇⁠y׃"],[17,21,"וְ⁠אֵ֨ת כָּל־מברח⁠ו בְּ⁠כָל־אֲגַפָּי⁠ו֙ בַּ⁠חֶ֣רֶב יִפֹּ֔לוּ וְ⁠הַ⁠נִּשְׁאָרִ֖ים לְ⁠כָל־ר֣וּחַ יִפָּרֵ֑שׂוּ וִ⁠ידַעְתֶּ֕ם כִּ֛י אֲנִ֥י יְהוָ֖ה דִּבַּֽרְתִּי׃ס","wĕ⁠ʼé֨ţ ká̇l-mbrẖ⁠w bĕ̇⁠kál-ʼàgapá̇y⁠w֙ bȧ⁠ẖe֣reb yipò̇֔lẇ wĕ⁠ha⁠ni̇şĕ̌ʼári֖ym lĕ⁠kál-r֣ẇẖa yipá̇ré֑ş̂ẇ wi⁠ydaʻĕţė֕m ki֛̇y ʼàni֥y yĕhwá֖h di̇bȧֽrĕţi̇y׃s"],[17,22,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה וְ⁠לָקַ֣חְתִּי אָ֗נִי מִ⁠צַּמֶּ֧רֶת הָ⁠אֶ֛רֶז הָ⁠רָמָ֖ה וְ⁠נָתָ֑תִּי מֵ⁠רֹ֤אשׁ יֹֽנְקוֹתָי⁠ו֙ רַ֣ךְ אֶקְטֹ֔ף וְ⁠שָׁתַ֣לְתִּי אָ֔נִי עַ֥ל הַר־גָּבֹ֖הַ וְ⁠תָלֽוּל׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h wĕ⁠láqa֣ẖĕţi̇y ʼá֗niy mi⁠ẕȧmė֧reţ há⁠ʼe֛rez há⁠rámá֖h wĕ⁠náţá֑ţi̇y mé⁠rò֤ʼş̌ yòֽnĕqwòţáy⁠w֙ ra֣kĕ ʼeqĕtò֔p wĕ⁠şá̌ţa֣lĕţi̇y ʼá֔niy ʻa֥l har-gá̇bò֖ha wĕ⁠ţálֽẇl׃"],[17,23,"בְּ⁠הַ֨ר מְר֤וֹם יִשְׂרָאֵל֙ אֶשְׁתֳּלֶ֔⁠נּוּ וְ⁠נָשָׂ֤א עָנָף֙ וְ⁠עָ֣שָׂה פֶ֔רִי וְ⁠הָיָ֖ה לְ⁠אֶ֣רֶז אַדִּ֑יר וְ⁠שָׁכְנ֣וּ תַחְתָּ֗י⁠ו כֹּ֚ל צִפּ֣וֹר כָּל־כָּנָ֔ף בְּ⁠צֵ֥ל דָּלִיּוֹתָ֖י⁠ו תִּשְׁכֹּֽנָּה׃","bĕ̇⁠ha֨r mĕr֤wòm yişĕ̂ráʼél֙ ʼeşĕ̌ţȯle֔⁠ṅẇ wĕ⁠náşá֤̂ʼ ʻánáp֙ wĕ⁠ʻá֣şá̂h pe֔riy wĕ⁠háyá֖h lĕ⁠ʼe֣rez ʼadi֑̇yr wĕ⁠şá̌kĕn֣ẇ ţaẖĕţá̇֗y⁠w kò֚̇l ẕiṗ֣wòr ká̇l-ká̇ná֔p bĕ̇⁠ẕé֥l dá̇liẏwòţá֖y⁠w ţi̇şĕ̌kòֽ̇ná̇h׃"],[17,24,"וְֽ⁠יָדְע֞וּ כָּל־עֲצֵ֣י הַ⁠שָּׂדֶ֗ה כִּ֣י אֲנִ֤י יְהוָה֙ הִשְׁפַּ֣לְתִּי ׀ עֵ֣ץ גָּבֹ֗הַ הִגְבַּ֨הְתִּי֙ עֵ֣ץ שָׁפָ֔ל הוֹבַ֨שְׁתִּי֙ עֵ֣ץ לָ֔ח וְ⁠הִפְרַ֖חְתִּי עֵ֣ץ יָבֵ֑שׁ אֲנִ֥י יְהוָ֖ה דִּבַּ֥רְתִּי וְ⁠עָשִֽׂיתִי׃פ","wĕֽ⁠yádĕʻ֞ẇ ká̇l-ʻàẕé֣y ha⁠şá̇̂de֗h ki֣̇y ʼàni֤y yĕhwáh֙ hişĕ̌pȧ֣lĕţi̇y ׀ ʻé֣ẕ gá̇bò֗ha higĕbȧ֨hĕţi̇y֙ ʻé֣ẕ şá̌pá֔l hwòba֨şĕ̌ţi̇y֙ ʻé֣ẕ lá֔ẖ wĕ⁠hipĕra֖ẖĕţi̇y ʻé֣ẕ yábé֑ş̌ ʼàni֥y yĕhwá֖h di̇bȧ֥rĕţi̇y wĕ⁠ʻáşîֽyţiy׃p"],[18,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[18,2,"מַה־לָּ⁠כֶ֗ם אַתֶּם֙ מֹֽשְׁלִים֙ אֶת־הַ⁠מָּשָׁ֣ל הַ⁠זֶּ֔ה עַל־אַדְמַ֥ת יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר אָבוֹת֙ יֹ֣אכְלוּ בֹ֔סֶר וְ⁠שִׁנֵּ֥י הַ⁠בָּנִ֖ים תִּקְהֶֽינָה׃","mah-lá̇⁠ke֗m ʼaţėm֙ mòֽşĕ̌liym֙ ʼeţ-ha⁠má̇şá֣̌l ha⁠zė֔h ʻal-ʼadĕma֥ţ yişĕ̂ráʼé֖l lé⁠ʼmò֑r ʼábwòţ֙ yò֣ʼkĕlẇ bò֔ser wĕ⁠şǐné֥̇y ha⁠bá̇ni֖ym ţi̇qĕheֽynáh׃"],[18,3,"חַי־אָ֕נִי נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה אִם־יִֽהְיֶ֨ה לָ⁠כֶ֜ם ע֗וֹד מְשֹׁ֛ל הַ⁠מָּשָׁ֥ל הַ⁠זֶּ֖ה בְּ⁠יִשְׂרָאֵֽל׃","ẖay-ʼá֕niy nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h ʼim-yiֽhĕye֨h lá⁠ke֜m ʻ֗wòd mĕşò֛̌l ha⁠má̇şá֥̌l ha⁠zė֖h bĕ̇⁠yişĕ̂ráʼéֽl׃"],[18,4,"הֵ֤ן כָּל־הַ⁠נְּפָשׁוֹת֙ לִ֣⁠י הֵ֔נָּה כְּ⁠נֶ֧פֶשׁ הָ⁠אָ֛ב וּ⁠כְ⁠נֶ֥פֶשׁ הַ⁠בֵּ֖ן לִ⁠י־הֵ֑נָּה הַ⁠נֶּ֥פֶשׁ הַ⁠חֹטֵ֖את הִ֥יא תָמֽוּת׃ס","hé֤n ká̇l-ha⁠nĕ̇páş̌wòţ֙ li֣⁠y hé֔ná̇h kĕ̇⁠ne֧peş̌ há⁠ʼá֛b ẇ⁠kĕ⁠ne֥peş̌ ha⁠bé֖̇n li⁠y-hé֑ná̇h ha⁠nė֥peş̌ ha⁠ẖòté֖ʼţ hi֥yʼ ţámֽẇţ׃s"],[18,5,"וְ⁠אִ֖ישׁ כִּי־יִהְיֶ֣ה צַדִּ֑יק וְ⁠עָשָׂ֥ה מִשְׁפָּ֖ט וּ⁠צְדָקָֽה׃","wĕ⁠ʼi֖yş̌ ki̇y-yihĕye֣h ẕadi֑̇yq wĕ⁠ʻáşá֥̂h mişĕ̌pá֖̇t ẇ⁠ẕĕdáqáֽh׃"],[18,6,"אֶל־הֶֽ⁠הָרִים֙ לֹ֣א אָכָ֔ל וְ⁠עֵינָי⁠ו֙ לֹ֣א נָשָׂ֔א אֶל־גִּלּוּלֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל וְ⁠אֶת־אֵ֤שֶׁת רֵעֵ֨⁠הוּ֙ לֹ֣א טִמֵּ֔א וְ⁠אֶל־אִשָּׁ֥ה נִדָּ֖ה לֹ֥א יִקְרָֽב׃","ʼel-heֽ⁠háriym֙ lò֣ʼ ʼáká֔l wĕ⁠ʻéynáy⁠w֙ lò֣ʼ náşá̂֔ʼ ʼel-gi̇l̇ẇlé֖y bé֣̇yţ yişĕ̂ráʼé֑l wĕ⁠ʼeţ-ʼé֤şěţ réʻé֨⁠hẇ֙ lò֣ʼ timé̇֔ʼ wĕ⁠ʼel-ʼişá֥̇̌h nidá֖̇h lò֥ʼ yiqĕráֽb׃"],[18,7,"וְ⁠אִישׁ֙ לֹ֣א יוֹנֶ֔ה חֲבֹלָת֥⁠וֹ חוֹב֙ יָשִׁ֔יב גְּזֵלָ֖ה לֹ֣א יִגְזֹ֑ל לַחְמ⁠וֹ֙ לְ⁠רָעֵ֣ב יִתֵּ֔ן וְ⁠עֵירֹ֖ם יְכַסֶּה־בָּֽגֶד׃","wĕ⁠ʼiyş̌֙ lò֣ʼ ywòne֔h ẖàbòláţ֥⁠wò ẖwòb֙ yáşǐ֔yb gĕ̇zélá֖h lò֣ʼ yigĕzò֑l laẖĕm⁠wò֙ lĕ⁠ráʻé֣b yiţé̇֔n wĕ⁠ʻéyrò֖m yĕkasėh-báֽ̇ged׃"],[18,8,"בַּ⁠נֶּ֣שֶׁךְ לֹֽא־יִתֵּ֗ן וְ⁠תַרְבִּית֙ לֹ֣א יִקָּ֔ח מֵ⁠עָ֖וֶל יָשִׁ֣יב יָד֑⁠וֹ מִשְׁפַּ֤ט אֱמֶת֙ יַֽעֲשֶׂ֔ה בֵּ֥ין אִ֖ישׁ לְ⁠אִֽישׁ׃","bȧ⁠nė֣şěkĕ lòֽʼ-yiţé̇֗n wĕ⁠ţarĕbi̇yţ֙ lò֣ʼ yiqá̇֔ẖ mé⁠ʻá֖wel yáşǐ֣yb yád֑⁠wò mişĕ̌pȧ֤t ʼèmeţ֙ yaֽʻàşê֔h bé֥̇yn ʼi֖yş̌ lĕ⁠ʼiֽyş̌׃"],[18,9,"בְּ⁠חֻקּוֹתַ֧⁠י יְהַלֵּ֛ךְ וּ⁠מִשְׁפָּטַ֥⁠י שָׁמַ֖ר לַ⁠עֲשׂ֣וֹת אֱמֶ֑ת צַדִּ֥יק הוּא֙ חָיֹ֣ה יִֽחְיֶ֔ה נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","bĕ̇⁠ẖuq̇wòţa֧⁠y yĕhalé֛̇kĕ ẇ⁠mişĕ̌pá̇ta֥⁠y şá̌ma֖r la⁠ʻàş֣̂wòţ ʼème֑ţ ẕadi֥̇yq hẇʼ֙ ẖáyò֣h yiֽẖĕye֔h nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[18,10,"וְ⁠הוֹלִ֥יד בֵּן־פָּרִ֖יץ שֹׁפֵ֣ךְ דָּ֑ם וְ⁠עָ֣שָׂה אָ֔ח מֵ⁠אַחַ֖ד מֵ⁠אֵֽלֶּה׃","wĕ⁠hwòli֥yd bé̇n-pá̇ri֖yẕ şò̌pé֣kĕ dá֑̇m wĕ⁠ʻá֣şá̂h ʼá֔ẖ mé⁠ʼaẖa֖d mé⁠ʼéֽlėh׃"],[18,11,"וְ⁠ה֕וּא אֶת־כָּל־אֵ֖לֶּה לֹ֣א עָשָׂ֑ה כִּ֣י גַ֤ם אֶל־הֶֽ⁠הָרִים֙ אָכַ֔ל וְ⁠אֶת־אֵ֥שֶׁת רֵעֵ֖⁠הוּ טִמֵּֽא׃","wĕ⁠h֕ẇʼ ʼeţ-ká̇l-ʼé֖lėh lò֣ʼ ʻáşá֑̂h ki֣̇y ga֤m ʼel-heֽ⁠háriym֙ ʼáka֔l wĕ⁠ʼeţ-ʼé֥şěţ réʻé֖⁠hẇ timéֽ̇ʼ׃"],[18,12,"עָנִ֤י וְ⁠אֶבְיוֹן֙ הוֹנָ֔ה גְּזֵל֣וֹת גָּזָ֔ל חֲבֹ֖ל לֹ֣א יָשִׁ֑יב וְ⁠אֶל־הַ⁠גִּלּוּלִים֙ נָשָׂ֣א עֵינָ֔י⁠ו תּוֹעֵבָ֖ה עָשָֽׂה׃","ʻáni֤y wĕ⁠ʼebĕywòn֙ hwòná֔h gĕ̇zél֣wòţ gá̇zá֔l ẖàbò֖l lò֣ʼ yáşǐ֑yb wĕ⁠ʼel-ha⁠gi̇l̇ẇliym֙ náşá֣̂ʼ ʻéyná֔y⁠w ţ̇wòʻébá֖h ʻáşáֽ̂h׃"],[18,13,"בַּ⁠נֶּ֧שֶׁךְ נָתַ֛ן וְ⁠תַרְבִּ֥ית לָקַ֖ח וָ⁠חָ֑י לֹ֣א יִֽחְיֶ֗ה אֵ֣ת כָּל־הַ⁠תּוֹעֵב֤וֹת הָ⁠אֵ֨לֶּה֙ עָשָׂ֔ה מ֣וֹת יוּמָ֔ת דָּמָ֖י⁠ו בּ֥⁠וֹ יִהְיֶֽה׃","bȧ⁠nė֧şěkĕ náţa֛n wĕ⁠ţarĕbi֥̇yţ láqa֖ẖ wá⁠ẖá֑y lò֣ʼ yiֽẖĕye֗h ʼé֣ţ ká̇l-ha⁠ţ̇wòʻéb֤wòţ há⁠ʼé֨lėh֙ ʻáşá̂֔h m֣wòţ yẇmá֔ţ dá̇má֖y⁠w ḃ֥⁠wò yihĕyeֽh׃"],[18,14,"וְ⁠הִנֵּה֙ הוֹלִ֣יד בֵּ֔ן וַ⁠יַּ֕רְא אֶת־כָּל־חַטֹּ֥את אָבִ֖י⁠ו אֲשֶׁ֣ר עָשָׂ֑ה וַ⁠יִּרְאֶ֕ה וְ⁠לֹ֥א יַעֲשֶׂ֖ה כָּ⁠הֵֽן׃","wĕ⁠hiné̇h֙ hwòli֣yd bé̇֔n wa⁠yȧ֕rĕʼ ʼeţ-ká̇l-ẖatò֥̇ʼţ ʼábi֖y⁠w ʼàşě֣r ʻáşá֑̂h wa⁠yi̇rĕʼe֕h wĕ⁠lò֥ʼ yaʻàşê֖h ká̇⁠héֽn׃"],[18,15,"עַל־הֶֽ⁠הָרִים֙ לֹ֣א אָכָ֔ל וְ⁠עֵינָי⁠ו֙ לֹ֣א נָשָׂ֔א אֶל־גִּלּוּלֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל אֶת־אֵ֥שֶׁת רֵעֵ֖⁠הוּ לֹ֥א טִמֵּֽא׃","ʻal-heֽ⁠háriym֙ lò֣ʼ ʼáká֔l wĕ⁠ʻéynáy⁠w֙ lò֣ʼ náşá̂֔ʼ ʼel-gi̇l̇ẇlé֖y bé֣̇yţ yişĕ̂ráʼé֑l ʼeţ-ʼé֥şěţ réʻé֖⁠hẇ lò֥ʼ timéֽ̇ʼ׃"],[18,16,"וְ⁠אִישׁ֙ לֹ֣א הוֹנָ֔ה חֲבֹל֙ לֹ֣א חָבָ֔ל וּ⁠גְזֵלָ֖ה לֹ֣א גָזָ֑ל לַחְמ⁠וֹ֙ לְ⁠רָעֵ֣ב נָתָ֔ן וְ⁠עֵר֖וֹם כִּסָּה־בָֽגֶד׃","wĕ⁠ʼiyş̌֙ lò֣ʼ hwòná֔h ẖàbòl֙ lò֣ʼ ẖábá֔l ẇ⁠gĕzélá֖h lò֣ʼ gázá֑l laẖĕm⁠wò֙ lĕ⁠ráʻé֣b náţá֔n wĕ⁠ʻér֖wòm ki̇sá̇h-báֽged׃"],[18,17,"מֵ⁠עָנִ֞י הֵשִׁ֣יב יָד֗⁠וֹ נֶ֤שֶׁךְ וְ⁠תַרְבִּית֙ לֹ֣א לָקָ֔ח מִשְׁפָּטַ֣⁠י עָשָׂ֔ה בְּ⁠חֻקּוֹתַ֖⁠י הָלָ֑ךְ ה֗וּא לֹ֥א יָמ֛וּת בַּ⁠עֲוֺ֥ן אָבִ֖י⁠ו חָיֹ֥ה יִחְיֶֽה׃","mé⁠ʻáni֞y héşǐ֣yb yád֗⁠wò ne֤şěkĕ wĕ⁠ţarĕbi̇yţ֙ lò֣ʼ láqá֔ẖ mişĕ̌pá̇ta֣⁠y ʻáşá̂֔h bĕ̇⁠ẖuq̇wòţa֖⁠y hálá֑kĕ h֗ẇʼ lò֥ʼ yám֛ẇţ bȧ⁠ʻàwֺ֥n ʼábi֖y⁠w ẖáyò֥h yiẖĕyeֽh׃"],[18,18,"אָבִ֞י⁠ו כִּֽי־עָ֣שַׁק עֹ֗שֶׁק גָּזַל֙ גֵּ֣זֶל אָ֔ח וַ⁠אֲשֶׁ֥ר לֹא־ט֛וֹב עָשָׂ֖ה בְּ⁠ת֣וֹךְ עַמָּ֑י⁠ו וְ⁠הִנֵּה־מֵ֖ת בַּ⁠עֲוֺנֽ⁠וֹ׃","ʼábi֞y⁠w kiֽ̇y-ʻá֣şǎq ʻò֗şěq gá̇zal֙ gé֣̇zel ʼá֔ẖ wa⁠ʼàşě֥r lòʼ-t֛wòb ʻáşá֖̂h bĕ̇⁠ţ֣wòkĕ ʻamá֑̇y⁠w wĕ⁠hiné̇h-mé֖ţ bȧ⁠ʻàwֺnֽ⁠wò׃"],[18,19,"וַ⁠אֲמַרְתֶּ֕ם מַדֻּ֛עַ לֹא־נָשָׂ֥א הַ⁠בֵּ֖ן בַּ⁠עֲוֺ֣ן הָ⁠אָ֑ב וְ⁠הַ⁠בֵּ֞ן מִשְׁפָּ֧ט וּ⁠צְדָקָ֣ה עָשָׂ֗ה אֵ֣ת כָּל־חֻקּוֹתַ֥⁠י שָׁמַ֛ר וַ⁠יַּעֲשֶׂ֥ה אֹתָ֖⁠ם חָיֹ֥ה יִחְיֶֽה׃","wa⁠ʼàmarĕţė֕m madu֛̇ʻa lòʼ-náşá֥̂ʼ ha⁠bé֖̇n bȧ⁠ʻàwֺ֣n há⁠ʼá֑b wĕ⁠ha⁠bé̇֞n mişĕ̌pá֧̇t ẇ⁠ẕĕdáqá֣h ʻáşá̂֗h ʼé֣ţ ká̇l-ẖuq̇wòţa֥⁠y şá̌ma֛r wa⁠yȧʻàşê֥h ʼòţá֖⁠m ẖáyò֥h yiẖĕyeֽh׃"],[18,20,"הַ⁠נֶּ֥פֶשׁ הַ⁠חֹטֵ֖את הִ֣יא תָמ֑וּת בֵּ֞ן לֹא־יִשָּׂ֣א ׀ בַּ⁠עֲוֺ֣ן הָ⁠אָ֗ב וְ⁠אָב֙ לֹ֤א יִשָּׂא֙ בַּ⁠עֲוֺ֣ן הַ⁠בֵּ֔ן צִדְקַ֤ת הַ⁠צַּדִּיק֙ עָלָ֣י⁠ו תִּֽהְיֶ֔ה וְ⁠רִשְׁעַ֥ת רשע עָלָ֥י⁠ו תִּֽהְיֶֽה׃ס","ha⁠nė֥peş̌ ha⁠ẖòté֖ʼţ hi֣yʼ ţám֑ẇţ bé̇֞n lòʼ-yişá֣̇̂ʼ ׀ bȧ⁠ʻàwֺ֣n há⁠ʼá֗b wĕ⁠ʼáb֙ lò֤ʼ yişá̇̂ʼ֙ bȧ⁠ʻàwֺ֣n ha⁠bé̇֔n ẕidĕqa֤ţ ha⁠ẕȧdi̇yq֙ ʻálá֣y⁠w ţiֽ̇hĕye֔h wĕ⁠rişĕ̌ʻa֥ţ rşʻ ʻálá֥y⁠w ţiֽ̇hĕyeֽh׃s"],[18,21,"וְ⁠הָ⁠רָשָׁ֗ע כִּ֤י יָשׁוּב֙ מִ⁠כָּל־חטאת⁠ו אֲשֶׁ֣ר עָשָׂ֔ה וְ⁠שָׁמַר֙ אֶת־כָּל־חֻקּוֹתַ֔⁠י וְ⁠עָשָׂ֥ה מִשְׁפָּ֖ט וּ⁠צְדָקָ֑ה חָיֹ֥ה יִחְיֶ֖ה לֹ֥א יָמֽוּת׃","wĕ⁠há⁠ráşá̌֗ʻ ki֤̇y yáş̌ẇb֙ mi⁠ká̇l-ẖtʼţ⁠w ʼàşě֣r ʻáşá̂֔h wĕ⁠şá̌mar֙ ʼeţ-ká̇l-ẖuq̇wòţa֔⁠y wĕ⁠ʻáşá֥̂h mişĕ̌pá֖̇t ẇ⁠ẕĕdáqá֑h ẖáyò֥h yiẖĕye֖h lò֥ʼ yámֽẇţ׃"],[18,22,"כָּל־פְּשָׁעָי⁠ו֙ אֲשֶׁ֣ר עָשָׂ֔ה לֹ֥א יִזָּכְר֖וּ ל֑⁠וֹ בְּ⁠צִדְקָת֥⁠וֹ אֲשֶׁר־עָשָׂ֖ה יִֽחְיֶֽה׃","ká̇l-pĕ̇şá̌ʻáy⁠w֙ ʼàşě֣r ʻáşá̂֔h lò֥ʼ yizá̇kĕr֖ẇ l֑⁠wò bĕ̇⁠ẕidĕqáţ֥⁠wò ʼàşěr-ʻáşá֖̂h yiֽẖĕyeֽh׃"],[18,23,"הֶ⁠חָפֹ֤ץ אֶחְפֹּץ֙ מ֣וֹת רָשָׁ֔ע נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה הֲ⁠ל֛וֹא בְּ⁠שׁוּב֥⁠וֹ מִ⁠דְּרָכָ֖י⁠ו וְ⁠חָיָֽה׃ס","he⁠ẖápò֤ẕ ʼeẖĕpò̇ẕ֙ m֣wòţ ráşá̌֔ʻ nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h hà⁠l֛wòʼ bĕ̇⁠ş̌ẇb֥⁠wò mi⁠dĕ̇ráká֖y⁠w wĕ⁠ẖáyáֽh׃s"],[18,24,"וּ⁠בְ⁠שׁ֨וּב צַדִּ֤יק מִ⁠צִּדְקָת⁠וֹ֙ וְ⁠עָ֣שָׂה עָ֔וֶל כְּ⁠כֹ֨ל הַ⁠תּוֹעֵב֜וֹת אֲשֶׁר־עָשָׂ֧ה הָ⁠רָשָׁ֛ע יַעֲשֶׂ֖ה וָ⁠חָ֑י כָּל־צדקת⁠ו אֲשֶׁר־עָשָׂה֙ לֹ֣א תִזָּכַ֔רְנָה בְּ⁠מַעֲל֧⁠וֹ אֲשֶׁר־מָעַ֛ל וּ⁠בְ⁠חַטָּאת֥⁠וֹ אֲשֶׁר־חָטָ֖א בָּ֥⁠ם יָמֽוּת׃","ẇ⁠bĕ⁠ş̌֨ẇb ẕadi֤̇yq mi⁠ẕi̇dĕqáţ⁠wò֙ wĕ⁠ʻá֣şá̂h ʻá֔wel kĕ̇⁠kò֨l ha⁠ţ̇wòʻéb֜wòţ ʼàşěr-ʻáşá֧̂h há⁠ráşá֛̌ʻ yaʻàşê֖h wá⁠ẖá֑y ká̇l-ẕdqţ⁠w ʼàşěr-ʻáşá̂h֙ lò֣ʼ ţizá̇ka֔rĕnáh bĕ̇⁠maʻàl֧⁠wò ʼàşěr-máʻa֛l ẇ⁠bĕ⁠ẖatá̇ʼţ֥⁠wò ʼàşěr-ẖátá֖ʼ bá֥̇⁠m yámֽẇţ׃"],[18,25,"וַ⁠אֲמַרְתֶּ֕ם לֹ֥א יִתָּכֵ֖ן דֶּ֣רֶךְ אֲדֹנָ֑⁠י שִׁמְעוּ־נָא֙ בֵּ֣ית יִשְׂרָאֵ֔ל הֲ⁠דַרְכִּ⁠י֙ לֹ֣א יִתָּכֵ֔ן הֲ⁠לֹ֥א דַרְכֵי⁠כֶ֖ם לֹ֥א יִתָּכֵֽנוּ׃","wa⁠ʼàmarĕţė֕m lò֥ʼ yiţá̇ké֖n dė֣rekĕ ʼàdòná֑⁠y şǐmĕʻẇ-náʼ֙ bé֣̇yţ yişĕ̂ráʼé֔l hà⁠darĕki̇⁠y֙ lò֣ʼ yiţá̇ké֔n hà⁠lò֥ʼ darĕkéy⁠ke֖m lò֥ʼ yiţá̇kéֽnẇ׃"],[18,26,"בְּ⁠שׁוּב־צַדִּ֧יק מִ⁠צִּדְקָת֛⁠וֹ וְ⁠עָ֥שָׂה עָ֖וֶל וּ⁠מֵ֣ת עֲלֵי⁠הֶ֑ם בְּ⁠עַוְל֥⁠וֹ אֲשֶׁר־עָשָׂ֖ה יָמֽוּת׃ס","bĕ̇⁠ş̌ẇb-ẕadi֧̇yq mi⁠ẕi̇dĕqáţ֛⁠wò wĕ⁠ʻá֥şá̂h ʻá֖wel ẇ⁠mé֣ţ ʻàléy⁠he֑m bĕ̇⁠ʻawĕl֥⁠wò ʼàşěr-ʻáşá֖̂h yámֽẇţ׃s"],[18,27,"וּ⁠בְ⁠שׁ֣וּב רָשָׁ֗ע מֵֽ⁠רִשְׁעָת⁠וֹ֙ אֲשֶׁ֣ר עָשָׂ֔ה וַ⁠יַּ֥עַשׂ מִשְׁפָּ֖ט וּ⁠צְדָקָ֑ה ה֖וּא אֶת־נַפְשׁ֥⁠וֹ יְחַיֶּֽה׃","ẇ⁠bĕ⁠ş֣̌ẇb ráşá̌֗ʻ méֽ⁠rişĕ̌ʻáţ⁠wò֙ ʼàşě֣r ʻáşá̂֔h wa⁠yȧ֥ʻaş̂ mişĕ̌pá֖̇t ẇ⁠ẕĕdáqá֑h h֖ẇʼ ʼeţ-napĕş֥̌⁠wò yĕẖayėֽh׃"],[18,28,"וַ⁠יִּרְאֶ֣ה ו⁠ישוב מִ⁠כָּל־פְּשָׁעָ֖י⁠ו אֲשֶׁ֣ר עָשָׂ֑ה חָי֥וֹ יִחְיֶ֖ה לֹ֥א יָמֽוּת׃","wa⁠yi̇rĕʼe֣h w⁠yşwb mi⁠ká̇l-pĕ̇şá̌ʻá֖y⁠w ʼàşě֣r ʻáşá֑̂h ẖáy֥wò yiẖĕye֖h lò֥ʼ yámֽẇţ׃"],[18,29,"וְ⁠אָֽמְרוּ֙ בֵּ֣ית יִשְׂרָאֵ֔ל לֹ֥א יִתָּכֵ֖ן דֶּ֣רֶךְ אֲדֹנָ֑⁠י הַ⁠דְּרָכַ֞⁠י לֹ֤א יִתָּֽכְנּוּ֙ בֵּ֣ית יִשְׂרָאֵ֔ל הֲ⁠לֹ֥א דַרְכֵי⁠כֶ֖ם לֹ֥א יִתָּכֵֽן׃","wĕ⁠ʼáֽmĕrẇ֙ bé֣̇yţ yişĕ̂ráʼé֔l lò֥ʼ yiţá̇ké֖n dė֣rekĕ ʼàdòná֑⁠y ha⁠dĕ̇ráka֞⁠y lò֤ʼ yiţáֽ̇kĕṅẇ֙ bé֣̇yţ yişĕ̂ráʼé֔l hà⁠lò֥ʼ darĕkéy⁠ke֖m lò֥ʼ yiţá̇kéֽn׃"],[18,30,"לָ⁠כֵן֩ אִ֨ישׁ כִּ⁠דְרָכָ֜י⁠ו אֶשְׁפֹּ֤ט אֶתְ⁠כֶם֙ בֵּ֣ית יִשְׂרָאֵ֔ל נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה שׁ֤וּבוּ וְ⁠הָשִׁ֨יבוּ֙ מִ⁠כָּל־פִּשְׁעֵי⁠כֶ֔ם וְ⁠לֹֽא־יִהְיֶ֥ה לָ⁠כֶ֛ם לְ⁠מִכְשׁ֖וֹל עָוֺֽן׃","lá⁠kén֩ ʼi֨yş̌ ki̇⁠dĕráká֜y⁠w ʼeşĕ̌pò֤̇t ʼeţĕ⁠kem֙ bé֣̇yţ yişĕ̂ráʼé֔l nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h ş֤̌ẇbẇ wĕ⁠háşǐ֨ybẇ֙ mi⁠ká̇l-pi̇şĕ̌ʻéy⁠ke֔m wĕ⁠lòֽʼ-yihĕye֥h lá⁠ke֛m lĕ⁠mikĕş֖̌wòl ʻáwֺֽn׃"],[18,31,"הַשְׁלִ֣יכוּ מֵ⁠עֲלֵי⁠כֶ֗ם אֶת־כָּל־פִּשְׁעֵי⁠כֶם֙ אֲשֶׁ֣ר פְּשַׁעְתֶּ֣ם בָּ֔⁠ם וַ⁠עֲשׂ֥וּ לָ⁠כֶ֛ם לֵ֥ב חָדָ֖שׁ וְ⁠ר֣וּחַ חֲדָשָׁ֑ה וְ⁠לָ֥⁠מָּה תָמֻ֖תוּ בֵּ֥ית יִשְׂרָאֵֽל׃","haşĕ̌li֣ykẇ mé⁠ʻàléy⁠ke֗m ʼeţ-ká̇l-pi̇şĕ̌ʻéy⁠kem֙ ʼàşě֣r pĕ̇şǎʻĕţė֣m bá̇֔⁠m wa⁠ʻàş֥̂ẇ lá⁠ke֛m lé֥b ẖádá֖ş̌ wĕ⁠r֣ẇẖa ẖàdáşá֑̌h wĕ⁠lá֥⁠má̇h ţámu֖ţẇ bé֥̇yţ yişĕ̂ráʼéֽl׃"],[18,32,"כִּ֣י לֹ֤א אֶחְפֹּץ֙ בְּ⁠מ֣וֹת הַ⁠מֵּ֔ת נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה וְ⁠הָשִׁ֖יבוּ וִֽ⁠חְיֽוּ׃פ","ki֣̇y lò֤ʼ ʼeẖĕpò̇ẕ֙ bĕ̇⁠m֣wòţ ha⁠mé̇֔ţ nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h wĕ⁠háşǐ֖ybẇ wiֽ⁠ẖĕyֽẇ׃p"],[19,1,"וְ⁠אַתָּה֙ שָׂ֣א קִינָ֔ה אֶל־נְשִׂיאֵ֖י יִשְׂרָאֵֽל׃","wĕ⁠ʼaţá̇h֙ şá֣̂ʼ qiyná֔h ʼel-nĕşîyʼé֖y yişĕ̂ráʼéֽl׃"],[19,2,"וְ⁠אָמַרְתָּ֗ מָ֤ה אִמְּ⁠ךָ֙ לְבִיָּ֔א בֵּ֥ין אֲרָי֖וֹת רָבָ֑צָה בְּ⁠ת֥וֹךְ כְּפִרִ֖ים רִבְּתָ֥ה גוּרֶֽי⁠הָ׃","wĕ⁠ʼámarĕţá̇֗ má֤h ʼimĕ̇⁠ká֙ lĕbiyá̇֔ʼ bé֥̇yn ʼàráy֖wòţ rábá֑ẕáh bĕ̇⁠ţ֥wòkĕ kĕ̇piri֖ym ribĕ̇ţá֥h gẇreֽy⁠há׃"],[19,3,"וַ⁠תַּ֛עַל אֶחָ֥ד מִ⁠גֻּרֶ֖י⁠הָ כְּפִ֣יר הָיָ֑ה וַ⁠יִּלְמַ֥ד לִ⁠טְרָף־טֶ֖רֶף אָדָ֥ם אָכָֽל׃","wa⁠ţȧ֛ʻal ʼeẖá֥d mi⁠gu̇re֖y⁠há kĕ̇pi֣yr háyá֑h wa⁠yi̇lĕma֥d li⁠tĕráp-te֖rep ʼádá֥m ʼákáֽl׃"],[19,4,"וַ⁠יִּשְׁמְע֥וּ אֵלָ֛י⁠ו גּוֹיִ֖ם בְּ⁠שַׁחְתָּ֣⁠ם נִתְפָּ֑שׂ וַ⁠יְבִאֻ֥⁠הוּ בַֽ⁠חַחִ֖ים אֶל־אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yi̇şĕ̌mĕʻ֥ẇ ʼélá֛y⁠w ġwòyi֖m bĕ̇⁠şǎẖĕţá֣̇⁠m niţĕpá֑̇ş̂ wa⁠yĕbiʼu֥⁠hẇ baֽ⁠ẖaẖi֖ym ʼel-ʼe֥reẕ miẕĕráֽyim׃"],[19,5,"וַ⁠תֵּ֨רֶא֙ כִּ֣י נֽוֹחֲלָ֔ה אָבְדָ֖ה תִּקְוָתָ֑⁠הּ וַ⁠תִּקַּ֛ח אֶחָ֥ד מִ⁠גֻּרֶ֖י⁠הָ כְּפִ֥יר שָׂמָֽתְ⁠הוּ׃","wa⁠ţé̇֨reʼ֙ ki֣̇y nֽwòẖàlá֔h ʼábĕdá֖h ţi̇qĕwáţá֑⁠ḣ wa⁠ţi̇qȧ֛ẖ ʼeẖá֥d mi⁠gu̇re֖y⁠há kĕ̇pi֥yr şá̂máֽţĕ⁠hẇ׃"],[19,6,"וַ⁠יִּתְהַלֵּ֥ךְ בְּ⁠תוֹךְ־אֲרָי֖וֹת כְּפִ֣יר הָיָ֑ה וַ⁠יִּלְמַ֥ד לִ⁠טְרָף־טֶ֖רֶף אָדָ֥ם אָכָֽל׃","wa⁠yi̇ţĕhalé֥̇kĕ bĕ̇⁠ţwòkĕ-ʼàráy֖wòţ kĕ̇pi֣yr háyá֑h wa⁠yi̇lĕma֥d li⁠tĕráp-te֖rep ʼádá֥m ʼákáֽl׃"],[19,7,"וַ⁠יֵּ֨דַע֙ אַלְמְנוֹתָ֔י⁠ו וְ⁠עָרֵי⁠הֶ֖ם הֶחֱרִ֑יב וַ⁠תֵּ֤שַׁם אֶ֨רֶץ֙ וּ⁠מְלֹאָ֔⁠הּ מִ⁠קּ֖וֹל שַׁאֲגָתֽ⁠וֹ׃","wa⁠yé̇֨daʻ֙ ʼalĕmĕnwòţá֔y⁠w wĕ⁠ʻáréy⁠he֖m heẖèri֑yb wa⁠ţé֤̇şǎm ʼe֨reẕ֙ ẇ⁠mĕlòʼá֔⁠ḣ mi⁠q֖̇wòl şǎʼàgáţֽ⁠wò׃"],[19,8,"וַ⁠יִּתְּנ֨וּ עָלָ֥י⁠ו גּוֹיִ֛ם סָבִ֖יב מִ⁠מְּדִינ֑וֹת וַֽ⁠יִּפְרְשׂ֥וּ עָלָ֛י⁠ו רִשְׁתָּ֖⁠ם בְּ⁠שַׁחְתָּ֥⁠ם נִתְפָּֽשׂ׃","wa⁠yi̇ţĕ̇n֨ẇ ʻálá֥y⁠w ġwòyi֛m sábi֖yb mi⁠mĕ̇diyn֑wòţ waֽ⁠yi̇pĕrĕş֥̂ẇ ʻálá֛y⁠w rişĕ̌ţá֖̇⁠m bĕ̇⁠şǎẖĕţá֥̇⁠m niţĕpáֽ̇ş̂׃"],[19,9,"וַֽ⁠יִּתְּנֻ֤⁠הוּ בַ⁠סּוּגַר֙ בַּֽ⁠חַחִ֔ים וַ⁠יְבִאֻ֖⁠הוּ אֶל־מֶ֣לֶךְ בָּבֶ֑ל יְבִאֻ֨⁠הוּ֙ בַּ⁠מְּצֹד֔וֹת לְמַ֗עַן לֹא־יִשָּׁמַ֥ע קוֹל֛⁠וֹ ע֖וֹד אֶל־הָרֵ֥י יִשְׂרָאֵֽל׃פ","waֽ⁠yi̇ţĕ̇nu֤⁠hẇ ba⁠ṡẇgar֙ bȧֽ⁠ẖaẖi֔ym wa⁠yĕbiʼu֖⁠hẇ ʼel-me֣lekĕ bá̇be֑l yĕbiʼu֨⁠hẇ֙ bȧ⁠mĕ̇ẕòd֔wòţ lĕma֗ʻan lòʼ-yişá̇̌ma֥ʻ qwòl֛⁠wò ʻ֖wòd ʼel-háré֥y yişĕ̂ráʼéֽl׃p"],[19,10,"אִמְּ⁠ךָ֥ כַ⁠גֶּ֛פֶן בְּ⁠דָמְ⁠ךָ֖ עַל־מַ֣יִם שְׁתוּלָ֑ה פֹּֽרִיָּה֙ וַֽ⁠עֲנֵפָ֔ה הָיְתָ֖ה מִ⁠מַּ֥יִם רַבִּֽים׃","ʼimĕ̇⁠ká֥ ka⁠gė֛pen bĕ̇⁠dámĕ⁠ká֖ ʻal-ma֣yim şĕ̌ţẇlá֑h pòֽ̇riyá̇h֙ waֽ⁠ʻànépá֔h háyĕţá֖h mi⁠mȧ֥yim rabiֽ̇ym׃"],[19,11,"וַ⁠יִּֽהְיוּ־לָ֞⁠הּ מַטּ֣וֹת עֹ֗ז אֶל־שִׁבְטֵי֙ מֹֽשְׁלִ֔ים וַ⁠תִּגְבַּ֥הּ קֽוֹמָת֖⁠וֹ עַל־בֵּ֣ין עֲבֹתִ֑ים וַ⁠יֵּרָ֣א בְ⁠גָבְה֔⁠וֹ בְּ⁠רֹ֖ב דָּלִיֹּתָֽי⁠ו׃","wa⁠yiֽ̇hĕyẇ-lá֞⁠ḣ maṫ֣wòţ ʻò֗z ʼel-şǐbĕtéy֙ mòֽşĕ̌li֔ym wa⁠ţi̇gĕbȧ֥ḣ qֽwòmáţ֖⁠wò ʻal-bé֣̇yn ʻàbòţi֑ym wa⁠yé̇rá֣ʼ bĕ⁠gábĕh֔⁠wò bĕ̇⁠rò֖b dá̇liyò̇ţáֽy⁠w׃"],[19,12,"וַ⁠תֻּתַּ֤שׁ בְּ⁠חֵמָה֙ לָ⁠אָ֣רֶץ הֻשְׁלָ֔כָה וְ⁠ר֥וּחַ הַ⁠קָּדִ֖ים הוֹבִ֣ישׁ פִּרְיָ֑⁠הּ הִתְפָּרְק֧וּ וְ⁠יָבֵ֛שׁוּ מַטֵּ֥ה עֻזָּ֖⁠הּ אֵ֥שׁ אֲכָלָֽתְ⁠הוּ׃","wa⁠ţu̇ţȧ֤ş̌ bĕ̇⁠ẖémáh֙ lá⁠ʼá֣reẕ huşĕ̌lá֔káh wĕ⁠r֥ẇẖa ha⁠qá̇di֖ym hwòbi֣yş̌ pi̇rĕyá֑⁠ḣ hiţĕpá̇rĕq֧ẇ wĕ⁠yábé֛ş̌ẇ maté֥̇h ʻuzá֖̇⁠ḣ ʼé֥ş̌ ʼàkáláֽţĕ⁠hẇ׃"],[19,13,"וְ⁠עַתָּ֖ה שְׁתוּלָ֣ה בַ⁠מִּדְבָּ֑ר בְּ⁠אֶ֖רֶץ צִיָּ֥ה וְ⁠צָמָֽא׃","wĕ⁠ʻaţá֖̇h şĕ̌ţẇlá֣h ba⁠mi̇dĕbá֑̇r bĕ̇⁠ʼe֖reẕ ẕiyá֥̇h wĕ⁠ẕámáֽʼ׃"],[19,14,"וַ⁠תֵּצֵ֨א אֵ֜שׁ מִ⁠מַּטֵּ֤ה בַדֶּ֨י⁠הָ֙ פִּרְיָ֣⁠הּ אָכָ֔לָה וְ⁠לֹא־הָ֥יָה בָ֛⁠הּ מַטֵּה־עֹ֖ז שֵׁ֣בֶט לִ⁠מְשׁ֑וֹל קִ֥ינָה הִ֖יא וַ⁠תְּהִ֥י לְ⁠קִינָֽה׃פ","wa⁠ţé̇ẕé֨ʼ ʼé֜ş̌ mi⁠mȧté֤̇h badė֨y⁠há֙ pi̇rĕyá֣⁠ḣ ʼáká֔láh wĕ⁠lòʼ-há֥yáh bá֛⁠ḣ maté̇h-ʻò֖z şé֣̌bet li⁠mĕş֑̌wòl qi֥ynáh hi֖yʼ wa⁠ţĕ̇hi֥y lĕ⁠qiynáֽh׃p"],[20,1,"וַ⁠יְהִ֣י ׀ בַּ⁠שָּׁנָ֣ה הַ⁠שְּׁבִיעִ֗ית בַּֽ⁠חֲמִשִׁי֙ בֶּ⁠עָשׂ֣וֹר לַ⁠חֹ֔דֶשׁ בָּ֧אוּ אֲנָשִׁ֛ים מִ⁠זִּקְנֵ֥י יִשְׂרָאֵ֖ל לִ⁠דְרֹ֣שׁ אֶת־יְהוָ֑ה וַ⁠יֵּשְׁב֖וּ לְ⁠פָנָֽ⁠י׃ס","wa⁠yĕhi֣y ׀ bȧ⁠şá̇̌ná֣h ha⁠şĕ̇̌biyʻi֗yţ bȧֽ⁠ẖàmişǐy֙ bė⁠ʻáş֣̂wòr la⁠ẖò֔deş̌ bá֧̇ʼẇ ʼànáşǐ֛ym mi⁠zi̇qĕné֥y yişĕ̂ráʼé֖l li⁠dĕrò֣ş̌ ʼeţ-yĕhwá֑h wa⁠yé̇şĕ̌b֖ẇ lĕ⁠pánáֽ⁠y׃s"],[20,2,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[20,3,"בֶּן־אָדָ֗ם דַּבֵּ֞ר אֶת־זִקְנֵ֤י יִשְׂרָאֵל֙ וְ⁠אָמַרְתָּ֣ אֲלֵ⁠הֶ֔ם כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הֲ⁠לִ⁠דְרֹ֥שׁ אֹתִ֖⁠י אַתֶּ֣ם בָּאִ֑ים חַי־אָ֨נִי֙ אִם־אִדָּרֵ֣שׁ לָ⁠כֶ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","bėn-ʼádá֗m dȧbé̇֞r ʼeţ-ziqĕné֤y yişĕ̂ráʼél֙ wĕ⁠ʼámarĕţá֣̇ ʼàlé⁠he֔m kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hà⁠li⁠dĕrò֥ş̌ ʼòţi֖⁠y ʼaţė֣m bá̇ʼi֑ym ẖay-ʼá֨niy֙ ʼim-ʼidá̇ré֣ş̌ lá⁠ke֔m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[20,4,"הֲ⁠תִשְׁפֹּ֣ט אֹתָ֔⁠ם הֲ⁠תִשְׁפּ֖וֹט בֶּן־אָדָ֑ם אֶת־תּוֹעֲבֹ֥ת אֲבוֹתָ֖⁠ם הוֹדִיעֵֽ⁠ם׃","hà⁠ţişĕ̌pò֣̇t ʼòţá֔⁠m hà⁠ţişĕ̌ṗ֖wòt bėn-ʼádá֑m ʼeţ-ţ̇wòʻàbò֥ţ ʼàbwòţá֖⁠m hwòdiyʻéֽ⁠m׃"],[20,5,"וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֗ם כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ בְּ⁠יוֹם֙ בָּחֳרִ֣⁠י בְ⁠יִשְׂרָאֵ֔ל וָ⁠אֶשָּׂ֣א יָדִ֗⁠י לְ⁠זֶ֨רַע֙ בֵּ֣ית יַֽעֲקֹ֔ב וָ⁠אִוָּדַ֥ע לָ⁠הֶ֖ם בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם וָ⁠אֶשָּׂ֨א יָדִ֤⁠י לָ⁠הֶם֙ לֵ⁠אמֹ֔ר אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֗m kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ bĕ̇⁠ywòm֙ bá̇ẖori֣⁠y bĕ⁠yişĕ̂ráʼé֔l wá⁠ʼeşá֣̇̂ʼ yádi֗⁠y lĕ⁠ze֨raʻ֙ bé֣̇yţ yaֽʻàqò֔b wá⁠ʼiwá̇da֥ʻ lá⁠he֖m bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim wá⁠ʼeşá̇̂֨ʼ yádi֤⁠y lá⁠hem֙ lé⁠ʼmò֔r ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[20,6,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא נָשָׂ֤אתִי יָדִ⁠י֙ לָ⁠הֶ֔ם לְ⁠הֽוֹצִיאָ֖⁠ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם אֶל־אֶ֜רֶץ אֲשֶׁר־תַּ֣רְתִּי לָ⁠הֶ֗ם זָבַ֤ת חָלָב֙ וּ⁠דְבַ֔שׁ צְבִ֥י הִ֖יא לְ⁠כָל־הָ⁠אֲרָצֽוֹת׃","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ náşá֤̂ʼţiy yádi⁠y֙ lá⁠he֔m lĕ⁠hֽwòẕiyʼá֖⁠m mé⁠ʼe֣reẕ miẕĕrá֑yim ʼel-ʼe֜reẕ ʼàşěr-ţȧ֣rĕţi̇y lá⁠he֗m zába֤ţ ẖáláb֙ ẇ⁠dĕba֔ş̌ ẕĕbi֥y hi֖yʼ lĕ⁠kál-há⁠ʼàráẕֽwòţ׃"],[20,7,"וָ⁠אֹמַ֣ר אֲלֵ⁠הֶ֗ם אִ֣ישׁ שִׁקּוּצֵ֤י עֵינָי⁠ו֙ הַשְׁלִ֔יכוּ וּ⁠בְ⁠גִלּוּלֵ֥י מִצְרַ֖יִם אַל־תִּטַּמָּ֑אוּ אֲנִ֖י יְהוָ֥ה אֱלֹהֵי⁠כֶֽם׃","wá⁠ʼòma֣r ʼàlé⁠he֗m ʼi֣yş̌ şǐq̇ẇẕé֤y ʻéynáy⁠w֙ haşĕ̌li֔ykẇ ẇ⁠bĕ⁠gil̇ẇlé֥y miẕĕra֖yim ʼal-ţi̇tȧmá֑̇ʼẇ ʼàni֖y yĕhwá֥h ʼèlòhéy⁠keֽm׃"],[20,8,"וַ⁠יַּמְרוּ־בִ֗⁠י וְ⁠לֹ֤א אָבוּ֙ לִּ⁠שְׁמֹ֣עַ אֵלַ֔⁠י אִ֣ישׁ אֶת־שִׁקּוּצֵ֤י עֵֽינֵי⁠הֶם֙ לֹ֣א הִשְׁלִ֔יכוּ וְ⁠אֶת־גִּלּוּלֵ֥י מִצְרַ֖יִם לֹ֣א עָזָ֑בוּ וָ⁠אֹמַ֞ר לִ⁠שְׁפֹּ֧ךְ חֲמָתִ֣⁠י עֲלֵי⁠הֶ֗ם לְ⁠כַלּ֤וֹת אַפִּ⁠י֙ בָּ⁠הֶ֔ם בְּ⁠ת֖וֹךְ אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠yȧmĕrẇ-bi֗⁠y wĕ⁠lò֤ʼ ʼábẇ֙ li̇⁠şĕ̌mò֣ʻa ʼéla֔⁠y ʼi֣yş̌ ʼeţ-şǐq̇ẇẕé֤y ʻéֽynéy⁠hem֙ lò֣ʼ hişĕ̌li֔ykẇ wĕ⁠ʼeţ-gi̇l̇ẇlé֥y miẕĕra֖yim lò֣ʼ ʻázá֑bẇ wá⁠ʼòma֞r li⁠şĕ̌pò֧̇kĕ ẖàmáţi֣⁠y ʻàléy⁠he֗m lĕ⁠kal֤̇wòţ ʼapi̇⁠y֙ bá̇⁠he֔m bĕ̇⁠ţ֖wòkĕ ʼe֥reẕ miẕĕráֽyim׃"],[20,9,"וָ⁠אַ֨עַשׂ֙ לְמַ֣עַן שְׁמִ֔⁠י לְ⁠בִלְתִּ֥י הֵחֵ֛ל לְ⁠עֵינֵ֥י הַ⁠גּוֹיִ֖ם אֲשֶׁר־הֵ֣מָּה בְ⁠תוֹכָ֑⁠ם אֲשֶׁ֨ר נוֹדַ֤עְתִּי אֲלֵי⁠הֶם֙ לְ⁠עֵ֣ינֵי⁠הֶ֔ם לְ⁠הוֹצִיאָ֖⁠ם מֵ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wá⁠ʼa֨ʻaş̂֙ lĕma֣ʻan şĕ̌mi֔⁠y lĕ⁠bilĕţi֥̇y héẖé֛l lĕ⁠ʻéyné֥y ha⁠ġwòyi֖m ʼàşěr-hé֣má̇h bĕ⁠ţwòká֑⁠m ʼàşě֨r nwòda֤ʻĕţi̇y ʼàléy⁠hem֙ lĕ⁠ʻé֣ynéy⁠he֔m lĕ⁠hwòẕiyʼá֖⁠m mé⁠ʼe֥reẕ miẕĕráֽyim׃"],[20,10,"וָ⁠אֽוֹצִיאֵ֖⁠ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם וָ⁠אֲבִאֵ֖⁠ם אֶל־הַ⁠מִּדְבָּֽר׃","wá⁠ʼֽwòẕiyʼé֖⁠m mé⁠ʼe֣reẕ miẕĕrá֑yim wá⁠ʼàbiʼé֖⁠m ʼel-ha⁠mi̇dĕbáֽ̇r׃"],[20,11,"וָ⁠אֶתֵּ֤ן לָ⁠הֶם֙ אֶת־חֻקּוֹתַ֔⁠י וְ⁠אֶת־מִשְׁפָּטַ֖⁠י הוֹדַ֣עְתִּי אוֹתָ֑⁠ם אֲשֶׁ֨ר יַעֲשֶׂ֥ה אוֹתָ֛⁠ם הָ⁠אָדָ֖ם וָ⁠חַ֥י בָּ⁠הֶֽם׃","wá⁠ʼeţé֤̇n lá⁠hem֙ ʼeţ-ẖuq̇wòţa֔⁠y wĕ⁠ʼeţ-mişĕ̌pá̇ta֖⁠y hwòda֣ʻĕţi̇y ʼwòţá֑⁠m ʼàşě֨r yaʻàşê֥h ʼwòţá֛⁠m há⁠ʼádá֖m wá⁠ẖa֥y bá̇⁠heֽm׃"],[20,12,"וְ⁠גַ֤ם אֶת־שַׁבְּתוֹתַ⁠י֙ נָתַ֣תִּי לָ⁠הֶ֔ם לִ⁠הְי֣וֹת לְ⁠א֔וֹת בֵּינִ֖⁠י וּ⁠בֵֽינֵי⁠הֶ֑ם לָ⁠דַ֕עַת כִּ֛י אֲנִ֥י יְהוָ֖ה מְקַדְּשָֽׁ⁠ם׃","wĕ⁠ga֤m ʼeţ-şǎbĕ̇ţwòţa⁠y֙ náţa֣ţi̇y lá⁠he֔m li⁠hĕy֣wòţ lĕ⁠ʼ֔wòţ bé̇yni֖⁠y ẇ⁠béֽynéy⁠he֑m lá⁠da֕ʻaţ ki֛̇y ʼàni֥y yĕhwá֖h mĕqadĕ̇şáֽ̌⁠m׃"],[20,13,"וַ⁠יַּמְרוּ־בִ֨⁠י בֵֽית־יִשְׂרָאֵ֜ל בַּ⁠מִּדְבָּ֗ר בְּ⁠חֻקּוֹתַ֨⁠י לֹא־הָלָ֜כוּ וְ⁠אֶת־מִשְׁפָּטַ֣⁠י מָאָ֗סוּ אֲשֶׁר֩ יַעֲשֶׂ֨ה אֹתָ֤⁠ם הָֽ⁠אָדָם֙ וָ⁠חַ֣י בָּ⁠הֶ֔ם וְ⁠אֶת־שַׁבְּתֹתַ֖⁠י חִלְּל֣וּ מְאֹ֑ד וָ⁠אֹמַ֞ר לִ⁠שְׁפֹּ֨ךְ חֲמָתִ֧⁠י עֲלֵי⁠הֶ֛ם בַּ⁠מִּדְבָּ֖ר לְ⁠כַלּוֹתָֽ⁠ם׃","wa⁠yȧmĕrẇ-bi֨⁠y béֽyţ-yişĕ̂ráʼé֜l bȧ⁠mi̇dĕbá̇֗r bĕ̇⁠ẖuq̇wòţa֨⁠y lòʼ-hálá֜kẇ wĕ⁠ʼeţ-mişĕ̌pá̇ta֣⁠y máʼá֗sẇ ʼàşěr֩ yaʻàşê֨h ʼòţá֤⁠m háֽ⁠ʼádám֙ wá⁠ẖa֣y bá̇⁠he֔m wĕ⁠ʼeţ-şǎbĕ̇ţòţa֖⁠y ẖilĕ̇l֣ẇ mĕʼò֑d wá⁠ʼòma֞r li⁠şĕ̌pò̇֨kĕ ẖàmáţi֧⁠y ʻàléy⁠he֛m bȧ⁠mi̇dĕbá֖̇r lĕ⁠kal̇wòţáֽ⁠m׃"],[20,14,"וָ⁠אֶעֱשֶׂ֖ה לְמַ֣עַן שְׁמִ֑⁠י לְ⁠בִלְתִּ֤י הֵחֵל֙ לְ⁠עֵינֵ֣י הַ⁠גּוֹיִ֔ם אֲשֶׁ֥ר הוֹצֵאתִ֖י⁠ם לְ⁠עֵינֵי⁠הֶֽם׃","wá⁠ʼeʻèşê֖h lĕma֣ʻan şĕ̌mi֑⁠y lĕ⁠bilĕţi֤̇y héẖél֙ lĕ⁠ʻéyné֣y ha⁠ġwòyi֔m ʼàşě֥r hwòẕéʼţi֖y⁠m lĕ⁠ʻéynéy⁠heֽm׃"],[20,15,"וְ⁠גַם־אֲנִ֗י נָשָׂ֧אתִי יָדִ֛⁠י לָ⁠הֶ֖ם בַּ⁠מִּדְבָּ֑ר לְ⁠בִלְתִּי֩ הָבִ֨יא אוֹתָ֜⁠ם אֶל־הָ⁠אָ֣רֶץ אֲשֶׁר־נָתַ֗תִּי זָבַ֤ת חָלָב֙ וּ⁠דְבַ֔שׁ צְבִ֥י הִ֖יא לְ⁠כָל־הָ⁠אֲרָצֽוֹת׃","wĕ⁠gam-ʼàni֗y náşá֧̂ʼţiy yádi֛⁠y lá⁠he֖m bȧ⁠mi̇dĕbá֑̇r lĕ⁠bilĕţi̇y֩ hábi֨yʼ ʼwòţá֜⁠m ʼel-há⁠ʼá֣reẕ ʼàşěr-náţa֗ţi̇y zába֤ţ ẖáláb֙ ẇ⁠dĕba֔ş̌ ẕĕbi֥y hi֖yʼ lĕ⁠kál-há⁠ʼàráẕֽwòţ׃"],[20,16,"יַ֜עַן בְּ⁠מִשְׁפָּטַ֣⁠י מָאָ֗סוּ וְ⁠אֶת־חֻקּוֹתַ⁠י֙ לֹא־הָלְכ֣וּ בָ⁠הֶ֔ם וְ⁠אֶת־שַׁבְּתוֹתַ֖⁠י חִלֵּ֑לוּ כִּ֛י אַחֲרֵ֥י גִלּוּלֵי⁠הֶ֖ם לִבָּ֥⁠ם הֹלֵֽךְ׃","ya֜ʻan bĕ̇⁠mişĕ̌pá̇ta֣⁠y máʼá֗sẇ wĕ⁠ʼeţ-ẖuq̇wòţa⁠y֙ lòʼ-hálĕk֣ẇ bá⁠he֔m wĕ⁠ʼeţ-şǎbĕ̇ţwòţa֖⁠y ẖilé֑̇lẇ ki֛̇y ʼaẖàré֥y gil̇ẇléy⁠he֖m libá֥̇⁠m hòléֽkĕ׃"],[20,17,"וַ⁠תָּ֧חָס עֵינִ֛⁠י עֲלֵי⁠הֶ֖ם מִֽ⁠שַּׁחֲתָ֑⁠ם וְ⁠לֹֽא־עָשִׂ֧יתִי אוֹתָ֛⁠ם כָּלָ֖ה בַּ⁠מִּדְבָּֽר׃","wa⁠ţá֧̇ẖás ʻéyni֛⁠y ʻàléy⁠he֖m miֽ⁠şȧ̌ẖàţá֑⁠m wĕ⁠lòֽʼ-ʻáşî֧yţiy ʼwòţá֛⁠m ká̇lá֖h bȧ⁠mi̇dĕbáֽ̇r׃"],[20,18,"וָ⁠אֹמַ֤ר אֶל־בְּנֵי⁠הֶם֙ בַּ⁠מִּדְבָּ֔ר בְּ⁠חוּקֵּ֤י אֲבֽוֹתֵי⁠כֶם֙ אַל־תֵּלֵ֔כוּ וְ⁠אֶת־מִשְׁפְּטֵי⁠הֶ֖ם אַל־תִּשְׁמֹ֑רוּ וּ⁠בְ⁠גִלּוּלֵי⁠הֶ֖ם אַל־תִּטַּמָּֽאוּ׃","wá⁠ʼòma֤r ʼel-bĕ̇néy⁠hem֙ bȧ⁠mi̇dĕbá̇֔r bĕ̇⁠ẖẇqé֤̇y ʼàbֽwòţéy⁠kem֙ ʼal-ţé̇lé֔kẇ wĕ⁠ʼeţ-mişĕ̌pĕ̇téy⁠he֖m ʼal-ţi̇şĕ̌mò֑rẇ ẇ⁠bĕ⁠gil̇ẇléy⁠he֖m ʼal-ţi̇tȧmáֽ̇ʼẇ׃"],[20,19,"אֲנִי֙ יְהוָ֣ה אֱלֹהֵי⁠כֶ֔ם בְּ⁠חֻקּוֹתַ֖⁠י לֵ֑כוּ וְ⁠אֶת־מִשְׁפָּטַ֥⁠י שִׁמְר֖וּ וַ⁠עֲשׂ֥וּ אוֹתָֽ⁠ם׃","ʼàniy֙ yĕhwá֣h ʼèlòhéy⁠ke֔m bĕ̇⁠ẖuq̇wòţa֖⁠y lé֑kẇ wĕ⁠ʼeţ-mişĕ̌pá̇ta֥⁠y şǐmĕr֖ẇ wa⁠ʻàş֥̂ẇ ʼwòţáֽ⁠m׃"],[20,20,"וְ⁠אֶת־שַׁבְּתוֹתַ֖⁠י קַדֵּ֑שׁוּ וְ⁠הָי֤וּ לְ⁠אוֹת֙ בֵּינִ֣⁠י וּ⁠בֵֽינֵי⁠כֶ֔ם לָ⁠דַ֕עַת כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹהֵי⁠כֶֽם׃","wĕ⁠ʼeţ-şǎbĕ̇ţwòţa֖⁠y qadé֑̇ş̌ẇ wĕ⁠háy֤ẇ lĕ⁠ʼwòţ֙ bé̇yni֣⁠y ẇ⁠béֽynéy⁠ke֔m lá⁠da֕ʻaţ ki֛̇y ʼàni֥y yĕhwá֖h ʼèlòhéy⁠keֽm׃"],[20,21,"וַ⁠יַּמְרוּ־בִ֣⁠י הַ⁠בָּנִ֗ים בְּ⁠חֻקּוֹתַ֣⁠י לֹֽא־הָ֠לָכוּ וְ⁠אֶת־מִשְׁפָּטַ֨⁠י לֹא־שָׁמְר֜וּ לַ⁠עֲשׂ֣וֹת אוֹתָ֗⁠ם אֲשֶׁר֩ יַעֲשֶׂ֨ה אוֹתָ֤⁠ם הָֽ⁠אָדָם֙ וָ⁠חַ֣י בָּ⁠הֶ֔ם אֶת־שַׁבְּתוֹתַ֖⁠י חִלֵּ֑לוּ וָ⁠אֹמַ֞ר לִ⁠שְׁפֹּ֧ךְ חֲמָתִ֣⁠י עֲלֵי⁠הֶ֗ם לְ⁠כַלּ֥וֹת אַפִּ֛⁠י בָּ֖⁠ם בַּ⁠מִּדְבָּֽר׃","wa⁠yȧmĕrẇ-bi֣⁠y ha⁠bá̇ni֗ym bĕ̇⁠ẖuq̇wòţa֣⁠y lòֽʼ-há֠lákẇ wĕ⁠ʼeţ-mişĕ̌pá̇ta֨⁠y lòʼ-şá̌mĕr֜ẇ la⁠ʻàş֣̂wòţ ʼwòţá֗⁠m ʼàşěr֩ yaʻàşê֨h ʼwòţá֤⁠m háֽ⁠ʼádám֙ wá⁠ẖa֣y bá̇⁠he֔m ʼeţ-şǎbĕ̇ţwòţa֖⁠y ẖilé֑̇lẇ wá⁠ʼòma֞r li⁠şĕ̌pò֧̇kĕ ẖàmáţi֣⁠y ʻàléy⁠he֗m lĕ⁠kal֥̇wòţ ʼapi֛̇⁠y bá֖̇⁠m bȧ⁠mi̇dĕbáֽ̇r׃"],[20,22,"וַ⁠הֲשִׁבֹ֨תִי֙ אֶת־יָדִ֔⁠י וָ⁠אַ֖עַשׂ לְמַ֣עַן שְׁמִ֑⁠י לְ⁠בִלְתִּ֤י הֵחֵל֙ לְ⁠עֵינֵ֣י הַ⁠גּוֹיִ֔ם אֲשֶׁר־הוֹצֵ֥אתִי אוֹתָ֖⁠ם לְ⁠עֵינֵי⁠הֶֽם׃","wa⁠hàşǐbò֨ţiy֙ ʼeţ-yádi֔⁠y wá⁠ʼa֖ʻaş̂ lĕma֣ʻan şĕ̌mi֑⁠y lĕ⁠bilĕţi֤̇y héẖél֙ lĕ⁠ʻéyné֣y ha⁠ġwòyi֔m ʼàşěr-hwòẕé֥ʼţiy ʼwòţá֖⁠m lĕ⁠ʻéynéy⁠heֽm׃"],[20,23,"גַּם־אֲנִ֗י נָשָׂ֧אתִי אֶת־יָדִ֛⁠י לָ⁠הֶ֖ם בַּ⁠מִּדְבָּ֑ר לְ⁠הָפִ֤יץ אֹתָ⁠ם֙ בַּ⁠גּוֹיִ֔ם וּ⁠לְ⁠זָר֥וֹת אוֹתָ֖⁠ם בָּ⁠אֲרָצֽוֹת׃","gȧm-ʼàni֗y náşá֧̂ʼţiy ʼeţ-yádi֛⁠y lá⁠he֖m bȧ⁠mi̇dĕbá֑̇r lĕ⁠hápi֤yẕ ʼòţá⁠m֙ bȧ⁠ġwòyi֔m ẇ⁠lĕ⁠zár֥wòţ ʼwòţá֖⁠m bá̇⁠ʼàráẕֽwòţ׃"],[20,24,"יַ֜עַן מִשְׁפָּטַ֤⁠י לֹֽא־עָשׂוּ֙ וְ⁠חֻקּוֹתַ֣⁠י מָאָ֔סוּ וְ⁠אֶת־שַׁבְּתוֹתַ֖⁠י חִלֵּ֑לוּ וְ⁠אַחֲרֵי֙ גִּלּוּלֵ֣י אֲבוֹתָ֔⁠ם הָי֖וּ עֵינֵי⁠הֶֽם׃","ya֜ʻan mişĕ̌pá̇ta֤⁠y lòֽʼ-ʻáş̂ẇ֙ wĕ⁠ẖuq̇wòţa֣⁠y máʼá֔sẇ wĕ⁠ʼeţ-şǎbĕ̇ţwòţa֖⁠y ẖilé֑̇lẇ wĕ⁠ʼaẖàréy֙ gi̇l̇ẇlé֣y ʼàbwòţá֔⁠m háy֖ẇ ʻéynéy⁠heֽm׃"],[20,25,"וְ⁠גַם־אֲנִי֙ נָתַ֣תִּי לָ⁠הֶ֔ם חֻקִּ֖ים לֹ֣א טוֹבִ֑ים וּ⁠מִ֨שְׁפָּטִ֔ים לֹ֥א יִֽחְי֖וּ בָּ⁠הֶֽם׃","wĕ⁠gam-ʼàniy֙ náţa֣ţi̇y lá⁠he֔m ẖuqi֖̇ym lò֣ʼ twòbi֑ym ẇ⁠mi֨şĕ̌pá̇ti֔ym lò֥ʼ yiֽẖĕy֖ẇ bá̇⁠heֽm׃"],[20,26,"וָ⁠אֲטַמֵּ֤א אוֹתָ⁠ם֙ בְּ⁠מַתְּנוֹתָ֔⁠ם בְּ⁠הַעֲבִ֖יר כָּל־פֶּ֣טֶר רָ֑חַם לְמַ֣עַן אֲשִׁמֵּ֔⁠ם לְמַ֨עַן֙ אֲשֶׁ֣ר יֵֽדְע֔וּ אֲשֶׁ֖ר אֲנִ֥י יְהוָֽה׃ס","wá⁠ʼàtamé֤̇ʼ ʼwòţá⁠m֙ bĕ̇⁠maţĕ̇nwòţá֔⁠m bĕ̇⁠haʻàbi֖yr ká̇l-pė֣ter rá֑ẖam lĕma֣ʻan ʼàşǐmé̇֔⁠m lĕma֨ʻan֙ ʼàşě֣r yéֽdĕʻ֔ẇ ʼàşě֖r ʼàni֥y yĕhwáֽh׃s"],[20,27,"לָ⁠כֵ֞ן דַּבֵּ֨ר אֶל־בֵּ֤ית יִשְׂרָאֵל֙ בֶּן־אָדָ֔ם וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה ע֗וֹד זֹ֚את גִּדְּפ֤וּ אוֹתִ⁠י֙ אֲב֣וֹתֵי⁠כֶ֔ם בְּ⁠מַעֲלָ֥⁠ם בִּ֖⁠י מָֽעַל׃","lá⁠ké֞n dȧbé̇֨r ʼel-bé֤̇yţ yişĕ̂ráʼél֙ bėn-ʼádá֔m wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h ʻ֗wòd zò֚ʼţ gi̇dĕ̇p֤ẇ ʼwòţi⁠y֙ ʼàb֣wòţéy⁠ke֔m bĕ̇⁠maʻàlá֥⁠m bi֖̇⁠y máֽʻal׃"],[20,28,"וָ⁠אֲבִיאֵ⁠ם֙ אֶל־הָ⁠אָ֔רֶץ אֲשֶׁ֤ר נָשָׂ֨אתִי֙ אֶת־יָדִ֔⁠י לָ⁠תֵ֥ת אוֹתָ֖⁠הּ לָ⁠הֶ֑ם וַ⁠יִּרְאוּ֩ כָל־גִּבְעָ֨ה רָמָ֜ה וְ⁠כָל־עֵ֣ץ עָבֹ֗ת וַ⁠יִּזְבְּחוּ־שָׁ֤ם אֶת־זִבְחֵי⁠הֶם֙ וַ⁠יִּתְּנוּ־שָׁם֙ כַּ֣עַס קָרְבָּנָ֔⁠ם וַ⁠יָּשִׂ֣ימוּ שָׁ֗ם רֵ֚יחַ נִיח֣וֹחֵי⁠הֶ֔ם וַ⁠יַּסִּ֥יכוּ שָׁ֖ם אֶת־נִסְכֵּי⁠הֶֽם׃","wá⁠ʼàbiyʼé⁠m֙ ʼel-há⁠ʼá֔reẕ ʼàşě֤r náşá̂֨ʼţiy֙ ʼeţ-yádi֔⁠y lá⁠ţé֥ţ ʼwòţá֖⁠ḣ lá⁠he֑m wa⁠yi̇rĕʼẇ֩ kál-gi̇bĕʻá֨h rámá֜h wĕ⁠kál-ʻé֣ẕ ʻábò֗ţ wa⁠yi̇zĕbĕ̇ẖẇ-şá֤̌m ʼeţ-zibĕẖéy⁠hem֙ wa⁠yi̇ţĕ̇nẇ-şá̌m֙ kȧ֣ʻas qárĕbá̇ná֔⁠m wa⁠yá̇şî֣ymẇ şá̌֗m ré֚yẖa niyẖ֣wòẖéy⁠he֔m wa⁠yȧsi֥̇ykẇ şá֖̌m ʼeţ-nisĕké̇y⁠heֽm׃"],[20,29,"וָ⁠אֹמַ֣ר אֲלֵ⁠הֶ֔ם מָ֣ה הַ⁠בָּמָ֔ה אֲשֶׁר־אַתֶּ֥ם הַ⁠בָּאִ֖ים שָׁ֑ם וַ⁠יִּקָּרֵ֤א שְׁמָ⁠הּ֙ בָּמָ֔ה עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wá⁠ʼòma֣r ʼàlé⁠he֔m má֣h ha⁠bá̇má֔h ʼàşěr-ʼaţė֥m ha⁠bá̇ʼi֖ym şá֑̌m wa⁠yi̇qá̇ré֤ʼ şĕ̌má⁠ḣ֙ bá̇má֔h ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[20,30,"לָ⁠כֵ֞ן אֱמֹ֣ר ׀ אֶל־בֵּ֣ית יִשְׂרָאֵ֗ל כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הַ⁠בְּ⁠דֶ֥רֶךְ אֲבֽוֹתֵי⁠כֶ֖ם אַתֶּ֣ם נִטְמְאִ֑ים וְ⁠אַחֲרֵ֥י שִׁקּוּצֵי⁠הֶ֖ם אַתֶּ֥ם זֹנִֽים׃","lá⁠ké֞n ʼèmò֣r ׀ ʼel-bé֣̇yţ yişĕ̂ráʼé֗l kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ha⁠bĕ̇⁠de֥rekĕ ʼàbֽwòţéy⁠ke֖m ʼaţė֣m nitĕmĕʼi֑ym wĕ⁠ʼaẖàré֥y şǐq̇ẇẕéy⁠he֖m ʼaţė֥m zòniֽym׃"],[20,31,"וּ⁠בִ⁠שְׂאֵ֣ת מַתְּנֹֽתֵי⁠כֶ֡ם בְּֽ⁠הַעֲבִיר֩ בְּנֵי⁠כֶ֨ם בָּ⁠אֵ֜שׁ אַתֶּם֩ נִטְמְאִ֤֨ים לְ⁠כָל־גִּלּֽוּלֵי⁠כֶם֙ עַד־הַ⁠יּ֔וֹם וַ⁠אֲנִ֛י אִדָּרֵ֥שׁ לָ⁠כֶ֖ם בֵּ֣ית יִשְׂרָאֵ֑ל חַי־אָ֗נִי נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה אִם־אִדָּרֵ֖שׁ לָ⁠כֶֽם׃","ẇ⁠bi⁠şĕ̂ʼé֣ţ maţĕ̇nòֽţéy⁠ke֡m bĕֽ̇⁠haʻàbiyr֩ bĕ̇néy⁠ke֨m bá̇⁠ʼé֜ş̌ ʼaţėm֩ nitĕmĕʼi֤֨ym lĕ⁠kál-gi̇lֽ̇ẇléy⁠kem֙ ʻad-ha⁠ẏ֔wòm wa⁠ʼàni֛y ʼidá̇ré֥ş̌ lá⁠ke֖m bé֣̇yţ yişĕ̂ráʼé֑l ẖay-ʼá֗niy nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h ʼim-ʼidá̇ré֖ş̌ lá⁠keֽm׃"],[20,32,"וְ⁠הָֽ⁠עֹלָה֙ עַל־ר֣וּחֲ⁠כֶ֔ם הָי֖וֹ לֹ֣א תִֽהְיֶ֑ה אֲשֶׁ֣ר ׀ אַתֶּ֣ם אֹמְרִ֗ים נִֽהְיֶ֤ה כַ⁠גּוֹיִם֙ כְּ⁠מִשְׁפְּח֣וֹת הָ⁠אֲרָצ֔וֹת לְ⁠שָׁרֵ֖ת עֵ֥ץ וָ⁠אָֽבֶן׃","wĕ⁠háֽ⁠ʻòláh֙ ʻal-r֣ẇẖà⁠ke֔m háy֖wò lò֣ʼ ţiֽhĕye֑h ʼàşě֣r ׀ ʼaţė֣m ʼòmĕri֗ym niֽhĕye֤h ka⁠ġwòyim֙ kĕ̇⁠mişĕ̌pĕ̇ẖ֣wòţ há⁠ʼàráẕ֔wòţ lĕ⁠şá̌ré֖ţ ʻé֥ẕ wá⁠ʼáֽben׃"],[20,33,"חַי־אָ֕נִי נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה אִם־לֹ֠א בְּ⁠יָ֨ד חֲזָקָ֜ה וּ⁠בִ⁠זְר֧וֹעַ נְטוּיָ֛ה וּ⁠בְ⁠חֵמָ֥ה שְׁפוּכָ֖ה אֶמְל֥וֹךְ עֲלֵי⁠כֶֽם׃","ẖay-ʼá֕niy nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h ʼim-lò֠ʼ bĕ̇⁠yá֨d ẖàzáqá֜h ẇ⁠bi⁠zĕr֧wòʻa nĕtẇyá֛h ẇ⁠bĕ⁠ẖémá֥h şĕ̌pẇká֖h ʼemĕl֥wòkĕ ʻàléy⁠keֽm׃"],[20,34,"וְ⁠הוֹצֵאתִ֤י אֶתְ⁠כֶם֙ מִן־הָ֣⁠עַמִּ֔ים וְ⁠קִבַּצְתִּ֣י אֶתְ⁠כֶ֔ם מִן־הָ֣⁠אֲרָצ֔וֹת אֲשֶׁ֥ר נְפוֹצֹתֶ֖ם בָּ֑⁠ם בְּ⁠יָ֤ד חֲזָקָה֙ וּ⁠בִ⁠זְר֣וֹעַ נְטוּיָ֔ה וּ⁠בְ⁠חֵמָ֖ה שְׁפוּכָֽה׃","wĕ⁠hwòẕéʼţi֤y ʼeţĕ⁠kem֙ min-há֣⁠ʻami̇֔ym wĕ⁠qibȧẕĕţi֣̇y ʼeţĕ⁠ke֔m min-há֣⁠ʼàráẕ֔wòţ ʼàşě֥r nĕpwòẕòţe֖m bá֑̇⁠m bĕ̇⁠yá֤d ẖàzáqáh֙ ẇ⁠bi⁠zĕr֣wòʻa nĕtẇyá֔h ẇ⁠bĕ⁠ẖémá֖h şĕ̌pẇkáֽh׃"],[20,35,"וְ⁠הֵבֵאתִ֣י אֶתְ⁠כֶ֔ם אֶל־מִדְבַּ֖ר הָֽ⁠עַמִּ֑ים וְ⁠נִשְׁפַּטְתִּ֤י אִתְּ⁠כֶם֙ שָׁ֔ם פָּנִ֖ים אֶל־פָּנִֽים׃","wĕ⁠hébéʼţi֣y ʼeţĕ⁠ke֔m ʼel-midĕbȧ֖r háֽ⁠ʻami֑̇ym wĕ⁠nişĕ̌pȧtĕţi֤̇y ʼiţĕ̇⁠kem֙ şá̌֔m pá̇ni֖ym ʼel-pá̇niֽym׃"],[20,36,"כַּ⁠אֲשֶׁ֤ר נִשְׁפַּ֨טְתִּי֙ אֶת־אֲב֣וֹתֵי⁠כֶ֔ם בְּ⁠מִדְבַּ֖ר אֶ֣רֶץ מִצְרָ֑יִם כֵּ֚ן אִשָּׁפֵ֣ט אִתְּ⁠כֶ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","kȧ⁠ʼàşě֤r nişĕ̌pȧ֨tĕţi̇y֙ ʼeţ-ʼàb֣wòţéy⁠ke֔m bĕ̇⁠midĕbȧ֖r ʼe֣reẕ miẕĕrá֑yim ké֚̇n ʼişá̇̌pé֣t ʼiţĕ̇⁠ke֔m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[20,37,"וְ⁠הַעֲבַרְתִּ֥י אֶתְ⁠כֶ֖ם תַּ֣חַת הַ⁠שָּׁ֑בֶט וְ⁠הֵבֵאתִ֥י אֶתְ⁠כֶ֖ם בְּ⁠מָסֹ֥רֶת הַ⁠בְּרִֽית׃","wĕ⁠haʻàbarĕţi֥̇y ʼeţĕ⁠ke֖m ţȧ֣ẖaţ ha⁠şá֑̇̌bet wĕ⁠hébéʼţi֥y ʼeţĕ⁠ke֖m bĕ̇⁠másò֥reţ ha⁠bĕ̇riֽyţ׃"],[20,38,"וּ⁠בָרוֹתִ֣י מִ⁠כֶּ֗ם הַ⁠מֹּרְדִ֤ים וְ⁠הַ⁠פּֽוֹשְׁעִים֙ בִּ֔⁠י מֵ⁠אֶ֤רֶץ מְגֽוּרֵי⁠הֶם֙ אוֹצִ֣יא אוֹתָ֔⁠ם וְ⁠אֶל־אַדְמַ֥ת יִשְׂרָאֵ֖ל לֹ֣א יָב֑וֹא וִֽ⁠ידַעְתֶּ֖ם כִּי־אֲנִ֥י יְהוָֽה׃","ẇ⁠bárwòţi֣y mi⁠kė֗m ha⁠mò̇rĕdi֤ym wĕ⁠ha⁠ṗֽwòşĕ̌ʻiym֙ bi̇֔⁠y mé⁠ʼe֤reẕ mĕgֽẇréy⁠hem֙ ʼwòẕi֣yʼ ʼwòţá֔⁠m wĕ⁠ʼel-ʼadĕma֥ţ yişĕ̂ráʼé֖l lò֣ʼ yáb֑wòʼ wiֽ⁠ydaʻĕţė֖m ki̇y-ʼàni֥y yĕhwáֽh׃"],[20,39,"וְ⁠אַתֶּ֨ם בֵּֽית־יִשְׂרָאֵ֜ל כֹּֽה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהֹוִ֗ה אִ֤ישׁ גִּלּוּלָי⁠ו֙ לְכ֣וּ עֲבֹ֔דוּ וְ⁠אַחַ֕ר אִם־אֵינְ⁠כֶ֖ם שֹׁמְעִ֣ים אֵלָ֑⁠י וְ⁠אֶת־שֵׁ֤ם קָדְשִׁ⁠י֙ לֹ֣א תְחַלְּלוּ־ע֔וֹד בְּ⁠מַתְּנֽוֹתֵי⁠כֶ֖ם וּ⁠בְ⁠גִלּוּלֵי⁠כֶֽם׃","wĕ⁠ʼaţė֨m béֽ̇yţ-yişĕ̂ráʼé֜l kòֽ̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhòwi֗h ʼi֤yş̌ gi̇l̇ẇláy⁠w֙ lĕk֣ẇ ʻàbò֔dẇ wĕ⁠ʼaẖa֕r ʼim-ʼéynĕ⁠ke֖m şò̌mĕʻi֣ym ʼélá֑⁠y wĕ⁠ʼeţ-şé֤̌m qádĕşǐ⁠y֙ lò֣ʼ ţĕẖalĕ̇lẇ-ʻ֔wòd bĕ̇⁠maţĕ̇nֽwòţéy⁠ke֖m ẇ⁠bĕ⁠gil̇ẇléy⁠keֽm׃"],[20,40,"כִּ֣י בְ⁠הַר־קָדְשִׁ֞⁠י בְּ⁠הַ֣ר ׀ מְר֣וֹם יִשְׂרָאֵ֗ל נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה שָׁ֣ם יַעַבְדֻ֜⁠נִי כָּל־בֵּ֧ית יִשְׂרָאֵ֛ל כֻּלֹּ֖⁠ה בָּ⁠אָ֑רֶץ שָׁ֣ם אֶרְצֵ֔⁠ם וְ⁠שָׁ֞ם אֶדְר֣וֹשׁ אֶת־תְּרוּמֹֽתֵי⁠כֶ֗ם וְ⁠אֶת־רֵאשִׁ֛ית מַשְׂאוֹתֵי⁠כֶ֖ם בְּ⁠כָל־קָדְשֵׁי⁠כֶֽם׃","ki֣̇y bĕ⁠har-qádĕşǐ֞⁠y bĕ̇⁠ha֣r ׀ mĕr֣wòm yişĕ̂ráʼé֗l nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h şá֣̌m yaʻabĕdu֜⁠niy ká̇l-bé֧̇yţ yişĕ̂ráʼé֛l ku̇lò֖̇⁠h bá̇⁠ʼá֑reẕ şá֣̌m ʼerĕẕé֔⁠m wĕ⁠şá̌֞m ʼedĕr֣wòş̌ ʼeţ-ţĕ̇rẇmòֽţéy⁠ke֗m wĕ⁠ʼeţ-réʼşǐ֛yţ maşĕ̂ʼwòţéy⁠ke֖m bĕ̇⁠kál-qádĕşé̌y⁠keֽm׃"],[20,41,"בְּ⁠רֵ֣יחַ נִיחֹחַ֮ אֶרְצֶ֣ה אֶתְ⁠כֶם֒ בְּ⁠הוֹצִיאִ֤⁠י אֶתְ⁠כֶם֙ מִן־הָ֣⁠עַמִּ֔ים וְ⁠קִבַּצְתִּ֣י אֶתְ⁠כֶ֔ם מִן־הָ֣⁠אֲרָצ֔וֹת אֲשֶׁ֥ר נְפֹצֹתֶ֖ם בָּ֑⁠ם וְ⁠נִקְדַּשְׁתִּ֥י בָ⁠כֶ֖ם לְ⁠עֵינֵ֥י הַ⁠גּוֹיִֽם׃","bĕ̇⁠ré֣yẖa niyẖòẖa֮ ʼerĕẕe֣h ʼeţĕ⁠kem֒ bĕ̇⁠hwòẕiyʼi֤⁠y ʼeţĕ⁠kem֙ min-há֣⁠ʻami̇֔ym wĕ⁠qibȧẕĕţi֣̇y ʼeţĕ⁠ke֔m min-há֣⁠ʼàráẕ֔wòţ ʼàşě֥r nĕpòẕòţe֖m bá֑̇⁠m wĕ⁠niqĕdȧşĕ̌ţi֥̇y bá⁠ke֖m lĕ⁠ʻéyné֥y ha⁠ġwòyiֽm׃"],[20,42,"וִֽ⁠ידַעְתֶּם֙ כִּֽי־אֲנִ֣י יְהוָ֔ה בַּ⁠הֲבִיאִ֥⁠י אֶתְ⁠כֶ֖ם אֶל־אַדְמַ֣ת יִשְׂרָאֵ֑ל אֶל־הָ⁠אָ֗רֶץ אֲשֶׁ֤ר נָשָׂ֨אתִי֙ אֶת־יָדִ֔⁠י לָ⁠תֵ֥ת אוֹתָ֖⁠הּ לַ⁠אֲבֽוֹתֵי⁠כֶֽם׃","wiֽ⁠ydaʻĕţėm֙ kiֽ̇y-ʼàni֣y yĕhwá֔h bȧ⁠hàbiyʼi֥⁠y ʼeţĕ⁠ke֖m ʼel-ʼadĕma֣ţ yişĕ̂ráʼé֑l ʼel-há⁠ʼá֗reẕ ʼàşě֤r náşá̂֨ʼţiy֙ ʼeţ-yádi֔⁠y lá⁠ţé֥ţ ʼwòţá֖⁠ḣ la⁠ʼàbֽwòţéy⁠keֽm׃"],[20,43,"וּ⁠זְכַרְתֶּם־שָׁ֗ם אֶת־דַּרְכֵי⁠כֶם֙ וְ⁠אֵת֙ כָּל־עֲלִיל֣וֹתֵי⁠כֶ֔ם אֲשֶׁ֥ר נִטְמֵאתֶ֖ם בָּ֑⁠ם וּ⁠נְקֹֽטֹתֶם֙ בִּ⁠פְנֵי⁠כֶ֔ם בְּ⁠כָל־רָעוֹתֵי⁠כֶ֖ם אֲשֶׁ֥ר עֲשִׂיתֶֽם׃","ẇ⁠zĕkarĕţėm-şá̌֗m ʼeţ-dȧrĕkéy⁠kem֙ wĕ⁠ʼéţ֙ ká̇l-ʻàliyl֣wòţéy⁠ke֔m ʼàşě֥r nitĕméʼţe֖m bá֑̇⁠m ẇ⁠nĕqòֽtòţem֙ bi̇⁠pĕnéy⁠ke֔m bĕ̇⁠kál-ráʻwòţéy⁠ke֖m ʼàşě֥r ʻàşîyţeֽm׃"],[20,44,"וִֽ⁠ידַעְתֶּם֙ כִּֽי־אֲנִ֣י יְהוָ֔ה בַּ⁠עֲשׂוֹתִ֥⁠י אִתְּ⁠כֶ֖ם לְמַ֣עַן שְׁמִ֑⁠י לֹא֩ כְ⁠דַרְכֵי⁠כֶ֨ם הָ⁠רָעִ֜ים וְ⁠כַ⁠עֲלִילֽוֹתֵי⁠כֶ֤ם הַ⁠נִּשְׁחָתוֹת֙ בֵּ֣ית יִשְׂרָאֵ֔ל נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","wiֽ⁠ydaʻĕţėm֙ kiֽ̇y-ʼàni֣y yĕhwá֔h bȧ⁠ʻàş̂wòţi֥⁠y ʼiţĕ̇⁠ke֖m lĕma֣ʻan şĕ̌mi֑⁠y lòʼ֩ kĕ⁠darĕkéy⁠ke֨m há⁠ráʻi֜ym wĕ⁠ka⁠ʻàliylֽwòţéy⁠ke֤m ha⁠ni̇şĕ̌ẖáţwòţ֙ bé֣̇yţ yişĕ̂ráʼé֔l nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[20,45,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[20,46,"בֶּן־אָדָ֗ם שִׂ֤ים פָּנֶ֨י⁠ךָ֙ דֶּ֣רֶךְ תֵּימָ֔נָ⁠ה וְ⁠הַטֵּ֖ף אֶל־דָּר֑וֹם וְ⁠הִנָּבֵ֛א אֶל־יַ֥עַר הַ⁠שָּׂדֶ֖ה נֶֽגֶב׃","bėn-ʼádá֗m şî֤ym pá̇ne֨y⁠ká֙ dė֣rekĕ ţé̇ymá֔ná⁠h wĕ⁠haté֖̇p ʼel-dá̇r֑wòm wĕ⁠hiná̇bé֛ʼ ʼel-ya֥ʻar ha⁠şá̇̂de֖h neֽgeb׃"],[20,47,"וְ⁠אָֽמַרְתָּ֙ לְ⁠יַ֣עַר הַ⁠נֶּ֔גֶב שְׁמַ֖ע דְּבַר־יְהוָ֑ה כֹּֽה־אָמַ֣ר אֲדֹנָ֣⁠י יְהוִ֡ה הִנְ⁠נִ֣י מַֽצִּית־בְּ⁠ךָ֣ ׀ אֵ֡שׁ וְ⁠אָכְלָ֣ה בְ⁠ךָ֣ כָל־עֵֽץ־לַח֩ וְ⁠כָל־עֵ֨ץ יָבֵ֤שׁ לֹֽא־תִכְבֶּה֙ לַהֶ֣בֶת שַׁלְהֶ֔בֶת וְ⁠נִצְרְבוּ־בָ֥⁠הּ כָּל־פָּנִ֖ים מִ⁠נֶּ֥גֶב צָפֽוֹנָ⁠ה׃","wĕ⁠ʼáֽmarĕţá̇֙ lĕ⁠ya֣ʻar ha⁠nė֔geb şĕ̌ma֖ʻ dĕ̇bar-yĕhwá֑h kòֽ̇h-ʼáma֣r ʼàdòná֣⁠y yĕhwi֡h hinĕ⁠ni֣y maֽẕi̇yţ-bĕ̇⁠ká֣ ׀ ʼé֡ş̌ wĕ⁠ʼákĕlá֣h bĕ⁠ká֣ kál-ʻéֽẕ-laẖ֩ wĕ⁠kál-ʻé֨ẕ yábé֤ş̌ lòֽʼ-ţikĕbėh֙ lahe֣beţ şǎlĕhe֔beţ wĕ⁠niẕĕrĕbẇ-bá֥⁠ḣ ká̇l-pá̇ni֖ym mi⁠nė֥geb ẕápֽwòná⁠h׃"],[20,48,"וְ⁠רָאוּ֙ כָּל־בָּשָׂ֔ר כִּ֛י אֲנִ֥י יְהוָ֖ה בִּֽעַרְתִּ֑י⁠הָ לֹ֖א תִּכְבֶּֽה׃","wĕ⁠ráʼẇ֙ ká̇l-bá̇şá̂֔r ki֛̇y ʼàni֥y yĕhwá֖h biֽ̇ʻarĕţi֑̇y⁠há lò֖ʼ ţi̇kĕbėֽh׃"],[20,49,"וָ⁠אֹמַ֕ר אֲהָ֖הּ אֲדֹנָ֣⁠י יְהוִ֑ה הֵ֚מָּה אֹמְרִ֣ים לִ֔⁠י הֲ⁠לֹ֛א מְמַשֵּׁ֥ל מְשָׁלִ֖ים הֽוּא׃פ","wá⁠ʼòma֕r ʼàhá֖ḣ ʼàdòná֣⁠y yĕhwi֑h hé֚má̇h ʼòmĕri֣ym li֔⁠y hà⁠lò֛ʼ mĕmaşé֥̇̌l mĕşá̌li֖ym hֽẇʼ׃p"],[21,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[21,2,"בֶּן־אָדָ֗ם שִׂ֤ים פָּנֶ֨י⁠ךָ֙ אֶל־יְר֣וּשָׁלִַ֔ם וְ⁠הַטֵּ֖ף אֶל־מִקְדָּשִׁ֑ים וְ⁠הִנָּבֵ֖א אֶל־אַדְמַ֥ת יִשְׂרָאֵֽל׃","bėn-ʼádá֗m şî֤ym pá̇ne֨y⁠ká֙ ʼel-yĕr֣ẇşá̌lia֔m wĕ⁠haté֖̇p ʼel-miqĕdá̇şǐ֑ym wĕ⁠hiná̇bé֖ʼ ʼel-ʼadĕma֥ţ yişĕ̂ráʼéֽl׃"],[21,3,"וְ⁠אָמַרְתָּ֞ לְ⁠אַדְמַ֣ת יִשְׂרָאֵ֗ל כֹּ֚ה אָמַ֣ר יְהוָ֔ה הִנְ⁠נִ֣י אֵלַ֔יִ⁠ךְ וְ⁠הוֹצֵאתִ֥י חַרְבִּ֖⁠י מִ⁠תַּעְרָ֑⁠הּ וְ⁠הִכְרַתִּ֥י מִמֵּ֖⁠ךְ צַדִּ֥יק וְ⁠רָשָֽׁע׃","wĕ⁠ʼámarĕţá̇֞ lĕ⁠ʼadĕma֣ţ yişĕ̂ráʼé֗l kò֚̇h ʼáma֣r yĕhwá֔h hinĕ⁠ni֣y ʼéla֔yi⁠kĕ wĕ⁠hwòẕéʼţi֥y ẖarĕbi֖̇⁠y mi⁠ţȧʻĕrá֑⁠ḣ wĕ⁠hikĕraţi֥̇y mimé֖̇⁠kĕ ẕadi֥̇yq wĕ⁠ráşáֽ̌ʻ׃"],[21,4,"יַ֛עַן אֲשֶׁר־הִכְרַ֥תִּי מִמֵּ֖⁠ךְ צַדִּ֣יק וְ⁠רָשָׁ֑ע לָ֠⁠כֵן תֵּצֵ֨א חַרְבִּ֧⁠י מִ⁠תַּעְרָ֛⁠הּ אֶל־כָּל־בָּשָׂ֖ר מִ⁠נֶּ֥גֶב צָפֽוֹן׃","ya֛ʻan ʼàşěr-hikĕra֥ţi̇y mimé֖̇⁠kĕ ẕadi֣̇yq wĕ⁠ráşá֑̌ʻ lá֠⁠kén ţé̇ẕé֨ʼ ẖarĕbi֧̇⁠y mi⁠ţȧʻĕrá֛⁠ḣ ʼel-ká̇l-bá̇şá֖̂r mi⁠nė֥geb ẕápֽwòn׃"],[21,5,"וְ⁠יָֽדְעוּ֙ כָּל־בָּשָׂ֔ר כִּ֚י אֲנִ֣י יְהוָ֔ה הוֹצֵ֥אתִי חַרְבִּ֖⁠י מִ⁠תַּעְרָ֑⁠הּ לֹ֥א תָשׁ֖וּב עֽוֹד׃ס","wĕ⁠yáֽdĕʻẇ֙ ká̇l-bá̇şá̂֔r ki֚̇y ʼàni֣y yĕhwá֔h hwòẕé֥ʼţiy ẖarĕbi֖̇⁠y mi⁠ţȧʻĕrá֑⁠ḣ lò֥ʼ ţáş֖̌ẇb ʻֽwòd׃s"],[21,6,"וְ⁠אַתָּ֥ה בֶן־אָדָ֖ם הֵֽאָנַ֑ח בְּ⁠שִׁבְר֤וֹן מָתְנַ֨יִם֙ וּ⁠בִ⁠מְרִיר֔וּת תֵּֽאָנַ֖ח לְ⁠עֵינֵי⁠הֶֽם׃","wĕ⁠ʼaţá֥̇h ben-ʼádá֖m héֽʼána֑ẖ bĕ̇⁠şǐbĕr֤wòn máţĕna֨yim֙ ẇ⁠bi⁠mĕriyr֔ẇţ ţéֽ̇ʼána֖ẖ lĕ⁠ʻéynéy⁠heֽm׃"],[21,7,"וְ⁠הָיָה֙ כִּֽי־יֹאמְר֣וּ אֵלֶ֔י⁠ךָ עַל־מָ֖ה אַתָּ֣ה נֶאֱנָ֑ח וְ⁠אָמַרְתָּ֡ אֶל־שְׁמוּעָ֣ה כִֽי־בָאָ֡ה וְ⁠נָמֵ֣ס כָּל־לֵב֩ וְ⁠רָפ֨וּ כָל־יָדַ֜יִם וְ⁠כִהֲתָ֣ה כָל־ר֗וּחַ וְ⁠כָל־בִּרְכַּ֨יִם֙ תֵּלַ֣כְנָה מַּ֔יִם הִנֵּ֤ה בָאָה֙ וְ⁠נִֽהְיָ֔תָה נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","wĕ⁠háyáh֙ kiֽ̇y-yòʼmĕr֣ẇ ʼéle֔y⁠ká ʻal-má֖h ʼaţá֣̇h neʼèná֑ẖ wĕ⁠ʼámarĕţá̇֡ ʼel-şĕ̌mẇʻá֣h kiֽy-báʼá֡h wĕ⁠námé֣s ká̇l-léb֩ wĕ⁠ráp֨ẇ kál-yáda֜yim wĕ⁠kihàţá֣h kál-r֗ẇẖa wĕ⁠kál-bi̇rĕkȧ֨yim֙ ţé̇la֣kĕnáh mȧ֔yim hiné֤̇h báʼáh֙ wĕ⁠niֽhĕyá֔ţáh nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[21,8,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[21,9,"בֶּן־אָדָ֕ם הִנָּבֵא֙ וְ⁠אָ֣מַרְתָּ֔ כֹּ֖ה אָמַ֣ר אֲדֹנָ֑⁠י אֱמֹ֕ר חֶ֥רֶב חֶ֛רֶב הוּחַ֖דָּה וְ⁠גַם־מְרוּטָֽה׃","bėn-ʼádá֕m hiná̇béʼ֙ wĕ⁠ʼá֣marĕţá̇֔ kò֖̇h ʼáma֣r ʼàdòná֑⁠y ʼèmò֕r ẖe֥reb ẖe֛reb hẇẖa֖dá̇h wĕ⁠gam-mĕrẇtáֽh׃"],[21,10,"לְמַ֨עַן טְבֹ֤חַ טֶ֨בַח֙ הוּחַ֔דָּה לְמַעַן־הֱיֵה־לָ֥⁠הּ בָּ֖רָק מֹרָ֑טָּה א֣וֹ נָשִׂ֔ישׂ שֵׁ֥בֶט בְּנִ֖⁠י מֹאֶ֥סֶת כָּל־עֵֽץ׃","lĕma֨ʻan tĕbò֤ẖa te֨baẖ֙ hẇẖa֔dá̇h lĕmaʻan-hèyéh-lá֥⁠ḣ bá֖̇ráq mòrá֑tá̇h ʼ֣wò náşî֔yş̂ şé֥̌bet bĕ̇ni֖⁠y mòʼe֥seţ ká̇l-ʻéֽẕ׃"],[21,11,"וַ⁠יִּתֵּ֥ן אֹתָ֛⁠הּ לְ⁠מָרְטָ֖ה לִ⁠תְפֹּ֣שׂ בַּ⁠כָּ֑ף הִֽיא־הוּחַ֤דָּה חֶ֨רֶב֙ וְ⁠הִ֣יא מֹרָ֔טָּה לָ⁠תֵ֥ת אוֹתָ֖⁠הּ בְּ⁠יַד־הוֹרֵֽג׃","wa⁠yi̇ţé֥̇n ʼòţá֛⁠ḣ lĕ⁠márĕtá֖h li⁠ţĕpò֣̇ş̂ bȧ⁠ká֑̇p hiֽyʼ-hẇẖa֤dá̇h ẖe֨reb֙ wĕ⁠hi֣yʼ mòrá֔tá̇h lá⁠ţé֥ţ ʼwòţá֖⁠ḣ bĕ̇⁠yad-hwòréֽg׃"],[21,12,"זְעַ֤ק וְ⁠הֵילֵל֙ בֶּן־אָדָ֔ם כִּי־הִיא֙ הָיתָ֣ה בְ⁠עַמִּ֔⁠י הִ֖יא בְּ⁠כָל־נְשִׂיאֵ֣י יִשְׂרָאֵ֑ל מְגוּרֵ֤י אֶל־חֶ֨רֶב֙ הָי֣וּ אֶת־עַמִּ֔⁠י לָ⁠כֵ֖ן סְפֹ֥ק אֶל־יָרֵֽךְ׃","zĕʻa֤q wĕ⁠héylél֙ bėn-ʼádá֔m ki̇y-hiyʼ֙ háyţá֣h bĕ⁠ʻami̇֔⁠y hi֖yʼ bĕ̇⁠kál-nĕşîyʼé֣y yişĕ̂ráʼé֑l mĕgẇré֤y ʼel-ẖe֨reb֙ háy֣ẇ ʼeţ-ʻami̇֔⁠y lá⁠ké֖n sĕpò֥q ʼel-yáréֽkĕ׃"],[21,13,"כִּ֣י בֹ֔חַן וּ⁠מָ֕ה אִם־גַּם־שֵׁ֥בֶט מֹאֶ֖סֶת לֹ֣א יִֽהְיֶ֑ה נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","ki֣̇y bò֔ẖan ẇ⁠má֕h ʼim-gȧm-şé֥̌bet mòʼe֖seţ lò֣ʼ yiֽhĕye֑h nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[21,14,"וְ⁠אַתָּ֣ה בֶן־אָדָ֔ם הִנָּבֵ֕א וְ⁠הַ֖ךְ כַּ֣ף אֶל־כָּ֑ף וְ⁠תִכָּפֵ֞ל חֶ֤רֶב שְׁלִישִׁ֨תָ⁠ה֙ חֶ֣רֶב חֲלָלִ֔ים הִ֗יא חֶ֚רֶב חָלָ֣ל הַ⁠גָּד֔וֹל הַ⁠חֹדֶ֖רֶת לָ⁠הֶֽם׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֔m hiná̇bé֕ʼ wĕ⁠ha֖kĕ kȧ֣p ʼel-ká֑̇p wĕ⁠ţiká̇pé֞l ẖe֤reb şĕ̌liyşǐ֨ţá⁠h֙ ẖe֣reb ẖàláli֔ym hi֗yʼ ẖe֚reb ẖálá֣l ha⁠gá̇d֔wòl ha⁠ẖòde֖reţ lá⁠heֽm׃"],[21,15,"לְמַ֣עַן ׀ לָ⁠מ֣וּג לֵ֗ב וְ⁠הַרְבֵּה֙ הַ⁠מִּכְשֹׁלִ֔ים עַ֚ל כָּל־שַׁ֣עֲרֵי⁠הֶ֔ם נָתַ֖תִּי אִבְחַת־חָ֑רֶב אָ֛ח עֲשׂוּיָ֥ה לְ⁠בָרָ֖ק מְעֻטָּ֥ה לְ⁠טָֽבַח׃","lĕma֣ʻan ׀ lá⁠m֣ẇg lé֗b wĕ⁠harĕbé̇h֙ ha⁠mi̇kĕşò̌li֔ym ʻa֚l ká̇l-şǎ֣ʻàréy⁠he֔m náţa֖ţi̇y ʼibĕẖaţ-ẖá֑reb ʼá֛ẖ ʻàş̂ẇyá֥h lĕ⁠bárá֖q mĕʻutá֥̇h lĕ⁠táֽbaẖ׃"],[21,16,"הִתְאַחֲדִ֥י הֵימִ֖נִי הָשִׂ֣ימִי הַשְׂמִ֑ילִי אָ֖נָה פָּנַ֥יִ⁠ךְ מֻעָדֽוֹת׃","hiţĕʼaẖàdi֥y héymi֖niy háşî֣ymiy haşĕ̂mi֑yliy ʼá֖náh pá̇na֥yi⁠kĕ muʻádֽwòţ׃"],[21,17,"וְ⁠גַם־אֲנִ֗י אַכֶּ֤ה כַפִּ⁠י֙ אֶל־כַּפִּ֔⁠י וַ⁠הֲנִחֹתִ֖י חֲמָתִ֑⁠י אֲנִ֥י יְהוָ֖ה דִּבַּֽרְתִּי׃פ","wĕ⁠gam-ʼàni֗y ʼakė֤h kapi̇⁠y֙ ʼel-kȧpi̇֔⁠y wa⁠hàniẖòţi֖y ẖàmáţi֑⁠y ʼàni֥y yĕhwá֖h di̇bȧֽrĕţi̇y׃p"],[21,18,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[21,19,"וְ⁠אַתָּ֨ה בֶן־אָדָ֜ם שִׂים־לְ⁠ךָ֣ ׀ שְׁנַ֣יִם דְּרָכִ֗ים לָ⁠בוֹא֙ חֶ֣רֶב מֶֽלֶךְ־בָּבֶ֔ל מֵ⁠אֶ֥רֶץ אֶחָ֖ד יֵצְא֣וּ שְׁנֵי⁠הֶ֑ם וְ⁠יָ֣ד בָּרֵ֔א בְּ⁠רֹ֥אשׁ דֶּֽרֶךְ־עִ֖יר בָּרֵֽא׃","wĕ⁠ʼaţá̇֨h ben-ʼádá֜m şîym-lĕ⁠ká֣ ׀ şĕ̌na֣yim dĕ̇ráki֗ym lá⁠bwòʼ֙ ẖe֣reb meֽlekĕ-bá̇be֔l mé⁠ʼe֥reẕ ʼeẖá֖d yéẕĕʼ֣ẇ şĕ̌néy⁠he֑m wĕ⁠yá֣d bá̇ré֔ʼ bĕ̇⁠rò֥ʼş̌ dėֽrekĕ-ʻi֖yr bá̇réֽʼ׃"],[21,20,"דֶּ֣רֶךְ תָּשִׂ֔ים לָ⁠ב֣וֹא חֶ֔רֶב אֵ֖ת רַבַּ֣ת בְּנֵֽי־עַמּ֑וֹן וְ⁠אֶת־יְהוּדָ֥ה בִ⁠ירוּשָׁלִַ֖ם בְּצוּרָֽה׃","dė֣rekĕ ţá̇şî֔ym lá⁠b֣wòʼ ẖe֔reb ʼé֖ţ rabȧ֣ţ bĕ̇néֽy-ʻaṁ֑wòn wĕ⁠ʼeţ-yĕhẇdá֥h bi⁠yrẇşá̌lia֖m bĕ̇ẕẇráֽh׃"],[21,21,"כִּֽי־עָמַ֨ד מֶלֶךְ־בָּבֶ֜ל אֶל־אֵ֣ם הַ⁠דֶּ֗רֶךְ בְּ⁠רֹ֛אשׁ שְׁנֵ֥י הַ⁠דְּרָכִ֖ים לִ⁠קְסָם־קָ֑סֶם קִלְקַ֤ל בַּֽ⁠חִצִּים֙ שָׁאַ֣ל בַּ⁠תְּרָפִ֔ים רָאָ֖ה בַּ⁠כָּבֵֽד׃","kiֽ̇y-ʻáma֨d melekĕ-bá̇be֜l ʼel-ʼé֣m ha⁠dė֗rekĕ bĕ̇⁠rò֛ʼş̌ şĕ̌né֥y ha⁠dĕ̇ráki֖ym li⁠qĕsám-qá֑sem qilĕqa֤l bȧֽ⁠ẖiẕi̇ym֙ şá̌ʼa֣l bȧ⁠ţĕ̇rápi֔ym ráʼá֖h bȧ⁠ká̇béֽd׃"],[21,22,"בִּֽ⁠ימִינ֞⁠וֹ הָיָ֣ה ׀ הַ⁠קֶּ֣סֶם יְרוּשָׁלִַ֗ם לָ⁠שׂ֤וּם כָּרִים֙ לִ⁠פְתֹּ֤חַ פֶּה֙ בְּ⁠רֶ֔צַח לְ⁠הָרִ֥ים ק֖וֹל בִּ⁠תְרוּעָ֑ה לָ⁠שׂ֤וּם כָּרִים֙ עַל־שְׁעָרִ֔ים לִ⁠שְׁפֹּ֥ךְ סֹלְלָ֖ה לִ⁠בְנ֥וֹת דָּיֵֽק׃","biֽ̇⁠ymiyn֞⁠wò háyá֣h ׀ ha⁠qė֣sem yĕrẇşá̌lia֗m lá⁠ş֤̂ẇm ká̇riym֙ li⁠pĕţò֤̇ẖa pėh֙ bĕ̇⁠re֔ẕaẖ lĕ⁠hári֥ym q֖wòl bi̇⁠ţĕrẇʻá֑h lá⁠ş֤̂ẇm ká̇riym֙ ʻal-şĕ̌ʻári֔ym li⁠şĕ̌pò֥̇kĕ sòlĕlá֖h li⁠bĕn֥wòţ dá̇yéֽq׃"],[21,23,"וְ⁠הָיָ֨ה לָ⁠הֶ֤ם כ⁠קסום־שָׁוְא֙ בְּ⁠עֵ֣ינֵי⁠הֶ֔ם שְׁבֻעֵ֥י שְׁבֻע֖וֹת לָ⁠הֶ֑ם וְ⁠הֽוּא־מַזְכִּ֥יר עָוֺ֖ן לְ⁠הִתָּפֵֽשׂ׃פ","wĕ⁠háyá֨h lá⁠he֤m k⁠qswm-şá̌wĕʼ֙ bĕ̇⁠ʻé֣ynéy⁠he֔m şĕ̌buʻé֥y şĕ̌buʻ֖wòţ lá⁠he֑m wĕ⁠hֽẇʼ-mazĕki֥̇yr ʻáwֺ֖n lĕ⁠hiţá̇péֽş̂׃p"],[21,24,"לָ⁠כֵ֗ן כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ יַ֗עַן הַזְכַּרְ⁠כֶם֙ עֲוֺ֣נְ⁠כֶ֔ם בְּ⁠הִגָּל֣וֹת פִּשְׁעֵי⁠כֶ֗ם לְ⁠הֵֽרָאוֹת֙ חַטֹּ֣אותֵי⁠כֶ֔ם בְּ⁠כֹ֖ל עֲלִילֽוֹתֵי⁠כֶ֑ם יַ֚עַן הִזָּ֣כֶרְ⁠כֶ֔ם בַּ⁠כַּ֖ף תִּתָּפֵֽשׂוּ׃פ","lá⁠ké֗n kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ ya֗ʻan hazĕkȧrĕ⁠kem֙ ʻàwֺ֣nĕ⁠ke֔m bĕ̇⁠higá̇l֣wòţ pi̇şĕ̌ʻéy⁠ke֗m lĕ⁠héֽráʼwòţ֙ ẖatò֣̇ʼwţéy⁠ke֔m bĕ̇⁠kò֖l ʻàliylֽwòţéy⁠ke֑m ya֚ʻan hizá֣̇kerĕ⁠ke֔m bȧ⁠kȧ֖p ţi̇ţá̇péֽş̂ẇ׃p"],[21,25,"וְ⁠אַתָּה֙ חָלָ֣ל רָשָׁ֔ע נְשִׂ֖יא יִשְׂרָאֵ֑ל אֲשֶׁר־בָּ֣א יוֹמ֔⁠וֹ בְּ⁠עֵ֖ת עֲוֺ֥ן קֵֽץ׃ס","wĕ⁠ʼaţá̇h֙ ẖálá֣l ráşá̌֔ʻ nĕşî֖yʼ yişĕ̂ráʼé֑l ʼàşěr-bá֣̇ʼ ywòm֔⁠wò bĕ̇⁠ʻé֖ţ ʻàwֺ֥n qéֽẕ׃s"],[21,26,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הָסִיר֙ הַ⁠מִּצְנֶ֔פֶת וְ⁠הָרִ֖ים הָֽ⁠עֲטָרָ֑ה זֹ֣את לֹא־זֹ֔את הַ⁠שָּׁפָ֣לָה הַגְבֵּ֔הַ וְ⁠הַ⁠גָּבֹ֖הַ הַשְׁפִּֽיל׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hásiyr֙ ha⁠mi̇ẕĕne֔peţ wĕ⁠hári֖ym háֽ⁠ʻàtárá֑h zò֣ʼţ lòʼ-zò֔ʼţ ha⁠şá̇̌pá֣láh hagĕbé̇֔ha wĕ⁠ha⁠gá̇bò֖ha haşĕ̌piֽ̇yl׃"],[21,27,"עַוָּ֥ה עַוָּ֖ה עַוָּ֣ה אֲשִׂימֶ֑⁠נָּה גַּם־זֹאת֙ לֹ֣א הָיָ֔ה עַד־בֹּ֛א אֲשֶׁר־ל֥⁠וֹ הַ⁠מִּשְׁפָּ֖ט וּ⁠נְתַתִּֽי⁠ו׃פ","ʻawá֥̇h ʻawá֖̇h ʻawá֣̇h ʼàşîyme֑⁠ná̇h gȧm-zòʼţ֙ lò֣ʼ háyá֔h ʻad-bò֛̇ʼ ʼàşěr-l֥⁠wò ha⁠mi̇şĕ̌pá֖̇t ẇ⁠nĕţaţiֽ̇y⁠w׃p"],[21,28,"וְ⁠אַתָּ֣ה בֶן־אָדָ֗ם הִנָּבֵ֤א וְ⁠אָֽמַרְתָּ֙ כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהֹוִ֔ה אֶל־בְּנֵ֥י עַמּ֖וֹן וְ⁠אֶל־חֶרְפָּתָ֑⁠ם וְ⁠אָמַרְתָּ֗ חֶ֣רֶב חֶ֤רֶב פְּתוּחָה֙ לְ⁠טֶ֣בַח מְרוּטָ֔ה לְ⁠הָכִ֖יל לְמַ֥עַן בָּרָֽק׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֗m hiná̇bé֤ʼ wĕ⁠ʼáֽmarĕţá̇֙ kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhòwi֔h ʼel-bĕ̇né֥y ʻaṁ֖wòn wĕ⁠ʼel-ẖerĕpá̇ţá֑⁠m wĕ⁠ʼámarĕţá̇֗ ẖe֣reb ẖe֤reb pĕ̇ţẇẖáh֙ lĕ⁠te֣baẖ mĕrẇtá֔h lĕ⁠háki֖yl lĕma֥ʻan bá̇ráֽq׃"],[21,29,"בַּ⁠חֲז֥וֹת לָ⁠ךְ֙ שָׁ֔וְא בִּ⁠קְסָם־לָ֖⁠ךְ כָּזָ֑ב לָ⁠תֵ֣ת אוֹתָ֗⁠ךְ אֶֽל־צַוְּארֵי֙ חַֽלְלֵ֣י רְשָׁעִ֔ים אֲשֶׁר־בָּ֣א יוֹמָ֔⁠ם בְּ⁠עֵ֖ת עֲוֺ֥ן קֵֽץ׃","bȧ⁠ẖàz֥wòţ lá⁠kĕ֙ şá̌֔wĕʼ bi̇⁠qĕsám-lá֖⁠kĕ ká̇zá֑b lá⁠ţé֣ţ ʼwòţá֗⁠kĕ ʼeֽl-ẕawĕ̇ʼréy֙ ẖaֽlĕlé֣y rĕşá̌ʻi֔ym ʼàşěr-bá֣̇ʼ ywòmá֔⁠m bĕ̇⁠ʻé֖ţ ʻàwֺ֥n qéֽẕ׃"],[21,30,"הָשַׁ֖ב אֶל־תַּעְרָ֑⁠הּ בִּ⁠מְק֧וֹם אֲשֶׁר־נִבְרֵ֛את בְּ⁠אֶ֥רֶץ מְכֻרוֹתַ֖יִ⁠ךְ אֶשְׁפֹּ֥ט אֹתָֽ⁠ךְ׃","háşǎ֖b ʼel-ţȧʻĕrá֑⁠ḣ bi̇⁠mĕq֧wòm ʼàşěr-nibĕré֛ʼţ bĕ̇⁠ʼe֥reẕ mĕkurwòţa֖yi⁠kĕ ʼeşĕ̌pò֥̇t ʼòţáֽ⁠kĕ׃"],[21,31,"וְ⁠שָׁפַכְתִּ֤י עָלַ֨יִ⁠ךְ֙ זַעְמִ֔⁠י בְּ⁠אֵ֥שׁ עֶבְרָתִ֖⁠י אָפִ֣יחַ עָלָ֑יִ⁠ךְ וּ⁠נְתַתִּ֗י⁠ךְ בְּ⁠יַד֙ אֲנָשִׁ֣ים בֹּֽעֲרִ֔ים חָרָשֵׁ֖י מַשְׁחִֽית׃","wĕ⁠şá̌pakĕţi֤̇y ʻála֨yi⁠kĕ֙ zaʻĕmi֔⁠y bĕ̇⁠ʼé֥ş̌ ʻebĕráţi֖⁠y ʼápi֣yẖa ʻálá֑yi⁠kĕ ẇ⁠nĕţaţi̇֗y⁠kĕ bĕ̇⁠yad֙ ʼànáşǐ֣ym bòֽ̇ʻàri֔ym ẖáráşé֖̌y maşĕ̌ẖiֽyţ׃"],[21,32,"לָ⁠אֵ֤שׁ תִּֽהְיֶה֙ לְ⁠אָכְלָ֔ה דָּמֵ֥⁠ךְ יִהְיֶ֖ה בְּ⁠ת֣וֹךְ הָ⁠אָ֑רֶץ לֹ֣א תִזָּכֵ֔רִי כִּ֛י אֲנִ֥י יְהוָ֖ה דִּבַּֽרְתִּי׃פ","lá⁠ʼé֤ş̌ ţiֽ̇hĕyeh֙ lĕ⁠ʼákĕlá֔h dá̇mé֥⁠kĕ yihĕye֖h bĕ̇⁠ţ֣wòkĕ há⁠ʼá֑reẕ lò֣ʼ ţizá̇ké֔riy ki֛̇y ʼàni֥y yĕhwá֖h di̇bȧֽrĕţi̇y׃p"],[22,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[22,2,"וְ⁠אַתָּ֣ה בֶן־אָדָ֔ם הֲ⁠תִשְׁפֹּ֥ט הֲ⁠תִשְׁפֹּ֖ט אֶת־עִ֣יר הַ⁠דָּמִ֑ים וְ⁠ה֣וֹדַעְתָּ֔⁠הּ אֵ֖ת כָּל־תּוֹעֲבוֹתֶֽי⁠הָ׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֔m hà⁠ţişĕ̌pò֥̇t hà⁠ţişĕ̌pò֖̇t ʼeţ-ʻi֣yr ha⁠dá̇mi֑ym wĕ⁠h֣wòdaʻĕţá̇֔⁠ḣ ʼé֖ţ ká̇l-ţ̇wòʻàbwòţeֽy⁠há׃"],[22,3,"וְ⁠אָמַרְתָּ֗ כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה עִ֣יר שֹׁפֶ֥כֶת דָּ֛ם בְּ⁠תוֹכָ֖⁠הּ לָ⁠ב֣וֹא עִתָּ֑⁠הּ וְ⁠עָשְׂתָ֧ה גִלּוּלִ֛ים עָלֶ֖י⁠הָ לְ⁠טָמְאָֽה׃","wĕ⁠ʼámarĕţá̇֗ kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ʻi֣yr şò̌pe֥keţ dá֛̇m bĕ̇⁠ţwòká֖⁠ḣ lá⁠b֣wòʼ ʻiţá֑̇⁠ḣ wĕ⁠ʻáşĕ̂ţá֧h gil̇ẇli֛ym ʻále֖y⁠há lĕ⁠támĕʼáֽh׃"],[22,4,"בְּ⁠דָמֵ֨⁠ךְ אֲשֶׁר־שָׁפַ֜כְתְּ אָשַׁ֗מְתְּ וּ⁠בְ⁠גִלּוּלַ֤יִ⁠ךְ אֲשֶׁר־עָשִׂית֙ טָמֵ֔את וַ⁠תַּקְרִ֣יבִי יָמַ֔יִ⁠ךְ וַ⁠תָּב֖וֹא עַד־שְׁנוֹתָ֑יִ⁠ךְ עַל־כֵּ֗ן נְתַתִּ֤י⁠ךְ חֶרְפָּה֙ לַ⁠גּוֹיִ֔ם וְ⁠קַלָּסָ֖ה לְ⁠כָל־הָ⁠אֲרָצֽוֹת׃","bĕ̇⁠dámé֨⁠kĕ ʼàşěr-şá̌pa֜kĕţĕ̇ ʼáşǎ֗mĕţĕ̇ ẇ⁠bĕ⁠gil̇ẇla֤yi⁠kĕ ʼàşěr-ʻáşîyţ֙ támé֔ʼţ wa⁠ţȧqĕri֣ybiy yáma֔yi⁠kĕ wa⁠ţá̇b֖wòʼ ʻad-şĕ̌nwòţá֑yi⁠kĕ ʻal-ké̇֗n nĕţaţi֤̇y⁠kĕ ẖerĕpá̇h֙ la⁠ġwòyi֔m wĕ⁠qalá̇sá֖h lĕ⁠kál-há⁠ʼàráẕֽwòţ׃"],[22,5,"הַ⁠קְּרֹב֛וֹת וְ⁠הָ⁠רְחֹק֥וֹת מִמֵּ֖⁠ךְ יִתְקַלְּסוּ־בָ֑⁠ךְ טְמֵאַ֣ת הַ⁠שֵּׁ֔ם רַבַּ֖ת הַ⁠מְּהוּמָֽה׃","ha⁠qĕ̇ròb֛wòţ wĕ⁠há⁠rĕẖòq֥wòţ mimé֖̇⁠kĕ yiţĕqalĕ̇sẇ-bá֑⁠kĕ tĕméʼa֣ţ ha⁠şé̇̌֔m rabȧ֖ţ ha⁠mĕ̇hẇmáֽh׃"],[22,6,"הִנֵּה֙ נְשִׂיאֵ֣י יִשְׂרָאֵ֔ל אִ֥ישׁ לִ⁠זְרֹע֖⁠וֹ הָ֣יוּ בָ֑⁠ךְ לְמַ֖עַן שְׁפָךְ־דָּֽם׃","hiné̇h֙ nĕşîyʼé֣y yişĕ̂ráʼé֔l ʼi֥yş̌ li⁠zĕròʻ֖⁠wò há֣yẇ bá֑⁠kĕ lĕma֖ʻan şĕ̌pákĕ-dáֽ̇m׃"],[22,7,"אָ֤ב וָ⁠אֵם֙ הֵקַ֣לּוּ בָ֔⁠ךְ לַ⁠גֵּ֛ר עָשׂ֥וּ בַ⁠עֹ֖שֶׁק בְּ⁠תוֹכֵ֑⁠ךְ יָת֥וֹם וְ⁠אַלְמָנָ֖ה ה֥וֹנוּ בָֽ⁠ךְ׃","ʼá֤b wá⁠ʼém֙ héqa֣l̇ẇ bá֔⁠kĕ la⁠gé֛̇r ʻáş֥̂ẇ ba⁠ʻò֖şěq bĕ̇⁠ţwòké֑⁠kĕ yáţ֥wòm wĕ⁠ʼalĕmáná֖h h֥wònẇ báֽ⁠kĕ׃"],[22,8,"קָדָשַׁ֖⁠י בָּזִ֑ית וְ⁠אֶת־שַׁבְּתֹתַ֖⁠י חִלָּֽלְתְּ׃","qádáşǎ֖⁠y bá̇zi֑yţ wĕ⁠ʼeţ-şǎbĕ̇ţòţa֖⁠y ẖiláֽ̇lĕţĕ̇׃"],[22,9,"אַנְשֵׁ֥י רָכִ֛יל הָ֥יוּ בָ֖⁠ךְ לְמַ֣עַן שְׁפָךְ־דָּ֑ם וְ⁠אֶל־הֶֽ⁠הָרִים֙ אָ֣כְלוּ בָ֔⁠ךְ זִמָּ֖ה עָשׂ֥וּ בְ⁠תוֹכֵֽ⁠ךְ׃","ʼanĕşé֥̌y ráki֛yl há֥yẇ bá֖⁠kĕ lĕma֣ʻan şĕ̌pákĕ-dá֑̇m wĕ⁠ʼel-heֽ⁠háriym֙ ʼá֣kĕlẇ bá֔⁠kĕ zimá֖̇h ʻáş֥̂ẇ bĕ⁠ţwòkéֽ⁠kĕ׃"],[22,10,"עֶרְוַת־אָ֖ב גִּלָּה־בָ֑⁠ךְ טְמֵאַ֥ת הַ⁠נִּדָּ֖ה עִנּוּ־בָֽ⁠ךְ׃","ʻerĕwaţ-ʼá֖b gi̇lá̇h-bá֑⁠kĕ tĕméʼa֥ţ ha⁠ni̇dá֖̇h ʻiṅẇ-báֽ⁠kĕ׃"],[22,11,"וְ⁠אִ֣ישׁ ׀ אֶת־אֵ֣שֶׁת רֵעֵ֗⁠הוּ עָשָׂה֙ תּֽוֹעֵבָ֔ה וְ⁠אִ֥ישׁ אֶת־כַּלָּת֖⁠וֹ טִמֵּ֣א בְ⁠זִמָּ֑ה וְ⁠אִ֛ישׁ אֶת־אֲחֹת֥⁠וֹ בַת־אָבִ֖י⁠ו עִנָּה־בָֽ⁠ךְ׃","wĕ⁠ʼi֣yş̌ ׀ ʼeţ-ʼé֣şěţ réʻé֗⁠hẇ ʻáşá̂h֙ ţֽ̇wòʻébá֔h wĕ⁠ʼi֥yş̌ ʼeţ-kȧlá̇ţ֖⁠wò timé֣̇ʼ bĕ⁠zimá֑̇h wĕ⁠ʼi֛yş̌ ʼeţ-ʼàẖòţ֥⁠wò baţ-ʼábi֖y⁠w ʻiná̇h-báֽ⁠kĕ׃"],[22,12,"שֹׁ֥חַד לָֽקְחוּ־בָ֖⁠ךְ לְמַ֣עַן שְׁפָךְ־דָּ֑ם נֶ֧שֶׁךְ וְ⁠תַרְבִּ֣ית לָקַ֗חַתְּ וַ⁠תְּבַצְּעִ֤י רֵעַ֨יִ⁠ךְ֙ בַּ⁠עֹ֔שֶׁק וְ⁠אֹתִ֣⁠י שָׁכַ֔חַתְּ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","şò֥̌ẖad láֽqĕẖẇ-bá֖⁠kĕ lĕma֣ʻan şĕ̌pákĕ-dá֑̇m ne֧şěkĕ wĕ⁠ţarĕbi֣̇yţ láqa֗ẖaţĕ̇ wa⁠ţĕ̇baẕĕ̇ʻi֤y réʻa֨yi⁠kĕ֙ bȧ⁠ʻò֔şěq wĕ⁠ʼòţi֣⁠y şá̌ka֔ẖaţĕ̇ nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[22,13,"וְ⁠הִנֵּה֙ הִכֵּ֣יתִי כַפִּ֔⁠י אֶל־בִּצְעֵ֖⁠ךְ אֲשֶׁ֣ר עָשִׂ֑ית וְ⁠עַ֨ל־דָּמֵ֔⁠ךְ אֲשֶׁ֥ר הָי֖וּ בְּ⁠תוֹכֵֽ⁠ךְ׃","wĕ⁠hiné̇h֙ hiké֣̇yţiy kapi̇֔⁠y ʼel-bi̇ẕĕʻé֖⁠kĕ ʼàşě֣r ʻáşî֑yţ wĕ⁠ʻa֨l-dá̇mé֔⁠kĕ ʼàşě֥r háy֖ẇ bĕ̇⁠ţwòkéֽ⁠kĕ׃"],[22,14,"הֲ⁠יַעֲמֹ֤ד לִבֵּ⁠ךְ֙ אִם־תֶּחֱזַ֣קְנָה יָדַ֔יִ⁠ךְ לַ⁠יָּמִ֕ים אֲשֶׁ֥ר אֲנִ֖י עֹשֶׂ֣ה אוֹתָ֑⁠ךְ אֲנִ֥י יְהוָ֖ה דִּבַּ֥רְתִּי וְ⁠עָשִֽׂיתִי׃","hà⁠yaʻàmò֤d libé̇⁠kĕ֙ ʼim-ţėẖèza֣qĕnáh yáda֔yi⁠kĕ la⁠yá̇mi֕ym ʼàşě֥r ʼàni֖y ʻòşê֣h ʼwòţá֑⁠kĕ ʼàni֥y yĕhwá֖h di̇bȧ֥rĕţi̇y wĕ⁠ʻáşîֽyţiy׃"],[22,15,"וַ⁠הֲפִיצוֹתִ֤י אוֹתָ⁠ךְ֙ בַּ⁠גּוֹיִ֔ם וְ⁠זֵרִיתִ֖י⁠ךְ בָּ⁠אֲרָצ֑וֹת וַ⁠הֲתִמֹּתִ֥י טֻמְאָתֵ֖⁠ךְ מִמֵּֽ⁠ךְ׃","wa⁠hàpiyẕwòţi֤y ʼwòţá⁠kĕ֙ bȧ⁠ġwòyi֔m wĕ⁠zériyţi֖y⁠kĕ bá̇⁠ʼàráẕ֑wòţ wa⁠hàţimò̇ţi֥y tumĕʼáţé֖⁠kĕ miméֽ̇⁠kĕ׃"],[22,16,"וְ⁠נִחַ֥לְתְּ בָּ֖⁠ךְ לְ⁠עֵינֵ֣י גוֹיִ֑ם וְ⁠יָדַ֖עַתְּ כִּֽי־אֲנִ֥י יְהוָֽה׃פ","wĕ⁠niẖa֥lĕţĕ̇ bá֖̇⁠kĕ lĕ⁠ʻéyné֣y gwòyi֑m wĕ⁠yáda֖ʻaţĕ̇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃p"],[22,17,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[22,18,"בֶּן־אָדָ֕ם הָיוּ־לִ֥⁠י בֵֽית־יִשְׂרָאֵ֖ל ל⁠סוג כֻּלָּ֡⁠ם נְ֠חֹשֶׁת וּ⁠בְדִ֨יל וּ⁠בַרְזֶ֤ל וְ⁠עוֹפֶ֨רֶת֙ בְּ⁠ת֣וֹךְ כּ֔וּר סִגִ֥ים כֶּ֖סֶף הָיֽוּ׃ס","bėn-ʼádá֕m háyẇ-li֥⁠y béֽyţ-yişĕ̂ráʼé֖l l⁠swg ku̇lá̇֡⁠m nĕ֠ẖòşěţ ẇ⁠bĕdi֨yl ẇ⁠barĕze֤l wĕ⁠ʻwòpe֨reţ֙ bĕ̇⁠ţ֣wòkĕ k̇֔ẇr sigi֥ym kė֖sep háyֽẇ׃s"],[22,19,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה יַ֛עַן הֱי֥וֹת כֻּלְּ⁠כֶ֖ם לְ⁠סִגִ֑ים לָ⁠כֵן֙ הִנְ⁠נִ֣י קֹבֵ֣ץ אֶתְ⁠כֶ֔ם אֶל־תּ֖וֹךְ יְרוּשָׁלִָֽם׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ya֛ʻan hèy֥wòţ ku̇lĕ̇⁠ke֖m lĕ⁠sigi֑ym lá⁠kén֙ hinĕ⁠ni֣y qòbé֣ẕ ʼeţĕ⁠ke֔m ʼel-ţ֖̇wòkĕ yĕrẇşá̌liáֽm׃"],[22,20,"קְבֻ֣צַת כֶּ֡סֶף וּ֠⁠נְחֹשֶׁת וּ⁠בַרְזֶ֨ל וְ⁠עוֹפֶ֤רֶת וּ⁠בְדִיל֙ אֶל־תּ֣וֹךְ כּ֔וּר לָ⁠פַֽחַת־עָלָ֥י⁠ו אֵ֖שׁ לְ⁠הַנְתִּ֑יךְ כֵּ֤ן אֶקְבֹּץ֙ בְּ⁠אַפִּ֣⁠י וּ⁠בַ⁠חֲמָתִ֔⁠י וְ⁠הִנַּחְתִּ֥י וְ⁠הִתַּכְתִּ֖י אֶתְ⁠כֶֽם׃","qĕbu֣ẕaţ kė֡sep ẇ֠⁠nĕẖòşěţ ẇ⁠barĕze֨l wĕ⁠ʻwòpe֤reţ ẇ⁠bĕdiyl֙ ʼel-ţ֣̇wòkĕ k̇֔ẇr lá⁠paֽẖaţ-ʻálá֥y⁠w ʼé֖ş̌ lĕ⁠hanĕţi֑̇ykĕ ké֤̇n ʼeqĕbò̇ẕ֙ bĕ̇⁠ʼapi֣̇⁠y ẇ⁠ba⁠ẖàmáţi֔⁠y wĕ⁠hinȧẖĕţi֥̇y wĕ⁠hiţȧkĕţi֖̇y ʼeţĕ⁠keֽm׃"],[22,21,"וְ⁠כִנַּסְתִּ֣י אֶתְ⁠כֶ֔ם וְ⁠נָפַחְתִּ֥י עֲלֵי⁠כֶ֖ם בְּ⁠אֵ֣שׁ עֶבְרָתִ֑⁠י וְ⁠נִתַּכְתֶּ֖ם בְּ⁠תוֹכָֽ⁠הּ׃","wĕ⁠kinȧsĕţi֣̇y ʼeţĕ⁠ke֔m wĕ⁠nápaẖĕţi֥̇y ʻàléy⁠ke֖m bĕ̇⁠ʼé֣ş̌ ʻebĕráţi֑⁠y wĕ⁠niţȧkĕţė֖m bĕ̇⁠ţwòkáֽ⁠ḣ׃"],[22,22,"כְּ⁠הִתּ֥וּךְ כֶּ֨סֶף֙ בְּ⁠ת֣וֹךְ כּ֔וּר כֵּ֖ן תֻּתְּכ֣וּ בְ⁠תוֹכָ֑⁠הּ וִֽ⁠ידַעְתֶּם֙ כִּֽי־אֲנִ֣י יְהוָ֔ה שָׁפַ֥כְתִּי חֲמָתִ֖⁠י עֲלֵי⁠כֶֽם׃פ","kĕ̇⁠hiţ֥̇ẇkĕ kė֨sep֙ bĕ̇⁠ţ֣wòkĕ k̇֔ẇr ké֖̇n ţu̇ţĕ̇k֣ẇ bĕ⁠ţwòká֑⁠ḣ wiֽ⁠ydaʻĕţėm֙ kiֽ̇y-ʼàni֣y yĕhwá֔h şá̌pa֥kĕţi̇y ẖàmáţi֖⁠y ʻàléy⁠keֽm׃p"],[22,23,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[22,24,"בֶּן־אָדָ֕ם אֱמָר־לָ֕⁠הּ אַ֣תְּ אֶ֔רֶץ לֹ֥א מְטֹהָרָ֖ה הִ֑יא לֹ֥א גֻשְׁמָ֖⁠הּ בְּ⁠י֥וֹם זָֽעַם׃","bėn-ʼádá֕m ʼèmár-lá֕⁠ḣ ʼa֣ţĕ̇ ʼe֔reẕ lò֥ʼ mĕtòhárá֖h hi֑yʼ lò֥ʼ guşĕ̌má֖⁠ḣ bĕ̇⁠y֥wòm záֽʻam׃"],[22,25,"קֶ֤שֶׁר נְבִיאֶ֨י⁠הָ֙ בְּ⁠תוֹכָ֔⁠הּ כַּ⁠אֲרִ֥י שׁוֹאֵ֖ג טֹ֣רֵֽף טָ֑רֶף נֶ֣פֶשׁ אָכָ֗לוּ חֹ֤סֶן וִ⁠יקָר֙ יִקָּ֔חוּ אַלְמְנוֹתֶ֖י⁠הָ הִרְבּ֥וּ בְ⁠תוֹכָֽ⁠הּ׃","qe֤şěr nĕbiyʼe֨y⁠há֙ bĕ̇⁠ţwòká֔⁠ḣ kȧ⁠ʼàri֥y ş̌wòʼé֖g tò֣réֽp tá֑rep ne֣peş̌ ʼáká֗lẇ ẖò֤sen wi⁠yqár֙ yiqá̇֔ẖẇ ʼalĕmĕnwòţe֖y⁠há hirĕḃ֥ẇ bĕ⁠ţwòkáֽ⁠ḣ׃"],[22,26,"כֹּהֲנֶ֜י⁠הָ חָמְס֣וּ תוֹרָתִ⁠י֮ וַ⁠יְחַלְּל֣וּ קָדָשַׁ⁠י֒ בֵּֽין־קֹ֤דֶשׁ לְ⁠חֹל֙ לֹ֣א הִבְדִּ֔ילוּ וּ⁠בֵין־הַ⁠טָּמֵ֥א לְ⁠טָה֖וֹר לֹ֣א הוֹדִ֑יעוּ וּ⁠מִ⁠שַׁבְּתוֹתַ⁠י֙ הֶעְלִ֣ימוּ עֵֽינֵי⁠הֶ֔ם וָ⁠אֵחַ֖ל בְּ⁠תוֹכָֽ⁠ם׃","kò̇hàne֜y⁠há ẖámĕs֣ẇ ţwòráţi⁠y֮ wa⁠yĕẖalĕ̇l֣ẇ qádáşǎ⁠y֒ béֽ̇yn-qò֤deş̌ lĕ⁠ẖòl֙ lò֣ʼ hibĕdi̇֔ylẇ ẇ⁠béyn-ha⁠tá̇mé֥ʼ lĕ⁠táh֖wòr lò֣ʼ hwòdi֑yʻẇ ẇ⁠mi⁠şǎbĕ̇ţwòţa⁠y֙ heʻĕli֣ymẇ ʻéֽynéy⁠he֔m wá⁠ʼéẖa֖l bĕ̇⁠ţwòkáֽ⁠m׃"],[22,27,"שָׂרֶ֣י⁠הָ בְ⁠קִרְבָּ֔⁠הּ כִּ⁠זְאֵבִ֖ים טֹ֣רְפֵי טָ֑רֶף לִ⁠שְׁפָּךְ־דָּם֙ לְ⁠אַבֵּ֣ד נְפָשׁ֔וֹת לְמַ֖עַן בְּצֹ֥עַ בָּֽצַע׃","şá̂re֣y⁠há bĕ⁠qirĕbá̇֔⁠ḣ ki̇⁠zĕʼébi֖ym tò֣rĕpéy tá֑rep li⁠şĕ̌pá̇kĕ-dá̇m֙ lĕ⁠ʼabé֣̇d nĕpáş̌֔wòţ lĕma֖ʻan bĕ̇ẕò֥ʻa báֽ̇ẕaʻ׃"],[22,28,"וּ⁠נְבִיאֶ֗י⁠הָ טָח֤וּ לָ⁠הֶם֙ תָּפֵ֔ל חֹזִ֣ים שָׁ֔וְא וְ⁠קֹסְמִ֥ים לָ⁠הֶ֖ם כָּזָ֑ב אֹמְרִ֗ים כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה וַֽ⁠יהוָ֖ה לֹ֥א דִבֵּֽר׃","ẇ⁠nĕbiyʼe֗y⁠há táẖ֤ẇ lá⁠hem֙ ţá̇pé֔l ẖòzi֣ym şá̌֔wĕʼ wĕ⁠qòsĕmi֥ym lá⁠he֖m ká̇zá֑b ʼòmĕri֗ym kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h waֽ⁠yhwá֖h lò֥ʼ dibéֽ̇r׃"],[22,29,"עַ֤ם הָ⁠אָ֨רֶץ֙ עָ֣שְׁקוּ עֹ֔שֶׁק וְ⁠גָזְל֖וּ גָּזֵ֑ל וְ⁠עָנִ֤י וְ⁠אֶבְיוֹן֙ הוֹנ֔וּ וְ⁠אֶת־הַ⁠גֵּ֥ר עָשְׁק֖וּ בְּ⁠לֹ֥א מִשְׁפָּֽט׃","ʻa֤m há⁠ʼá֨reẕ֙ ʻá֣şĕ̌qẇ ʻò֔şěq wĕ⁠gázĕl֖ẇ gá̇zé֑l wĕ⁠ʻáni֤y wĕ⁠ʼebĕywòn֙ hwòn֔ẇ wĕ⁠ʼeţ-ha⁠gé֥̇r ʻáşĕ̌q֖ẇ bĕ̇⁠lò֥ʼ mişĕ̌páֽ̇t׃"],[22,30,"וָ⁠אֲבַקֵּ֣שׁ מֵ⁠הֶ֡ם אִ֣ישׁ גֹּֽדֵר־גָּדֵר֩ וְ⁠עֹמֵ֨ד בַּ⁠פֶּ֧רֶץ לְ⁠פָנַ֛⁠י בְּעַ֥ד הָ⁠אָ֖רֶץ לְ⁠בִלְתִּ֣י שַׁחֲתָ֑⁠הּ וְ⁠לֹ֖א מָצָֽאתִי׃","wá⁠ʼàbaqé֣̇ş̌ mé⁠he֡m ʼi֣yş̌ gòֽ̇dér-gá̇dér֩ wĕ⁠ʻòmé֨d bȧ⁠pė֧reẕ lĕ⁠pána֛⁠y bĕ̇ʻa֥d há⁠ʼá֖reẕ lĕ⁠bilĕţi֣̇y şǎẖàţá֑⁠ḣ wĕ⁠lò֖ʼ máẕáֽʼţiy׃"],[22,31,"וָ⁠אֶשְׁפֹּ֤ךְ עֲלֵי⁠הֶם֙ זַעְמִ֔⁠י בְּ⁠אֵ֥שׁ עֶבְרָתִ֖⁠י כִּלִּיתִ֑י⁠ם דַּרְכָּ⁠ם֙ בְּ⁠רֹאשָׁ֣⁠ם נָתַ֔תִּי נְאֻ֖ם אֲדֹנָ֥⁠י יְהֹוִֽה׃פ","wá⁠ʼeşĕ̌pò֤̇kĕ ʻàléy⁠hem֙ zaʻĕmi֔⁠y bĕ̇⁠ʼé֥ş̌ ʻebĕráţi֖⁠y ki̇li̇yţi֑y⁠m dȧrĕká̇⁠m֙ bĕ̇⁠ròʼşá֣̌⁠m náţa֔ţi̇y nĕʼu֖m ʼàdòná֥⁠y yĕhòwiֽh׃p"],[23,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[23,2,"בֶּן־אָדָ֑ם שְׁתַּ֣יִם נָשִׁ֔ים בְּנ֥וֹת אֵם־אַחַ֖ת הָיֽוּ׃","bėn-ʼádá֑m şĕ̌ţȧ֣yim náşǐ֔ym bĕ̇n֥wòţ ʼém-ʼaẖa֖ţ háyֽẇ׃"],[23,3,"וַ⁠תִּזְנֶ֣ינָה בְ⁠מִצְרַ֔יִם בִּ⁠נְעוּרֵי⁠הֶ֖ן זָנ֑וּ שָׁ֚מָּ⁠ה מֹעֲכ֣וּ שְׁדֵי⁠הֶ֔ן וְ⁠שָׁ֣ם עִשּׂ֔וּ דַּדֵּ֖י בְּתוּלֵי⁠הֶֽן׃","wa⁠ţi̇zĕne֣ynáh bĕ⁠miẕĕra֔yim bi̇⁠nĕʻẇréy⁠he֖n zán֑ẇ şá֚̌má̇⁠h mòʻàk֣ẇ şĕ̌déy⁠he֔n wĕ⁠şá֣̌m ʻiş̇̂֔ẇ dȧdé֖̇y bĕ̇ţẇléy⁠heֽn׃"],[23,4,"וּ⁠שְׁמוֹתָ֗⁠ן אָהֳלָ֤ה הַ⁠גְּדוֹלָה֙ וְ⁠אָהֳלִיבָ֣ה אֲחוֹתָ֔⁠הּ וַ⁠תִּֽהְיֶ֣ינָה לִ֔⁠י וַ⁠תֵּלַ֖דְנָה בָּנִ֣ים וּ⁠בָנ֑וֹת וּ⁠שְׁמוֹתָ֕⁠ן שֹׁמְר֣וֹן אָהֳלָ֔ה וִ⁠ירוּשָׁלִַ֖ם אָהֳלִיבָֽה׃","ẇ⁠şĕ̌mwòţá֗⁠n ʼáholá֤h ha⁠gĕ̇dwòláh֙ wĕ⁠ʼáholiybá֣h ʼàẖwòţá֔⁠ḣ wa⁠ţiֽ̇hĕye֣ynáh li֔⁠y wa⁠ţé̇la֖dĕnáh bá̇ni֣ym ẇ⁠bán֑wòţ ẇ⁠şĕ̌mwòţá֕⁠n şò̌mĕr֣wòn ʼáholá֔h wi⁠yrẇşá̌lia֖m ʼáholiybáֽh׃"],[23,5,"וַ⁠תִּ֥זֶן אָהֳלָ֖ה תַּחְתָּ֑⁠י וַ⁠תַּעְגַּב֙ עַֽל־מְאַהֲבֶ֔י⁠הָ אֶל־אַשּׁ֖וּר קְרוֹבִֽים׃","wa⁠ţi֥̇zen ʼáholá֖h ţȧẖĕţá֑̇⁠y wa⁠ţȧʻĕgȧb֙ ʻaֽl-mĕʼahàbe֔y⁠há ʼel-ʼaş֖̇̌ẇr qĕrwòbiֽym׃"],[23,6,"לְבֻשֵׁ֤י תְכֵ֨לֶת֙ פַּח֣וֹת וּ⁠סְגָנִ֔ים בַּח֥וּרֵי חֶ֖מֶד כֻּלָּ֑⁠ם פָּרָשִׁ֕ים רֹכְבֵ֖י סוּסִֽים׃","lĕbuşé֤̌y ţĕké֨leţ֙ pȧẖ֣wòţ ẇ⁠sĕgáni֔ym bȧẖ֥ẇréy ẖe֖med ku̇lá֑̇⁠m pá̇ráşǐ֕ym ròkĕbé֖y sẇsiֽym׃"],[23,7,"וַ⁠תִּתֵּ֤ן תַּזְנוּתֶ֨י⁠הָ֙ עֲלֵי⁠הֶ֔ם מִבְחַ֥ר בְּנֵֽי־אַשּׁ֖וּר כֻּלָּ֑⁠ם וּ⁠בְ⁠כֹ֧ל אֲשֶׁר־עָֽגְבָ֛ה בְּ⁠כָל־גִּלּוּלֵי⁠הֶ֖ם נִטְמָֽאָה׃","wa⁠ţi̇ţé֤̇n ţȧzĕnẇţe֨y⁠há֙ ʻàléy⁠he֔m mibĕẖa֥r bĕ̇néֽy-ʼaş֖̇̌ẇr ku̇lá֑̇⁠m ẇ⁠bĕ⁠kò֧l ʼàşěr-ʻֽágĕbá֛h bĕ̇⁠kál-gi̇l̇ẇléy⁠he֖m nitĕmáֽʼáh׃"],[23,8,"וְ⁠אֶת־תַּזְנוּתֶ֤י⁠הָ מִ⁠מִּצְרַ֨יִם֙ לֹ֣א עָזָ֔בָה כִּ֤י אוֹתָ⁠הּ֙ שָׁכְב֣וּ בִ⁠נְעוּרֶ֔י⁠הָ וְ⁠הֵ֥מָּה עִשּׂ֖וּ דַּדֵּ֣י בְתוּלֶ֑י⁠הָ וַ⁠יִּשְׁפְּכ֥וּ תַזְנוּתָ֖⁠ם עָלֶֽי⁠הָ׃","wĕ⁠ʼeţ-ţȧzĕnẇţe֤y⁠há mi⁠mi̇ẕĕra֨yim֙ lò֣ʼ ʻázá֔báh ki֤̇y ʼwòţá⁠ḣ֙ şá̌kĕb֣ẇ bi⁠nĕʻẇre֔y⁠há wĕ⁠hé֥má̇h ʻiş֖̇̂ẇ dȧdé֣̇y bĕţẇle֑y⁠há wa⁠yi̇şĕ̌pĕ̇k֥ẇ ţazĕnẇţá֖⁠m ʻáleֽy⁠há׃"],[23,9,"לָ⁠כֵ֥ן נְתַתִּ֖י⁠הָ בְּ⁠יַד־מְאַֽהֲבֶ֑י⁠הָ בְּ⁠יַד֙ בְּנֵ֣י אַשּׁ֔וּר אֲשֶׁ֥ר עָגְבָ֖ה עֲלֵי⁠הֶֽם׃","lá⁠ké֥n nĕţaţi֖̇y⁠há bĕ̇⁠yad-mĕʼaֽhàbe֑y⁠há bĕ̇⁠yad֙ bĕ̇né֣y ʼaş̇̌֔ẇr ʼàşě֥r ʻágĕbá֖h ʻàléy⁠heֽm׃"],[23,10,"הֵמָּה֮ גִּלּ֣וּ עֶרְוָתָ⁠הּ֒ בָּנֶ֤י⁠הָ וּ⁠בְנוֹתֶ֨י⁠הָ֙ לָקָ֔חוּ וְ⁠אוֹתָ֖⁠הּ בַּ⁠חֶ֣רֶב הָרָ֑גוּ וַ⁠תְּהִי־שֵׁם֙ לַ⁠נָּשִׁ֔ים וּ⁠שְׁפוּטִ֖ים עָ֥שׂוּ בָֽ⁠הּ׃ס","hémá̇h֮ gi̇l֣̇ẇ ʻerĕwáţá⁠ḣ֒ bá̇ne֤y⁠há ẇ⁠bĕnwòţe֨y⁠há֙ láqá֔ẖẇ wĕ⁠ʼwòţá֖⁠ḣ bȧ⁠ẖe֣reb hárá֑gẇ wa⁠ţĕ̇hiy-şé̌m֙ la⁠ná̇şǐ֔ym ẇ⁠şĕ̌pẇti֖ym ʻá֥ş̂ẇ báֽ⁠ḣ׃s"],[23,11,"וַ⁠תֵּ֨רֶא֙ אֲחוֹתָ֣⁠הּ אָהֳלִיבָ֔ה וַ⁠תַּשְׁחֵ֥ת עַגְבָתָ֖⁠הּ מִמֶּ֑⁠נָּה וְ⁠אֶת־תַּ֨זְנוּתֶ֔י⁠הָ מִ⁠זְּנוּנֵ֖י אֲחוֹתָֽ⁠הּ׃","wa⁠ţé̇֨reʼ֙ ʼàẖwòţá֣⁠ḣ ʼáholiybá֔h wa⁠ţȧşĕ̌ẖé֥ţ ʻagĕbáţá֖⁠ḣ mimė֑⁠ná̇h wĕ⁠ʼeţ-ţȧ֨zĕnẇţe֔y⁠há mi⁠zĕ̇nẇné֖y ʼàẖwòţáֽ⁠ḣ׃"],[23,12,"אֶל־בְּנֵי֩ אַשּׁ֨וּר עָגָ֜בָה פַּח֨וֹת וּ⁠סְגָנִ֤ים קְרֹבִים֙ לְבֻשֵׁ֣י מִכְל֔וֹל פָּרָשִׁ֖ים רֹכְבֵ֣י סוּסִ֑ים בַּח֥וּרֵי חֶ֖מֶד כֻּלָּֽ⁠ם׃","ʼel-bĕ̇néy֩ ʼaş̇̌֨ẇr ʻágá֜báh pȧẖ֨wòţ ẇ⁠sĕgáni֤ym qĕròbiym֙ lĕbuşé֣̌y mikĕl֔wòl pá̇ráşǐ֖ym ròkĕbé֣y sẇsi֑ym bȧẖ֥ẇréy ẖe֖med ku̇láֽ̇⁠m׃"],[23,13,"וָ⁠אֵ֖רֶא כִּ֣י נִטְמָ֑אָה דֶּ֥רֶךְ אֶחָ֖ד לִ⁠שְׁתֵּי⁠הֶֽן׃","wá⁠ʼé֖reʼ ki֣̇y nitĕmá֑ʼáh dė֥rekĕ ʼeẖá֖d li⁠şĕ̌ţé̇y⁠heֽn׃"],[23,14,"וַ⁠תּ֖וֹסֶף אֶל־תַּזְנוּתֶ֑י⁠הָ וַ⁠תֵּ֗רֶא אַנְשֵׁי֙ מְחֻקֶּ֣ה עַל־הַ⁠קִּ֔יר צַלְמֵ֣י כשדיים חֲקֻקִ֖ים בַּ⁠שָּׁשַֽׁר׃","wa⁠ţ֖̇wòsep ʼel-ţȧzĕnẇţe֑y⁠há wa⁠ţé̇֗reʼ ʼanĕşé̌y֙ mĕẖuqė֣h ʻal-ha⁠qi̇֔yr ẕalĕmé֣y kşdyym ẖàquqi֖ym bȧ⁠şá̇̌şǎֽr׃"],[23,15,"חֲגוֹרֵ֨י אֵז֜וֹר בְּ⁠מָתְנֵי⁠הֶ֗ם סְרוּחֵ֤י טְבוּלִים֙ בְּ⁠רָ֣אשֵׁי⁠הֶ֔ם מַרְאֵ֥ה שָׁלִשִׁ֖ים כֻּלָּ֑⁠ם דְּמ֤וּת בְּנֵֽי־בָבֶל֙ כַּשְׂדִּ֔ים אֶ֖רֶץ מוֹלַדְתָּֽ⁠ם׃","ẖàgwòré֨y ʼéz֜wòr bĕ̇⁠máţĕnéy⁠he֗m sĕrẇẖé֤y tĕbẇliym֙ bĕ̇⁠rá֣ʼşé̌y⁠he֔m marĕʼé֥h şá̌lişǐ֖ym ku̇lá֑̇⁠m dĕ̇m֤ẇţ bĕ̇néֽy-bábel֙ kȧşĕ̂di̇֔ym ʼe֖reẕ mwòladĕţáֽ̇⁠m׃"],[23,16,"ו⁠תעגב עֲלֵי⁠הֶ֖ם לְ⁠מַרְאֵ֣ה עֵינֶ֑י⁠הָ וַ⁠תִּשְׁלַ֧ח מַלְאָכִ֛ים אֲלֵי⁠הֶ֖ם כַּשְׂדִּֽימָ⁠ה׃","w⁠ţʻgb ʻàléy⁠he֖m lĕ⁠marĕʼé֣h ʻéyne֑y⁠há wa⁠ţi̇şĕ̌la֧ẖ malĕʼáki֛ym ʼàléy⁠he֖m kȧşĕ̂diֽ̇ymá⁠h׃"],[23,17,"וַ⁠יָּבֹ֨אוּ אֵלֶ֤י⁠הָ בְנֵֽי־בָבֶל֙ לְ⁠מִשְׁכַּ֣ב דֹּדִ֔ים וַ⁠יְטַמְּא֥וּ אוֹתָ֖⁠הּ בְּ⁠תַזְנוּתָ֑⁠ם וַ⁠תִּ֨טְמָא־בָ֔⁠ם וַ⁠תֵּ֥קַע נַפְשָׁ֖⁠הּ מֵ⁠הֶֽם׃","wa⁠yá̇bò֨ʼẇ ʼéle֤y⁠há bĕnéֽy-bábel֙ lĕ⁠mişĕ̌kȧ֣b dò̇di֔ym wa⁠yĕtamĕ̇ʼ֥ẇ ʼwòţá֖⁠ḣ bĕ̇⁠ţazĕnẇţá֑⁠m wa⁠ţi̇֨tĕmáʼ-bá֔⁠m wa⁠ţé֥̇qaʻ napĕşá֖̌⁠ḣ mé⁠heֽm׃"],[23,18,"וַ⁠תְּגַל֙ תַּזְנוּתֶ֔י⁠הָ וַ⁠תְּגַ֖ל אֶת־עֶרְוָתָ֑⁠הּ וַ⁠תֵּ֤קַע נַפְשִׁ⁠י֙ מֵֽ⁠עָלֶ֔י⁠הָ כַּ⁠אֲשֶׁ֛ר נָקְעָ֥ה נַפְשִׁ֖⁠י מֵ⁠עַ֥ל אֲחוֹתָֽ⁠הּ׃","wa⁠ţĕ̇gal֙ ţȧzĕnẇţe֔y⁠há wa⁠ţĕ̇ga֖l ʼeţ-ʻerĕwáţá֑⁠ḣ wa⁠ţé֤̇qaʻ napĕşǐ⁠y֙ méֽ⁠ʻále֔y⁠há kȧ⁠ʼàşě֛r náqĕʻá֥h napĕşǐ֖⁠y mé⁠ʻa֥l ʼàẖwòţáֽ⁠ḣ׃"],[23,19,"וַ⁠תַּרְבֶּ֖ה אֶת־תַּזְנוּתֶ֑י⁠הָ לִ⁠זְכֹּר֙ אֶת־יְמֵ֣י נְעוּרֶ֔י⁠הָ אֲשֶׁ֥ר זָנְתָ֖ה בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","wa⁠ţȧrĕbė֖h ʼeţ-ţȧzĕnẇţe֑y⁠há li⁠zĕkò̇r֙ ʼeţ-yĕmé֣y nĕʻẇre֔y⁠há ʼàşě֥r zánĕţá֖h bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[23,20,"וַֽ⁠תַּעְגְּבָ֔⁠ה עַ֖ל פִּֽלַגְשֵׁי⁠הֶ֑ם אֲשֶׁ֤ר בְּשַׂר־חֲמוֹרִים֙ בְּשָׂרָ֔⁠ם וְ⁠זִרְמַ֥ת סוּסִ֖ים זִרְמָתָֽ⁠ם׃","waֽ⁠ţȧʻĕgĕ̇bá֔⁠h ʻa֖l piֽ̇lagĕşé̌y⁠he֑m ʼàşě֤r bĕ̇şâr-ẖàmwòriym֙ bĕ̇şá̂rá֔⁠m wĕ⁠zirĕma֥ţ sẇsi֖ym zirĕmáţáֽ⁠m׃"],[23,21,"וַֽ⁠תִּפְקְדִ֔י אֵ֖ת זִמַּ֣ת נְעוּרָ֑יִ⁠ךְ בַּ⁠עְשׂ֤וֹת מִ⁠מִּצְרַ֨יִם֙ דַּדַּ֔יִ⁠ךְ לְמַ֖עַן שְׁדֵ֥י נְעוּרָֽיִ⁠ךְ׃ס","waֽ⁠ţi̇pĕqĕdi֔y ʼé֖ţ zimȧ֣ţ nĕʻẇrá֑yi⁠kĕ bȧ⁠ʻĕş֤̂wòţ mi⁠mi̇ẕĕra֨yim֙ dȧdȧ֔yi⁠kĕ lĕma֖ʻan şĕ̌dé֥y nĕʻẇráֽyi⁠kĕ׃s"],[23,22,"לָ⁠כֵ֣ן אָהֳלִיבָ֗ה כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ הִנְ⁠נִ֨י מֵעִ֤יר אֶת־מְאַהֲבַ֨יִ⁠ךְ֙ עָלַ֔יִ⁠ךְ אֵ֛ת אֲשֶׁר־נָקְעָ֥ה נַפְשֵׁ֖⁠ךְ מֵ⁠הֶ֑ם וַ⁠הֲבֵאתִ֥י⁠ם עָלַ֖יִ⁠ךְ מִ⁠סָּבִֽיב׃","lá⁠ké֣n ʼáholiybá֗h kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ hinĕ⁠ni֨y méʻi֤yr ʼeţ-mĕʼahàba֨yi⁠kĕ֙ ʻála֔yi⁠kĕ ʼé֛ţ ʼàşěr-náqĕʻá֥h napĕşé֖̌⁠kĕ mé⁠he֑m wa⁠hàbéʼţi֥y⁠m ʻála֖yi⁠kĕ mi⁠sá̇biֽyb׃"],[23,23,"בְּנֵ֧י בָבֶ֣ל וְ⁠כָל־כַּשְׂדִּ֗ים פְּק֤וֹד וְ⁠שׁ֨וֹעַ֙ וְ⁠ק֔וֹעַ כָּל־בְּנֵ֥י אַשּׁ֖וּר אוֹתָ֑⁠ם בַּח֨וּרֵי חֶ֜מֶד פַּח֤וֹת וּ⁠סְגָנִים֙ כֻּלָּ֔⁠ם שָֽׁלִשִׁים֙ וּ⁠קְרוּאִ֔ים רֹכְבֵ֥י סוּסִ֖ים כֻּלָּֽ⁠ם׃","bĕ̇né֧y bábe֣l wĕ⁠kál-kȧşĕ̂di̇֗ym pĕ̇q֤wòd wĕ⁠ş̌֨wòʻa֙ wĕ⁠q֔wòʻa ká̇l-bĕ̇né֥y ʼaş֖̇̌ẇr ʼwòţá֑⁠m bȧẖ֨ẇréy ẖe֜med pȧẖ֤wòţ ẇ⁠sĕgániym֙ ku̇lá̇֔⁠m şáֽ̌lişǐym֙ ẇ⁠qĕrẇʼi֔ym ròkĕbé֥y sẇsi֖ym ku̇láֽ̇⁠m׃"],[23,24,"וּ⁠בָ֣אוּ עָלַ֡יִ⁠ךְ הֹ֠צֶן רֶ֤כֶב וְ⁠גַלְגַּל֙ וּ⁠בִ⁠קְהַ֣ל עַמִּ֔ים צִנָּ֤ה וּ⁠מָגֵן֙ וְ⁠קוֹבַ֔ע יָשִׂ֥ימוּ עָלַ֖יִ⁠ךְ סָבִ֑יב וְ⁠נָתַתִּ֤י לִ⁠פְנֵי⁠הֶם֙ מִשְׁפָּ֔ט וּ⁠שְׁפָט֖וּ⁠ךְ בְּ⁠מִשְׁפְּטֵי⁠הֶֽם׃","ẇ⁠bá֣ʼẇ ʻála֡yi⁠kĕ hò֠ẕen re֤keb wĕ⁠galĕgȧl֙ ẇ⁠bi⁠qĕha֣l ʻami̇֔ym ẕiná֤̇h ẇ⁠mágén֙ wĕ⁠qwòba֔ʻ yáşî֥ymẇ ʻála֖yi⁠kĕ sábi֑yb wĕ⁠náţaţi֤̇y li⁠pĕnéy⁠hem֙ mişĕ̌pá̇֔t ẇ⁠şĕ̌pát֖ẇ⁠kĕ bĕ̇⁠mişĕ̌pĕ̇téy⁠heֽm׃"],[23,25,"וְ⁠נָתַתִּ֨י קִנְאָתִ֜⁠י בָּ֗⁠ךְ וְ⁠עָשׂ֤וּ אוֹתָ⁠ךְ֙ בְּ⁠חֵמָ֔ה אַפֵּ֤⁠ךְ וְ⁠אָזְנַ֨יִ⁠ךְ֙ יָסִ֔ירוּ וְ⁠אַחֲרִיתֵ֖⁠ךְ בַּ⁠חֶ֣רֶב תִּפּ֑וֹל הֵ֗מָּה בָּנַ֤יִ⁠ךְ וּ⁠בְנוֹתַ֨יִ⁠ךְ֙ יִקָּ֔חוּ וְ⁠אַחֲרִיתֵ֖⁠ךְ תֵּאָכֵ֥ל בָּ⁠אֵֽשׁ׃","wĕ⁠náţaţi̇֨y qinĕʼáţi֜⁠y bá̇֗⁠kĕ wĕ⁠ʻáş֤̂ẇ ʼwòţá⁠kĕ֙ bĕ̇⁠ẖémá֔h ʼapé֤̇⁠kĕ wĕ⁠ʼázĕna֨yi⁠kĕ֙ yási֔yrẇ wĕ⁠ʼaẖàriyţé֖⁠kĕ bȧ⁠ẖe֣reb ţi̇ṗ֑wòl hé֗má̇h bá̇na֤yi⁠kĕ ẇ⁠bĕnwòţa֨yi⁠kĕ֙ yiqá̇֔ẖẇ wĕ⁠ʼaẖàriyţé֖⁠kĕ ţé̇ʼáké֥l bá̇⁠ʼéֽş̌׃"],[23,26,"וְ⁠הִפְשִׁיט֖וּ⁠ךְ אֶת־בְּגָדָ֑יִ⁠ךְ וְ⁠לָקְח֖וּ כְּלֵ֥י תִפְאַרְתֵּֽ⁠ךְ׃","wĕ⁠hipĕşǐyt֖ẇ⁠kĕ ʼeţ-bĕ̇gádá֑yi⁠kĕ wĕ⁠láqĕẖ֖ẇ kĕ̇lé֥y ţipĕʼarĕţéֽ̇⁠kĕ׃"],[23,27,"וְ⁠הִשְׁבַּתִּ֤י זִמָּתֵ⁠ךְ֙ מִמֵּ֔⁠ךְ וְ⁠אֶת־זְנוּתֵ֖⁠ךְ מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם וְ⁠לֹֽא־תִשְׂאִ֤י עֵינַ֨יִ⁠ךְ֙ אֲלֵי⁠הֶ֔ם וּ⁠מִצְרַ֖יִם לֹ֥א תִזְכְּרִי־עֽוֹד׃ס","wĕ⁠hişĕ̌bȧţi֤̇y zimá̇ţé⁠kĕ֙ mimé̇֔⁠kĕ wĕ⁠ʼeţ-zĕnẇţé֖⁠kĕ mé⁠ʼe֣reẕ miẕĕrá֑yim wĕ⁠lòֽʼ-ţişĕ̂ʼi֤y ʻéyna֨yi⁠kĕ֙ ʼàléy⁠he֔m ẇ⁠miẕĕra֖yim lò֥ʼ ţizĕkĕ̇riy-ʻֽwòd׃s"],[23,28,"כִּ֣י כֹ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִי֙ נֹֽתְנָ֔⁠ךְ בְּ⁠יַ֖ד אֲשֶׁ֣ר שָׂנֵ֑את בְּ⁠יַ֛ד אֲשֶׁר־נָקְעָ֥ה נַפְשֵׁ֖⁠ךְ מֵ⁠הֶֽם׃","ki֣̇y kò֤h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠niy֙ nòֽţĕná֔⁠kĕ bĕ̇⁠ya֖d ʼàşě֣r şá̂né֑ʼţ bĕ̇⁠ya֛d ʼàşěr-náqĕʻá֥h napĕşé֖̌⁠kĕ mé⁠heֽm׃"],[23,29,"וְ⁠עָשׂ֨וּ אוֹתָ֜⁠ךְ בְּ⁠שִׂנְאָ֗ה וְ⁠לָקְחוּ֙ כָּל־יְגִיעֵ֔⁠ךְ וַ⁠עֲזָב֖וּ⁠ךְ עֵירֹ֣ם וְ⁠עֶרְיָ֑ה וְ⁠נִגְלָה֙ עֶרְוַ֣ת זְנוּנַ֔יִ⁠ךְ וְ⁠זִמָּתֵ֖⁠ךְ וְ⁠תַזְנוּתָֽיִ⁠ךְ׃","wĕ⁠ʻáş̂֨ẇ ʼwòţá֜⁠kĕ bĕ̇⁠şînĕʼá֗h wĕ⁠láqĕẖẇ֙ ká̇l-yĕgiyʻé֔⁠kĕ wa⁠ʻàzáb֖ẇ⁠kĕ ʻéyrò֣m wĕ⁠ʻerĕyá֑h wĕ⁠nigĕláh֙ ʻerĕwa֣ţ zĕnẇna֔yi⁠kĕ wĕ⁠zimá̇ţé֖⁠kĕ wĕ⁠ţazĕnẇţáֽyi⁠kĕ׃"],[23,30,"עָשֹׂ֥ה אֵ֖לֶּה לָ֑⁠ךְ בִּ⁠זְנוֹתֵ⁠ךְ֙ אַחֲרֵ֣י גוֹיִ֔ם עַ֥ל אֲשֶׁר־נִטְמֵ֖את בְּ⁠גִלּוּלֵי⁠הֶֽם׃","ʻáşò֥̂h ʼé֖lėh lá֑⁠kĕ bi̇⁠zĕnwòţé⁠kĕ֙ ʼaẖàré֣y gwòyi֔m ʻa֥l ʼàşěr-nitĕmé֖ʼţ bĕ̇⁠gil̇ẇléy⁠heֽm׃"],[23,31,"בְּ⁠דֶ֥רֶךְ אֲחוֹתֵ֖⁠ךְ הָלָ֑כְתְּ וְ⁠נָתַתִּ֥י כוֹסָ֖⁠הּ בְּ⁠יָדֵֽ⁠ךְ׃ס","bĕ̇⁠de֥rekĕ ʼàẖwòţé֖⁠kĕ hálá֑kĕţĕ̇ wĕ⁠náţaţi֥̇y kwòsá֖⁠ḣ bĕ̇⁠yádéֽ⁠kĕ׃s"],[23,32,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהֹוִ֔ה כּ֤וֹס אֲחוֹתֵ⁠ךְ֙ תִּשְׁתִּ֔י הָ⁠עֲמֻקָּ֖ה וְ⁠הָ⁠רְחָבָ֑ה תִּהְיֶ֥ה לִ⁠צְחֹ֛ק וּ⁠לְ⁠לַ֖עַג מִרְבָּ֥ה לְ⁠הָכִֽיל׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhòwi֔h k֤̇wòs ʼàẖwòţé⁠kĕ֙ ţi̇şĕ̌ţi̇֔y há⁠ʻàmuqá֖̇h wĕ⁠há⁠rĕẖábá֑h ţi̇hĕye֥h li⁠ẕĕẖò֛q ẇ⁠lĕ⁠la֖ʻag mirĕbá֥̇h lĕ⁠hákiֽyl׃"],[23,33,"שִׁכָּר֥וֹן וְ⁠יָג֖וֹן תִּמָּלֵ֑אִי כּ֚וֹס שַׁמָּ֣ה וּ⁠שְׁמָמָ֔ה כּ֖וֹס אֲחוֹתֵ֥⁠ךְ שֹׁמְרֽוֹן׃","şǐká̇r֥wòn wĕ⁠yág֖wòn ţi̇má̇lé֑ʼiy k֚̇wòs şǎmá֣̇h ẇ⁠şĕ̌mámá֔h k֖̇wòs ʼàẖwòţé֥⁠kĕ şò̌mĕrֽwòn׃"],[23,34,"וְ⁠שָׁתִ֨ית אוֹתָ֜⁠הּ וּ⁠מָצִ֗ית וְ⁠אֶת־חֲרָשֶׂ֛י⁠הָ תְּגָרֵ֖מִי וְ⁠שָׁדַ֣יִ⁠ךְ תְּנַתֵּ֑קִי כִּ֚י אֲנִ֣י דִבַּ֔רְתִּי נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","wĕ⁠şá̌ţi֨yţ ʼwòţá֜⁠ḣ ẇ⁠máẕi֗yţ wĕ⁠ʼeţ-ẖàráşê֛y⁠há ţĕ̇gáré֖miy wĕ⁠şá̌da֣yi⁠kĕ ţĕ̇naţé֑̇qiy ki֚̇y ʼàni֣y dibȧ֔rĕţi̇y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[23,35,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה יַ֚עַן שָׁכַ֣חַתְּ אוֹתִ֔⁠י וַ⁠תַּשְׁלִ֥יכִי אוֹתִ֖⁠י אַחֲרֵ֣י גַוֵּ֑⁠ךְ וְ⁠גַם־אַ֛תְּ שְׂאִ֥י זִמָּתֵ֖⁠ךְ וְ⁠אֶת־תַּזְנוּתָֽיִ⁠ךְ׃ס","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ya֚ʻan şá̌ka֣ẖaţĕ̇ ʼwòţi֔⁠y wa⁠ţȧşĕ̌li֥ykiy ʼwòţi֖⁠y ʼaẖàré֣y gawé֑̇⁠kĕ wĕ⁠gam-ʼa֛ţĕ̇ şĕ̂ʼi֥y zimá̇ţé֖⁠kĕ wĕ⁠ʼeţ-ţȧzĕnẇţáֽyi⁠kĕ׃s"],[23,36,"וַ⁠יֹּ֤אמֶר יְהוָה֙ אֵלַ֔⁠י בֶּן־אָדָ֕ם הֲ⁠תִשְׁפּ֥וֹט אֶֽת־אָהֳלָ֖ה וְ⁠אֶת־אָהֳלִיבָ֑ה וְ⁠הַגֵּ֣ד לָ⁠הֶ֔ן אֵ֖ת תוֹעֲבוֹתֵי⁠הֶֽן׃","wa⁠yò֤̇ʼmer yĕhwáh֙ ʼéla֔⁠y bėn-ʼádá֕m hà⁠ţişĕ̌ṗ֥wòt ʼeֽţ-ʼáholá֖h wĕ⁠ʼeţ-ʼáholiybá֑h wĕ⁠hagé֣̇d lá⁠he֔n ʼé֖ţ ţwòʻàbwòţéy⁠heֽn׃"],[23,37,"כִּ֣י נִאֵ֗פוּ וְ⁠דָם֙ בִּֽ⁠ידֵי⁠הֶ֔ן וְ⁠אֶת־גִּלּֽוּלֵי⁠הֶ֖ן נִאֵ֑פוּ וְ⁠גַ֤ם אֶת־בְּנֵי⁠הֶן֙ אֲשֶׁ֣ר יָֽלְדוּ־לִ֔⁠י הֶעֱבִ֥ירוּ לָ⁠הֶ֖ם לְ⁠אָכְלָֽה׃","ki֣̇y niʼé֗pẇ wĕ⁠dám֙ biֽ̇⁠ydéy⁠he֔n wĕ⁠ʼeţ-gi̇lֽ̇ẇléy⁠he֖n niʼé֑pẇ wĕ⁠ga֤m ʼeţ-bĕ̇néy⁠hen֙ ʼàşě֣r yáֽlĕdẇ-li֔⁠y heʻèbi֥yrẇ lá⁠he֖m lĕ⁠ʼákĕláֽh׃"],[23,38,"ע֥וֹד זֹ֖את עָ֣שׂוּ לִ֑⁠י טִמְּא֤וּ אֶת־מִקְדָּשִׁ⁠י֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא וְ⁠אֶת־שַׁבְּתוֹתַ֖⁠י חִלֵּֽלוּ׃","ʻ֥wòd zò֖ʼţ ʻá֣ş̂ẇ li֑⁠y timĕ̇ʼ֤ẇ ʼeţ-miqĕdá̇şǐ⁠y֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ wĕ⁠ʼeţ-şǎbĕ̇ţwòţa֖⁠y ẖiléֽ̇lẇ׃"],[23,39,"וּֽ⁠בְ⁠שַׁחֲטָ֤⁠ם אֶת־בְּנֵי⁠הֶם֙ לְ⁠גִלּ֣וּלֵי⁠הֶ֔ם וַ⁠יָּבֹ֧אוּ אֶל־מִקְדָּשִׁ֛⁠י בַּ⁠יּ֥וֹם הַ⁠ה֖וּא לְ⁠חַלְּל֑⁠וֹ וְ⁠הִנֵּה־כֹ֥ה עָשׂ֖וּ בְּ⁠ת֥וֹךְ בֵּיתִֽ⁠י׃","ẇֽ⁠bĕ⁠şǎẖàtá֤⁠m ʼeţ-bĕ̇néy⁠hem֙ lĕ⁠gil֣̇ẇléy⁠he֔m wa⁠yá̇bò֧ʼẇ ʼel-miqĕdá̇şǐ֛⁠y bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ lĕ⁠ẖalĕ̇l֑⁠wò wĕ⁠hiné̇h-kò֥h ʻáş֖̂ẇ bĕ̇⁠ţ֥wòkĕ bé̇yţiֽ⁠y׃"],[23,40,"וְ⁠אַ֗ף כִּ֤י תִשְׁלַ֨חְנָה֙ לַֽ⁠אֲנָשִׁ֔ים בָּאִ֖ים מִ⁠מֶּרְחָ֑ק אֲשֶׁ֨ר מַלְאָ֜ךְ שָׁל֤וּחַ אֲלֵי⁠הֶם֙ וְ⁠הִנֵּה־בָ֔אוּ לַ⁠אֲשֶׁ֥ר רָחַ֛צְתְּ כָּחַ֥לְתְּ עֵינַ֖יִ⁠ךְ וְ⁠עָ֥דִית עֶֽדִי׃","wĕ⁠ʼa֗p ki֤̇y ţişĕ̌la֨ẖĕnáh֙ laֽ⁠ʼànáşǐ֔ym bá̇ʼi֖ym mi⁠mėrĕẖá֑q ʼàşě֨r malĕʼá֜kĕ şá̌l֤ẇẖa ʼàléy⁠hem֙ wĕ⁠hiné̇h-bá֔ʼẇ la⁠ʼàşě֥r ráẖa֛ẕĕţĕ̇ ká̇ẖa֥lĕţĕ̇ ʻéyna֖yi⁠kĕ wĕ⁠ʻá֥diyţ ʻeֽdiy׃"],[23,41,"וְ⁠יָשַׁבְתְּ֙ עַל־מִטָּ֣ה כְבוּדָּ֔ה וְ⁠שֻׁלְחָ֥ן עָר֖וּךְ לְ⁠פָנֶ֑י⁠הָ וּ⁠קְטָרְתִּ֥⁠י וְ⁠שַׁמְנִ֖⁠י שַׂ֥מְתְּ עָלֶֽי⁠הָ׃","wĕ⁠yáşǎbĕţĕ̇֙ ʻal-mitá֣̇h kĕbẇdá̇֔h wĕ⁠şǔlĕẖá֥n ʻár֖ẇkĕ lĕ⁠páne֑y⁠há ẇ⁠qĕtárĕţi֥̇⁠y wĕ⁠şǎmĕni֖⁠y şâ֥mĕţĕ̇ ʻáleֽy⁠há׃"],[23,42,"וְ⁠ק֣וֹל הָמוֹן֮ שָׁלֵ֣ו בָ⁠הּ֒ וְ⁠אֶל־אֲנָשִׁים֙ מֵ⁠רֹ֣ב אָדָ֔ם מוּבָאִ֥ים סובאים מִ⁠מִּדְבָּ֑ר וַֽ⁠יִּתְּנ֤וּ צְמִידִים֙ אֶל־יְדֵי⁠הֶ֔ן וַ⁠עֲטֶ֥רֶת תִּפְאֶ֖רֶת עַל־רָאשֵׁי⁠הֶֽן׃","wĕ⁠q֣wòl hámwòn֮ şá̌lé֣w bá⁠ḣ֒ wĕ⁠ʼel-ʼànáşǐym֙ mé⁠rò֣b ʼádá֔m mẇbáʼi֥ym swbʼym mi⁠mi̇dĕbá֑̇r waֽ⁠yi̇ţĕ̇n֤ẇ ẕĕmiydiym֙ ʼel-yĕdéy⁠he֔n wa⁠ʻàte֥reţ ţi̇pĕʼe֖reţ ʻal-ráʼşé̌y⁠heֽn׃"],[23,43,"וָ⁠אֹמַ֕ר לַ⁠בָּלָ֖ה נִֽאוּפִ֑ים עת יזנה תַזְנוּתֶ֖⁠הָ וָ⁠הִֽיא׃","wá⁠ʼòma֕r la⁠bá̇lá֖h niֽʼẇpi֑ym ʻţ yznh ţazĕnẇţe֖⁠há wá⁠hiֽyʼ׃"],[23,44,"וַ⁠יָּב֣וֹא אֵלֶ֔י⁠הָ כְּ⁠ב֖וֹא אֶל־אִשָּׁ֣ה זוֹנָ֑ה כֵּ֣ן בָּ֗אוּ אֶֽל־אָֽהֳלָה֙ וְ⁠אֶל־אָ֣הֳלִיבָ֔ה אִשֹּׁ֖ת הַ⁠זִּמָּֽה׃","wa⁠yá̇b֣wòʼ ʼéle֔y⁠há kĕ̇⁠b֖wòʼ ʼel-ʼişá֣̇̌h zwòná֑h ké֣̇n bá̇֗ʼẇ ʼeֽl-ʼáֽholáh֙ wĕ⁠ʼel-ʼá֣holiybá֔h ʼişò֖̇̌ţ ha⁠zi̇máֽ̇h׃"],[23,45,"וַ⁠אֲנָשִׁ֣ים צַדִּיקִ֗ם הֵ֚מָּה יִשְׁפְּט֣וּ אֽוֹתְ⁠הֶ֔ם מִשְׁפַּט֙ נֹֽאֲפ֔וֹת וּ⁠מִשְׁפַּ֖ט שֹׁפְכ֣וֹת דָּ֑ם כִּ֤י נֹֽאֲפֹת֙ הֵ֔נָּה וְ⁠דָ֖ם בִּֽ⁠ידֵי⁠הֶֽן׃ס","wa⁠ʼànáşǐ֣ym ẕadi̇yqi֗m hé֚má̇h yişĕ̌pĕ̇t֣ẇ ʼֽwòţĕ⁠he֔m mişĕ̌pȧt֙ nòֽʼàp֔wòţ ẇ⁠mişĕ̌pȧ֖t şò̌pĕk֣wòţ dá֑̇m ki֤̇y nòֽʼàpòţ֙ hé֔ná̇h wĕ⁠dá֖m biֽ̇⁠ydéy⁠heֽn׃s"],[23,46,"כִּ֛י כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה הַעֲלֵ֤ה עֲלֵי⁠הֶם֙ קָהָ֔ל וְ⁠נָתֹ֥ן אֶתְ⁠הֶ֖ן לְ⁠זַעֲוָ֥ה וְ⁠לָ⁠בַֽז׃","ki֛̇y kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h haʻàlé֤h ʻàléy⁠hem֙ qáhá֔l wĕ⁠náţò֥n ʼeţĕ⁠he֖n lĕ⁠zaʻàwá֥h wĕ⁠lá⁠baֽz׃"],[23,47,"וְ⁠רָגְמ֨וּ עֲלֵי⁠הֶ֥ן אֶ֨בֶן֙ קָהָ֔ל וּ⁠בָרֵ֥א אוֹתְ⁠הֶ֖ן בְּ⁠חַרְבוֹתָ֑⁠ם בְּנֵי⁠הֶ֤ם וּ⁠בְנֽוֹתֵי⁠הֶם֙ יַהֲרֹ֔גוּ וּ⁠בָתֵּי⁠הֶ֖ן בָּ⁠אֵ֥שׁ יִשְׂרֹֽפוּ׃","wĕ⁠rágĕm֨ẇ ʻàléy⁠he֥n ʼe֨ben֙ qáhá֔l ẇ⁠báré֥ʼ ʼwòţĕ⁠he֖n bĕ̇⁠ẖarĕbwòţá֑⁠m bĕ̇néy⁠he֤m ẇ⁠bĕnֽwòţéy⁠hem֙ yahàrò֔gẇ ẇ⁠báţé̇y⁠he֖n bá̇⁠ʼé֥ş̌ yişĕ̂ròֽpẇ׃"],[23,48,"וְ⁠הִשְׁבַּתִּ֥י זִמָּ֖ה מִן־הָ⁠אָ֑רֶץ וְ⁠נִֽוַּסְּרוּ֙ כָּל־הַ⁠נָּשִׁ֔ים וְ⁠לֹ֥א תַעֲשֶׂ֖ינָה כְּ⁠זִמַּתְ⁠כֶֽנָה׃","wĕ⁠hişĕ̌bȧţi֥̇y zimá֖̇h min-há⁠ʼá֑reẕ wĕ⁠niֽwȧsĕ̇rẇ֙ ká̇l-ha⁠ná̇şǐ֔ym wĕ⁠lò֥ʼ ţaʻàşê֖ynáh kĕ̇⁠zimȧţĕ⁠keֽnáh׃"],[23,49,"וְ⁠נָתְנ֤וּ זִמַּתְ⁠כֶ֨נָה֙ עֲלֵי⁠כֶ֔ן וַ⁠חֲטָאֵ֥י גִלּוּלֵי⁠כֶ֖ן תִּשֶּׂ֑אינָה וִ⁠ידַעְתֶּ֕ם כִּ֥י אֲנִ֖י אֲדֹנָ֥⁠י יְהוִֽה׃פ","wĕ⁠náţĕn֤ẇ zimȧţĕ⁠ke֨náh֙ ʻàléy⁠ke֔n wa⁠ẖàtáʼé֥y gil̇ẇléy⁠ke֖n ţi̇şė֑̂ʼynáh wi⁠ydaʻĕţė֕m ki֥̇y ʼàni֖y ʼàdòná֥⁠y yĕhwiֽh׃p"],[24,1,"וַ⁠יְהִי֩ דְבַר־יְהוָ֨ה אֵלַ֜⁠י בַּ⁠שָּׁנָ֤ה הַ⁠תְּשִׁיעִית֙ בַּ⁠חֹ֣דֶשׁ הָ⁠עֲשִׂירִ֔י בֶּ⁠עָשׂ֥וֹר לַ⁠חֹ֖דֶשׁ לֵ⁠אמֹֽר׃","wa⁠yĕhiy֩ dĕbar-yĕhwá֨h ʼéla֜⁠y bȧ⁠şá̇̌ná֤h ha⁠ţĕ̇şǐyʻiyţ֙ bȧ⁠ẖò֣deş̌ há⁠ʻàşîyri֔y bė⁠ʻáş֥̂wòr la⁠ẖò֖deş̌ lé⁠ʼmòֽr׃"],[24,2,"בֶּן־אָדָ֗ם כתוב־לְ⁠ךָ֙ אֶת־שֵׁ֣ם הַ⁠יּ֔וֹם אֶת־עֶ֖צֶם הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה סָמַ֤ךְ מֶֽלֶךְ־בָּבֶל֙ אֶל־יְר֣וּשָׁלִַ֔ם בְּ⁠עֶ֖צֶם הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","bėn-ʼádá֗m kţwb-lĕ⁠ká֙ ʼeţ-şé֣̌m ha⁠ẏ֔wòm ʼeţ-ʻe֖ẕem ha⁠ẏ֣wòm ha⁠zė֑h sáma֤kĕ meֽlekĕ-bá̇bel֙ ʼel-yĕr֣ẇşá̌lia֔m bĕ̇⁠ʻe֖ẕem ha⁠ẏ֥wòm ha⁠zėֽh׃"],[24,3,"וּ⁠מְשֹׁ֤ל אֶל־בֵּית־הַ⁠מֶּ֨רִי֙ מָשָׁ֔ל וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה שְׁפֹ֤ת הַ⁠סִּיר֙ שְׁפֹ֔ת וְ⁠גַם־יְצֹ֥ק בּ֖⁠וֹ מָֽיִם׃","ẇ⁠mĕşò֤̌l ʼel-bé̇yţ-ha⁠mė֨riy֙ máşá̌֔l wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h şĕ̌pò֤ţ ha⁠si̇yr֙ şĕ̌pò֔ţ wĕ⁠gam-yĕẕò֥q ḃ֖⁠wò máֽyim׃"],[24,4,"אֱסֹ֤ף נְתָחֶ֨י⁠הָ֙ אֵלֶ֔י⁠הָ כָּל־נֵ֥תַח ט֖וֹב יָרֵ֣ךְ וְ⁠כָתֵ֑ף מִבְחַ֥ר עֲצָמִ֖ים מַלֵּֽא׃","ʼèsò֤p nĕţáẖe֨y⁠há֙ ʼéle֔y⁠há ká̇l-né֥ţaẖ t֖wòb yáré֣kĕ wĕ⁠káţé֑p mibĕẖa֥r ʻàẕámi֖ym maléֽ̇ʼ׃"],[24,5,"מִבְחַ֤ר הַ⁠צֹּאן֙ לָק֔וֹחַ וְ⁠גַ֛ם דּ֥וּר הָ⁠עֲצָמִ֖ים תַּחְתֶּ֑י⁠הָ רַתַּ֣ח רְתָחֶ֔י⁠הָ גַּם־בָּשְׁל֥וּ עֲצָמֶ֖י⁠הָ בְּ⁠תוֹכָֽ⁠הּ׃ס","mibĕẖa֤r ha⁠ẕò̇ʼn֙ láq֔wòẖa wĕ⁠ga֛m ḋ֥ẇr há⁠ʻàẕámi֖ym ţȧẖĕţė֑y⁠há raţȧ֣ẖ rĕţáẖe֔y⁠há gȧm-bá̇şĕ̌l֥ẇ ʻàẕáme֖y⁠há bĕ̇⁠ţwòkáֽ⁠ḣ׃s"],[24,6,"לָ⁠כֵ֞ן כֹּה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהֹוִ֗ה אוֹי֮ עִ֣יר הַ⁠דָּמִים֒ סִ֚יר אֲשֶׁ֣ר חֶלְאָתָ֣⁠ה בָ֔⁠הּ וְ⁠חֶ֨לְאָתָ֔⁠הּ לֹ֥א יָצְאָ֖ה מִמֶּ֑⁠נָּה לִ⁠נְתָחֶ֤י⁠הָ לִ⁠נְתָחֶ֨י⁠הָ֙ הוֹצִיאָ֔⁠הּ לֹא־נָפַ֥ל עָלֶ֖י⁠הָ גּוֹרָֽל׃","lá⁠ké֞n kò̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhòwi֗h ʼwòy֮ ʻi֣yr ha⁠dá̇miym֒ si֚yr ʼàşě֣r ẖelĕʼáţá֣⁠h bá֔⁠ḣ wĕ⁠ẖe֨lĕʼáţá֔⁠ḣ lò֥ʼ yáẕĕʼá֖h mimė֑⁠ná̇h li⁠nĕţáẖe֤y⁠há li⁠nĕţáẖe֨y⁠há֙ hwòẕiyʼá֔⁠ḣ lòʼ-nápa֥l ʻále֖y⁠há ġwòráֽl׃"],[24,7,"כִּ֤י דָמָ⁠הּ֙ בְּ⁠תוֹכָ֣⁠הּ הָיָ֔ה עַל־צְחִ֥יחַ סֶ֖לַע שָׂמָ֑תְ⁠הוּ לֹ֤א שְׁפָכַ֨תְ⁠הוּ֙ עַל־הָ⁠אָ֔רֶץ לְ⁠כַסּ֥וֹת עָלָ֖י⁠ו עָפָֽר׃","ki֤̇y dámá⁠ḣ֙ bĕ̇⁠ţwòká֣⁠ḣ háyá֔h ʻal-ẕĕẖi֥yẖa se֖laʻ şá̂má֑ţĕ⁠hẇ lò֤ʼ şĕ̌páka֨ţĕ⁠hẇ֙ ʻal-há⁠ʼá֔reẕ lĕ⁠kaṡ֥wòţ ʻálá֖y⁠w ʻápáֽr׃"],[24,8,"לְ⁠הַעֲל֤וֹת חֵמָה֙ לִ⁠נְקֹ֣ם נָקָ֔ם נָתַ֥תִּי אֶת־דָּמָ֖⁠הּ עַל־צְחִ֣יחַ סָ֑לַע לְ⁠בִלְתִּ֖י הִכָּסֽוֹת׃פ","lĕ⁠haʻàl֤wòţ ẖémáh֙ li⁠nĕqò֣m náqá֔m náţa֥ţi̇y ʼeţ-dá̇má֖⁠ḣ ʻal-ẕĕẖi֣yẖa sá֑laʻ lĕ⁠bilĕţi֖̇y hiká̇sֽwòţ׃p"],[24,9,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה א֖וֹי עִ֣יר הַ⁠דָּמִ֑ים גַּם־אֲנִ֖י אַגְדִּ֥יל הַ⁠מְּדוּרָֽה׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ʼ֖wòy ʻi֣yr ha⁠dá̇mi֑ym gȧm-ʼàni֖y ʼagĕdi֥̇yl ha⁠mĕ̇dẇráֽh׃"],[24,10,"הַרְבֵּ֤ה הָ⁠עֵצִים֙ הַדְלֵ֣ק הָ⁠אֵ֔שׁ הָתֵ֖ם הַ⁠בָּשָׂ֑ר וְ⁠הַרְקַח֙ הַ⁠מֶּרְקָחָ֔ה וְ⁠הָ⁠עֲצָמ֖וֹת יֵחָֽרוּ׃","harĕbé֤̇h há⁠ʻéẕiym֙ hadĕlé֣q há⁠ʼé֔ş̌ háţé֖m ha⁠bá̇şá֑̂r wĕ⁠harĕqaẖ֙ ha⁠mėrĕqáẖá֔h wĕ⁠há⁠ʻàẕám֖wòţ yéẖáֽrẇ׃"],[24,11,"וְ⁠הַעֲמִידֶ֥⁠הָ עַל־גֶּחָלֶ֖י⁠הָ רֵקָ֑ה לְמַ֨עַן תֵּחַ֜ם וְ⁠חָ֣רָה נְחֻשְׁתָּ֗⁠הּ וְ⁠נִתְּכָ֤ה בְ⁠תוֹכָ⁠הּ֙ טֻמְאָתָ֔⁠הּ תִּתֻּ֖ם חֶלְאָתָֽ⁠הּ׃","wĕ⁠haʻàmiyde֥⁠há ʻal-gėẖále֖y⁠há réqá֑h lĕma֨ʻan ţé̇ẖa֜m wĕ⁠ẖá֣ráh nĕẖuşĕ̌ţá̇֗⁠ḣ wĕ⁠niţĕ̇ká֤h bĕ⁠ţwòká⁠ḣ֙ tumĕʼáţá֔⁠ḣ ţi̇ţu֖̇m ẖelĕʼáţáֽ⁠ḣ׃"],[24,12,"תְּאֻנִ֖ים הֶלְאָ֑ת וְ⁠לֹֽא־תֵצֵ֤א מִמֶּ֨⁠נָּה֙ רַבַּ֣ת חֶלְאָתָ֔⁠הּ בְּ⁠אֵ֖שׁ חֶלְאָתָֽ⁠הּ׃","ţĕ̇ʼuni֖ym helĕʼá֑ţ wĕ⁠lòֽʼ-ţéẕé֤ʼ mimė֨⁠ná̇h֙ rabȧ֣ţ ẖelĕʼáţá֔⁠ḣ bĕ̇⁠ʼé֖ş̌ ẖelĕʼáţáֽ⁠ḣ׃"],[24,13,"בְּ⁠טֻמְאָתֵ֖⁠ךְ זִמָּ֑ה יַ֤עַן טִֽהַרְתִּי⁠ךְ֙ וְ⁠לֹ֣א טָהַ֔רְתְּ מִ⁠טֻּמְאָתֵ⁠ךְ֙ לֹ֣א תִטְהֲרִי־ע֔וֹד עַד־הֲנִיחִ֥⁠י אֶת־חֲמָתִ֖⁠י בָּֽ⁠ךְ׃","bĕ̇⁠tumĕʼáţé֖⁠kĕ zimá֑̇h ya֤ʻan tiֽharĕţi̇y⁠kĕ֙ wĕ⁠lò֣ʼ táha֔rĕţĕ̇ mi⁠tu̇mĕʼáţé⁠kĕ֙ lò֣ʼ ţitĕhàriy-ʻ֔wòd ʻad-hàniyẖi֥⁠y ʼeţ-ẖàmáţi֖⁠y báֽ̇⁠kĕ׃"],[24,14,"אֲנִ֨י יְהוָ֤ה דִּבַּ֨רְתִּי֙ בָּאָ֣ה וְ⁠עָשִׂ֔יתִי לֹֽא־אֶפְרַ֥ע וְ⁠לֹא־אָח֖וּס וְ⁠לֹ֣א אֶנָּחֵ֑ם כִּ⁠דְרָכַ֤יִ⁠ךְ וְ⁠כַ⁠עֲלִילוֹתַ֨יִ⁠ךְ֙ שְׁפָט֔וּ⁠ךְ נְאֻ֖ם אֲדֹנָ֥⁠י יְהֹוִֽה׃פ","ʼàni֨y yĕhwá֤h di̇bȧ֨rĕţi̇y֙ bá̇ʼá֣h wĕ⁠ʻáşî֔yţiy lòֽʼ-ʼepĕra֥ʻ wĕ⁠lòʼ-ʼáẖ֖ẇs wĕ⁠lò֣ʼ ʼená̇ẖé֑m ki̇⁠dĕráka֤yi⁠kĕ wĕ⁠ka⁠ʻàliylwòţa֨yi⁠kĕ֙ şĕ̌pát֔ẇ⁠kĕ nĕʼu֖m ʼàdòná֥⁠y yĕhòwiֽh׃p"],[24,15,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[24,16,"בֶּן־אָדָ֕ם הִנְ⁠נִ֨י לֹקֵ֧חַ מִמְּ⁠ךָ֛ אֶת־מַחְמַ֥ד עֵינֶ֖י⁠ךָ בְּ⁠מַגֵּפָ֑ה וְ⁠לֹ֤א תִסְפֹּד֙ וְ⁠לֹ֣א תִבְכֶּ֔ה וְ⁠ל֥וֹא תָב֖וֹא דִּמְעָתֶֽ⁠ךָ׃","bėn-ʼádá֕m hinĕ⁠ni֨y lòqé֧ẖa mimĕ̇⁠ká֛ ʼeţ-maẖĕma֥d ʻéyne֖y⁠ká bĕ̇⁠magé̇pá֑h wĕ⁠lò֤ʼ ţisĕpò̇d֙ wĕ⁠lò֣ʼ ţibĕkė֔h wĕ⁠l֥wòʼ ţáb֖wòʼ di̇mĕʻáţeֽ⁠ká׃"],[24,17,"הֵאָנֵ֣ק ׀ דֹּ֗ם מֵתִים֙ אֵ֣בֶל לֹֽא־תַֽעֲשֶׂ֔ה פְאֵֽרְ⁠ךָ֙ חֲב֣וֹשׁ עָלֶ֔י⁠ךָ וּ⁠נְעָלֶ֖י⁠ךָ תָּשִׂ֣ים בְּ⁠רַגְלֶ֑י⁠ךָ וְ⁠לֹ֤א תַעְטֶה֙ עַל־שָׂפָ֔ם וְ⁠לֶ֥חֶם אֲנָשִׁ֖ים לֹ֥א תֹאכֵֽל׃","héʼáné֣q ׀ dò̇֗m méţiym֙ ʼé֣bel lòֽʼ-ţaֽʻàşê֔h pĕʼéֽrĕ⁠ká֙ ẖàb֣wòş̌ ʻále֔y⁠ká ẇ⁠nĕʻále֖y⁠ká ţá̇şî֣ym bĕ̇⁠ragĕle֑y⁠ká wĕ⁠lò֤ʼ ţaʻĕteh֙ ʻal-şá̂pá֔m wĕ⁠le֥ẖem ʼànáşǐ֖ym lò֥ʼ ţòʼkéֽl׃"],[24,18,"וָ⁠אֲדַבֵּ֤ר אֶל־הָ⁠עָם֙ בַּ⁠בֹּ֔קֶר וַ⁠תָּ֥מָת אִשְׁתִּ֖⁠י בָּ⁠עָ֑רֶב וָ⁠אַ֥עַשׂ בַּ⁠בֹּ֖קֶר כַּ⁠אֲשֶׁ֥ר צֻוֵּֽיתִי׃","wá⁠ʼàdabé֤̇r ʼel-há⁠ʻám֙ bȧ⁠bò̇֔qer wa⁠ţá֥̇máţ ʼişĕ̌ţi֖̇⁠y bá̇⁠ʻá֑reb wá⁠ʼa֥ʻaş̂ bȧ⁠bò֖̇qer kȧ⁠ʼàşě֥r ẕuwéֽ̇yţiy׃"],[24,19,"וַ⁠יֹּאמְר֥וּ אֵלַ֖⁠י הָ⁠עָ֑ם הֲ⁠לֹֽא־תַגִּ֥יד לָ֨⁠נוּ֙ מָה־אֵ֣לֶּה לָּ֔⁠נוּ כִּ֥י אַתָּ֖ה עֹשֶֽׂה׃","wa⁠yò̇ʼmĕr֥ẇ ʼéla֖⁠y há⁠ʻá֑m hà⁠lòֽʼ-ţagi֥̇yd lá֨⁠nẇ֙ máh-ʼé֣lėh lá̇֔⁠nẇ ki֥̇y ʼaţá֖̇h ʻòşêֽh׃"],[24,20,"וָ⁠אֹמַ֖ר אֲלֵי⁠הֶ֑ם דְּבַ֨ר־יְהוָ֔ה הָיָ֥ה אֵלַ֖⁠י לֵ⁠אמֹֽר׃","wá⁠ʼòma֖r ʼàléy⁠he֑m dĕ̇ba֨r-yĕhwá֔h háyá֥h ʼéla֖⁠y lé⁠ʼmòֽr׃"],[24,21,"אֱמֹ֣ר ׀ לְ⁠בֵ֣ית יִשְׂרָאֵ֗ל כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ הִנְ⁠נִ֨י מְחַלֵּ֤ל אֶת־מִקְדָּשִׁ⁠י֙ גְּא֣וֹן עֻזְּ⁠כֶ֔ם מַחְמַ֥ד עֵֽינֵי⁠כֶ֖ם וּ⁠מַחְמַ֣ל נַפְשְׁ⁠כֶ֑ם וּ⁠בְנֵי⁠כֶ֧ם וּ⁠בְנֽוֹתֵי⁠כֶ֛ם אֲשֶׁ֥ר עֲזַבְתֶּ֖ם בַּ⁠חֶ֥רֶב יִפֹּֽלוּ׃","ʼèmò֣r ׀ lĕ⁠bé֣yţ yişĕ̂ráʼé֗l kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ hinĕ⁠ni֨y mĕẖalé֤̇l ʼeţ-miqĕdá̇şǐ⁠y֙ gĕ̇ʼ֣wòn ʻuzĕ̇⁠ke֔m maẖĕma֥d ʻéֽynéy⁠ke֖m ẇ⁠maẖĕma֣l napĕşĕ̌⁠ke֑m ẇ⁠bĕnéy⁠ke֧m ẇ⁠bĕnֽwòţéy⁠ke֛m ʼàşě֥r ʻàzabĕţė֖m bȧ⁠ẖe֥reb yipòֽ̇lẇ׃"],[24,22,"וַ⁠עֲשִׂיתֶ֖ם כַּ⁠אֲשֶׁ֣ר עָשִׂ֑יתִי עַל־שָׂפָם֙ לֹ֣א תַעְט֔וּ וְ⁠לֶ֥חֶם אֲנָשִׁ֖ים לֹ֥א תֹאכֵֽלוּ׃","wa⁠ʻàşîyţe֖m kȧ⁠ʼàşě֣r ʻáşî֑yţiy ʻal-şá̂pám֙ lò֣ʼ ţaʻĕt֔ẇ wĕ⁠le֥ẖem ʼànáşǐ֖ym lò֥ʼ ţòʼkéֽlẇ׃"],[24,23,"וּ⁠פְאֵרֵ⁠כֶ֣ם עַל־רָאשֵׁי⁠כֶ֗ם וְ⁠נַֽעֲלֵי⁠כֶם֙ בְּ⁠רַגְלֵי⁠כֶ֔ם לֹ֥א תִסְפְּד֖וּ וְ⁠לֹ֣א תִבְכּ֑וּ וּ⁠נְמַקֹּתֶם֙ בַּ⁠עֲוֺנֹ֣תֵי⁠כֶ֔ם וּ⁠נְהַמְתֶּ֖ם אִ֥ישׁ אֶל־אָחִֽי⁠ו׃","ẇ⁠pĕʼéré⁠ke֣m ʻal-ráʼşé̌y⁠ke֗m wĕ⁠naֽʻàléy⁠kem֙ bĕ̇⁠ragĕléy⁠ke֔m lò֥ʼ ţisĕpĕ̇d֖ẇ wĕ⁠lò֣ʼ ţibĕk֑̇ẇ ẇ⁠nĕmaqò̇ţem֙ bȧ⁠ʻàwֺnò֣ţéy⁠ke֔m ẇ⁠nĕhamĕţė֖m ʼi֥yş̌ ʼel-ʼáẖiֽy⁠w׃"],[24,24,"וְ⁠הָיָ֨ה יְחֶזְקֵ֤אל לָ⁠כֶם֙ לְ⁠מוֹפֵ֔ת כְּ⁠כֹ֥ל אֲשֶׁר־עָשָׂ֖ה תַּעֲשׂ֑וּ בְּ⁠בֹאָ֕⁠הּ וִֽ⁠ידַעְתֶּ֕ם כִּ֥י אֲנִ֖י אֲדֹנָ֥⁠י יְהוִֽה׃ס","wĕ⁠háyá֨h yĕẖezĕqé֤ʼl lá⁠kem֙ lĕ⁠mwòpé֔ţ kĕ̇⁠kò֥l ʼàşěr-ʻáşá֖̂h ţȧʻàş֑̂ẇ bĕ̇⁠bòʼá֕⁠ḣ wiֽ⁠ydaʻĕţė֕m ki֥̇y ʼàni֖y ʼàdòná֥⁠y yĕhwiֽh׃s"],[24,25,"וְ⁠אַתָּ֣ה בֶן־אָדָ֔ם הֲ⁠ל֗וֹא בְּ⁠י֨וֹם קַחְתִּ֤⁠י מֵ⁠הֶם֙ אֶת־מָ֣עוּזָּ֔⁠ם מְשׂ֖וֹשׂ תִּפְאַרְתָּ֑⁠ם אֶת־מַחְמַ֤ד עֵֽינֵי⁠הֶם֙ וְ⁠אֶת־מַשָּׂ֣א נַפְשָׁ֔⁠ם בְּנֵי⁠הֶ֖ם וּ⁠בְנוֹתֵי⁠הֶֽם׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֔m hà⁠l֗wòʼ bĕ̇⁠y֨wòm qaẖĕţi֤̇⁠y mé⁠hem֙ ʼeţ-má֣ʻẇzá̇֔⁠m mĕş֖̂wòş̂ ţi̇pĕʼarĕţá֑̇⁠m ʼeţ-maẖĕma֤d ʻéֽynéy⁠hem֙ wĕ⁠ʼeţ-maşá֣̇̂ʼ napĕşá̌֔⁠m bĕ̇néy⁠he֖m ẇ⁠bĕnwòţéy⁠heֽm׃"],[24,26,"בַּ⁠יּ֣וֹם הַ⁠ה֔וּא יָב֥וֹא הַ⁠פָּלִ֖יט אֵלֶ֑י⁠ךָ לְ⁠הַשְׁמָע֖וּת אָזְנָֽיִם׃","bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ yáb֥wòʼ ha⁠pá̇li֖yt ʼéle֑y⁠ká lĕ⁠haşĕ̌máʻ֖ẇţ ʼázĕnáֽyim׃"],[24,27,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִפָּ֤תַח פִּ֨י⁠ךָ֙ אֶת־הַ⁠פָּלִ֔יט וּ⁠תְדַבֵּ֕ר וְ⁠לֹ֥א תֵֽאָלֵ֖ם ע֑וֹד וְ⁠הָיִ֤יתָ לָ⁠הֶם֙ לְ⁠מוֹפֵ֔ת וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃ס","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yipá֤̇ţaẖ pi̇֨y⁠ká֙ ʼeţ-ha⁠pá̇li֔yt ẇ⁠ţĕdabé̇֕r wĕ⁠lò֥ʼ ţéֽʼálé֖m ʻ֑wòd wĕ⁠háyi֤yţá lá⁠hem֙ lĕ⁠mwòpé֔ţ wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃s"],[25,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[25,2,"בֶּן־אָדָ֕ם שִׂ֥ים פָּנֶ֖י⁠ךָ אֶל־בְּנֵ֣י עַמּ֑וֹן וְ⁠הִנָּבֵ֖א עֲלֵי⁠הֶֽם׃","bėn-ʼádá֕m şî֥ym pá̇ne֖y⁠ká ʼel-bĕ̇né֣y ʻaṁ֑wòn wĕ⁠hiná̇bé֖ʼ ʻàléy⁠heֽm׃"],[25,3,"וְ⁠אָֽמַרְתָּ֙ לִ⁠בְנֵ֣י עַמּ֔וֹן שִׁמְע֖וּ דְּבַר־אֲדֹנָ֣⁠י יְהוִ֑ה כֹּה־אָמַ֣ר אֲדֹנָ֣⁠י יְהוִ֡ה יַעַן֩ אָמְרֵ֨⁠ךְ הֶאָ֜ח אֶל־מִקְדָּשִׁ֣⁠י כִֽי־נִחָ֗ל וְ⁠אֶל־אַדְמַ֤ת יִשְׂרָאֵל֙ כִּ֣י נָשַׁ֔מָּה וְ⁠אֶל־בֵּ֣ית יְהוּדָ֔ה כִּ֥י הָלְכ֖וּ בַּ⁠גּוֹלָֽה׃","wĕ⁠ʼáֽmarĕţá̇֙ li⁠bĕné֣y ʻaṁ֔wòn şǐmĕʻ֖ẇ dĕ̇bar-ʼàdòná֣⁠y yĕhwi֑h kò̇h-ʼáma֣r ʼàdòná֣⁠y yĕhwi֡h yaʻan֩ ʼámĕré֨⁠kĕ heʼá֜ẖ ʼel-miqĕdá̇şǐ֣⁠y kiֽy-niẖá֗l wĕ⁠ʼel-ʼadĕma֤ţ yişĕ̂ráʼél֙ ki֣̇y náşǎ֔má̇h wĕ⁠ʼel-bé֣̇yţ yĕhẇdá֔h ki֥̇y hálĕk֖ẇ bȧ⁠ġwòláֽh׃"],[25,4,"לָ⁠כֵ֡ן הִנְ⁠נִי֩ נֹתְנָ֨⁠ךְ לִ⁠בְנֵי־קֶ֜דֶם לְ⁠מֽוֹרָשָׁ֗ה וְ⁠יִשְּׁב֤וּ טִירֽוֹתֵי⁠הֶם֙ בָּ֔⁠ךְ וְ⁠נָ֥תְנוּ בָ֖⁠ךְ מִשְׁכְּנֵי⁠הֶ֑ם הֵ֚מָּה יֹאכְל֣וּ פִרְיֵ֔⁠ךְ וְ⁠הֵ֖מָּה יִשְׁתּ֥וּ חֲלָבֵֽ⁠ךְ׃","lá⁠ké֡n hinĕ⁠niy֩ nòţĕná֨⁠kĕ li⁠bĕnéy-qe֜dem lĕ⁠mֽwòráşá̌֗h wĕ⁠yişĕ̇̌b֤ẇ tiyrֽwòţéy⁠hem֙ bá̇֔⁠kĕ wĕ⁠ná֥ţĕnẇ bá֖⁠kĕ mişĕ̌kĕ̇néy⁠he֑m hé֚má̇h yòʼkĕl֣ẇ pirĕyé֔⁠kĕ wĕ⁠hé֖má̇h yişĕ̌ţ֥̇ẇ ẖàlábéֽ⁠kĕ׃"],[25,5,"וְ⁠נָתַתִּ֤י אֶת־רַבָּה֙ לִ⁠נְוֵ֣ה גְמַלִּ֔ים וְ⁠אֶת־בְּנֵ֥י עַמּ֖וֹן לְ⁠מִרְבַּץ־צֹ֑אן וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃ס","wĕ⁠náţaţi֤̇y ʼeţ-rabá̇h֙ li⁠nĕwé֣h gĕmali̇֔ym wĕ⁠ʼeţ-bĕ̇né֥y ʻaṁ֖wòn lĕ⁠mirĕbȧẕ-ẕò֑ʼn wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃s"],[25,6,"כִּ֣י כֹ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה יַ֚עַן מַחְאֲ⁠ךָ֣ יָ֔ד וְ⁠רַקְעֲ⁠ךָ֖ בְּ⁠רָ֑גֶל וַ⁠תִּשְׂמַ֤ח בְּ⁠כָל־שָֽׁאטְ⁠ךָ֙ בְּ⁠נֶ֔פֶשׁ אֶל־אַדְמַ֖ת יִשְׂרָאֵֽל׃","ki֣̇y kò֤h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ya֚ʻan maẖĕʼà⁠ká֣ yá֔d wĕ⁠raqĕʻà⁠ká֖ bĕ̇⁠rá֑gel wa⁠ţi̇şĕ̂ma֤ẖ bĕ̇⁠kál-şáֽ̌ʼtĕ⁠ká֙ bĕ̇⁠ne֔peş̌ ʼel-ʼadĕma֖ţ yişĕ̂ráʼéֽl׃"],[25,7,"לָ⁠כֵ֡ן הִנְ⁠נִי֩ נָטִ֨יתִי אֶת־יָדִ֜⁠י עָלֶ֗י⁠ךָ וּ⁠נְתַתִּ֤י⁠ךָֽ־ל⁠בג לַ⁠גּוֹיִ֔ם וְ⁠הִכְרַתִּ֨י⁠ךָ֙ מִן־הָ֣⁠עַמִּ֔ים וְ⁠הַאֲבַדְתִּ֖י⁠ךָ מִן־הָ⁠אֲרָצ֑וֹת אַשְׁמִ֣ידְ⁠ךָ֔ וְ⁠יָדַעְתָּ֖ כִּֽי־אֲנִ֥י יְהוָֽה׃ס","lá⁠ké֡n hinĕ⁠niy֩ náti֨yţiy ʼeţ-yádi֜⁠y ʻále֗y⁠ká ẇ⁠nĕţaţi֤̇y⁠káֽ-l⁠bg la⁠ġwòyi֔m wĕ⁠hikĕraţi̇֨y⁠ká֙ min-há֣⁠ʻami̇֔ym wĕ⁠haʼàbadĕţi֖̇y⁠ká min-há⁠ʼàráẕ֑wòţ ʼaşĕ̌mi֣ydĕ⁠ká֔ wĕ⁠yádaʻĕţá֖̇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃s"],[25,8,"כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה יַ֗עַן אֲמֹ֤ר מוֹאָב֙ וְ⁠שֵׂעִ֔יר הִנֵּ֥ה כְּ⁠כָֽל־הַ⁠גּוֹיִ֖ם בֵּ֥ית יְהוּדָֽה׃","kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h ya֗ʻan ʼàmò֤r mwòʼáb֙ wĕ⁠şé̂ʻi֔yr hiné֥̇h kĕ̇⁠káֽl-ha⁠ġwòyi֖m bé֥̇yţ yĕhẇdáֽh׃"],[25,9,"לָ⁠כֵן֩ הִנְ⁠נִ֨י פֹתֵ֜חַ אֶת־כֶּ֤תֶף מוֹאָב֙ מֵ⁠הֶ֣⁠עָרִ֔ים מֵֽ⁠עָרָ֖י⁠ו מִ⁠קָּצֵ֑⁠הוּ צְבִ֗י אֶ֚רֶץ בֵּ֣ית הַיְשִׁימֹ֔ת בַּ֥עַל מְע֖וֹן ו⁠קריתמ⁠ה׃","lá⁠kén֩ hinĕ⁠ni֨y pòţé֜ẖa ʼeţ-kė֤ţep mwòʼáb֙ mé⁠he֣⁠ʻári֔ym méֽ⁠ʻárá֖y⁠w mi⁠qá̇ẕé֑⁠hẇ ẕĕbi֗y ʼe֚reẕ bé֣̇yţ hayĕşǐymò֔ţ bȧ֥ʻal mĕʻ֖wòn w⁠qryţm⁠h׃"],[25,10,"לִ⁠בְנֵי־קֶ֨דֶם֙ עַל־בְּנֵ֣י עַמּ֔וֹן וּ⁠נְתַתִּ֖י⁠הָ לְ⁠מֽוֹרָשָׁ֑ה לְמַ֛עַן לֹֽא־תִזָּכֵ֥ר בְּנֵֽי־עַמּ֖וֹן בַּ⁠גּוֹיִֽם׃","li⁠bĕnéy-qe֨dem֙ ʻal-bĕ̇né֣y ʻaṁ֔wòn ẇ⁠nĕţaţi֖̇y⁠há lĕ⁠mֽwòráşá֑̌h lĕma֛ʻan lòֽʼ-ţizá̇ké֥r bĕ̇néֽy-ʻaṁ֖wòn bȧ⁠ġwòyiֽm׃"],[25,11,"וּ⁠בְ⁠מוֹאָ֖ב אֶעֱשֶׂ֣ה שְׁפָטִ֑ים וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃ס","ẇ⁠bĕ⁠mwòʼá֖b ʼeʻèşê֣h şĕ̌páti֑ym wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃s"],[25,12,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה יַ֣עַן עֲשׂ֥וֹת אֱד֛וֹם בִּ⁠נְקֹ֥ם נָקָ֖ם לְ⁠בֵ֣ית יְהוּדָ֑ה וַ⁠יֶּאְשְׁמ֥וּ אָשׁ֖וֹם וְ⁠נִקְּמ֥וּ בָ⁠הֶֽם׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ya֣ʻan ʻàş֥̂wòţ ʼèd֛wòm bi̇⁠nĕqò֥m náqá֖m lĕ⁠bé֣yţ yĕhẇdá֑h wa⁠yėʼĕşĕ̌m֥ẇ ʼáş֖̌wòm wĕ⁠niqĕ̇m֥ẇ bá⁠heֽm׃"],[25,13,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה וְ⁠נָטִ֤תִי יָדִ⁠י֙ עַל־אֱד֔וֹם וְ⁠הִכְרַתִּ֥י מִמֶּ֖⁠נָּה אָדָ֣ם וּ⁠בְהֵמָ֑ה וּ⁠נְתַתִּ֤י⁠הָ חָרְבָּה֙ מִ⁠תֵּימָ֔ן וּ⁠דְדָ֖נֶ⁠ה בַּ⁠חֶ֥רֶב יִפֹּֽלוּ׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h wĕ⁠náti֤ţiy yádi⁠y֙ ʻal-ʼèd֔wòm wĕ⁠hikĕraţi֥̇y mimė֖⁠ná̇h ʼádá֣m ẇ⁠bĕhémá֑h ẇ⁠nĕţaţi֤̇y⁠há ẖárĕbá̇h֙ mi⁠ţé̇ymá֔n ẇ⁠dĕdá֖ne⁠h bȧ⁠ẖe֥reb yipòֽ̇lẇ׃"],[25,14,"וְ⁠נָתַתִּ֨י אֶת־נִקְמָתִ֜⁠י בֶּ⁠אֱד֗וֹם בְּ⁠יַד֙ עַמִּ֣⁠י יִשְׂרָאֵ֔ל וְ⁠עָשׂ֣וּ בֶ⁠אֱד֔וֹם כְּ⁠אַפִּ֖⁠י וְ⁠כַ⁠חֲמָתִ֑⁠י וְ⁠יָֽדְעוּ֙ אֶת־נִקְמָתִ֔⁠י נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","wĕ⁠náţaţi̇֨y ʼeţ-niqĕmáţi֜⁠y bė⁠ʼèd֗wòm bĕ̇⁠yad֙ ʻami֣̇⁠y yişĕ̂ráʼé֔l wĕ⁠ʻáş֣̂ẇ be⁠ʼèd֔wòm kĕ̇⁠ʼapi֖̇⁠y wĕ⁠ka⁠ẖàmáţi֑⁠y wĕ⁠yáֽdĕʻẇ֙ ʼeţ-niqĕmáţi֔⁠y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[25,15,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה יַ֛עַן עֲשׂ֥וֹת פְּלִשְׁתִּ֖ים בִּ⁠נְקָמָ֑ה וַ⁠יִּנָּקְמ֤וּ נָקָם֙ בִּ⁠שְׁאָ֣ט בְּ⁠נֶ֔פֶשׁ לְ⁠מַשְׁחִ֖ית אֵיבַ֥ת עוֹלָֽם׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ya֛ʻan ʻàş֥̂wòţ pĕ̇lişĕ̌ţi֖̇ym bi̇⁠nĕqámá֑h wa⁠yi̇ná̇qĕm֤ẇ náqám֙ bi̇⁠şĕ̌ʼá֣t bĕ̇⁠ne֔peş̌ lĕ⁠maşĕ̌ẖi֖yţ ʼéyba֥ţ ʻwòláֽm׃"],[25,16,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִ֨י נוֹטֶ֤ה יָדִ⁠י֙ עַל־פְּלִשְׁתִּ֔ים וְ⁠הִכְרַתִּ֖י אֶת־כְּרֵתִ֑ים וְ⁠הַ֣אֲבַדְתִּ֔י אֶת־שְׁאֵרִ֖ית ח֥וֹף הַ⁠יָּֽם׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠ni֨y nwòte֤h yádi⁠y֙ ʻal-pĕ̇lişĕ̌ţi̇֔ym wĕ⁠hikĕraţi֖̇y ʼeţ-kĕ̇réţi֑ym wĕ⁠ha֣ʼàbadĕţi̇֔y ʼeţ-şĕ̌ʼéri֖yţ ẖ֥wòp ha⁠yáֽ̇m׃"],[25,17,"וְ⁠עָשִׂ֤יתִי בָ⁠ם֙ נְקָמ֣וֹת גְּדֹל֔וֹת בְּ⁠תוֹכְח֖וֹת חֵמָ֑ה וְ⁠יָֽדְעוּ֙ כִּֽי־אֲנִ֣י יְהוָ֔ה בְּ⁠תִתִּ֥⁠י אֶת־נִקְמָתִ֖⁠י בָּֽ⁠ם׃ס","wĕ⁠ʻáşî֤yţiy bá⁠m֙ nĕqám֣wòţ gĕ̇dòl֔wòţ bĕ̇⁠ţwòkĕẖ֖wòţ ẖémá֑h wĕ⁠yáֽdĕʻẇ֙ kiֽ̇y-ʼàni֣y yĕhwá֔h bĕ̇⁠ţiţi֥̇⁠y ʼeţ-niqĕmáţi֖⁠y báֽ̇⁠m׃s"],[26,1,"וַ⁠יְהִ֛י בְּ⁠עַשְׁתֵּֽי־עֶשְׂרֵ֥ה שָׁנָ֖ה בְּ⁠אֶחָ֣ד לַ⁠חֹ֑דֶשׁ הָיָ֥ה דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֛y bĕ̇⁠ʻaşĕ̌ţéֽ̇y-ʻeşĕ̂ré֥h şá̌ná֖h bĕ̇⁠ʼeẖá֣d la⁠ẖò֑deş̌ háyá֥h dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[26,2,"בֶּן־אָדָ֗ם יַ֠עַן אֲשֶׁר־אָ֨מְרָה צֹּ֤ר עַל־יְרוּשָׁלִַ֨ם֙ הֶאָ֔ח נִשְׁבְּרָ֛ה דַּלְת֥וֹת הָ⁠עַמִּ֖ים נָסֵ֣בָּה אֵלָ֑⁠י אִמָּלְאָ֖ה הָחֳרָֽבָה׃","bėn-ʼádá֗m ya֠ʻan ʼàşěr-ʼá֨mĕráh ẕò֤̇r ʻal-yĕrẇşá̌lia֨m֙ heʼá֔ẖ nişĕ̌bĕ̇rá֛h dȧlĕţ֥wòţ há⁠ʻami֖̇ym násé֣bá̇h ʼélá֑⁠y ʼimá̇lĕʼá֖h háẖoráֽbáh׃"],[26,3,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִ֥י עָלַ֖יִ⁠ךְ צֹ֑ר וְ⁠הַעֲלֵיתִ֤י עָלַ֨יִ⁠ךְ֙ גּוֹיִ֣ם רַבִּ֔ים כְּ⁠הַעֲל֥וֹת הַ⁠יָּ֖ם לְ⁠גַלָּֽי⁠ו׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠ni֥y ʻála֖yi⁠kĕ ẕò֑r wĕ⁠haʻàléyţi֤y ʻála֨yi⁠kĕ֙ ġwòyi֣m rabi̇֔ym kĕ̇⁠haʻàl֥wòţ ha⁠yá֖̇m lĕ⁠galáֽ̇y⁠w׃"],[26,4,"וְ⁠שִׁחֲת֞וּ חֹמ֣וֹת צֹ֗ר וְ⁠הָֽרְסוּ֙ מִגְדָּלֶ֔י⁠הָ וְ⁠סִֽחֵיתִ֥י עֲפָרָ֖⁠הּ מִמֶּ֑⁠נָּה וְ⁠נָתַתִּ֥י אוֹתָ֖⁠הּ לִ⁠צְחִ֥יחַ סָֽלַע׃","wĕ⁠şǐẖàţ֞ẇ ẖòm֣wòţ ẕò֗r wĕ⁠háֽrĕsẇ֙ migĕdá̇le֔y⁠há wĕ⁠siֽẖéyţi֥y ʻàpárá֖⁠ḣ mimė֑⁠ná̇h wĕ⁠náţaţi֥̇y ʼwòţá֖⁠ḣ li⁠ẕĕẖi֥yẖa sáֽlaʻ׃"],[26,5,"מִשְׁטַ֨ח חֲרָמִ֤ים תִּֽהְיֶה֙ בְּ⁠ת֣וֹךְ הַ⁠יָּ֔ם כִּ֚י אֲנִ֣י דִבַּ֔רְתִּי נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה וְ⁠הָיְתָ֥ה לְ⁠בַ֖ז לַ⁠גּוֹיִֽם׃","mişĕ̌ta֨ẖ ẖàrámi֤ym ţiֽ̇hĕyeh֙ bĕ̇⁠ţ֣wòkĕ ha⁠yá̇֔m ki֚̇y ʼàni֣y dibȧ֔rĕţi̇y nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h wĕ⁠háyĕţá֥h lĕ⁠ba֖z la⁠ġwòyiֽm׃"],[26,6,"וּ⁠בְנוֹתֶ֨י⁠הָ֙ אֲשֶׁ֣ר בַּ⁠שָּׂדֶ֔ה בַּ⁠חֶ֖רֶב תֵּהָרַ֑גְנָה וְ⁠יָדְע֖וּ כִּי־אֲנִ֥י יְהוָֽה׃פ","ẇ⁠bĕnwòţe֨y⁠há֙ ʼàşě֣r bȧ⁠şá̇̂de֔h bȧ⁠ẖe֖reb ţé̇hára֑gĕnáh wĕ⁠yádĕʻ֖ẇ ki̇y-ʼàni֥y yĕhwáֽh׃p"],[26,7,"כִּ֣י כֹ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִ֧י מֵבִ֣יא אֶל־צֹ֗ר נְבוּכַדְרֶאצַּ֧ר מֶֽלֶךְ־בָּבֶ֛ל מִ⁠צָּפ֖וֹן מֶ֣לֶךְ מְלָכִ֑ים בְּ⁠ס֛וּס וּ⁠בְ⁠רֶ֥כֶב וּ⁠בְ⁠פָרָשִׁ֖ים וְ⁠קָהָ֥ל וְ⁠עַם־רָֽב׃","ki֣̇y kò֤h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠ni֧y mébi֣yʼ ʼel-ẕò֗r nĕbẇkadĕreʼẕȧ֧r meֽlekĕ-bá̇be֛l mi⁠ẕá̇p֖wòn me֣lekĕ mĕláki֑ym bĕ̇⁠s֛ẇs ẇ⁠bĕ⁠re֥keb ẇ⁠bĕ⁠páráşǐ֖ym wĕ⁠qáhá֥l wĕ⁠ʻam-ráֽb׃"],[26,8,"בְּנוֹתַ֥יִ⁠ךְ בַּ⁠שָּׂדֶ֖ה בַּ⁠חֶ֣רֶב יַהֲרֹ֑ג וְ⁠נָתַ֨ן עָלַ֜יִ⁠ךְ דָּיֵ֗ק וְ⁠שָׁפַ֤ךְ עָלַ֨יִ⁠ךְ֙ סֹֽלְלָ֔ה וְ⁠הֵקִ֥ים עָלַ֖יִ⁠ךְ צִנָּֽה׃","bĕ̇nwòţa֥yi⁠kĕ bȧ⁠şá̇̂de֖h bȧ⁠ẖe֣reb yahàrò֑g wĕ⁠náţa֨n ʻála֜yi⁠kĕ dá̇yé֗q wĕ⁠şá̌pa֤kĕ ʻála֨yi⁠kĕ֙ sòֽlĕlá֔h wĕ⁠héqi֥ym ʻála֖yi⁠kĕ ẕináֽ̇h׃"],[26,9,"וּ⁠מְחִ֣י קָֽבָלּ֔⁠וֹ יִתֵּ֖ן בְּ⁠חֹֽמוֹתָ֑יִ⁠ךְ וּ⁠מִ֨גְדְּלֹתַ֔יִ⁠ךְ יִתֹּ֖ץ בְּ⁠חַרְבוֹתָֽי⁠ו׃","ẇ⁠mĕẖi֣y qáֽbál̇֔⁠wò yiţé֖̇n bĕ̇⁠ẖòֽmwòţá֑yi⁠kĕ ẇ⁠mi֨gĕdĕ̇lòţa֔yi⁠kĕ yiţò֖̇ẕ bĕ̇⁠ẖarĕbwòţáֽy⁠w׃"],[26,10,"מִ⁠שִּׁפְעַ֥ת סוּסָ֖י⁠ו יְכַסֵּ֣⁠ךְ אֲבָקָ֑⁠ם מִ⁠קּוֹל֩ פָּרַ֨שׁ וְ⁠גַלְגַּ֜ל וָ⁠רֶ֗כֶב תִּרְעַ֨שְׁנָה֙ חֽוֹמוֹתַ֔יִ⁠ךְ בְּ⁠בֹא⁠וֹ֙ בִּ⁠שְׁעָרַ֔יִ⁠ךְ כִּ⁠מְבוֹאֵ֖י עִ֥יר מְבֻקָּעָֽה׃","mi⁠şi̇̌pĕʻa֥ţ sẇsá֖y⁠w yĕkasé֣̇⁠kĕ ʼàbáqá֑⁠m mi⁠q̇wòl֩ pá̇ra֨ş̌ wĕ⁠galĕgȧ֜l wá⁠re֗keb ţi̇rĕʻa֨şĕ̌náh֙ ẖֽwòmwòţa֔yi⁠kĕ bĕ̇⁠bòʼ⁠wò֙ bi̇⁠şĕ̌ʻára֔yi⁠kĕ ki̇⁠mĕbwòʼé֖y ʻi֥yr mĕbuqá̇ʻáֽh׃"],[26,11,"בְּ⁠פַרְס֣וֹת סוּסָ֔י⁠ו יִרְמֹ֖ס אֶת־כָּל־חֽוּצוֹתָ֑יִ⁠ךְ עַמֵּ⁠ךְ֙ בַּ⁠חֶ֣רֶב יַהֲרֹ֔ג וּ⁠מַצְּב֥וֹת עֻזֵּ֖⁠ךְ לָ⁠אָ֥רֶץ תֵּרֵֽד׃","bĕ̇⁠parĕs֣wòţ sẇsá֔y⁠w yirĕmò֖s ʼeţ-ká̇l-ẖֽẇẕwòţá֑yi⁠kĕ ʻamé̇⁠kĕ֙ bȧ⁠ẖe֣reb yahàrò֔g ẇ⁠maẕĕ̇b֥wòţ ʻuzé֖̇⁠kĕ lá⁠ʼá֥reẕ ţé̇réֽd׃"],[26,12,"וְ⁠שָׁלְל֣וּ חֵילֵ֗⁠ךְ וּ⁠בָֽזְזוּ֙ רְכֻלָּתֵ֔⁠ךְ וְ⁠הָֽרְסוּ֙ חוֹמוֹתַ֔יִ⁠ךְ וּ⁠בָתֵּ֥י חֶמְדָּתֵ֖⁠ךְ יִתֹּ֑צוּ וַ⁠אֲבָנַ֤יִ⁠ךְ וְ⁠עֵצַ֨יִ⁠ךְ֙ וַֽ⁠עֲפָרֵ֔⁠ךְ בְּ⁠ת֥וֹךְ מַ֖יִם יָשִֽׂימוּ׃","wĕ⁠şá̌lĕl֣ẇ ẖéylé֗⁠kĕ ẇ⁠báֽzĕzẇ֙ rĕkulá̇ţé֔⁠kĕ wĕ⁠háֽrĕsẇ֙ ẖwòmwòţa֔yi⁠kĕ ẇ⁠báţé֥̇y ẖemĕdá̇ţé֖⁠kĕ yiţò֑̇ẕẇ wa⁠ʼàbána֤yi⁠kĕ wĕ⁠ʻéẕa֨yi⁠kĕ֙ waֽ⁠ʻàpáré֔⁠kĕ bĕ̇⁠ţ֥wòkĕ ma֖yim yáşîֽymẇ׃"],[26,13,"וְ⁠הִשְׁבַּתִּ֖י הֲמ֣וֹן שִׁירָ֑יִ⁠ךְ וְ⁠ק֣וֹל כִּנּוֹרַ֔יִ⁠ךְ לֹ֥א יִשָּׁמַ֖ע עֽוֹד׃","wĕ⁠hişĕ̌bȧţi֖̇y hàm֣wòn şǐyrá֑yi⁠kĕ wĕ⁠q֣wòl ki̇ṅwòra֔yi⁠kĕ lò֥ʼ yişá̇̌ma֖ʻ ʻֽwòd׃"],[26,14,"וּ⁠נְתַתִּ֞י⁠ךְ לִ⁠צְחִ֣יחַ סֶ֗לַע מִשְׁטַ֤ח חֲרָמִים֙ תִּֽהְיֶ֔ה לֹ֥א תִבָּנֶ֖ה ע֑וֹד כִּ֣י אֲנִ֤י יְהוָה֙ דִּבַּ֔רְתִּי נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","ẇ⁠nĕţaţi̇֞y⁠kĕ li⁠ẕĕẖi֣yẖa se֗laʻ mişĕ̌ta֤ẖ ẖàrámiym֙ ţiֽ̇hĕye֔h lò֥ʼ ţibá̇ne֖h ʻ֑wòd ki֣̇y ʼàni֤y yĕhwáh֙ di̇bȧ֔rĕţi̇y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[26,15,"כֹּ֥ה אָמַ֛ר אֲדֹנָ֥⁠י יְהוִ֖ה לְ⁠צ֑וֹר הֲ⁠לֹ֣א ׀ מִ⁠קּ֣וֹל מַפַּלְתֵּ֗⁠ךְ בֶּ⁠אֱנֹ֨ק חָלָ֜ל בֵּ⁠הָ֤רֵֽג הֶ֨רֶג֙ בְּ⁠תוֹכֵ֔⁠ךְ יִרְעֲשׁ֖וּ הָ⁠אִיִּֽים׃","kò֥̇h ʼáma֛r ʼàdòná֥⁠y yĕhwi֖h lĕ⁠ẕ֑wòr hà⁠lò֣ʼ ׀ mi⁠q֣̇wòl mapȧlĕţé̇֗⁠kĕ bė⁠ʼènò֨q ẖálá֜l bé̇⁠há֤réֽg he֨reg֙ bĕ̇⁠ţwòké֔⁠kĕ yirĕʻàş֖̌ẇ há⁠ʼiyiֽ̇ym׃"],[26,16,"וְֽ⁠יָרְד֞וּ מֵ⁠עַ֣ל כִּסְאוֹתָ֗⁠ם כֹּ֚ל נְשִׂיאֵ֣י הַ⁠יָּ֔ם וְ⁠הֵסִ֨ירוּ֙ אֶת־מְעִ֣ילֵי⁠הֶ֔ם וְ⁠אֶת־בִּגְדֵ֥י רִקְמָתָ֖⁠ם יִפְשֹׁ֑טוּ חֲרָד֤וֹת ׀ יִלְבָּ֨שׁוּ֙ עַל־הָ⁠אָ֣רֶץ יֵשֵׁ֔בוּ וְ⁠חָֽרְדוּ֙ לִ⁠רְגָעִ֔ים וְ⁠שָׁמְמ֖וּ עָלָֽיִ⁠ךְ׃","wֽĕ⁠yárĕd֞ẇ mé⁠ʻa֣l ki̇sĕʼwòţá֗⁠m kò֚̇l nĕşîyʼé֣y ha⁠yá̇֔m wĕ⁠hési֨yrẇ֙ ʼeţ-mĕʻi֣yléy⁠he֔m wĕ⁠ʼeţ-bi̇gĕdé֥y riqĕmáţá֖⁠m yipĕşò֑̌tẇ ẖàrád֤wòţ ׀ yilĕbá̇֨ş̌ẇ֙ ʻal-há⁠ʼá֣reẕ yéşé̌֔bẇ wĕ⁠ẖáֽrĕdẇ֙ li⁠rĕgáʻi֔ym wĕ⁠şá̌mĕm֖ẇ ʻáláֽyi⁠kĕ׃"],[26,17,"וְ⁠נָשְׂא֨וּ עָלַ֤יִ⁠ךְ קִינָה֙ וְ⁠אָ֣מְרוּ לָ֔⁠ךְ אֵ֣יךְ אָבַ֔דְתְּ נוֹשֶׁ֖בֶת מִ⁠יַּמִּ֑ים הָ⁠עִ֣יר הַ⁠הֻלָּ֗לָה אֲשֶׁר֩ הָיְתָ֨ה חֲזָקָ֤ה בַ⁠יָּם֙ הִ֣יא וְ⁠יֹשְׁבֶ֔י⁠הָ אֲשֶׁר־נָתְנ֥וּ חִתִּיתָ֖⁠ם לְ⁠כָל־יוֹשְׁבֶֽי⁠הָ׃","wĕ⁠náşĕ̂ʼ֨ẇ ʻála֤yi⁠kĕ qiynáh֙ wĕ⁠ʼá֣mĕrẇ lá֔⁠kĕ ʼé֣ykĕ ʼába֔dĕţĕ̇ nwòşě֖beţ mi⁠yȧmi֑̇ym há⁠ʻi֣yr ha⁠hulá̇֗láh ʼàşěr֩ háyĕţá֨h ẖàzáqá֤h ba⁠yá̇m֙ hi֣yʼ wĕ⁠yòşĕ̌be֔y⁠há ʼàşěr-náţĕn֥ẇ ẖiţi̇yţá֖⁠m lĕ⁠kál-ywòşĕ̌beֽy⁠há׃"],[26,18,"עַתָּה֙ יֶחְרְד֣וּ הָֽ⁠אִיִּ֔ן י֖וֹם מַפַּלְתֵּ֑⁠ךְ וְ⁠נִבְהֲל֛וּ הָ⁠אִיִּ֥ים אֲשֶׁר־בַּ⁠יָּ֖ם מִ⁠צֵּאתֵֽ⁠ךְ׃ס","ʻaţá̇h֙ yeẖĕrĕd֣ẇ háֽ⁠ʼiyi̇֔n y֖wòm mapȧlĕţé֑̇⁠kĕ wĕ⁠nibĕhàl֛ẇ há⁠ʼiyi֥̇ym ʼàşěr-bȧ⁠yá֖̇m mi⁠ẕé̇ʼţéֽ⁠kĕ׃s"],[26,19,"כִּ֣י כֹ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה בְּ⁠תִתִּ֤⁠י אֹתָ⁠ךְ֙ עִ֣יר נֶחֱרֶ֔בֶת כֶּ⁠עָרִ֖ים אֲשֶׁ֣ר לֹֽא־נוֹשָׁ֑בוּ בְּ⁠הַעֲל֤וֹת עָלַ֨יִ⁠ךְ֙ אֶת־תְּה֔וֹם וְ⁠כִסּ֖וּ⁠ךְ הַ⁠מַּ֥יִם הָ⁠רַבִּֽים׃","ki֣̇y kò֤h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h bĕ̇⁠ţiţi֤̇⁠y ʼòţá⁠kĕ֙ ʻi֣yr neẖère֔beţ kė⁠ʻári֖ym ʼàşě֣r lòֽʼ-nwòşá֑̌bẇ bĕ̇⁠haʻàl֤wòţ ʻála֨yi⁠kĕ֙ ʼeţ-ţĕ̇h֔wòm wĕ⁠kiṡ֖ẇ⁠kĕ ha⁠mȧ֥yim há⁠rabiֽ̇ym׃"],[26,20,"וְ⁠הוֹרַדְתִּי⁠ךְ֩ אֶת־י֨וֹרְדֵי ב֜וֹר אֶל־עַ֣ם עוֹלָ֗ם וְ֠⁠הוֹשַׁבְתִּי⁠ךְ בְּ⁠אֶ֨רֶץ תַּחְתִּיּ֜וֹת כָּ⁠חֳרָב֤וֹת מֵֽ⁠עוֹלָם֙ אֶת־י֣וֹרְדֵי ב֔וֹר לְמַ֖עַן לֹ֣א תֵשֵׁ֑בִי וְ⁠נָתַתִּ֥י צְבִ֖י בְּ⁠אֶ֥רֶץ חַיִּֽים׃","wĕ⁠hwòradĕţi̇y⁠kĕ֩ ʼeţ-y֨wòrĕdéy b֜wòr ʼel-ʻa֣m ʻwòlá֗m wĕ֠⁠hwòşǎbĕţi̇y⁠kĕ bĕ̇⁠ʼe֨reẕ ţȧẖĕţi̇ẏ֜wòţ ká̇⁠ẖoráb֤wòţ méֽ⁠ʻwòlám֙ ʼeţ-y֣wòrĕdéy b֔wòr lĕma֖ʻan lò֣ʼ ţéşé֑̌biy wĕ⁠náţaţi֥̇y ẕĕbi֖y bĕ̇⁠ʼe֥reẕ ẖayiֽ̇ym׃"],[26,21,"בַּלָּה֥וֹת אֶתְּנֵ֖⁠ךְ וְ⁠אֵינֵ֑⁠ךְ וּֽ⁠תְבֻקְשִׁ֗י וְ⁠לֹֽא־תִמָּצְאִ֥י עוֹד֙ לְ⁠עוֹלָ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהֹוִֽה׃ס","bȧlá̇h֥wòţ ʼeţĕ̇né֖⁠kĕ wĕ⁠ʼéyné֑⁠kĕ ẇֽ⁠ţĕbuqĕşǐ֗y wĕ⁠lòֽʼ-ţimá̇ẕĕʼi֥y ʻwòd֙ lĕ⁠ʻwòlá֔m nĕʼu֖m ʼàdòná֥⁠y yĕhòwiֽh׃s"],[27,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[27,2,"וְ⁠אַתָּ֣ה בֶן־אָדָ֔ם שָׂ֥א עַל־צֹ֖ר קִינָֽה׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֔m şá֥̂ʼ ʻal-ẕò֖r qiynáֽh׃"],[27,3,"וְ⁠אָמַרְתָּ֣ לְ⁠צ֗וֹר ה⁠ישבתי עַל־מְבוֹאֹ֣ת יָ֔ם רֹכֶ֨לֶת֙ הָֽ⁠עַמִּ֔ים אֶל־אִיִּ֖ים רַבִּ֑ים כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה צ֕וֹר אַ֣תְּ אָמַ֔רְתְּ אֲנִ֖י כְּלִ֥ילַת יֹֽפִי׃","wĕ⁠ʼámarĕţá֣̇ lĕ⁠ẕ֗wòr h⁠yşbţy ʻal-mĕbwòʼò֣ţ yá֔m ròke֨leţ֙ háֽ⁠ʻami̇֔ym ʼel-ʼiyi֖̇ym rabi֑̇ym kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ẕ֕wòr ʼa֣ţĕ̇ ʼáma֔rĕţĕ̇ ʼàni֖y kĕ̇li֥ylaţ yòֽpiy׃"],[27,4,"בְּ⁠לֵ֥ב יַמִּ֖ים גְּבוּלָ֑יִ⁠ךְ בֹּנַ֕יִ⁠ךְ כָּלְל֖וּ יָפְיֵֽ⁠ךְ׃","bĕ̇⁠lé֥b yami֖̇ym gĕ̇bẇlá֑yi⁠kĕ bò̇na֕yi⁠kĕ ká̇lĕl֖ẇ yápĕyéֽ⁠kĕ׃"],[27,5,"בְּרוֹשִׁ֤ים מִ⁠שְּׂנִיר֙ בָּ֣נוּ לָ֔⁠ךְ אֵ֖ת כָּל־לֻֽחֹתָ֑יִם אֶ֤רֶז מִ⁠לְּבָנוֹן֙ לָקָ֔חוּ לַ⁠עֲשׂ֥וֹת תֹּ֖רֶן עָלָֽיִ⁠ךְ׃","bĕ̇rwòşǐ֤ym mi⁠şĕ̇̂niyr֙ bá֣̇nẇ lá֔⁠kĕ ʼé֖ţ ká̇l-luֽẖòţá֑yim ʼe֤rez mi⁠lĕ̇bánwòn֙ láqá֔ẖẇ la⁠ʻàş֥̂wòţ ţò֖̇ren ʻáláֽyi⁠kĕ׃"],[27,6,"אַלּוֹנִים֙ מִ⁠בָּ֔שָׁן עָשׂ֖וּ מִשּׁוֹטָ֑יִ⁠ךְ קַרְשֵׁ֤⁠ךְ עָֽשׂוּ־שֵׁן֙ בַּת־אֲשֻׁרִ֔ים מֵ⁠אִיֵּ֖י כתים׃","ʼal̇wòniym֙ mi⁠bá̇֔şá̌n ʻáş֖̂ẇ miş̇̌wòtá֑yi⁠kĕ qarĕşé֤̌⁠kĕ ʻáֽş̂ẇ-şé̌n֙ bȧţ-ʼàşǔri֔ym mé⁠ʼiyé֖̇y kţym׃"],[27,7,"שֵׁשׁ־בְּ⁠רִקְמָ֤ה מִ⁠מִּצְרַ֨יִם֙ הָיָ֣ה מִפְרָשֵׂ֔⁠ךְ לִ⁠הְי֥וֹת לָ֖⁠ךְ לְ⁠נֵ֑ס תְּכֵ֧לֶת וְ⁠אַרְגָּמָ֛ן מֵ⁠אִיֵּ֥י אֱלִישָׁ֖ה הָיָ֥ה מְכַסֵּֽ⁠ךְ׃","şé̌ş̌-bĕ̇⁠riqĕmá֤h mi⁠mi̇ẕĕra֨yim֙ háyá֣h mipĕráşé̂֔⁠kĕ li⁠hĕy֥wòţ lá֖⁠kĕ lĕ⁠né֑s ţĕ̇ké֧leţ wĕ⁠ʼarĕgá̇má֛n mé⁠ʼiyé֥̇y ʼèliyşá֖̌h háyá֥h mĕkaséֽ̇⁠kĕ׃"],[27,8,"יֹשְׁבֵ֤י צִידוֹן֙ וְ⁠אַרְוַ֔ד הָי֥וּ שָׁטִ֖ים לָ֑⁠ךְ חֲכָמַ֤יִ⁠ךְ צוֹר֙ הָ֣יוּ בָ֔⁠ךְ הֵ֖מָּה חֹבְלָֽיִ⁠ךְ׃","yòşĕ̌bé֤y ẕiydwòn֙ wĕ⁠ʼarĕwa֔d háy֥ẇ şá̌ti֖ym lá֑⁠kĕ ẖàkáma֤yi⁠kĕ ẕwòr֙ há֣yẇ bá֔⁠kĕ hé֖má̇h ẖòbĕláֽyi⁠kĕ׃"],[27,9,"זִקְנֵ֨י גְבַ֤ל וַ⁠חֲכָמֶ֨י⁠הָ֙ הָ֣יוּ בָ֔⁠ךְ מַחֲזִיקֵ֖י בִּדְקֵ֑⁠ךְ כָּל־אֳנִיּ֨וֹת הַ⁠יָּ֤ם וּ⁠מַלָּֽחֵי⁠הֶם֙ הָ֣יוּ בָ֔⁠ךְ לַ⁠עֲרֹ֖ב מַעֲרָבֵֽ⁠ךְ׃","ziqĕné֨y gĕba֤l wa⁠ẖàkáme֨y⁠há֙ há֣yẇ bá֔⁠kĕ maẖàziyqé֖y bi̇dĕqé֑⁠kĕ ká̇l-ʼoniẏ֨wòţ ha⁠yá֤̇m ẇ⁠maláֽ̇ẖéy⁠hem֙ há֣yẇ bá֔⁠kĕ la⁠ʻàrò֖b maʻàrábéֽ⁠kĕ׃"],[27,10,"פָּרַ֨ס וְ⁠ל֤וּד וּ⁠פוּט֙ הָי֣וּ בְ⁠חֵילֵ֔⁠ךְ אַנְשֵׁ֖י מִלְחַמְתֵּ֑⁠ךְ מָגֵ֤ן וְ⁠כוֹבַע֙ תִּלּוּ־בָ֔⁠ךְ הֵ֖מָּה נָתְנ֥וּ הֲדָרֵֽ⁠ךְ׃","pá̇ra֨s wĕ⁠l֤ẇd ẇ⁠pẇt֙ háy֣ẇ bĕ⁠ẖéylé֔⁠kĕ ʼanĕşé֖̌y milĕẖamĕţé֑̇⁠kĕ mágé֤n wĕ⁠kwòbaʻ֙ ţi̇l̇ẇ-bá֔⁠kĕ hé֖má̇h náţĕn֥ẇ hàdáréֽ⁠kĕ׃"],[27,11,"בְּנֵ֧י אַרְוַ֣ד וְ⁠חֵילֵ֗ךְ עַל־חוֹמוֹתַ֨יִ⁠ךְ֙ סָבִ֔יב וְ⁠גַ֨מָּדִ֔ים בְּ⁠מִגְדְּלוֹתַ֖יִ⁠ךְ הָי֑וּ שִׁלְטֵי⁠הֶ֞ם תִּלּ֤וּ עַל־חוֹמוֹתַ֨יִ⁠ךְ֙ סָבִ֔יב הֵ֖מָּה כָּלְל֥וּ יָפְיֵֽ⁠ךְ׃","bĕ̇né֧y ʼarĕwa֣d wĕ⁠ẖéylé֗kĕ ʻal-ẖwòmwòţa֨yi⁠kĕ֙ sábi֔yb wĕ⁠ga֨má̇di֔ym bĕ̇⁠migĕdĕ̇lwòţa֖yi⁠kĕ háy֑ẇ şǐlĕtéy⁠he֞m ţi̇l֤̇ẇ ʻal-ẖwòmwòţa֨yi⁠kĕ֙ sábi֔yb hé֖má̇h ká̇lĕl֥ẇ yápĕyéֽ⁠kĕ׃"],[27,12,"תַּרְשִׁ֥ישׁ סֹחַרְתֵּ֖⁠ךְ מֵ⁠רֹ֣ב כָּל־ה֑וֹן בְּ⁠כֶ֤סֶף בַּרְזֶל֙ בְּדִ֣יל וְ⁠עוֹפֶ֔רֶת נָתְנ֖וּ עִזְבוֹנָֽיִ⁠ךְ׃","ţȧrĕşǐ֥yş̌ sòẖarĕţé֖̇⁠kĕ mé⁠rò֣b ká̇l-h֑wòn bĕ̇⁠ke֤sep bȧrĕzel֙ bĕ̇di֣yl wĕ⁠ʻwòpe֔reţ náţĕn֖ẇ ʻizĕbwònáֽyi⁠kĕ׃"],[27,13,"יָוָ֤ן תֻּבַל֙ וָ⁠מֶ֔שֶׁךְ הֵ֖מָּה רֹֽכְלָ֑יִ⁠ךְ בְּ⁠נֶ֤פֶשׁ אָדָם֙ וּ⁠כְלֵ֣י נְחֹ֔שֶׁת נָתְנ֖וּ מַעֲרָבֵֽ⁠ךְ׃","yáwá֤n ţu̇bal֙ wá⁠me֔şěkĕ hé֖má̇h ròֽkĕlá֑yi⁠kĕ bĕ̇⁠ne֤peş̌ ʼádám֙ ẇ⁠kĕlé֣y nĕẖò֔şěţ náţĕn֖ẇ maʻàrábéֽ⁠kĕ׃"],[27,14,"מִ⁠בֵּ֖ית תּוֹגַרְמָ֑ה סוּסִ֤ים וּ⁠פָֽרָשִׁים֙ וּ⁠פְרָדִ֔ים נָתְנ֖וּ עִזְבוֹנָֽיִ⁠ךְ׃","mi⁠bé֖̇yţ ţ̇wògarĕmá֑h sẇsi֤ym ẇ⁠páֽráşǐym֙ ẇ⁠pĕrádi֔ym náţĕn֖ẇ ʻizĕbwònáֽyi⁠kĕ׃"],[27,15,"בְּנֵ֤י דְדָן֙ רֹֽכְלַ֔יִ⁠ךְ אִיִּ֥ים רַבִּ֖ים סְחֹרַ֣ת יָדֵ֑⁠ךְ קַרְנ֥וֹת שֵׁן֙ ו⁠הובנים הֵשִׁ֖יבוּ אֶשְׁכָּרֵֽ⁠ךְ׃","bĕ̇né֤y dĕdán֙ ròֽkĕla֔yi⁠kĕ ʼiyi֥̇ym rabi֖̇ym sĕẖòra֣ţ yádé֑⁠kĕ qarĕn֥wòţ şé̌n֙ w⁠hwbnym héşǐ֖ybẇ ʼeşĕ̌ká̇réֽ⁠kĕ׃"],[27,16,"אֲרָ֥ם סֹחַרְתֵּ֖⁠ךְ מֵ⁠רֹ֣ב מַעֲשָׂ֑יִ⁠ךְ בְּ֠⁠נֹפֶךְ אַרְגָּמָ֨ן וְ⁠רִקְמָ֤ה וּ⁠בוּץ֙ וְ⁠רָאמֹ֣ת וְ⁠כַדְכֹּ֔ד נָתְנ֖וּ בְּ⁠עִזְבוֹנָֽיִ⁠ךְ׃","ʼàrá֥m sòẖarĕţé֖̇⁠kĕ mé⁠rò֣b maʻàşá֑̂yi⁠kĕ bĕ̇֠⁠nòpekĕ ʼarĕgá̇má֨n wĕ⁠riqĕmá֤h ẇ⁠bẇẕ֙ wĕ⁠ráʼmò֣ţ wĕ⁠kadĕkò̇֔d náţĕn֖ẇ bĕ̇⁠ʻizĕbwònáֽyi⁠kĕ׃"],[27,17,"יְהוּדָה֙ וְ⁠אֶ֣רֶץ יִשְׂרָאֵ֔ל הֵ֖מָּה רֹכְלָ֑יִ⁠ךְ בְּ⁠חִטֵּ֣י מִ֠נִּית וּ⁠פַנַּ֨ג וּ⁠דְבַ֤שׁ וָ⁠שֶׁ֨מֶן֙ וָ⁠צֹ֔רִי נָתְנ֖וּ מַעֲרָבֵֽ⁠ךְ׃","yĕhẇdáh֙ wĕ⁠ʼe֣reẕ yişĕ̂ráʼé֔l hé֖má̇h ròkĕlá֑yi⁠kĕ bĕ̇⁠ẖité֣̇y mi֠ni̇yţ ẇ⁠panȧ֨g ẇ⁠dĕba֤ş̌ wá⁠şě֨men֙ wá⁠ẕò֔riy náţĕn֖ẇ maʻàrábéֽ⁠kĕ׃"],[27,18,"דַּמֶּ֧שֶׂק סֹחַרְתֵּ֛⁠ךְ בְּ⁠רֹ֥ב מַעֲשַׂ֖יִ⁠ךְ מֵ⁠רֹ֣ב כָּל־ה֑וֹן בְּ⁠יֵ֥ין חֶלְבּ֖וֹן וְ⁠צֶ֥מֶר צָֽחַר׃","dȧmė֧şêq sòẖarĕţé֛̇⁠kĕ bĕ̇⁠rò֥b maʻàşâ֖yi⁠kĕ mé⁠rò֣b ká̇l-h֑wòn bĕ̇⁠yé֥yn ẖelĕḃ֖wòn wĕ⁠ẕe֥mer ẕáֽẖar׃"],[27,19,"וְדָ֤ן וְ⁠יָוָן֙ מְ⁠אוּזָּ֔ל בְּ⁠עִזְבוֹנַ֖יִ⁠ךְ נָתָ֑נּוּ בַּרְזֶ֤ל עָשׁוֹת֙ קִדָּ֣ה וְ⁠קָנֶ֔ה בְּ⁠מַעֲרָבֵ֖⁠ךְ הָיָֽה׃","wĕdá֤n wĕ⁠yáwán֙ mĕ⁠ʼẇzá̇֔l bĕ̇⁠ʻizĕbwòna֖yi⁠kĕ náţá֑ṅẇ bȧrĕze֤l ʻáş̌wòţ֙ qidá֣̇h wĕ⁠qáne֔h bĕ̇⁠maʻàrábé֖⁠kĕ háyáֽh׃"],[27,20,"דְּדָן֙ רֹֽכַלְתֵּ֔⁠ךְ בְ⁠בִגְדֵי־חֹ֖פֶשׁ לְ⁠רִכְבָּֽה׃","dĕ̇dán֙ ròֽkalĕţé̇֔⁠kĕ bĕ⁠bigĕdéy-ẖò֖peş̌ lĕ⁠rikĕbáֽ̇h׃"],[27,21,"עֲרַב֙ וְ⁠כָל־נְשִׂיאֵ֣י קֵדָ֔ר הֵ֖מָּה סֹחֲרֵ֣י יָדֵ֑⁠ךְ בְּ⁠כָרִ֤ים וְ⁠אֵילִים֙ וְ⁠עַתּוּדִ֔ים בָּ֖⁠ם סֹחֲרָֽיִ⁠ךְ׃","ʻàrab֙ wĕ⁠kál-nĕşîyʼé֣y qédá֔r hé֖má̇h sòẖàré֣y yádé֑⁠kĕ bĕ̇⁠kári֤ym wĕ⁠ʼéyliym֙ wĕ⁠ʻaţ̇ẇdi֔ym bá֖̇⁠m sòẖàráֽyi⁠kĕ׃"],[27,22,"רֹכְלֵ֤י שְׁבָא֙ וְ⁠רַעְמָ֔ה הֵ֖מָּה רֹכְלָ֑יִ⁠ךְ בְּ⁠רֹ֨אשׁ כָּל־בֹּ֜שֶׂם וּ⁠בְ⁠כָל־אֶ֤בֶן יְקָרָה֙ וְ⁠זָהָ֔ב נָתְנ֖וּ עִזְבוֹנָֽיִ⁠ךְ׃","ròkĕlé֤y şĕ̌báʼ֙ wĕ⁠raʻĕmá֔h hé֖má̇h ròkĕlá֑yi⁠kĕ bĕ̇⁠rò֨ʼş̌ ká̇l-bò̇֜şêm ẇ⁠bĕ⁠kál-ʼe֤ben yĕqáráh֙ wĕ⁠záhá֔b náţĕn֖ẇ ʻizĕbwònáֽyi⁠kĕ׃"],[27,23,"חָרָ֤ן וְ⁠כַנֵּה֙ וָ⁠עֶ֔דֶן רֹכְלֵ֖י שְׁבָ֑א אַשּׁ֖וּר כִּלְמַ֥ד רֹכַלְתֵּֽ⁠ךְ׃","ẖárá֤n wĕ⁠kané̇h֙ wá⁠ʻe֔den ròkĕlé֖y şĕ̌bá֑ʼ ʼaş֖̇̌ẇr ki̇lĕma֥d ròkalĕţéֽ̇⁠kĕ׃"],[27,24,"הֵ֤מָּה רֹכְלַ֨יִ⁠ךְ֙ בְּ⁠מַכְלֻלִ֔ים בִּ⁠גְלוֹמֵי֙ תְּכֵ֣לֶת וְ⁠רִקְמָ֔ה וּ⁠בְ⁠גִנְזֵ֖י בְּרֹמִ֑ים בַּ⁠חֲבָלִ֧ים חֲבֻשִׁ֛ים וַ⁠אֲרֻזִ֖ים בְּ⁠מַרְכֻלְתֵּֽ⁠ךְ׃","hé֤má̇h ròkĕla֨yi⁠kĕ֙ bĕ̇⁠makĕluli֔ym bi̇⁠gĕlwòméy֙ ţĕ̇ké֣leţ wĕ⁠riqĕmá֔h ẇ⁠bĕ⁠ginĕzé֖y bĕ̇ròmi֑ym bȧ⁠ẖàbáli֧ym ẖàbuşǐ֛ym wa⁠ʼàruzi֖ym bĕ̇⁠marĕkulĕţéֽ̇⁠kĕ׃"],[27,25,"אֳנִיּ֣וֹת תַּרְשִׁ֔ישׁ שָׁרוֹתַ֖יִ⁠ךְ מַעֲרָבֵ֑⁠ךְ וַ⁠תִּמָּלְאִ֧י וַֽ⁠תִּכְבְּדִ֛י מְאֹ֖ד בְּ⁠לֵ֥ב־יַמִּֽים׃","ʼoniẏ֣wòţ ţȧrĕşǐ֔yş̌ şá̌rwòţa֖yi⁠kĕ maʻàrábé֑⁠kĕ wa⁠ţi̇má̇lĕʼi֧y waֽ⁠ţi̇kĕbĕ̇di֛y mĕʼò֖d bĕ̇⁠lé֥b-yamiֽ̇ym׃"],[27,26,"בְּ⁠מַ֤יִם רַבִּים֙ הֱבִיא֔וּ⁠ךְ הַ⁠שָּׁטִ֖ים אֹתָ֑⁠ךְ ר֚וּחַ הַ⁠קָּדִ֔ים שְׁבָרֵ֖⁠ךְ בְּ⁠לֵ֥ב יַמִּֽים׃","bĕ̇⁠ma֤yim rabi̇ym֙ hèbiyʼ֔ẇ⁠kĕ ha⁠şá̇̌ti֖ym ʼòţá֑⁠kĕ r֚ẇẖa ha⁠qá̇di֔ym şĕ̌báré֖⁠kĕ bĕ̇⁠lé֥b yamiֽ̇ym׃"],[27,27,"הוֹנֵ⁠ךְ֙ וְ⁠עִזְבוֹנַ֔יִ⁠ךְ מַעֲרָבֵ֕⁠ךְ מַלָּחַ֖יִ⁠ךְ וְ⁠חֹבְלָ֑יִ⁠ךְ מַחֲזִיקֵ֣י בִדְקֵ֣⁠ך וְֽ⁠עֹרְבֵ֣י מַ֠עֲרָבֵ⁠ךְ וְ⁠כָל־אַנְשֵׁ֨י מִלְחַמְתֵּ֜⁠ךְ אֲשֶׁר־בָּ֗⁠ךְ וּ⁠בְ⁠כָל־קְהָלֵ⁠ךְ֙ אֲשֶׁ֣ר בְּ⁠תוֹכֵ֔⁠ךְ יִפְּלוּ֙ בְּ⁠לֵ֣ב יַמִּ֔ים בְּ⁠י֖וֹם מַפַּלְתֵּֽ⁠ךְ׃","hwòné⁠kĕ֙ wĕ⁠ʻizĕbwòna֔yi⁠kĕ maʻàrábé֕⁠kĕ malá̇ẖa֖yi⁠kĕ wĕ⁠ẖòbĕlá֑yi⁠kĕ maẖàziyqé֣y bidĕqé֣⁠k wĕֽ⁠ʻòrĕbé֣y ma֠ʻàrábé⁠kĕ wĕ⁠kál-ʼanĕşé̌֨y milĕẖamĕţé̇֜⁠kĕ ʼàşěr-bá̇֗⁠kĕ ẇ⁠bĕ⁠kál-qĕhálé⁠kĕ֙ ʼàşě֣r bĕ̇⁠ţwòké֔⁠kĕ yipĕ̇lẇ֙ bĕ̇⁠lé֣b yami̇֔ym bĕ̇⁠y֖wòm mapȧlĕţéֽ̇⁠kĕ׃"],[27,28,"לְ⁠ק֖וֹל זַעֲקַ֣ת חֹבְלָ֑יִ⁠ךְ יִרְעֲשׁ֖וּ מִגְרֹשֽׁוֹת׃","lĕ⁠q֖wòl zaʻàqa֣ţ ẖòbĕlá֑yi⁠kĕ yirĕʻàş֖̌ẇ migĕròşֽ̌wòţ׃"],[27,29,"וְֽ⁠יָרְד֞וּ מֵ⁠אָנִיּֽוֹתֵי⁠הֶ֗ם כֹּ֚ל תֹּפְשֵׂ֣י מָשׁ֔וֹט מַלָּחִ֕ים כֹּ֖ל חֹבְלֵ֣י הַ⁠יָּ֑ם אֶל־הָ⁠אָ֖רֶץ יַעֲמֹֽדוּ׃","wĕֽ⁠yárĕd֞ẇ mé⁠ʼániẏֽwòţéy⁠he֗m kò֚̇l ţò̇pĕşé֣̂y máş̌֔wòt malá̇ẖi֕ym kò֖̇l ẖòbĕlé֣y ha⁠yá֑̇m ʼel-há⁠ʼá֖reẕ yaʻàmòֽdẇ׃"],[27,30,"וְ⁠הִשְׁמִ֤יעוּ עָלַ֨יִ⁠ךְ֙ בְּ⁠קוֹלָ֔⁠ם וְ⁠יִזְעֲק֖וּ מָרָ֑ה וְ⁠יַעֲל֤וּ עָֽפָר֙ עַל־רָ֣אשֵׁי⁠הֶ֔ם בָּ⁠אֵ֖פֶר יִתְפַּלָּֽשׁוּ׃","wĕ⁠hişĕ̌mi֤yʻẇ ʻála֨yi⁠kĕ֙ bĕ̇⁠qwòlá֔⁠m wĕ⁠yizĕʻàq֖ẇ márá֑h wĕ⁠yaʻàl֤ẇ ʻֽápár֙ ʻal-rá֣ʼşé̌y⁠he֔m bá̇⁠ʼé֖per yiţĕpȧláֽ̇ş̌ẇ׃"],[27,31,"וְ⁠הִקְרִ֤יחוּ אֵלַ֨יִ⁠ךְ֙ קָרְחָ֔ה וְ⁠חָגְר֖וּ שַׂקִּ֑ים וּ⁠בָכ֥וּ אֵלַ֛יִ⁠ךְ בְּ⁠מַר־נֶ֖פֶשׁ מִסְפֵּ֥ד מָֽר׃","wĕ⁠hiqĕri֤yẖẇ ʼéla֨yi⁠kĕ֙ qárĕẖá֔h wĕ⁠ẖágĕr֖ẇ şâqi֑̇ym ẇ⁠bák֥ẇ ʼéla֛yi⁠kĕ bĕ̇⁠mar-ne֖peş̌ misĕpé֥̇d máֽr׃"],[27,32,"וְ⁠נָשְׂא֨וּ אֵלַ֤יִ⁠ךְ בְּ⁠נִי⁠הֶם֙ קִינָ֔ה וְ⁠קוֹנְנ֖וּ עָלָ֑יִ⁠ךְ מִ֣י כְ⁠צ֔וֹר כְּ⁠דֻמָ֖ה בְּ⁠ת֥וֹךְ הַ⁠יָּֽם׃","wĕ⁠náşĕ̂ʼ֨ẇ ʼéla֤yi⁠kĕ bĕ̇⁠niy⁠hem֙ qiyná֔h wĕ⁠qwònĕn֖ẇ ʻálá֑yi⁠kĕ mi֣y kĕ⁠ẕ֔wòr kĕ̇⁠dumá֖h bĕ̇⁠ţ֥wòkĕ ha⁠yáֽ̇m׃"],[27,33,"בְּ⁠צֵ֤את עִזְבוֹנַ֨יִ⁠ךְ֙ מִ⁠יַּמִּ֔ים הִשְׂבַּ֖עַתְּ עַמִּ֣ים רַבִּ֑ים בְּ⁠רֹ֤ב הוֹנַ֨יִ⁠ךְ֙ וּ⁠מַ֣עֲרָבַ֔יִ⁠ךְ הֶעֱשַׁ֖רְתְּ מַלְכֵי־אָֽרֶץ׃","bĕ̇⁠ẕé֤ʼţ ʻizĕbwòna֨yi⁠kĕ֙ mi⁠yȧmi̇֔ym hişĕ̂bȧ֖ʻaţĕ̇ ʻami֣̇ym rabi֑̇ym bĕ̇⁠rò֤b hwòna֨yi⁠kĕ֙ ẇ⁠ma֣ʻàrába֔yi⁠kĕ heʻèşǎ֖rĕţĕ̇ malĕkéy-ʼáֽreẕ׃"],[27,34,"עֵ֛ת נִשְׁבֶּ֥רֶת מִ⁠יַּמִּ֖ים בְּ⁠מַֽעֲמַקֵּי־מָ֑יִם מַעֲרָבֵ֥⁠ךְ וְ⁠כָל־קְהָלֵ֖⁠ךְ בְּ⁠תוֹכֵ֥⁠ךְ נָפָֽלוּ׃","ʻé֛ţ nişĕ̌bė֥reţ mi⁠yȧmi֖̇ym bĕ̇⁠maֽʻàmaqé̇y-má֑yim maʻàrábé֥⁠kĕ wĕ⁠kál-qĕhálé֖⁠kĕ bĕ̇⁠ţwòké֥⁠kĕ nápáֽlẇ׃"],[27,35,"כֹּ֚ל יֹשְׁבֵ֣י הָ⁠אִיִּ֔ים שָׁמְמ֖וּ עָלָ֑יִ⁠ךְ וּ⁠מַלְכֵי⁠הֶם֙ שָׂ֣עֲרוּ שַׂ֔עַר רָעֲמ֖וּ פָּנִֽים׃","kò֚̇l yòşĕ̌bé֣y há⁠ʼiyi̇֔ym şá̌mĕm֖ẇ ʻálá֑yi⁠kĕ ẇ⁠malĕkéy⁠hem֙ şá֣̂ʻàrẇ şâ֔ʻar ráʻàm֖ẇ pá̇niֽym׃"],[27,36,"סֹֽחֲרִים֙ בָּ֣⁠עַמִּ֔ים שָׁרְק֖וּ עָלָ֑יִ⁠ךְ בַּלָּה֣וֹת הָיִ֔ית וְ⁠אֵינֵ֖⁠ךְ עַד־עוֹלָֽם׃ס","sòֽẖàriym֙ bá֣̇⁠ʻami̇֔ym şá̌rĕq֖ẇ ʻálá֑yi⁠kĕ bȧlá̇h֣wòţ háyi֔yţ wĕ⁠ʼéyné֖⁠kĕ ʻad-ʻwòláֽm׃s"],[28,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[28,2,"בֶּן־אָדָ֡ם אֱמֹר֩ לִ⁠נְגִ֨יד צֹ֜ר כֹּֽה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהֹוִ֗ה יַ֣עַן גָּבַ֤הּ לִבְּ⁠ךָ֙ וַ⁠תֹּ֨אמֶר֙ אֵ֣ל אָ֔נִי מוֹשַׁ֧ב אֱלֹהִ֛ים יָשַׁ֖בְתִּי בְּ⁠לֵ֣ב יַמִּ֑ים וְ⁠אַתָּ֤ה אָדָם֙ וְֽ⁠לֹא־אֵ֔ל וַ⁠תִּתֵּ֥ן לִבְּ⁠ךָ֖ כְּ⁠לֵ֥ב אֱלֹהִֽים׃","bėn-ʼádá֡m ʼèmòr֩ li⁠nĕgi֨yd ẕò֜r kòֽ̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhòwi֗h ya֣ʻan gá̇ba֤ḣ libĕ̇⁠ká֙ wa⁠ţò̇֨ʼmer֙ ʼé֣l ʼá֔niy mwòşǎ֧b ʼèlòhi֛ym yáşǎ֖bĕţi̇y bĕ̇⁠lé֣b yami֑̇ym wĕ⁠ʼaţá֤̇h ʼádám֙ wĕֽ⁠lòʼ-ʼé֔l wa⁠ţi̇ţé֥̇n libĕ̇⁠ká֖ kĕ̇⁠lé֥b ʼèlòhiֽym׃"],[28,3,"הִנֵּ֥ה חָכָ֛ם אַתָּ֖ה מ⁠דנאל כָּל־סָת֖וּם לֹ֥א עֲמָמֽוּ⁠ךָ׃","hiné֥̇h ẖáká֛m ʼaţá֖̇h m⁠dnʼl ká̇l-sáţ֖ẇm lò֥ʼ ʻàmámֽẇ⁠ká׃"],[28,4,"בְּ⁠חָכְמָֽתְ⁠ךָ֙ וּ⁠בִ⁠תְבוּנָ֣תְ⁠ךָ֔ עָשִׂ֥יתָ לְּ⁠ךָ֖ חָ֑יִל וַ⁠תַּ֛עַשׂ זָהָ֥ב וָ⁠כֶ֖סֶף בְּ⁠אוֹצְרוֹתֶֽי⁠ךָ׃","bĕ̇⁠ẖákĕmáֽţĕ⁠ká֙ ẇ⁠bi⁠ţĕbẇná֣ţĕ⁠ká֔ ʻáşî֥yţá lĕ̇⁠ká֖ ẖá֑yil wa⁠ţȧ֛ʻaş̂ záhá֥b wá⁠ke֖sep bĕ̇⁠ʼwòẕĕrwòţeֽy⁠ká׃"],[28,5,"בְּ⁠רֹ֧ב חָכְמָתְ⁠ךָ֛ בִּ⁠רְכֻלָּתְ⁠ךָ֖ הִרְבִּ֣יתָ חֵילֶ֑⁠ךָ וַ⁠יִּגְבַּ֥הּ לְבָבְ⁠ךָ֖ בְּ⁠חֵילֶֽ⁠ךָ׃ס","bĕ̇⁠rò֧b ẖákĕmáţĕ⁠ká֛ bi̇⁠rĕkulá̇ţĕ⁠ká֖ hirĕbi֣̇yţá ẖéyle֑⁠ká wa⁠yi̇gĕbȧ֥ḣ lĕbábĕ⁠ká֖ bĕ̇⁠ẖéyleֽ⁠ká׃s"],[28,6,"לָ⁠כֵ֕ן כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה יַ֛עַן תִּתְּ⁠ךָ֥ אֶת־לְבָבְ⁠ךָ֖ כְּ⁠לֵ֥ב אֱלֹהִֽים׃","lá⁠ké֕n kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h ya֛ʻan ţi̇ţĕ̇⁠ká֥ ʼeţ-lĕbábĕ⁠ká֖ kĕ̇⁠lé֥b ʼèlòhiֽym׃"],[28,7,"לָ⁠כֵ֗ן הִנְ⁠נִ֨י מֵבִ֤יא עָלֶ֨י⁠ךָ֙ זָרִ֔ים עָרִיצֵ֖י גּוֹיִ֑ם וְ⁠הֵרִ֤יקוּ חַרְבוֹתָ⁠ם֙ עַל־יְפִ֣י חָכְמָתֶ֔⁠ךָ וְ⁠חִלְּל֖וּ יִפְעָתֶֽ⁠ךָ׃","lá⁠ké֗n hinĕ⁠ni֨y mébi֤yʼ ʻále֨y⁠ká֙ zári֔ym ʻáriyẕé֖y ġwòyi֑m wĕ⁠héri֤yqẇ ẖarĕbwòţá⁠m֙ ʻal-yĕpi֣y ẖákĕmáţe֔⁠ká wĕ⁠ẖilĕ̇l֖ẇ yipĕʻáţeֽ⁠ká׃"],[28,8,"לַ⁠שַּׁ֖חַת יֽוֹרִד֑וּ⁠ךָ וָ⁠מַ֛תָּה מְמוֹתֵ֥י חָלָ֖ל בְּ⁠לֵ֥ב יַמִּֽים׃","la⁠şȧ֖̌ẖaţ yֽwòrid֑ẇ⁠ká wá⁠ma֛ţá̇h mĕmwòţé֥y ẖálá֖l bĕ̇⁠lé֥b yamiֽ̇ym׃"],[28,9,"הֶ⁠אָמֹ֤ר תֹּאמַר֙ אֱלֹהִ֣ים אָ֔נִי לִ⁠פְנֵ֖י הֹֽרְגֶ֑⁠ךָ וְ⁠אַתָּ֥ה אָדָ֛ם וְ⁠לֹא־אֵ֖ל בְּ⁠יַ֥ד מְחַלְלֶֽי⁠ךָ׃","he⁠ʼámò֤r ţò̇ʼmar֙ ʼèlòhi֣ym ʼá֔niy li⁠pĕné֖y hòֽrĕge֑⁠ká wĕ⁠ʼaţá֥̇h ʼádá֛m wĕ⁠lòʼ-ʼé֖l bĕ̇⁠ya֥d mĕẖalĕleֽy⁠ká׃"],[28,10,"מוֹתֵ֧י עֲרֵלִ֛ים תָּמ֖וּת בְּ⁠יַד־זָרִ֑ים כִּ֚י אֲנִ֣י דִבַּ֔רְתִּי נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","mwòţé֧y ʻàréli֛ym ţá̇m֖ẇţ bĕ̇⁠yad-zári֑ym ki֚̇y ʼàni֣y dibȧ֔rĕţi̇y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[28,11,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[28,12,"בֶּן־אָדָ֕ם שָׂ֥א קִינָ֖ה עַל־מֶ֣לֶךְ צ֑וֹר וְ⁠אָמַ֣רְתָּ לּ֗⁠וֹ כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה אַתָּה֙ חוֹתֵ֣ם תָּכְנִ֔ית מָלֵ֥א חָכְמָ֖ה וּ⁠כְלִ֥יל יֹֽפִי׃","bėn-ʼádá֕m şá֥̂ʼ qiyná֖h ʻal-me֣lekĕ ẕ֑wòr wĕ⁠ʼáma֣rĕţá̇ l̇֗⁠wò kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ʼaţá̇h֙ ẖwòţé֣m ţá̇kĕni֔yţ málé֥ʼ ẖákĕmá֖h ẇ⁠kĕli֥yl yòֽpiy׃"],[28,13,"בְּ⁠עֵ֨דֶן גַּן־אֱלֹהִ֜ים הָיִ֗יתָ כָּל־אֶ֨בֶן יְקָרָ֤ה מְסֻכָתֶ֨⁠ךָ֙ אֹ֣דֶם פִּטְדָ֞ה וְ⁠יָהֲלֹ֗ם תַּרְשִׁ֥ישׁ שֹׁ֨הַם֙ וְ⁠יָ֣שְׁפֵ֔ה סַפִּ֣יר נֹ֔פֶךְ וּ⁠בָרְקַ֖ת וְ⁠זָהָ֑ב מְלֶ֨אכֶת תֻּפֶּ֤י⁠ךָ וּ⁠נְקָבֶ֨י⁠ךָ֙ בָּ֔⁠ךְ בְּ⁠י֥וֹם הִבָּרַאֲ⁠ךָ֖ כּוֹנָֽנוּ׃","bĕ̇⁠ʻé֨den gȧn-ʼèlòhi֜ym háyi֗yţá ká̇l-ʼe֨ben yĕqárá֤h mĕsukáţe֨⁠ká֙ ʼò֣dem pi̇tĕdá֞h wĕ⁠yáhàlò֗m ţȧrĕşǐ֥yş̌ şò̌֨ham֙ wĕ⁠yá֣şĕ̌pé֔h sapi֣̇yr nò֔pekĕ ẇ⁠bárĕqa֖ţ wĕ⁠záhá֑b mĕle֨ʼkeţ ţu̇pė֤y⁠ká ẇ⁠nĕqábe֨y⁠ká֙ bá̇֔⁠kĕ bĕ̇⁠y֥wòm hibá̇raʼà⁠ká֖ k̇wònáֽnẇ׃"],[28,14,"אַ֨תְּ־כְּר֔וּב מִמְשַׁ֖ח הַ⁠סּוֹכֵ֑ךְ וּ⁠נְתַתִּ֗י⁠ךָ בְּ⁠הַ֨ר קֹ֤דֶשׁ אֱלֹהִים֙ הָיִ֔יתָ בְּ⁠ת֥וֹךְ אַבְנֵי־אֵ֖שׁ הִתְהַלָּֽכְתָּ׃","ʼa֨ţĕ̇-kĕ̇r֔ẇb mimĕşǎ֖ẖ ha⁠ṡwòké֑kĕ ẇ⁠nĕţaţi̇֗y⁠ká bĕ̇⁠ha֨r qò֤deş̌ ʼèlòhiym֙ háyi֔yţá bĕ̇⁠ţ֥wòkĕ ʼabĕnéy-ʼé֖ş̌ hiţĕhaláֽ̇kĕţá̇׃"],[28,15,"תָּמִ֤ים אַתָּה֙ בִּ⁠דְרָכֶ֔י⁠ךָ מִ⁠יּ֖וֹם הִבָּֽרְאָ֑⁠ךְ עַד־נִמְצָ֥א עַוְלָ֖תָ⁠ה בָּֽ⁠ךְ׃","ţá̇mi֤ym ʼaţá̇h֙ bi̇⁠dĕráke֔y⁠ká mi⁠ẏ֖wòm hibáֽ̇rĕʼá֑⁠kĕ ʻad-nimĕẕá֥ʼ ʻawĕlá֖ţá⁠h báֽ̇⁠kĕ׃"],[28,16,"בְּ⁠רֹ֣ב רְכֻלָּתְ⁠ךָ֗ מָל֧וּ תוֹכְ⁠ךָ֛ חָמָ֖ס וַֽ⁠תֶּחֱטָ֑א וָ⁠אֶחַלֶּלְ⁠ךָ֩ מֵ⁠הַ֨ר אֱלֹהִ֤ים וָֽ⁠אַבֶּדְ⁠ךָ֙ כְּר֣וּב הַ⁠סֹּכֵ֔ךְ מִ⁠תּ֖וֹךְ אַבְנֵי־אֵֽשׁ׃","bĕ̇⁠rò֣b rĕkulá̇ţĕ⁠ká֗ mál֧ẇ ţwòkĕ⁠ká֛ ẖámá֖s waֽ⁠ţėẖètá֑ʼ wá⁠ʼeẖalėlĕ⁠ká֩ mé⁠ha֨r ʼèlòhi֤ym wáֽ⁠ʼabėdĕ⁠ká֙ kĕ̇r֣ẇb ha⁠sò̇ké֔kĕ mi⁠ţ֖̇wòkĕ ʼabĕnéy-ʼéֽş̌׃"],[28,17,"גָּבַ֤הּ לִבְּ⁠ךָ֙ בְּ⁠יָפְיֶ֔⁠ךָ שִׁחַ֥תָּ חָכְמָתְ⁠ךָ֖ עַל־יִפְעָתֶ֑⁠ךָ עַל־אֶ֣רֶץ הִשְׁלַכְתִּ֗י⁠ךָ לִ⁠פְנֵ֧י מְלָכִ֛ים נְתַתִּ֖י⁠ךָ לְ⁠רַ֥אֲוָה בָֽ⁠ךְ׃","gá̇ba֤ḣ libĕ̇⁠ká֙ bĕ̇⁠yápĕye֔⁠ká şǐẖa֥ţá̇ ẖákĕmáţĕ⁠ká֖ ʻal-yipĕʻáţe֑⁠ká ʻal-ʼe֣reẕ hişĕ̌lakĕţi̇֗y⁠ká li⁠pĕné֧y mĕláki֛ym nĕţaţi֖̇y⁠ká lĕ⁠ra֥ʼàwáh báֽ⁠kĕ׃"],[28,18,"מֵ⁠רֹ֣ב עֲוֺנֶ֗י⁠ךָ בְּ⁠עֶ֨וֶל֙ רְכֻלָּ֣תְ⁠ךָ֔ חִלַּ֖לְתָּ מִקְדָּשֶׁ֑י⁠ךָ וָֽ⁠אוֹצִא־אֵ֤שׁ מִ⁠תּֽוֹכְ⁠ךָ֙ הִ֣יא אֲכָלַ֔תְ⁠ךָ וָ⁠אֶתֶּנְ⁠ךָ֤ לְ⁠אֵ֨פֶר֙ עַל־הָ⁠אָ֔רֶץ לְ⁠עֵינֵ֖י כָּל־רֹאֶֽי⁠ךָ׃","mé⁠rò֣b ʻàwֺne֗y⁠ká bĕ̇⁠ʻe֨wel֙ rĕkulá֣̇ţĕ⁠ká֔ ẖilȧ֖lĕţá̇ miqĕdá̇şě֑y⁠ká wáֽ⁠ʼwòẕiʼ-ʼé֤ş̌ mi⁠ţֽ̇wòkĕ⁠ká֙ hi֣yʼ ʼàkála֔ţĕ⁠ká wá⁠ʼeţėnĕ⁠ká֤ lĕ⁠ʼé֨per֙ ʻal-há⁠ʼá֔reẕ lĕ⁠ʻéyné֖y ká̇l-ròʼeֽy⁠ká׃"],[28,19,"כָּל־יוֹדְעֶ֨י⁠ךָ֙ בָּֽ⁠עַמִּ֔ים שָׁמְמ֖וּ עָלֶ֑י⁠ךָ בַּלָּה֣וֹת הָיִ֔יתָ וְ⁠אֵינְ⁠ךָ֖ עַד־עוֹלָֽם׃פ","ká̇l-ywòdĕʻe֨y⁠ká֙ báֽ̇⁠ʻami̇֔ym şá̌mĕm֖ẇ ʻále֑y⁠ká bȧlá̇h֣wòţ háyi֔yţá wĕ⁠ʼéynĕ⁠ká֖ ʻad-ʻwòláֽm׃p"],[28,20,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[28,21,"בֶּן־אָדָ֕ם שִׂ֥ים פָּנֶ֖י⁠ךָ אֶל־צִיד֑וֹן וְ⁠הִנָּבֵ֖א עָלֶֽי⁠הָ׃","bėn-ʼádá֕m şî֥ym pá̇ne֖y⁠ká ʼel-ẕiyd֑wòn wĕ⁠hiná̇bé֖ʼ ʻáleֽy⁠há׃"],[28,22,"וְ⁠אָמַרְתָּ֗ כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִ֤י עָלַ֨יִ⁠ךְ֙ צִיד֔וֹן וְ⁠נִכְבַּדְתִּ֖י בְּ⁠תוֹכֵ֑⁠ךְ וְֽ⁠יָדְע֞וּ כִּֽי־אֲנִ֣י יְהוָ֗ה בַּ⁠עֲשׂ֥וֹתִ⁠י בָ֛⁠הּ שְׁפָטִ֖ים וְ⁠נִקְדַּ֥שְׁתִּי בָֽ⁠הּ׃","wĕ⁠ʼámarĕţá̇֗ kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠ni֤y ʻála֨yi⁠kĕ֙ ẕiyd֔wòn wĕ⁠nikĕbȧdĕţi֖̇y bĕ̇⁠ţwòké֑⁠kĕ wĕֽ⁠yádĕʻ֞ẇ kiֽ̇y-ʼàni֣y yĕhwá֗h bȧ⁠ʻàş֥̂wòţi⁠y bá֛⁠ḣ şĕ̌páti֖ym wĕ⁠niqĕdȧ֥şĕ̌ţi̇y báֽ⁠ḣ׃"],[28,23,"וְ⁠שִׁלַּחְתִּי־בָ֞⁠הּ דֶּ֤בֶר וָ⁠דָם֙ בְּ⁠ח֣וּצוֹתֶ֔י⁠הָ וְ⁠נִפְלַ֤ל חָלָל֙ בְּ⁠תוֹכָ֔⁠הּ בְּ⁠חֶ֥רֶב עָלֶ֖י⁠הָ מִ⁠סָּבִ֑יב וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃","wĕ⁠şǐlȧẖĕţi̇y-bá֞⁠ḣ dė֤ber wá⁠dám֙ bĕ̇⁠ẖ֣ẇẕwòţe֔y⁠há wĕ⁠nipĕla֤l ẖálál֙ bĕ̇⁠ţwòká֔⁠ḣ bĕ̇⁠ẖe֥reb ʻále֖y⁠há mi⁠sá̇bi֑yb wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[28,24,"וְ⁠לֹֽא־יִהְיֶ֨ה ע֜וֹד לְ⁠בֵ֣ית יִשְׂרָאֵ֗ל סִלּ֤וֹן מַמְאִיר֙ וְ⁠ק֣וֹץ מַכְאִ֔ב מִ⁠כֹּל֙ סְבִ֣יבֹתָ֔⁠ם הַ⁠שָּׁאטִ֖ים אוֹתָ֑⁠ם וְ⁠יָ֣דְע֔וּ כִּ֥י אֲנִ֖י אֲדֹנָ֥⁠י יְהוִֽה׃ס","wĕ⁠lòֽʼ-yihĕye֨h ʻ֜wòd lĕ⁠bé֣yţ yişĕ̂ráʼé֗l sil֤̇wòn mamĕʼiyr֙ wĕ⁠q֣wòẕ makĕʼi֔b mi⁠kò̇l֙ sĕbi֣ybòţá֔⁠m ha⁠şá̇̌ʼti֖ym ʼwòţá֑⁠m wĕ⁠yá֣dĕʻ֔ẇ ki֥̇y ʼàni֖y ʼàdòná֥⁠y yĕhwiֽh׃s"],[28,25,"כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ בְּ⁠קַבְּצִ֣⁠י ׀ אֶת־בֵּ֣ית יִשְׂרָאֵ֗ל מִן־הָֽ⁠עַמִּים֙ אֲשֶׁ֣ר נָפֹ֣צוּ בָ֔⁠ם וְ⁠נִקְדַּ֥שְׁתִּי בָ֖⁠ם לְ⁠עֵינֵ֣י הַ⁠גּוֹיִ֑ם וְ⁠יָֽשְׁבוּ֙ עַל־אַדְמָתָ֔⁠ם אֲשֶׁ֥ר נָתַ֖תִּי לְ⁠עַבְדִּ֥⁠י לְ⁠יַעֲקֹֽב׃","kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ bĕ̇⁠qabĕ̇ẕi֣⁠y ׀ ʼeţ-bé֣̇yţ yişĕ̂ráʼé֗l min-háֽ⁠ʻami̇ym֙ ʼàşě֣r nápò֣ẕẇ bá֔⁠m wĕ⁠niqĕdȧ֥şĕ̌ţi̇y bá֖⁠m lĕ⁠ʻéyné֣y ha⁠ġwòyi֑m wĕ⁠yáֽşĕ̌bẇ֙ ʻal-ʼadĕmáţá֔⁠m ʼàşě֥r náţa֖ţi̇y lĕ⁠ʻabĕdi֥̇⁠y lĕ⁠yaʻàqòֽb׃"],[28,26,"וְ⁠יָשְׁב֣וּ עָלֶי⁠הָ֮ לָ⁠בֶטַח֒ וּ⁠בָנ֤וּ בָתִּים֙ וְ⁠נָטְע֣וּ כְרָמִ֔ים וְ⁠יָשְׁב֖וּ לָ⁠בֶ֑טַח בַּ⁠עֲשׂוֹתִ֣⁠י שְׁפָטִ֗ים בְּ⁠כֹ֨ל הַ⁠שָּׁאטִ֤ים אֹתָ⁠ם֙ מִ⁠סְּבִ֣יבוֹתָ֔⁠ם וְ⁠יָ֣דְע֔וּ כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹהֵי⁠הֶֽם׃ס","wĕ⁠yáşĕ̌b֣ẇ ʻáley⁠há֮ lá⁠betaẖ֒ ẇ⁠bán֤ẇ báţi̇ym֙ wĕ⁠nátĕʻ֣ẇ kĕrámi֔ym wĕ⁠yáşĕ̌b֖ẇ lá⁠be֑taẖ bȧ⁠ʻàş̂wòţi֣⁠y şĕ̌páti֗ym bĕ̇⁠kò֨l ha⁠şá̇̌ʼti֤ym ʼòţá⁠m֙ mi⁠sĕ̇bi֣ybwòţá֔⁠m wĕ⁠yá֣dĕʻ֔ẇ ki֛̇y ʼàni֥y yĕhwá֖h ʼèlòhéy⁠heֽm׃s"],[29,1,"בַּ⁠שָּׁנָה֙ הָ⁠עֲשִׂירִ֔ית בָּ⁠עֲשִׂרִ֕י בִּ⁠שְׁנֵ֥ים עָשָׂ֖ר לַ⁠חֹ֑דֶשׁ הָיָ֥ה דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","bȧ⁠şá̇̌náh֙ há⁠ʻàşîyri֔yţ bá̇⁠ʻàşîri֕y bi̇⁠şĕ̌né֥ym ʻáşá֖̂r la⁠ẖò֑deş̌ háyá֥h dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[29,2,"בֶּן־אָדָ֕ם שִׂ֣ים פָּנֶ֔י⁠ךָ עַל־פַּרְעֹ֖ה מֶ֣לֶךְ מִצְרָ֑יִם וְ⁠הִנָּבֵ֣א עָלָ֔י⁠ו וְ⁠עַל־מִצְרַ֖יִם כֻּלָּֽ⁠הּ׃","bėn-ʼádá֕m şî֣ym pá̇ne֔y⁠ká ʻal-pȧrĕʻò֖h me֣lekĕ miẕĕrá֑yim wĕ⁠hiná̇bé֣ʼ ʻálá֔y⁠w wĕ⁠ʻal-miẕĕra֖yim ku̇láֽ̇⁠ḣ׃"],[29,3,"דַּבֵּ֨ר וְ⁠אָמַרְתָּ֜ כֹּֽה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה הִנְ⁠נִ֤י עָלֶ֨י⁠ךָ֙ פַּרְעֹ֣ה מֶֽלֶךְ־מִצְרַ֔יִם הַ⁠תַּנִּים֙ הַ⁠גָּד֔וֹל הָ⁠רֹבֵ֖ץ בְּ⁠ת֣וֹךְ יְאֹרָ֑י⁠ו אֲשֶׁ֥ר אָמַ֛ר לִ֥⁠י יְאֹרִ֖⁠י וַ⁠אֲנִ֥י עֲשִׂיתִֽ⁠נִי׃","dȧbé̇֨r wĕ⁠ʼámarĕţá̇֜ kòֽ̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h hinĕ⁠ni֤y ʻále֨y⁠ká֙ pȧrĕʻò֣h meֽlekĕ-miẕĕra֔yim ha⁠ţȧni̇ym֙ ha⁠gá̇d֔wòl há⁠ròbé֖ẕ bĕ̇⁠ţ֣wòkĕ yĕʼòrá֑y⁠w ʼàşě֥r ʼáma֛r li֥⁠y yĕʼòri֖⁠y wa⁠ʼàni֥y ʻàşîyţiֽ⁠niy׃"],[29,4,"וְ⁠נָתַתִּ֤י חחיים בִּ⁠לְחָיֶ֔י⁠ךָ וְ⁠הִדְבַּקְתִּ֥י דְגַת־יְאֹרֶ֖י⁠ךָ בְּ⁠קַשְׂקְשֹׂתֶ֑י⁠ךָ וְ⁠הַעֲלִיתִ֨י⁠ךָ֙ מִ⁠תּ֣וֹךְ יְאֹרֶ֔י⁠ךָ וְ⁠אֵת֙ כָּל־דְּגַ֣ת יְאֹרֶ֔י⁠ךָ בְּ⁠קַשְׂקְשֹׂתֶ֖י⁠ךָ תִּדְבָּֽק׃","wĕ⁠náţaţi֤̇y ẖẖyym bi̇⁠lĕẖáye֔y⁠ká wĕ⁠hidĕbȧqĕţi֥̇y dĕgaţ-yĕʼòre֖y⁠ká bĕ̇⁠qaşĕ̂qĕşò̂ţe֑y⁠ká wĕ⁠haʻàliyţi֨y⁠ká֙ mi⁠ţ֣̇wòkĕ yĕʼòre֔y⁠ká wĕ⁠ʼéţ֙ ká̇l-dĕ̇ga֣ţ yĕʼòre֔y⁠ká bĕ̇⁠qaşĕ̂qĕşò̂ţe֖y⁠ká ţi̇dĕbáֽ̇q׃"],[29,5,"וּ⁠נְטַשְׁתִּ֣י⁠ךָ הַ⁠מִּדְבָּ֗רָ⁠ה אוֹתְ⁠ךָ֙ וְ⁠אֵת֙ כָּל־דְּגַ֣ת יְאֹרֶ֔י⁠ךָ עַל־פְּנֵ֤י הַ⁠שָּׂדֶה֙ תִּפּ֔וֹל לֹ֥א תֵאָסֵ֖ף וְ⁠לֹ֣א תִקָּבֵ֑ץ לְ⁠חַיַּ֥ת הָ⁠אָ֛רֶץ וּ⁠לְ⁠ע֥וֹף הַ⁠שָּׁמַ֖יִם נְתַתִּ֥י⁠ךָ לְ⁠אָכְלָֽה׃","ẇ⁠nĕtaşĕ̌ţi֣̇y⁠ká ha⁠mi̇dĕbá̇֗rá⁠h ʼwòţĕ⁠ká֙ wĕ⁠ʼéţ֙ ká̇l-dĕ̇ga֣ţ yĕʼòre֔y⁠ká ʻal-pĕ̇né֤y ha⁠şá̇̂deh֙ ţi̇ṗ֔wòl lò֥ʼ ţéʼásé֖p wĕ⁠lò֣ʼ ţiqá̇bé֑ẕ lĕ⁠ẖayȧ֥ţ há⁠ʼá֛reẕ ẇ⁠lĕ⁠ʻ֥wòp ha⁠şá̇̌ma֖yim nĕţaţi֥̇y⁠ká lĕ⁠ʼákĕláֽh׃"],[29,6,"וְ⁠יָֽדְעוּ֙ כָּל־יֹשְׁבֵ֣י מִצְרַ֔יִם כִּ֖י אֲנִ֣י יְהוָ֑ה יַ֧עַן הֱיוֹתָ֛⁠ם מִשְׁעֶ֥נֶת קָנֶ֖ה לְ⁠בֵ֥ית יִשְׂרָאֵֽל׃","wĕ⁠yáֽdĕʻẇ֙ ká̇l-yòşĕ̌bé֣y miẕĕra֔yim ki֖̇y ʼàni֣y yĕhwá֑h ya֧ʻan hèywòţá֛⁠m mişĕ̌ʻe֥neţ qáne֖h lĕ⁠bé֥yţ yişĕ̂ráʼéֽl׃"],[29,7,"בְּ⁠תָפְשָׂ֨⁠ם בְּ⁠ךָ֤ ב⁠כפ⁠ך תֵּר֔וֹץ וּ⁠בָקַעְתָּ֥ לָ⁠הֶ֖ם כָּל־כָּתֵ֑ף וּ⁠בְ⁠הִֽשָּׁעֲנָ֤⁠ם עָלֶ֨י⁠ךָ֙ תִּשָּׁבֵ֔ר וְ⁠הַעֲמַדְתָּ֥ לָ⁠הֶ֖ם כָּל־מָתְנָֽיִם׃ס","bĕ̇⁠ţápĕşá̂֨⁠m bĕ̇⁠ká֤ b⁠kp⁠k ţé̇r֔wòẕ ẇ⁠báqaʻĕţá֥̇ lá⁠he֖m ká̇l-ká̇ţé֑p ẇ⁠bĕ⁠hiֽşá̇̌ʻàná֤⁠m ʻále֨y⁠ká֙ ţi̇şá̇̌bé֔r wĕ⁠haʻàmadĕţá֥̇ lá⁠he֖m ká̇l-máţĕnáֽyim׃s"],[29,8,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִ֛י מֵבִ֥יא עָלַ֖יִ⁠ךְ חָ֑רֶב וְ⁠הִכְרַתִּ֥י מִמֵּ֖⁠ךְ אָדָ֥ם וּ⁠בְהֵמָֽה׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠ni֛y mébi֥yʼ ʻála֖yi⁠kĕ ẖá֑reb wĕ⁠hikĕraţi֥̇y mimé֖̇⁠kĕ ʼádá֥m ẇ⁠bĕhémáֽh׃"],[29,9,"וְ⁠הָיְתָ֤ה אֶֽרֶץ־מִצְרַ֨יִם֙ לִ⁠שְׁמָמָ֣ה וְ⁠חָרְבָּ֔ה וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֣י יְהוָ֑ה יַ֧עַן אָמַ֛ר יְאֹ֥ר לִ֖⁠י וַ⁠אֲנִ֥י עָשִֽׂיתִי׃","wĕ⁠háyĕţá֤h ʼeֽreẕ-miẕĕra֨yim֙ li⁠şĕ̌mámá֣h wĕ⁠ẖárĕbá̇֔h wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֣y yĕhwá֑h ya֧ʻan ʼáma֛r yĕʼò֥r li֖⁠y wa⁠ʼàni֥y ʻáşîֽyţiy׃"],[29,10,"לָ⁠כֵ֛ן הִנְ⁠נִ֥י אֵלֶ֖י⁠ךָ וְ⁠אֶל־יְאֹרֶ֑י⁠ךָ וְ⁠נָתַתִּ֞י אֶת־אֶ֣רֶץ מִצְרַ֗יִם לְ⁠חָרְבוֹת֙ חֹ֣רֶב שְׁמָמָ֔ה מִ⁠מִּגְדֹּ֥ל סְוֵנֵ֖ה וְ⁠עַד־גְּב֥וּל כּֽוּשׁ׃","lá⁠ké֛n hinĕ⁠ni֥y ʼéle֖y⁠ká wĕ⁠ʼel-yĕʼòre֑y⁠ká wĕ⁠náţaţi̇֞y ʼeţ-ʼe֣reẕ miẕĕra֗yim lĕ⁠ẖárĕbwòţ֙ ẖò֣reb şĕ̌mámá֔h mi⁠mi̇gĕdò֥̇l sĕwéné֖h wĕ⁠ʻad-gĕ̇b֥ẇl kֽ̇ẇş̌׃"],[29,11,"לֹ֤א תַעֲבָר־בָּ⁠הּ֙ רֶ֣גֶל אָדָ֔ם וְ⁠רֶ֥גֶל בְּהֵמָ֖ה לֹ֣א תַעֲבָר־בָּ֑⁠הּ וְ⁠לֹ֥א תֵשֵׁ֖ב אַרְבָּעִ֥ים שָׁנָֽה׃","lò֤ʼ ţaʻàbár-bá̇⁠ḣ֙ re֣gel ʼádá֔m wĕ⁠re֥gel bĕ̇hémá֖h lò֣ʼ ţaʻàbár-bá֑̇⁠ḣ wĕ⁠lò֥ʼ ţéşé֖̌b ʼarĕbá̇ʻi֥ym şá̌náֽh׃"],[29,12,"וְ⁠נָתַתִּ֣י אֶת־אֶרֶץ֩ מִצְרַ֨יִם שְׁמָמָ֜ה בְּ⁠ת֣וֹךְ ׀ אֲרָצ֣וֹת נְשַׁמּ֗וֹת וְ⁠עָרֶ֨י⁠הָ֙ בְּ⁠ת֨וֹךְ עָרִ֤ים מָֽחֳרָבוֹת֙ תִּֽהְיֶ֣יןָ שְׁמָמָ֔ה אַרְבָּעִ֖ים שָׁנָ֑ה וַ⁠הֲפִצֹתִ֤י אֶת־מִצְרַ֨יִם֙ בַּ⁠גּוֹיִ֔ם וְֽ⁠זֵרִיתִ֖י⁠ם בָּ⁠אֲרָצֽוֹת׃פ","wĕ⁠náţaţi֣̇y ʼeţ-ʼereẕ֩ miẕĕra֨yim şĕ̌mámá֜h bĕ̇⁠ţ֣wòkĕ ׀ ʼàráẕ֣wòţ nĕşǎṁ֗wòţ wĕ⁠ʻáre֨y⁠há֙ bĕ̇⁠ţ֨wòkĕ ʻári֤ym máֽẖorábwòţ֙ ţiֽ̇hĕye֣yná şĕ̌mámá֔h ʼarĕbá̇ʻi֖ym şá̌ná֑h wa⁠hàpiẕòţi֤y ʼeţ-miẕĕra֨yim֙ bȧ⁠ġwòyi֔m wĕֽ⁠zériyţi֖y⁠m bá̇⁠ʼàráẕֽwòţ׃p"],[29,13,"כִּ֛י כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה מִ⁠קֵּ֞ץ אַרְבָּעִ֤ים שָׁנָה֙ אֲקַבֵּ֣ץ אֶת־מִצְרַ֔יִם מִן־הָ⁠עַמִּ֖ים אֲשֶׁר־נָפֹ֥צוּ שָֽׁמָּ⁠ה׃","ki֛̇y kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h mi⁠qé̇֞ẕ ʼarĕbá̇ʻi֤ym şá̌náh֙ ʼàqabé֣̇ẕ ʼeţ-miẕĕra֔yim min-há⁠ʻami֖̇ym ʼàşěr-nápò֥ẕẇ şáֽ̌má̇⁠h׃"],[29,14,"וְ⁠שַׁבְתִּי֙ אֶת־שְׁב֣וּת מִצְרַ֔יִם וַ⁠הֲשִׁבֹתִ֤י אֹתָ⁠ם֙ אֶ֣רֶץ פַּתְר֔וֹס עַל־אֶ֖רֶץ מְכֽוּרָתָ֑⁠ם וְ⁠הָ֥יוּ שָׁ֖ם מַמְלָכָ֥ה שְׁפָלָֽה׃","wĕ⁠şǎbĕţi̇y֙ ʼeţ-şĕ̌b֣ẇţ miẕĕra֔yim wa⁠hàşǐbòţi֤y ʼòţá⁠m֙ ʼe֣reẕ pȧţĕr֔wòs ʻal-ʼe֖reẕ mĕkֽẇráţá֑⁠m wĕ⁠há֥yẇ şá֖̌m mamĕláká֥h şĕ̌páláֽh׃"],[29,15,"מִן־הַ⁠מַּמְלָכוֹת֙ תִּהְיֶ֣ה שְׁפָלָ֔ה וְ⁠לֹֽא־תִתְנַשֵּׂ֥א ע֖וֹד עַל־הַ⁠גּוֹיִ֑ם וְ⁠הִ֨מְעַטְתִּ֔י⁠ם לְ⁠בִלְתִּ֖י רְד֥וֹת בַּ⁠גּוֹיִֽם׃","min-ha⁠mȧmĕlákwòţ֙ ţi̇hĕye֣h şĕ̌pálá֔h wĕ⁠lòֽʼ-ţiţĕnaşé֥̇̂ʼ ʻ֖wòd ʻal-ha⁠ġwòyi֑m wĕ⁠hi֨mĕʻatĕţi̇֔y⁠m lĕ⁠bilĕţi֖̇y rĕd֥wòţ bȧ⁠ġwòyiֽm׃"],[29,16,"וְ⁠לֹ֣א יִֽהְיֶה־עוֹד֩ לְ⁠בֵ֨ית יִשְׂרָאֵ֤ל לְ⁠מִבְטָח֙ מַזְכִּ֣יר עָוֺ֔ן בִּ⁠פְנוֹתָ֖⁠ם אַחֲרֵי⁠הֶ֑ם וְ⁠יָ֣דְע֔וּ כִּ֥י אֲנִ֖י אֲדֹנָ֥⁠י יְהוִֽה׃פ","wĕ⁠lò֣ʼ yiֽhĕyeh-ʻwòd֩ lĕ⁠bé֨yţ yişĕ̂ráʼé֤l lĕ⁠mibĕtáẖ֙ mazĕki֣̇yr ʻáwֺ֔n bi̇⁠pĕnwòţá֖⁠m ʼaẖàréy⁠he֑m wĕ⁠yá֣dĕʻ֔ẇ ki֥̇y ʼàni֖y ʼàdòná֥⁠y yĕhwiֽh׃p"],[29,17,"וַ⁠יְהִ֗י בְּ⁠עֶשְׂרִ֤ים וָ⁠שֶׁ֨בַע֙ שָׁנָ֔ה בָּֽ⁠רִאשׁ֖וֹן בְּ⁠אֶחָ֣ד לַ⁠חֹ֑דֶשׁ הָיָ֥ה דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֗y bĕ̇⁠ʻeşĕ̂ri֤ym wá⁠şě֨baʻ֙ şá̌ná֔h báֽ̇⁠riʼş֖̌wòn bĕ̇⁠ʼeẖá֣d la⁠ẖò֑deş̌ háyá֥h dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[29,18,"בֶּן־אָדָ֗ם נְבוּכַדְרֶאצַּ֣ר מֶֽלֶךְ־בָּ֠בֶל הֶעֱבִ֨יד אֶת־חֵיל֜⁠וֹ עֲבֹדָ֤ה גְדֹלָה֙ אֶל־צֹ֔ר כָּל־רֹ֣אשׁ מֻקְרָ֔ח וְ⁠כָל־כָּתֵ֖ף מְרוּטָ֑ה וְ֠⁠שָׂכָר לֹא־הָ֨יָה ל֤⁠וֹ וּ⁠לְ⁠חֵיל⁠וֹ֙ מִ⁠צֹּ֔ר עַל־הָ⁠עֲבֹדָ֖ה אֲשֶׁר־עָבַ֥ד עָלֶֽי⁠הָ׃ס","bėn-ʼádá֗m nĕbẇkadĕreʼẕȧ֣r meֽlekĕ-bá̇֠bel heʻèbi֨yd ʼeţ-ẖéyl֜⁠wò ʻàbòdá֤h gĕdòláh֙ ʼel-ẕò֔r ká̇l-rò֣ʼş̌ muqĕrá֔ẖ wĕ⁠kál-ká̇ţé֖p mĕrẇtá֑h wĕ֠⁠şá̂kár lòʼ-há֨yáh l֤⁠wò ẇ⁠lĕ⁠ẖéyl⁠wò֙ mi⁠ẕò̇֔r ʻal-há⁠ʻàbòdá֖h ʼàşěr-ʻába֥d ʻáleֽy⁠há׃s"],[29,19,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִ֥י נֹתֵ֛ן לִ⁠נְבוּכַדְרֶאצַּ֥ר מֶֽלֶךְ־בָּבֶ֖ל אֶת־אֶ֣רֶץ מִצְרָ֑יִם וְ⁠נָשָׂ֨א הֲמֹנָ֜⁠הּ וְ⁠שָׁלַ֤ל שְׁלָלָ⁠הּ֙ וּ⁠בָזַ֣ז בִּזָּ֔⁠הּ וְ⁠הָיְתָ֥ה שָׂכָ֖ר לְ⁠חֵילֽ⁠וֹ׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠ni֥y nòţé֛n li⁠nĕbẇkadĕreʼẕȧ֥r meֽlekĕ-bá̇be֖l ʼeţ-ʼe֣reẕ miẕĕrá֑yim wĕ⁠náşá̂֨ʼ hàmòná֜⁠ḣ wĕ⁠şá̌la֤l şĕ̌lálá⁠ḣ֙ ẇ⁠báza֣z bi̇zá̇֔⁠ḣ wĕ⁠háyĕţá֥h şá̂ká֖r lĕ⁠ẖéylֽ⁠wò׃"],[29,20,"פְּעֻלָּת⁠וֹ֙ אֲשֶׁר־עָ֣בַד בָּ֔⁠הּ נָתַ֥תִּי ל֖⁠וֹ אֶת־אֶ֣רֶץ מִצְרָ֑יִם אֲשֶׁר֙ עָ֣שׂוּ לִ֔⁠י נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","pĕ̇ʻulá̇ţ⁠wò֙ ʼàşěr-ʻá֣bad bá̇֔⁠ḣ náţa֥ţi̇y l֖⁠wò ʼeţ-ʼe֣reẕ miẕĕrá֑yim ʼàşěr֙ ʻá֣ş̂ẇ li֔⁠y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[29,21,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא אַצְמִ֤יחַ קֶ֨רֶן֙ לְ⁠בֵ֣ית יִשְׂרָאֵ֔ל וּ⁠לְ⁠ךָ֛ אֶתֵּ֥ן פִּתְחֽוֹן־פֶּ֖ה בְּ⁠תוֹכָ֑⁠ם וְ⁠יָדְע֖וּ כִּי־אֲנִ֥י יְהוָֽה׃פ","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ ʼaẕĕmi֤yẖa qe֨ren֙ lĕ⁠bé֣yţ yişĕ̂ráʼé֔l ẇ⁠lĕ⁠ká֛ ʼeţé֥̇n pi̇ţĕẖֽwòn-pė֖h bĕ̇⁠ţwòká֑⁠m wĕ⁠yádĕʻ֖ẇ ki̇y-ʼàni֥y yĕhwáֽh׃p"],[30,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[30,2,"בֶּן־אָדָ֕ם הִנָּבֵא֙ וְ⁠אָ֣מַרְתָּ֔ כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה הֵילִ֖ילוּ הָ֥הּ לַ⁠יּֽוֹם׃","bėn-ʼádá֕m hiná̇béʼ֙ wĕ⁠ʼá֣marĕţá̇֔ kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h héyli֖ylẇ há֥ḣ la⁠ẏֽwòm׃"],[30,3,"כִּֽי־קָר֣וֹב י֔וֹם וְ⁠קָר֥וֹב י֖וֹם לַֽ⁠יהוָ֑ה י֣וֹם עָנָ֔ן עֵ֥ת גּוֹיִ֖ם יִֽהְיֶֽה׃","kiֽ̇y-qár֣wòb y֔wòm wĕ⁠qár֥wòb y֖wòm laֽ⁠yhwá֑h y֣wòm ʻáná֔n ʻé֥ţ ġwòyi֖m yiֽhĕyeֽh׃"],[30,4,"וּ⁠בָאָ֥ה חֶ֨רֶב֙ בְּ⁠מִצְרַ֔יִם וְ⁠הָיְתָ֤ה חַלְחָלָה֙ בְּ⁠כ֔וּשׁ בִּ⁠נְפֹ֥ל חָלָ֖ל בְּ⁠מִצְרָ֑יִם וְ⁠לָקְח֣וּ הֲמוֹנָ֔⁠הּ וְ⁠נֶהֶרְס֖וּ יְסוֹדֹתֶֽי⁠הָ׃","ẇ⁠báʼá֥h ẖe֨reb֙ bĕ̇⁠miẕĕra֔yim wĕ⁠háyĕţá֤h ẖalĕẖáláh֙ bĕ̇⁠k֔ẇş̌ bi̇⁠nĕpò֥l ẖálá֖l bĕ̇⁠miẕĕrá֑yim wĕ⁠láqĕẖ֣ẇ hàmwòná֔⁠ḣ wĕ⁠neherĕs֖ẇ yĕswòdòţeֽy⁠há׃"],[30,5,"כּ֣וּשׁ וּ⁠פ֤וּט וְ⁠לוּד֙ וְ⁠כָל־הָ⁠עֶ֣רֶב וְ⁠כ֔וּב וּ⁠בְנֵ֖י אֶ֣רֶץ הַ⁠בְּרִ֑ית אִתָּ֖⁠ם בַּ⁠חֶ֥רֶב יִפֹּֽלוּ׃פ","k֣̇ẇş̌ ẇ⁠p֤ẇt wĕ⁠lẇd֙ wĕ⁠kál-há⁠ʻe֣reb wĕ⁠k֔ẇb ẇ⁠bĕné֖y ʼe֣reẕ ha⁠bĕ̇ri֑yţ ʼiţá֖̇⁠m bȧ⁠ẖe֥reb yipòֽ̇lẇ׃p"],[30,6,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה וְ⁠נָֽפְלוּ֙ סֹמְכֵ֣י מִצְרַ֔יִם וְ⁠יָרַ֖ד גְּא֣וֹן עֻזָּ֑⁠הּ מִ⁠מִּגְדֹּ֣ל סְוֵנֵ֗ה בַּ⁠חֶ֨רֶב֙ יִפְּלוּ־בָ֔⁠הּ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","kò֚̇h ʼáma֣r yĕhwá֔h wĕ⁠náֽpĕlẇ֙ sòmĕké֣y miẕĕra֔yim wĕ⁠yára֖d gĕ̇ʼ֣wòn ʻuzá֑̇⁠ḣ mi⁠mi̇gĕdò֣̇l sĕwéné֗h bȧ⁠ẖe֨reb֙ yipĕ̇lẇ-bá֔⁠ḣ nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[30,7,"וְ⁠נָשַׁ֕מּוּ בְּ⁠ת֖וֹךְ אֲרָצ֣וֹת נְשַׁמּ֑וֹת וְ⁠עָרָ֕י⁠ו בְּ⁠תוֹךְ־עָרִ֥ים נַחֲרָב֖וֹת תִּֽהְיֶֽינָה׃","wĕ⁠náşǎ֕ṁẇ bĕ̇⁠ţ֖wòkĕ ʼàráẕ֣wòţ nĕşǎṁ֑wòţ wĕ⁠ʻárá֕y⁠w bĕ̇⁠ţwòkĕ-ʻári֥ym naẖàráb֖wòţ ţiֽ̇hĕyeֽynáh׃"],[30,8,"וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֣י יְהוָ֑ה בְּ⁠תִתִּ⁠י־אֵ֣שׁ בְּ⁠מִצְרַ֔יִם וְ⁠נִשְׁבְּר֖וּ כָּל־עֹזְרֶֽי⁠הָ׃","wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֣y yĕhwá֑h bĕ̇⁠ţiţi̇⁠y-ʼé֣ş̌ bĕ̇⁠miẕĕra֔yim wĕ⁠nişĕ̌bĕ̇r֖ẇ ká̇l-ʻòzĕreֽy⁠há׃"],[30,9,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יֵצְא֨וּ מַלְאָכִ֤ים מִ⁠לְּ⁠פָנַ⁠י֙ בַּ⁠צִּ֔ים לְ⁠הַחֲרִ֖יד אֶת־כּ֣וּשׁ בֶּ֑טַח וְ⁠הָיְתָ֨ה חַלְחָלָ֤ה בָ⁠הֶם֙ בְּ⁠י֣וֹם מִצְרַ֔יִם כִּ֥י הִנֵּ֖ה בָּאָֽה׃ס","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yéẕĕʼ֨ẇ malĕʼáki֤ym mi⁠lĕ̇⁠pána⁠y֙ bȧ⁠ẕi̇֔ym lĕ⁠haẖàri֖yd ʼeţ-k֣̇ẇş̌ bė֑taẖ wĕ⁠háyĕţá֨h ẖalĕẖálá֤h bá⁠hem֙ bĕ̇⁠y֣wòm miẕĕra֔yim ki֥̇y hiné֖̇h bá̇ʼáֽh׃s"],[30,10,"כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה וְ⁠הִשְׁבַּתִּי֙ אֶת־הֲמ֣וֹן מִצְרַ֔יִם בְּ⁠יַ֖ד נְבוּכַדְרֶאצַּ֥ר מֶלֶךְ־בָּבֶֽל׃","kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h wĕ⁠hişĕ̌bȧţi̇y֙ ʼeţ-hàm֣wòn miẕĕra֔yim bĕ̇⁠ya֖d nĕbẇkadĕreʼẕȧ֥r melekĕ-bá̇beֽl׃"],[30,11,"ה֠וּא וְ⁠עַמּ֤⁠וֹ אִתּ⁠וֹ֙ עָרִיצֵ֣י גוֹיִ֔ם מֽוּבָאִ֖ים לְ⁠שַׁחֵ֣ת הָ⁠אָ֑רֶץ וְ⁠הֵרִ֤יקוּ חַרְבוֹתָ⁠ם֙ עַל־מִצְרַ֔יִם וּ⁠מָלְא֥וּ אֶת־הָ⁠אָ֖רֶץ חָלָֽל׃","h֠ẇʼ wĕ⁠ʻaṁ֤⁠wò ʼiţ̇⁠wò֙ ʻáriyẕé֣y gwòyi֔m mֽẇbáʼi֖ym lĕ⁠şǎẖé֣ţ há⁠ʼá֑reẕ wĕ⁠héri֤yqẇ ẖarĕbwòţá⁠m֙ ʻal-miẕĕra֔yim ẇ⁠málĕʼ֥ẇ ʼeţ-há⁠ʼá֖reẕ ẖáláֽl׃"],[30,12,"וְ⁠נָתַתִּ֤י יְאֹרִים֙ חָֽרָבָ֔ה וּ⁠מָכַרְתִּ֥י אֶת־הָ⁠אָ֖רֶץ בְּ⁠יַד־רָעִ֑ים וַ⁠הֲשִׁמֹּתִ֞י אֶ֤רֶץ וּ⁠מְלֹאָ⁠הּ֙ בְּ⁠יַד־זָרִ֔ים אֲנִ֥י יְהוָ֖ה דִּבַּֽרְתִּי׃ס","wĕ⁠náţaţi֤̇y yĕʼòriym֙ ẖáֽrábá֔h ẇ⁠mákarĕţi֥̇y ʼeţ-há⁠ʼá֖reẕ bĕ̇⁠yad-ráʻi֑ym wa⁠hàşǐmò̇ţi֞y ʼe֤reẕ ẇ⁠mĕlòʼá⁠ḣ֙ bĕ̇⁠yad-zári֔ym ʼàni֥y yĕhwá֖h di̇bȧֽrĕţi̇y׃s"],[30,13,"כֹּֽה־אָמַ֞ר אֲדֹנָ֣⁠י יְהוִ֗ה וְ⁠הַאֲבַדְתִּ֨י גִלּוּלִ֜ים וְ⁠הִשְׁבַּתִּ֤י אֱלִילִים֙ מִ⁠נֹּ֔ף וְ⁠נָשִׂ֥יא מֵ⁠אֶֽרֶץ־מִצְרַ֖יִם לֹ֣א יִֽהְיֶה־ע֑וֹד וְ⁠נָתַתִּ֥י יִרְאָ֖ה בְּ⁠אֶ֥רֶץ מִצְרָֽיִם׃","kòֽ̇h-ʼáma֞r ʼàdòná֣⁠y yĕhwi֗h wĕ⁠haʼàbadĕţi̇֨y gil̇ẇli֜ym wĕ⁠hişĕ̌bȧţi֤̇y ʼèliyliym֙ mi⁠nò̇֔p wĕ⁠náşî֥yʼ mé⁠ʼeֽreẕ-miẕĕra֖yim lò֣ʼ yiֽhĕyeh-ʻ֑wòd wĕ⁠náţaţi֥̇y yirĕʼá֖h bĕ̇⁠ʼe֥reẕ miẕĕráֽyim׃"],[30,14,"וַ⁠הֲשִׁמֹּתִי֙ אֶת־פַּתְר֔וֹס וְ⁠נָתַ֥תִּי אֵ֖שׁ בְּ⁠צֹ֑עַן וְ⁠עָשִׂ֥יתִי שְׁפָטִ֖ים בְּ⁠נֹֽא׃","wa⁠hàşǐmò̇ţiy֙ ʼeţ-pȧţĕr֔wòs wĕ⁠náţa֥ţi̇y ʼé֖ş̌ bĕ̇⁠ẕò֑ʻan wĕ⁠ʻáşî֥yţiy şĕ̌páti֖ym bĕ̇⁠nòֽʼ׃"],[30,15,"וְ⁠שָׁפַכְתִּ֣י חֲמָתִ֔⁠י עַל־סִ֖ין מָע֣וֹז מִצְרָ֑יִם וְ⁠הִכְרַתִּ֖י אֶת־הֲמ֥וֹן נֹֽא׃","wĕ⁠şá̌pakĕţi֣̇y ẖàmáţi֔⁠y ʻal-si֖yn máʻ֣wòz miẕĕrá֑yim wĕ⁠hikĕraţi֖̇y ʼeţ-hàm֥wòn nòֽʼ׃"],[30,16,"וְ⁠נָתַ֤תִּי אֵשׁ֙ בְּ⁠מִצְרַ֔יִם ח֤וּל תחיל סִ֔ין וְ⁠נֹ֖א תִּהְיֶ֣ה לְ⁠הִבָּקֵ֑עַ וְ⁠נֹ֖ף צָרֵ֥י יוֹמָֽם׃","wĕ⁠náţa֤ţi̇y ʼéş̌֙ bĕ̇⁠miẕĕra֔yim ẖ֤ẇl ţẖyl si֔yn wĕ⁠nò֖ʼ ţi̇hĕye֣h lĕ⁠hibá̇qé֑ʻa wĕ⁠nò֖p ẕáré֥y ywòmáֽm׃"],[30,17,"בַּח֥וּרֵי אָ֛וֶן וּ⁠פִי־בֶ֖סֶת בַּ⁠חֶ֣רֶב יִפֹּ֑לוּ וְ⁠הֵ֖נָּה בַּ⁠שְּׁבִ֥י תֵלַֽכְנָה׃","bȧẖ֥ẇréy ʼá֛wen ẇ⁠piy-be֖seţ bȧ⁠ẖe֣reb yipò֑̇lẇ wĕ⁠hé֖ná̇h bȧ⁠şĕ̇̌bi֥y ţélaֽkĕnáh׃"],[30,18,"וּ⁠בִֽ⁠תְחַפְנְחֵס֙ חָשַׂ֣ךְ הַ⁠יּ֔וֹם בְּ⁠שִׁבְרִ⁠י־שָׁם֙ אֶת־מֹט֣וֹת מִצְרַ֔יִם וְ⁠נִשְׁבַּת־בָּ֖⁠הּ גְּא֣וֹן עֻזָּ֑⁠הּ הִ֚יא עָנָ֣ן יְכַסֶּ֔⁠נָּה וּ⁠בְנוֹתֶ֖י⁠הָ בַּ⁠שְּׁבִ֥י תֵלַֽכְנָה׃","ẇ⁠biֽ⁠ţĕẖapĕnĕẖés֙ ẖáşâ֣kĕ ha⁠ẏ֔wòm bĕ̇⁠şǐbĕri⁠y-şá̌m֙ ʼeţ-mòt֣wòţ miẕĕra֔yim wĕ⁠nişĕ̌bȧţ-bá֖̇⁠ḣ gĕ̇ʼ֣wòn ʻuzá֑̇⁠ḣ hi֚yʼ ʻáná֣n yĕkasė֔⁠ná̇h ẇ⁠bĕnwòţe֖y⁠há bȧ⁠şĕ̇̌bi֥y ţélaֽkĕnáh׃"],[30,19,"וְ⁠עָשִׂ֥יתִי שְׁפָטִ֖ים בְּ⁠מִצְרָ֑יִם וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃פ","wĕ⁠ʻáşî֥yţiy şĕ̌páti֖ym bĕ̇⁠miẕĕrá֑yim wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃p"],[30,20,"וַ⁠יְהִ֗י בְּ⁠אַחַ֤ת עֶשְׂרֵה֙ שָׁנָ֔ה בָּֽ⁠רִאשׁ֖וֹן בְּ⁠שִׁבְעָ֣ה לַ⁠חֹ֑דֶשׁ הָיָ֥ה דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֗y bĕ̇⁠ʼaẖa֤ţ ʻeşĕ̂réh֙ şá̌ná֔h báֽ̇⁠riʼş֖̌wòn bĕ̇⁠şǐbĕʻá֣h la⁠ẖò֑deş̌ háyá֥h dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[30,21,"בֶּן־אָדָ֕ם אֶת־זְר֛וֹעַ פַּרְעֹ֥ה מֶֽלֶךְ־מִצְרַ֖יִם שָׁבָ֑רְתִּי וְ⁠הִנֵּ֣ה לֹֽא־חֻ֠בְּשָׁה לָ⁠תֵ֨ת רְפֻא֜וֹת לָ⁠שׂ֥וּם חִתּ֛וּל לְ⁠חָבְשָׁ֥⁠הּ לְ⁠חָזְקָ֖⁠הּ לִ⁠תְפֹּ֥שׂ בֶּ⁠חָֽרֶב׃ס","bėn-ʼádá֕m ʼeţ-zĕr֛wòʻa pȧrĕʻò֥h meֽlekĕ-miẕĕra֖yim şá̌bá֑rĕţi̇y wĕ⁠hiné֣̇h lòֽʼ-ẖu֠bĕ̇şá̌h lá⁠ţé֨ţ rĕpuʼ֜wòţ lá⁠ş֥̂ẇm ẖiţ֛̇ẇl lĕ⁠ẖábĕşá֥̌⁠ḣ lĕ⁠ẖázĕqá֖⁠ḣ li⁠ţĕpò֥̇ş̂ bė⁠ẖáֽreb׃s"],[30,22,"לָ⁠כֵ֞ן כֹּה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהֹוִ֗ה הִנְ⁠נִי֙ אֶל־פַּרְעֹ֣ה מֶֽלֶךְ־מִצְרַ֔יִם וְ⁠שָֽׁבַרְתִּי֙ אֶת־זְרֹ֣עֹתָ֔י⁠ו אֶת־הַ⁠חֲזָקָ֖ה וְ⁠אֶת־הַ⁠נִּשְׁבָּ֑רֶת וְ⁠הִפַּלְתִּ֥י אֶת־הַ⁠חֶ֖רֶב מִ⁠יָּדֽ⁠וֹ׃","lá⁠ké֞n kò̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhòwi֗h hinĕ⁠niy֙ ʼel-pȧrĕʻò֣h meֽlekĕ-miẕĕra֔yim wĕ⁠şáֽ̌barĕţi̇y֙ ʼeţ-zĕrò֣ʻòţá֔y⁠w ʼeţ-ha⁠ẖàzáqá֖h wĕ⁠ʼeţ-ha⁠ni̇şĕ̌bá֑̇reţ wĕ⁠hipȧlĕţi֥̇y ʼeţ-ha⁠ẖe֖reb mi⁠yá̇dֽ⁠wò׃"],[30,23,"וַ⁠הֲפִצוֹתִ֥י אֶת־מִצְרַ֖יִם בַּ⁠גּוֹיִ֑ם וְ⁠זֵרִיתִ֖⁠ם בָּ⁠אֲרָצֽוֹת׃","wa⁠hàpiẕwòţi֥y ʼeţ-miẕĕra֖yim bȧ⁠ġwòyi֑m wĕ⁠zériyţi֖⁠m bá̇⁠ʼàráẕֽwòţ׃"],[30,24,"וְ⁠חִזַּקְתִּ֗י אֶת־זְרֹעוֹת֙ מֶ֣לֶךְ בָּבֶ֔ל וְ⁠נָתַתִּ֥י אֶת־חַרְבִּ֖⁠י בְּ⁠יָד֑⁠וֹ וְ⁠שָׁבַרְתִּי֙ אֶת־זְרֹע֣וֹת פַּרְעֹ֔ה וְ⁠נָאַ֛ק נַאֲק֥וֹת חָלָ֖ל לְ⁠פָנָֽי⁠ו׃","wĕ⁠ẖizȧqĕţi̇֗y ʼeţ-zĕròʻwòţ֙ me֣lekĕ bá̇be֔l wĕ⁠náţaţi֥̇y ʼeţ-ẖarĕbi֖̇⁠y bĕ̇⁠yád֑⁠wò wĕ⁠şá̌barĕţi̇y֙ ʼeţ-zĕròʻ֣wòţ pȧrĕʻò֔h wĕ⁠náʼa֛q naʼàq֥wòţ ẖálá֖l lĕ⁠pánáֽy⁠w׃"],[30,25,"וְ⁠הַחֲזַקְתִּ֗י אֶת־זְרֹעוֹת֙ מֶ֣לֶךְ בָּבֶ֔ל וּ⁠זְרֹע֥וֹת פַּרְעֹ֖ה תִּפֹּ֑לְנָה וְֽ⁠יָדְע֞וּ כִּֽי־אֲנִ֣י יְהוָ֗ה בְּ⁠תִתִּ֤⁠י חַרְבִּ⁠י֙ בְּ⁠יַ֣ד מֶֽלֶךְ־בָּבֶ֔ל וְ⁠נָטָ֥ה אוֹתָ֖⁠הּ אֶל־אֶ֥רֶץ מִצְרָֽיִם׃","wĕ⁠haẖàzaqĕţi̇֗y ʼeţ-zĕròʻwòţ֙ me֣lekĕ bá̇be֔l ẇ⁠zĕròʻ֥wòţ pȧrĕʻò֖h ţi̇pò֑̇lĕnáh wĕֽ⁠yádĕʻ֞ẇ kiֽ̇y-ʼàni֣y yĕhwá֗h bĕ̇⁠ţiţi֤̇⁠y ẖarĕbi̇⁠y֙ bĕ̇⁠ya֣d meֽlekĕ-bá̇be֔l wĕ⁠nátá֥h ʼwòţá֖⁠ḣ ʼel-ʼe֥reẕ miẕĕráֽyim׃"],[30,26,"וַ⁠הֲפִצוֹתִ֤י אֶת־מִצְרַ֨יִם֙ בַּ⁠גּוֹיִ֔ם וְ⁠זֵרִיתִ֥י אוֹתָ֖⁠ם בָּ⁠אֲרָצ֑וֹת וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃ס","wa⁠hàpiẕwòţi֤y ʼeţ-miẕĕra֨yim֙ bȧ⁠ġwòyi֔m wĕ⁠zériyţi֥y ʼwòţá֖⁠m bá̇⁠ʼàráẕ֑wòţ wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃s"],[31,1,"וַ⁠יְהִ֗י בְּ⁠אַחַ֤ת עֶשְׂרֵה֙ שָׁנָ֔ה בַּ⁠שְּׁלִישִׁ֖י בְּ⁠אֶחָ֣ד לַ⁠חֹ֑דֶשׁ הָיָ֥ה דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֗y bĕ̇⁠ʼaẖa֤ţ ʻeşĕ̂réh֙ şá̌ná֔h bȧ⁠şĕ̇̌liyşǐ֖y bĕ̇⁠ʼeẖá֣d la⁠ẖò֑deş̌ háyá֥h dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[31,2,"בֶּן־אָדָ֕ם אֱמֹ֛ר אֶל־פַּרְעֹ֥ה מֶֽלֶךְ־מִצְרַ֖יִם וְ⁠אֶל־הֲמוֹנ֑⁠וֹ אֶל־מִ֖י דָּמִ֥יתָ בְ⁠גָדְלֶֽ⁠ךָ׃","bėn-ʼádá֕m ʼèmò֛r ʼel-pȧrĕʻò֥h meֽlekĕ-miẕĕra֖yim wĕ⁠ʼel-hàmwòn֑⁠wò ʼel-mi֖y dá̇mi֥yţá bĕ⁠gádĕleֽ⁠ká׃"],[31,3,"הִנֵּ֨ה אַשּׁ֜וּר אֶ֣רֶז בַּ⁠לְּבָנ֗וֹן יְפֵ֥ה עָנָ֛ף וְ⁠חֹ֥רֶשׁ מֵצַ֖ל וּ⁠גְבַ֣הּ קוֹמָ֑ה וּ⁠בֵ֣ין עֲבֹתִ֔ים הָיְתָ֖ה צַמַּרְתּֽ⁠וֹ׃","hiné̇֨h ʼaş̇̌֜ẇr ʼe֣rez bȧ⁠lĕ̇bán֗wòn yĕpé֥h ʻáná֛p wĕ⁠ẖò֥reş̌ méẕa֖l ẇ⁠gĕba֣ḣ qwòmá֑h ẇ⁠bé֣yn ʻàbòţi֔ym háyĕţá֖h ẕamȧrĕţֽ̇⁠wò׃"],[31,4,"מַ֣יִם גִּדְּל֔וּ⁠הוּ תְּה֖וֹם רֹֽמְמָ֑תְ⁠הוּ אֶת־נַהֲרֹתֶ֗י⁠הָ הֹלֵךְ֙ סְבִיב֣וֹת מַטָּעָ֔⁠הּ וְ⁠אֶת־תְּעָלֹתֶ֣י⁠הָ שִׁלְחָ֔ה אֶ֖ל כָּל־עֲצֵ֥י הַ⁠שָּׂדֶֽה׃","ma֣yim gi̇dĕ̇l֔ẇ⁠hẇ ţĕ̇h֖wòm ròֽmĕmá֑ţĕ⁠hẇ ʼeţ-nahàròţe֗y⁠há hòlékĕ֙ sĕbiyb֣wòţ matá̇ʻá֔⁠ḣ wĕ⁠ʼeţ-ţĕ̇ʻálòţe֣y⁠há şǐlĕẖá֔h ʼe֖l ká̇l-ʻàẕé֥y ha⁠şá̇̂deֽh׃"],[31,5,"עַל־כֵּן֙ גָּבְהָ֣א קֹמָת֔⁠וֹ מִ⁠כֹּ֖ל עֲצֵ֣י הַ⁠שָּׂדֶ֑ה וַ⁠תִּרְבֶּ֨ינָה סַֽרְעַפֹּתָ֜י⁠ו וַ⁠תֶּאֱרַ֧כְנָה פארת⁠ו מִ⁠מַּ֥יִם רַבִּ֖ים בְּ⁠שַׁלְּחֽ⁠וֹ׃","ʻal-ké̇n֙ gá̇bĕhá֣ʼ qòmáţ֔⁠wò mi⁠kò֖̇l ʻàẕé֣y ha⁠şá̇̂de֑h wa⁠ţi̇rĕbė֨ynáh saֽrĕʻapò̇ţá֜y⁠w wa⁠ţėʼèra֧kĕnáh pʼrţ⁠w mi⁠mȧ֥yim rabi֖̇ym bĕ̇⁠şǎlĕ̇ẖֽ⁠wò׃"],[31,6,"בִּ⁠סְעַפֹּתָ֤י⁠ו קִֽנְנוּ֙ כָּל־ע֣וֹף הַ⁠שָּׁמַ֔יִם וְ⁠תַ֤חַת פֹּֽארֹתָי⁠ו֙ יָֽלְד֔וּ כֹּ֖ל חַיַּ֣ת הַ⁠שָּׂדֶ֑ה וּ⁠בְ⁠צִלּ⁠וֹ֙ יֵֽשְׁב֔וּ כֹּ֖ל גּוֹיִ֥ם רַבִּֽים׃","bi̇⁠sĕʻapò̇ţá֤y⁠w qiֽnĕnẇ֙ ká̇l-ʻ֣wòp ha⁠şá̇̌ma֔yim wĕ⁠ţa֤ẖaţ pòֽ̇ʼròţáy⁠w֙ yáֽlĕd֔ẇ kò֖̇l ẖayȧ֣ţ ha⁠şá̇̂de֑h ẇ⁠bĕ⁠ẕil̇⁠wò֙ yéֽşĕ̌b֔ẇ kò֖̇l ġwòyi֥m rabiֽ̇ym׃"],[31,7,"וַ⁠יְּיִ֣ף בְּ⁠גָדְל֔⁠וֹ בְּ⁠אֹ֖רֶךְ דָּֽלִיּוֹתָ֑י⁠ו כִּֽי־הָיָ֥ה שָׁרְשׁ֖⁠וֹ אֶל־מַ֥יִם רַבִּֽים׃","wa⁠yĕ̇yi֣p bĕ̇⁠gádĕl֔⁠wò bĕ̇⁠ʼò֖rekĕ dáֽ̇liẏwòţá֑y⁠w kiֽ̇y-háyá֥h şá̌rĕş֖̌⁠wò ʼel-ma֥yim rabiֽ̇ym׃"],[31,8,"אֲרָזִ֣ים לֹֽא־עֲמָמֻ⁠הוּ֮ בְּ⁠גַן־אֱלֹהִים֒ בְּרוֹשִׁ֗ים לֹ֤א דָמוּ֙ אֶל־סְעַפֹּתָ֔י⁠ו וְ⁠עַרְמֹנִ֥ים לֹֽא־הָי֖וּ כְּ⁠פֹֽארֹתָ֑י⁠ו כָּל־עֵץ֙ בְּ⁠גַן־אֱלֹהִ֔ים לֹא־דָמָ֥ה אֵלָ֖י⁠ו בְּ⁠יָפְיֽ⁠וֹ׃","ʼàrázi֣ym lòֽʼ-ʻàmámu⁠hẇ֮ bĕ̇⁠gan-ʼèlòhiym֒ bĕ̇rwòşǐ֗ym lò֤ʼ dámẇ֙ ʼel-sĕʻapò̇ţá֔y⁠w wĕ⁠ʻarĕmòni֥ym lòֽʼ-háy֖ẇ kĕ̇⁠pòֽʼròţá֑y⁠w ká̇l-ʻéẕ֙ bĕ̇⁠gan-ʼèlòhi֔ym lòʼ-dámá֥h ʼélá֖y⁠w bĕ̇⁠yápĕyֽ⁠wò׃"],[31,9,"יָפֶ֣ה עֲשִׂיתִ֔י⁠ו בְּ⁠רֹ֖ב דָּֽלִיּוֹתָ֑י⁠ו וַ⁠יְקַנְאֻ֨⁠הוּ֙ כָּל־עֲצֵי־עֵ֔דֶן אֲשֶׁ֖ר בְּ⁠גַ֥ן הָ⁠אֱלֹהִֽים׃ס","yápe֣h ʻàşîyţi֔y⁠w bĕ̇⁠rò֖b dáֽ̇liẏwòţá֑y⁠w wa⁠yĕqanĕʼu֨⁠hẇ֙ ká̇l-ʻàẕéy-ʻé֔den ʼàşě֖r bĕ̇⁠ga֥n há⁠ʼèlòhiֽym׃s"],[31,10,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה יַ֕עַן אֲשֶׁ֥ר גָּבַ֖הְתָּ בְּ⁠קוֹמָ֑ה וַ⁠יִּתֵּ֤ן צַמַּרְתּ⁠וֹ֙ אֶל־בֵּ֣ין עֲבוֹתִ֔ים וְ⁠רָ֥ם לְבָב֖⁠וֹ בְּ⁠גָבְהֽ⁠וֹ׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ya֕ʻan ʼàşě֥r gá̇ba֖hĕţá̇ bĕ̇⁠qwòmá֑h wa⁠yi̇ţé֤̇n ẕamȧrĕţ̇⁠wò֙ ʼel-bé֣̇yn ʻàbwòţi֔ym wĕ⁠rá֥m lĕbáb֖⁠wò bĕ̇⁠gábĕhֽ⁠wò׃"],[31,11,"וְ⁠אֶ֨תְּנֵ֔⁠הוּ בְּ⁠יַ֖ד אֵ֣יל גּוֹיִ֑ם עָשׂ֤וֹ יַֽעֲשֶׂה֙ ל֔⁠וֹ כְּ⁠רִשְׁע֖⁠וֹ גֵּרַשְׁתִּֽ⁠הוּ׃","wĕ⁠ʼe֨ţĕ̇né֔⁠hẇ bĕ̇⁠ya֖d ʼé֣yl ġwòyi֑m ʻáş֤̂wò yaֽʻàşêh֙ l֔⁠wò kĕ̇⁠rişĕ̌ʻ֖⁠wò gé̇raşĕ̌ţiֽ̇⁠hẇ׃"],[31,12,"וַ⁠יִּכְרְתֻ֧⁠הוּ זָרִ֛ים עָרִיצֵ֥י גוֹיִ֖ם וַֽ⁠יִּטְּשֻׁ֑⁠הוּ אֶל־הֶ֠⁠הָרִים וּ⁠בְ⁠כָל־גֵּ֨אָי֜וֹת נָפְל֣וּ דָלִיּוֹתָ֗י⁠ו וַ⁠תִּשָּׁבַ֤רְנָה פֹֽארֹתָי⁠ו֙ בְּ⁠כֹל֙ אֲפִיקֵ֣י הָ⁠אָ֔רֶץ וַ⁠יֵּרְד֧וּ מִ⁠צִּלּ֛⁠וֹ כָּל־עַמֵּ֥י הָ⁠אָ֖רֶץ וַֽ⁠יִּטְּשֻֽׁ⁠הוּ׃","wa⁠yi̇kĕrĕţu֧⁠hẇ zári֛ym ʻáriyẕé֥y gwòyi֖m waֽ⁠yi̇tĕ̇şǔ֑⁠hẇ ʼel-he֠⁠háriym ẇ⁠bĕ⁠kál-gé̇֨ʼáy֜wòţ nápĕl֣ẇ dáliẏwòţá֗y⁠w wa⁠ţi̇şá̇̌ba֤rĕnáh pòֽʼròţáy⁠w֙ bĕ̇⁠kòl֙ ʼàpiyqé֣y há⁠ʼá֔reẕ wa⁠yé̇rĕd֧ẇ mi⁠ẕi̇l֛̇⁠wò ká̇l-ʻamé֥̇y há⁠ʼá֖reẕ waֽ⁠yi̇tĕ̇şǔֽ⁠hẇ׃"],[31,13,"עַל־מַפַּלְתּ֥⁠וֹ יִשְׁכְּנ֖וּ כָּל־ע֣וֹף הַ⁠שָּׁמָ֑יִם וְ⁠אֶל־פֹּארֹתָ֣י⁠ו הָי֔וּ כֹּ֖ל חַיַּ֥ת הַ⁠שָּׂדֶֽה׃","ʻal-mapȧlĕţ֥̇⁠wò yişĕ̌kĕ̇n֖ẇ ká̇l-ʻ֣wòp ha⁠şá̇̌má֑yim wĕ⁠ʼel-pò̇ʼròţá֣y⁠w háy֔ẇ kò֖̇l ẖayȧ֥ţ ha⁠şá̇̂deֽh׃"],[31,14,"לְמַ֡עַן אֲשֶׁר֩ לֹא־יִגְבְּה֨וּ בְ⁠קוֹמָתָ֜⁠ם כָּל־עֲצֵי־מַ֗יִם וְ⁠לֹֽא־יִתְּנ֤וּ אֶת־צַמַּרְתָּ⁠ם֙ אֶל־בֵּ֣ין עֲבֹתִ֔ים וְ⁠לֹֽא־יַעַמְד֧וּ אֵלֵי⁠הֶ֛ם בְּ⁠גָבְהָ֖⁠ם כָּל־שֹׁ֣תֵי מָ֑יִם כִּֽי־כֻלָּ⁠ם֩ נִתְּנ֨וּ לַ⁠מָּ֜וֶת אֶל־אֶ֣רֶץ תַּחְתִּ֗ית בְּ⁠ת֛וֹךְ בְּנֵ֥י אָדָ֖ם אֶל־י֥וֹרְדֵי בֽוֹר׃ס","lĕma֡ʻan ʼàşěr֩ lòʼ-yigĕbĕ̇h֨ẇ bĕ⁠qwòmáţá֜⁠m ká̇l-ʻàẕéy-ma֗yim wĕ⁠lòֽʼ-yiţĕ̇n֤ẇ ʼeţ-ẕamȧrĕţá̇⁠m֙ ʼel-bé֣̇yn ʻàbòţi֔ym wĕ⁠lòֽʼ-yaʻamĕd֧ẇ ʼéléy⁠he֛m bĕ̇⁠gábĕhá֖⁠m ká̇l-şò֣̌ţéy má֑yim kiֽ̇y-kulá̇⁠m֩ niţĕ̇n֨ẇ la⁠má̇֜weţ ʼel-ʼe֣reẕ ţȧẖĕţi̇֗yţ bĕ̇⁠ţ֛wòkĕ bĕ̇né֥y ʼádá֖m ʼel-y֥wòrĕdéy bֽwòr׃s"],[31,15,"כֹּֽה־אָמַ֞ר אֲדֹנָ֣⁠י יְהוִ֗ה בְּ⁠י֨וֹם רִדְתּ֤⁠וֹ שְׁא֨וֹלָ⁠ה֙ הֶאֱבַ֜לְתִּי כִּסֵּ֤תִי עָלָי⁠ו֙ אֶת־תְּה֔וֹם וָֽ⁠אֶמְנַע֙ נַהֲרוֹתֶ֔י⁠הָ וַ⁠יִּכָּלְא֖וּ מַ֣יִם רַבִּ֑ים וָ⁠אַקְדִּ֤ר עָלָי⁠ו֙ לְבָנ֔וֹן וְ⁠כָל־עֲצֵ֥י הַ⁠שָּׂדֶ֖ה עָלָ֥י⁠ו עֻלְפֶּֽה׃","kòֽ̇h-ʼáma֞r ʼàdòná֣⁠y yĕhwi֗h bĕ̇⁠y֨wòm ridĕţ֤̇⁠wò şĕ̌ʼ֨wòlá⁠h֙ heʼèba֜lĕţi̇y ki̇sé֤̇ţiy ʻáláy⁠w֙ ʼeţ-ţĕ̇h֔wòm wáֽ⁠ʼemĕnaʻ֙ nahàrwòţe֔y⁠há wa⁠yi̇ká̇lĕʼ֖ẇ ma֣yim rabi֑̇ym wá⁠ʼaqĕdi֤̇r ʻáláy⁠w֙ lĕbán֔wòn wĕ⁠kál-ʻàẕé֥y ha⁠şá̇̂de֖h ʻálá֥y⁠w ʻulĕpėֽh׃"],[31,16,"מִ⁠קּ֤וֹל מַפַּלְתּ⁠וֹ֙ הִרְעַ֣שְׁתִּי גוֹיִ֔ם בְּ⁠הוֹרִדִ֥⁠י אֹת֛⁠וֹ שְׁא֖וֹלָ⁠ה אֶת־י֣וֹרְדֵי ב֑וֹר וַ⁠יִּנָּ֨חֲמ֜וּ בְּ⁠אֶ֤רֶץ תַּחְתִּית֙ כָּל־עֲצֵי־עֵ֔דֶן מִבְחַ֥ר וְ⁠טוֹב־לְבָנ֖וֹן כָּל־שֹׁ֥תֵי מָֽיִם׃","mi⁠q֤̇wòl mapȧlĕţ̇⁠wò֙ hirĕʻa֣şĕ̌ţi̇y gwòyi֔m bĕ̇⁠hwòridi֥⁠y ʼòţ֛⁠wò şĕ̌ʼ֖wòlá⁠h ʼeţ-y֣wòrĕdéy b֑wòr wa⁠yi̇ná̇֨ẖàm֜ẇ bĕ̇⁠ʼe֤reẕ ţȧẖĕţi̇yţ֙ ká̇l-ʻàẕéy-ʻé֔den mibĕẖa֥r wĕ⁠twòb-lĕbán֖wòn ká̇l-şò֥̌ţéy máֽyim׃"],[31,17,"גַּם־הֵ֗ם אִתּ֛⁠וֹ יָרְד֥וּ שְׁא֖וֹלָ⁠ה אֶל־חַלְלֵי־חָ֑רֶב וּ⁠זְרֹע֛⁠וֹ יָשְׁב֥וּ בְ⁠צִלּ֖⁠וֹ בְּ⁠ת֥וֹךְ גּוֹיִֽם׃","gȧm-hé֗m ʼiţ֛̇⁠wò yárĕd֥ẇ şĕ̌ʼ֖wòlá⁠h ʼel-ẖalĕléy-ẖá֑reb ẇ⁠zĕròʻ֛⁠wò yáşĕ̌b֥ẇ bĕ⁠ẕil֖̇⁠wò bĕ̇⁠ţ֥wòkĕ ġwòyiֽm׃"],[31,18,"אֶל־מִ֨י דָמִ֥יתָ כָּ֛כָה בְּ⁠כָב֥וֹד וּ⁠בְ⁠גֹ֖דֶל בַּ⁠עֲצֵי־עֵ֑דֶן וְ⁠הוּרַדְתָּ֨ אֶת־עֲצֵי־עֵ֜דֶן אֶל־אֶ֣רֶץ תַּחְתִּ֗ית בְּ⁠ת֨וֹךְ עֲרֵלִ֤ים תִּשְׁכַּב֙ אֶת־חַלְלֵי־חֶ֔רֶב ה֤וּא פַרְעֹה֙ וְ⁠כָל־הֲמוֹנֹ֔⁠ה נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","ʼel-mi֨y dámi֥yţá ká֛̇káh bĕ̇⁠káb֥wòd ẇ⁠bĕ⁠gò֖del bȧ⁠ʻàẕéy-ʻé֑den wĕ⁠hẇradĕţá̇֨ ʼeţ-ʻàẕéy-ʻé֜den ʼel-ʼe֣reẕ ţȧẖĕţi̇֗yţ bĕ̇⁠ţ֨wòkĕ ʻàréli֤ym ţi̇şĕ̌kȧb֙ ʼeţ-ẖalĕléy-ẖe֔reb h֤ẇʼ parĕʻòh֙ wĕ⁠kál-hàmwònò֔⁠h nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[32,1,"וַֽ⁠יְהִי֙ בִּ⁠שְׁתֵּ֣י עֶשְׂרֵ֣ה שָׁנָ֔ה בִּ⁠שְׁנֵי־עָשָׂ֥ר חֹ֖דֶשׁ בְּ⁠אֶחָ֣ד לַ⁠חֹ֑דֶשׁ הָיָ֥ה דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ bi̇⁠şĕ̌ţé֣̇y ʻeşĕ̂ré֣h şá̌ná֔h bi̇⁠şĕ̌néy-ʻáşá֥̂r ẖò֖deş̌ bĕ̇⁠ʼeẖá֣d la⁠ẖò֑deş̌ háyá֥h dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[32,2,"בֶּן־אָדָ֗ם שָׂ֤א קִינָה֙ עַל־פַּרְעֹ֣ה מֶֽלֶךְ־מִצְרַ֔יִם וְ⁠אָמַרְתָּ֣ אֵלָ֔י⁠ו כְּפִ֥יר גּוֹיִ֖ם נִדְמֵ֑יתָ וְ⁠אַתָּה֙ כַּ⁠תַּנִּ֣ים בַּ⁠יַּמִּ֔ים וַ⁠תָּ֣גַח בְּ⁠נַהֲרוֹתֶ֗י⁠ךָ וַ⁠תִּדְלַח־מַ֨יִם֙ בְּ⁠רַגְלֶ֔י⁠ךָ וַ⁠תִּרְפֹּ֖ס נַהֲרוֹתָֽ⁠ם׃","bėn-ʼádá֗m şá֤̂ʼ qiynáh֙ ʻal-pȧrĕʻò֣h meֽlekĕ-miẕĕra֔yim wĕ⁠ʼámarĕţá֣̇ ʼélá֔y⁠w kĕ̇pi֥yr ġwòyi֖m nidĕmé֑yţá wĕ⁠ʼaţá̇h֙ kȧ⁠ţȧni֣̇ym bȧ⁠yȧmi̇֔ym wa⁠ţá֣̇gaẖ bĕ̇⁠nahàrwòţe֗y⁠ká wa⁠ţi̇dĕlaẖ-ma֨yim֙ bĕ̇⁠ragĕle֔y⁠ká wa⁠ţi̇rĕpò֖̇s nahàrwòţáֽ⁠m׃"],[32,3,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה וּ⁠פָרַשְׂתִּ֤י עָלֶ֨י⁠ךָ֙ אֶת־רִשְׁתִּ֔⁠י בִּ⁠קְהַ֖ל עַמִּ֣ים רַבִּ֑ים וְ⁠הֶעֱל֖וּ⁠ךָ בְּ⁠חֶרְמִֽ⁠י׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ẇ⁠páraşĕ̂ţi֤̇y ʻále֨y⁠ká֙ ʼeţ-rişĕ̌ţi̇֔⁠y bi̇⁠qĕha֖l ʻami֣̇ym rabi֑̇ym wĕ⁠heʻèl֖ẇ⁠ká bĕ̇⁠ẖerĕmiֽ⁠y׃"],[32,4,"וּ⁠נְטַשְׁתִּ֣י⁠ךָ בָ⁠אָ֔רֶץ עַל־פְּנֵ֥י הַ⁠שָּׂדֶ֖ה אֲטִילֶ֑⁠ךָ וְ⁠הִשְׁכַּנְתִּ֤י עָלֶ֨י⁠ךָ֙ כָּל־ע֣וֹף הַ⁠שָּׁמַ֔יִם וְ⁠הִשְׂבַּעְתִּ֥י מִמְּ⁠ךָ֖ חַיַּ֥ת כָּל־הָ⁠אָֽרֶץ׃","ẇ⁠nĕtaşĕ̌ţi֣̇y⁠ká bá⁠ʼá֔reẕ ʻal-pĕ̇né֥y ha⁠şá̇̂de֖h ʼàtiyle֑⁠ká wĕ⁠hişĕ̌kȧnĕţi֤̇y ʻále֨y⁠ká֙ ká̇l-ʻ֣wòp ha⁠şá̇̌ma֔yim wĕ⁠hişĕ̂bȧʻĕţi֥̇y mimĕ̇⁠ká֖ ẖayȧ֥ţ ká̇l-há⁠ʼáֽreẕ׃"],[32,5,"וְ⁠נָתַתִּ֥י אֶת־בְּשָׂרְ⁠ךָ֖ עַל־הֶֽ⁠הָרִ֑ים וּ⁠מִלֵּאתִ֥י הַ⁠גֵּאָי֖וֹת רָמוּתֶֽ⁠ךָ׃","wĕ⁠náţaţi֥̇y ʼeţ-bĕ̇şá̂rĕ⁠ká֖ ʻal-heֽ⁠hári֑ym ẇ⁠milé̇ʼţi֥y ha⁠gé̇ʼáy֖wòţ rámẇţeֽ⁠ká׃"],[32,6,"וְ⁠הִשְׁקֵיתִ֨י אֶ֧רֶץ צָפָתְ⁠ךָ֛ מִ⁠דָּמְ⁠ךָ֖ אֶל־הֶֽ⁠הָרִ֑ים וַ⁠אֲפִקִ֖ים יִמָּלְא֥וּ⁠ן מִמֶּֽ⁠ךָּ׃","wĕ⁠hişĕ̌qéyţi֨y ʼe֧reẕ ẕápáţĕ⁠ká֛ mi⁠dá̇mĕ⁠ká֖ ʼel-heֽ⁠hári֑ym wa⁠ʼàpiqi֖ym yimá̇lĕʼ֥ẇ⁠n mimėֽ⁠ká̇׃"],[32,7,"וְ⁠כִסֵּיתִ֤י בְ⁠כַבּֽוֹתְ⁠ךָ֙ שָׁמַ֔יִם וְ⁠הִקְדַּרְתִּ֖י אֶת־כֹּֽכְבֵי⁠הֶ֑ם שֶׁ֚מֶשׁ בֶּ⁠עָנָ֣ן אֲכַסֶּ֔⁠נּוּ וְ⁠יָרֵ֖חַ לֹא־יָאִ֥יר אוֹרֽ⁠וֹ׃","wĕ⁠kisé̇yţi֤y bĕ⁠kaḃֽwòţĕ⁠ká֙ şá̌ma֔yim wĕ⁠hiqĕdȧrĕţi֖̇y ʼeţ-kòֽ̇kĕbéy⁠he֑m şě֚meş̌ bė⁠ʻáná֣n ʼàkasė֔⁠ṅẇ wĕ⁠yáré֖ẖa lòʼ-yáʼi֥yr ʼwòrֽ⁠wò׃"],[32,8,"כָּל־מְא֤וֹרֵי אוֹר֙ בַּ⁠שָּׁמַ֔יִם אַקְדִּירֵ֖⁠ם עָלֶ֑י⁠ךָ וְ⁠נָתַ֤תִּי חֹ֨שֶׁךְ֙ עַֽל־אַרְצְ⁠ךָ֔ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","ká̇l-mĕʼ֤wòréy ʼwòr֙ bȧ⁠şá̇̌ma֔yim ʼaqĕdi̇yré֖⁠m ʻále֑y⁠ká wĕ⁠náţa֤ţi̇y ẖò֨şěkĕ֙ ʻaֽl-ʼarĕẕĕ⁠ká֔ nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[32,9,"וְ⁠הִ֨כְעַסְתִּ֔י לֵ֖ב עַמִּ֣ים רַבִּ֑ים בַּ⁠הֲבִיאִ֤⁠י שִׁבְרְ⁠ךָ֙ בַּ⁠גּוֹיִ֔ם עַל־אֲרָצ֖וֹת אֲשֶׁ֥ר לֹֽא־יְדַעְתָּֽ⁠ם׃","wĕ⁠hi֨kĕʻasĕţi̇֔y lé֖b ʻami֣̇ym rabi֑̇ym bȧ⁠hàbiyʼi֤⁠y şǐbĕrĕ⁠ká֙ bȧ⁠ġwòyi֔m ʻal-ʼàráẕ֖wòţ ʼàşě֥r lòֽʼ-yĕdaʻĕţáֽ̇⁠m׃"],[32,10,"וַ⁠הֲשִׁמּוֹתִ֨י עָלֶ֜י⁠ךָ עַמִּ֣ים רַבִּ֗ים וּ⁠מַלְכֵי⁠הֶם֙ יִשְׂעֲר֤וּ עָלֶ֨י⁠ךָ֙ שַׂ֔עַר בְּ⁠עוֹפְפִ֥⁠י חַרְבִּ֖⁠י עַל־פְּנֵי⁠הֶ֑ם וְ⁠חָרְד֤וּ לִ⁠רְגָעִים֙ אִ֣ישׁ לְ⁠נַפְשׁ֔⁠וֹ בְּ⁠י֖וֹם מַפַּלְתֶּֽ⁠ךָ׃ס","wa⁠hàşǐṁwòţi֨y ʻále֜y⁠ká ʻami֣̇ym rabi̇֗ym ẇ⁠malĕkéy⁠hem֙ yişĕ̂ʻàr֤ẇ ʻále֨y⁠ká֙ şâ֔ʻar bĕ̇⁠ʻwòpĕpi֥⁠y ẖarĕbi֖̇⁠y ʻal-pĕ̇néy⁠he֑m wĕ⁠ẖárĕd֤ẇ li⁠rĕgáʻiym֙ ʼi֣yş̌ lĕ⁠napĕş̌֔⁠wò bĕ̇⁠y֖wòm mapȧlĕţėֽ⁠ká׃s"],[32,11,"כִּ֛י כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה חֶ֥רֶב מֶֽלֶךְ־בָּבֶ֖ל תְּבוֹאֶֽ⁠ךָ׃","ki֛̇y kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h ẖe֥reb meֽlekĕ-bá̇be֖l ţĕ̇bwòʼeֽ⁠ká׃"],[32,12,"בְּ⁠חַרְב֤וֹת גִּבּוֹרִים֙ אַפִּ֣יל הֲמוֹנֶ֔⁠ךָ עָרִיצֵ֥י גוֹיִ֖ם כֻּלָּ֑⁠ם וְ⁠שָֽׁדְדוּ֙ אֶת־גְּא֣וֹן מִצְרַ֔יִם וְ⁠נִשְׁמַ֖ד כָּל־הֲמוֹנָֽ⁠הּ׃","bĕ̇⁠ẖarĕb֤wòţ gi̇ḃwòriym֙ ʼapi֣̇yl hàmwòne֔⁠ká ʻáriyẕé֥y gwòyi֖m ku̇lá֑̇⁠m wĕ⁠şáֽ̌dĕdẇ֙ ʼeţ-gĕ̇ʼ֣wòn miẕĕra֔yim wĕ⁠nişĕ̌ma֖d ká̇l-hàmwònáֽ⁠ḣ׃"],[32,13,"וְ⁠הַֽאֲבַדְתִּי֙ אֶת־כָּל־בְּהֶמְתָּ֔⁠הּ מֵ⁠עַ֖ל מַ֣יִם רַבִּ֑ים וְ⁠לֹ֨א תִדְלָחֵ֤⁠ם רֶֽגֶל־אָדָם֙ ע֔וֹד וּ⁠פַרְס֥וֹת בְּהֵמָ֖ה לֹ֥א תִדְלָחֵֽ⁠ם׃","wĕ⁠haֽʼàbadĕţi̇y֙ ʼeţ-ká̇l-bĕ̇hemĕţá̇֔⁠ḣ mé⁠ʻa֖l ma֣yim rabi֑̇ym wĕ⁠lò֨ʼ ţidĕláẖé֤⁠m reֽgel-ʼádám֙ ʻ֔wòd ẇ⁠parĕs֥wòţ bĕ̇hémá֖h lò֥ʼ ţidĕláẖéֽ⁠m׃"],[32,14,"אָ֚ז אַשְׁקִ֣יעַ מֵֽימֵי⁠הֶ֔ם וְ⁠נַהֲרוֹתָ֖⁠ם כַּ⁠שֶּׁ֣מֶן אוֹלִ֑יךְ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","ʼá֚z ʼaşĕ̌qi֣yʻa méֽyméy⁠he֔m wĕ⁠nahàrwòţá֖⁠m kȧ⁠şė֣̌men ʼwòli֑ykĕ nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[32,15,"בְּ⁠תִתִּ⁠י֩ אֶת־אֶ֨רֶץ מִצְרַ֜יִם שְׁמָמָ֣ה וּ⁠נְשַׁמָּ֗ה אֶ֚רֶץ מִ⁠מְּלֹאָ֔⁠הּ בְּ⁠הַכּוֹתִ֖⁠י אֶת־כָּל־י֣וֹשְׁבֵי בָ֑⁠הּ וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃","bĕ̇⁠ţiţi̇⁠y֩ ʼeţ-ʼe֨reẕ miẕĕra֜yim şĕ̌mámá֣h ẇ⁠nĕşǎmá̇֗h ʼe֚reẕ mi⁠mĕ̇lòʼá֔⁠ḣ bĕ̇⁠hak̇wòţi֖⁠y ʼeţ-ká̇l-y֣wòşĕ̌béy bá֑⁠ḣ wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[32,16,"קִינָ֥ה הִיא֙ וְ⁠ק֣וֹנְנ֔וּ⁠הָ בְּנ֥וֹת הַ⁠גּוֹיִ֖ם תְּקוֹנֵ֣נָּה אוֹתָ֑⁠הּ עַל־מִצְרַ֤יִם וְ⁠עַל־כָּל־הֲמוֹנָ⁠הּ֙ תְּקוֹנֵ֣נָּה אוֹתָ֔⁠הּ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","qiyná֥h hiyʼ֙ wĕ⁠q֣wònĕn֔ẇ⁠há bĕ̇n֥wòţ ha⁠ġwòyi֖m ţĕ̇qwòné֣ná̇h ʼwòţá֑⁠ḣ ʻal-miẕĕra֤yim wĕ⁠ʻal-ká̇l-hàmwòná⁠ḣ֙ ţĕ̇qwòné֣ná̇h ʼwòţá֔⁠ḣ nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[32,17,"וַֽ⁠יְהִי֙ בִּ⁠שְׁתֵּ֣י עֶשְׂרֵ֣ה שָׁנָ֔ה בַּ⁠חֲמִשָּׁ֥ה עָשָׂ֖ר לַ⁠חֹ֑דֶשׁ הָיָ֥ה דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","waֽ⁠yĕhiy֙ bi̇⁠şĕ̌ţé֣̇y ʻeşĕ̂ré֣h şá̌ná֔h bȧ⁠ẖàmişá֥̇̌h ʻáşá֖̂r la⁠ẖò֑deş̌ háyá֥h dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[32,18,"בֶּן־אָדָ֕ם נְהֵ֛ה עַל־הֲמ֥וֹן מִצְרַ֖יִם וְ⁠הוֹרִדֵ֑⁠הוּ א֠וֹתָ⁠הּ וּ⁠בְנ֨וֹת גּוֹיִ֧ם אַדִּרִ֛ם אֶל־אֶ֥רֶץ תַּחְתִּיּ֖וֹת אֶת־י֥וֹרְדֵי בֽוֹר׃","bėn-ʼádá֕m nĕhé֛h ʻal-hàm֥wòn miẕĕra֖yim wĕ⁠hwòridé֑⁠hẇ ʼ֠wòţá⁠ḣ ẇ⁠bĕn֨wòţ ġwòyi֧m ʼadi̇ri֛m ʼel-ʼe֥reẕ ţȧẖĕţi̇ẏ֖wòţ ʼeţ-y֥wòrĕdéy bֽwòr׃"],[32,19,"מִ⁠מִּ֖י נָעָ֑מְתָּ רְדָ֥⁠ה וְ⁠הָשְׁכְּבָ֖⁠ה אֶת־עֲרֵלִֽים׃","mi⁠mi֖̇y náʻá֑mĕţá̇ rĕdá֥⁠h wĕ⁠háşĕ̌kĕ̇bá֖⁠h ʼeţ-ʻàréliֽym׃"],[32,20,"בְּ⁠ת֥וֹךְ חַלְלֵי־חֶ֖רֶב יִפֹּ֑לוּ חֶ֣רֶב נִתָּ֔נָה מָשְׁכ֥וּ אוֹתָ֖⁠הּ וְ⁠כָל־הֲמוֹנֶֽי⁠הָ׃","bĕ̇⁠ţ֥wòkĕ ẖalĕléy-ẖe֖reb yipò֑̇lẇ ẖe֣reb niţá̇֔náh máşĕ̌k֥ẇ ʼwòţá֖⁠ḣ wĕ⁠kál-hàmwòneֽy⁠há׃"],[32,21,"יְדַבְּרוּ־ל֞⁠וֹ אֵלֵ֧י גִבּוֹרִ֛ים מִ⁠תּ֥וֹךְ שְׁא֖וֹל אֶת־עֹֽזְרָ֑י⁠ו יָֽרְד֛וּ שָׁכְב֥וּ הָ⁠עֲרֵלִ֖ים חַלְלֵי־חָֽרֶב׃","yĕdabĕ̇rẇ-l֞⁠wò ʼélé֧y giḃwòri֛ym mi⁠ţ֥̇wòkĕ şĕ̌ʼ֖wòl ʼeţ-ʻòֽzĕrá֑y⁠w yáֽrĕd֛ẇ şá̌kĕb֥ẇ há⁠ʻàréli֖ym ẖalĕléy-ẖáֽreb׃"],[32,22,"שָׁ֤ם אַשּׁוּר֙ וְ⁠כָל־קְהָלָ֔⁠הּ סְבִֽיבוֹתָ֖י⁠ו קִבְרֹתָ֑י⁠ו כֻּלָּ֣⁠ם חֲלָלִ֔ים הַ⁠נֹּפְלִ֖ים בֶּ⁠חָֽרֶב׃","şá֤̌m ʼaş̇̌ẇr֙ wĕ⁠kál-qĕhálá֔⁠ḣ sĕbiֽybwòţá֖y⁠w qibĕròţá֑y⁠w ku̇lá֣̇⁠m ẖàláli֔ym ha⁠nò̇pĕli֖ym bė⁠ẖáֽreb׃"],[32,23,"אֲשֶׁ֨ר נִתְּנ֤וּ קִבְרֹתֶ֨י⁠הָ֙ בְּ⁠יַרְכְּתֵי־ב֔וֹר וַ⁠יְהִ֣י קְהָלָ֔⁠הּ סְבִיב֖וֹת קְבֻרָתָ֑⁠הּ כֻּלָּ֤⁠ם חֲלָלִים֙ נֹפְלִ֣ים בַּ⁠חֶ֔רֶב אֲשֶׁר־נָתְנ֥וּ חִתִּ֖ית בְּ⁠אֶ֥רֶץ חַיִּֽים׃","ʼàşě֨r niţĕ̇n֤ẇ qibĕròţe֨y⁠há֙ bĕ̇⁠yarĕkĕ̇ţéy-b֔wòr wa⁠yĕhi֣y qĕhálá֔⁠ḣ sĕbiyb֖wòţ qĕburáţá֑⁠ḣ ku̇lá֤̇⁠m ẖàláliym֙ nòpĕli֣ym bȧ⁠ẖe֔reb ʼàşěr-náţĕn֥ẇ ẖiţi֖̇yţ bĕ̇⁠ʼe֥reẕ ẖayiֽ̇ym׃"],[32,24,"שָׁ֤ם עֵילָם֙ וְ⁠כָל־הֲמוֹנָ֔⁠הּ סְבִיב֖וֹת קְבֻרָתָ֑⁠הּ כֻּלָּ֣⁠ם חֲלָלִים֩ הַ⁠נֹּפְלִ֨ים בַּ⁠חֶ֜רֶב אֲֽשֶׁר־יָרְד֥וּ עֲרֵלִ֣ים ׀ אֶל־אֶ֣רֶץ תַּחְתִּיּ֗וֹת אֲשֶׁ֨ר נָתְנ֤וּ חִתִּיתָ⁠ם֙ בְּ⁠אֶ֣רֶץ חַיִּ֔ים וַ⁠יִּשְׂא֥וּ כְלִמָּתָ֖⁠ם אֶת־י֥וֹרְדֵי בֽוֹר׃","şá֤̌m ʻéylám֙ wĕ⁠kál-hàmwòná֔⁠ḣ sĕbiyb֖wòţ qĕburáţá֑⁠ḣ ku̇lá֣̇⁠m ẖàláliym֩ ha⁠nò̇pĕli֨ym bȧ⁠ẖe֜reb ʼàֽşěr-yárĕd֥ẇ ʻàréli֣ym ׀ ʼel-ʼe֣reẕ ţȧẖĕţi̇ẏ֗wòţ ʼàşě֨r náţĕn֤ẇ ẖiţi̇yţá⁠m֙ bĕ̇⁠ʼe֣reẕ ẖayi̇֔ym wa⁠yi̇şĕ̂ʼ֥ẇ kĕlimá̇ţá֖⁠m ʼeţ-y֥wòrĕdéy bֽwòr׃"],[32,25,"בְּ⁠ת֣וֹךְ חֲ֠לָלִים נָתְנ֨וּ מִשְׁכָּ֥ב לָ⁠הּ֙ בְּ⁠כָל־הֲמוֹנָ֔⁠הּ סְבִֽיבוֹתָ֖י⁠ו קִבְרֹתֶ֑⁠הָ כֻּלָּ֣⁠ם עֲרֵלִ֣ים חַלְלֵי־חֶ֡רֶב כִּֽי־נִתַּ֨ן חִתִּיתָ֜⁠ם בְּ⁠אֶ֣רֶץ חַיִּ֗ים וַ⁠יִּשְׂא֤וּ כְלִמָּתָ⁠ם֙ אֶת־י֣וֹרְדֵי ב֔וֹר בְּ⁠ת֥וֹךְ חֲלָלִ֖ים נִתָּֽן׃","bĕ̇⁠ţ֣wòkĕ ẖà֠láliym náţĕn֨ẇ mişĕ̌ká֥̇b lá⁠ḣ֙ bĕ̇⁠kál-hàmwòná֔⁠ḣ sĕbiֽybwòţá֖y⁠w qibĕròţe֑⁠há ku̇lá֣̇⁠m ʻàréli֣ym ẖalĕléy-ẖe֡reb kiֽ̇y-niţȧ֨n ẖiţi̇yţá֜⁠m bĕ̇⁠ʼe֣reẕ ẖayi̇֗ym wa⁠yi̇şĕ̂ʼ֤ẇ kĕlimá̇ţá⁠m֙ ʼeţ-y֣wòrĕdéy b֔wòr bĕ̇⁠ţ֥wòkĕ ẖàláli֖ym niţáֽ̇n׃"],[32,26,"שָׁ֣ם מֶ֤שֶׁךְ תֻּבַל֙ וְ⁠כָל־הֲמוֹנָ֔⁠הּ סְבִֽיבוֹתָ֖י⁠ו קִבְרוֹתֶ֑י⁠הָ כֻּלָּ֤⁠ם עֲרֵלִים֙ מְחֻ֣לְלֵי חֶ֔רֶב כִּֽי־נָתְנ֥וּ חִתִּיתָ֖⁠ם בְּ⁠אֶ֥רֶץ חַיִּֽים׃","şá֣̌m me֤şěkĕ ţu̇bal֙ wĕ⁠kál-hàmwòná֔⁠ḣ sĕbiֽybwòţá֖y⁠w qibĕrwòţe֑y⁠há ku̇lá֤̇⁠m ʻàréliym֙ mĕẖu֣lĕléy ẖe֔reb kiֽ̇y-náţĕn֥ẇ ẖiţi̇yţá֖⁠m bĕ̇⁠ʼe֥reẕ ẖayiֽ̇ym׃"],[32,27,"וְ⁠לֹ֤א יִשְׁכְּבוּ֙ אֶת־גִּבּוֹרִ֔ים נֹפְלִ֖ים מֵ⁠עֲרֵלִ֑ים אֲשֶׁ֣ר יָרְדֽוּ־שְׁא֣וֹל בִּ⁠כְלֵֽי־מִלְחַמְתָּ⁠ם֩ וַ⁠יִּתְּנ֨וּ אֶת־חַרְבוֹתָ֜⁠ם תַּ֣חַת רָאשֵׁי⁠הֶ֗ם וַ⁠תְּהִ֤י עֲוֺֽנֹתָ⁠ם֙ עַל־עַצְמוֹתָ֔⁠ם כִּֽי־חִתִּ֥ית גִּבּוֹרִ֖ים בְּ⁠אֶ֥רֶץ חַיִּֽים׃","wĕ⁠lò֤ʼ yişĕ̌kĕ̇bẇ֙ ʼeţ-gi̇ḃwòri֔ym nòpĕli֖ym mé⁠ʻàréli֑ym ʼàşě֣r yárĕdֽẇ-şĕ̌ʼ֣wòl bi̇⁠kĕléֽy-milĕẖamĕţá̇⁠m֩ wa⁠yi̇ţĕ̇n֨ẇ ʼeţ-ẖarĕbwòţá֜⁠m ţȧ֣ẖaţ ráʼşé̌y⁠he֗m wa⁠ţĕ̇hi֤y ʻàwֺֽnòţá⁠m֙ ʻal-ʻaẕĕmwòţá֔⁠m kiֽ̇y-ẖiţi֥̇yţ gi̇ḃwòri֖ym bĕ̇⁠ʼe֥reẕ ẖayiֽ̇ym׃"],[32,28,"וְ⁠אַתָּ֗ה בְּ⁠ת֧וֹךְ עֲרֵלִ֛ים תִּשָּׁבַ֥ר וְ⁠תִשְׁכַּ֖ב אֶת־חַלְלֵי־חָֽרֶב׃","wĕ⁠ʼaţá̇֗h bĕ̇⁠ţ֧wòkĕ ʻàréli֛ym ţi̇şá̇̌ba֥r wĕ⁠ţişĕ̌kȧ֖b ʼeţ-ẖalĕléy-ẖáֽreb׃"],[32,29,"שָׁ֣מָּ⁠ה אֱד֗וֹם מְלָכֶ֨י⁠הָ֙ וְ⁠כָל־נְשִׂיאֶ֔י⁠הָ אֲשֶׁר־נִתְּנ֥וּ בִ⁠גְבוּרָתָ֖⁠ם אֶת־חַלְלֵי־חָ֑רֶב הֵ֛מָּה אֶת־עֲרֵלִ֥ים יִשְׁכָּ֖בוּ וְ⁠אֶת־יֹ֥רְדֵי בֽוֹר׃","şá֣̌má̇⁠h ʼèd֗wòm mĕláke֨y⁠há֙ wĕ⁠kál-nĕşîyʼe֔y⁠há ʼàşěr-niţĕ̇n֥ẇ bi⁠gĕbẇráţá֖⁠m ʼeţ-ẖalĕléy-ẖá֑reb hé֛má̇h ʼeţ-ʻàréli֥ym yişĕ̌ká֖̇bẇ wĕ⁠ʼeţ-yò֥rĕdéy bֽwòr׃"],[32,30,"שָׁ֣מָּ⁠ה נְסִיכֵ֥י צָפ֛וֹן כֻּלָּ֖⁠ם וְ⁠כָל־צִֽדֹנִ֑י אֲשֶׁר־יָרְד֣וּ אֶת־חֲלָלִ֗ים בְּ⁠חִתִּיתָ֤⁠ם מִ⁠גְבֽוּרָתָ⁠ם֙ בּוֹשִׁ֔ים וַ⁠יִּשְׁכְּב֤וּ עֲרֵלִים֙ אֶת־חַלְלֵי־חֶ֔רֶב וַ⁠יִּשְׂא֥וּ כְלִמָּתָ֖⁠ם אֶת־י֥וֹרְדֵי בֽוֹר׃","şá֣̌má̇⁠h nĕsiyké֥y ẕáp֛wòn ku̇lá֖̇⁠m wĕ⁠kál-ẕiֽdòni֑y ʼàşěr-yárĕd֣ẇ ʼeţ-ẖàláli֗ym bĕ̇⁠ẖiţi̇yţá֤⁠m mi⁠gĕbֽẇráţá⁠m֙ ḃwòşǐ֔ym wa⁠yi̇şĕ̌kĕ̇b֤ẇ ʻàréliym֙ ʼeţ-ẖalĕléy-ẖe֔reb wa⁠yi̇şĕ̂ʼ֥ẇ kĕlimá̇ţá֖⁠m ʼeţ-y֥wòrĕdéy bֽwòr׃"],[32,31,"אוֹתָ⁠ם֙ יִרְאֶ֣ה פַרְעֹ֔ה וְ⁠נִחַ֖ם עַל־כָּל־המונ⁠ה חַלְלֵי־חֶ֨רֶב֙ פַּרְעֹ֣ה וְ⁠כָל־חֵיל֔⁠וֹ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","ʼwòţá⁠m֙ yirĕʼe֣h parĕʻò֔h wĕ⁠niẖa֖m ʻal-ká̇l-hmwn⁠h ẖalĕléy-ẖe֨reb֙ pȧrĕʻò֣h wĕ⁠kál-ẖéyl֔⁠wò nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[32,32,"כִּֽי־נָתַ֥תִּי אֶת־חתית⁠ו בְּ⁠אֶ֣רֶץ חַיִּ֑ים וְ⁠הֻשְׁכַּב֩ בְּ⁠ת֨וֹךְ עֲרֵלִ֜ים אֶת־חַלְלֵי־חֶ֗רֶב פַּרְעֹה֙ וְ⁠כָל־הֲמוֹנֹ֔⁠ה נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","kiֽ̇y-náţa֥ţi̇y ʼeţ-ẖţyţ⁠w bĕ̇⁠ʼe֣reẕ ẖayi֑̇ym wĕ⁠huşĕ̌kȧb֩ bĕ̇⁠ţ֨wòkĕ ʻàréli֜ym ʼeţ-ẖalĕléy-ẖe֗reb pȧrĕʻòh֙ wĕ⁠kál-hàmwònò֔⁠h nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[33,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[33,2,"בֶּן־אָדָ֗ם דַּבֵּ֤ר אֶל־בְּנֵֽי־עַמְּ⁠ךָ֙ וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם אֶ֕רֶץ כִּֽי־אָבִ֥יא עָלֶ֖י⁠הָ חָ֑רֶב וְ⁠לָקְח֨וּ עַם־הָ⁠אָ֜רֶץ אִ֤ישׁ אֶחָד֙ מִ⁠קְצֵי⁠הֶ֔ם וְ⁠נָתְנ֥וּ אֹת֛⁠וֹ לָ⁠הֶ֖ם לְ⁠צֹפֶֽה׃","bėn-ʼádá֗m dȧbé֤̇r ʼel-bĕ̇néֽy-ʻamĕ̇⁠ká֙ wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m ʼe֕reẕ kiֽ̇y-ʼábi֥yʼ ʻále֖y⁠há ẖá֑reb wĕ⁠láqĕẖ֨ẇ ʻam-há⁠ʼá֜reẕ ʼi֤yş̌ ʼeẖád֙ mi⁠qĕẕéy⁠he֔m wĕ⁠náţĕn֥ẇ ʼòţ֛⁠wò lá⁠he֖m lĕ⁠ẕòpeֽh׃"],[33,3,"וְ⁠רָאָ֥ה אֶת־הַ⁠חֶ֖רֶב בָּאָ֣ה עַל־הָ⁠אָ֑רֶץ וְ⁠תָקַ֥ע בַּ⁠שּׁוֹפָ֖ר וְ⁠הִזְהִ֥יר אֶת־הָ⁠עָֽם׃","wĕ⁠ráʼá֥h ʼeţ-ha⁠ẖe֖reb bá̇ʼá֣h ʻal-há⁠ʼá֑reẕ wĕ⁠ţáqa֥ʻ bȧ⁠ş̇̌wòpá֖r wĕ⁠hizĕhi֥yr ʼeţ-há⁠ʻáֽm׃"],[33,4,"וְ⁠שָׁמַ֨ע הַ⁠שֹּׁמֵ֜עַ אֶת־ק֤וֹל הַ⁠שּׁוֹפָר֙ וְ⁠לֹ֣א נִזְהָ֔ר וַ⁠תָּ֥בוֹא חֶ֖רֶב וַ⁠תִּקָּחֵ֑⁠הוּ דָּמ֥⁠וֹ בְ⁠רֹאשׁ֖⁠וֹ יִֽהְיֶֽה׃","wĕ⁠şá̌ma֨ʻ ha⁠şò̇̌mé֜ʻa ʼeţ-q֤wòl ha⁠ş̇̌wòpár֙ wĕ⁠lò֣ʼ nizĕhá֔r wa⁠ţá֥̇bwòʼ ẖe֖reb wa⁠ţi̇qá̇ẖé֑⁠hẇ dá̇m֥⁠wò bĕ⁠ròʼş֖̌⁠wò yiֽhĕyeֽh׃"],[33,5,"אֵת֩ ק֨וֹל הַ⁠שּׁוֹפָ֤ר שָׁמַע֙ וְ⁠לֹ֣א נִזְהָ֔ר דָּמ֖⁠וֹ בּ֣⁠וֹ יִֽהְיֶ֑ה וְ⁠ה֥וּא נִזְהָ֖ר נַפְשׁ֥⁠וֹ מִלֵּֽט׃","ʼéţ֩ q֨wòl ha⁠ş̇̌wòpá֤r şá̌maʻ֙ wĕ⁠lò֣ʼ nizĕhá֔r dá̇m֖⁠wò ḃ֣⁠wò yiֽhĕye֑h wĕ⁠h֥ẇʼ nizĕhá֖r napĕş֥̌⁠wò miléֽ̇t׃"],[33,6,"וְ֠⁠הַ⁠צֹּפֶה כִּֽי־יִרְאֶ֨ה אֶת־הַ⁠חֶ֜רֶב בָּאָ֗ה וְ⁠לֹֽא־תָקַ֤ע בַּ⁠שּׁוֹפָר֙ וְ⁠הָ⁠עָ֣ם לֹֽא־נִזְהָ֔ר וַ⁠תָּב֣וֹא חֶ֔רֶב וַ⁠תִּקַּ֥ח מֵ⁠הֶ֖ם נָ֑פֶשׁ ה֚וּא בַּ⁠עֲוֺנ֣⁠וֹ נִלְקָ֔ח וְ⁠דָמ֖⁠וֹ מִ⁠יַּֽד־הַ⁠צֹּפֶ֥ה אֶדְרֹֽשׁ׃ס","wĕ֠⁠ha⁠ẕò̇peh kiֽ̇y-yirĕʼe֨h ʼeţ-ha⁠ẖe֜reb bá̇ʼá֗h wĕ⁠lòֽʼ-ţáqa֤ʻ bȧ⁠ş̇̌wòpár֙ wĕ⁠há⁠ʻá֣m lòֽʼ-nizĕhá֔r wa⁠ţá̇b֣wòʼ ẖe֔reb wa⁠ţi̇qȧ֥ẖ mé⁠he֖m ná֑peş̌ h֚ẇʼ bȧ⁠ʻàwֺn֣⁠wò nilĕqá֔ẖ wĕ⁠dám֖⁠wò mi⁠yȧֽd-ha⁠ẕò̇pe֥h ʼedĕròֽş̌׃s"],[33,7,"וְ⁠אַתָּ֣ה בֶן־אָדָ֔ם צֹפֶ֥ה נְתַתִּ֖י⁠ךָ לְ⁠בֵ֣ית יִשְׂרָאֵ֑ל וְ⁠שָׁמַעְתָּ֤ מִ⁠פִּ⁠י֙ דָּבָ֔ר וְ⁠הִזְהַרְתָּ֥ אֹתָ֖⁠ם מִמֶּֽ⁠נִּי׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֔m ẕòpe֥h nĕţaţi֖̇y⁠ká lĕ⁠bé֣yţ yişĕ̂ráʼé֑l wĕ⁠şá̌maʻĕţá֤̇ mi⁠pi̇⁠y֙ dá̇bá֔r wĕ⁠hizĕharĕţá֥̇ ʼòţá֖⁠m mimėֽ⁠ni̇y׃"],[33,8,"בְּ⁠אָמְרִ֣⁠י לָ⁠רָשָׁ֗ע רָשָׁע֙ מ֣וֹת תָּמ֔וּת וְ⁠לֹ֣א דִבַּ֔רְתָּ לְ⁠הַזְהִ֥יר רָשָׁ֖ע מִ⁠דַּרְכּ֑⁠וֹ ה֤וּא רָשָׁע֙ בַּ⁠עֲוֺנ֣⁠וֹ יָמ֔וּת וְ⁠דָמ֖⁠וֹ מִ⁠יָּדְ⁠ךָ֥ אֲבַקֵּֽשׁ׃","bĕ̇⁠ʼámĕri֣⁠y lá⁠ráşá̌֗ʻ ráşá̌ʻ֙ m֣wòţ ţá̇m֔ẇţ wĕ⁠lò֣ʼ dibȧ֔rĕţá̇ lĕ⁠hazĕhi֥yr ráşá֖̌ʻ mi⁠dȧrĕk֑̇⁠wò h֤ẇʼ ráşá̌ʻ֙ bȧ⁠ʻàwֺn֣⁠wò yám֔ẇţ wĕ⁠dám֖⁠wò mi⁠yá̇dĕ⁠ká֥ ʼàbaqéֽ̇ş̌׃"],[33,9,"וְ֠⁠אַתָּה כִּֽי־הִזְהַ֨רְתָּ רָשָׁ֤ע מִ⁠דַּרְכּ⁠וֹ֙ לָ⁠שׁ֣וּב מִמֶּ֔⁠נָּה וְ⁠לֹא־שָׁ֖ב מִ⁠דַּרְכּ֑⁠וֹ ה֚וּא בַּ⁠עֲוֺנ֣⁠וֹ יָמ֔וּת וְ⁠אַתָּ֖ה נַפְשְׁ⁠ךָ֥ הִצַּֽלְתָּ׃ס","wĕ֠⁠ʼaţá̇h kiֽ̇y-hizĕha֨rĕţá̇ ráşá֤̌ʻ mi⁠dȧrĕk̇⁠wò֙ lá⁠ş֣̌ẇb mimė֔⁠ná̇h wĕ⁠lòʼ-şá֖̌b mi⁠dȧrĕk֑̇⁠wò h֚ẇʼ bȧ⁠ʻàwֺn֣⁠wò yám֔ẇţ wĕ⁠ʼaţá֖̇h napĕşĕ̌⁠ká֥ hiẕȧֽlĕţá̇׃s"],[33,10,"וְ⁠אַתָּ֣ה בֶן־אָדָ֗ם אֱמֹר֙ אֶל־בֵּ֣ית יִשְׂרָאֵ֔ל כֵּ֤ן אֲמַרְתֶּם֙ לֵ⁠אמֹ֔ר כִּֽי־פְשָׁעֵ֥י⁠נוּ וְ⁠חַטֹּאתֵ֖י⁠נוּ עָלֵ֑י⁠נוּ וּ⁠בָ֛⁠ם אֲנַ֥חְנוּ נְמַקִּ֖ים וְ⁠אֵ֥יךְ נִֽחְיֶֽה׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֗m ʼèmòr֙ ʼel-bé֣̇yţ yişĕ̂ráʼé֔l ké֤̇n ʼàmarĕţėm֙ lé⁠ʼmò֔r kiֽ̇y-pĕşá̌ʻé֥y⁠nẇ wĕ⁠ẖatò̇ʼţé֖y⁠nẇ ʻálé֑y⁠nẇ ẇ⁠bá֛⁠m ʼàna֥ẖĕnẇ nĕmaqi֖̇ym wĕ⁠ʼé֥ykĕ niֽẖĕyeֽh׃"],[33,11,"אֱמֹ֨ר אֲלֵי⁠הֶ֜ם חַי־אָ֣נִי ׀ נְאֻ֣ם ׀ אֲדֹנָ֣⁠י יְהוִ֗ה אִם־אֶחְפֹּץ֙ בְּ⁠מ֣וֹת הָ⁠רָשָׁ֔ע כִּ֣י אִם־בְּ⁠שׁ֥וּב רָשָׁ֛ע מִ⁠דַּרְכּ֖⁠וֹ וְ⁠חָיָ֑ה שׁ֣וּבוּ שׁ֜וּבוּ מִ⁠דַּרְכֵי⁠כֶ֧ם הָ⁠רָעִ֛ים וְ⁠לָ֥⁠מָּה תָמ֖וּתוּ בֵּ֥ית יִשְׂרָאֵֽל׃פ","ʼèmò֨r ʼàléy⁠he֜m ẖay-ʼá֣niy ׀ nĕʼu֣m ׀ ʼàdòná֣⁠y yĕhwi֗h ʼim-ʼeẖĕpò̇ẕ֙ bĕ̇⁠m֣wòţ há⁠ráşá̌֔ʻ ki֣̇y ʼim-bĕ̇⁠ş֥̌ẇb ráşá֛̌ʻ mi⁠dȧrĕk֖̇⁠wò wĕ⁠ẖáyá֑h ş֣̌ẇbẇ ş̌֜ẇbẇ mi⁠dȧrĕkéy⁠ke֧m há⁠ráʻi֛ym wĕ⁠lá֥⁠má̇h ţám֖ẇţẇ bé֥̇yţ yişĕ̂ráʼéֽl׃p"],[33,12,"וְ⁠אַתָּ֣ה בֶן־אָדָ֗ם אֱמֹ֤ר אֶל־בְּנֵֽי־עַמְּ⁠ךָ֙ צִדְקַ֣ת הַ⁠צַּדִּ֗יק לֹ֤א תַצִּילֶ֨⁠נּוּ֙ בְּ⁠י֣וֹם פִּשְׁע֔⁠וֹ וְ⁠רִשְׁעַ֤ת הָֽ⁠רָשָׁע֙ לֹֽא־יִכָּ֣שֶׁל בָּ֔⁠הּ בְּ⁠י֖וֹם שׁוּב֣⁠וֹ מֵֽ⁠רִשְׁע֑⁠וֹ וְ⁠צַדִּ֗יק לֹ֥א יוּכַ֛ל לִֽ⁠חְי֥וֹת בָּ֖⁠הּ בְּ⁠י֥וֹם חֲטֹאתֽ⁠וֹ׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֗m ʼèmò֤r ʼel-bĕ̇néֽy-ʻamĕ̇⁠ká֙ ẕidĕqa֣ţ ha⁠ẕȧdi̇֗yq lò֤ʼ ţaẕi̇yle֨⁠ṅẇ֙ bĕ̇⁠y֣wòm pi̇şĕ̌ʻ֔⁠wò wĕ⁠rişĕ̌ʻa֤ţ háֽ⁠ráşá̌ʻ֙ lòֽʼ-yiká֣̇şěl bá̇֔⁠ḣ bĕ̇⁠y֖wòm ş̌ẇb֣⁠wò méֽ⁠rişĕ̌ʻ֑⁠wò wĕ⁠ẕadi̇֗yq lò֥ʼ yẇka֛l liֽ⁠ẖĕy֥wòţ bá֖̇⁠ḣ bĕ̇⁠y֥wòm ẖàtòʼţֽ⁠wò׃"],[33,13,"בְּ⁠אָמְרִ֤⁠י לַ⁠צַּדִּיק֙ חָיֹ֣ה יִֽחְיֶ֔ה וְ⁠הֽוּא־בָטַ֥ח עַל־צִדְקָת֖⁠וֹ וְ⁠עָ֣שָׂה עָ֑וֶל כָּל־צדקת⁠ו לֹ֣א תִזָּכַ֔רְנָה וּ⁠בְ⁠עַוְל֥⁠וֹ אֲשֶׁר־עָשָׂ֖ה בּ֥⁠וֹ יָמֽוּת׃","bĕ̇⁠ʼámĕri֤⁠y la⁠ẕȧdi̇yq֙ ẖáyò֣h yiֽẖĕye֔h wĕ⁠hֽẇʼ-báta֥ẖ ʻal-ẕidĕqáţ֖⁠wò wĕ⁠ʻá֣şá̂h ʻá֑wel ká̇l-ẕdqţ⁠w lò֣ʼ ţizá̇ka֔rĕnáh ẇ⁠bĕ⁠ʻawĕl֥⁠wò ʼàşěr-ʻáşá֖̂h ḃ֥⁠wò yámֽẇţ׃"],[33,14,"וּ⁠בְ⁠אָמְרִ֥⁠י לָֽ⁠רָשָׁ֖ע מ֣וֹת תָּמ֑וּת וְ⁠שָׁב֙ מֵֽ⁠חַטָּאת֔⁠וֹ וְ⁠עָשָׂ֥ה מִשְׁפָּ֖ט וּ⁠צְדָקָֽה׃","ẇ⁠bĕ⁠ʼámĕri֥⁠y láֽ⁠ráşá֖̌ʻ m֣wòţ ţá̇m֑ẇţ wĕ⁠şá̌b֙ méֽ⁠ẖatá̇ʼţ֔⁠wò wĕ⁠ʻáşá֥̂h mişĕ̌pá֖̇t ẇ⁠ẕĕdáqáֽh׃"],[33,15,"חֲבֹ֨ל יָשִׁ֤יב רָשָׁע֙ גְּזֵלָ֣ה יְשַׁלֵּ֔ם בְּ⁠חֻקּ֤וֹת הַֽ⁠חַיִּים֙ הָלַ֔ךְ לְ⁠בִלְתִּ֖י עֲשׂ֣וֹת עָ֑וֶל חָי֥וֹ יִֽחְיֶ֖ה לֹ֥א יָמֽוּת׃","ẖàbò֨l yáşǐ֤yb ráşá̌ʻ֙ gĕ̇zélá֣h yĕşǎlé̇֔m bĕ̇⁠ẖuq֤̇wòţ haֽ⁠ẖayi̇ym֙ hála֔kĕ lĕ⁠bilĕţi֖̇y ʻàş֣̂wòţ ʻá֑wel ẖáy֥wò yiֽẖĕye֖h lò֥ʼ yámֽẇţ׃"],[33,16,"כָּל־חטאת⁠ו אֲשֶׁ֣ר חָטָ֔א לֹ֥א תִזָּכַ֖רְנָה ל֑⁠וֹ מִשְׁפָּ֧ט וּ⁠צְדָקָ֛ה עָשָׂ֖ה חָי֥וֹ יִֽחְיֶֽה׃","ká̇l-ẖtʼţ⁠w ʼàşě֣r ẖátá֔ʼ lò֥ʼ ţizá̇ka֖rĕnáh l֑⁠wò mişĕ̌pá֧̇t ẇ⁠ẕĕdáqá֛h ʻáşá֖̂h ẖáy֥wò yiֽẖĕyeֽh׃"],[33,17,"וְ⁠אָמְרוּ֙ בְּנֵ֣י עַמְּ⁠ךָ֔ לֹ֥א יִתָּכֵ֖ן דֶּ֣רֶךְ אֲדֹנָ֑⁠י וְ⁠הֵ֖מָּה דַּרְכָּ֥⁠ם לֹֽא־יִתָּכֵֽן׃","wĕ⁠ʼámĕrẇ֙ bĕ̇né֣y ʻamĕ̇⁠ká֔ lò֥ʼ yiţá̇ké֖n dė֣rekĕ ʼàdòná֑⁠y wĕ⁠hé֖má̇h dȧrĕká֥̇⁠m lòֽʼ-yiţá̇kéֽn׃"],[33,18,"בְּ⁠שׁוּב־צַדִּ֥יק מִ⁠צִּדְקָת֖⁠וֹ וְ⁠עָ֣שָׂה עָ֑וֶל וּ⁠מֵ֖ת בָּ⁠הֶֽם׃","bĕ̇⁠ş̌ẇb-ẕadi֥̇yq mi⁠ẕi̇dĕqáţ֖⁠wò wĕ⁠ʻá֣şá̂h ʻá֑wel ẇ⁠mé֖ţ bá̇⁠heֽm׃"],[33,19,"וּ⁠בְ⁠שׁ֤וּב רָשָׁע֙ מֵֽ⁠רִשְׁעָת֔⁠וֹ וְ⁠עָשָׂ֥ה מִשְׁפָּ֖ט וּ⁠צְדָקָ֑ה עֲלֵי⁠הֶ֖ם ה֥וּא יִֽחְיֶֽה׃","ẇ⁠bĕ⁠ş֤̌ẇb ráşá̌ʻ֙ méֽ⁠rişĕ̌ʻáţ֔⁠wò wĕ⁠ʻáşá֥̂h mişĕ̌pá֖̇t ẇ⁠ẕĕdáqá֑h ʻàléy⁠he֖m h֥ẇʼ yiֽẖĕyeֽh׃"],[33,20,"וַ⁠אֲמַרְתֶּ֕ם לֹ֥א יִתָּכֵ֖ן דֶּ֣רֶךְ אֲדֹנָ֑⁠י אִ֧ישׁ כִּ⁠דְרָכָ֛י⁠ו אֶשְׁפּ֥וֹט אֶתְ⁠כֶ֖ם בֵּ֥ית יִשְׂרָאֵֽל פ","wa⁠ʼàmarĕţė֕m lò֥ʼ yiţá̇ké֖n dė֣rekĕ ʼàdòná֑⁠y ʼi֧yş̌ ki̇⁠dĕráká֛y⁠w ʼeşĕ̌ṗ֥wòt ʼeţĕ⁠ke֖m bé֥̇yţ yişĕ̂ráʼéֽl p"],[33,21,"וַ⁠יְהִ֞י בִּ⁠שְׁתֵּ֧י עֶשְׂרֵ֣ה שָׁנָ֗ה בָּ⁠עֲשִׂרִ֛י בַּ⁠חֲמִשָּׁ֥ה לַ⁠חֹ֖דֶשׁ לְ⁠גָלוּתֵ֑⁠נוּ בָּא־אֵלַ֨⁠י הַ⁠פָּלִ֧יט מִ⁠ירוּשָׁלִַ֛ם לֵ⁠אמֹ֖ר הֻכְּתָ֥ה הָ⁠עִֽיר׃","wa⁠yĕhi֞y bi̇⁠şĕ̌ţé֧̇y ʻeşĕ̂ré֣h şá̌ná֗h bá̇⁠ʻàşîri֛y bȧ⁠ẖàmişá֥̇̌h la⁠ẖò֖deş̌ lĕ⁠gálẇţé֑⁠nẇ bá̇ʼ-ʼéla֨⁠y ha⁠pá̇li֧yt mi⁠yrẇşá̌lia֛m lé⁠ʼmò֖r hukĕ̇ţá֥h há⁠ʻiֽyr׃"],[33,22,"וְ⁠יַד־יְהוָה֩ הָיְתָ֨ה אֵלַ֜⁠י בָּ⁠עֶ֗רֶב לִ⁠פְנֵי֙ בּ֣וֹא הַ⁠פָּלִ֔יט וַ⁠יִּפְתַּ֣ח אֶת־פִּ֔⁠י עַד־בּ֥וֹא אֵלַ֖⁠י בַּ⁠בֹּ֑קֶר וַ⁠יִּפָּ֣תַח פִּ֔⁠י וְ⁠לֹ֥א נֶאֱלַ֖מְתִּי עֽוֹד׃פ","wĕ⁠yad-yĕhwáh֩ háyĕţá֨h ʼéla֜⁠y bá̇⁠ʻe֗reb li⁠pĕnéy֙ ḃ֣wòʼ ha⁠pá̇li֔yt wa⁠yi̇pĕţȧ֣ẖ ʼeţ-pi̇֔⁠y ʻad-ḃ֥wòʼ ʼéla֖⁠y bȧ⁠bò֑̇qer wa⁠yi̇pá֣̇ţaẖ pi̇֔⁠y wĕ⁠lò֥ʼ neʼèla֖mĕţi̇y ʻֽwòd׃p"],[33,23,"וַ⁠יְהִ֥י דְבַר־יְהֹוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhòwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[33,24,"בֶּן־אָדָ֗ם יֹ֠שְׁבֵי הֶ⁠חֳרָב֨וֹת הָ⁠אֵ֜לֶּה עַל־אַדְמַ֤ת יִשְׂרָאֵל֙ אֹמְרִ֣ים לֵ⁠אמֹ֔ר אֶחָד֙ הָיָ֣ה אַבְרָהָ֔ם וַ⁠יִּירַ֖שׁ אֶת־הָ⁠אָ֑רֶץ וַ⁠אֲנַ֣חְנוּ רַבִּ֔ים לָ֛⁠נוּ נִתְּנָ֥ה הָ⁠אָ֖רֶץ לְ⁠מוֹרָשָֽׁה׃ס","bėn-ʼádá֗m yò֠şĕ̌béy he⁠ẖoráb֨wòţ há⁠ʼé֜lėh ʻal-ʼadĕma֤ţ yişĕ̂ráʼél֙ ʼòmĕri֣ym lé⁠ʼmò֔r ʼeẖád֙ háyá֣h ʼabĕráhá֔m wa⁠yi̇yra֖ş̌ ʼeţ-há⁠ʼá֑reẕ wa⁠ʼàna֣ẖĕnẇ rabi̇֔ym lá֛⁠nẇ niţĕ̇ná֥h há⁠ʼá֖reẕ lĕ⁠mwòráşáֽ̌h׃s"],[33,25,"לָ⁠כֵן֩ אֱמֹ֨ר אֲלֵי⁠הֶ֜ם כֹּֽה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהֹוִ֗ה עַל־הַ⁠דָּ֧ם ׀ תֹּאכֵ֛לוּ וְ⁠עֵינֵ⁠כֶ֛ם תִּשְׂא֥וּ אֶל־גִּלּוּלֵי⁠כֶ֖ם וְ⁠דָ֣ם תִּשְׁפֹּ֑כוּ וְ⁠הָ⁠אָ֖רֶץ תִּירָֽשׁוּ׃","lá⁠kén֩ ʼèmò֨r ʼàléy⁠he֜m kòֽ̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhòwi֗h ʻal-ha⁠dá֧̇m ׀ ţò̇ʼké֛lẇ wĕ⁠ʻéyné⁠ke֛m ţi̇şĕ̂ʼ֥ẇ ʼel-gi̇l̇ẇléy⁠ke֖m wĕ⁠dá֣m ţi̇şĕ̌pò֑̇kẇ wĕ⁠há⁠ʼá֖reẕ ţi̇yráֽş̌ẇ׃"],[33,26,"עֲמַדְתֶּ֤ם עַֽל־חַרְבְּ⁠כֶם֙ עֲשִׂיתֶ֣ן תּוֹעֵבָ֔ה וְ⁠אִ֛ישׁ אֶת־אֵ֥שֶׁת רֵעֵ֖⁠הוּ טִמֵּאתֶ֑ם וְ⁠הָ⁠אָ֖רֶץ תִּירָֽשׁוּ׃ס","ʻàmadĕţė֤m ʻaֽl-ẖarĕbĕ̇⁠kem֙ ʻàşîyţe֣n ţ̇wòʻébá֔h wĕ⁠ʼi֛yş̌ ʼeţ-ʼé֥şěţ réʻé֖⁠hẇ timé̇ʼţe֑m wĕ⁠há⁠ʼá֖reẕ ţi̇yráֽş̌ẇ׃s"],[33,27,"כֹּֽה־תֹאמַ֨ר אֲלֵ⁠הֶ֜ם כֹּה־אָמַ֨ר אֲדֹנָ֣⁠י יְהוִה֮ חַי־אָנִי֒ אִם־לֹ֞א אֲשֶׁ֤ר בֶּֽ⁠חֳרָבוֹת֙ בַּ⁠חֶ֣רֶב יִפֹּ֔לוּ וַֽ⁠אֲשֶׁר֙ עַל־פְּנֵ֣י הַ⁠שָּׂדֶ֔ה לַ⁠חַיָּ֥ה נְתַתִּ֖י⁠ו לְ⁠אָכְל֑⁠וֹ וַ⁠אֲשֶׁ֛ר בַּ⁠מְּצָד֥וֹת וּ⁠בַ⁠מְּעָר֖וֹת בַּ⁠דֶּ֥בֶר יָמֽוּתוּ׃","kòֽ̇h-ţòʼma֨r ʼàlé⁠he֜m kò̇h-ʼáma֨r ʼàdòná֣⁠y yĕhwih֮ ẖay-ʼániy֒ ʼim-lò֞ʼ ʼàşě֤r bėֽ⁠ẖorábwòţ֙ bȧ⁠ẖe֣reb yipò̇֔lẇ waֽ⁠ʼàşěr֙ ʻal-pĕ̇né֣y ha⁠şá̇̂de֔h la⁠ẖayá֥̇h nĕţaţi֖̇y⁠w lĕ⁠ʼákĕl֑⁠wò wa⁠ʼàşě֛r bȧ⁠mĕ̇ẕád֥wòţ ẇ⁠ba⁠mĕ̇ʻár֖wòţ bȧ⁠dė֥ber yámֽẇţẇ׃"],[33,28,"וְ⁠נָתַתִּ֤י אֶת־הָ⁠אָ֨רֶץ֙ שְׁמָמָ֣ה וּ⁠מְשַׁמָּ֔ה וְ⁠נִשְׁבַּ֖ת גְּא֣וֹן עֻזָּ֑⁠הּ וְ⁠שָֽׁמְמ֛וּ הָרֵ֥י יִשְׂרָאֵ֖ל מֵ⁠אֵ֥ין עוֹבֵֽר׃","wĕ⁠náţaţi֤̇y ʼeţ-há⁠ʼá֨reẕ֙ şĕ̌mámá֣h ẇ⁠mĕşǎmá̇֔h wĕ⁠nişĕ̌bȧ֖ţ gĕ̇ʼ֣wòn ʻuzá֑̇⁠ḣ wĕ⁠şáֽ̌mĕm֛ẇ háré֥y yişĕ̂ráʼé֖l mé⁠ʼé֥yn ʻwòbéֽr׃"],[33,29,"וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֣י יְהוָ֑ה בְּ⁠תִתִּ֤⁠י אֶת־הָ⁠אָ֨רֶץ֙ שְׁמָמָ֣ה וּ⁠מְשַׁמָּ֔ה עַ֥ל כָּל־תּוֹעֲבֹתָ֖⁠ם אֲשֶׁ֥ר עָשֽׂוּ׃ס","wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֣y yĕhwá֑h bĕ̇⁠ţiţi֤̇⁠y ʼeţ-há⁠ʼá֨reẕ֙ şĕ̌mámá֣h ẇ⁠mĕşǎmá̇֔h ʻa֥l ká̇l-ţ̇wòʻàbòţá֖⁠m ʼàşě֥r ʻáşֽ̂ẇ׃s"],[33,30,"וְ⁠אַתָּ֣ה בֶן־אָדָ֔ם בְּנֵ֣י עַמְּ⁠ךָ֗ הַ⁠נִּדְבָּרִ֤ים בְּ⁠ךָ֙ אֵ֣צֶל הַ⁠קִּיר֔וֹת וּ⁠בְ⁠פִתְחֵ֖י הַ⁠בָּתִּ֑ים וְ⁠דִבֶּר־חַ֣ד אֶת־אַחַ֗ד אִ֤ישׁ אֶת־אָחִי⁠ו֙ לֵ⁠אמֹ֔ר בֹּֽאוּ־נָ֣א וְ⁠שִׁמְע֔וּ מָ֣ה הַ⁠דָּבָ֔ר הַ⁠יּוֹצֵ֖א מֵ⁠אֵ֥ת יְהוָֽה׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֔m bĕ̇né֣y ʻamĕ̇⁠ká֗ ha⁠ni̇dĕbá̇ri֤ym bĕ̇⁠ká֙ ʼé֣ẕel ha⁠qi̇yr֔wòţ ẇ⁠bĕ⁠piţĕẖé֖y ha⁠bá̇ţi֑̇ym wĕ⁠dibėr-ẖa֣d ʼeţ-ʼaẖa֗d ʼi֤yş̌ ʼeţ-ʼáẖiy⁠w֙ lé⁠ʼmò֔r bòֽ̇ʼẇ-ná֣ʼ wĕ⁠şǐmĕʻ֔ẇ má֣h ha⁠dá̇bá֔r ha⁠ẏwòẕé֖ʼ mé⁠ʼé֥ţ yĕhwáֽh׃"],[33,31,"וְ⁠יָב֣וֹאוּ אֵ֠לֶי⁠ךָ כִּ⁠מְבוֹא־עָ֞ם וְ⁠יֵשְׁב֤וּ לְ⁠פָנֶ֨י⁠ךָ֙ עַמִּ֔⁠י וְ⁠שָֽׁמְעוּ֙ אֶת־דְּבָרֶ֔י⁠ךָ וְ⁠אוֹתָ֖⁠ם לֹ֣א יַֽעֲשׂ֑וּ כִּֽי־עֲגָבִ֤ים בְּ⁠פִי⁠הֶם֙ הֵ֣מָּה עֹשִׂ֔ים אַחֲרֵ֥י בִצְעָ֖⁠ם לִבָּ֥⁠ם הֹלֵֽךְ׃","wĕ⁠yáb֣wòʼẇ ʼé֠ley⁠ká ki̇⁠mĕbwòʼ-ʻá֞m wĕ⁠yéşĕ̌b֤ẇ lĕ⁠páne֨y⁠ká֙ ʻami̇֔⁠y wĕ⁠şáֽ̌mĕʻẇ֙ ʼeţ-dĕ̇báre֔y⁠ká wĕ⁠ʼwòţá֖⁠m lò֣ʼ yaֽʻàş֑̂ẇ kiֽ̇y-ʻàgábi֤ym bĕ̇⁠piy⁠hem֙ hé֣má̇h ʻòşî֔ym ʼaẖàré֥y biẕĕʻá֖⁠m libá֥̇⁠m hòléֽkĕ׃"],[33,32,"וְ⁠הִנְּ⁠ךָ֤ לָ⁠הֶם֙ כְּ⁠שִׁ֣יר עֲגָבִ֔ים יְפֵ֥ה ק֖וֹל וּ⁠מֵטִ֣ב נַגֵּ֑ן וְ⁠שָֽׁמְעוּ֙ אֶת־דְּבָרֶ֔י⁠ךָ וְ⁠עֹשִׂ֥ים אֵינָ֖⁠ם אוֹתָֽ⁠ם׃","wĕ⁠hinĕ̇⁠ká֤ lá⁠hem֙ kĕ̇⁠şǐ֣yr ʻàgábi֔ym yĕpé֥h q֖wòl ẇ⁠méti֣b nagé֑̇n wĕ⁠şáֽ̌mĕʻẇ֙ ʼeţ-dĕ̇báre֔y⁠ká wĕ⁠ʻòşî֥ym ʼéyná֖⁠m ʼwòţáֽ⁠m׃"],[33,33,"וּ⁠בְ⁠בֹאָ֑⁠הּ הִנֵּ֣ה בָאָ֔ה וְ⁠יָ֣דְע֔וּ כִּ֥י נָבִ֖יא הָיָ֥ה בְ⁠תוֹכָֽ⁠ם׃ס","ẇ⁠bĕ⁠bòʼá֑⁠ḣ hiné֣̇h báʼá֔h wĕ⁠yá֣dĕʻ֔ẇ ki֥̇y nábi֖yʼ háyá֥h bĕ⁠ţwòkáֽ⁠m׃s"],[34,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[34,2,"בֶּן־אָדָ֕ם הִנָּבֵ֖א עַל־רוֹעֵ֣י יִשְׂרָאֵ֑ל הִנָּבֵ֣א וְ⁠אָמַרְתָּ֩ אֲלֵי⁠הֶ֨ם לָ⁠רֹעִ֜ים כֹּ֥ה אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה ה֤וֹי רֹעֵֽי־יִשְׂרָאֵל֙ אֲשֶׁ֤ר הָיוּ֙ רֹעִ֣ים אוֹתָ֔⁠ם הֲ⁠ל֣וֹא הַ⁠צֹּ֔אן יִרְע֖וּ הָ⁠רֹעִֽים׃","bėn-ʼádá֕m hiná̇bé֖ʼ ʻal-rwòʻé֣y yişĕ̂ráʼé֑l hiná̇bé֣ʼ wĕ⁠ʼámarĕţá̇֩ ʼàléy⁠he֨m lá⁠ròʻi֜ym kò֥̇h ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h h֤wòy ròʻéֽy-yişĕ̂ráʼél֙ ʼàşě֤r háyẇ֙ ròʻi֣ym ʼwòţá֔⁠m hà⁠l֣wòʼ ha⁠ẕò̇֔ʼn yirĕʻ֖ẇ há⁠ròʻiֽym׃"],[34,3,"אֶת־הַ⁠חֵ֤לֶב תֹּאכֵ֨לוּ֙ וְ⁠אֶת־הַ⁠צֶּ֣מֶר תִּלְבָּ֔שׁוּ הַ⁠בְּרִיאָ֖ה תִּזְבָּ֑חוּ הַ⁠צֹּ֖אן לֹ֥א תִרְעֽוּ׃","ʼeţ-ha⁠ẖé֤leb ţò̇ʼké֨lẇ֙ wĕ⁠ʼeţ-ha⁠ẕė֣mer ţi̇lĕbá̇֔ş̌ẇ ha⁠bĕ̇riyʼá֖h ţi̇zĕbá֑̇ẖẇ ha⁠ẕò֖̇ʼn lò֥ʼ ţirĕʻֽẇ׃"],[34,4,"אֶֽת־הַ⁠נַּחְלוֹת֩ לֹ֨א חִזַּקְתֶּ֜ם וְ⁠אֶת־הַ⁠חוֹלָ֣ה לֹֽא־רִפֵּאתֶ֗ם וְ⁠לַ⁠נִּשְׁבֶּ֨רֶת֙ לֹ֣א חֲבַשְׁתֶּ֔ם וְ⁠אֶת־הַ⁠נִּדַּ֨חַת֙ לֹ֣א הֲשֵׁבֹתֶ֔ם וְ⁠אֶת־הָ⁠אֹבֶ֖דֶת לֹ֣א בִקַּשְׁתֶּ֑ם וּ⁠בְ⁠חָזְקָ֛ה רְדִיתֶ֥ם אֹתָ֖⁠ם וּ⁠בְ⁠פָֽרֶךְ׃","ʼeֽţ-ha⁠nȧẖĕlwòţ֩ lò֨ʼ ẖizȧqĕţė֜m wĕ⁠ʼeţ-ha⁠ẖwòlá֣h lòֽʼ-ripé̇ʼţe֗m wĕ⁠la⁠ni̇şĕ̌bė֨reţ֙ lò֣ʼ ẖàbaşĕ̌ţė֔m wĕ⁠ʼeţ-ha⁠ni̇dȧ֨ẖaţ֙ lò֣ʼ hàşé̌bòţe֔m wĕ⁠ʼeţ-há⁠ʼòbe֖deţ lò֣ʼ biqȧşĕ̌ţė֑m ẇ⁠bĕ⁠ẖázĕqá֛h rĕdiyţe֥m ʼòţá֖⁠m ẇ⁠bĕ⁠páֽrekĕ׃"],[34,5,"וַ⁠תְּפוּצֶ֖ינָה מִ⁠בְּלִ֣י רֹעֶ֑ה וַ⁠תִּהְיֶ֧ינָה לְ⁠אָכְלָ֛ה לְ⁠כָל־חַיַּ֥ת הַ⁠שָּׂדֶ֖ה וַ⁠תְּפוּצֶֽינָה׃","wa⁠ţĕ̇pẇẕe֖ynáh mi⁠bĕ̇li֣y ròʻe֑h wa⁠ţi̇hĕye֧ynáh lĕ⁠ʼákĕlá֛h lĕ⁠kál-ẖayȧ֥ţ ha⁠şá̇̂de֖h wa⁠ţĕ̇pẇẕeֽynáh׃"],[34,6,"יִשְׁגּ֤וּ צֹאנִ⁠י֙ בְּ⁠כָל־הֶ֣⁠הָרִ֔ים וְ⁠עַ֖ל כָּל־גִּבְעָ֣ה רָמָ֑ה וְ⁠עַ֨ל כָּל־פְּנֵ֤י הָ⁠אָ֨רֶץ֙ נָפֹ֣צוּ צֹאנִ֔⁠י וְ⁠אֵ֥ין דּוֹרֵ֖שׁ וְ⁠אֵ֥ין מְבַקֵּֽשׁ׃","yişĕ̌ġ֤ẇ ẕòʼni⁠y֙ bĕ̇⁠kál-he֣⁠hári֔ym wĕ⁠ʻa֖l ká̇l-gi̇bĕʻá֣h rámá֑h wĕ⁠ʻa֨l ká̇l-pĕ̇né֤y há⁠ʼá֨reẕ֙ nápò֣ẕẇ ẕòʼni֔⁠y wĕ⁠ʼé֥yn ḋwòré֖ş̌ wĕ⁠ʼé֥yn mĕbaqéֽ̇ş̌׃"],[34,7,"לָ⁠כֵ֣ן רֹעִ֔ים שִׁמְע֖וּ אֶת־דְּבַ֥ר יְהוָֽה׃","lá⁠ké֣n ròʻi֔ym şǐmĕʻ֖ẇ ʼeţ-dĕ̇ba֥r yĕhwáֽh׃"],[34,8,"חַי־אָ֜נִי נְאֻ֣ם ׀ אֲדֹנָ֣⁠י יְהוִ֗ה אִם־לֹ֣א יַ֣עַן הֱיֽוֹת־צֹאנִ֣⁠י ׀ לָ⁠בַ֡ז וַ⁠תִּֽהְיֶינָה֩ צֹאנִ֨⁠י לְ⁠אָכְלָ֜ה לְ⁠כָל־חַיַּ֤ת הַ⁠שָּׂדֶה֙ מֵ⁠אֵ֣ין רֹעֶ֔ה וְ⁠לֹֽא־דָרְשׁ֥וּ רֹעַ֖⁠י אֶת־צֹאנִ֑⁠י וַ⁠יִּרְע֤וּ הָֽ⁠רֹעִים֙ אוֹתָ֔⁠ם וְ⁠אֶת־צֹאנִ֖⁠י לֹ֥א רָעֽוּ׃ס","ẖay-ʼá֜niy nĕʼu֣m ׀ ʼàdòná֣⁠y yĕhwi֗h ʼim-lò֣ʼ ya֣ʻan hèyֽwòţ-ẕòʼni֣⁠y ׀ lá⁠ba֡z wa⁠ţiֽ̇hĕyeynáh֩ ẕòʼni֨⁠y lĕ⁠ʼákĕlá֜h lĕ⁠kál-ẖayȧ֤ţ ha⁠şá̇̂deh֙ mé⁠ʼé֣yn ròʻe֔h wĕ⁠lòֽʼ-dárĕş֥̌ẇ ròʻa֖⁠y ʼeţ-ẕòʼni֑⁠y wa⁠yi̇rĕʻ֤ẇ háֽ⁠ròʻiym֙ ʼwòţá֔⁠m wĕ⁠ʼeţ-ẕòʼni֖⁠y lò֥ʼ ráʻֽẇ׃s"],[34,9,"לָ⁠כֵן֙ הָֽ⁠רֹעִ֔ים שִׁמְע֖וּ דְּבַר־יְהוָֽה׃","lá⁠kén֙ háֽ⁠ròʻi֔ym şǐmĕʻ֖ẇ dĕ̇bar-yĕhwáֽh׃"],[34,10,"כֹּה־אָמַ֞ר אֲדֹנָ֣⁠י יְהוִ֗ה הִנְ⁠נִ֨י אֶֽל־הָ⁠רֹעִ֜ים וְֽ⁠דָרַשְׁתִּ֧י אֶת־צֹאנִ֣⁠י מִ⁠יָּדָ֗⁠ם וְ⁠הִשְׁבַּתִּי⁠ם֙ מֵ⁠רְע֣וֹת צֹ֔אן וְ⁠לֹא־יִרְע֥וּ ע֛וֹד הָ⁠רֹעִ֖ים אוֹתָ֑⁠ם וְ⁠הִצַּלְתִּ֤י צֹאנִ⁠י֙ מִ⁠פִּי⁠הֶ֔ם וְ⁠לֹֽא־תִהְיֶ֥יןָ לָ⁠הֶ֖ם לְ⁠אָכְלָֽה׃ס","kò̇h-ʼáma֞r ʼàdòná֣⁠y yĕhwi֗h hinĕ⁠ni֨y ʼeֽl-há⁠ròʻi֜ym wĕֽ⁠dáraşĕ̌ţi֧̇y ʼeţ-ẕòʼni֣⁠y mi⁠yá̇dá֗⁠m wĕ⁠hişĕ̌bȧţi̇y⁠m֙ mé⁠rĕʻ֣wòţ ẕò֔ʼn wĕ⁠lòʼ-yirĕʻ֥ẇ ʻ֛wòd há⁠ròʻi֖ym ʼwòţá֑⁠m wĕ⁠hiẕȧlĕţi֤̇y ẕòʼni⁠y֙ mi⁠pi̇y⁠he֔m wĕ⁠lòֽʼ-ţihĕye֥yná lá⁠he֖m lĕ⁠ʼákĕláֽh׃s"],[34,11,"כִּ֛י כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה הִנְ⁠נִי־אָ֕נִי וְ⁠דָרַשְׁתִּ֥י אֶת־צֹאנִ֖⁠י וּ⁠בִקַּרְתִּֽי⁠ם׃","ki֛̇y kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h hinĕ⁠niy-ʼá֕niy wĕ⁠dáraşĕ̌ţi֥̇y ʼeţ-ẕòʼni֖⁠y ẇ⁠biqȧrĕţiֽ̇y⁠m׃"],[34,12,"כְּ⁠בַקָּרַת֩ רֹעֶ֨ה עֶדְר֜⁠וֹ בְּ⁠יוֹם־הֱיוֹת֤⁠וֹ בְ⁠תוֹךְ־צֹאנ⁠וֹ֙ נִפְרָשׁ֔וֹת כֵּ֖ן אֲבַקֵּ֣ר אֶת־צֹאנִ֑⁠י וְ⁠הִצַּלְתִּ֣י אֶתְ⁠הֶ֗ם מִ⁠כָּל־הַ⁠מְּקוֹמֹת֙ אֲשֶׁ֣ר נָפֹ֣צוּ שָׁ֔ם בְּ⁠י֥וֹם עָנָ֖ן וַ⁠עֲרָפֶֽל׃","kĕ̇⁠baqá̇raţ֩ ròʻe֨h ʻedĕr֜⁠wò bĕ̇⁠ywòm-hèywòţ֤⁠wò bĕ⁠ţwòkĕ-ẕòʼn⁠wò֙ nipĕráş̌֔wòţ ké֖̇n ʼàbaqé֣̇r ʼeţ-ẕòʼni֑⁠y wĕ⁠hiẕȧlĕţi֣̇y ʼeţĕ⁠he֗m mi⁠ká̇l-ha⁠mĕ̇qwòmòţ֙ ʼàşě֣r nápò֣ẕẇ şá̌֔m bĕ̇⁠y֥wòm ʻáná֖n wa⁠ʻàrápeֽl׃"],[34,13,"וְ⁠הוֹצֵאתִ֣י⁠ם מִן־הָ⁠עַמִּ֗ים וְ⁠קִבַּצְתִּי⁠ם֙ מִן־הָ֣⁠אֲרָצ֔וֹת וַ⁠הֲבִיאֹתִ֖י⁠ם אֶל־אַדְמָתָ֑⁠ם וּ⁠רְעִיתִי⁠ם֙ אֶל־הָרֵ֣י יִשְׂרָאֵ֔ל בָּ⁠אֲפִיקִ֕ים וּ⁠בְ⁠כֹ֖ל מוֹשְׁבֵ֥י הָ⁠אָֽרֶץ׃","wĕ⁠hwòẕéʼţi֣y⁠m min-há⁠ʻami̇֗ym wĕ⁠qibȧẕĕţi̇y⁠m֙ min-há֣⁠ʼàráẕ֔wòţ wa⁠hàbiyʼòţi֖y⁠m ʼel-ʼadĕmáţá֑⁠m ẇ⁠rĕʻiyţiy⁠m֙ ʼel-háré֣y yişĕ̂ráʼé֔l bá̇⁠ʼàpiyqi֕ym ẇ⁠bĕ⁠kò֖l mwòşĕ̌bé֥y há⁠ʼáֽreẕ׃"],[34,14,"בְּ⁠מִרְעֶה־טּוֹב֙ אֶרְעֶ֣ה אֹתָ֔⁠ם וּ⁠בְ⁠הָרֵ֥י מְרֽוֹם־יִשְׂרָאֵ֖ל יִהְיֶ֣ה נְוֵ⁠הֶ֑ם שָׁ֤ם תִּרְבַּ֨צְנָה֙ בְּ⁠נָ֣וֶה טּ֔וֹב וּ⁠מִרְעֶ֥ה שָׁמֵ֛ן תִּרְעֶ֖ינָה אֶל־הָרֵ֥י יִשְׂרָאֵֽל׃","bĕ̇⁠mirĕʻeh-ṫwòb֙ ʼerĕʻe֣h ʼòţá֔⁠m ẇ⁠bĕ⁠háré֥y mĕrֽwòm-yişĕ̂ráʼé֖l yihĕye֣h nĕwé⁠he֑m şá֤̌m ţi̇rĕbȧ֨ẕĕnáh֙ bĕ̇⁠ná֣weh ṫ֔wòb ẇ⁠mirĕʻe֥h şá̌mé֛n ţi̇rĕʻe֖ynáh ʼel-háré֥y yişĕ̂ráʼéֽl׃"],[34,15,"אֲנִ֨י אֶרְעֶ֤ה צֹאנִ⁠י֙ וַ⁠אֲנִ֣י אַרְבִּיצֵ֔⁠ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","ʼàni֨y ʼerĕʻe֤h ẕòʼni⁠y֙ wa⁠ʼàni֣y ʼarĕbi̇yẕé֔⁠m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[34,16,"אֶת־הָ⁠אֹבֶ֤דֶת אֲבַקֵּשׁ֙ וְ⁠אֶת־הַ⁠נִּדַּ֣חַת אָשִׁ֔יב וְ⁠לַ⁠נִּשְׁבֶּ֣רֶת אֶחֱבֹ֔שׁ וְ⁠אֶת־הַ⁠חוֹלָ֖ה אֲחַזֵּ֑ק וְ⁠אֶת־הַ⁠שְּׁמֵנָ֧ה וְ⁠אֶת־הַ⁠חֲזָקָ֛ה אַשְׁמִ֖יד אֶרְעֶ֥⁠נָּה בְ⁠מִשְׁפָּֽט׃","ʼeţ-há⁠ʼòbe֤deţ ʼàbaqé̇ş̌֙ wĕ⁠ʼeţ-ha⁠ni̇dȧ֣ẖaţ ʼáşǐ֔yb wĕ⁠la⁠ni̇şĕ̌bė֣reţ ʼeẖèbò֔ş̌ wĕ⁠ʼeţ-ha⁠ẖwòlá֖h ʼàẖazé֑̇q wĕ⁠ʼeţ-ha⁠şĕ̇̌méná֧h wĕ⁠ʼeţ-ha⁠ẖàzáqá֛h ʼaşĕ̌mi֖yd ʼerĕʻe֥⁠ná̇h bĕ⁠mişĕ̌páֽ̇t׃"],[34,17,"וְ⁠אַתֵּ֣נָה צֹאנִ֔⁠י כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה הִנְ⁠נִ֤י שֹׁפֵט֙ בֵּֽין־שֶׂ֣ה לָ⁠שֶׂ֔ה לָ⁠אֵילִ֖ים וְ⁠לָ⁠עַתּוּדִֽים׃","wĕ⁠ʼaţé֣̇náh ẕòʼni֔⁠y kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h hinĕ⁠ni֤y şò̌pét֙ béֽ̇yn-şê֣h lá⁠şê֔h lá⁠ʼéyli֖ym wĕ⁠lá⁠ʻaţ̇ẇdiֽym׃"],[34,18,"הַ⁠מְעַ֣ט מִ⁠כֶּ֗ם הַ⁠מִּרְעֶ֤ה הַ⁠טּוֹב֙ תִּרְע֔וּ וְ⁠יֶ֨תֶר֙ מִרְעֵי⁠כֶ֔ם תִּרְמְס֖וּ בְּ⁠רַגְלֵי⁠כֶ֑ם וּ⁠מִשְׁקַע־מַ֣יִם תִּשְׁתּ֔וּ וְ⁠אֵת֙ הַ⁠נּ֣וֹתָרִ֔ים בְּ⁠רַגְלֵי⁠כֶ֖ם תִּרְפֹּשֽׂוּ⁠ן׃","ha⁠mĕʻa֣t mi⁠kė֗m ha⁠mi̇rĕʻe֤h ha⁠ṫwòb֙ ţi̇rĕʻ֔ẇ wĕ⁠ye֨ţer֙ mirĕʻéy⁠ke֔m ţi̇rĕmĕs֖ẇ bĕ̇⁠ragĕléy⁠ke֑m ẇ⁠mişĕ̌qaʻ-ma֣yim ţi̇şĕ̌ţ̇֔ẇ wĕ⁠ʼéţ֙ ha⁠ṅ֣wòţári֔ym bĕ̇⁠ragĕléy⁠ke֖m ţi̇rĕpò̇şֽ̂ẇ⁠n׃"],[34,19,"וְ⁠צֹאנִ֑⁠י מִרְמַ֤ס רַגְלֵי⁠כֶם֙ תִּרְעֶ֔ינָה וּ⁠מִרְפַּ֥שׂ רַגְלֵי⁠כֶ֖ם תִּשְׁתֶּֽינָה׃ס","wĕ⁠ẕòʼni֑⁠y mirĕma֤s ragĕléy⁠kem֙ ţi̇rĕʻe֔ynáh ẇ⁠mirĕpȧ֥ş̂ ragĕléy⁠ke֖m ţi̇şĕ̌ţėֽynáh׃s"],[34,20,"לָ⁠כֵ֗ן כֹּ֥ה אָמַ֛ר אֲדֹנָ֥⁠י יְהוִ֖ה אֲלֵי⁠הֶ֑ם הִנְ⁠נִי־אָ֕נִי וְ⁠שָֽׁפַטְתִּי֙ בֵּֽין־שֶׂ֣ה בִרְיָ֔ה וּ⁠בֵ֥ין שֶׂ֖ה רָזָֽה׃","lá⁠ké֗n kò֥̇h ʼáma֛r ʼàdòná֥⁠y yĕhwi֖h ʼàléy⁠he֑m hinĕ⁠niy-ʼá֕niy wĕ⁠şáֽ̌patĕţi̇y֙ béֽ̇yn-şê֣h birĕyá֔h ẇ⁠bé֥yn şê֖h rázáֽh׃"],[34,21,"יַ֗עַן בְּ⁠צַ֤ד וּ⁠בְ⁠כָתֵף֙ תֶּהְדֹּ֔פוּ וּ⁠בְ⁠קַרְנֵי⁠כֶ֥ם תְּנַגְּח֖וּ כָּל־הַ⁠נַּחְל֑וֹת עַ֣ד אֲשֶׁ֧ר הֲפִיצוֹתֶ֛ם אוֹתָ֖⁠נָה אֶל־הַ⁠חֽוּצָ⁠ה׃","ya֗ʻan bĕ̇⁠ẕa֤d ẇ⁠bĕ⁠káţép֙ ţėhĕdò̇֔pẇ ẇ⁠bĕ⁠qarĕnéy⁠ke֥m ţĕ̇nagĕ̇ẖ֖ẇ ká̇l-ha⁠nȧẖĕl֑wòţ ʻa֣d ʼàşě֧r hàpiyẕwòţe֛m ʼwòţá֖⁠náh ʼel-ha⁠ẖֽẇẕá⁠h׃"],[34,22,"וְ⁠הוֹשַׁעְתִּ֣י לְ⁠צֹאנִ֔⁠י וְ⁠לֹֽא־תִהְיֶ֥ינָה ע֖וֹד לָ⁠בַ֑ז וְ⁠שָׁ֣פַטְתִּ֔י בֵּ֥ין שֶׂ֖ה לָ⁠שֶֽׂה׃","wĕ⁠hwòşǎʻĕţi֣̇y lĕ⁠ẕòʼni֔⁠y wĕ⁠lòֽʼ-ţihĕye֥ynáh ʻ֖wòd lá⁠ba֑z wĕ⁠şá֣̌patĕţi̇֔y bé֥̇yn şê֖h lá⁠şêֽh׃"],[34,23,"וַ⁠הֲקִמֹתִ֨י עֲלֵי⁠הֶ֜ם רֹעֶ֤ה אֶחָד֙ וְ⁠רָעָ֣ה אֶתְ⁠הֶ֔ן אֵ֖ת עַבְדִּ֣⁠י דָוִ֑יד ה֚וּא יִרְעֶ֣ה אֹתָ֔⁠ם וְ⁠הֽוּא־יִהְיֶ֥ה לָ⁠הֶ֖ן לְ⁠רֹעֶֽה׃","wa⁠hàqimòţi֨y ʻàléy⁠he֜m ròʻe֤h ʼeẖád֙ wĕ⁠ráʻá֣h ʼeţĕ⁠he֔n ʼé֖ţ ʻabĕdi֣̇⁠y dáwi֑yd h֚ẇʼ yirĕʻe֣h ʼòţá֔⁠m wĕ⁠hֽẇʼ-yihĕye֥h lá⁠he֖n lĕ⁠ròʻeֽh׃"],[34,24,"וַ⁠אֲנִ֣י יְהוָ֗ה אֶהְיֶ֤ה לָ⁠הֶם֙ לֵֽ⁠אלֹהִ֔ים וְ⁠עַבְדִּ֥⁠י דָוִ֖ד נָשִׂ֣יא בְ⁠תוֹכָ֑⁠ם אֲנִ֥י יְהוָ֖ה דִּבַּֽרְתִּי׃","wa⁠ʼàni֣y yĕhwá֗h ʼehĕye֤h lá⁠hem֙ léֽ⁠ʼlòhi֔ym wĕ⁠ʻabĕdi֥̇⁠y dáwi֖d náşî֣yʼ bĕ⁠ţwòká֑⁠m ʼàni֥y yĕhwá֖h di̇bȧֽrĕţi̇y׃"],[34,25,"וְ⁠כָרַתִּ֤י לָ⁠הֶם֙ בְּרִ֣ית שָׁל֔וֹם וְ⁠הִשְׁבַּתִּ֥י חַיָּֽה־רָעָ֖ה מִן־הָ⁠אָ֑רֶץ וְ⁠יָשְׁב֤וּ בַ⁠מִּדְבָּר֙ לָ⁠בֶ֔טַח וְ⁠יָשְׁנ֖וּ בַּ⁠יְּעָרִֽים׃","wĕ⁠káraţi֤̇y lá⁠hem֙ bĕ̇ri֣yţ şá̌l֔wòm wĕ⁠hişĕ̌bȧţi֥̇y ẖayáֽ̇h-ráʻá֖h min-há⁠ʼá֑reẕ wĕ⁠yáşĕ̌b֤ẇ ba⁠mi̇dĕbá̇r֙ lá⁠be֔taẖ wĕ⁠yáşĕ̌n֖ẇ bȧ⁠yĕ̇ʻáriֽym׃"],[34,26,"וְ⁠נָתַתִּ֥י אוֹתָ֛⁠ם וּ⁠סְבִיב֥וֹת גִּבְעָתִ֖⁠י בְּרָכָ֑ה וְ⁠הוֹרַדְתִּ֤י הַ⁠גֶּ֨שֶׁם֙ בְּ⁠עִתּ֔⁠וֹ גִּשְׁמֵ֥י בְרָכָ֖ה יִֽהְיֽוּ׃","wĕ⁠náţaţi֥̇y ʼwòţá֛⁠m ẇ⁠sĕbiyb֥wòţ gi̇bĕʻáţi֖⁠y bĕ̇ráká֑h wĕ⁠hwòradĕţi֤̇y ha⁠gė֨şěm֙ bĕ̇⁠ʻiţ̇֔⁠wò gi̇şĕ̌mé֥y bĕráká֖h yiֽhĕyֽẇ׃"],[34,27,"וְ⁠נָתַן֩ עֵ֨ץ הַ⁠שָּׂדֶ֜ה אֶת־פִּרְי֗⁠וֹ וְ⁠הָ⁠אָ֨רֶץ֙ תִּתֵּ֣ן יְבוּלָ֔⁠הּ וְ⁠הָי֥וּ עַל־אַדְמָתָ֖⁠ם לָ⁠בֶ֑טַח וְֽ⁠יָדְע֞וּ כִּי־אֲנִ֣י יְהוָ֗ה בְּ⁠שִׁבְרִ⁠י֙ אֶת־מֹט֣וֹת עֻלָּ֔⁠ם וְ⁠הִ֨צַּלְתִּ֔י⁠ם מִ⁠יַּ֖ד הָ⁠עֹבְדִ֥ים בָּ⁠הֶֽם׃","wĕ⁠náţan֩ ʻé֨ẕ ha⁠şá̇̂de֜h ʼeţ-pi̇rĕy֗⁠wò wĕ⁠há⁠ʼá֨reẕ֙ ţi̇ţé֣̇n yĕbẇlá֔⁠ḣ wĕ⁠háy֥ẇ ʻal-ʼadĕmáţá֖⁠m lá⁠be֑taẖ wĕֽ⁠yádĕʻ֞ẇ ki̇y-ʼàni֣y yĕhwá֗h bĕ̇⁠şǐbĕri⁠y֙ ʼeţ-mòt֣wòţ ʻulá̇֔⁠m wĕ⁠hi֨ẕȧlĕţi̇֔y⁠m mi⁠yȧ֖d há⁠ʻòbĕdi֥ym bá̇⁠heֽm׃"],[34,28,"וְ⁠לֹא־יִהְי֨וּ ע֥וֹד בַּז֙ לַ⁠גּוֹיִ֔ם וְ⁠חַיַּ֥ת הָ⁠אָ֖רֶץ לֹ֣א תֹאכְלֵ֑⁠ם וְ⁠יָשְׁב֥וּ לָ⁠בֶ֖טַח וְ⁠אֵ֥ין מַחֲרִֽיד׃","wĕ⁠lòʼ-yihĕy֨ẇ ʻ֥wòd bȧz֙ la⁠ġwòyi֔m wĕ⁠ẖayȧ֥ţ há⁠ʼá֖reẕ lò֣ʼ ţòʼkĕlé֑⁠m wĕ⁠yáşĕ̌b֥ẇ lá⁠be֖taẖ wĕ⁠ʼé֥yn maẖàriֽyd׃"],[34,29,"וַ⁠הֲקִמֹתִ֥י לָ⁠הֶ֛ם מַטָּ֖ע לְ⁠שֵׁ֑ם וְ⁠לֹֽא־יִהְי֨וּ ע֜וֹד אֲסֻפֵ֤י רָעָב֙ בָּ⁠אָ֔רֶץ וְ⁠לֹֽא־יִשְׂא֥וּ ע֖וֹד כְּלִמַּ֥ת הַ⁠גּוֹיִֽם׃","wa⁠hàqimòţi֥y lá⁠he֛m matá֖̇ʻ lĕ⁠şé֑̌m wĕ⁠lòֽʼ-yihĕy֨ẇ ʻ֜wòd ʼàsupé֤y ráʻáb֙ bá̇⁠ʼá֔reẕ wĕ⁠lòֽʼ-yişĕ̂ʼ֥ẇ ʻ֖wòd kĕ̇limȧ֥ţ ha⁠ġwòyiֽm׃"],[34,30,"וְ⁠יָדְע֗וּ כִּ֣י אֲנִ֧י יְהוָ֛ה אֱלֹהֵי⁠הֶ֖ם אִתָּ֑⁠ם וְ⁠הֵ֗מָּה עַמִּ⁠י֙ בֵּ֣ית יִשְׂרָאֵ֔ל נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wĕ⁠yádĕʻ֗ẇ ki֣̇y ʼàni֧y yĕhwá֛h ʼèlòhéy⁠he֖m ʼiţá֑̇⁠m wĕ⁠hé֗má̇h ʻami̇⁠y֙ bé֣̇yţ yişĕ̂ráʼé֔l nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[34,31,"וְ⁠אַתֵּ֥ן צֹאנִ֛⁠י צֹ֥אן מַרְעִיתִ֖⁠י אָדָ֣ם אַתֶּ֑ם אֲנִי֙ אֱלֹ֣הֵי⁠כֶ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","wĕ⁠ʼaţé֥̇n ẕòʼni֛⁠y ẕò֥ʼn marĕʻiyţi֖⁠y ʼádá֣m ʼaţė֑m ʼàniy֙ ʼèlò֣héy⁠ke֔m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[35,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[35,2,"בֶּן־אָדָ֕ם שִׂ֥ים פָּנֶ֖י⁠ךָ עַל־הַ֣ר שֵׂעִ֑יר וְ⁠הִנָּבֵ֖א עָלָֽי⁠ו׃","bėn-ʼádá֕m şî֥ym pá̇ne֖y⁠ká ʻal-ha֣r şé̂ʻi֑yr wĕ⁠hiná̇bé֖ʼ ʻáláֽy⁠w׃"],[35,3,"וְ⁠אָמַ֣רְתָּ לּ֗⁠וֹ כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הִנְ⁠נִ֥י אֵלֶ֖י⁠ךָ הַר־שֵׂעִ֑יר וְ⁠נָטִ֤יתִי יָדִ⁠י֙ עָלֶ֔י⁠ךָ וּ⁠נְתַתִּ֖י⁠ךָ שְׁמָמָ֥ה וּ⁠מְשַׁמָּֽה׃","wĕ⁠ʼáma֣rĕţá̇ l̇֗⁠wò kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h hinĕ⁠ni֥y ʼéle֖y⁠ká har-şé̂ʻi֑yr wĕ⁠náti֤yţiy yádi⁠y֙ ʻále֔y⁠ká ẇ⁠nĕţaţi֖̇y⁠ká şĕ̌mámá֥h ẇ⁠mĕşǎmáֽ̇h׃"],[35,4,"עָרֶ֨י⁠ךָ֙ חָרְבָּ֣ה אָשִׂ֔ים וְ⁠אַתָּ֖ה שְׁמָמָ֣ה תִֽהְיֶ֑ה וְ⁠יָדַעְתָּ֖ כִּֽי־אֲנִ֥י יְהוָֽה׃","ʻáre֨y⁠ká֙ ẖárĕbá֣̇h ʼáşî֔ym wĕ⁠ʼaţá֖̇h şĕ̌mámá֣h ţiֽhĕye֑h wĕ⁠yádaʻĕţá֖̇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[35,5,"יַ֗עַן הֱי֤וֹת לְ⁠ךָ֙ אֵיבַ֣ת עוֹלָ֔ם וַ⁠תַּגֵּ֥ר אֶת־בְּנֵֽי־יִשְׂרָאֵ֖ל עַל־יְדֵי־חָ֑רֶב בְּ⁠עֵ֣ת אֵידָ֔⁠ם בְּ⁠עֵ֖ת עֲוֺ֥ן קֵֽץ׃","ya֗ʻan hèy֤wòţ lĕ⁠ká֙ ʼéyba֣ţ ʻwòlá֔m wa⁠ţȧgé֥̇r ʼeţ-bĕ̇néֽy-yişĕ̂ráʼé֖l ʻal-yĕdéy-ẖá֑reb bĕ̇⁠ʻé֣ţ ʼéydá֔⁠m bĕ̇⁠ʻé֖ţ ʻàwֺ֥n qéֽẕ׃"],[35,6,"לָ⁠כֵ֣ן חַי־אָ֗נִי נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה כִּֽי־לְ⁠דָ֥ם אֶעֶשְׂ⁠ךָ֖ וְ⁠דָ֣ם יִרְדֲּפֶ֑⁠ךָ אִם־לֹ֥א דָ֛ם שָׂנֵ֖אתָ וְ⁠דָ֥ם יִרְדֲּפֶֽ⁠ךָ׃","lá⁠ké֣n ẖay-ʼá֗niy nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h kiֽ̇y-lĕ⁠dá֥m ʼeʻeşĕ̂⁠ká֖ wĕ⁠dá֣m yirĕdà̇pe֑⁠ká ʼim-lò֥ʼ dá֛m şá̂né֖ʼţá wĕ⁠dá֥m yirĕdà̇peֽ⁠ká׃"],[35,7,"וְ⁠נָֽתַתִּי֙ אֶת־הַ֣ר שֵׂעִ֔יר לְ⁠שִֽׁמְמָ֖ה וּ⁠שְׁמָמָ֑ה וְ⁠הִכְרַתִּ֥י מִמֶּ֖⁠נּוּ עֹבֵ֥ר וָ⁠שָֽׁב׃","wĕ⁠náֽţaţi̇y֙ ʼeţ-ha֣r şé̂ʻi֔yr lĕ⁠şǐֽmĕmá֖h ẇ⁠şĕ̌mámá֑h wĕ⁠hikĕraţi֥̇y mimė֖⁠ṅẇ ʻòbé֥r wá⁠şáֽ̌b׃"],[35,8,"וּ⁠מִלֵּאתִ֥י אֶת־הָרָ֖י⁠ו חֲלָלָ֑י⁠ו גִּבְעוֹתֶ֤י⁠ךָ וְ⁠גֵאוֹתֶ֨י⁠ךָ֙ וְ⁠כָל־אֲפִיקֶ֔י⁠ךָ חַלְלֵי־חֶ֖רֶב יִפְּל֥וּ בָ⁠הֶֽם׃","ẇ⁠milé̇ʼţi֥y ʼeţ-hárá֖y⁠w ẖàlálá֑y⁠w gi̇bĕʻwòţe֤y⁠ká wĕ⁠géʼwòţe֨y⁠ká֙ wĕ⁠kál-ʼàpiyqe֔y⁠ká ẖalĕléy-ẖe֖reb yipĕ̇l֥ẇ bá⁠heֽm׃"],[35,9,"שִֽׁמְמ֤וֹת עוֹלָם֙ אֶתֶּנְ⁠ךָ֔ וְ⁠עָרֶ֖י⁠ךָ לֹ֣א תישבנה וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃","şǐֽmĕm֤wòţ ʻwòlám֙ ʼeţėnĕ⁠ká֔ wĕ⁠ʻáre֖y⁠ká lò֣ʼ ţyşbnh wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[35,10,"יַ֣עַן אֲ֠מָרְ⁠ךָ אֶת־שְׁנֵ֨י הַ⁠גּוֹיִ֜ם וְ⁠אֶת־שְׁתֵּ֧י הָ⁠אֲרָצ֛וֹת לִ֥⁠י תִהְיֶ֖ינָה וִֽ⁠ירַשְׁנ֑וּ⁠הָ וַֽ⁠יהוָ֖ה שָׁ֥ם הָיָֽה׃","ya֣ʻan ʼà֠márĕ⁠ká ʼeţ-şĕ̌né֨y ha⁠ġwòyi֜m wĕ⁠ʼeţ-şĕ̌ţé֧̇y há⁠ʼàráẕ֛wòţ li֥⁠y ţihĕye֖ynáh wiֽ⁠yraşĕ̌n֑ẇ⁠há waֽ⁠yhwá֖h şá֥̌m háyáֽh׃"],[35,11,"לָ⁠כֵ֣ן חַי־אָ֗נִי נְאֻם֮ אֲדֹנָ֣⁠י יְהוִה֒ וְ⁠עָשִׂ֗יתִי כְּ⁠אַפְּ⁠ךָ֙ וּ⁠כְ⁠קִנְאָ֣תְ⁠ךָ֔ אֲשֶׁ֣ר עָשִׂ֔יתָה מִ⁠שִּׂנְאָתֶ֖י⁠ךָ בָּ֑⁠ם וְ⁠נוֹדַ֥עְתִּי בָ֖⁠ם כַּ⁠אֲשֶׁ֥ר אֶשְׁפְּטֶֽ⁠ךָ׃","lá⁠ké֣n ẖay-ʼá֗niy nĕʼum֮ ʼàdòná֣⁠y yĕhwih֒ wĕ⁠ʻáşî֗yţiy kĕ̇⁠ʼapĕ̇⁠ká֙ ẇ⁠kĕ⁠qinĕʼá֣ţĕ⁠ká֔ ʼàşě֣r ʻáşî֔yţáh mi⁠şi̇̂nĕʼáţe֖y⁠ká bá֑̇⁠m wĕ⁠nwòda֥ʻĕţi̇y bá֖⁠m kȧ⁠ʼàşě֥r ʼeşĕ̌pĕ̇teֽ⁠ká׃"],[35,12,"וְֽ⁠יָדַעְתָּ֮ כִּֽי־אֲנִ֣י יְהוָה֒ שָׁמַ֣עְתִּי ׀ אֶת־כָּל־נָאָֽצוֹתֶ֗י⁠ךָ אֲשֶׁ֥ר אָמַ֛רְתָּ עַל־הָרֵ֥י יִשְׂרָאֵ֖ל לֵ⁠אמֹ֣ר ׀ שממה לָ֥⁠נוּ נִתְּנ֖וּ לְ⁠אָכְלָֽה׃","wĕֽ⁠yádaʻĕţá֮̇ kiֽ̇y-ʼàni֣y yĕhwáh֒ şá̌ma֣ʻĕţi̇y ׀ ʼeţ-ká̇l-náʼáֽẕwòţe֗y⁠ká ʼàşě֥r ʼáma֛rĕţá̇ ʻal-háré֥y yişĕ̂ráʼé֖l lé⁠ʼmò֣r ׀ şmmh lá֥⁠nẇ niţĕ̇n֖ẇ lĕ⁠ʼákĕláֽh׃"],[35,13,"וַ⁠תַּגְדִּ֤ילוּ עָלַ⁠י֙ בְּ⁠פִי⁠כֶ֔ם וְ⁠הַעְתַּרְתֶּ֥ם עָלַ֖⁠י דִּבְרֵי⁠כֶ֑ם אֲנִ֖י שָׁמָֽעְתִּי׃ס","wa⁠ţȧgĕdi֤̇ylẇ ʻála⁠y֙ bĕ̇⁠piy⁠ke֔m wĕ⁠haʻĕţȧrĕţė֥m ʻála֖⁠y di̇bĕréy⁠ke֑m ʼàni֖y şá̌máֽʻĕţi̇y׃s"],[35,14,"כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה כִּ⁠שְׂמֹ֨חַ֙ כָּל־הָ⁠אָ֔רֶץ שְׁמָמָ֖ה אֶעֱשֶׂה־לָּֽ⁠ךְ׃","kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h ki̇⁠şĕ̂mò֨ẖa֙ ká̇l-há⁠ʼá֔reẕ şĕ̌mámá֖h ʼeʻèşêh-láֽ̇⁠kĕ׃"],[35,15,"כְּ⁠שִׂמְחָ֨תְ⁠ךָ֜ לְ⁠נַחְלַ֧ת בֵּֽית־יִשְׂרָאֵ֛ל עַ֥ל אֲשֶׁר־שָׁמֵ֖מָה כֵּ֣ן אֶעֱשֶׂה־לָּ֑⁠ךְ שְׁמָמָ֨ה תִֽהְיֶ֤ה הַר־שֵׂעִיר֙ וְ⁠כָל־אֱד֣וֹם כֻּלָּ֔⁠הּ וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃פ","kĕ̇⁠şîmĕẖá֨ţĕ⁠ká֜ lĕ⁠naẖĕla֧ţ béֽ̇yţ-yişĕ̂ráʼé֛l ʻa֥l ʼàşěr-şá̌mé֖máh ké֣̇n ʼeʻèşêh-lá֑̇⁠kĕ şĕ̌mámá֨h ţiֽhĕye֤h har-şé̂ʻiyr֙ wĕ⁠kál-ʼèd֣wòm ku̇lá̇֔⁠ḣ wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃p"],[36,1,"וְ⁠אַתָּ֣ה בֶן־אָדָ֔ם הִנָּבֵ֖א אֶל־הָרֵ֣י יִשְׂרָאֵ֑ל וְ⁠אָ֣מַרְתָּ֔ הָרֵי֙ יִשְׂרָאֵ֔ל שִׁמְע֖וּ דְּבַר־יְהוָֽה׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֔m hiná̇bé֖ʼ ʼel-háré֣y yişĕ̂ráʼé֑l wĕ⁠ʼá֣marĕţá̇֔ háréy֙ yişĕ̂ráʼé֔l şǐmĕʻ֖ẇ dĕ̇bar-yĕhwáֽh׃"],[36,2,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה יַ֣עַן אָמַ֧ר הָ⁠אוֹיֵ֛ב עֲלֵי⁠כֶ֖ם הֶאָ֑ח וּ⁠בָמ֣וֹת עוֹלָ֔ם לְ⁠מֽוֹרָשָׁ֖ה הָ֥יְתָה לָּֽ⁠נוּ׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ya֣ʻan ʼáma֧r há⁠ʼwòyé֛b ʻàléy⁠ke֖m heʼá֑ẖ ẇ⁠bám֣wòţ ʻwòlá֔m lĕ⁠mֽwòráşá֖̌h há֥yĕţáh láֽ̇⁠nẇ׃"],[36,3,"לָ⁠כֵן֙ הִנָּבֵ֣א וְ⁠אָמַרְתָּ֔ כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה יַ֣עַן בְּ⁠יַ֡עַן שַׁמּוֹת֩ וְ⁠שָׁאֹ֨ף אֶתְ⁠כֶ֜ם מִ⁠סָּבִ֗יב לִֽ⁠הְיוֹתְ⁠כֶ֤ם מֽוֹרָשָׁה֙ לִ⁠שְׁאֵרִ֣ית הַ⁠גּוֹיִ֔ם וַ⁠תֵּֽעֲל֛וּ עַל־שְׂפַ֥ת לָשׁ֖וֹן וְ⁠דִבַּת־עָֽם׃","lá⁠kén֙ hiná̇bé֣ʼ wĕ⁠ʼámarĕţá̇֔ kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h ya֣ʻan bĕ̇⁠ya֡ʻan şǎṁwòţ֩ wĕ⁠şá̌ʼò֨p ʼeţĕ⁠ke֜m mi⁠sá̇bi֗yb liֽ⁠hĕywòţĕ⁠ke֤m mֽwòráşá̌h֙ li⁠şĕ̌ʼéri֣yţ ha⁠ġwòyi֔m wa⁠ţéֽ̇ʻàl֛ẇ ʻal-şĕ̂pa֥ţ láş֖̌wòn wĕ⁠dibȧţ-ʻáֽm׃"],[36,4,"לָ⁠כֵן֙ הָרֵ֣י יִשְׂרָאֵ֔ל שִׁמְע֖וּ דְּבַר־אֲדֹנָ֣⁠י יְהוִ֑ה כֹּֽה־אָמַ֣ר אֲדֹנָ֣⁠י יְ֠הוִה לֶ⁠הָרִ֨ים וְ⁠לַ⁠גְּבָע֜וֹת לָ⁠אֲפִיקִ֣ים וְ⁠לַ⁠גֵּאָי֗וֹת וְ⁠לֶ⁠חֳרָב֤וֹת הַ⁠שֹּֽׁמְמוֹת֙ וְ⁠לֶ⁠עָרִ֣ים הַ⁠נֶּעֱזָב֔וֹת אֲשֶׁ֨ר הָי֤וּ לְ⁠בַז֙ וּ⁠לְ⁠לַ֔עַג לִ⁠שְׁאֵרִ֥ית הַ⁠גּוֹיִ֖ם אֲשֶׁ֥ר מִ⁠סָּבִֽיב׃ס","lá⁠kén֙ háré֣y yişĕ̂ráʼé֔l şǐmĕʻ֖ẇ dĕ̇bar-ʼàdòná֣⁠y yĕhwi֑h kòֽ̇h-ʼáma֣r ʼàdòná֣⁠y yĕ֠hwih le⁠hári֨ym wĕ⁠la⁠gĕ̇báʻ֜wòţ lá⁠ʼàpiyqi֣ym wĕ⁠la⁠gé̇ʼáy֗wòţ wĕ⁠le⁠ẖoráb֤wòţ ha⁠şòֽ̇̌mĕmwòţ֙ wĕ⁠le⁠ʻári֣ym ha⁠nėʻèzáb֔wòţ ʼàşě֨r háy֤ẇ lĕ⁠baz֙ ẇ⁠lĕ⁠la֔ʻag li⁠şĕ̌ʼéri֥yţ ha⁠ġwòyi֖m ʼàşě֥r mi⁠sá̇biֽyb׃s"],[36,5,"לָ⁠כֵ֗ן כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ אִם־לֹ֠א בְּ⁠אֵ֨שׁ קִנְאָתִ֥⁠י דִבַּ֛רְתִּי עַל־שְׁאֵרִ֥ית הַ⁠גּוֹיִ֖ם וְ⁠עַל־אֱד֣וֹם כֻּלָּ֑⁠א אֲשֶׁ֣ר נָתְנֽוּ־אֶת־אַרְצִ֣⁠י ׀ לָ֠⁠הֶם לְ⁠מ֨וֹרָשָׁ֜ה בְּ⁠שִׂמְחַ֤ת כָּל־לֵבָב֙ בִּ⁠שְׁאָ֣ט נֶ֔פֶשׁ לְמַ֥עַן מִגְרָשָׁ֖⁠הּ לָ⁠בַֽז׃","lá⁠ké֗n kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ ʼim-lò֠ʼ bĕ̇⁠ʼé֨ş̌ qinĕʼáţi֥⁠y dibȧ֛rĕţi̇y ʻal-şĕ̌ʼéri֥yţ ha⁠ġwòyi֖m wĕ⁠ʻal-ʼèd֣wòm ku̇lá֑̇⁠ʼ ʼàşě֣r náţĕnֽẇ-ʼeţ-ʼarĕẕi֣⁠y ׀ lá֠⁠hem lĕ⁠m֨wòráşá̌֜h bĕ̇⁠şîmĕẖa֤ţ ká̇l-lébáb֙ bi̇⁠şĕ̌ʼá֣t ne֔peş̌ lĕma֥ʻan migĕráşá֖̌⁠ḣ lá⁠baֽz׃"],[36,6,"לָ⁠כֵ֕ן הִנָּבֵ֖א עַל־אַדְמַ֣ת יִשְׂרָאֵ֑ל וְ⁠אָמַרְתָּ֡ לֶ⁠הָרִ֣ים וְ֠⁠לַ⁠גְּבָעוֹת לָ⁠אֲפִיקִ֨ים וְ⁠לַ⁠גֵּאָי֜וֹת כֹּֽה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה הִנְ⁠נִ֨י בְ⁠קִנְאָתִ֤⁠י וּ⁠בַ⁠חֲמָתִ⁠י֙ דִּבַּ֔רְתִּי יַ֛עַן כְּלִמַּ֥ת גּוֹיִ֖ם נְשָׂאתֶֽם׃","lá⁠ké֕n hiná̇bé֖ʼ ʻal-ʼadĕma֣ţ yişĕ̂ráʼé֑l wĕ⁠ʼámarĕţá̇֡ le⁠hári֣ym wĕ֠⁠la⁠gĕ̇báʻwòţ lá⁠ʼàpiyqi֨ym wĕ⁠la⁠gé̇ʼáy֜wòţ kòֽ̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h hinĕ⁠ni֨y bĕ⁠qinĕʼáţi֤⁠y ẇ⁠ba⁠ẖàmáţi⁠y֙ di̇bȧ֔rĕţi̇y ya֛ʻan kĕ̇limȧ֥ţ ġwòyi֖m nĕşá̂ʼţeֽm׃"],[36,7,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה אֲנִ֖י נָשָׂ֣אתִי אֶת־יָדִ֑⁠י אִם־לֹ֤א הַ⁠גּוֹיִם֙ אֲשֶׁ֣ר לָ⁠כֶ֣ם מִ⁠סָּבִ֔יב הֵ֖מָּה כְּלִמָּתָ֥⁠ם יִשָּֽׂאוּ׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ʼàni֖y náşá֣̂ʼţiy ʼeţ-yádi֑⁠y ʼim-lò֤ʼ ha⁠ġwòyim֙ ʼàşě֣r lá⁠ke֣m mi⁠sá̇bi֔yb hé֖má̇h kĕ̇limá̇ţá֥⁠m yişáֽ̇̂ʼẇ׃"],[36,8,"וְ⁠אַתֶּ֞ם הָרֵ֤י יִשְׂרָאֵל֙ עַנְפְּ⁠כֶ֣ם תִּתֵּ֔נוּ וּ⁠פֶרְיְ⁠כֶ֥ם תִּשְׂא֖וּ לְ⁠עַמִּ֣⁠י יִשְׂרָאֵ֑ל כִּ֥י קֵרְב֖וּ לָ⁠בֽוֹא׃","wĕ⁠ʼaţė֞m háré֤y yişĕ̂ráʼél֙ ʻanĕpĕ̇⁠ke֣m ţi̇ţé̇֔nẇ ẇ⁠perĕyĕ⁠ke֥m ţi̇şĕ̂ʼ֖ẇ lĕ⁠ʻami֣̇⁠y yişĕ̂ráʼé֑l ki֥̇y qérĕb֖ẇ lá⁠bֽwòʼ׃"],[36,9,"כִּ֖י הִנְ⁠נִ֣י אֲלֵי⁠כֶ֑ם וּ⁠פָנִ֣יתִי אֲלֵי⁠כֶ֔ם וְ⁠נֶעֱבַדְתֶּ֖ם וְ⁠נִזְרַעְתֶּֽם׃","ki֖̇y hinĕ⁠ni֣y ʼàléy⁠ke֑m ẇ⁠páni֣yţiy ʼàléy⁠ke֔m wĕ⁠neʻèbadĕţė֖m wĕ⁠nizĕraʻĕţėֽm׃"],[36,10,"וְ⁠הִרְבֵּיתִ֤י עֲלֵי⁠כֶם֙ אָדָ֔ם כָּל־בֵּ֥ית יִשְׂרָאֵ֖ל כֻּלֹּ֑⁠ה וְ⁠נֹֽשְׁבוּ֙ הֶֽ⁠עָרִ֔ים וְ⁠הֶ⁠חֳרָב֖וֹת תִּבָּנֶֽינָה׃","wĕ⁠hirĕbé̇yţi֤y ʻàléy⁠kem֙ ʼádá֔m ká̇l-bé֥̇yţ yişĕ̂ráʼé֖l ku̇lò֑̇⁠h wĕ⁠nòֽşĕ̌bẇ֙ heֽ⁠ʻári֔ym wĕ⁠he⁠ẖoráb֖wòţ ţi̇bá̇neֽynáh׃"],[36,11,"וְ⁠הִרְבֵּיתִ֧י עֲלֵי⁠כֶ֛ם אָדָ֥ם וּ⁠בְהֵמָ֖ה וְ⁠רָב֣וּ וּ⁠פָר֑וּ וְ⁠הוֹשַׁבְתִּ֨י אֶתְ⁠כֶ֜ם כְּ⁠קַדְמֽוֹתֵי⁠כֶ֗ם וְ⁠הֵטִֽבֹתִי֙ מֵ⁠רִאשֹׁ֣תֵי⁠כֶ֔ם וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃","wĕ⁠hirĕbé̇yţi֧y ʻàléy⁠ke֛m ʼádá֥m ẇ⁠bĕhémá֖h wĕ⁠ráb֣ẇ ẇ⁠pár֑ẇ wĕ⁠hwòşǎbĕţi̇֨y ʼeţĕ⁠ke֜m kĕ̇⁠qadĕmֽwòţéy⁠ke֗m wĕ⁠hétiֽbòţiy֙ mé⁠riʼşò֣̌ţéy⁠ke֔m wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[36,12,"וְ⁠הוֹלַכְתִּי֩ עֲלֵי⁠כֶ֨ם אָדָ֜ם אֶת־עַמִּ֤⁠י יִשְׂרָאֵל֙ וִֽ⁠ירֵשׁ֔וּ⁠ךָ וְ⁠הָיִ֥יתָ לָ⁠הֶ֖ם לְ⁠נַחֲלָ֑ה וְ⁠לֹא־תוֹסִ֥ף ע֖וֹד לְ⁠שַׁכְּלָֽ⁠ם׃ס","wĕ⁠hwòlakĕţi̇y֩ ʻàléy⁠ke֨m ʼádá֜m ʼeţ-ʻami֤̇⁠y yişĕ̂ráʼél֙ wiֽ⁠yréş̌֔ẇ⁠ká wĕ⁠háyi֥yţá lá⁠he֖m lĕ⁠naẖàlá֑h wĕ⁠lòʼ-ţwòsi֥p ʻ֖wòd lĕ⁠şǎkĕ̇láֽ⁠m׃s"],[36,13,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה יַ֚עַן אֹמְרִ֣ים לָ⁠כֶ֔ם אֹכֶ֥לֶת אָדָ֖ם אתי וּ⁠מְשַׁכֶּ֥לֶת גוי⁠ך הָיִֽית׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ya֚ʻan ʼòmĕri֣ym lá⁠ke֔m ʼòke֥leţ ʼádá֖m ʼţy ẇ⁠mĕşǎkė֥leţ gwy⁠k háyiֽyţ׃"],[36,14,"לָ⁠כֵ֗ן אָדָם֙ לֹא־תֹ֣אכְלִי ע֔וֹד ו⁠גוי⁠ך לֹ֣א תכשלי־ע֑וֹד נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","lá⁠ké֗n ʼádám֙ lòʼ-ţò֣ʼkĕliy ʻ֔wòd w⁠gwy⁠k lò֣ʼ ţkşly-ʻ֑wòd nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[36,15,"וְ⁠לֹא־אַשְׁמִ֨יעַ אֵלַ֤יִ⁠ךְ עוֹד֙ כְּלִמַּ֣ת הַ⁠גּוֹיִ֔ם וְ⁠חֶרְפַּ֥ת עַמִּ֖ים לֹ֣א תִשְׂאִי־ע֑וֹד ו⁠גוי⁠ך לֹא־תַכְשִׁ֣לִי ע֔וֹד נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","wĕ⁠lòʼ-ʼaşĕ̌mi֨yʻa ʼéla֤yi⁠kĕ ʻwòd֙ kĕ̇limȧ֣ţ ha⁠ġwòyi֔m wĕ⁠ẖerĕpȧ֥ţ ʻami֖̇ym lò֣ʼ ţişĕ̂ʼiy-ʻ֑wòd w⁠gwy⁠k lòʼ-ţakĕşǐ֣liy ʻ֔wòd nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[36,16,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[36,17,"בֶּן־אָדָ֗ם בֵּ֤ית יִשְׂרָאֵל֙ יֹשְׁבִ֣ים עַל־אַדְמָתָ֔⁠ם וַ⁠יְטַמְּא֣וּ אוֹתָ֔⁠הּ בְּ⁠דַרְכָּ֖⁠ם וּ⁠בַ⁠עֲלִֽילוֹתָ֑⁠ם כְּ⁠טֻמְאַת֙ הַ⁠נִּדָּ֔ה הָיְתָ֥ה דַרְכָּ֖⁠ם לְ⁠פָנָֽ⁠י׃","bėn-ʼádá֗m bé֤̇yţ yişĕ̂ráʼél֙ yòşĕ̌bi֣ym ʻal-ʼadĕmáţá֔⁠m wa⁠yĕtamĕ̇ʼ֣ẇ ʼwòţá֔⁠ḣ bĕ̇⁠darĕká֖̇⁠m ẇ⁠ba⁠ʻàliֽylwòţá֑⁠m kĕ̇⁠tumĕʼaţ֙ ha⁠ni̇dá̇֔h háyĕţá֥h darĕká֖̇⁠m lĕ⁠pánáֽ⁠y׃"],[36,18,"וָ⁠אֶשְׁפֹּ֤ךְ חֲמָתִ⁠י֙ עֲלֵי⁠הֶ֔ם עַל־הַ⁠דָּ֖ם אֲשֶׁר־שָׁפְכ֣וּ עַל־הָ⁠אָ֑רֶץ וּ⁠בְ⁠גִלּוּלֵי⁠הֶ֖ם טִמְּאֽוּ⁠הָ׃","wá⁠ʼeşĕ̌pò֤̇kĕ ẖàmáţi⁠y֙ ʻàléy⁠he֔m ʻal-ha⁠dá֖̇m ʼàşěr-şá̌pĕk֣ẇ ʻal-há⁠ʼá֑reẕ ẇ⁠bĕ⁠gil̇ẇléy⁠he֖m timĕ̇ʼֽẇ⁠há׃"],[36,19,"וָ⁠אָפִ֤יץ אֹתָ⁠ם֙ בַּ⁠גּוֹיִ֔ם וַ⁠יִּזָּר֖וּ בָּ⁠אֲרָצ֑וֹת כְּ⁠דַרְכָּ֥⁠ם וְ⁠כַ⁠עֲלִילוֹתָ֖⁠ם שְׁפַטְתִּֽי⁠ם׃","wá⁠ʼápi֤yẕ ʼòţá⁠m֙ bȧ⁠ġwòyi֔m wa⁠yi̇zá̇r֖ẇ bá̇⁠ʼàráẕ֑wòţ kĕ̇⁠darĕká֥̇⁠m wĕ⁠ka⁠ʻàliylwòţá֖⁠m şĕ̌patĕţiֽ̇y⁠m׃"],[36,20,"וַ⁠יָּב֗וֹא אֶל־הַ⁠גּוֹיִם֙ אֲשֶׁר־בָּ֣אוּ שָׁ֔ם וַֽ⁠יְחַלְּל֖וּ אֶת־שֵׁ֣ם קָדְשִׁ֑⁠י בֶּ⁠אֱמֹ֤ר לָ⁠הֶם֙ עַם־יְהוָ֣ה אֵ֔לֶּה וּ⁠מֵ⁠אַרְצ֖⁠וֹ יָצָֽאוּ׃","wa⁠yá̇b֗wòʼ ʼel-ha⁠ġwòyim֙ ʼàşěr-bá֣̇ʼẇ şá̌֔m waֽ⁠yĕẖalĕ̇l֖ẇ ʼeţ-şé֣̌m qádĕşǐ֑⁠y bė⁠ʼèmò֤r lá⁠hem֙ ʻam-yĕhwá֣h ʼé֔lėh ẇ⁠mé⁠ʼarĕẕ֖⁠wò yáẕáֽʼẇ׃"],[36,21,"וָ⁠אֶחְמֹ֖ל עַל־שֵׁ֣ם קָדְשִׁ֑⁠י אֲשֶׁ֤ר חִלְּל֨וּ⁠הוּ֙ בֵּ֣ית יִשְׂרָאֵ֔ל בַּ⁠גּוֹיִ֖ם אֲשֶׁר־בָּ֥אוּ שָֽׁמָּ⁠ה׃ס","wá⁠ʼeẖĕmò֖l ʻal-şé֣̌m qádĕşǐ֑⁠y ʼàşě֤r ẖilĕ̇l֨ẇ⁠hẇ֙ bé֣̇yţ yişĕ̂ráʼé֔l bȧ⁠ġwòyi֖m ʼàşěr-bá֥̇ʼẇ şáֽ̌má̇⁠h׃s"],[36,22,"לָ⁠כֵ֞ן אֱמֹ֣ר לְ⁠בֵֽית־יִשְׂרָאֵ֗ל כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה לֹ֧א לְמַעַנְ⁠כֶ֛ם אֲנִ֥י עֹשֶׂ֖ה בֵּ֣ית יִשְׂרָאֵ֑ל כִּ֤י אִם־לְ⁠שֵׁם־קָדְשִׁ⁠י֙ אֲשֶׁ֣ר חִלַּלְתֶּ֔ם בַּ⁠גּוֹיִ֖ם אֲשֶׁר־בָּ֥אתֶם שָֽׁם׃","lá⁠ké֞n ʼèmò֣r lĕ⁠béֽyţ-yişĕ̂ráʼé֗l kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h lò֧ʼ lĕmaʻanĕ⁠ke֛m ʼàni֥y ʻòşê֖h bé֣̇yţ yişĕ̂ráʼé֑l ki֤̇y ʼim-lĕ⁠şé̌m-qádĕşǐ⁠y֙ ʼàşě֣r ẖilȧlĕţė֔m bȧ⁠ġwòyi֖m ʼàşěr-bá֥̇ʼţem şáֽ̌m׃"],[36,23,"וְ⁠קִדַּשְׁתִּ֞י אֶת־שְׁמִ֣⁠י הַ⁠גָּד֗וֹל הַֽ⁠מְחֻלָּל֙ בַּ⁠גּוֹיִ֔ם אֲשֶׁ֥ר חִלַּלְתֶּ֖ם בְּ⁠תוֹכָ֑⁠ם וְ⁠יָדְע֨וּ הַ⁠גּוֹיִ֜ם כִּי־אֲנִ֣י יְהוָ֗ה נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה בְּ⁠הִקָּדְשִׁ֥⁠י בָ⁠כֶ֖ם לְ⁠עֵינֵי⁠הֶֽם׃","wĕ⁠qidȧşĕ̌ţi̇֞y ʼeţ-şĕ̌mi֣⁠y ha⁠gá̇d֗wòl haֽ⁠mĕẖulá̇l֙ bȧ⁠ġwòyi֔m ʼàşě֥r ẖilȧlĕţė֖m bĕ̇⁠ţwòká֑⁠m wĕ⁠yádĕʻ֨ẇ ha⁠ġwòyi֜m ki̇y-ʼàni֣y yĕhwá֗h nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h bĕ̇⁠hiqá̇dĕşǐ֥⁠y bá⁠ke֖m lĕ⁠ʻéynéy⁠heֽm׃"],[36,24,"וְ⁠לָקַחְתִּ֤י אֶתְ⁠כֶם֙ מִן־הַ⁠גּוֹיִ֔ם וְ⁠קִבַּצְתִּ֥י אֶתְ⁠כֶ֖ם מִ⁠כָּל־הָ⁠אֲרָצ֑וֹת וְ⁠הֵבֵאתִ֥י אֶתְ⁠כֶ֖ם אֶל־אַדְמַתְ⁠כֶֽם׃","wĕ⁠láqaẖĕţi֤̇y ʼeţĕ⁠kem֙ min-ha⁠ġwòyi֔m wĕ⁠qibȧẕĕţi֥̇y ʼeţĕ⁠ke֖m mi⁠ká̇l-há⁠ʼàráẕ֑wòţ wĕ⁠hébéʼţi֥y ʼeţĕ⁠ke֖m ʼel-ʼadĕmaţĕ⁠keֽm׃"],[36,25,"וְ⁠זָרַקְתִּ֧י עֲלֵי⁠כֶ֛ם מַ֥יִם טְהוֹרִ֖ים וּ⁠טְהַרְתֶּ֑ם מִ⁠כֹּ֧ל טֻמְאוֹתֵי⁠כֶ֛ם וּ⁠מִ⁠כָּל־גִּלּ֥וּלֵי⁠כֶ֖ם אֲטַהֵ֥ר אֶתְ⁠כֶֽם׃","wĕ⁠záraqĕţi֧̇y ʻàléy⁠ke֛m ma֥yim tĕhwòri֖ym ẇ⁠tĕharĕţė֑m mi⁠kò֧̇l tumĕʼwòţéy⁠ke֛m ẇ⁠mi⁠ká̇l-gi̇l֥̇ẇléy⁠ke֖m ʼàtahé֥r ʼeţĕ⁠keֽm׃"],[36,26,"וְ⁠נָתַתִּ֤י לָ⁠כֶם֙ לֵ֣ב חָדָ֔שׁ וְ⁠ר֥וּחַ חֲדָשָׁ֖ה אֶתֵּ֣ן בְּ⁠קִרְבְּ⁠כֶ֑ם וַ⁠הֲסִ֨רֹתִ֜י אֶת־לֵ֤ב הָ⁠אֶ֨בֶן֙ מִ⁠בְּשַׂרְ⁠כֶ֔ם וְ⁠נָתַתִּ֥י לָ⁠כֶ֖ם לֵ֥ב בָּשָֽׂר׃","wĕ⁠náţaţi֤̇y lá⁠kem֙ lé֣b ẖádá֔ş̌ wĕ⁠r֥ẇẖa ẖàdáşá֖̌h ʼeţé֣̇n bĕ̇⁠qirĕbĕ̇⁠ke֑m wa⁠hàsi֨ròţi֜y ʼeţ-lé֤b há⁠ʼe֨ben֙ mi⁠bĕ̇şârĕ⁠ke֔m wĕ⁠náţaţi֥̇y lá⁠ke֖m lé֥b bá̇şáֽ̂r׃"],[36,27,"וְ⁠אֶת־רוּחִ֖⁠י אֶתֵּ֣ן בְּ⁠קִרְבְּ⁠כֶ֑ם וְ⁠עָשִׂ֗יתִי אֵ֤ת אֲשֶׁר־בְּ⁠חֻקַּ⁠י֙ תֵּלֵ֔כוּ וּ⁠מִשְׁפָּטַ֥⁠י תִּשְׁמְר֖וּ וַ⁠עֲשִׂיתֶֽם׃","wĕ⁠ʼeţ-rẇẖi֖⁠y ʼeţé֣̇n bĕ̇⁠qirĕbĕ̇⁠ke֑m wĕ⁠ʻáşî֗yţiy ʼé֤ţ ʼàşěr-bĕ̇⁠ẖuqȧ⁠y֙ ţé̇lé֔kẇ ẇ⁠mişĕ̌pá̇ta֥⁠y ţi̇şĕ̌mĕr֖ẇ wa⁠ʻàşîyţeֽm׃"],[36,28,"וִ⁠ישַׁבְתֶּ֣ם בָּ⁠אָ֔רֶץ אֲשֶׁ֥ר נָתַ֖תִּי לַ⁠אֲבֹֽתֵי⁠כֶ֑ם וִ⁠הְיִ֤יתֶם לִ⁠י֙ לְ⁠עָ֔ם וְ⁠אָ֣נֹכִ֔י אֶהְיֶ֥ה לָ⁠כֶ֖ם לֵ⁠אלֹהִֽים׃","wi⁠yşǎbĕţė֣m bá̇⁠ʼá֔reẕ ʼàşě֥r náţa֖ţi̇y la⁠ʼàbòֽţéy⁠ke֑m wi⁠hĕyi֤yţem li⁠y֙ lĕ⁠ʻá֔m wĕ⁠ʼá֣nòki֔y ʼehĕye֥h lá⁠ke֖m lé⁠ʼlòhiֽym׃"],[36,29,"וְ⁠הוֹשַׁעְתִּ֣י אֶתְ⁠כֶ֔ם מִ⁠כֹּ֖ל טֻמְאֽוֹתֵי⁠כֶ֑ם וְ⁠קָרָ֤אתִי אֶל־הַ⁠דָּגָן֙ וְ⁠הִרְבֵּיתִ֣י אֹת֔⁠וֹ וְ⁠לֹא־אֶתֵּ֥ן עֲלֵי⁠כֶ֖ם רָעָֽב׃","wĕ⁠hwòşǎʻĕţi֣̇y ʼeţĕ⁠ke֔m mi⁠kò֖̇l tumĕʼֽwòţéy⁠ke֑m wĕ⁠qárá֤ʼţiy ʼel-ha⁠dá̇gán֙ wĕ⁠hirĕbé̇yţi֣y ʼòţ֔⁠wò wĕ⁠lòʼ-ʼeţé֥̇n ʻàléy⁠ke֖m ráʻáֽb׃"],[36,30,"וְ⁠הִרְבֵּיתִי֙ אֶת־פְּרִ֣י הָ⁠עֵ֔ץ וּ⁠תְנוּבַ֖ת הַ⁠שָּׂדֶ֑ה לְמַ֗עַן אֲ֠שֶׁר לֹ֣א תִקְח֥וּ ע֛וֹד חֶרְפַּ֥ת רָעָ֖ב בַּ⁠גּוֹיִֽם׃","wĕ⁠hirĕbé̇yţiy֙ ʼeţ-pĕ̇ri֣y há⁠ʻé֔ẕ ẇ⁠ţĕnẇba֖ţ ha⁠şá̇̂de֑h lĕma֗ʻan ʼà֠şěr lò֣ʼ ţiqĕẖ֥ẇ ʻ֛wòd ẖerĕpȧ֥ţ ráʻá֖b bȧ⁠ġwòyiֽm׃"],[36,31,"וּ⁠זְכַרְתֶּם֙ אֶת־דַּרְכֵי⁠כֶ֣ם הָ⁠רָעִ֔ים וּ⁠מַעַלְלֵי⁠כֶ֖ם אֲשֶׁ֣ר לֹֽא־טוֹבִ֑ים וּ⁠נְקֹֽטֹתֶם֙ בִּ⁠פְנֵי⁠כֶ֔ם עַ֚ל עֲוֺנֹ֣תֵי⁠כֶ֔ם וְ⁠עַ֖ל תּוֹעֲבֽוֹתֵי⁠כֶֽם׃","ẇ⁠zĕkarĕţėm֙ ʼeţ-dȧrĕkéy⁠ke֣m há⁠ráʻi֔ym ẇ⁠maʻalĕléy⁠ke֖m ʼàşě֣r lòֽʼ-twòbi֑ym ẇ⁠nĕqòֽtòţem֙ bi̇⁠pĕnéy⁠ke֔m ʻa֚l ʻàwֺnò֣ţéy⁠ke֔m wĕ⁠ʻa֖l ţ̇wòʻàbֽwòţéy⁠keֽm׃"],[36,32,"לֹ֧א לְמַעַנְ⁠כֶ֣ם אֲנִֽי־עֹשֶׂ֗ה נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה יִוָּדַ֖ע לָ⁠כֶ֑ם בּ֧וֹשׁוּ וְ⁠הִכָּלְמ֛וּ מִ⁠דַּרְכֵי⁠כֶ֖ם בֵּ֥ית יִשְׂרָאֵֽל׃ס","lò֧ʼ lĕmaʻanĕ⁠ke֣m ʼàniֽy-ʻòşê֗h nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h yiwá̇da֖ʻ lá⁠ke֑m ḃ֧wòş̌ẇ wĕ⁠hiká̇lĕm֛ẇ mi⁠dȧrĕkéy⁠ke֖m bé֥̇yţ yişĕ̂ráʼéֽl׃s"],[36,33,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה בְּ⁠יוֹם֙ טַהֲרִ֣⁠י אֶתְ⁠כֶ֔ם מִ⁠כֹּ֖ל עֲוֺנֽוֹתֵי⁠כֶ֑ם וְ⁠הֽוֹשַׁבְתִּי֙ אֶת־הֶ֣⁠עָרִ֔ים וְ⁠נִבְנ֖וּ הֶ⁠חֳרָבֽוֹת׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h bĕ̇⁠ywòm֙ tahàri֣⁠y ʼeţĕ⁠ke֔m mi⁠kò֖̇l ʻàwֺnֽwòţéy⁠ke֑m wĕ⁠hֽwòşǎbĕţi̇y֙ ʼeţ-he֣⁠ʻári֔ym wĕ⁠nibĕn֖ẇ he⁠ẖorábֽwòţ׃"],[36,34,"וְ⁠הָ⁠אָ֥רֶץ הַ⁠נְּשַׁמָּ֖ה תֵּֽעָבֵ֑ד תַּ֚חַת אֲשֶׁ֣ר הָיְתָ֣ה שְׁמָמָ֔ה לְ⁠עֵינֵ֖י כָּל־עוֹבֵֽר׃","wĕ⁠há⁠ʼá֥reẕ ha⁠nĕ̇şǎmá֖̇h ţéֽ̇ʻábé֑d ţȧ֚ẖaţ ʼàşě֣r háyĕţá֣h şĕ̌mámá֔h lĕ⁠ʻéyné֖y ká̇l-ʻwòbéֽr׃"],[36,35,"וְ⁠אָמְר֗וּ הָ⁠אָ֤רֶץ הַלֵּ֨זוּ֙ הַ⁠נְּשַׁמָּ֔ה הָיְתָ֖ה כְּ⁠גַן־עֵ֑דֶן וְ⁠הֶ⁠עָרִ֧ים הֶ⁠חֳרֵב֛וֹת וְ⁠הַֽ⁠נְשַׁמּ֥וֹת וְ⁠הַ⁠נֶּהֱרָס֖וֹת בְּצוּר֥וֹת יָשָֽׁבוּ׃","wĕ⁠ʼámĕr֗ẇ há⁠ʼá֤reẕ halé̇֨zẇ֙ ha⁠nĕ̇şǎmá̇֔h háyĕţá֖h kĕ̇⁠gan-ʻé֑den wĕ⁠he⁠ʻári֧ym he⁠ẖoréb֛wòţ wĕ⁠haֽ⁠nĕşǎṁ֥wòţ wĕ⁠ha⁠nėhèrás֖wòţ bĕ̇ẕẇr֥wòţ yáşáֽ̌bẇ׃"],[36,36,"וְ⁠יָדְע֣וּ הַ⁠גּוֹיִ֗ם אֲשֶׁ֣ר יִֽשָּׁאֲרוּ֮ סְבִיבוֹתֵי⁠כֶם֒ כִּ֣י ׀ אֲנִ֣י יְהוָ֗ה בָּנִ֨יתִי֙ הַ⁠נֶּ֣הֱרָס֔וֹת נָטַ֖עְתִּי הַ⁠נְּשַׁמָּ֑ה אֲנִ֥י יְהוָ֖ה דִּבַּ֥רְתִּי וְ⁠עָשִֽׂיתִי׃ס","wĕ⁠yádĕʻ֣ẇ ha⁠ġwòyi֗m ʼàşě֣r yiֽşá̇̌ʼàrẇ֮ sĕbiybwòţéy⁠kem֒ ki֣̇y ׀ ʼàni֣y yĕhwá֗h bá̇ni֨yţiy֙ ha⁠nė֣hèrás֔wòţ náta֖ʻĕţi̇y ha⁠nĕ̇şǎmá֑̇h ʼàni֥y yĕhwá֖h di̇bȧ֥rĕţi̇y wĕ⁠ʻáşîֽyţiy׃s"],[36,37,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה ע֗וֹד זֹ֛את אִדָּרֵ֥שׁ לְ⁠בֵֽית־יִשְׂרָאֵ֖ל לַ⁠עֲשׂ֣וֹת לָ⁠הֶ֑ם אַרְבֶּ֥ה אֹתָ֛⁠ם כַּ⁠צֹּ֖אן אָדָֽם׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ʻ֗wòd zò֛ʼţ ʼidá̇ré֥ş̌ lĕ⁠béֽyţ-yişĕ̂ráʼé֖l la⁠ʻàş֣̂wòţ lá⁠he֑m ʼarĕbė֥h ʼòţá֛⁠m kȧ⁠ẕò֖̇ʼn ʼádáֽm׃"],[36,38,"כְּ⁠צֹ֣אן קָֽדָשִׁ֗ים כְּ⁠צֹ֤אן יְרוּשָׁלִַ֨ם֙ בְּ⁠מ֣וֹעֲדֶ֔י⁠הָ כֵּ֤ן תִּהְיֶ֨ינָה֙ הֶ⁠עָרִ֣ים הֶ⁠חֳרֵב֔וֹת מְלֵא֖וֹת צֹ֣אן אָדָ֑ם וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃ס","kĕ̇⁠ẕò֣ʼn qáֽdáşǐ֗ym kĕ̇⁠ẕò֤ʼn yĕrẇşá̌lia֨m֙ bĕ̇⁠m֣wòʻàde֔y⁠há ké֤̇n ţi̇hĕye֨ynáh֙ he⁠ʻári֣ym he⁠ẖoréb֔wòţ mĕléʼ֖wòţ ẕò֣ʼn ʼádá֑m wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃s"],[37,1,"הָיְתָ֣ה עָלַ⁠י֮ יַד־יְהוָה֒ וַ⁠יּוֹצִאֵ֤⁠נִי בְ⁠ר֨וּחַ֙ יְהוָ֔ה וַ⁠יְנִיחֵ֖⁠נִי בְּ⁠ת֣וֹךְ הַ⁠בִּקְעָ֑ה וְ⁠הִ֖יא מְלֵאָ֥ה עֲצָמֽוֹת׃","háyĕţá֣h ʻála⁠y֮ yad-yĕhwáh֒ wa⁠ẏwòẕiʼé֤⁠niy bĕ⁠r֨ẇẖa֙ yĕhwá֔h wa⁠yĕniyẖé֖⁠niy bĕ̇⁠ţ֣wòkĕ ha⁠bi̇qĕʻá֑h wĕ⁠hi֖yʼ mĕléʼá֥h ʻàẕámֽwòţ׃"],[37,2,"וְ⁠הֶעֱבִירַ֥⁠נִי עֲלֵי⁠הֶ֖ם סָבִ֣יב ׀ סָבִ֑יב וְ⁠הִנֵּ֨ה רַבּ֤וֹת מְאֹד֙ עַל־פְּנֵ֣י הַ⁠בִּקְעָ֔ה וְ⁠הִנֵּ֖ה יְבֵשׁ֥וֹת מְאֹֽד׃","wĕ⁠heʻèbiyra֥⁠niy ʻàléy⁠he֖m sábi֣yb ׀ sábi֑yb wĕ⁠hiné̇֨h raḃ֤wòţ mĕʼòd֙ ʻal-pĕ̇né֣y ha⁠bi̇qĕʻá֔h wĕ⁠hiné֖̇h yĕbéş֥̌wòţ mĕʼòֽd׃"],[37,3,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י בֶּן־אָדָ֕ם הֲ⁠תִחְיֶ֖ינָה הָ⁠עֲצָמ֣וֹת הָ⁠אֵ֑לֶּה וָ⁠אֹמַ֕ר אֲדֹנָ֥⁠י יְהוִ֖ה אַתָּ֥ה יָדָֽעְתָּ׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y bėn-ʼádá֕m hà⁠ţiẖĕye֖ynáh há⁠ʻàẕám֣wòţ há⁠ʼé֑lėh wá⁠ʼòma֕r ʼàdòná֥⁠y yĕhwi֖h ʼaţá֥̇h yádáֽʻĕţá̇׃"],[37,4,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י הִנָּבֵ֖א עַל־הָ⁠עֲצָמ֣וֹת הָ⁠אֵ֑לֶּה וְ⁠אָמַרְתָּ֣ אֲלֵי⁠הֶ֔ם הָ⁠עֲצָמוֹת֙ הַ⁠יְבֵשׁ֔וֹת שִׁמְע֖וּ דְּבַר־יְהוָֽה׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y hiná̇bé֖ʼ ʻal-há⁠ʻàẕám֣wòţ há⁠ʼé֑lėh wĕ⁠ʼámarĕţá֣̇ ʼàléy⁠he֔m há⁠ʻàẕámwòţ֙ ha⁠yĕbéş̌֔wòţ şǐmĕʻ֖ẇ dĕ̇bar-yĕhwáֽh׃"],[37,5,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה לָ⁠עֲצָמ֖וֹת הָ⁠אֵ֑לֶּה הִנֵּ֨ה אֲנִ֜י מֵבִ֥יא בָ⁠כֶ֛ם ר֖וּחַ וִ⁠חְיִיתֶֽם׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h lá⁠ʻàẕám֖wòţ há⁠ʼé֑lėh hiné̇֨h ʼàni֜y mébi֥yʼ bá⁠ke֛m r֖ẇẖa wi⁠ẖĕyiyţeֽm׃"],[37,6,"וְ⁠נָתַתִּי֩ עֲלֵי⁠כֶ֨ם גִּדִ֜ים וְֽ⁠הַעֲלֵתִ֧י עֲלֵי⁠כֶ֣ם בָּשָׂ֗ר וְ⁠קָרַמְתִּ֤י עֲלֵי⁠כֶם֙ ע֔וֹר וְ⁠נָתַתִּ֥י בָ⁠כֶ֛ם ר֖וּחַ וִ⁠חְיִיתֶ֑ם וִ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֥י יְהוָֽה׃","wĕ⁠náţaţi̇y֩ ʻàléy⁠ke֨m gi̇di֜ym wĕֽ⁠haʻàléţi֧y ʻàléy⁠ke֣m bá̇şá̂֗r wĕ⁠qáramĕţi֤̇y ʻàléy⁠kem֙ ʻ֔wòr wĕ⁠náţaţi֥̇y bá⁠ke֛m r֖ẇẖa wi⁠ẖĕyiyţe֑m wi⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֥y yĕhwáֽh׃"],[37,7,"וְ⁠נִבֵּ֖אתִי כַּ⁠אֲשֶׁ֣ר צֻוֵּ֑יתִי וַֽ⁠יְהִי־ק֤וֹל כְּ⁠הִנָּֽבְאִ⁠י֙ וְ⁠הִנֵּה־רַ֔עַשׁ וַ⁠תִּקְרְב֣וּ עֲצָמ֔וֹת עֶ֖צֶם אֶל־עַצְמֽ⁠וֹ׃","wĕ⁠nibé֖̇ʼţiy kȧ⁠ʼàşě֣r ẕuwé֑̇yţiy waֽ⁠yĕhiy-q֤wòl kĕ̇⁠hináֽ̇bĕʼi⁠y֙ wĕ⁠hiné̇h-ra֔ʻaş̌ wa⁠ţi̇qĕrĕb֣ẇ ʻàẕám֔wòţ ʻe֖ẕem ʼel-ʻaẕĕmֽ⁠wò׃"],[37,8,"וְ⁠רָאִ֜יתִי וְ⁠הִנֵּֽה־עֲלֵי⁠הֶ֤ם גִּדִים֙ וּ⁠בָשָׂ֣ר עָלָ֔ה וַ⁠יִּקְרַ֧ם עֲלֵי⁠הֶ֛ם ע֖וֹר מִ⁠לְ⁠מָ֑עְלָ⁠ה וְ⁠ר֖וּחַ אֵ֥ין בָּ⁠הֶֽם׃","wĕ⁠ráʼi֜yţiy wĕ⁠hinéֽ̇h-ʻàléy⁠he֤m gi̇diym֙ ẇ⁠báşá֣̂r ʻálá֔h wa⁠yi̇qĕra֧m ʻàléy⁠he֛m ʻ֖wòr mi⁠lĕ⁠má֑ʻĕlá⁠h wĕ⁠r֖ẇẖa ʼé֥yn bá̇⁠heֽm׃"],[37,9,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י הִנָּבֵ֖א אֶל־הָ⁠ר֑וּחַ הִנָּבֵ֣א בֶן־אָ֠דָם וְ⁠אָמַרְתָּ֨ אֶל־הָ⁠ר֜וּחַ כֹּֽה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהוִ֗ה מֵ⁠אַרְבַּ֤ע רוּחוֹת֙ בֹּ֣אִי הָ⁠ר֔וּחַ וּ⁠פְחִ֛י בַּ⁠הֲרוּגִ֥ים הָ⁠אֵ֖לֶּה וְ⁠יִֽחְיֽוּ׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y hiná̇bé֖ʼ ʼel-há⁠r֑ẇẖa hiná̇bé֣ʼ ben-ʼá֠dám wĕ⁠ʼámarĕţá̇֨ ʼel-há⁠r֜ẇẖa kòֽ̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhwi֗h mé⁠ʼarĕbȧ֤ʻ rẇẖwòţ֙ bò֣̇ʼiy há⁠r֔ẇẖa ẇ⁠pĕẖi֛y bȧ⁠hàrẇgi֥ym há⁠ʼé֖lėh wĕ⁠yiֽẖĕyֽẇ׃"],[37,10,"וְ⁠הִנַּבֵּ֖אתִי כַּ⁠אֲשֶׁ֣ר צִוָּ֑⁠נִי וַ⁠תָּבוֹא֩ בָ⁠הֶ֨ם הָ⁠ר֜וּחַ וַ⁠יִּֽחְי֗וּ וַ⁠יַּֽעַמְדוּ֙ עַל־רַגְלֵי⁠הֶ֔ם חַ֖יִל גָּד֥וֹל מְאֹד־מְאֹֽד׃ס","wĕ⁠hinȧbé֖̇ʼţiy kȧ⁠ʼàşě֣r ẕiwá֑̇⁠niy wa⁠ţá̇bwòʼ֩ bá⁠he֨m há⁠r֜ẇẖa wa⁠yiֽ̇ẖĕy֗ẇ wa⁠yȧֽʻamĕdẇ֙ ʻal-ragĕléy⁠he֔m ẖa֖yil gá̇d֥wòl mĕʼòd-mĕʼòֽd׃s"],[37,11,"וַ⁠יֹּאמֶר֮ אֵלַ⁠י֒ בֶּן־אָדָ֕ם הָ⁠עֲצָמ֣וֹת הָ⁠אֵ֔לֶּה כָּל־בֵּ֥ית יִשְׂרָאֵ֖ל הֵ֑מָּה הִנֵּ֣ה אֹמְרִ֗ים יָבְשׁ֧וּ עַצְמוֹתֵ֛י⁠נוּ וְ⁠אָבְדָ֥ה תִקְוָתֵ֖⁠נוּ נִגְזַ֥רְנוּ לָֽ⁠נוּ׃","wa⁠yò̇ʼmer֮ ʼéla⁠y֒ bėn-ʼádá֕m há⁠ʻàẕám֣wòţ há⁠ʼé֔lėh ká̇l-bé֥̇yţ yişĕ̂ráʼé֖l hé֑má̇h hiné֣̇h ʼòmĕri֗ym yábĕş֧̌ẇ ʻaẕĕmwòţé֛y⁠nẇ wĕ⁠ʼábĕdá֥h ţiqĕwáţé֖⁠nẇ nigĕza֥rĕnẇ láֽ⁠nẇ׃"],[37,12,"לָ⁠כֵן֩ הִנָּבֵ֨א וְ⁠אָמַרְתָּ֜ אֲלֵי⁠הֶ֗ם כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ הִנֵּה֩ אֲנִ֨י פֹתֵ֜חַ אֶת־קִבְרֽוֹתֵי⁠כֶ֗ם וְ⁠הַעֲלֵיתִ֥י אֶתְ⁠כֶ֛ם מִ⁠קִּבְרוֹתֵי⁠כֶ֖ם עַמִּ֑⁠י וְ⁠הֵבֵאתִ֥י אֶתְ⁠כֶ֖ם אֶל־אַדְמַ֥ת יִשְׂרָאֵֽל׃ס","lá⁠kén֩ hiná̇bé֨ʼ wĕ⁠ʼámarĕţá̇֜ ʼàléy⁠he֗m kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ hiné̇h֩ ʼàni֨y pòţé֜ẖa ʼeţ-qibĕrֽwòţéy⁠ke֗m wĕ⁠haʻàléyţi֥y ʼeţĕ⁠ke֛m mi⁠qi̇bĕrwòţéy⁠ke֖m ʻami֑̇⁠y wĕ⁠hébéʼţi֥y ʼeţĕ⁠ke֖m ʼel-ʼadĕma֥ţ yişĕ̂ráʼéֽl׃s"],[37,13,"וִֽ⁠ידַעְתֶּ֖ם כִּֽי־אֲנִ֣י יְהוָ֑ה בְּ⁠פִתְחִ֣⁠י אֶת־קִבְרֽוֹתֵי⁠כֶ֗ם וּ⁠בְ⁠הַעֲלוֹתִ֥⁠י אֶתְ⁠כֶ֛ם מִ⁠קִּבְרוֹתֵי⁠כֶ֖ם עַמִּֽ⁠י׃","wiֽ⁠ydaʻĕţė֖m kiֽ̇y-ʼàni֣y yĕhwá֑h bĕ̇⁠piţĕẖi֣⁠y ʼeţ-qibĕrֽwòţéy⁠ke֗m ẇ⁠bĕ⁠haʻàlwòţi֥⁠y ʼeţĕ⁠ke֛m mi⁠qi̇bĕrwòţéy⁠ke֖m ʻamiֽ̇⁠y׃"],[37,14,"וְ⁠נָתַתִּ֨י רוּחִ֤⁠י בָ⁠כֶם֙ וִ⁠חְיִיתֶ֔ם וְ⁠הִנַּחְתִּ֥י אֶתְ⁠כֶ֖ם עַל־אַדְמַתְ⁠כֶ֑ם וִ⁠ידַעְתֶּ֞ם כִּי־אֲנִ֧י יְהוָ֛ה דִּבַּ֥רְתִּי וְ⁠עָשִׂ֖יתִי נְאֻם־יְהוָֽה׃פ","wĕ⁠náţaţi̇֨y rẇẖi֤⁠y bá⁠kem֙ wi⁠ẖĕyiyţe֔m wĕ⁠hinȧẖĕţi֥̇y ʼeţĕ⁠ke֖m ʻal-ʼadĕmaţĕ⁠ke֑m wi⁠ydaʻĕţė֞m ki̇y-ʼàni֧y yĕhwá֛h di̇bȧ֥rĕţi̇y wĕ⁠ʻáşî֖yţiy nĕʼum-yĕhwáֽh׃p"],[37,15,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[37,16,"וְ⁠אַתָּ֣ה בֶן־אָדָ֗ם קַח־לְ⁠ךָ֙ עֵ֣ץ אֶחָ֔ד וּ⁠כְתֹ֤ב עָלָי⁠ו֙ לִֽ⁠יהוּדָ֔ה וְ⁠לִ⁠בְנֵ֥י יִשְׂרָאֵ֖ל חבר⁠ו וּ⁠לְקַח֙ עֵ֣ץ אֶחָ֔ד וּ⁠כְת֣וֹב עָלָ֗י⁠ו לְ⁠יוֹסֵף֙ עֵ֣ץ אֶפְרַ֔יִם וְ⁠כָל־בֵּ֥ית יִשְׂרָאֵ֖ל חבר⁠ו׃","wĕ⁠ʼaţá֣̇h ben-ʼádá֗m qaẖ-lĕ⁠ká֙ ʻé֣ẕ ʼeẖá֔d ẇ⁠kĕţò֤b ʻáláy⁠w֙ liֽ⁠yhẇdá֔h wĕ⁠li⁠bĕné֥y yişĕ̂ráʼé֖l ẖbr⁠w ẇ⁠lĕqaẖ֙ ʻé֣ẕ ʼeẖá֔d ẇ⁠kĕţ֣wòb ʻálá֗y⁠w lĕ⁠ywòsép֙ ʻé֣ẕ ʼepĕra֔yim wĕ⁠kál-bé֥̇yţ yişĕ̂ráʼé֖l ẖbr⁠w׃"],[37,17,"וְ⁠קָרַ֨ב אֹתָ֜⁠ם אֶחָ֧ד אֶל־אֶחָ֛ד לְ⁠ךָ֖ לְ⁠עֵ֣ץ אֶחָ֑ד וְ⁠הָי֥וּ לַ⁠אֲחָדִ֖ים בְּ⁠יָדֶֽ⁠ךָ׃","wĕ⁠qára֨b ʼòţá֜⁠m ʼeẖá֧d ʼel-ʼeẖá֛d lĕ⁠ká֖ lĕ⁠ʻé֣ẕ ʼeẖá֑d wĕ⁠háy֥ẇ la⁠ʼàẖádi֖ym bĕ̇⁠yádeֽ⁠ká׃"],[37,18,"וְ⁠כַֽ⁠אֲשֶׁר֙ יֹאמְר֣וּ אֵלֶ֔י⁠ךָ בְּנֵ֥י עַמְּ⁠ךָ֖ לֵ⁠אמֹ֑ר הֲ⁠לֽוֹא־תַגִּ֥יד לָ֖⁠נוּ מָה־אֵ֥לֶּה לָּֽ⁠ךְ׃","wĕ⁠kaֽ⁠ʼàşěr֙ yòʼmĕr֣ẇ ʼéle֔y⁠ká bĕ̇né֥y ʻamĕ̇⁠ká֖ lé⁠ʼmò֑r hà⁠lֽwòʼ-ţagi֥̇yd lá֖⁠nẇ máh-ʼé֥lėh láֽ̇⁠kĕ׃"],[37,19,"דַּבֵּ֣ר אֲלֵ⁠הֶ֗ם כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ הִנֵּה֩ אֲנִ֨י לֹקֵ֜חַ אֶת־עֵ֤ץ יוֹסֵף֙ אֲשֶׁ֣ר בְּ⁠יַד־אֶפְרַ֔יִם וְ⁠שִׁבְטֵ֥י יִשְׂרָאֵ֖ל חבר⁠ו וְ⁠נָתַתִּי֩ אוֹתָ֨⁠ם עָלָ֜י⁠ו אֶת־עֵ֣ץ יְהוּדָ֗ה וַֽ⁠עֲשִׂיתִ⁠ם֙ לְ⁠עֵ֣ץ אֶחָ֔ד וְ⁠הָי֥וּ אֶחָ֖ד בְּ⁠יָדִֽ⁠י׃","dȧbé֣̇r ʼàlé⁠he֗m kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ hiné̇h֩ ʼàni֨y lòqé֜ẖa ʼeţ-ʻé֤ẕ ywòsép֙ ʼàşě֣r bĕ̇⁠yad-ʼepĕra֔yim wĕ⁠şǐbĕté֥y yişĕ̂ráʼé֖l ẖbr⁠w wĕ⁠náţaţi̇y֩ ʼwòţá֨⁠m ʻálá֜y⁠w ʼeţ-ʻé֣ẕ yĕhẇdá֗h waֽ⁠ʻàşîyţi⁠m֙ lĕ⁠ʻé֣ẕ ʼeẖá֔d wĕ⁠háy֥ẇ ʼeẖá֖d bĕ̇⁠yádiֽ⁠y׃"],[37,20,"וְ⁠הָי֨וּ הָ⁠עֵצִ֜ים אֲֽשֶׁר־תִּכְתֹּ֧ב עֲלֵי⁠הֶ֛ם בְּ⁠יָדְ⁠ךָ֖ לְ⁠עֵינֵי⁠הֶֽם׃","wĕ⁠háy֨ẇ há⁠ʻéẕi֜ym ʼàֽşěr-ţi̇kĕţò֧̇b ʻàléy⁠he֛m bĕ̇⁠yádĕ⁠ká֖ lĕ⁠ʻéynéy⁠heֽm׃"],[37,21,"וְ⁠דַבֵּ֣ר אֲלֵי⁠הֶ֗ם כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ הִנֵּ֨ה אֲנִ֤י לֹקֵ֨חַ֙ אֶת־בְּנֵ֣י יִשְׂרָאֵ֔ל מִ⁠בֵּ֥ין הַ⁠גּוֹיִ֖ם אֲשֶׁ֣ר הָֽלְכוּ־שָׁ֑ם וְ⁠קִבַּצְתִּ֤י אֹתָ⁠ם֙ מִ⁠סָּבִ֔יב וְ⁠הֵבֵאתִ֥י אוֹתָ֖⁠ם אֶל־אַדְמָתָֽ⁠ם׃","wĕ⁠dabé֣̇r ʼàléy⁠he֗m kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ hiné̇֨h ʼàni֤y lòqé֨ẖa֙ ʼeţ-bĕ̇né֣y yişĕ̂ráʼé֔l mi⁠bé֥̇yn ha⁠ġwòyi֖m ʼàşě֣r háֽlĕkẇ-şá֑̌m wĕ⁠qibȧẕĕţi֤̇y ʼòţá⁠m֙ mi⁠sá̇bi֔yb wĕ⁠hébéʼţi֥y ʼwòţá֖⁠m ʼel-ʼadĕmáţáֽ⁠m׃"],[37,22,"וְ⁠עָשִׂ֣יתִי אֹ֠תָ⁠ם לְ⁠ג֨וֹי אֶחָ֤ד בָּ⁠אָ֨רֶץ֙ בְּ⁠הָרֵ֣י יִשְׂרָאֵ֔ל וּ⁠מֶ֧לֶךְ אֶחָ֛ד יִֽהְיֶ֥ה לְ⁠כֻלָּ֖⁠ם לְ⁠מֶ֑לֶךְ וְ⁠לֹ֤א יהיה־עוֹד֙ לִ⁠שְׁנֵ֣י גוֹיִ֔ם וְ⁠לֹ֨א יֵחָ֥צוּ ע֛וֹד לִ⁠שְׁתֵּ֥י מַמְלָכ֖וֹת עֽוֹד׃","wĕ⁠ʻáşî֣yţiy ʼò֠ţá⁠m lĕ⁠g֨wòy ʼeẖá֤d bá̇⁠ʼá֨reẕ֙ bĕ̇⁠háré֣y yişĕ̂ráʼé֔l ẇ⁠me֧lekĕ ʼeẖá֛d yiֽhĕye֥h lĕ⁠kulá֖̇⁠m lĕ⁠me֑lekĕ wĕ⁠lò֤ʼ yhyh-ʻwòd֙ li⁠şĕ̌né֣y gwòyi֔m wĕ⁠lò֨ʼ yéẖá֥ẕẇ ʻ֛wòd li⁠şĕ̌ţé֥̇y mamĕlák֖wòţ ʻֽwòd׃"],[37,23,"וְ⁠לֹ֧א יִֽטַמְּא֣וּ ע֗וֹד בְּ⁠גִלּֽוּלֵי⁠הֶם֙ וּ⁠בְ⁠שִׁקּ֣וּצֵי⁠הֶ֔ם וּ⁠בְ⁠כֹ֖ל פִּשְׁעֵי⁠הֶ֑ם וְ⁠הוֹשַׁעְתִּ֣י אֹתָ֗⁠ם מִ⁠כֹּ֤ל מוֹשְׁבֹֽתֵי⁠הֶם֙ אֲשֶׁ֣ר חָטְא֣וּ בָ⁠הֶ֔ם וְ⁠טִהַרְתִּ֤י אוֹתָ⁠ם֙ וְ⁠הָיוּ־לִ֣⁠י לְ⁠עָ֔ם וַ⁠אֲנִ֕י אֶהְיֶ֥ה לָ⁠הֶ֖ם לֵ⁠אלֹהִֽים׃","wĕ⁠lò֧ʼ yiֽtamĕ̇ʼ֣ẇ ʻ֗wòd bĕ̇⁠gilֽ̇ẇléy⁠hem֙ ẇ⁠bĕ⁠şǐq֣̇ẇẕéy⁠he֔m ẇ⁠bĕ⁠kò֖l pi̇şĕ̌ʻéy⁠he֑m wĕ⁠hwòşǎʻĕţi֣̇y ʼòţá֗⁠m mi⁠kò֤̇l mwòşĕ̌bòֽţéy⁠hem֙ ʼàşě֣r ẖátĕʼ֣ẇ bá⁠he֔m wĕ⁠tiharĕţi֤̇y ʼwòţá⁠m֙ wĕ⁠háyẇ-li֣⁠y lĕ⁠ʻá֔m wa⁠ʼàni֕y ʼehĕye֥h lá⁠he֖m lé⁠ʼlòhiֽym׃"],[37,24,"וְ⁠עַבְדִּ֤⁠י דָוִד֙ מֶ֣לֶךְ עֲלֵי⁠הֶ֔ם וְ⁠רוֹעֶ֥ה אֶחָ֖ד יִהְיֶ֣ה לְ⁠כֻלָּ֑⁠ם וּ⁠בְ⁠מִשְׁפָּטַ֣⁠י יֵלֵ֔כוּ וְ⁠חֻקֹּתַ֥⁠י יִשְׁמְר֖וּ וְ⁠עָשׂ֥וּ אוֹתָֽ⁠ם׃","wĕ⁠ʻabĕdi֤̇⁠y dáwid֙ me֣lekĕ ʻàléy⁠he֔m wĕ⁠rwòʻe֥h ʼeẖá֖d yihĕye֣h lĕ⁠kulá֑̇⁠m ẇ⁠bĕ⁠mişĕ̌pá̇ta֣⁠y yélé֔kẇ wĕ⁠ẖuqò̇ţa֥⁠y yişĕ̌mĕr֖ẇ wĕ⁠ʻáş֥̂ẇ ʼwòţáֽ⁠m׃"],[37,25,"וְ⁠יָשְׁב֣וּ עַל־הָ⁠אָ֗רֶץ אֲשֶׁ֤ר נָתַ֨תִּי֙ לְ⁠עַבְדִּ֣⁠י לְ⁠יַֽעֲקֹ֔ב אֲשֶׁ֥ר יָֽשְׁבוּ־בָ֖⁠הּ אֲבֽוֹתֵי⁠כֶ֑ם וְ⁠יָשְׁב֣וּ עָלֶ֡י⁠הָ הֵ֠מָּה וּ⁠בְנֵי⁠הֶ֞ם וּ⁠בְנֵ֤י בְנֵי⁠הֶם֙ עַד־עוֹלָ֔ם וְ⁠דָוִ֣ד עַבְדִּ֔⁠י נָשִׂ֥יא לָ⁠הֶ֖ם לְ⁠עוֹלָֽם׃","wĕ⁠yáşĕ̌b֣ẇ ʻal-há⁠ʼá֗reẕ ʼàşě֤r náţa֨ţi̇y֙ lĕ⁠ʻabĕdi֣̇⁠y lĕ⁠yaֽʻàqò֔b ʼàşě֥r yáֽşĕ̌bẇ-bá֖⁠ḣ ʼàbֽwòţéy⁠ke֑m wĕ⁠yáşĕ̌b֣ẇ ʻále֡y⁠há hé֠má̇h ẇ⁠bĕnéy⁠he֞m ẇ⁠bĕné֤y bĕnéy⁠hem֙ ʻad-ʻwòlá֔m wĕ⁠dáwi֣d ʻabĕdi̇֔⁠y náşî֥yʼ lá⁠he֖m lĕ⁠ʻwòláֽm׃"],[37,26,"וְ⁠כָרַתִּ֤י לָ⁠הֶם֙ בְּרִ֣ית שָׁל֔וֹם בְּרִ֥ית עוֹלָ֖ם יִהְיֶ֣ה אוֹתָ֑⁠ם וּ⁠נְתַתִּי⁠ם֙ וְ⁠הִרְבֵּיתִ֣י אוֹתָ֔⁠ם וְ⁠נָתַתִּ֧י אֶת־מִקְדָּשִׁ֛⁠י בְּ⁠תוֹכָ֖⁠ם לְ⁠עוֹלָֽם׃","wĕ⁠káraţi֤̇y lá⁠hem֙ bĕ̇ri֣yţ şá̌l֔wòm bĕ̇ri֥yţ ʻwòlá֖m yihĕye֣h ʼwòţá֑⁠m ẇ⁠nĕţaţi̇y⁠m֙ wĕ⁠hirĕbé̇yţi֣y ʼwòţá֔⁠m wĕ⁠náţaţi֧̇y ʼeţ-miqĕdá̇şǐ֛⁠y bĕ̇⁠ţwòká֖⁠m lĕ⁠ʻwòláֽm׃"],[37,27,"וְ⁠הָיָ֤ה מִשְׁכָּנִ⁠י֙ עֲלֵי⁠הֶ֔ם וְ⁠הָיִ֥יתִי לָ⁠הֶ֖ם לֵֽ⁠אלֹהִ֑ים וְ⁠הֵ֖מָּה יִֽהְיוּ־לִ֥⁠י לְ⁠עָֽם׃","wĕ⁠háyá֤h mişĕ̌ká̇ni⁠y֙ ʻàléy⁠he֔m wĕ⁠háyi֥yţiy lá⁠he֖m léֽ⁠ʼlòhi֑ym wĕ⁠hé֖má̇h yiֽhĕyẇ-li֥⁠y lĕ⁠ʻáֽm׃"],[37,28,"וְ⁠יָֽדְעוּ֙ הַ⁠גּוֹיִ֔ם כִּ֚י אֲנִ֣י יְהוָ֔ה מְקַדֵּ֖שׁ אֶת־יִשְׂרָאֵ֑ל בִּ⁠הְי֧וֹת מִקְדָּשִׁ֛⁠י בְּ⁠תוֹכָ֖⁠ם לְ⁠עוֹלָֽם׃ס","wĕ⁠yáֽdĕʻẇ֙ ha⁠ġwòyi֔m ki֚̇y ʼàni֣y yĕhwá֔h mĕqadé֖̇ş̌ ʼeţ-yişĕ̂ráʼé֑l bi̇⁠hĕy֧wòţ miqĕdá̇şǐ֛⁠y bĕ̇⁠ţwòká֖⁠m lĕ⁠ʻwòláֽm׃s"],[38,1,"וַ⁠יְהִ֥י דְבַר־יְהוָ֖ה אֵלַ֥⁠י לֵ⁠אמֹֽר׃","wa⁠yĕhi֥y dĕbar-yĕhwá֖h ʼéla֥⁠y lé⁠ʼmòֽr׃"],[38,2,"בֶּן־אָדָ֗ם שִׂ֤ים פָּנֶ֨י⁠ךָ֙ אֶל־גּוֹג֙ אֶ֣רֶץ הַ⁠מָּג֔וֹג נְשִׂ֕יא רֹ֖אשׁ מֶ֣שֶׁךְ וְ⁠תֻבָ֑ל וְ⁠הִנָּבֵ֖א עָלָֽי⁠ו׃","bėn-ʼádá֗m şî֤ym pá̇ne֨y⁠ká֙ ʼel-ġwòg֙ ʼe֣reẕ ha⁠má̇g֔wòg nĕşî֕yʼ rò֖ʼş̌ me֣şěkĕ wĕ⁠ţubá֑l wĕ⁠hiná̇bé֖ʼ ʻáláֽy⁠w׃"],[38,3,"וְ⁠אָ֣מַרְתָּ֔ כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה הִנְ⁠נִ֤י אֵלֶ֨י⁠ךָ֙ גּ֔וֹג נְשִׂ֕יא רֹ֖אשׁ מֶ֥שֶׁךְ וְ⁠תֻבָֽל׃","wĕ⁠ʼá֣marĕţá̇֔ kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h hinĕ⁠ni֤y ʼéle֨y⁠ká֙ ġ֔wòg nĕşî֕yʼ rò֖ʼş̌ me֥şěkĕ wĕ⁠ţubáֽl׃"],[38,4,"וְ⁠שׁ֣וֹבַבְתִּ֔י⁠ךָ וְ⁠נָתַתִּ֥י חַחִ֖ים בִּ⁠לְחָיֶ֑י⁠ךָ וְ⁠הוֹצֵאתִי֩ אוֹתְ⁠ךָ֨ וְ⁠אֶת־כָּל־חֵילֶ֜⁠ךָ סוּסִ֣ים וּ⁠פָרָשִׁ֗ים לְבֻשֵׁ֤י מִכְלוֹל֙ כֻּלָּ֔⁠ם קָהָ֥ל רָב֙ צִנָּ֣ה וּ⁠מָגֵ֔ן תֹּפְשֵׂ֥י חֲרָב֖וֹת כֻּלָּֽ⁠ם׃","wĕ⁠ş֣̌wòbabĕţi̇֔y⁠ká wĕ⁠náţaţi֥̇y ẖaẖi֖ym bi̇⁠lĕẖáye֑y⁠ká wĕ⁠hwòẕéʼţiy֩ ʼwòţĕ⁠ká֨ wĕ⁠ʼeţ-ká̇l-ẖéyle֜⁠ká sẇsi֣ym ẇ⁠páráşǐ֗ym lĕbuşé֤̌y mikĕlwòl֙ ku̇lá̇֔⁠m qáhá֥l ráb֙ ẕiná֣̇h ẇ⁠mágé֔n ţò̇pĕşé֥̂y ẖàráb֖wòţ ku̇láֽ̇⁠m׃"],[38,5,"פָּרַ֛ס כּ֥וּשׁ וּ⁠פ֖וּט אִתָּ֑⁠ם כֻּלָּ֖⁠ם מָגֵ֥ן וְ⁠כוֹבָֽע׃","pá̇ra֛s k֥̇ẇş̌ ẇ⁠p֖ẇt ʼiţá֑̇⁠m ku̇lá֖̇⁠m mágé֥n wĕ⁠kwòbáֽʻ׃"],[38,6,"גֹּ֚מֶר וְ⁠כָל־אֲגַפֶּ֔י⁠הָ בֵּ֚ית תּֽוֹגַרְמָ֔ה יַרְכְּתֵ֥י צָפ֖וֹן וְ⁠אֶת־כָּל־אֲגַפָּ֑י⁠ו עַמִּ֥ים רַבִּ֖ים אִתָּֽ⁠ךְ׃","gò֚̇mer wĕ⁠kál-ʼàgapė֔y⁠há bé֚̇yţ ţֽ̇wògarĕmá֔h yarĕkĕ̇ţé֥y ẕáp֖wòn wĕ⁠ʼeţ-ká̇l-ʼàgapá֑̇y⁠w ʻami֥̇ym rabi֖̇ym ʼiţáֽ̇⁠kĕ׃"],[38,7,"הִכֹּן֙ וְ⁠הָכֵ֣ן לְ⁠ךָ֔ אַתָּ֕ה וְ⁠כָל־קְהָלֶ֖⁠ךָ הַ⁠נִּקְהָלִ֣ים עָלֶ֑י⁠ךָ וְ⁠הָיִ֥יתָ לָ⁠הֶ֖ם לְ⁠מִשְׁמָֽר׃","hikò̇n֙ wĕ⁠háké֣n lĕ⁠ká֔ ʼaţá̇֕h wĕ⁠kál-qĕhále֖⁠ká ha⁠ni̇qĕháli֣ym ʻále֑y⁠ká wĕ⁠háyi֥yţá lá⁠he֖m lĕ⁠mişĕ̌máֽr׃"],[38,8,"מִ⁠יָּמִ֣ים רַבִּים֮ תִּפָּקֵד֒ בְּ⁠אַחֲרִ֨ית הַ⁠שָּׁנִ֜ים תָּב֣וֹא ׀ אֶל־אֶ֣רֶץ ׀ מְשׁוֹבֶ֣בֶת מֵ⁠חֶ֗רֶב מְקֻבֶּ֨צֶת֙ מֵ⁠עַמִּ֣ים רַבִּ֔ים עַ֚ל הָרֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁר־הָי֥וּ לְ⁠חָרְבָּ֖ה תָּמִ֑יד וְ⁠הִיא֙ מֵ⁠עַמִּ֣ים הוּצָ֔אָה וְ⁠יָשְׁב֥וּ לָ⁠בֶ֖טַח כֻּלָּֽ⁠ם׃","mi⁠yá̇mi֣ym rabi̇ym֮ ţi̇pá̇qéd֒ bĕ̇⁠ʼaẖàri֨yţ ha⁠şá̇̌ni֜ym ţá̇b֣wòʼ ׀ ʼel-ʼe֣reẕ ׀ mĕş̌wòbe֣beţ mé⁠ẖe֗reb mĕqubė֨ẕeţ֙ mé⁠ʻami֣̇ym rabi̇֔ym ʻa֚l háré֣y yişĕ̂ráʼé֔l ʼàşěr-háy֥ẇ lĕ⁠ẖárĕbá֖̇h ţá̇mi֑yd wĕ⁠hiyʼ֙ mé⁠ʻami֣̇ym hẇẕá֔ʼáh wĕ⁠yáşĕ̌b֥ẇ lá⁠be֖taẖ ku̇láֽ̇⁠m׃"],[38,9,"וְ⁠עָלִ֨יתָ֙ כַּ⁠שֹּׁאָ֣ה תָב֔וֹא כֶּ⁠עָנָ֛ן לְ⁠כַסּ֥וֹת הָ⁠אָ֖רֶץ תִּֽהְיֶ֑ה אַתָּה֙ וְ⁠כָל־אֲגַפֶּ֔י⁠ךָ וְ⁠עַמִּ֥ים רַבִּ֖ים אוֹתָֽ⁠ךְ׃ס","wĕ⁠ʻáli֨yţá֙ kȧ⁠şò̇̌ʼá֣h ţáb֔wòʼ kė⁠ʻáná֛n lĕ⁠kaṡ֥wòţ há⁠ʼá֖reẕ ţiֽ̇hĕye֑h ʼaţá̇h֙ wĕ⁠kál-ʼàgapė֔y⁠ká wĕ⁠ʻami֥̇ym rabi֖̇ym ʼwòţáֽ⁠kĕ׃s"],[38,10,"כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יַעֲל֤וּ דְבָרִים֙ עַל־לְבָבֶ֔⁠ךָ וְ⁠חָשַׁבְתָּ֖ מַחֲשֶׁ֥בֶת רָעָֽה׃","kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yaʻàl֤ẇ dĕbáriym֙ ʻal-lĕbábe֔⁠ká wĕ⁠ẖáşǎbĕţá֖̇ maẖàşě֥beţ ráʻáֽh׃"],[38,11,"וְ⁠אָמַרְתָּ֗ אֶֽעֱלֶה֙ עַל־אֶ֣רֶץ פְּרָז֔וֹת אָבוֹא֙ הַ⁠שֹּׁ֣קְטִ֔ים יֹשְׁבֵ֖י לָ⁠בֶ֑טַח כֻּלָּ֗⁠ם יֹֽשְׁבִים֙ בְּ⁠אֵ֣ין חוֹמָ֔ה וּ⁠בְרִ֥יחַ וּ⁠דְלָתַ֖יִם אֵ֥ין לָ⁠הֶֽם׃","wĕ⁠ʼámarĕţá̇֗ ʼeֽʻèleh֙ ʻal-ʼe֣reẕ pĕ̇ráz֔wòţ ʼábwòʼ֙ ha⁠şò֣̇̌qĕti֔ym yòşĕ̌bé֖y lá⁠be֑taẖ ku̇lá̇֗⁠m yòֽşĕ̌biym֙ bĕ̇⁠ʼé֣yn ẖwòmá֔h ẇ⁠bĕri֥yẖa ẇ⁠dĕláţa֖yim ʼé֥yn lá⁠heֽm׃"],[38,12,"לִ⁠שְׁלֹ֥ל שָׁלָ֖ל וְ⁠לָ⁠בֹ֣ז בַּ֑ז לְ⁠הָשִׁ֨יב יָדְ⁠ךָ֜ עַל־חֳרָב֣וֹת נוֹשָׁבֹ֗ת וְ⁠אֶל־עַם֙ מְאֻסָּ֣ף מִ⁠גּוֹיִ֔ם עֹשֶׂה֙ מִקְנֶ֣ה וְ⁠קִנְיָ֔ן יֹשְׁבֵ֖י עַל־טַבּ֥וּר הָ⁠אָֽרֶץ׃","li⁠şĕ̌lò֥l şá̌lá֖l wĕ⁠lá⁠bò֣z bȧ֑z lĕ⁠háşǐ֨yb yádĕ⁠ká֜ ʻal-ẖoráb֣wòţ nwòşá̌bò֗ţ wĕ⁠ʼel-ʻam֙ mĕʼusá֣̇p mi⁠ġwòyi֔m ʻòşêh֙ miqĕne֣h wĕ⁠qinĕyá֔n yòşĕ̌bé֖y ʻal-taḃ֥ẇr há⁠ʼáֽreẕ׃"],[38,13,"שְׁבָ֡א וּ֠⁠דְדָן וְ⁠סֹחֲרֵ֨י תַרְשִׁ֤ישׁ וְ⁠כָל־כְּפִרֶ֨י⁠הָ֙ יֹאמְר֣וּ לְ⁠ךָ֔ הֲ⁠לִ⁠שְׁלֹ֤ל שָׁלָל֙ אַתָּ֣ה בָ֔א הֲ⁠לָ⁠בֹ֥ז בַּ֖ז הִקְהַ֣לְתָּ קְהָלֶ֑⁠ךָ לָ⁠שֵׂ֣את ׀ כֶּ֣סֶף וְ⁠זָהָ֗ב לָ⁠קַ֨חַת֙ מִקְנֶ֣ה וְ⁠קִנְיָ֔ן לִ⁠שְׁלֹ֖ל שָׁלָ֥ל גָּדֽוֹל׃ס","şĕ̌bá֡ʼ ẇ֠⁠dĕdán wĕ⁠sòẖàré֨y ţarĕşǐ֤yş̌ wĕ⁠kál-kĕ̇pire֨y⁠há֙ yòʼmĕr֣ẇ lĕ⁠ká֔ hà⁠li⁠şĕ̌lò֤l şá̌lál֙ ʼaţá֣̇h bá֔ʼ hà⁠lá⁠bò֥z bȧ֖z hiqĕha֣lĕţá̇ qĕhále֑⁠ká lá⁠şé֣̂ʼţ ׀ kė֣sep wĕ⁠záhá֗b lá⁠qa֨ẖaţ֙ miqĕne֣h wĕ⁠qinĕyá֔n li⁠şĕ̌lò֖l şá̌lá֥l gá̇dֽwòl׃s"],[38,14,"לָ⁠כֵן֙ הִנָּבֵ֣א בֶן־אָדָ֔ם וְ⁠אָמַרְתָּ֣ לְ⁠ג֔וֹג כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה הֲ⁠ל֣וֹא ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא בְּ⁠שֶׁ֨בֶת עַמִּ֧⁠י יִשְׂרָאֵ֛ל לָ⁠בֶ֖טַח תֵּדָֽע׃","lá⁠kén֙ hiná̇bé֣ʼ ben-ʼádá֔m wĕ⁠ʼámarĕţá֣̇ lĕ⁠g֔wòg kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h hà⁠l֣wòʼ ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ bĕ̇⁠şě֨beţ ʻami֧̇⁠y yişĕ̂ráʼé֛l lá⁠be֖taẖ ţé̇dáֽʻ׃"],[38,15,"וּ⁠בָ֤אתָ מִ⁠מְּקֽוֹמְ⁠ךָ֙ מִ⁠יַּרְכְּתֵ֣י צָפ֔וֹן אַתָּ֕ה וְ⁠עַמִּ֥ים רַבִּ֖ים אִתָּ֑⁠ךְ רֹכְבֵ֤י סוּסִים֙ כֻּלָּ֔⁠ם קָהָ֥ל גָּד֖וֹל וְ⁠חַ֥יִל רָֽב׃","ẇ⁠bá֤ʼţá mi⁠mĕ̇qֽwòmĕ⁠ká֙ mi⁠yȧrĕkĕ̇ţé֣y ẕáp֔wòn ʼaţá̇֕h wĕ⁠ʻami֥̇ym rabi֖̇ym ʼiţá֑̇⁠kĕ ròkĕbé֤y sẇsiym֙ ku̇lá̇֔⁠m qáhá֥l gá̇d֖wòl wĕ⁠ẖa֥yil ráֽb׃"],[38,16,"וְ⁠עָלִ֨יתָ֙ עַל־עַמִּ֣⁠י יִשְׂרָאֵ֔ל כֶּֽ⁠עָנָ֖ן לְ⁠כַסּ֣וֹת הָ⁠אָ֑רֶץ בְּ⁠אַחֲרִ֨ית הַ⁠יָּמִ֜ים תִּֽהְיֶ֗ה וַ⁠הֲבִאוֹתִ֨י⁠ךָ֙ עַל־אַרְצִ֔⁠י לְמַעַן֩ דַּ֨עַת הַ⁠גּוֹיִ֜ם אֹתִ֗⁠י בְּ⁠הִקָּדְשִׁ֥⁠י בְ⁠ךָ֛ לְ⁠עֵינֵי⁠הֶ֖ם גּֽוֹג׃ס","wĕ⁠ʻáli֨yţá֙ ʻal-ʻami֣̇⁠y yişĕ̂ráʼé֔l kėֽ⁠ʻáná֖n lĕ⁠kaṡ֣wòţ há⁠ʼá֑reẕ bĕ̇⁠ʼaẖàri֨yţ ha⁠yá̇mi֜ym ţiֽ̇hĕye֗h wa⁠hàbiʼwòţi֨y⁠ká֙ ʻal-ʼarĕẕi֔⁠y lĕmaʻan֩ dȧ֨ʻaţ ha⁠ġwòyi֜m ʼòţi֗⁠y bĕ̇⁠hiqá̇dĕşǐ֥⁠y bĕ⁠ká֛ lĕ⁠ʻéynéy⁠he֖m ġֽwòg׃s"],[38,17,"כֹּֽה־אָמַ֞ר אֲדֹנָ֣⁠י יְהוִ֗ה הַֽ⁠אַתָּה־ה֨וּא אֲשֶׁר־דִּבַּ֜רְתִּי בְּ⁠יָמִ֣ים קַדְמוֹנִ֗ים בְּ⁠יַד֙ עֲבָדַ⁠י֙ נְבִיאֵ֣י יִשְׂרָאֵ֔ל הַֽ⁠נִּבְּאִ֛ים בַּ⁠יָּמִ֥ים הָ⁠הֵ֖ם שָׁנִ֑ים לְ⁠הָבִ֥יא אֹתְ⁠ךָ֖ עֲלֵי⁠הֶֽם׃ס","kòֽ̇h-ʼáma֞r ʼàdòná֣⁠y yĕhwi֗h haֽ⁠ʼaţá̇h-h֨ẇʼ ʼàşěr-di̇bȧ֜rĕţi̇y bĕ̇⁠yámi֣ym qadĕmwòni֗ym bĕ̇⁠yad֙ ʻàbáda⁠y֙ nĕbiyʼé֣y yişĕ̂ráʼé֔l haֽ⁠ni̇bĕ̇ʼi֛ym bȧ⁠yá̇mi֥ym há⁠hé֖m şá̌ni֑ym lĕ⁠hábi֥yʼ ʼòţĕ⁠ká֖ ʻàléy⁠heֽm׃s"],[38,18,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא בְּ⁠י֨וֹם בּ֥וֹא גוֹג֙ עַל־אַדְמַ֣ת יִשְׂרָאֵ֔ל נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה תַּעֲלֶ֥ה חֲמָתִ֖⁠י בְּ⁠אַפִּֽ⁠י׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ bĕ̇⁠y֨wòm ḃ֥wòʼ gwòg֙ ʻal-ʼadĕma֣ţ yişĕ̂ráʼé֔l nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h ţȧʻàle֥h ẖàmáţi֖⁠y bĕ̇⁠ʼapiֽ̇⁠y׃"],[38,19,"וּ⁠בְ⁠קִנְאָתִ֥⁠י בְ⁠אֵשׁ־עֶבְרָתִ֖⁠י דִּבַּ֑רְתִּי אִם־לֹ֣א ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא יִֽהְיֶה֙ רַ֣עַשׁ גָּד֔וֹל עַ֖ל אַדְמַ֥ת יִשְׂרָאֵֽל׃","ẇ⁠bĕ⁠qinĕʼáţi֥⁠y bĕ⁠ʼéş̌-ʻebĕráţi֖⁠y di̇bȧ֑rĕţi̇y ʼim-lò֣ʼ ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ yiֽhĕyeh֙ ra֣ʻaş̌ gá̇d֔wòl ʻa֖l ʼadĕma֥ţ yişĕ̂ráʼéֽl׃"],[38,20,"וְ⁠רָעֲשׁ֣וּ מִ⁠פָּנַ֡⁠י דְּגֵ֣י הַ⁠יָּם֩ וְ⁠ע֨וֹף הַ⁠שָּׁמַ֜יִם וְ⁠חַיַּ֣ת הַ⁠שָּׂדֶ֗ה וְ⁠כָל־הָ⁠רֶ֨מֶשׂ֙ הָ⁠רֹמֵ֣שׂ עַל־הָֽ⁠אֲדָמָ֔ה וְ⁠כֹל֙ הָֽ⁠אָדָ֔ם אֲשֶׁ֖ר עַל־פְּנֵ֣י הָ⁠אֲדָמָ֑ה וְ⁠נֶהֶרְס֣וּ הֶ⁠הָרִ֗ים וְ⁠נָֽפְלוּ֙ הַ⁠מַּדְרֵג֔וֹת וְ⁠כָל־חוֹמָ֖ה לָ⁠אָ֥רֶץ תִּפּֽוֹל׃","wĕ⁠ráʻàş֣̌ẇ mi⁠pá̇na֡⁠y dĕ̇gé֣y ha⁠yá̇m֩ wĕ⁠ʻ֨wòp ha⁠şá̇̌ma֜yim wĕ⁠ẖayȧ֣ţ ha⁠şá̇̂de֗h wĕ⁠kál-há⁠re֨meş̂֙ há⁠ròmé֣ş̂ ʻal-háֽ⁠ʼàdámá֔h wĕ⁠kòl֙ háֽ⁠ʼádá֔m ʼàşě֖r ʻal-pĕ̇né֣y há⁠ʼàdámá֑h wĕ⁠neherĕs֣ẇ he⁠hári֗ym wĕ⁠náֽpĕlẇ֙ ha⁠mȧdĕrég֔wòţ wĕ⁠kál-ẖwòmá֖h lá⁠ʼá֥reẕ ţi̇ṗֽwòl׃"],[38,21,"וְ⁠קָרָ֨אתִי עָלָ֤י⁠ו לְ⁠כָל־הָרַ⁠י֙ חֶ֔רֶב נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה חֶ֥רֶב אִ֖ישׁ בְּ⁠אָחִ֥י⁠ו תִּֽהְיֶֽה׃","wĕ⁠qárá֨ʼţiy ʻálá֤y⁠w lĕ⁠kál-hára⁠y֙ ẖe֔reb nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h ẖe֥reb ʼi֖yş̌ bĕ̇⁠ʼáẖi֥y⁠w ţiֽ̇hĕyeֽh׃"],[38,22,"וְ⁠נִשְׁפַּטְתִּ֥י אִתּ֖⁠וֹ בְּ⁠דֶ֣בֶר וּ⁠בְ⁠דָ֑ם וְ⁠גֶ֣שֶׁם שׁוֹטֵף֩ וְ⁠אַבְנֵ֨י אֶלְגָּבִ֜ישׁ אֵ֣שׁ וְ⁠גָפְרִ֗ית אַמְטִ֤יר עָלָי⁠ו֙ וְ⁠עַל־אֲגַפָּ֔י⁠ו וְ⁠עַל־עַמִּ֥ים רַבִּ֖ים אֲשֶׁ֥ר אִתּֽ⁠וֹ׃","wĕ⁠nişĕ̌pȧtĕţi֥̇y ʼiţ֖̇⁠wò bĕ̇⁠de֣ber ẇ⁠bĕ⁠dá֑m wĕ⁠ge֣şěm ş̌wòtép֩ wĕ⁠ʼabĕné֨y ʼelĕgá̇bi֜yş̌ ʼé֣ş̌ wĕ⁠gápĕri֗yţ ʼamĕti֤yr ʻáláy⁠w֙ wĕ⁠ʻal-ʼàgapá̇֔y⁠w wĕ⁠ʻal-ʻami֥̇ym rabi֖̇ym ʼàşě֥r ʼiţֽ̇⁠wò׃"],[38,23,"וְ⁠הִתְגַּדִּלְתִּי֙ וְ⁠הִתְקַדִּשְׁתִּ֔י וְ⁠נ֣וֹדַעְתִּ֔י לְ⁠עֵינֵ֖י גּוֹיִ֣ם רַבִּ֑ים וְ⁠יָדְע֖וּ כִּֽי־אֲנִ֥י יְהוָֽה׃ס","wĕ⁠hiţĕgȧdi̇lĕţi̇y֙ wĕ⁠hiţĕqadi̇şĕ̌ţi̇֔y wĕ⁠n֣wòdaʻĕţi̇֔y lĕ⁠ʻéyné֖y ġwòyi֣m rabi֑̇ym wĕ⁠yádĕʻ֖ẇ kiֽ̇y-ʼàni֥y yĕhwáֽh׃s"],[39,1,"וְ⁠אַתָּ֤ה בֶן־אָדָם֙ הִנָּבֵ֣א עַל־גּ֔וֹג וְ⁠אָ֣מַרְתָּ֔ כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה הִנְ⁠נִ֤י אֵלֶ֨י⁠ךָ֙ גּ֔וֹג נְשִׂ֕יא רֹ֖אשׁ מֶ֥שֶׁךְ וְ⁠תֻבָֽל׃","wĕ⁠ʼaţá֤̇h ben-ʼádám֙ hiná̇bé֣ʼ ʻal-ġ֔wòg wĕ⁠ʼá֣marĕţá̇֔ kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h hinĕ⁠ni֤y ʼéle֨y⁠ká֙ ġ֔wòg nĕşî֕yʼ rò֖ʼş̌ me֥şěkĕ wĕ⁠ţubáֽl׃"],[39,2,"וְ⁠שֹׁבַבְתִּ֨י⁠ךָ֙ וְ⁠שִׁשֵּׁאתִ֔י⁠ךָ וְ⁠הַעֲלִיתִ֖י⁠ךָ מִ⁠יַּרְכְּתֵ֣י צָפ֑וֹן וַ⁠הֲבִאוֹתִ֖⁠ךָ עַל־הָרֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠şò̌babĕţi̇֨y⁠ká֙ wĕ⁠şǐşé̇̌ʼţi֔y⁠ká wĕ⁠haʻàliyţi֖y⁠ká mi⁠yȧrĕkĕ̇ţé֣y ẕáp֑wòn wa⁠hàbiʼwòţi֖⁠ká ʻal-háré֥y yişĕ̂ráʼéֽl׃"],[39,3,"וְ⁠הִכֵּיתִ֥י קַשְׁתְּ⁠ךָ֖ מִ⁠יַּ֣ד שְׂמֹאולֶ֑⁠ךָ וְ⁠חִצֶּ֕י⁠ךָ מִ⁠יַּ֥ד יְמִינְ⁠ךָ֖ אַפִּֽיל׃","wĕ⁠hiké̇yţi֥y qaşĕ̌ţĕ̇⁠ká֖ mi⁠yȧ֣d şĕ̂mòʼwle֑⁠ká wĕ⁠ẖiẕė֕y⁠ká mi⁠yȧ֥d yĕmiynĕ⁠ká֖ ʼapiֽ̇yl׃"],[39,4,"עַל־הָרֵ֨י יִשְׂרָאֵ֜ל תִּפּ֗וֹל אַתָּה֙ וְ⁠כָל־אֲגַפֶּ֔י⁠ךָ וְ⁠עַמִּ֖ים אֲשֶׁ֣ר אִתָּ֑⁠ךְ לְ⁠עֵ֨יט צִפּ֧וֹר כָּל־כָּנָ֛ף וְ⁠חַיַּ֥ת הַ⁠שָּׂדֶ֖ה נְתַתִּ֥י⁠ךָ לְ⁠אָכְלָֽה׃","ʻal-háré֨y yişĕ̂ráʼé֜l ţi̇ṗ֗wòl ʼaţá̇h֙ wĕ⁠kál-ʼàgapė֔y⁠ká wĕ⁠ʻami֖̇ym ʼàşě֣r ʼiţá֑̇⁠kĕ lĕ⁠ʻé֨yt ẕiṗ֧wòr ká̇l-ká̇ná֛p wĕ⁠ẖayȧ֥ţ ha⁠şá̇̂de֖h nĕţaţi֥̇y⁠ká lĕ⁠ʼákĕláֽh׃"],[39,5,"עַל־פְּנֵ֥י הַ⁠שָּׂדֶ֖ה תִּפּ֑וֹל כִּ֚י אֲנִ֣י דִבַּ֔רְתִּי נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","ʻal-pĕ̇né֥y ha⁠şá̇̂de֖h ţi̇ṗ֑wòl ki֚̇y ʼàni֣y dibȧ֔rĕţi̇y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[39,6,"וְ⁠שִׁלַּחְתִּי־אֵ֣שׁ בְּ⁠מָג֔וֹג וּ⁠בְ⁠יֹשְׁבֵ֥י הָ⁠אִיִּ֖ים לָ⁠בֶ֑טַח וְ⁠יָדְע֖וּ כִּי־אֲנִ֥י יְהוָֽה׃","wĕ⁠şǐlȧẖĕţi̇y-ʼé֣ş̌ bĕ̇⁠mág֔wòg ẇ⁠bĕ⁠yòşĕ̌bé֥y há⁠ʼiyi֖̇ym lá⁠be֑taẖ wĕ⁠yádĕʻ֖ẇ ki̇y-ʼàni֥y yĕhwáֽh׃"],[39,7,"וְ⁠אֶת־שֵׁ֨ם קָדְשִׁ֜⁠י אוֹדִ֗יעַ בְּ⁠תוֹךְ֙ עַמִּ֣⁠י יִשְׂרָאֵ֔ל וְ⁠לֹֽא־אַחֵ֥ל אֶת־שֵׁם־קָדְשִׁ֖⁠י ע֑וֹד וְ⁠יָדְע֤וּ הַ⁠גּוֹיִם֙ כִּי־אֲנִ֣י יְהוָ֔ה קָד֖וֹשׁ בְּ⁠יִשְׂרָאֵֽל׃","wĕ⁠ʼeţ-şé̌֨m qádĕşǐ֜⁠y ʼwòdi֗yʻa bĕ̇⁠ţwòkĕ֙ ʻami֣̇⁠y yişĕ̂ráʼé֔l wĕ⁠lòֽʼ-ʼaẖé֥l ʼeţ-şé̌m-qádĕşǐ֖⁠y ʻ֑wòd wĕ⁠yádĕʻ֤ẇ ha⁠ġwòyim֙ ki̇y-ʼàni֣y yĕhwá֔h qád֖wòş̌ bĕ̇⁠yişĕ̂ráʼéֽl׃"],[39,8,"הִנֵּ֤ה בָאָה֙ וְ⁠נִֽהְיָ֔תָה נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה ה֥וּא הַ⁠יּ֖וֹם אֲשֶׁ֥ר דִּבַּֽרְתִּי׃","hiné֤̇h báʼáh֙ wĕ⁠niֽhĕyá֔ţáh nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h h֥ẇʼ ha⁠ẏ֖wòm ʼàşě֥r di̇bȧֽrĕţi̇y׃"],[39,9,"וְֽ⁠יָצְא֞וּ יֹשְׁבֵ֣י ׀ עָרֵ֣י יִשְׂרָאֵ֗ל וּ⁠בִעֲר֡וּ וְ֠⁠הִשִּׂיקוּ בְּ⁠נֶ֨שֶׁק וּ⁠מָגֵ֤ן וְ⁠צִנָּה֙ בְּ⁠קֶ֣שֶׁת וּ⁠בְ⁠חִצִּ֔ים וּ⁠בְ⁠מַקֵּ֥ל יָ֖ד וּ⁠בְ⁠רֹ֑מַח וּ⁠בִעֲר֥וּ בָ⁠הֶ֛ם אֵ֖שׁ שֶׁ֥בַע שָׁנִֽים׃","wĕֽ⁠yáẕĕʼ֞ẇ yòşĕ̌bé֣y ׀ ʻáré֣y yişĕ̂ráʼé֗l ẇ⁠biʻàr֡ẇ wĕ֠⁠hişi̇̂yqẇ bĕ̇⁠ne֨şěq ẇ⁠mágé֤n wĕ⁠ẕiná̇h֙ bĕ̇⁠qe֣şěţ ẇ⁠bĕ⁠ẖiẕi̇֔ym ẇ⁠bĕ⁠maqé֥̇l yá֖d ẇ⁠bĕ⁠rò֑maẖ ẇ⁠biʻàr֥ẇ bá⁠he֛m ʼé֖ş̌ şě֥baʻ şá̌niֽym׃"],[39,10,"וְ⁠לֹֽא־יִשְׂא֨וּ עֵצִ֜ים מִן־הַ⁠שָּׂדֶ֗ה וְ⁠לֹ֤א יַחְטְבוּ֙ מִן־הַ⁠יְּעָרִ֔ים כִּ֥י בַ⁠נֶּ֖שֶׁק יְבַֽעֲרוּ־אֵ֑שׁ וְ⁠שָׁלְל֣וּ אֶת־שֹׁלְלֵי⁠הֶ֗ם וּ⁠בָֽזְזוּ֙ אֶת־בֹּ֣זְזֵי⁠הֶ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","wĕ⁠lòֽʼ-yişĕ̂ʼ֨ẇ ʻéẕi֜ym min-ha⁠şá̇̂de֗h wĕ⁠lò֤ʼ yaẖĕtĕbẇ֙ min-ha⁠yĕ̇ʻári֔ym ki֥̇y ba⁠nė֖şěq yĕbaֽʻàrẇ-ʼé֑ş̌ wĕ⁠şá̌lĕl֣ẇ ʼeţ-şò̌lĕléy⁠he֗m ẇ⁠báֽzĕzẇ֙ ʼeţ-bò֣̇zĕzéy⁠he֔m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[39,11,"וְ⁠הָיָ֣ה בַ⁠יּ֣וֹם הַ⁠ה֡וּא אֶתֵּ֣ן לְ⁠גוֹג֩ ׀ מְקֽוֹם־שָׁ֨ם קֶ֜בֶר בְּ⁠יִשְׂרָאֵ֗ל גֵּ֤י הָ⁠עֹֽבְרִים֙ קִדְמַ֣ת הַ⁠יָּ֔ם וְ⁠חֹסֶ֥מֶת הִ֖יא אֶת־הָ⁠עֹֽבְרִ֑ים וְ⁠קָ֣בְרוּ שָׁ֗ם אֶת־גּוֹג֙ וְ⁠אֶת־כָּל־הֲמוֹנֹ֔⁠ה וְ⁠קָ֣רְא֔וּ גֵּ֖יא הֲמ֥וֹן גּֽוֹג׃","wĕ⁠háyá֣h ba⁠ẏ֣wòm ha⁠h֡ẇʼ ʼeţé֣̇n lĕ⁠gwòg֩ ׀ mĕqֽwòm-şá̌֨m qe֜ber bĕ̇⁠yişĕ̂ráʼé֗l gé֤̇y há⁠ʻòֽbĕriym֙ qidĕma֣ţ ha⁠yá̇֔m wĕ⁠ẖòse֥meţ hi֖yʼ ʼeţ-há⁠ʻòֽbĕri֑ym wĕ⁠qá֣bĕrẇ şá̌֗m ʼeţ-ġwòg֙ wĕ⁠ʼeţ-ká̇l-hàmwònò֔⁠h wĕ⁠qá֣rĕʼ֔ẇ gé֖̇yʼ hàm֥wòn ġֽwòg׃"],[39,12,"וּ⁠קְבָרוּ⁠ם֙ בֵּ֣ית יִשְׂרָאֵ֔ל לְמַ֖עַן טַהֵ֣ר אֶת־הָ⁠אָ֑רֶץ שִׁבְעָ֖ה חֳדָשִֽׁים׃","ẇ⁠qĕbárẇ⁠m֙ bé֣̇yţ yişĕ̂ráʼé֔l lĕma֖ʻan tahé֣r ʼeţ-há⁠ʼá֑reẕ şǐbĕʻá֖h ẖodáşǐֽym׃"],[39,13,"וְ⁠קָֽבְרוּ֙ כָּל־עַ֣ם הָ⁠אָ֔רֶץ וְ⁠הָיָ֥ה לָ⁠הֶ֖ם לְ⁠שֵׁ֑ם י֚וֹם הִכָּ֣בְדִ֔⁠י נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wĕ⁠qáֽbĕrẇ֙ ká̇l-ʻa֣m há⁠ʼá֔reẕ wĕ⁠háyá֥h lá⁠he֖m lĕ⁠şé֑̌m y֚wòm hiká֣̇bĕdi֔⁠y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[39,14,"וְ⁠אַנְשֵׁ֨י תָמִ֤יד יַבְדִּ֨ילוּ֙ עֹבְרִ֣ים בָּ⁠אָ֔רֶץ מְקַבְּרִ֣ים אֶת־הָ⁠עֹבְרִ֗ים אֶת־הַ⁠נּוֹתָרִ֛ים עַל־פְּנֵ֥י הָ⁠אָ֖רֶץ לְ⁠טַֽהֲרָ֑⁠הּ מִ⁠קְצֵ֥ה שִׁבְעָֽה־חֳדָשִׁ֖ים יַחְקֹֽרוּ׃","wĕ⁠ʼanĕşé̌֨y ţámi֤yd yabĕdi̇֨ylẇ֙ ʻòbĕri֣ym bá̇⁠ʼá֔reẕ mĕqabĕ̇ri֣ym ʼeţ-há⁠ʻòbĕri֗ym ʼeţ-ha⁠ṅwòţári֛ym ʻal-pĕ̇né֥y há⁠ʼá֖reẕ lĕ⁠taֽhàrá֑⁠ḣ mi⁠qĕẕé֥h şǐbĕʻáֽh-ẖodáşǐ֖ym yaẖĕqòֽrẇ׃"],[39,15,"וְ⁠עָבְר֤וּ הָ⁠עֹֽבְרִים֙ בָּ⁠אָ֔רֶץ וְ⁠רָאָה֙ עֶ֣צֶם אָדָ֔ם וּ⁠בָנָ֥ה אֶצְל֖⁠וֹ צִיּ֑וּן עַ֣ד קָבְר֤וּ אֹת⁠וֹ֙ הַֽ⁠מְקַבְּרִ֔ים אֶל־גֵּ֖יא הֲמ֥וֹן גּֽוֹג׃","wĕ⁠ʻábĕr֤ẇ há⁠ʻòֽbĕriym֙ bá̇⁠ʼá֔reẕ wĕ⁠ráʼáh֙ ʻe֣ẕem ʼádá֔m ẇ⁠báná֥h ʼeẕĕl֖⁠wò ẕiẏ֑ẇn ʻa֣d qábĕr֤ẇ ʼòţ⁠wò֙ haֽ⁠mĕqabĕ̇ri֔ym ʼel-gé֖̇yʼ hàm֥wòn ġֽwòg׃"],[39,16,"וְ⁠גַ֥ם שֶׁם־עִ֛יר הֲמוֹנָ֖ה וְ⁠טִהֲר֥וּ הָ⁠אָֽרֶץ׃ס","wĕ⁠ga֥m şěm-ʻi֛yr hàmwòná֖h wĕ⁠tihàr֥ẇ há⁠ʼáֽreẕ׃s"],[39,17,"וְ⁠אַתָּ֨ה בֶן־אָדָ֜ם כֹּֽה־אָמַ֣ר ׀ אֲדֹנָ֣⁠י יְהֹוִ֗ה אֱמֹר֩ לְ⁠צִפּ֨וֹר כָּל־כָּנָ֜ף וּ⁠לְ⁠כֹ֣ל ׀ חַיַּ֣ת הַ⁠שָּׂדֶ֗ה הִקָּבְצ֤וּ וָ⁠בֹ֨אוּ֙ הֵאָסְפ֣וּ מִ⁠סָּבִ֔יב עַל־זִבְחִ֗⁠י אֲשֶׁ֨ר אֲנִ֜י זֹבֵ֤חַ לָ⁠כֶם֙ זֶ֣בַח גָּד֔וֹל עַ֖ל הָרֵ֣י יִשְׂרָאֵ֑ל וַ⁠אֲכַלְתֶּ֥ם בָּשָׂ֖ר וּ⁠שְׁתִ֥יתֶם דָּֽם׃","wĕ⁠ʼaţá̇֨h ben-ʼádá֜m kòֽ̇h-ʼáma֣r ׀ ʼàdòná֣⁠y yĕhòwi֗h ʼèmòr֩ lĕ⁠ẕiṗ֨wòr ká̇l-ká̇ná֜p ẇ⁠lĕ⁠kò֣l ׀ ẖayȧ֣ţ ha⁠şá̇̂de֗h hiqá̇bĕẕ֤ẇ wá⁠bò֨ʼẇ֙ héʼásĕp֣ẇ mi⁠sá̇bi֔yb ʻal-zibĕẖi֗⁠y ʼàşě֨r ʼàni֜y zòbé֤ẖa lá⁠kem֙ ze֣baẖ gá̇d֔wòl ʻa֖l háré֣y yişĕ̂ráʼé֑l wa⁠ʼàkalĕţė֥m bá̇şá֖̂r ẇ⁠şĕ̌ţi֥yţem dáֽ̇m׃"],[39,18,"בְּשַׂ֤ר גִּבּוֹרִים֙ תֹּאכֵ֔לוּ וְ⁠דַם־נְשִׂיאֵ֥י הָ⁠אָ֖רֶץ תִּשְׁתּ֑וּ אֵילִ֨ים כָּרִ֤ים וְ⁠עַתּוּדִים֙ פָּרִ֔ים מְרִיאֵ֥י בָשָׁ֖ן כֻּלָּֽ⁠ם׃","bĕ̇şâ֤r gi̇ḃwòriym֙ ţò̇ʼké֔lẇ wĕ⁠dam-nĕşîyʼé֥y há⁠ʼá֖reẕ ţi̇şĕ̌ţ֑̇ẇ ʼéyli֨ym ká̇ri֤ym wĕ⁠ʻaţ̇ẇdiym֙ pá̇ri֔ym mĕriyʼé֥y báşá֖̌n ku̇láֽ̇⁠m׃"],[39,19,"וַ⁠אֲכַלְתֶּם־חֵ֣לֶב לְ⁠שָׂבְעָ֔ה וּ⁠שְׁתִ֥יתֶם דָּ֖ם לְ⁠שִׁכָּר֑וֹן מִ⁠זִּבְחִ֖⁠י אֲשֶׁר־זָבַ֥חְתִּי לָ⁠כֶֽם׃","wa⁠ʼàkalĕţėm-ẖé֣leb lĕ⁠şá̂bĕʻá֔h ẇ⁠şĕ̌ţi֥yţem dá֖̇m lĕ⁠şǐká̇r֑wòn mi⁠zi̇bĕẖi֖⁠y ʼàşěr-zába֥ẖĕţi̇y lá⁠keֽm׃"],[39,20,"וּ⁠שְׂבַעְתֶּ֤ם עַל־שֻׁלְחָנִ⁠י֙ ס֣וּס וָ⁠רֶ֔כֶב גִּבּ֖וֹר וְ⁠כָל־אִ֣ישׁ מִלְחָמָ֑ה נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","ẇ⁠şĕ̂baʻĕţė֤m ʻal-şǔlĕẖáni⁠y֙ s֣ẇs wá⁠re֔keb gi̇ḃ֖wòr wĕ⁠kál-ʼi֣yş̌ milĕẖámá֑h nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[39,21,"וְ⁠נָתַתִּ֥י אֶת־כְּבוֹדִ֖⁠י בַּ⁠גּוֹיִ֑ם וְ⁠רָא֣וּ כָל־הַ⁠גּוֹיִ֗ם אֶת־מִשְׁפָּטִ⁠י֙ אֲשֶׁ֣ר עָשִׂ֔יתִי וְ⁠אֶת־יָדִ֖⁠י אֲשֶׁר־שַׂ֥מְתִּי בָ⁠הֶֽם׃","wĕ⁠náţaţi֥̇y ʼeţ-kĕ̇bwòdi֖⁠y bȧ⁠ġwòyi֑m wĕ⁠ráʼ֣ẇ kál-ha⁠ġwòyi֗m ʼeţ-mişĕ̌pá̇ti⁠y֙ ʼàşě֣r ʻáşî֔yţiy wĕ⁠ʼeţ-yádi֖⁠y ʼàşěr-şâ֥mĕţi̇y bá⁠heֽm׃"],[39,22,"וְ⁠יָֽדְעוּ֙ בֵּ֣ית יִשְׂרָאֵ֔ל כִּ֛י אֲנִ֥י יְהוָ֖ה אֱלֹֽהֵי⁠הֶ֑ם מִן־הַ⁠יּ֥וֹם הַ⁠ה֖וּא וָ⁠הָֽלְאָה׃","wĕ⁠yáֽdĕʻẇ֙ bé֣̇yţ yişĕ̂ráʼé֔l ki֛̇y ʼàni֥y yĕhwá֖h ʼèlòֽhéy⁠he֑m min-ha⁠ẏ֥wòm ha⁠h֖ẇʼ wá⁠háֽlĕʼáh׃"],[39,23,"וְ⁠יָדְע֣וּ הַ֠⁠גּוֹיִם כִּ֣י בַ⁠עֲוֺנָ֞⁠ם גָּל֣וּ בֵֽית־יִשְׂרָאֵ֗ל עַ֚ל אֲשֶׁ֣ר מָֽעֲלוּ־בִ֔⁠י וָ⁠אַסְתִּ֥ר פָּנַ֖⁠י מֵ⁠הֶ֑ם וָֽ⁠אֶתְּנֵ⁠ם֙ בְּ⁠יַ֣ד צָרֵי⁠הֶ֔ם וַ⁠יִּפְּל֥וּ בַ⁠חֶ֖רֶב כֻּלָּֽ⁠ם׃","wĕ⁠yádĕʻ֣ẇ ha֠⁠ġwòyim ki֣̇y ba⁠ʻàwֺná֞⁠m gá̇l֣ẇ béֽyţ-yişĕ̂ráʼé֗l ʻa֚l ʼàşě֣r máֽʻàlẇ-bi֔⁠y wá⁠ʼasĕţi֥̇r pá̇na֖⁠y mé⁠he֑m wáֽ⁠ʼeţĕ̇né⁠m֙ bĕ̇⁠ya֣d ẕáréy⁠he֔m wa⁠yi̇pĕ̇l֥ẇ ba⁠ẖe֖reb ku̇láֽ̇⁠m׃"],[39,24,"כְּ⁠טֻמְאָתָ֥⁠ם וּ⁠כְ⁠פִשְׁעֵי⁠הֶ֖ם עָשִׂ֣יתִי אֹתָ֑⁠ם וָ⁠אַסְתִּ֥ר פָּנַ֖⁠י מֵ⁠הֶֽם׃ס","kĕ̇⁠tumĕʼáţá֥⁠m ẇ⁠kĕ⁠pişĕ̌ʻéy⁠he֖m ʻáşî֣yţiy ʼòţá֑⁠m wá⁠ʼasĕţi֥̇r pá̇na֖⁠y mé⁠heֽm׃s"],[39,25,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה עַתָּ֗ה אָשִׁיב֙ אֶת־שבית יַֽעֲקֹ֔ב וְ⁠רִֽחַמְתִּ֖י כָּל־בֵּ֣ית יִשְׂרָאֵ֑ל וְ⁠קִנֵּאתִ֖י לְ⁠שֵׁ֥ם קָדְשִֽׁ⁠י׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ʻaţá̇֗h ʼáşǐyb֙ ʼeţ-şbyţ yaֽʻàqò֔b wĕ⁠riֽẖamĕţi֖̇y ká̇l-bé֣̇yţ yişĕ̂ráʼé֑l wĕ⁠qiné̇ʼţi֖y lĕ⁠şé֥̌m qádĕşǐֽ⁠y׃"],[39,26,"וְ⁠נָשׂוּ֙ אֶת־כְּלִמָּתָ֔⁠ם וְ⁠אֶת־כָּל־מַעֲלָ֖⁠ם אֲשֶׁ֣ר מָעֲלוּ־בִ֑⁠י בְּ⁠שִׁבְתָּ֧⁠ם עַל־אַדְמָתָ֛⁠ם לָ⁠בֶ֖טַח וְ⁠אֵ֥ין מַחֲרִֽיד׃","wĕ⁠náş̂ẇ֙ ʼeţ-kĕ̇limá̇ţá֔⁠m wĕ⁠ʼeţ-ká̇l-maʻàlá֖⁠m ʼàşě֣r máʻàlẇ-bi֑⁠y bĕ̇⁠şǐbĕţá֧̇⁠m ʻal-ʼadĕmáţá֛⁠m lá⁠be֖taẖ wĕ⁠ʼé֥yn maẖàriֽyd׃"],[39,27,"בְּ⁠שׁוֹבְבִ֤⁠י אוֹתָ⁠ם֙ מִן־הָ֣⁠עַמִּ֔ים וְ⁠קִבַּצְתִּ֣י אֹתָ֔⁠ם מֵֽ⁠אַרְצ֖וֹת אֹֽיְבֵי⁠הֶ֑ם וְ⁠נִקְדַּ֣שְׁתִּי בָ֔⁠ם לְ⁠עֵינֵ֖י הַ⁠גּוֹיִ֥ם רַבִּֽים׃","bĕ̇⁠ş̌wòbĕbi֤⁠y ʼwòţá⁠m֙ min-há֣⁠ʻami̇֔ym wĕ⁠qibȧẕĕţi֣̇y ʼòţá֔⁠m méֽ⁠ʼarĕẕ֖wòţ ʼòֽyĕbéy⁠he֑m wĕ⁠niqĕdȧ֣şĕ̌ţi̇y bá֔⁠m lĕ⁠ʻéyné֖y ha⁠ġwòyi֥m rabiֽ̇ym׃"],[39,28,"וְ⁠יָדְע֗וּ כִּ֣י אֲנִ֤י יְהוָה֙ אֱלֹ֣הֵי⁠הֶ֔ם בְּ⁠הַגְלוֹתִ֤⁠י אֹתָ⁠ם֙ אֶל־הַ⁠גּוֹיִ֔ם וְ⁠כִנַּסְתִּ֖י⁠ם עַל־אַדְמָתָ֑⁠ם וְ⁠לֹֽא־אוֹתִ֥יר ע֛וֹד מֵ⁠הֶ֖ם שָֽׁם׃","wĕ⁠yádĕʻ֗ẇ ki֣̇y ʼàni֤y yĕhwáh֙ ʼèlò֣héy⁠he֔m bĕ̇⁠hagĕlwòţi֤⁠y ʼòţá⁠m֙ ʼel-ha⁠ġwòyi֔m wĕ⁠kinȧsĕţi֖̇y⁠m ʻal-ʼadĕmáţá֑⁠m wĕ⁠lòֽʼ-ʼwòţi֥yr ʻ֛wòd mé⁠he֖m şáֽ̌m׃"],[39,29,"וְ⁠לֹֽא־אַסְתִּ֥יר ע֛וֹד פָּנַ֖⁠י מֵ⁠הֶ֑ם אֲשֶׁ֨ר שָׁפַ֤כְתִּי אֶת־רוּחִ⁠י֙ עַל־בֵּ֣ית יִשְׂרָאֵ֔ל נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","wĕ⁠lòֽʼ-ʼasĕţi֥̇yr ʻ֛wòd pá̇na֖⁠y mé⁠he֑m ʼàşě֨r şá̌pa֤kĕţi̇y ʼeţ-rẇẖi⁠y֙ ʻal-bé֣̇yţ yişĕ̂ráʼé֔l nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[40,1,"בְּ⁠עֶשְׂרִ֣ים וְ⁠חָמֵ֣שׁ שָׁנָ֣ה לְ֠⁠גָלוּתֵ⁠נוּ בְּ⁠רֹ֨אשׁ הַ⁠שָּׁנָ֜ה בֶּ⁠עָשׂ֣וֹר לַ⁠חֹ֗דֶשׁ בְּ⁠אַרְבַּ֤ע עֶשְׂרֵה֙ שָׁנָ֔ה אַחַ֕ר אֲשֶׁ֥ר הֻכְּתָ֖ה הָ⁠עִ֑יר בְּ⁠עֶ֣צֶם ׀ הַ⁠יּ֣וֹם הַ⁠זֶּ֗ה הָיְתָ֤ה עָלַ⁠י֙ יַד־יְהוָ֔ה וַ⁠יָּבֵ֥א אֹתִ֖⁠י שָֽׁמָּ⁠ה׃","bĕ̇⁠ʻeşĕ̂ri֣ym wĕ⁠ẖámé֣ş̌ şá̌ná֣h lĕ֠⁠gálẇţé⁠nẇ bĕ̇⁠rò֨ʼş̌ ha⁠şá̇̌ná֜h bė⁠ʻáş֣̂wòr la⁠ẖò֗deş̌ bĕ̇⁠ʼarĕbȧ֤ʻ ʻeşĕ̂réh֙ şá̌ná֔h ʼaẖa֕r ʼàşě֥r hukĕ̇ţá֖h há⁠ʻi֑yr bĕ̇⁠ʻe֣ẕem ׀ ha⁠ẏ֣wòm ha⁠zė֗h háyĕţá֤h ʻála⁠y֙ yad-yĕhwá֔h wa⁠yá̇bé֥ʼ ʼòţi֖⁠y şáֽ̌má̇⁠h׃"],[40,2,"בְּ⁠מַרְא֣וֹת אֱלֹהִ֔ים הֱבִיאַ֖⁠נִי אֶל־אֶ֣רֶץ יִשְׂרָאֵ֑ל וַ⁠יְנִיחֵ֗⁠נִי אֶל־הַ֤ר גָּבֹ֨הַּ֙ מְאֹ֔ד וְ⁠עָלָ֥י⁠ו כְּ⁠מִבְנֵה־עִ֖יר מִ⁠נֶּֽגֶב׃","bĕ̇⁠marĕʼ֣wòţ ʼèlòhi֔ym hèbiyʼa֖⁠niy ʼel-ʼe֣reẕ yişĕ̂ráʼé֑l wa⁠yĕniyẖé֗⁠niy ʼel-ha֤r gá̇bò֨hȧ֙ mĕʼò֔d wĕ⁠ʻálá֥y⁠w kĕ̇⁠mibĕnéh-ʻi֖yr mi⁠nėֽgeb׃"],[40,3,"וַ⁠יָּבֵ֨יא אוֹתִ֜⁠י שָׁ֗מָּ⁠ה וְ⁠הִנֵּה־אִישׁ֙ מַרְאֵ֨⁠הוּ֙ כְּ⁠מַרְאֵ֣ה נְחֹ֔שֶׁת וּ⁠פְתִיל־פִּשְׁתִּ֥ים בְּ⁠יָד֖⁠וֹ וּ⁠קְנֵ֣ה הַ⁠מִּדָּ֑ה וְ⁠ה֥וּא עֹמֵ֖ד בַּ⁠שָּֽׁעַר׃","wa⁠yá̇bé֨yʼ ʼwòţi֜⁠y şá̌֗má̇⁠h wĕ⁠hiné̇h-ʼiyş̌֙ marĕʼé֨⁠hẇ֙ kĕ̇⁠marĕʼé֣h nĕẖò֔şěţ ẇ⁠pĕţiyl-pi̇şĕ̌ţi֥̇ym bĕ̇⁠yád֖⁠wò ẇ⁠qĕné֣h ha⁠mi̇dá֑̇h wĕ⁠h֥ẇʼ ʻòmé֖d bȧ⁠şáֽ̇̌ʻar׃"],[40,4,"וַ⁠יְדַבֵּ֨ר אֵלַ֜⁠י הָ⁠אִ֗ישׁ בֶּן־אָדָ֡ם רְאֵ֣ה בְ⁠עֵינֶי⁠ךָ֩ וּ⁠בְ⁠אָזְנֶ֨י⁠ךָ שְּׁמָ֜ע וְ⁠שִׂ֣ים לִבְּ⁠ךָ֗ לְ⁠כֹ֤ל אֲשֶׁר־אֲנִי֙ מַרְאֶ֣ה אוֹתָ֔⁠ךְ כִּ֛י לְמַ֥עַן הַרְאוֹתְ⁠כָ֖ה הֻבָ֣אתָה הֵ֑נָּה הַגֵּ֛ד אֶת־כָּל־אֲשֶׁר־אַתָּ֥ה רֹאֶ֖ה לְ⁠בֵ֥ית יִשְׂרָאֵֽל׃","wa⁠yĕdabé̇֨r ʼéla֜⁠y há⁠ʼi֗yş̌ bėn-ʼádá֡m rĕʼé֣h bĕ⁠ʻéyney⁠ká֩ ẇ⁠bĕ⁠ʼázĕne֨y⁠ká şĕ̇̌má֜ʻ wĕ⁠şî֣ym libĕ̇⁠ká֗ lĕ⁠kò֤l ʼàşěr-ʼàniy֙ marĕʼe֣h ʼwòţá֔⁠kĕ ki֛̇y lĕma֥ʻan harĕʼwòţĕ⁠ká֖h hubá֣ʼţáh hé֑ná̇h hagé֛̇d ʼeţ-ká̇l-ʼàşěr-ʼaţá֥̇h ròʼe֖h lĕ⁠bé֥yţ yişĕ̂ráʼéֽl׃"],[40,5,"וְ⁠הִנֵּ֥ה חוֹמָ֛ה מִ⁠ח֥וּץ לַ⁠בַּ֖יִת סָבִ֣יב ׀ סָבִ֑יב וּ⁠בְ⁠יַ֨ד הָ⁠אִ֜ישׁ קְנֵ֣ה הַ⁠מִּדָּ֗ה שֵׁשׁ־אַמּ֤וֹת בָּֽ⁠אַמָּה֙ וָ⁠טֹ֔פַח וַ⁠יָּ֜מָד אֶת־רֹ֤חַב הַ⁠בִּנְיָן֙ קָנֶ֣ה אֶחָ֔ד וְ⁠קוֹמָ֖ה קָנֶ֥ה אֶחָֽד׃","wĕ⁠hiné֥̇h ẖwòmá֛h mi⁠ẖ֥ẇẕ la⁠bȧ֖yiţ sábi֣yb ׀ sábi֑yb ẇ⁠bĕ⁠ya֨d há⁠ʼi֜yş̌ qĕné֣h ha⁠mi̇dá̇֗h şé̌ş̌-ʼaṁ֤wòţ báֽ̇⁠ʼamá̇h֙ wá⁠tò֔paẖ wa⁠yá̇֜mád ʼeţ-rò֤ẖab ha⁠bi̇nĕyán֙ qáne֣h ʼeẖá֔d wĕ⁠qwòmá֖h qáne֥h ʼeẖáֽd׃"],[40,6,"וַ⁠יָּב֗וֹא אֶל־שַׁ֨עַר֙ אֲשֶׁ֤ר פָּנָי⁠ו֙ דֶּ֣רֶךְ הַ⁠קָּדִ֔ימָ⁠ה וַ⁠יַּ֖עַל ב⁠מעלות⁠ו וַ⁠יָּ֣מָד ׀ אֶת־סַ֣ף הַ⁠שַּׁ֗עַר קָנֶ֤ה אֶחָד֙ רֹ֔חַב וְ⁠אֵת֙ סַ֣ף אֶחָ֔ד קָנֶ֥ה אֶחָ֖ד רֹֽחַב׃","wa⁠yá̇b֗wòʼ ʼel-şǎ֨ʻar֙ ʼàşě֤r pá̇náy⁠w֙ dė֣rekĕ ha⁠qá̇di֔ymá⁠h wa⁠yȧ֖ʻal b⁠mʻlwţ⁠w wa⁠yá֣̇mád ׀ ʼeţ-sa֣p ha⁠şȧ̌֗ʻar qáne֤h ʼeẖád֙ rò֔ẖab wĕ⁠ʼéţ֙ sa֣p ʼeẖá֔d qáne֥h ʼeẖá֖d ròֽẖab׃"],[40,7,"וְ⁠הַ⁠תָּ֗א קָנֶ֨ה אֶחָ֥ד אֹ֨רֶךְ֙ וְ⁠קָנֶ֤ה אֶחָד֙ רֹ֔חַב וּ⁠בֵ֥ין הַ⁠תָּאִ֖ים חָמֵ֣שׁ אַמּ֑וֹת וְ⁠סַ֣ף הַ֠⁠שַּׁעַר מֵ⁠אֵ֨צֶל אוּלָ֥ם הַ⁠שַּׁ֛עַר מֵֽ⁠הַ⁠בַּ֖יִת קָנֶ֥ה אֶחָֽד׃","wĕ⁠ha⁠ţá̇֗ʼ qáne֨h ʼeẖá֥d ʼò֨rekĕ֙ wĕ⁠qáne֤h ʼeẖád֙ rò֔ẖab ẇ⁠bé֥yn ha⁠ţá̇ʼi֖ym ẖámé֣ş̌ ʼaṁ֑wòţ wĕ⁠sa֣p ha֠⁠şȧ̌ʻar mé⁠ʼé֨ẕel ʼẇlá֥m ha⁠şȧ֛̌ʻar méֽ⁠ha⁠bȧ֖yiţ qáne֥h ʼeẖáֽd׃"],[40,8,"וַ⁠יָּ֜מָד אֶת־אֻלָ֥ם הַ⁠שַּׁ֛עַר מֵ⁠הַ⁠בַּ֖יִת קָנֶ֥ה אֶחָֽד׃","wa⁠yá̇֜mád ʼeţ-ʼulá֥m ha⁠şȧ֛̌ʻar mé⁠ha⁠bȧ֖yiţ qáne֥h ʼeẖáֽd׃"],[40,9,"וַ⁠יָּ֜מָד אֶת־אֻלָ֤ם הַ⁠שַּׁ֨עַר֙ שְׁמֹנֶ֣ה אַמּ֔וֹת ו⁠איל⁠ו שְׁתַּ֣יִם אַמּ֑וֹת וְ⁠אֻלָ֥ם הַ⁠שַּׁ֖עַר מֵ⁠הַ⁠בָּֽיִת׃","wa⁠yá̇֜mád ʼeţ-ʼulá֤m ha⁠şȧ̌֨ʻar֙ şĕ̌mòne֣h ʼaṁ֔wòţ w⁠ʼyl⁠w şĕ̌ţȧ֣yim ʼaṁ֑wòţ wĕ⁠ʼulá֥m ha⁠şȧ֖̌ʻar mé⁠ha⁠báֽ̇yiţ׃"],[40,10,"וְ⁠תָאֵ֨י הַ⁠שַּׁ֜עַר דֶּ֣רֶךְ הַ⁠קָּדִ֗ים שְׁלֹשָׁ֤ה מִ⁠פֹּה֙ וּ⁠שְׁלֹשָׁ֣ה מִ⁠פֹּ֔ה מִדָּ֥ה אַחַ֖ת לִ⁠שְׁלָשְׁתָּ֑⁠ם וּ⁠מִדָּ֥ה אַחַ֛ת לָ⁠אֵילִ֖ם מִ⁠פֹּ֥ה וּ⁠מִ⁠פּֽוֹ׃","wĕ⁠ţáʼé֨y ha⁠şȧ̌֜ʻar dė֣rekĕ ha⁠qá̇di֗ym şĕ̌lòşá֤̌h mi⁠pò̇h֙ ẇ⁠şĕ̌lòşá֣̌h mi⁠pò̇֔h midá֥̇h ʼaẖa֖ţ li⁠şĕ̌láşĕ̌ţá֑̇⁠m ẇ⁠midá֥̇h ʼaẖa֛ţ lá⁠ʼéyli֖m mi⁠pò֥̇h ẇ⁠mi⁠ṗֽwò׃"],[40,11,"וַ⁠יָּ֛מָד אֶת־רֹ֥חַב פֶּֽתַח־הַ⁠שַּׁ֖עַר עֶ֣שֶׂר אַמּ֑וֹת אֹ֣רֶךְ הַ⁠שַּׁ֔עַר שְׁל֥וֹשׁ עֶשְׂרֵ֖ה אַמּֽוֹת׃","wa⁠yá֛̇mád ʼeţ-rò֥ẖab pėֽţaẖ-ha⁠şȧ֖̌ʻar ʻe֣şêr ʼaṁ֑wòţ ʼò֣rekĕ ha⁠şȧ̌֔ʻar şĕ̌l֥wòş̌ ʻeşĕ̂ré֖h ʼaṁֽwòţ׃"],[40,12,"וּ⁠גְב֞וּל לִ⁠פְנֵ֤י הַ⁠תָּאוֹת֙ אַמָּ֣ה אֶחָ֔ת וְ⁠אַמָּה־אַחַ֥ת גְּב֖וּל מִ⁠פֹּ֑ה וְ⁠הַ⁠תָּ֕א שֵׁשׁ־אַמּ֣וֹת מִ⁠פּ֔וֹ וְ⁠שֵׁ֥שׁ אַמּ֖וֹת מִ⁠פּֽוֹ׃","ẇ⁠gĕb֞ẇl li⁠pĕné֤y ha⁠ţá̇ʼwòţ֙ ʼamá֣̇h ʼeẖá֔ţ wĕ⁠ʼamá̇h-ʼaẖa֥ţ gĕ̇b֖ẇl mi⁠pò֑̇h wĕ⁠ha⁠ţá̇֕ʼ şé̌ş̌-ʼaṁ֣wòţ mi⁠ṗ֔wò wĕ⁠şé֥̌ş̌ ʼaṁ֖wòţ mi⁠ṗֽwò׃"],[40,13,"וַ⁠יָּ֣מָד אֶת־הַ⁠שַּׁ֗עַר מִ⁠גַּ֤ג הַ⁠תָּא֙ לְ⁠גַגּ֔⁠וֹ רֹ֕חַב עֶשְׂרִ֥ים וְ⁠חָמֵ֖שׁ אַמּ֑וֹת פֶּ֖תַח נֶ֥גֶד פָּֽתַח׃","wa⁠yá֣̇mád ʼeţ-ha⁠şȧ̌֗ʻar mi⁠gȧ֤g ha⁠ţá̇ʼ֙ lĕ⁠gaġ֔⁠wò rò֕ẖab ʻeşĕ̂ri֥ym wĕ⁠ẖámé֖ş̌ ʼaṁ֑wòţ pė֖ţaẖ ne֥ged páֽ̇ţaẖ׃"],[40,14,"וַ⁠יַּ֥עַשׂ אֶת־אֵילִ֖ים שִׁשִּׁ֣ים אַמָּ֑ה וְ⁠אֶל־אֵיל֙ הֶֽ⁠חָצֵ֔ר הַ⁠שַּׁ֖עַר סָבִ֥יב ׀ סָבִֽיב׃","wa⁠yȧ֥ʻaş̂ ʼeţ-ʼéyli֖ym şǐşi֣̇̌ym ʼamá֑̇h wĕ⁠ʼel-ʼéyl֙ heֽ⁠ẖáẕé֔r ha⁠şȧ֖̌ʻar sábi֥yb ׀ sábiֽyb׃"],[40,15,"וְ⁠עַ֗ל פְּנֵי֙ הַ⁠שַּׁ֣עַר ה⁠יאתון עַל־לִ⁠פְנֵ֕י אֻלָ֥ם הַ⁠שַּׁ֖עַר הַ⁠פְּנִימִ֑י חֲמִשִּׁ֖ים אַמָּֽה׃","wĕ⁠ʻa֗l pĕ̇néy֙ ha⁠şȧ֣̌ʻar h⁠yʼţwn ʻal-li⁠pĕné֕y ʼulá֥m ha⁠şȧ֖̌ʻar ha⁠pĕ̇niymi֑y ẖàmişi֖̇̌ym ʼamáֽ̇h׃"],[40,16,"וְ⁠חַלֹּנ֣וֹת אֲטֻמ֣וֹת אֶֽל־הַ⁠תָּאִ֡ים וְ⁠אֶל֩ אֵלֵי⁠הֵ֨מָה לִ⁠פְנִ֤ימָה לַ⁠שַּׁ֨עַר֙ סָבִ֣יב ׀ סָבִ֔יב וְ⁠כֵ֖ן לָ⁠אֵֽלַמּ֑וֹת וְ⁠חַלּוֹנ֞וֹת סָבִ֤יב ׀ סָבִיב֙ לִ⁠פְנִ֔ימָה וְ⁠אֶל־אַ֖יִל תִּמֹרִֽים׃","wĕ⁠ẖalò̇n֣wòţ ʼàtum֣wòţ ʼeֽl-ha⁠ţá̇ʼi֡ym wĕ⁠ʼel֩ ʼéléy⁠hé֨máh li⁠pĕni֤ymáh la⁠şȧ̌֨ʻar֙ sábi֣yb ׀ sábi֔yb wĕ⁠ké֖n lá⁠ʼéֽlaṁ֑wòţ wĕ⁠ẖal̇wòn֞wòţ sábi֤yb ׀ sábiyb֙ li⁠pĕni֔ymáh wĕ⁠ʼel-ʼa֖yil ţi̇mòriֽym׃"],[40,17,"וַ⁠יְבִיאֵ֗⁠נִי אֶל־הֶֽ⁠חָצֵר֙ הַ⁠חִ֣יצוֹנָ֔ה וְ⁠הִנֵּ֤ה לְשָׁכוֹת֙ וְ⁠רִֽצְפָ֔ה עָשׂ֥וּי לֶ⁠חָצֵ֖ר סָבִ֣יב ׀ סָבִ֑יב שְׁלֹשִׁ֥ים לְשָׁכ֖וֹת אֶל־הָ⁠רִֽצְפָֽה׃","wa⁠yĕbiyʼé֗⁠niy ʼel-heֽ⁠ẖáẕér֙ ha⁠ẖi֣yẕwòná֔h wĕ⁠hiné֤̇h lĕşá̌kwòţ֙ wĕ⁠riֽẕĕpá֔h ʻáş֥̂ẇy le⁠ẖáẕé֖r sábi֣yb ׀ sábi֑yb şĕ̌lòşǐ֥ym lĕşá̌k֖wòţ ʼel-há⁠riֽẕĕpáֽh׃"],[40,18,"וְ⁠הָ⁠רִֽצְפָה֙ אֶל־כֶּ֣תֶף הַ⁠שְּׁעָרִ֔ים לְ⁠עֻמַּ֖ת אֹ֣רֶךְ הַ⁠שְּׁעָרִ֑ים הָ⁠רִֽצְפָ֖ה הַ⁠תַּחְתּוֹנָֽה׃","wĕ⁠há⁠riֽẕĕpáh֙ ʼel-kė֣ţep ha⁠şĕ̇̌ʻári֔ym lĕ⁠ʻumȧ֖ţ ʼò֣rekĕ ha⁠şĕ̇̌ʻári֑ym há⁠riֽẕĕpá֖h ha⁠ţȧẖĕţ̇wònáֽh׃"],[40,19,"וַ⁠יָּ֣מָד רֹ֡חַב מִ⁠לִּ⁠פְנֵי֩ הַ⁠שַּׁ֨עַר הַ⁠תַּחְתּ֜וֹנָ⁠ה לִ⁠פְנֵ֨י הֶ⁠חָצֵ֧ר הַ⁠פְּנִימִ֛י מִ⁠ח֖וּץ מֵאָ֣ה אַמָּ֑ה הַ⁠קָּדִ֖ים וְ⁠הַ⁠צָּפֽוֹן׃","wa⁠yá֣̇mád rò֡ẖab mi⁠li̇⁠pĕnéy֩ ha⁠şȧ̌֨ʻar ha⁠ţȧẖĕţ̇֜wòná⁠h li⁠pĕné֨y he⁠ẖáẕé֧r ha⁠pĕ̇niymi֛y mi⁠ẖ֖ẇẕ méʼá֣h ʼamá֑̇h ha⁠qá̇di֖ym wĕ⁠ha⁠ẕá̇pֽwòn׃"],[40,20,"וְ⁠הַ⁠שַּׁ֗עַר אֲשֶׁ֤ר פָּנָי⁠ו֙ דֶּ֣רֶךְ הַ⁠צָּפ֔וֹן לֶ⁠חָצֵ֖ר הַ⁠חִֽיצוֹנָ֑ה מָדַ֥ד אָרְכּ֖⁠וֹ וְ⁠רָחְבּֽ⁠וֹ׃","wĕ⁠ha⁠şȧ̌֗ʻar ʼàşě֤r pá̇náy⁠w֙ dė֣rekĕ ha⁠ẕá̇p֔wòn le⁠ẖáẕé֖r ha⁠ẖiֽyẕwòná֑h máda֥d ʼárĕk֖̇⁠wò wĕ⁠ráẖĕḃֽ⁠wò׃"],[40,21,"ו⁠תא⁠ו שְׁלוֹשָׁ֤ה מִ⁠פּוֹ֙ וּ⁠שְׁלֹשָׁ֣ה מִ⁠פּ֔וֹ ו⁠איל⁠ו ו⁠אלמ⁠ו הָיָ֔ה כְּ⁠מִדַּ֖ת הַ⁠שַּׁ֣עַר הָ⁠רִאשׁ֑וֹן חֲמִשִּׁ֤ים אַמָּה֙ אָרְכּ֔⁠וֹ וְ⁠רֹ֕חַב חָמֵ֥שׁ וְ⁠עֶשְׂרִ֖ים בָּ⁠אַמָּֽה׃","w⁠ţʼ⁠w şĕ̌lwòşá֤̌h mi⁠ṗwò֙ ẇ⁠şĕ̌lòşá֣̌h mi⁠ṗ֔wò w⁠ʼyl⁠w w⁠ʼlm⁠w háyá֔h kĕ̇⁠midȧ֖ţ ha⁠şȧ֣̌ʻar há⁠riʼş֑̌wòn ẖàmişi֤̇̌ym ʼamá̇h֙ ʼárĕk̇֔⁠wò wĕ⁠rò֕ẖab ẖámé֥ş̌ wĕ⁠ʻeşĕ̂ri֖ym bá̇⁠ʼamáֽ̇h׃"],[40,22,"ו⁠חלונ⁠ו ו⁠אלמ⁠ו ו⁠תמר⁠ו כְּ⁠מִדַּ֣ת הַ⁠שַּׁ֔עַר אֲשֶׁ֥ר פָּנָ֖י⁠ו דֶּ֣רֶךְ הַ⁠קָּדִ֑ים וּ⁠בְ⁠מַעֲל֥וֹת שֶׁ֨בַע֙ יַֽעֲלוּ־ב֔⁠וֹ ו⁠אילמ⁠ו לִ⁠פְנֵי⁠הֶֽם׃","w⁠ẖlwn⁠w w⁠ʼlm⁠w w⁠ţmr⁠w kĕ̇⁠midȧ֣ţ ha⁠şȧ̌֔ʻar ʼàşě֥r pá̇ná֖y⁠w dė֣rekĕ ha⁠qá̇di֑ym ẇ⁠bĕ⁠maʻàl֥wòţ şě֨baʻ֙ yaֽʻàlẇ-b֔⁠wò w⁠ʼylm⁠w li⁠pĕnéy⁠heֽm׃"],[40,23,"וְ⁠שַׁ֨עַר֙ לֶ⁠חָצֵ֣ר הַ⁠פְּנִימִ֔י נֶ֣גֶד הַ⁠שַּׁ֔עַר לַ⁠צָּפ֖וֹן וְ⁠לַ⁠קָּדִ֑ים וַ⁠יָּ֧מָד מִ⁠שַּׁ֛עַר אֶל־שַׁ֖עַר מֵאָ֥ה אַמָּֽה׃","wĕ⁠şǎ֨ʻar֙ le⁠ẖáẕé֣r ha⁠pĕ̇niymi֔y ne֣ged ha⁠şȧ̌֔ʻar la⁠ẕá̇p֖wòn wĕ⁠la⁠qá̇di֑ym wa⁠yá֧̇mád mi⁠şȧ֛̌ʻar ʼel-şǎ֖ʻar méʼá֥h ʼamáֽ̇h׃"],[40,24,"וַ⁠יּוֹלִכֵ֨⁠נִי֙ דֶּ֣רֶךְ הַ⁠דָּר֔וֹם וְ⁠הִנֵּה־שַׁ֖עַר דֶּ֣רֶךְ הַ⁠דָּר֑וֹם וּ⁠מָדַ֤ד איל⁠ו ו⁠אילמ⁠ו כַּ⁠מִּדּ֖וֹת הָ⁠אֵֽלֶּה׃","wa⁠ẏwòliké֨⁠niy֙ dė֣rekĕ ha⁠dá̇r֔wòm wĕ⁠hiné̇h-şǎ֖ʻar dė֣rekĕ ha⁠dá̇r֑wòm ẇ⁠máda֤d ʼyl⁠w w⁠ʼylm⁠w kȧ⁠mi̇ḋ֖wòţ há⁠ʼéֽlėh׃"],[40,25,"וְ⁠חַלּוֹנִ֨ים ל֤⁠וֹ ו⁠ל⁠אילמ⁠ו סָבִ֣יב ׀ סָבִ֔יב כְּ⁠הַ⁠חֲלֹּנ֖וֹת הָ⁠אֵ֑לֶּה חֲמִשִּׁ֤ים אַמָּה֙ אֹ֔רֶךְ וְ⁠רֹ֕חַב חָמֵ֥שׁ וְ⁠עֶשְׂרִ֖ים אַמָּֽה׃","wĕ⁠ẖal̇wòni֨ym l֤⁠wò w⁠l⁠ʼylm⁠w sábi֣yb ׀ sábi֔yb kĕ̇⁠ha⁠ẖàlò̇n֖wòţ há⁠ʼé֑lėh ẖàmişi֤̇̌ym ʼamá̇h֙ ʼò֔rekĕ wĕ⁠rò֕ẖab ẖámé֥ş̌ wĕ⁠ʻeşĕ̂ri֖ym ʼamáֽ̇h׃"],[40,26,"וּ⁠מַעֲל֤וֹת שִׁבְעָה֙ עלות⁠ו ו⁠אלמ⁠ו לִ⁠פְנֵי⁠הֶ֑ם וְ⁠תִמֹרִ֣ים ל֗⁠וֹ אֶחָ֥ד מִ⁠פּ֛וֹ וְ⁠אֶחָ֥ד מִ⁠פּ֖וֹ אֶל־איל⁠ו׃","ẇ⁠maʻàl֤wòţ şǐbĕʻáh֙ ʻlwţ⁠w w⁠ʼlm⁠w li⁠pĕnéy⁠he֑m wĕ⁠ţimòri֣ym l֗⁠wò ʼeẖá֥d mi⁠ṗ֛wò wĕ⁠ʼeẖá֥d mi⁠ṗ֖wò ʼel-ʼyl⁠w׃"],[40,27,"וְ⁠שַׁ֛עַר לֶ⁠חָצֵ֥ר הַ⁠פְּנִימִ֖י דֶּ֣רֶךְ הַ⁠דָּר֑וֹם וַ⁠יָּ֨מָד מִ⁠שַּׁ֧עַר אֶל־הַ⁠שַּׁ֛עַר דֶּ֥רֶךְ הַ⁠דָּר֖וֹם מֵאָ֥ה אַמּֽוֹת׃","wĕ⁠şǎ֛ʻar le⁠ẖáẕé֥r ha⁠pĕ̇niymi֖y dė֣rekĕ ha⁠dá̇r֑wòm wa⁠yá̇֨mád mi⁠şȧ֧̌ʻar ʼel-ha⁠şȧ֛̌ʻar dė֥rekĕ ha⁠dá̇r֖wòm méʼá֥h ʼaṁֽwòţ׃"],[40,28,"וַ⁠יְבִיאֵ֛⁠נִי אֶל־חָצֵ֥ר הַ⁠פְּנִימִ֖י בְּ⁠שַׁ֣עַר הַ⁠דָּר֑וֹם וַ⁠יָּ֨מָד֙ אֶת־הַ⁠שַּׁ֣עַר הַ⁠דָּר֔וֹם כַּ⁠מִּדּ֖וֹת הָ⁠אֵֽלֶּה׃","wa⁠yĕbiyʼé֛⁠niy ʼel-ẖáẕé֥r ha⁠pĕ̇niymi֖y bĕ̇⁠şǎ֣ʻar ha⁠dá̇r֑wòm wa⁠yá̇֨mád֙ ʼeţ-ha⁠şȧ֣̌ʻar ha⁠dá̇r֔wòm kȧ⁠mi̇ḋ֖wòţ há⁠ʼéֽlėh׃"],[40,29,"ו⁠תא⁠ו ו⁠איל⁠ו ו⁠אלמ⁠ו כַּ⁠מִּדּ֣וֹת הָ⁠אֵ֔לֶּה וְ⁠חַלּוֹנ֥וֹת ל֛⁠וֹ ו⁠ל⁠אלמ⁠ו סָבִ֣יב ׀ סָבִ֑יב חֲמִשִּׁ֤ים אַמָּה֙ אֹ֔רֶךְ וְ⁠רֹ֕חַב עֶשְׂרִ֥ים וְ⁠חָמֵ֖שׁ אַמּֽוֹת׃","w⁠ţʼ⁠w w⁠ʼyl⁠w w⁠ʼlm⁠w kȧ⁠mi̇ḋ֣wòţ há⁠ʼé֔lėh wĕ⁠ẖal̇wòn֥wòţ l֛⁠wò w⁠l⁠ʼlm⁠w sábi֣yb ׀ sábi֑yb ẖàmişi֤̇̌ym ʼamá̇h֙ ʼò֔rekĕ wĕ⁠rò֕ẖab ʻeşĕ̂ri֥ym wĕ⁠ẖámé֖ş̌ ʼaṁֽwòţ׃"],[40,30,"וְ⁠אֵֽלַמּ֖וֹת סָבִ֣יב ׀ סָבִ֑יב אֹ֗רֶךְ חָמֵ֤שׁ וְ⁠עֶשְׂרִים֙ אַמָּ֔ה וְ⁠רֹ֖חַב חָמֵ֥שׁ אַמּֽוֹת׃","wĕ⁠ʼéֽlaṁ֖wòţ sábi֣yb ׀ sábi֑yb ʼò֗rekĕ ẖámé֤ş̌ wĕ⁠ʻeşĕ̂riym֙ ʼamá̇֔h wĕ⁠rò֖ẖab ẖámé֥ş̌ ʼaṁֽwòţ׃"],[40,31,"ואלמו אֶל־חָצֵר֙ הַ⁠חִ֣צוֹנָ֔ה וְ⁠תִמֹרִ֖ים אֶל־איל⁠ו וּ⁠מַעֲל֥וֹת שְׁמוֹנֶ֖ה מעל⁠ו׃","wʼlmw ʼel-ẖáẕér֙ ha⁠ẖi֣ẕwòná֔h wĕ⁠ţimòri֖ym ʼel-ʼyl⁠w ẇ⁠maʻàl֥wòţ şĕ̌mwòne֖h mʻl⁠w׃"],[40,32,"וַ⁠יְבִיאֵ֛⁠נִי אֶל־הֶ⁠חָצֵ֥ר הַ⁠פְּנִימִ֖י דֶּ֣רֶךְ הַ⁠קָּדִ֑ים וַ⁠יָּ֣מָד אֶת־הַ⁠שַּׁ֔עַר כַּ⁠מִּדּ֖וֹת הָ⁠אֵֽלֶּה׃","wa⁠yĕbiyʼé֛⁠niy ʼel-he⁠ẖáẕé֥r ha⁠pĕ̇niymi֖y dė֣rekĕ ha⁠qá̇di֑ym wa⁠yá֣̇mád ʼeţ-ha⁠şȧ̌֔ʻar kȧ⁠mi̇ḋ֖wòţ há⁠ʼéֽlėh׃"],[40,33,"ו⁠תא⁠ו ואלו ו⁠אלמ⁠ו כַּ⁠מִּדּ֣וֹת הָ⁠אֵ֔לֶּה וְ⁠חַלּוֹנ֥וֹת ל֛⁠וֹ ו⁠ל⁠אלמ⁠ו סָבִ֣יב ׀ סָבִ֑יב אֹ֚רֶךְ חֲמִשִּׁ֣ים אַמָּ֔ה וְ⁠רֹ֕חַב חָמֵ֥שׁ וְ⁠עֶשְׂרִ֖ים אַמָּֽה׃","w⁠ţʼ⁠w wʼlw w⁠ʼlm⁠w kȧ⁠mi̇ḋ֣wòţ há⁠ʼé֔lėh wĕ⁠ẖal̇wòn֥wòţ l֛⁠wò w⁠l⁠ʼlm⁠w sábi֣yb ׀ sábi֑yb ʼò֚rekĕ ẖàmişi֣̇̌ym ʼamá̇֔h wĕ⁠rò֕ẖab ẖámé֥ş̌ wĕ⁠ʻeşĕ̂ri֖ym ʼamáֽ̇h׃"],[40,34,"ו⁠אלמ⁠ו לֶֽ⁠חָצֵר֙ הַ⁠חִ֣יצוֹנָ֔ה וְ⁠תִמֹרִ֥ים אֶל־אל⁠ו מִ⁠פּ֣וֹ וּ⁠מִ⁠פּ֑וֹ וּ⁠שְׁמֹנֶ֥ה מַעֲל֖וֹת מעל⁠ו׃","w⁠ʼlm⁠w leֽ⁠ẖáẕér֙ ha⁠ẖi֣yẕwòná֔h wĕ⁠ţimòri֥ym ʼel-ʼl⁠w mi⁠ṗ֣wò ẇ⁠mi⁠ṗ֑wò ẇ⁠şĕ̌mòne֥h maʻàl֖wòţ mʻl⁠w׃"],[40,35,"וַ⁠יְבִיאֵ֖⁠נִי אֶל־שַׁ֣עַר הַ⁠צָּפ֑וֹן וּ⁠מָדַ֖ד כַּ⁠מִּדּ֥וֹת הָ⁠אֵֽלֶּה׃","wa⁠yĕbiyʼé֖⁠niy ʼel-şǎ֣ʻar ha⁠ẕá̇p֑wòn ẇ⁠máda֖d kȧ⁠mi̇ḋ֥wòţ há⁠ʼéֽlėh׃"],[40,36,"תא⁠ו אל⁠ו ו⁠אלמ⁠ו וְ⁠חַלּוֹנ֥וֹת ל֖⁠וֹ סָבִ֣יב ׀ סָבִ֑יב אֹ֚רֶךְ חֲמִשִּׁ֣ים אַמָּ֔ה וְ⁠רֹ֕חַב חָמֵ֥שׁ וְ⁠עֶשְׂרִ֖ים אַמָּֽה׃","ţʼ⁠w ʼl⁠w w⁠ʼlm⁠w wĕ⁠ẖal̇wòn֥wòţ l֖⁠wò sábi֣yb ׀ sábi֑yb ʼò֚rekĕ ẖàmişi֣̇̌ym ʼamá̇֔h wĕ⁠rò֕ẖab ẖámé֥ş̌ wĕ⁠ʻeşĕ̂ri֖ym ʼamáֽ̇h׃"],[40,37,"ו⁠איל⁠ו לֶֽ⁠חָצֵר֙ הַ⁠חִ֣יצוֹנָ֔ה וְ⁠תִמֹרִ֥ים אֶל־איל⁠ו מִ⁠פּ֣וֹ וּ⁠מִ⁠פּ֑וֹ וּ⁠שְׁמֹנֶ֥ה מַעֲל֖וֹת מעל⁠ו׃","w⁠ʼyl⁠w leֽ⁠ẖáẕér֙ ha⁠ẖi֣yẕwòná֔h wĕ⁠ţimòri֥ym ʼel-ʼyl⁠w mi⁠ṗ֣wò ẇ⁠mi⁠ṗ֑wò ẇ⁠şĕ̌mòne֥h maʻàl֖wòţ mʻl⁠w׃"],[40,38,"וְ⁠לִשְׁכָּ֣ה וּ⁠פִתְחָ֔⁠הּ בְּ⁠אֵילִ֖ים הַ⁠שְּׁעָרִ֑ים שָׁ֖ם יָדִ֥יחוּ אֶת־הָ⁠עֹלָֽה׃","wĕ⁠lişĕ̌ká֣̇h ẇ⁠piţĕẖá֔⁠ḣ bĕ̇⁠ʼéyli֖ym ha⁠şĕ̇̌ʻári֑ym şá֖̌m yádi֥yẖẇ ʼeţ-há⁠ʻòláֽh׃"],[40,39,"וּ⁠בְ⁠אֻלָ֣ם הַ⁠שַּׁ֗עַר שְׁנַ֤יִם שֻׁלְחָנוֹת֙ מִ⁠פּ֔וֹ וּ⁠שְׁנַ֥יִם שֻׁלְחָנ֖וֹת מִ⁠פֹּ֑ה לִ⁠שְׁח֤וֹט אֲלֵי⁠הֶם֙ הָ⁠עוֹלָ֔ה וְ⁠הַ⁠חַטָּ֖את וְ⁠הָ⁠אָשָֽׁם׃","ẇ⁠bĕ⁠ʼulá֣m ha⁠şȧ̌֗ʻar şĕ̌na֤yim şǔlĕẖánwòţ֙ mi⁠ṗ֔wò ẇ⁠şĕ̌na֥yim şǔlĕẖán֖wòţ mi⁠pò֑̇h li⁠şĕ̌ẖ֤wòt ʼàléy⁠hem֙ há⁠ʻwòlá֔h wĕ⁠ha⁠ẖatá֖̇ʼţ wĕ⁠há⁠ʼáşáֽ̌m׃"],[40,40,"וְ⁠אֶל־הַ⁠כָּתֵ֣ף מִ⁠ח֗וּצָ⁠ה לָ⁠עוֹלֶה֙ לְ⁠פֶ֨תַח֙ הַ⁠שַּׁ֣עַר הַ⁠צָּפ֔וֹנָ⁠ה שְׁנַ֖יִם שֻׁלְחָנ֑וֹת וְ⁠אֶל־הַ⁠כָּתֵ֣ף הָ⁠אַחֶ֗רֶת אֲשֶׁר֙ לְ⁠אֻלָ֣ם הַ⁠שַּׁ֔עַר שְׁנַ֖יִם שֻׁלְחָנֽוֹת׃","wĕ⁠ʼel-ha⁠ká̇ţé֣p mi⁠ẖ֗ẇẕá⁠h lá⁠ʻwòleh֙ lĕ⁠pe֨ţaẖ֙ ha⁠şȧ֣̌ʻar ha⁠ẕá̇p֔wòná⁠h şĕ̌na֖yim şǔlĕẖán֑wòţ wĕ⁠ʼel-ha⁠ká̇ţé֣p há⁠ʼaẖe֗reţ ʼàşěr֙ lĕ⁠ʼulá֣m ha⁠şȧ̌֔ʻar şĕ̌na֖yim şǔlĕẖánֽwòţ׃"],[40,41,"אַרְבָּעָ֨ה שֻׁלְחָנ֜וֹת מִ⁠פֹּ֗ה וְ⁠אַרְבָּעָ֧ה שֻׁלְחָנ֛וֹת מִ⁠פֹּ֖ה לְ⁠כֶ֣תֶף הַ⁠שָּׁ֑עַר שְׁמוֹנָ֥ה שֻׁלְחָנ֖וֹת אֲלֵי⁠הֶ֥ם יִשְׁחָֽטוּ׃","ʼarĕbá̇ʻá֨h şǔlĕẖán֜wòţ mi⁠pò̇֗h wĕ⁠ʼarĕbá̇ʻá֧h şǔlĕẖán֛wòţ mi⁠pò֖̇h lĕ⁠ke֣ţep ha⁠şá֑̇̌ʻar şĕ̌mwòná֥h şǔlĕẖán֖wòţ ʼàléy⁠he֥m yişĕ̌ẖáֽtẇ׃"],[40,42,"וְ⁠אַרְבָּעָה֩ שֻׁלְחָנ֨וֹת לָ⁠עוֹלָ֜ה אַבְנֵ֣י גָזִ֗ית אֹרֶךְ֩ אַמָּ֨ה אַחַ֤ת וָ⁠חֵ֨צִי֙ וְ⁠רֹ֨חַב אַמָּ֤ה אַחַת֙ וָ⁠חֵ֔צִי וְ⁠גֹ֖בַהּ אַמָּ֣ה אֶחָ֑ת אֲלֵי⁠הֶ֗ם וְ⁠יַנִּ֤יחוּ אֶת־הַ⁠כֵּלִים֙ אֲשֶׁ֨ר יִשְׁחֲט֧וּ אֶת־הָ⁠עוֹלָ֛ה בָּ֖⁠ם וְ⁠הַ⁠זָּֽבַח׃","wĕ⁠ʼarĕbá̇ʻáh֩ şǔlĕẖán֨wòţ lá⁠ʻwòlá֜h ʼabĕné֣y gázi֗yţ ʼòrekĕ֩ ʼamá̇֨h ʼaẖa֤ţ wá⁠ẖé֨ẕiy֙ wĕ⁠rò֨ẖab ʼamá֤̇h ʼaẖaţ֙ wá⁠ẖé֔ẕiy wĕ⁠gò֖baḣ ʼamá֣̇h ʼeẖá֑ţ ʼàléy⁠he֗m wĕ⁠yani֤̇yẖẇ ʼeţ-ha⁠ké̇liym֙ ʼàşě֨r yişĕ̌ẖàt֧ẇ ʼeţ-há⁠ʻwòlá֛h bá֖̇⁠m wĕ⁠ha⁠záֽ̇baẖ׃"],[40,43,"וְ⁠הַֽ⁠שְׁפַתַּ֗יִם טֹ֧פַח אֶחָ֛ד מוּכָנִ֥ים בַּ⁠בַּ֖יִת סָבִ֣יב ׀ סָבִ֑יב וְ⁠אֶל־הַ⁠שֻּׁלְחָנ֖וֹת בְּשַׂ֥ר הַ⁠קָּרְבָֽן׃","wĕ⁠haֽ⁠şĕ̌paţȧ֗yim tò֧paẖ ʼeẖá֛d mẇkáni֥ym bȧ⁠bȧ֖yiţ sábi֣yb ׀ sábi֑yb wĕ⁠ʼel-ha⁠şu̇̌lĕẖán֖wòţ bĕ̇şâ֥r ha⁠qá̇rĕbáֽn׃"],[40,44,"וּ⁠מִ⁠חוּצָ⁠ה֩ לַ⁠שַּׁ֨עַר הַ⁠פְּנִימִ֜י לִֽשְׁכ֣וֹת שָׁרִ֗ים בֶּ⁠חָצֵ֤ר הַ⁠פְּנִימִי֙ אֲשֶׁ֗ר אֶל־כֶּ֨תֶף֙ שַׁ֣עַר הַ⁠צָּפ֔וֹן וּ⁠פְנֵי⁠הֶ֖ם דֶּ֣רֶךְ הַ⁠דָּר֑וֹם אֶחָ֗ד אֶל־כֶּ֨תֶף֙ שַׁ֣עַר הַ⁠קָּדִ֔ים פְּנֵ֖י דֶּ֥רֶךְ הַ⁠צָּפֹֽן׃","ẇ⁠mi⁠ẖẇẕá⁠h֩ la⁠şȧ̌֨ʻar ha⁠pĕ̇niymi֜y liֽşĕ̌k֣wòţ şá̌ri֗ym bė⁠ẖáẕé֤r ha⁠pĕ̇niymiy֙ ʼàşě֗r ʼel-kė֨ţep֙ şǎ֣ʻar ha⁠ẕá̇p֔wòn ẇ⁠pĕnéy⁠he֖m dė֣rekĕ ha⁠dá̇r֑wòm ʼeẖá֗d ʼel-kė֨ţep֙ şǎ֣ʻar ha⁠qá̇di֔ym pĕ̇né֖y dė֥rekĕ ha⁠ẕá̇pòֽn׃"],[40,45,"וַ⁠יְדַבֵּ֖ר אֵלָ֑⁠י זֹ֣ה הַ⁠לִּשְׁכָּ֗ה אֲשֶׁ֤ר פָּנֶ֨י⁠הָ֙ דֶּ֣רֶךְ הַ⁠דָּר֔וֹם לַ⁠כֹּ֣הֲנִ֔ים שֹׁמְרֵ֖י מִשְׁמֶ֥רֶת הַ⁠בָּֽיִת׃","wa⁠yĕdabé֖̇r ʼélá֑⁠y zò֣h ha⁠li̇şĕ̌ká̇֗h ʼàşě֤r pá̇ne֨y⁠há֙ dė֣rekĕ ha⁠dá̇r֔wòm la⁠kò֣̇hàni֔ym şò̌mĕré֖y mişĕ̌me֥reţ ha⁠báֽ̇yiţ׃"],[40,46,"וְ⁠הַ⁠לִּשְׁכָּ֗ה אֲשֶׁ֤ר פָּנֶ֨י⁠הָ֙ דֶּ֣רֶךְ הַ⁠צָּפ֔וֹן לַ⁠כֹּ֣הֲנִ֔ים שֹׁמְרֵ֖י מִשְׁמֶ֣רֶת הַ⁠מִּזְבֵּ֑חַ הֵ֣מָּה בְנֵֽי־צָד֗וֹק הַ⁠קְּרֵבִ֧ים מִ⁠בְּנֵֽי־לֵוִ֛י אֶל־יְהוָ֖ה לְ⁠שָׁרְתֽ⁠וֹ׃","wĕ⁠ha⁠li̇şĕ̌ká̇֗h ʼàşě֤r pá̇ne֨y⁠há֙ dė֣rekĕ ha⁠ẕá̇p֔wòn la⁠kò֣̇hàni֔ym şò̌mĕré֖y mişĕ̌me֣reţ ha⁠mi̇zĕbé֑̇ẖa hé֣má̇h bĕnéֽy-ẕád֗wòq ha⁠qĕ̇rébi֧ym mi⁠bĕ̇néֽy-léwi֛y ʼel-yĕhwá֖h lĕ⁠şá̌rĕţֽ⁠wò׃"],[40,47,"וַ⁠יָּ֨מָד אֶת־הֶ⁠חָצֵ֜ר אֹ֣רֶךְ ׀ מֵאָ֣ה אַמָּ֗ה וְ⁠רֹ֛חַב מֵאָ֥ה אַמָּ֖ה מְרֻבָּ֑עַת וְ⁠הַ⁠מִּזְבֵּ֖חַ לִ⁠פְנֵ֥י הַ⁠בָּֽיִת׃","wa⁠yá̇֨mád ʼeţ-he⁠ẖáẕé֜r ʼò֣rekĕ ׀ méʼá֣h ʼamá̇֗h wĕ⁠rò֛ẖab méʼá֥h ʼamá֖̇h mĕrubá֑̇ʻaţ wĕ⁠ha⁠mi̇zĕbé֖̇ẖa li⁠pĕné֥y ha⁠báֽ̇yiţ׃"],[40,48,"וַ⁠יְבִאֵ⁠נִי֮ אֶל־אֻלָ֣ם הַ⁠בַּיִת֒ וַ⁠יָּ֨מָד֙ אֵ֣ל אֻלָ֔ם חָמֵ֤שׁ אַמּוֹת֙ מִ⁠פֹּ֔ה וְ⁠חָמֵ֥שׁ אַמּ֖וֹת מִ⁠פֹּ֑ה וְ⁠רֹ֣חַב הַ⁠שַּׁ֔עַר שָׁלֹ֤שׁ אַמּוֹת֙ מִ⁠פּ֔וֹ וְ⁠שָׁלֹ֥שׁ אַמּ֖וֹת מִ⁠פּֽוֹ׃","wa⁠yĕbiʼé⁠niy֮ ʼel-ʼulá֣m ha⁠bȧyiţ֒ wa⁠yá̇֨mád֙ ʼé֣l ʼulá֔m ẖámé֤ş̌ ʼaṁwòţ֙ mi⁠pò̇֔h wĕ⁠ẖámé֥ş̌ ʼaṁ֖wòţ mi⁠pò֑̇h wĕ⁠rò֣ẖab ha⁠şȧ̌֔ʻar şá̌lò֤ş̌ ʼaṁwòţ֙ mi⁠ṗ֔wò wĕ⁠şá̌lò֥ş̌ ʼaṁ֖wòţ mi⁠ṗֽwò׃"],[40,49,"אֹ֣רֶךְ הָ⁠אֻלָ֞ם עֶשְׂרִ֣ים אַמָּ֗ה וְ⁠רֹ֨חַב֙ עַשְׁתֵּ֣י עֶשְׂרֵ֣ה אַמָּ֔ה וּ⁠בַֽ⁠מַּעֲל֔וֹת אֲשֶׁ֥ר יַעֲל֖וּ אֵלָ֑י⁠ו וְ⁠עַמֻּדִים֙ אֶל־הָ֣⁠אֵילִ֔ים אֶחָ֥ד מִ⁠פֹּ֖ה וְ⁠אֶחָ֥ד מִ⁠פֹּֽה׃","ʼò֣rekĕ há⁠ʼulá֞m ʻeşĕ̂ri֣ym ʼamá̇֗h wĕ⁠rò֨ẖab֙ ʻaşĕ̌ţé֣̇y ʻeşĕ̂ré֣h ʼamá̇֔h ẇ⁠baֽ⁠mȧʻàl֔wòţ ʼàşě֥r yaʻàl֖ẇ ʼélá֑y⁠w wĕ⁠ʻamu̇diym֙ ʼel-há֣⁠ʼéyli֔ym ʼeẖá֥d mi⁠pò֖̇h wĕ⁠ʼeẖá֥d mi⁠pòֽ̇h׃"],[41,1,"וַ⁠יְבִיאֵ֖⁠נִי אֶל־הַ⁠הֵיכָ֑ל וַ⁠יָּ֣מָד אֶת־הָ⁠אֵילִ֗ים שֵׁשׁ־אַמּ֨וֹת רֹ֧חַב־מִ⁠פּ֛וֹ וְ⁠שֵׁשׁ־אַמּֽוֹת־רֹ֥חַב מִ⁠פּ֖וֹ רֹ֥חַב הָ⁠אֹֽהֶל׃","wa⁠yĕbiyʼé֖⁠niy ʼel-ha⁠héyká֑l wa⁠yá֣̇mád ʼeţ-há⁠ʼéyli֗ym şé̌ş̌-ʼaṁ֨wòţ rò֧ẖab-mi⁠ṗ֛wò wĕ⁠şé̌ş̌-ʼaṁֽwòţ-rò֥ẖab mi⁠ṗ֖wò rò֥ẖab há⁠ʼòֽhel׃"],[41,2,"וְ⁠רֹ֣חַב הַ⁠פֶּתַח֮ עֶ֣שֶׂר אַמּוֹת֒ וְ⁠כִתְפ֣וֹת הַ⁠פֶּ֔תַח חָמֵ֤שׁ אַמּוֹת֙ מִ⁠פּ֔וֹ וְ⁠חָמֵ֥שׁ אַמּ֖וֹת מִ⁠פּ֑וֹ וַ⁠יָּ֤מָד אָרְכּ⁠וֹ֙ אַרְבָּעִ֣ים אַמָּ֔ה וְ⁠רֹ֖חַב עֶשְׂרִ֥ים אַמָּֽה׃","wĕ⁠rò֣ẖab ha⁠pėţaẖ֮ ʻe֣şêr ʼaṁwòţ֒ wĕ⁠kiţĕp֣wòţ ha⁠pė֔ţaẖ ẖámé֤ş̌ ʼaṁwòţ֙ mi⁠ṗ֔wò wĕ⁠ẖámé֥ş̌ ʼaṁ֖wòţ mi⁠ṗ֑wò wa⁠yá֤̇mád ʼárĕk̇⁠wò֙ ʼarĕbá̇ʻi֣ym ʼamá̇֔h wĕ⁠rò֖ẖab ʻeşĕ̂ri֥ym ʼamáֽ̇h׃"],[41,3,"וּ⁠בָ֣א לִ⁠פְנִ֔ימָה וַ⁠יָּ֥מָד אֵֽיל־הַ⁠פֶּ֖תַח שְׁתַּ֣יִם אַמּ֑וֹת וְ⁠הַ⁠פֶּ֨תַח֙ שֵׁ֣שׁ אַמּ֔וֹת וְ⁠רֹ֥חַב הַ⁠פֶּ֖תַח שֶׁ֥בַע אַמּֽוֹת׃","ẇ⁠bá֣ʼ li⁠pĕni֔ymáh wa⁠yá֥̇mád ʼéֽyl-ha⁠pė֖ţaẖ şĕ̌ţȧ֣yim ʼaṁ֑wòţ wĕ⁠ha⁠pė֨ţaẖ֙ şé֣̌ş̌ ʼaṁ֔wòţ wĕ⁠rò֥ẖab ha⁠pė֖ţaẖ şě֥baʻ ʼaṁֽwòţ׃"],[41,4,"וַ⁠יָּ֨מָד אֶת־אָרְכּ֜⁠וֹ עֶשְׂרִ֣ים אַמָּ֗ה וְ⁠רֹ֛חַב עֶשְׂרִ֥ים אַמָּ֖ה אֶל־פְּנֵ֣י הַֽ⁠הֵיכָ֑ל וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י זֶ֖ה קֹ֥דֶשׁ הַ⁠קֳּדָשִֽׁים׃","wa⁠yá̇֨mád ʼeţ-ʼárĕk̇֜⁠wò ʻeşĕ̂ri֣ym ʼamá̇֗h wĕ⁠rò֛ẖab ʻeşĕ̂ri֥ym ʼamá֖̇h ʼel-pĕ̇né֣y haֽ⁠héyká֑l wa⁠yò֣̇ʼmer ʼéla֔⁠y ze֖h qò֥deş̌ ha⁠qȯdáşǐֽym׃"],[41,5,"וַ⁠יָּ֥מָד קִֽיר־הַ⁠בַּ֖יִת שֵׁ֣שׁ אַמּ֑וֹת וְ⁠רֹ֣חַב הַ⁠צֵּלָע֩ אַרְבַּ֨ע אַמּ֜וֹת סָבִ֧יב ׀ סָבִ֛יב לַ⁠בַּ֖יִת סָבִֽיב׃","wa⁠yá֥̇mád qiֽyr-ha⁠bȧ֖yiţ şé֣̌ş̌ ʼaṁ֑wòţ wĕ⁠rò֣ẖab ha⁠ẕé̇láʻ֩ ʼarĕbȧ֨ʻ ʼaṁ֜wòţ sábi֧yb ׀ sábi֛yb la⁠bȧ֖yiţ sábiֽyb׃"],[41,6,"וְ⁠הַ⁠צְּלָעוֹת֩ צֵלָ֨ע אֶל־צֵלָ֜ע שָׁל֧וֹשׁ וּ⁠שְׁלֹשִׁ֣ים פְּעָמִ֗ים וּ֠⁠בָאוֹת בַּ⁠קִּ֨יר אֲשֶׁר־לַ⁠בַּ֧יִת לַ⁠צְּלָע֛וֹת סָבִ֥יב ׀ סָבִ֖יב לִ⁠הְי֣וֹת אֲחוּזִ֑ים וְ⁠לֹֽא־יִהְי֥וּ אֲחוּזִ֖ים בְּ⁠קִ֥יר הַ⁠בָּֽיִת׃","wĕ⁠ha⁠ẕĕ̇láʻwòţ֩ ẕélá֨ʻ ʼel-ẕélá֜ʻ şá̌l֧wòş̌ ẇ⁠şĕ̌lòşǐ֣ym pĕ̇ʻámi֗ym ẇ֠⁠báʼwòţ bȧ⁠qi̇֨yr ʼàşěr-la⁠bȧ֧yiţ la⁠ẕĕ̇láʻ֛wòţ sábi֥yb ׀ sábi֖yb li⁠hĕy֣wòţ ʼàẖẇzi֑ym wĕ⁠lòֽʼ-yihĕy֥ẇ ʼàẖẇzi֖ym bĕ̇⁠qi֥yr ha⁠báֽ̇yiţ׃"],[41,7,"וְֽ⁠רָחֲבָ֡ה וְֽ⁠נָסְבָה֩ לְ⁠מַ֨עְלָ⁠ה לְ⁠מַ֜עְלָ⁠ה לַ⁠צְּלָע֗וֹת כִּ֣י מֽוּסַב־הַ֠⁠בַּיִת לְ⁠מַ֨עְלָ⁠ה לְ⁠מַ֜עְלָ⁠ה סָבִ֤יב ׀ סָבִיב֙ לַ⁠בַּ֔יִת עַל־כֵּ֥ן רֹֽחַב־לַ⁠בַּ֖יִת לְ⁠מָ֑עְלָ⁠ה וְ⁠כֵ֧ן הַ⁠תַּחְתּוֹנָ֛ה יַעֲלֶ֥ה עַל־הָ⁠עֶלְיוֹנָ֖ה לַ⁠תִּיכוֹנָֽה׃","wĕֽ⁠ráẖàbá֡h wĕֽ⁠násĕbáh֩ lĕ⁠ma֨ʻĕlá⁠h lĕ⁠ma֜ʻĕlá⁠h la⁠ẕĕ̇láʻ֗wòţ ki֣̇y mֽẇsab-ha֠⁠bȧyiţ lĕ⁠ma֨ʻĕlá⁠h lĕ⁠ma֜ʻĕlá⁠h sábi֤yb ׀ sábiyb֙ la⁠bȧ֔yiţ ʻal-ké֥̇n ròֽẖab-la⁠bȧ֖yiţ lĕ⁠má֑ʻĕlá⁠h wĕ⁠ké֧n ha⁠ţȧẖĕţ̇wòná֛h yaʻàle֥h ʻal-há⁠ʻelĕywòná֖h la⁠ţi̇ykwònáֽh׃"],[41,8,"וְ⁠רָאִ֧יתִי לַ⁠בַּ֛יִת גֹּ֖בַהּ סָבִ֣יב ׀ סָבִ֑יב מיסדות הַ⁠צְּלָעוֹת֙ מְל֣וֹ הַ⁠קָּנֶ֔ה שֵׁ֥שׁ אַמּ֖וֹת אַצִּֽילָה׃","wĕ⁠ráʼi֧yţiy la⁠bȧ֛yiţ gò֖̇baḣ sábi֣yb ׀ sábi֑yb mysdwţ ha⁠ẕĕ̇láʻwòţ֙ mĕl֣wò ha⁠qá̇ne֔h şé֥̌ş̌ ʼaṁ֖wòţ ʼaẕiֽ̇yláh׃"],[41,9,"רֹ֣חַב הַ⁠קִּ֧יר אֲֽשֶׁר־לַ⁠צֵּלָ֛ע אֶל־הַ⁠ח֖וּץ חָמֵ֣שׁ אַמּ֑וֹת וַ⁠אֲשֶׁ֣ר מֻנָּ֔ח בֵּ֥ית צְלָע֖וֹת אֲשֶׁ֥ר לַ⁠בָּֽיִת׃","rò֣ẖab ha⁠qi֧̇yr ʼàֽşěr-la⁠ẕé̇lá֛ʻ ʼel-ha⁠ẖ֖ẇẕ ẖámé֣ş̌ ʼaṁ֑wòţ wa⁠ʼàşě֣r muná̇֔ẖ bé֥̇yţ ẕĕláʻ֖wòţ ʼàşě֥r la⁠báֽ̇yiţ׃"],[41,10,"וּ⁠בֵ֨ין הַ⁠לְּשָׁכ֜וֹת רֹ֣חַב עֶשְׂרִ֥ים אַמָּ֛ה סָבִ֥יב לַ⁠בַּ֖יִת סָבִ֥יב ׀ סָבִֽיב׃","ẇ⁠bé֨yn ha⁠lĕ̇şá̌k֜wòţ rò֣ẖab ʻeşĕ̂ri֥ym ʼamá֛̇h sábi֥yb la⁠bȧ֖yiţ sábi֥yb ׀ sábiֽyb׃"],[41,11,"וּ⁠פֶ֤תַח הַ⁠צֵּלָע֙ לַ⁠מֻּנָּ֔ח פֶּ֤תַח אֶחָד֙ דֶּ֣רֶךְ הַ⁠צָּפ֔וֹן וּ⁠פֶ֥תַח אֶחָ֖ד לַ⁠דָּר֑וֹם וְ⁠רֹ֨חַב֙ מְק֣וֹם הַ⁠מֻּנָּ֔ח חָמֵ֥שׁ אַמּ֖וֹת סָבִ֥יב ׀ סָבִֽיב׃","ẇ⁠pe֤ţaẖ ha⁠ẕé̇láʻ֙ la⁠mu̇ná̇֔ẖ pė֤ţaẖ ʼeẖád֙ dė֣rekĕ ha⁠ẕá̇p֔wòn ẇ⁠pe֥ţaẖ ʼeẖá֖d la⁠dá̇r֑wòm wĕ⁠rò֨ẖab֙ mĕq֣wòm ha⁠mu̇ná̇֔ẖ ẖámé֥ş̌ ʼaṁ֖wòţ sábi֥yb ׀ sábiֽyb׃"],[41,12,"וְ⁠הַ⁠בִּנְיָ֡ן אֲשֶׁר֩ אֶל־פְּנֵ֨י הַ⁠גִּזְרָ֜ה פְּאַ֣ת דֶּֽרֶךְ־הַ⁠יָּ֗ם רֹ֚חַב שִׁבְעִ֣ים אַמָּ֔ה וְ⁠קִ֧יר הַ⁠בִּנְיָ֛ן חָֽמֵשׁ־אַמּ֥וֹת רֹ֖חַב סָבִ֣יב ׀ סָבִ֑יב וְ⁠אָרְכּ֖⁠וֹ תִּשְׁעִ֥ים אַמָּֽה׃","wĕ⁠ha⁠bi̇nĕyá֡n ʼàşěr֩ ʼel-pĕ̇né֨y ha⁠gi̇zĕrá֜h pĕ̇ʼa֣ţ dėֽrekĕ-ha⁠yá̇֗m rò֚ẖab şǐbĕʻi֣ym ʼamá̇֔h wĕ⁠qi֧yr ha⁠bi̇nĕyá֛n ẖáֽméş̌-ʼaṁ֥wòţ rò֖ẖab sábi֣yb ׀ sábi֑yb wĕ⁠ʼárĕk֖̇⁠wò ţi̇şĕ̌ʻi֥ym ʼamáֽ̇h׃"],[41,13,"וּ⁠מָדַ֣ד אֶת־הַ⁠בַּ֔יִת אֹ֖רֶךְ מֵאָ֣ה אַמָּ֑ה וְ⁠הַ⁠גִּזְרָ֤ה וְ⁠הַ⁠בִּנְיָה֙ וְ⁠קִ֣ירוֹתֶ֔י⁠הָ אֹ֖רֶךְ מֵאָ֥ה אַמָּֽה׃","ẇ⁠máda֣d ʼeţ-ha⁠bȧ֔yiţ ʼò֖rekĕ méʼá֣h ʼamá֑̇h wĕ⁠ha⁠gi̇zĕrá֤h wĕ⁠ha⁠bi̇nĕyáh֙ wĕ⁠qi֣yrwòţe֔y⁠há ʼò֖rekĕ méʼá֥h ʼamáֽ̇h׃"],[41,14,"וְ⁠רֹחַב֩ פְּנֵ֨י הַ⁠בַּ֧יִת וְ⁠הַ⁠גִּזְרָ֛ה לַ⁠קָּדִ֖ים מֵאָ֥ה אַמָּֽה׃","wĕ⁠ròẖab֩ pĕ̇né֨y ha⁠bȧ֧yiţ wĕ⁠ha⁠gi̇zĕrá֛h la⁠qá̇di֖ym méʼá֥h ʼamáֽ̇h׃"],[41,15,"וּ⁠מָדַ֣ד אֹֽרֶךְ־הַ֠⁠בִּנְיָן אֶל־פְּנֵ֨י הַ⁠גִּזְרָ֜ה אֲשֶׁ֨ר עַל־אַחֲרֶ֧י⁠הָ ו⁠אתוקי⁠הא מִ⁠פּ֥וֹ וּ⁠מִ⁠פּ֖וֹ מֵאָ֣ה אַמָּ֑ה וְ⁠הַֽ⁠הֵיכָל֙ הַ⁠פְּנִימִ֔י וְ⁠אֻֽלַמֵּ֖י הֶ⁠חָצֵֽר׃","ẇ⁠máda֣d ʼòֽrekĕ-ha֠⁠bi̇nĕyán ʼel-pĕ̇né֨y ha⁠gi̇zĕrá֜h ʼàşě֨r ʻal-ʼaẖàre֧y⁠há w⁠ʼţwqy⁠hʼ mi⁠ṗ֥wò ẇ⁠mi⁠ṗ֖wò méʼá֣h ʼamá֑̇h wĕ⁠haֽ⁠héykál֙ ha⁠pĕ̇niymi֔y wĕ⁠ʼuֽlamé֖̇y he⁠ẖáẕéֽr׃"],[41,16,"הַ⁠סִּפִּ֡ים וְ⁠הַ⁠חַלּוֹנִ֣ים הָ֠⁠אֲטֻמוֹת וְ⁠הָ⁠אַתִּיקִ֤ים ׀ סָבִיב֙ לִ⁠שְׁלָשְׁתָּ֔⁠ם נֶ֧גֶד הַ⁠סַּ֛ף שְׂחִ֥יף עֵ֖ץ סָבִ֣יב ׀ סָבִ֑יב וְ⁠הָ⁠אָ֨רֶץ֙ עַד־הַֽ⁠חַלֹּנ֔וֹת וְ⁠הַֽ⁠חַלֹּנ֖וֹת מְכֻסּֽוֹת׃","ha⁠si̇pi̇֡ym wĕ⁠ha⁠ẖal̇wòni֣ym há֠⁠ʼàtumwòţ wĕ⁠há⁠ʼaţi̇yqi֤ym ׀ sábiyb֙ li⁠şĕ̌láşĕ̌ţá̇֔⁠m ne֧ged ha⁠sȧ֛p şĕ̂ẖi֥yp ʻé֖ẕ sábi֣yb ׀ sábi֑yb wĕ⁠há⁠ʼá֨reẕ֙ ʻad-haֽ⁠ẖalò̇n֔wòţ wĕ⁠haֽ⁠ẖalò̇n֖wòţ mĕkuṡֽwòţ׃"],[41,17,"עַל־מֵ⁠עַ֣ל הַ⁠פֶּ֡תַח וְ⁠עַד־הַ⁠בַּיִת֩ הַ⁠פְּנִימִ֨י וְ⁠לַ⁠ח֜וּץ וְ⁠אֶל־כָּל־הַ⁠קִּ֨יר סָבִ֧יב ׀ סָבִ֛יב בַּ⁠פְּנִימִ֥י וּ⁠בַ⁠חִיצ֖וֹן מִדּֽוֹת׃","ʻal-mé⁠ʻa֣l ha⁠pė֡ţaẖ wĕ⁠ʻad-ha⁠bȧyiţ֩ ha⁠pĕ̇niymi֨y wĕ⁠la⁠ẖ֜ẇẕ wĕ⁠ʼel-ká̇l-ha⁠qi̇֨yr sábi֧yb ׀ sábi֛yb bȧ⁠pĕ̇niymi֥y ẇ⁠ba⁠ẖiyẕ֖wòn miḋֽwòţ׃"],[41,18,"וְ⁠עָשׂ֥וּי כְּרוּבִ֖ים וְ⁠תִֽמֹרִ֑ים וְ⁠תִֽמֹרָה֙ בֵּין־כְּר֣וּב לִ⁠כְר֔וּב וּ⁠שְׁנַ֥יִם פָּנִ֖ים לַ⁠כְּרֽוּב׃","wĕ⁠ʻáş֥̂ẇy kĕ̇rẇbi֖ym wĕ⁠ţiֽmòri֑ym wĕ⁠ţiֽmòráh֙ bé̇yn-kĕ̇r֣ẇb li⁠kĕr֔ẇb ẇ⁠şĕ̌na֥yim pá̇ni֖ym la⁠kĕ̇rֽẇb׃"],[41,19,"וּ⁠פְנֵ֨י אָדָ֤ם אֶל־הַ⁠תִּֽמֹרָה֙ מִ⁠פּ֔וֹ וּ⁠פְנֵֽי־כְפִ֥יר אֶל־הַ⁠תִּֽמֹרָ֖ה מִ⁠פּ֑וֹ עָשׂ֥וּי אֶל־כָּל־הַ⁠בַּ֖יִת סָבִ֥יב ׀ סָבִֽיב׃","ẇ⁠pĕné֨y ʼádá֤m ʼel-ha⁠ţiֽ̇mòráh֙ mi⁠ṗ֔wò ẇ⁠pĕnéֽy-kĕpi֥yr ʼel-ha⁠ţiֽ̇mòrá֖h mi⁠ṗ֑wò ʻáş֥̂ẇy ʼel-ká̇l-ha⁠bȧ֖yiţ sábi֥yb ׀ sábiֽyb׃"],[41,20,"מֵ⁠הָ⁠אָ֨רֶץ֙ עַד־מֵ⁠עַ֣ל הַ⁠פֶּ֔תַח הַ⁠כְּרוּבִ֥ים וְ⁠הַ⁠תִּֽמֹרִ֖ים עֲשׂוּיִ֑ם וְ⁠קִ֖יר הַׄ⁠הֵׄיׄכָֽׄלׄ׃","mé⁠há⁠ʼá֨reẕ֙ ʻad-mé⁠ʻa֣l ha⁠pė֔ţaẖ ha⁠kĕ̇rẇbi֥ym wĕ⁠ha⁠ţiֽ̇mòri֖ym ʻàş̂ẇyi֑m wĕ⁠qi֖yr haׄ⁠héׄyׄkáֽׄlׄ׃"],[41,21,"הַֽ⁠הֵיכָ֖ל מְזוּזַ֣ת רְבֻעָ֑ה וּ⁠פְנֵ֣י הַ⁠קֹּ֔דֶשׁ הַ⁠מַּרְאֶ֖ה כַּ⁠מַּרְאֶֽה׃","haֽ⁠héyká֖l mĕzẇza֣ţ rĕbuʻá֑h ẇ⁠pĕné֣y ha⁠qò̇֔deş̌ ha⁠mȧrĕʼe֖h kȧ⁠mȧrĕʼeֽh׃"],[41,22,"הַ⁠מִּזְבֵּ֡חַ עֵ֣ץ שָׁלוֹשׁ֩ אַמּ֨וֹת גָּבֹ֜הַּ וְ⁠אָרְכּ֣⁠וֹ שְׁתַּֽיִם־אַמּ֗וֹת וּ⁠מִקְצֹֽעוֹתָי⁠ו֙ ל֔⁠וֹ וְ⁠אָרְכּ֥⁠וֹ וְ⁠קִֽירֹתָ֖י⁠ו עֵ֑ץ וַ⁠יְדַבֵּ֣ר אֵלַ֔⁠י זֶ֚ה הַ⁠שֻּׁלְחָ֔ן אֲשֶׁ֖ר לִ⁠פְנֵ֥י יְהוָֽה׃","ha⁠mi̇zĕbé̇֡ẖa ʻé֣ẕ şá̌lwòş̌֩ ʼaṁ֨wòţ gá̇bò֜hȧ wĕ⁠ʼárĕk֣̇⁠wò şĕ̌ţȧֽyim-ʼaṁ֗wòţ ẇ⁠miqĕẕòֽʻwòţáy⁠w֙ l֔⁠wò wĕ⁠ʼárĕk֥̇⁠wò wĕ⁠qiֽyròţá֖y⁠w ʻé֑ẕ wa⁠yĕdabé֣̇r ʼéla֔⁠y ze֚h ha⁠şu̇̌lĕẖá֔n ʼàşě֖r li⁠pĕné֥y yĕhwáֽh׃"],[41,23,"וּ⁠שְׁתַּ֧יִם דְּלָת֛וֹת לַֽ⁠הֵיכָ֖ל וְ⁠לַ⁠קֹּֽדֶשׁ׃","ẇ⁠şĕ̌ţȧ֧yim dĕ̇láţ֛wòţ laֽ⁠héyká֖l wĕ⁠la⁠qòֽ̇deş̌׃"],[41,24,"וּ⁠שְׁתַּ֥יִם דְּלָת֖וֹת לַ⁠דְּלָת֑וֹת שְׁ֚תַּיִם מוּסַבּ֣וֹת דְּלָת֔וֹת שְׁ֚תַּיִם לְ⁠דֶ֣לֶת אֶחָ֔ת וּ⁠שְׁתֵּ֥י דְלָת֖וֹת לָ⁠אַחֶֽרֶת׃","ẇ⁠şĕ̌ţȧ֥yim dĕ̇láţ֖wòţ la⁠dĕ̇láţ֑wòţ şĕ֚̌ţȧyim mẇsaḃ֣wòţ dĕ̇láţ֔wòţ şĕ֚̌ţȧyim lĕ⁠de֣leţ ʼeẖá֔ţ ẇ⁠şĕ̌ţé֥̇y dĕláţ֖wòţ lá⁠ʼaẖeֽreţ׃"],[41,25,"וַ⁠עֲשׂוּיָ֨ה אֲלֵי⁠הֶ֜ן אֶל־דַּלְת֤וֹת הַֽ⁠הֵיכָל֙ כְּרוּבִ֣ים וְ⁠תִֽמֹרִ֔ים כַּ⁠אֲשֶׁ֥ר עֲשׂוּיִ֖ם לַ⁠קִּיר֑וֹת וְ⁠עָ֥ב עֵ֛ץ אֶל־פְּנֵ֥י הָ⁠אוּלָ֖ם מֵ⁠הַ⁠חֽוּץ׃","wa⁠ʻàş̂ẇyá֨h ʼàléy⁠he֜n ʼel-dȧlĕţ֤wòţ haֽ⁠héykál֙ kĕ̇rẇbi֣ym wĕ⁠ţiֽmòri֔ym kȧ⁠ʼàşě֥r ʻàş̂ẇyi֖m la⁠qi̇yr֑wòţ wĕ⁠ʻá֥b ʻé֛ẕ ʼel-pĕ̇né֥y há⁠ʼẇlá֖m mé⁠ha⁠ẖֽẇẕ׃"],[41,26,"וְ⁠חַלּוֹנִ֨ים אֲטֻמ֤וֹת וְ⁠תִֽמֹרִים֙ מִ⁠פּ֣וֹ וּ⁠מִ⁠פּ֔וֹ אֶל־כִּתְפ֖וֹת הָֽ⁠אוּלָ֑ם וְ⁠צַלְע֥וֹת הַ⁠בַּ֖יִת וְ⁠הָ⁠עֻבִּֽים׃","wĕ⁠ẖal̇wòni֨ym ʼàtum֤wòţ wĕ⁠ţiֽmòriym֙ mi⁠ṗ֣wò ẇ⁠mi⁠ṗ֔wò ʼel-ki̇ţĕp֖wòţ háֽ⁠ʼẇlá֑m wĕ⁠ẕalĕʻ֥wòţ ha⁠bȧ֖yiţ wĕ⁠há⁠ʻubiֽ̇ym׃"],[42,1,"וַ⁠יּוֹצִאֵ֗⁠נִי אֶל־הֶֽ⁠חָצֵר֙ הַ⁠חִ֣יצוֹנָ֔ה הַ⁠דֶּ֖רֶךְ דֶּ֣רֶךְ הַ⁠צָּפ֑וֹן וַ⁠יְבִאֵ֣⁠נִי אֶל־הַ⁠לִּשְׁכָּ֗ה אֲשֶׁ֨ר נֶ֧גֶד הַ⁠גִּזְרָ֛ה וַ⁠אֲשֶֽׁר־נֶ֥גֶד הַ⁠בִּנְיָ֖ן אֶל־הַ⁠צָּפֽוֹן׃","wa⁠ẏwòẕiʼé֗⁠niy ʼel-heֽ⁠ẖáẕér֙ ha⁠ẖi֣yẕwòná֔h ha⁠dė֖rekĕ dė֣rekĕ ha⁠ẕá̇p֑wòn wa⁠yĕbiʼé֣⁠niy ʼel-ha⁠li̇şĕ̌ká̇֗h ʼàşě֨r ne֧ged ha⁠gi̇zĕrá֛h wa⁠ʼàşěֽr-ne֥ged ha⁠bi̇nĕyá֖n ʼel-ha⁠ẕá̇pֽwòn׃"],[42,2,"אֶל־פְּנֵי־אֹ֨רֶךְ֙ אַמּ֣וֹת הַ⁠מֵּאָ֔ה פֶּ֖תַח הַ⁠צָּפ֑וֹן וְ⁠הָ⁠רֹ֖חַב חֲמִשִּׁ֥ים אַמּֽוֹת׃","ʼel-pĕ̇néy-ʼò֨rekĕ֙ ʼaṁ֣wòţ ha⁠mé̇ʼá֔h pė֖ţaẖ ha⁠ẕá̇p֑wòn wĕ⁠há⁠rò֖ẖab ẖàmişi֥̇̌ym ʼaṁֽwòţ׃"],[42,3,"נֶ֣גֶד הָֽ⁠עֶשְׂרִ֗ים אֲשֶׁר֙ לֶ⁠חָצֵ֣ר הַ⁠פְּנִימִ֔י וְ⁠נֶ֣גֶד רִֽצְפָ֔ה אֲשֶׁ֖ר לֶ⁠חָצֵ֣ר הַ⁠חִֽיצוֹנָ֑ה אַתִּ֥יק אֶל־פְּנֵֽי־אַתִּ֖יק בַּ⁠שְּׁלִשִֽׁים׃","ne֣ged háֽ⁠ʻeşĕ̂ri֗ym ʼàşěr֙ le⁠ẖáẕé֣r ha⁠pĕ̇niymi֔y wĕ⁠ne֣ged riֽẕĕpá֔h ʼàşě֖r le⁠ẖáẕé֣r ha⁠ẖiֽyẕwòná֑h ʼaţi֥̇yq ʼel-pĕ̇néֽy-ʼaţi֖̇yq bȧ⁠şĕ̇̌lişǐֽym׃"],[42,4,"וְ⁠לִ⁠פְנֵ֨י הַ⁠לְּשָׁכ֜וֹת מַהֲלַךְ֩ עֶ֨שֶׂר אַמּ֥וֹת רֹ֨חַב֙ אֶל־הַ⁠פְּנִימִ֔ית דֶּ֖רֶךְ אַמָּ֣ה אֶחָ֑ת וּ⁠פִתְחֵי⁠הֶ֖ם לַ⁠צָּפֽוֹן׃","wĕ⁠li⁠pĕné֨y ha⁠lĕ̇şá̌k֜wòţ mahàlakĕ֩ ʻe֨şêr ʼaṁ֥wòţ rò֨ẖab֙ ʼel-ha⁠pĕ̇niymi֔yţ dė֖rekĕ ʼamá֣̇h ʼeẖá֑ţ ẇ⁠piţĕẖéy⁠he֖m la⁠ẕá̇pֽwòn׃"],[42,5,"וְ⁠הַ⁠לְּשָׁכ֥וֹת הָ⁠עֶלְיוֹנֹ֖ת קְצֻר֑וֹת כִּֽי־יוֹכְל֨וּ אַתִּיקִ֜ים מֵ⁠הֵ֗נָה מֵֽ⁠הַ⁠תַּחְתֹּנ֛וֹת וּ⁠מֵ⁠הַ⁠תִּֽכֹנ֖וֹת בִּנְיָֽן׃","wĕ⁠ha⁠lĕ̇şá̌k֥wòţ há⁠ʻelĕywònò֖ţ qĕẕur֑wòţ kiֽ̇y-ywòkĕl֨ẇ ʼaţi̇yqi֜ym mé⁠hé֗náh méֽ⁠ha⁠ţȧẖĕţò̇n֛wòţ ẇ⁠mé⁠ha⁠ţiֽ̇kòn֖wòţ bi̇nĕyáֽn׃"],[42,6,"כִּ֤י מְשֻׁלָּשׁוֹת֙ הֵ֔נָּה וְ⁠אֵ֤ין לָ⁠הֶן֙ עַמּוּדִ֔ים כְּ⁠עַמּוּדֵ֖י הַ⁠חֲצֵר֑וֹת עַל־כֵּ֣ן נֶאֱצַ֗ל מֵ⁠הַ⁠תַּחְתּוֹנ֛וֹת וּ⁠מֵ⁠הַ⁠תִּֽיכֹנ֖וֹת מֵ⁠הָ⁠אָֽרֶץ׃","ki֤̇y mĕşǔlá̇ş̌wòţ֙ hé֔ná̇h wĕ⁠ʼé֤yn lá⁠hen֙ ʻaṁẇdi֔ym kĕ̇⁠ʻaṁẇdé֖y ha⁠ẖàẕér֑wòţ ʻal-ké֣̇n neʼèẕa֗l mé⁠ha⁠ţȧẖĕţ̇wòn֛wòţ ẇ⁠mé⁠ha⁠ţiֽ̇ykòn֖wòţ mé⁠há⁠ʼáֽreẕ׃"],[42,7,"וְ⁠גָדֵ֤ר אֲשֶׁר־לַ⁠חוּץ֙ לְ⁠עֻמַּ֣ת הַ⁠לְּשָׁכ֔וֹת דֶּ֛רֶךְ הֶ⁠חָצֵ֥ר הַ⁠חִֽצוֹנָ֖ה אֶל־פְּנֵ֣י הַ⁠לְּשָׁכ֑וֹת אָרְכּ֖⁠וֹ חֲמִשִּׁ֥ים אַמָּֽה׃","wĕ⁠gádé֤r ʼàşěr-la⁠ẖẇẕ֙ lĕ⁠ʻumȧ֣ţ ha⁠lĕ̇şá̌k֔wòţ dė֛rekĕ he⁠ẖáẕé֥r ha⁠ẖiֽẕwòná֖h ʼel-pĕ̇né֣y ha⁠lĕ̇şá̌k֑wòţ ʼárĕk֖̇⁠wò ẖàmişi֥̇̌ym ʼamáֽ̇h׃"],[42,8,"כִּֽי־אֹ֣רֶךְ הַ⁠לְּשָׁכ֗וֹת אֲשֶׁ֛ר לֶ⁠חָצֵ֥ר הַ⁠חִֽצוֹנָ֖ה חֲמִשִּׁ֣ים אַמָּ֑ה וְ⁠הִנֵּ֛ה עַל־פְּנֵ֥י הַ⁠הֵיכָ֖ל מֵאָ֥ה אַמָּֽה׃","kiֽ̇y-ʼò֣rekĕ ha⁠lĕ̇şá̌k֗wòţ ʼàşě֛r le⁠ẖáẕé֥r ha⁠ẖiֽẕwòná֖h ẖàmişi֣̇̌ym ʼamá֑̇h wĕ⁠hiné֛̇h ʻal-pĕ̇né֥y ha⁠héyká֖l méʼá֥h ʼamáֽ̇h׃"],[42,9,"ו⁠מ⁠תחת⁠ה לשכות הָ⁠אֵ֑לֶּה ה⁠מבוא מֵֽ⁠הַ⁠קָּדִ֔ים בְּ⁠בֹא֣⁠וֹ לָ⁠הֵ֔נָּה מֵֽ⁠הֶ⁠חָצֵ֖ר הַ⁠חִצֹנָֽה׃","w⁠m⁠ţẖţ⁠h lşkwţ há⁠ʼé֑lėh h⁠mbwʼ méֽ⁠ha⁠qá̇di֔ym bĕ̇⁠bòʼ֣⁠wò lá⁠hé֔ná̇h méֽ⁠he⁠ẖáẕé֖r ha⁠ẖiẕònáֽh׃"],[42,10,"בְּ⁠רֹ֣חַב ׀ גֶּ֣דֶר הֶ⁠חָצֵ֗ר דֶּ֧רֶךְ הַ⁠קָּדִ֛ים אֶל־פְּנֵ֧י הַ⁠גִּזְרָ֛ה וְ⁠אֶל־פְּנֵ֥י הַ⁠בִּנְיָ֖ן לְשָׁכֽוֹת׃","bĕ̇⁠rò֣ẖab ׀ gė֣der he⁠ẖáẕé֗r dė֧rekĕ ha⁠qá̇di֛ym ʼel-pĕ̇né֧y ha⁠gi̇zĕrá֛h wĕ⁠ʼel-pĕ̇né֥y ha⁠bi̇nĕyá֖n lĕşá̌kֽwòţ׃"],[42,11,"וְ⁠דֶ֨רֶךְ֙ לִ⁠פְנֵי⁠הֶ֔ם כְּ⁠מַרְאֵ֣ה הַ⁠לְּשָׁכ֗וֹת אֲשֶׁר֙ דֶּ֣רֶךְ הַ⁠צָּפ֔וֹן כְּ⁠אָרְכָּ֖⁠ן כֵּ֣ן רָחְבָּ֑⁠ן וְ⁠כֹל֙ מוֹצָ֣אֵי⁠הֶ֔ן וּ⁠כְ⁠מִשְׁפְּטֵי⁠הֶ֖ן וּ⁠כְ⁠פִתְחֵי⁠הֶֽן׃","wĕ⁠de֨rekĕ֙ li⁠pĕnéy⁠he֔m kĕ̇⁠marĕʼé֣h ha⁠lĕ̇şá̌k֗wòţ ʼàşěr֙ dė֣rekĕ ha⁠ẕá̇p֔wòn kĕ̇⁠ʼárĕká֖̇⁠n ké֣̇n ráẖĕbá֑̇⁠n wĕ⁠kòl֙ mwòẕá֣ʼéy⁠he֔n ẇ⁠kĕ⁠mişĕ̌pĕ̇téy⁠he֖n ẇ⁠kĕ⁠piţĕẖéy⁠heֽn׃"],[42,12,"וּ⁠כְ⁠פִתְחֵ֣י הַ⁠לְּשָׁכ֗וֹת אֲשֶׁר֙ דֶּ֣רֶךְ הַ⁠דָּר֔וֹם פֶּ֖תַח בְּ⁠רֹ֣אשׁ דָּ֑רֶךְ דֶּ֗רֶךְ בִּ⁠פְנֵי֙ הַ⁠גְּדֶ֣רֶת הֲגִינָ֔ה דֶּ֥רֶךְ הַ⁠קָּדִ֖ים בְּ⁠בוֹאָֽ⁠ן׃","ẇ⁠kĕ⁠piţĕẖé֣y ha⁠lĕ̇şá̌k֗wòţ ʼàşěr֙ dė֣rekĕ ha⁠dá̇r֔wòm pė֖ţaẖ bĕ̇⁠rò֣ʼş̌ dá֑̇rekĕ dė֗rekĕ bi̇⁠pĕnéy֙ ha⁠gĕ̇de֣reţ hàgiyná֔h dė֥rekĕ ha⁠qá̇di֖ym bĕ̇⁠bwòʼáֽ⁠n׃"],[42,13,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י לִֽשְׁכ֨וֹת הַ⁠צָּפ֜וֹן לִֽשְׁכ֣וֹת הַ⁠דָּרוֹם֮ אֲשֶׁ֣ר אֶל־פְּנֵ֣י הַ⁠גִּזְרָה֒ הֵ֣נָּה ׀ לִֽשְׁכ֣וֹת הַ⁠קֹּ֗דֶשׁ אֲשֶׁ֨ר יֹאכְלוּ־שָׁ֧ם הַ⁠כֹּהֲנִ֛ים אֲשֶׁר־קְרוֹבִ֥ים לַֽ⁠יהוָ֖ה קָדְשֵׁ֣י הַ⁠קֳּדָשִׁ֑ים שָׁ֞ם יַנִּ֣יחוּ ׀ קָדְשֵׁ֣י הַ⁠קֳּדָשִׁ֗ים וְ⁠הַ⁠מִּנְחָה֙ וְ⁠הַ⁠חַטָּ֣את וְ⁠הָ⁠אָשָׁ֔ם כִּ֥י הַ⁠מָּק֖וֹם קָדֹֽשׁ׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y liֽşĕ̌k֨wòţ ha⁠ẕá̇p֜wòn liֽşĕ̌k֣wòţ ha⁠dá̇rwòm֮ ʼàşě֣r ʼel-pĕ̇né֣y ha⁠gi̇zĕráh֒ hé֣ná̇h ׀ liֽşĕ̌k֣wòţ ha⁠qò̇֗deş̌ ʼàşě֨r yòʼkĕlẇ-şá֧̌m ha⁠kò̇hàni֛ym ʼàşěr-qĕrwòbi֥ym laֽ⁠yhwá֖h qádĕşé֣̌y ha⁠qȯdáşǐ֑ym şá̌֞m yani֣̇yẖẇ ׀ qádĕşé֣̌y ha⁠qȯdáşǐ֗ym wĕ⁠ha⁠mi̇nĕẖáh֙ wĕ⁠ha⁠ẖatá֣̇ʼţ wĕ⁠há⁠ʼáşá̌֔m ki֥̇y ha⁠má̇q֖wòm qádòֽş̌׃"],[42,14,"בְּ⁠בֹאָ֣⁠ם הַ⁠כֹּהֲנִ֗ים וְ⁠לֹֽא־יֵצְא֤וּ מֵ⁠הַ⁠קֹּ֨דֶשׁ֙ אֶל־הֶ⁠חָצֵ֣ר הַ⁠חִיצוֹנָ֔ה וְ⁠שָׁ֞ם יַנִּ֧יחוּ בִגְדֵי⁠הֶ֛ם אֲשֶׁר־יְשָׁרְת֥וּ בָ⁠הֶ֖ן כִּֽי־קֹ֣דֶשׁ הֵ֑נָּה ילבשו בְּגָדִ֣ים אֲחֵרִ֔ים וְ⁠קָרְב֖וּ אֶל־אֲשֶׁ֥ר לָ⁠עָֽם׃","bĕ̇⁠bòʼá֣⁠m ha⁠kò̇hàni֗ym wĕ⁠lòֽʼ-yéẕĕʼ֤ẇ mé⁠ha⁠qò̇֨deş̌֙ ʼel-he⁠ẖáẕé֣r ha⁠ẖiyẕwòná֔h wĕ⁠şá̌֞m yani֧̇yẖẇ bigĕdéy⁠he֛m ʼàşěr-yĕşá̌rĕţ֥ẇ bá⁠he֖n kiֽ̇y-qò֣deş̌ hé֑ná̇h ylbşw bĕ̇gádi֣ym ʼàẖéri֔ym wĕ⁠qárĕb֖ẇ ʼel-ʼàşě֥r lá⁠ʻáֽm׃"],[42,15,"וְ⁠כִלָּ֗ה אֶת־מִדּוֹת֙ הַ⁠בַּ֣יִת הַ⁠פְּנִימִ֔י וְ⁠הוֹצִיאַ֨⁠נִי֙ דֶּ֣רֶךְ הַ⁠שַּׁ֔עַר אֲשֶׁ֥ר פָּנָ֖י⁠ו דֶּ֣רֶךְ הַ⁠קָּדִ֑ים וּ⁠מְדָד֖⁠וֹ סָבִ֥יב ׀ סָבִֽיב׃","wĕ⁠kilá̇֗h ʼeţ-miḋwòţ֙ ha⁠bȧ֣yiţ ha⁠pĕ̇niymi֔y wĕ⁠hwòẕiyʼa֨⁠niy֙ dė֣rekĕ ha⁠şȧ̌֔ʻar ʼàşě֥r pá̇ná֖y⁠w dė֣rekĕ ha⁠qá̇di֑ym ẇ⁠mĕdád֖⁠wò sábi֥yb ׀ sábiֽyb׃"],[42,16,"מָדַ֛ד ר֥וּחַ הַ⁠קָּדִ֖ים בִּ⁠קְנֵ֣ה הַ⁠מִּדָּ֑ה חֲמֵשׁ־אמות קָנִ֛ים בִּ⁠קְנֵ֥ה הַ⁠מִּדָּ֖ה סָבִֽיב׃","máda֛d r֥ẇẖa ha⁠qá̇di֖ym bi̇⁠qĕné֣h ha⁠mi̇dá֑̇h ẖàméş̌-ʼmwţ qáni֛ym bi̇⁠qĕné֥h ha⁠mi̇dá֖̇h sábiֽyb׃"],[42,17,"מָדַ֖ד ר֣וּחַ הַ⁠צָּפ֑וֹן חֲמֵשׁ־מֵא֥וֹת קָנִ֛ים בִּ⁠קְנֵ֥ה הַ⁠מִּדָּ֖ה סָבִֽיב׃","máda֖d r֣ẇẖa ha⁠ẕá̇p֑wòn ẖàméş̌-méʼ֥wòţ qáni֛ym bi̇⁠qĕné֥h ha⁠mi̇dá֖̇h sábiֽyb׃"],[42,18,"אֵ֛ת ר֥וּחַ הַ⁠דָּר֖וֹם מָדָ֑ד חֲמֵשׁ־מֵא֥וֹת קָנִ֖ים בִּ⁠קְנֵ֥ה הַ⁠מִּדָּֽה׃","ʼé֛ţ r֥ẇẖa ha⁠dá̇r֖wòm mádá֑d ẖàméş̌-méʼ֥wòţ qáni֖ym bi̇⁠qĕné֥h ha⁠mi̇dáֽ̇h׃"],[42,19,"סָבַ֖ב אֶל־ר֣וּחַ הַ⁠יָּ֑ם מָדַ֛ד חֲמֵשׁ־מֵא֥וֹת קָנִ֖ים בִּ⁠קְנֵ֥ה הַ⁠מִּדָּֽה׃","sába֖b ʼel-r֣ẇẖa ha⁠yá֑̇m máda֛d ẖàméş̌-méʼ֥wòţ qáni֖ym bi̇⁠qĕné֥h ha⁠mi̇dáֽ̇h׃"],[42,20,"לְ⁠אַרְבַּ֨ע רוּח֜וֹת מְדָד֗⁠וֹ ח֤וֹמָה ל⁠וֹ֙ סָבִ֣יב ׀ סָבִ֔יב אֹ֚רֶךְ חֲמֵ֣שׁ מֵא֔וֹת וְ⁠רֹ֖חַב חֲמֵ֣שׁ מֵא֑וֹת לְ⁠הַבְדִּ֕יל בֵּ֥ין הַ⁠קֹּ֖דֶשׁ לְ⁠חֹֽל׃","lĕ⁠ʼarĕbȧ֨ʻ rẇẖ֜wòţ mĕdád֗⁠wò ẖ֤wòmáh l⁠wò֙ sábi֣yb ׀ sábi֔yb ʼò֚rekĕ ẖàmé֣ş̌ méʼ֔wòţ wĕ⁠rò֖ẖab ẖàmé֣ş̌ méʼ֑wòţ lĕ⁠habĕdi̇֕yl bé֥̇yn ha⁠qò֖̇deş̌ lĕ⁠ẖòֽl׃"],[43,1,"וַ⁠יּוֹלִכֵ֖⁠נִי אֶל־הַ⁠שָּׁ֑עַר שַׁ֕עַר אֲשֶׁ֥ר פֹּנֶ֖ה דֶּ֥רֶךְ הַ⁠קָּדִֽים׃","wa⁠ẏwòliké֖⁠niy ʼel-ha⁠şá֑̇̌ʻar şǎ֕ʻar ʼàşě֥r pò̇ne֖h dė֥rekĕ ha⁠qá̇diֽym׃"],[43,2,"וְ⁠הִנֵּ֗ה כְּבוֹד֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל בָּ֖א מִ⁠דֶּ֣רֶךְ הַ⁠קָּדִ֑ים וְ⁠קוֹל֗⁠וֹ כְּ⁠קוֹל֙ מַ֣יִם רַבִּ֔ים וְ⁠הָ⁠אָ֖רֶץ הֵאִ֥ירָה מִ⁠כְּבֹדֽ⁠וֹ׃","wĕ⁠hiné̇֗h kĕ̇bwòd֙ ʼèlòhé֣y yişĕ̂ráʼé֔l bá֖̇ʼ mi⁠dė֣rekĕ ha⁠qá̇di֑ym wĕ⁠qwòl֗⁠wò kĕ̇⁠qwòl֙ ma֣yim rabi̇֔ym wĕ⁠há⁠ʼá֖reẕ héʼi֥yráh mi⁠kĕ̇bòdֽ⁠wò׃"],[43,3,"וּ⁠כְ⁠מַרְאֵ֨ה הַ⁠מַּרְאֶ֜ה אֲשֶׁ֣ר רָאִ֗יתִי כַּ⁠מַּרְאֶ֤ה אֲשֶׁר־רָאִ֨יתִי֙ בְּ⁠בֹאִ⁠י֙ לְ⁠שַׁחֵ֣ת אֶת־הָ⁠עִ֔יר וּ⁠מַרְא֕וֹת כַּ⁠מַּרְאֶ֕ה אֲשֶׁ֥ר רָאִ֖יתִי אֶל־נְהַר־כְּבָ֑ר וָ⁠אֶפֹּ֖ל אֶל־פָּנָֽ⁠י׃","ẇ⁠kĕ⁠marĕʼé֨h ha⁠mȧrĕʼe֜h ʼàşě֣r ráʼi֗yţiy kȧ⁠mȧrĕʼe֤h ʼàşěr-ráʼi֨yţiy֙ bĕ̇⁠bòʼi⁠y֙ lĕ⁠şǎẖé֣ţ ʼeţ-há⁠ʻi֔yr ẇ⁠marĕʼ֕wòţ kȧ⁠mȧrĕʼe֕h ʼàşě֥r ráʼi֖yţiy ʼel-nĕhar-kĕ̇bá֑r wá⁠ʼepò֖̇l ʼel-pá̇náֽ⁠y׃"],[43,4,"וּ⁠כְב֥וֹד יְהוָ֖ה בָּ֣א אֶל־הַ⁠בָּ֑יִת דֶּ֣רֶךְ שַׁ֔עַר אֲשֶׁ֥ר פָּנָ֖י⁠ו דֶּ֥רֶךְ הַ⁠קָּדִֽים׃","ẇ⁠kĕb֥wòd yĕhwá֖h bá֣̇ʼ ʼel-ha⁠bá֑̇yiţ dė֣rekĕ şǎ֔ʻar ʼàşě֥r pá̇ná֖y⁠w dė֥rekĕ ha⁠qá̇diֽym׃"],[43,5,"וַ⁠תִּשָּׂאֵ֣⁠נִי ר֔וּחַ וַ⁠תְּבִיאֵ֕⁠נִי אֶל־הֶֽ⁠חָצֵ֖ר הַ⁠פְּנִימִ֑י וְ⁠הִנֵּ֛ה מָלֵ֥א כְבוֹד־יְהוָ֖ה הַ⁠בָּֽיִת׃","wa⁠ţi̇şá̇̂ʼé֣⁠niy r֔ẇẖa wa⁠ţĕ̇biyʼé֕⁠niy ʼel-heֽ⁠ẖáẕé֖r ha⁠pĕ̇niymi֑y wĕ⁠hiné֛̇h málé֥ʼ kĕbwòd-yĕhwá֖h ha⁠báֽ̇yiţ׃"],[43,6,"וָ⁠אֶשְׁמַ֛ע מִדַּבֵּ֥ר אֵלַ֖⁠י מֵ⁠הַ⁠בָּ֑יִת וְ⁠אִ֕ישׁ הָיָ֥ה עֹמֵ֖ד אֶצְלִֽ⁠י׃","wá⁠ʼeşĕ̌ma֛ʻ midȧbé֥̇r ʼéla֖⁠y mé⁠ha⁠bá֑̇yiţ wĕ⁠ʼi֕yş̌ háyá֥h ʻòmé֖d ʼeẕĕliֽ⁠y׃"],[43,7,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י בֶּן־אָדָם֙ אֶת־מְק֣וֹם כִּסְאִ֗⁠י וְ⁠אֶת־מְקוֹם֙ כַּפּ֣וֹת רַגְלַ֔⁠י אֲשֶׁ֧ר אֶשְׁכָּן־שָׁ֛ם בְּ⁠ת֥וֹךְ בְּנֵֽי־יִשְׂרָאֵ֖ל לְ⁠עוֹלָ֑ם וְ⁠לֹ֣א יְטַמְּא֣וּ ע֣וֹד בֵּֽית־יִ֠שְׂרָאֵל שֵׁ֣ם קָדְשִׁ֞⁠י הֵ֤מָּה וּ⁠מַלְכֵי⁠הֶם֙ בִּ⁠זְנוּתָ֔⁠ם וּ⁠בְ⁠פִגְרֵ֥י מַלְכֵי⁠הֶ֖ם בָּמוֹתָֽ⁠ם׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y bėn-ʼádám֙ ʼeţ-mĕq֣wòm ki̇sĕʼi֗⁠y wĕ⁠ʼeţ-mĕqwòm֙ kȧṗ֣wòţ ragĕla֔⁠y ʼàşě֧r ʼeşĕ̌ká̇n-şá֛̌m bĕ̇⁠ţ֥wòkĕ bĕ̇néֽy-yişĕ̂ráʼé֖l lĕ⁠ʻwòlá֑m wĕ⁠lò֣ʼ yĕtamĕ̇ʼ֣ẇ ʻ֣wòd béֽ̇yţ-yi֠şĕ̂ráʼél şé֣̌m qádĕşǐ֞⁠y hé֤má̇h ẇ⁠malĕkéy⁠hem֙ bi̇⁠zĕnẇţá֔⁠m ẇ⁠bĕ⁠pigĕré֥y malĕkéy⁠he֖m bá̇mwòţáֽ⁠m׃"],[43,8,"בְּ⁠תִתָּ֨⁠ם סִפָּ֜⁠ם אֶת־סִפִּ֗⁠י וּ⁠מְזֽוּזָתָ⁠ם֙ אֵ֣צֶל מְזוּזָתִ֔⁠י וְ⁠הַ⁠קִּ֖יר בֵּינִ֣⁠י וּ⁠בֵֽינֵי⁠הֶ֑ם וְ⁠טִמְּא֣וּ ׀ אֶת־שֵׁ֣ם קָדְשִׁ֗⁠י בְּ⁠תֽוֹעֲבוֹתָ⁠ם֙ אֲשֶׁ֣ר עָשׂ֔וּ וָ⁠אֲכַ֥ל אֹתָ֖⁠ם בְּ⁠אַפִּֽ⁠י׃","bĕ̇⁠ţiţá̇֨⁠m sipá̇֜⁠m ʼeţ-sipi̇֗⁠y ẇ⁠mĕzֽẇzáţá⁠m֙ ʼé֣ẕel mĕzẇzáţi֔⁠y wĕ⁠ha⁠qi֖̇yr bé̇yni֣⁠y ẇ⁠béֽynéy⁠he֑m wĕ⁠timĕ̇ʼ֣ẇ ׀ ʼeţ-şé֣̌m qádĕşǐ֗⁠y bĕ̇⁠ţֽwòʻàbwòţá⁠m֙ ʼàşě֣r ʻáş̂֔ẇ wá⁠ʼàka֥l ʼòţá֖⁠m bĕ̇⁠ʼapiֽ̇⁠y׃"],[43,9,"עַתָּ֞ה יְרַחֲק֧וּ אֶת־זְנוּתָ֛⁠ם וּ⁠פִגְרֵ֥י מַלְכֵי⁠הֶ֖ם מִמֶּ֑⁠נִּי וְ⁠שָׁכַנְתִּ֥י בְ⁠תוֹכָ֖⁠ם לְ⁠עוֹלָֽם׃ס","ʻaţá̇֞h yĕraẖàq֧ẇ ʼeţ-zĕnẇţá֛⁠m ẇ⁠pigĕré֥y malĕkéy⁠he֖m mimė֑⁠ni̇y wĕ⁠şá̌kanĕţi֥̇y bĕ⁠ţwòká֖⁠m lĕ⁠ʻwòláֽm׃s"],[43,10,"אַתָּ֣ה בֶן־אָדָ֗ם הַגֵּ֤ד אֶת־בֵּֽית־יִשְׂרָאֵל֙ אֶת־הַ⁠בַּ֔יִת וְ⁠יִכָּלְמ֖וּ מֵ⁠עֲוֺנֽוֹתֵי⁠הֶ֑ם וּ⁠מָדְד֖וּ אֶת־תָּכְנִֽית׃","ʼaţá֣̇h ben-ʼádá֗m hagé֤̇d ʼeţ-béֽ̇yţ-yişĕ̂ráʼél֙ ʼeţ-ha⁠bȧ֔yiţ wĕ⁠yiká̇lĕm֖ẇ mé⁠ʻàwֺnֽwòţéy⁠he֑m ẇ⁠mádĕd֖ẇ ʼeţ-ţá̇kĕniֽyţ׃"],[43,11,"וְ⁠אִֽם־נִכְלְמ֞וּ מִ⁠כֹּ֣ל אֲשֶׁר־עָשׂ֗וּ צוּרַ֣ת הַ⁠בַּ֡יִת וּ⁠תְכוּנָת֡⁠וֹ וּ⁠מוֹצָאָ֡י⁠ו וּ⁠מוֹבָאָ֣י⁠ו וְֽ⁠כָל־צֽוּרֹתָ֡⁠ו וְ⁠אֵ֣ת כָּל־חֻקֹּתָי⁠ו֩ וְ⁠כָל־צורת⁠י וְ⁠כָל־תורת⁠ו הוֹדַ֣ע אוֹתָ֔⁠ם וּ⁠כְתֹ֖ב לְ⁠עֵֽינֵי⁠הֶ֑ם וְ⁠יִשְׁמְר֞וּ אֶת־כָּל־צוּרָת֛⁠וֹ וְ⁠אֶת־כָּל־חֻקֹּתָ֖י⁠ו וְ⁠עָשׂ֥וּ אוֹתָֽ⁠ם׃","wĕ⁠ʼiֽm-nikĕlĕm֞ẇ mi⁠kò֣̇l ʼàşěr-ʻáş̂֗ẇ ẕẇra֣ţ ha⁠bȧ֡yiţ ẇ⁠ţĕkẇnáţ֡⁠wò ẇ⁠mwòẕáʼá֡y⁠w ẇ⁠mwòbáʼá֣y⁠w wĕֽ⁠kál-ẕֽẇròţá֡⁠w wĕ⁠ʼé֣ţ ká̇l-ẖuqò̇ţáy⁠w֩ wĕ⁠kál-ẕwrţ⁠y wĕ⁠kál-ţwrţ⁠w hwòda֣ʻ ʼwòţá֔⁠m ẇ⁠kĕţò֖b lĕ⁠ʻéֽynéy⁠he֑m wĕ⁠yişĕ̌mĕr֞ẇ ʼeţ-ká̇l-ẕẇráţ֛⁠wò wĕ⁠ʼeţ-ká̇l-ẖuqò̇ţá֖y⁠w wĕ⁠ʻáş֥̂ẇ ʼwòţáֽ⁠m׃"],[43,12,"זֹ֖את תּוֹרַ֣ת הַ⁠בָּ֑יִת עַל־רֹ֣אשׁ הָ֠⁠הָר כָּל־גְּבֻל֞⁠וֹ סָבִ֤יב ׀ סָבִיב֙ קֹ֣דֶשׁ קָדָשִׁ֔ים הִנֵּה־זֹ֖את תּוֹרַ֥ת הַ⁠בָּֽיִת׃","zò֖ʼţ ţ̇wòra֣ţ ha⁠bá֑̇yiţ ʻal-rò֣ʼş̌ há֠⁠hár ká̇l-gĕ̇bul֞⁠wò sábi֤yb ׀ sábiyb֙ qò֣deş̌ qádáşǐ֔ym hiné̇h-zò֖ʼţ ţ̇wòra֥ţ ha⁠báֽ̇yiţ׃"],[43,13,"וְ⁠אֵ֨לֶּה מִדּ֤וֹת הַ⁠מִּזְבֵּ֨חַ֙ בָּֽ⁠אַמּ֔וֹת אַמָּ֥ה אַמָּ֖ה וָ⁠טֹ֑פַח וְ⁠חֵ֨יק הָ⁠אַמָּ֜ה וְ⁠אַמָּה־רֹ֗חַב וּ⁠גְבוּלָ֨⁠הּ אֶל־שְׂפָתָ֤⁠הּ סָבִיב֙ זֶ֣רֶת הָ⁠אֶחָ֔ד וְ⁠זֶ֖ה גַּ֥ב הַ⁠מִּזְבֵּֽחַ׃","wĕ⁠ʼé֨lėh miḋ֤wòţ ha⁠mi̇zĕbé̇֨ẖa֙ báֽ̇⁠ʼaṁ֔wòţ ʼamá֥̇h ʼamá֖̇h wá⁠tò֑paẖ wĕ⁠ẖé֨yq há⁠ʼamá̇֜h wĕ⁠ʼamá̇h-rò֗ẖab ẇ⁠gĕbẇlá֨⁠ḣ ʼel-şĕ̂páţá֤⁠ḣ sábiyb֙ ze֣reţ há⁠ʼeẖá֔d wĕ⁠ze֖h gȧ֥b ha⁠mi̇zĕbéֽ̇ẖa׃"],[43,14,"וּ⁠מֵ⁠חֵ֨יק הָ⁠אָ֜רֶץ עַד־הָ⁠עֲזָרָ֤ה הַ⁠תַּחְתּוֹנָה֙ שְׁתַּ֣יִם אַמּ֔וֹת וְ⁠רֹ֖חַב אַמָּ֣ה אֶחָ֑ת וּ⁠מֵ⁠הֳ⁠עֲזָרָ֨ה הַ⁠קְּטַנָּ֜ה עַד־הָ⁠עֲזָרָ֤ה הַ⁠גְּדוֹלָה֙ אַרְבַּ֣ע אַמּ֔וֹת וְ⁠רֹ֖חַב הָ⁠אַמָּֽה׃","ẇ⁠mé⁠ẖé֨yq há⁠ʼá֜reẕ ʻad-há⁠ʻàzárá֤h ha⁠ţȧẖĕţ̇wònáh֙ şĕ̌ţȧ֣yim ʼaṁ֔wòţ wĕ⁠rò֖ẖab ʼamá֣̇h ʼeẖá֑ţ ẇ⁠mé⁠ho⁠ʻàzárá֨h ha⁠qĕ̇taná̇֜h ʻad-há⁠ʻàzárá֤h ha⁠gĕ̇dwòláh֙ ʼarĕbȧ֣ʻ ʼaṁ֔wòţ wĕ⁠rò֖ẖab há⁠ʼamáֽ̇h׃"],[43,15,"וְ⁠הַֽ⁠הַרְאֵ֖ל אַרְבַּ֣ע אַמּ֑וֹת וּ⁠מֵ⁠הָ⁠אֲרִאֵ֣יל וּ⁠לְ⁠מַ֔עְלָ⁠ה הַ⁠קְּרָנ֖וֹת אַרְבַּֽע׃","wĕ⁠haֽ⁠harĕʼé֖l ʼarĕbȧ֣ʻ ʼaṁ֑wòţ ẇ⁠mé⁠há⁠ʼàriʼé֣yl ẇ⁠lĕ⁠ma֔ʻĕlá⁠h ha⁠qĕ̇rán֖wòţ ʼarĕbȧֽʻ׃"],[43,16,"ו⁠ה⁠אראיל שְׁתֵּ֤ים עֶשְׂרֵה֙ אֹ֔רֶךְ בִּ⁠שְׁתֵּ֥ים עֶשְׂרֵ֖ה רֹ֑חַב רָב֕וּעַ אֶ֖ל אַרְבַּ֥עַת רְבָעָֽי⁠ו׃","w⁠h⁠ʼrʼyl şĕ̌ţé֤̇ym ʻeşĕ̂réh֙ ʼò֔rekĕ bi̇⁠şĕ̌ţé֥̇ym ʻeşĕ̂ré֖h rò֑ẖab ráb֕ẇʻa ʼe֖l ʼarĕbȧ֥ʻaţ rĕbáʻáֽy⁠w׃"],[43,17,"וְ⁠הָ⁠עֲזָרָ֞ה אַרְבַּ֧ע עֶשְׂרֵ֣ה אֹ֗רֶךְ בְּ⁠אַרְבַּ֤ע עֶשְׂרֵה֙ רֹ֔חַב אֶ֖ל אַרְבַּ֣עַת רְבָעֶ֑י⁠הָ וְ⁠הַ⁠גְּבוּל סָבִ֨יב אוֹתָ֜⁠הּ חֲצִ֣י הָ⁠אַמָּ֗ה וְ⁠הַֽ⁠חֵיק־לָ֤⁠הּ אַמָּה֙ סָבִ֔יב וּ⁠מַעֲלֹתֵ֖⁠הוּ פְּנ֥וֹת קָדִֽים׃","wĕ⁠há⁠ʻàzárá֞h ʼarĕbȧ֧ʻ ʻeşĕ̂ré֣h ʼò֗rekĕ bĕ̇⁠ʼarĕbȧ֤ʻ ʻeşĕ̂réh֙ rò֔ẖab ʼe֖l ʼarĕbȧ֣ʻaţ rĕbáʻe֑y⁠há wĕ⁠ha⁠gĕ̇bẇl sábi֨yb ʼwòţá֜⁠ḣ ẖàẕi֣y há⁠ʼamá̇֗h wĕ⁠haֽ⁠ẖéyq-lá֤⁠ḣ ʼamá̇h֙ sábi֔yb ẇ⁠maʻàlòţé֖⁠hẇ pĕ̇n֥wòţ qádiֽym׃"],[43,18,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י בֶּן־אָדָם֙ כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה אֵ֚לֶּה חֻקּ֣וֹת הַ⁠מִּזְבֵּ֔חַ בְּ⁠י֖וֹם הֵעָֽשׂוֹת֑⁠וֹ לְ⁠הַעֲל֤וֹת עָלָי⁠ו֙ עוֹלָ֔ה וְ⁠לִ⁠זְרֹ֥ק עָלָ֖י⁠ו דָּֽם׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y bėn-ʼádám֙ kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ʼé֚lėh ẖuq֣̇wòţ ha⁠mi̇zĕbé̇֔ẖa bĕ̇⁠y֖wòm héʻáֽş̂wòţ֑⁠wò lĕ⁠haʻàl֤wòţ ʻáláy⁠w֙ ʻwòlá֔h wĕ⁠li⁠zĕrò֥q ʻálá֖y⁠w dáֽ̇m׃"],[43,19,"וְ⁠נָתַתָּ֣ה אֶל־הַ⁠כֹּהֲנִ֣ים הַ⁠לְוִיִּ֡ם אֲשֶׁ֣ר הֵם֩ מִ⁠זֶּ֨רַע צָד֜וֹק הַ⁠קְּרֹבִ֣ים אֵלַ֗⁠י נְאֻ֛ם אֲדֹנָ֥⁠י יְהוִ֖ה לְ⁠שָֽׁרְתֵ֑⁠נִי פַּ֥ר בֶּן־בָּקָ֖ר לְ⁠חַטָּֽאת׃","wĕ⁠náţaţá֣̇h ʼel-ha⁠kò̇hàni֣ym ha⁠lĕwiyi̇֡m ʼàşě֣r hém֩ mi⁠zė֨raʻ ẕád֜wòq ha⁠qĕ̇ròbi֣ym ʼéla֗⁠y nĕʼu֛m ʼàdòná֥⁠y yĕhwi֖h lĕ⁠şáֽ̌rĕţé֑⁠niy pȧ֥r bėn-bá̇qá֖r lĕ⁠ẖatáֽ̇ʼţ׃"],[43,20,"וְ⁠לָקַחְתָּ֣ מִ⁠דָּמ֗⁠וֹ וְ⁠נָ֨תַתָּ֜ה עַל־אַרְבַּ֤ע קַרְנֹתָי⁠ו֙ וְ⁠אֶל־אַרְבַּע֙ פִּנּ֣וֹת הָ⁠עֲזָרָ֔ה וְ⁠אֶֽל־הַ⁠גְּב֖וּל סָבִ֑יב וְ⁠חִטֵּאתָ֥ אוֹת֖⁠וֹ וְ⁠כִפַּרְתָּֽ⁠הוּ׃","wĕ⁠láqaẖĕţá֣̇ mi⁠dá̇m֗⁠wò wĕ⁠ná֨ţaţá̇֜h ʻal-ʼarĕbȧ֤ʻ qarĕnòţáy⁠w֙ wĕ⁠ʼel-ʼarĕbȧʻ֙ pi̇ṅ֣wòţ há⁠ʻàzárá֔h wĕ⁠ʼeֽl-ha⁠gĕ̇b֖ẇl sábi֑yb wĕ⁠ẖité̇ʼţá֥ ʼwòţ֖⁠wò wĕ⁠kipȧrĕţáֽ̇⁠hẇ׃"],[43,21,"וְ⁠לָ֣קַחְתָּ֔ אֵ֖ת הַ⁠פָּ֣ר הַֽ⁠חַטָּ֑את וּ⁠שְׂרָפ⁠וֹ֙ בְּ⁠מִפְקַ֣ד הַ⁠בַּ֔יִת מִ⁠ח֖וּץ לַ⁠מִּקְדָּֽשׁ׃","wĕ⁠lá֣qaẖĕţá̇֔ ʼé֖ţ ha⁠pá֣̇r haֽ⁠ẖatá֑̇ʼţ ẇ⁠şĕ̂ráp⁠wò֙ bĕ̇⁠mipĕqa֣d ha⁠bȧ֔yiţ mi⁠ẖ֖ẇẕ la⁠mi̇qĕdáֽ̇ş̌׃"],[43,22,"וּ⁠בַ⁠יּוֹם֙ הַ⁠שֵּׁנִ֔י תַּקְרִ֛יב שְׂעִיר־עִזִּ֥ים תָּמִ֖ים לְ⁠חַטָּ֑את וְ⁠חִטְּאוּ֙ אֶת־הַ⁠מִּזְבֵּ֔חַ כַּ⁠אֲשֶׁ֥ר חִטְּא֖וּ בַּ⁠פָּֽר׃","ẇ⁠ba⁠ẏwòm֙ ha⁠şé̇̌ni֔y ţȧqĕri֛yb şĕ̂ʻiyr-ʻizi֥̇ym ţá̇mi֖ym lĕ⁠ẖatá֑̇ʼţ wĕ⁠ẖitĕ̇ʼẇ֙ ʼeţ-ha⁠mi̇zĕbé̇֔ẖa kȧ⁠ʼàşě֥r ẖitĕ̇ʼ֖ẇ bȧ⁠páֽ̇r׃"],[43,23,"בְּ⁠כַלּוֹתְ⁠ךָ֖ מֵֽ⁠חַטֵּ֑א תַּקְרִיב֙ פַּ֣ר בֶּן־בָּקָ֣ר תָּמִ֔ים וְ⁠אַ֥יִל מִן־הַ⁠צֹּ֖אן תָּמִֽים׃","bĕ̇⁠kal̇wòţĕ⁠ká֖ méֽ⁠ẖaté֑̇ʼ ţȧqĕriyb֙ pȧ֣r bėn-bá̇qá֣r ţá̇mi֔ym wĕ⁠ʼa֥yil min-ha⁠ẕò֖̇ʼn ţá̇miֽym׃"],[43,24,"וְ⁠הִקְרַבְתָּ֖⁠ם לִ⁠פְנֵ֣י יְהוָ֑ה וְ⁠הִשְׁלִ֨יכוּ הַ⁠כֹּהֲנִ֤ים עֲלֵי⁠הֶם֙ מֶ֔לַח וְ⁠הֶעֱל֥וּ אוֹתָ֛⁠ם עֹלָ֖ה לַֽ⁠יהוָֽה׃","wĕ⁠hiqĕrabĕţá֖̇⁠m li⁠pĕné֣y yĕhwá֑h wĕ⁠hişĕ̌li֨ykẇ ha⁠kò̇hàni֤ym ʻàléy⁠hem֙ me֔laẖ wĕ⁠heʻèl֥ẇ ʼwòţá֛⁠m ʻòlá֖h laֽ⁠yhwáֽh׃"],[43,25,"שִׁבְעַ֣ת יָמִ֔ים תַּעֲשֶׂ֥ה שְׂעִיר־חַטָּ֖את לַ⁠יּ֑וֹם וּ⁠פַ֧ר בֶּן־בָּקָ֛ר וְ⁠אַ֥יִל מִן־הַ⁠צֹּ֖אן תְּמִימִ֥ים יַעֲשֽׂוּ׃","şǐbĕʻa֣ţ yámi֔ym ţȧʻàşê֥h şĕ̂ʻiyr-ẖatá֖̇ʼţ la⁠ẏ֑wòm ẇ⁠pa֧r bėn-bá̇qá֛r wĕ⁠ʼa֥yil min-ha⁠ẕò֖̇ʼn ţĕ̇miymi֥ym yaʻàşֽ̂ẇ׃"],[43,26,"שִׁבְעַ֣ת יָמִ֗ים יְכַפְּרוּ֙ אֶת־הַ⁠מִּזְבֵּ֔חַ וְ⁠טִֽהֲר֖וּ אֹת֑⁠וֹ וּ⁠מִלְא֖וּ יד⁠ו׃","şǐbĕʻa֣ţ yámi֗ym yĕkapĕ̇rẇ֙ ʼeţ-ha⁠mi̇zĕbé̇֔ẖa wĕ⁠tiֽhàr֖ẇ ʼòţ֑⁠wò ẇ⁠milĕʼ֖ẇ yd⁠w׃"],[43,27,"וִֽ⁠יכַלּ֖וּ אֶת־הַ⁠יָּמִ֑ים ס וְ⁠הָיָה֩ בַ⁠יּ֨וֹם הַ⁠שְּׁמִינִ֜י וָ⁠הָ֗לְאָה יַעֲשׂ֨וּ הַ⁠כֹּהֲנִ֤ים עַל־הַ⁠מִּזְבֵּ֨חַ֙ אֶת־עוֹלֽוֹתֵי⁠כֶם֙ וְ⁠אֶת־שַׁלְמֵי⁠כֶ֔ם וְ⁠רָצִ֣אתִי אֶתְ⁠כֶ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהֹוִֽה׃ס","wiֽ⁠ykal֖̇ẇ ʼeţ-ha⁠yá̇mi֑ym s wĕ⁠háyáh֩ ba⁠ẏ֨wòm ha⁠şĕ̇̌miyni֜y wá⁠há֗lĕʼáh yaʻàş̂֨ẇ ha⁠kò̇hàni֤ym ʻal-ha⁠mi̇zĕbé̇֨ẖa֙ ʼeţ-ʻwòlֽwòţéy⁠kem֙ wĕ⁠ʼeţ-şǎlĕméy⁠ke֔m wĕ⁠ráẕi֣ʼţiy ʼeţĕ⁠ke֔m nĕʼu֖m ʼàdòná֥⁠y yĕhòwiֽh׃s"],[44,1,"וַ⁠יָּ֣שֶׁב אֹתִ֗⁠י דֶּ֣רֶךְ שַׁ֤עַר הַ⁠מִּקְדָּשׁ֙ הַֽ⁠חִיצ֔וֹן הַ⁠פֹּנֶ֖ה קָדִ֑ים וְ⁠ה֖וּא סָגֽוּר׃","wa⁠yá֣̇şěb ʼòţi֗⁠y dė֣rekĕ şǎ֤ʻar ha⁠mi̇qĕdá̇ş̌֙ haֽ⁠ẖiyẕ֔wòn ha⁠pò̇ne֖h qádi֑ym wĕ⁠h֖ẇʼ ságֽẇr׃"],[44,2,"וַ⁠יֹּ֨אמֶר אֵלַ֜⁠י יְהוָ֗ה הַ⁠שַּׁ֣עַר הַ⁠זֶּה֩ סָג֨וּר יִהְיֶ֜ה לֹ֣א יִפָּתֵ֗חַ וְ⁠אִישׁ֙ לֹא־יָ֣בֹא ב֔⁠וֹ כִּ֛י יְהוָ֥ה אֱלֹהֵֽי־יִשְׂרָאֵ֖ל בָּ֣א ב֑⁠וֹ וְ⁠הָיָ֖ה סָגֽוּר׃","wa⁠yò̇֨ʼmer ʼéla֜⁠y yĕhwá֗h ha⁠şȧ֣̌ʻar ha⁠zėh֩ ság֨ẇr yihĕye֜h lò֣ʼ yipá̇ţé֗ẖa wĕ⁠ʼiyş̌֙ lòʼ-yá֣bòʼ b֔⁠wò ki֛̇y yĕhwá֥h ʼèlòhéֽy-yişĕ̂ráʼé֖l bá֣̇ʼ b֑⁠wò wĕ⁠háyá֖h ságֽẇr׃"],[44,3,"אֶֽת־הַ⁠נָּשִׂ֗יא נָ֥שִׂיא ה֛וּא יֵֽשֶׁב־בּ֥⁠וֹ לאכול־לֶ֖חֶם לִ⁠פְנֵ֣י יְהוָ֑ה מִ⁠דֶּ֨רֶךְ אֻלָ֤ם הַ⁠שַּׁ֨עַר֙ יָב֔וֹא וּ⁠מִ⁠דַּרְכּ֖⁠וֹ יֵצֵֽא׃","ʼeֽţ-ha⁠ná̇şî֗yʼ ná֥şîyʼ h֛ẇʼ yéֽşěb-ḃ֥⁠wò lʼkwl-le֖ẖem li⁠pĕné֣y yĕhwá֑h mi⁠dė֨rekĕ ʼulá֤m ha⁠şȧ̌֨ʻar֙ yáb֔wòʼ ẇ⁠mi⁠dȧrĕk֖̇⁠wò yéẕéֽʼ׃"],[44,4,"וַ⁠יְבִיאֵ֜⁠נִי דֶּֽרֶךְ־שַׁ֣עַר הַ⁠צָּפוֹן֮ אֶל־פְּנֵ֣י הַ⁠בַּיִת֒ וָ⁠אֵ֕רֶא וְ⁠הִנֵּ֛ה מָלֵ֥א כְבוֹד־יְהוָ֖ה אֶת־בֵּ֣ית יְהוָ֑ה וָ⁠אֶפֹּ֖ל אֶל־פָּנָֽ⁠י׃","wa⁠yĕbiyʼé֜⁠niy dėֽrekĕ-şǎ֣ʻar ha⁠ẕá̇pwòn֮ ʼel-pĕ̇né֣y ha⁠bȧyiţ֒ wá⁠ʼé֕reʼ wĕ⁠hiné֛̇h málé֥ʼ kĕbwòd-yĕhwá֖h ʼeţ-bé֣̇yţ yĕhwá֑h wá⁠ʼepò֖̇l ʼel-pá̇náֽ⁠y׃"],[44,5,"וַ⁠יֹּ֨אמֶר אֵלַ֜⁠י יְהֹוָ֗ה בֶּן־אָדָ֡ם שִׂ֣ים לִבְּ⁠ךָ֩ וּ⁠רְאֵ֨ה בְ⁠עֵינֶ֜י⁠ךָ וּ⁠בְ⁠אָזְנֶ֣י⁠ךָ שְּׁמָ֗ע אֵ֣ת כָּל־אֲשֶׁ֤ר אֲנִי֙ מְדַבֵּ֣ר אֹתָ֔⁠ךְ לְ⁠כָל־חֻקּ֥וֹת בֵּית־יְהוָ֖ה וּ⁠לְ⁠כָל־תורת⁠ו וְ⁠שַׂמְתָּ֤ לִבְּ⁠ךָ֙ לִ⁠מְב֣וֹא הַ⁠בַּ֔יִת בְּ⁠כֹ֖ל מוֹצָאֵ֥י הַ⁠מִּקְדָּֽשׁ׃","wa⁠yò̇֨ʼmer ʼéla֜⁠y yĕhòwá֗h bėn-ʼádá֡m şî֣ym libĕ̇⁠ká֩ ẇ⁠rĕʼé֨h bĕ⁠ʻéyne֜y⁠ká ẇ⁠bĕ⁠ʼázĕne֣y⁠ká şĕ̇̌má֗ʻ ʼé֣ţ ká̇l-ʼàşě֤r ʼàniy֙ mĕdabé֣̇r ʼòţá֔⁠kĕ lĕ⁠kál-ẖuq֥̇wòţ bé̇yţ-yĕhwá֖h ẇ⁠lĕ⁠kál-ţwrţ⁠w wĕ⁠şâmĕţá֤̇ libĕ̇⁠ká֙ li⁠mĕb֣wòʼ ha⁠bȧ֔yiţ bĕ̇⁠kò֖l mwòẕáʼé֥y ha⁠mi̇qĕdáֽ̇ş̌׃"],[44,6,"וְ⁠אָמַרְתָּ֤ אֶל־מֶ֨רִי֙ אֶל־בֵּ֣ית יִשְׂרָאֵ֔ל כֹּ֥ה אָמַ֖ר אֲדֹנָ֣⁠י יְהוִ֑ה רַב־לָ⁠כֶ֛ם מִֽ⁠כָּל־תּוֹעֲבֽוֹתֵי⁠כֶ֖ם בֵּ֥ית יִשְׂרָאֵֽל׃","wĕ⁠ʼámarĕţá֤̇ ʼel-me֨riy֙ ʼel-bé֣̇yţ yişĕ̂ráʼé֔l kò֥̇h ʼáma֖r ʼàdòná֣⁠y yĕhwi֑h rab-lá⁠ke֛m miֽ⁠ká̇l-ţ̇wòʻàbֽwòţéy⁠ke֖m bé֥̇yţ yişĕ̂ráʼéֽl׃"],[44,7,"בַּ⁠הֲבִיאֲ⁠כֶ֣ם בְּנֵֽי־נֵכָ֗ר עַרְלֵי־לֵב֙ וְ⁠עַרְלֵ֣י בָשָׂ֔ר לִ⁠הְי֥וֹת בְּ⁠מִקְדָּשִׁ֖⁠י לְ⁠חַלְּל֣⁠וֹ אֶת־בֵּיתִ֑⁠י בְּ⁠הַקְרִֽיבְ⁠כֶ֤ם אֶת־לַחְמִ⁠י֙ חֵ֣לֶב וָ⁠דָ֔ם וַ⁠יָּפֵ֨רוּ֙ אֶת־בְּרִיתִ֔⁠י אֶ֖ל כָּל־תּוֹעֲבוֹתֵי⁠כֶֽם׃","bȧ⁠hàbiyʼà⁠ke֣m bĕ̇néֽy-néká֗r ʻarĕléy-léb֙ wĕ⁠ʻarĕlé֣y báşá̂֔r li⁠hĕy֥wòţ bĕ̇⁠miqĕdá̇şǐ֖⁠y lĕ⁠ẖalĕ̇l֣⁠wò ʼeţ-bé̇yţi֑⁠y bĕ̇⁠haqĕriֽybĕ⁠ke֤m ʼeţ-laẖĕmi⁠y֙ ẖé֣leb wá⁠dá֔m wa⁠yá̇pé֨rẇ֙ ʼeţ-bĕ̇riyţi֔⁠y ʼe֖l ká̇l-ţ̇wòʻàbwòţéy⁠keֽm׃"],[44,8,"וְ⁠לֹ֥א שְׁמַרְתֶּ֖ם מִשְׁמֶ֣רֶת קָדָשָׁ֑⁠י וַ⁠תְּשִׂימ֗וּ⁠ן לְ⁠שֹׁמְרֵ֧י מִשְׁמַרְתִּ֛⁠י בְּ⁠מִקְדָּשִׁ֖⁠י לָ⁠כֶֽם׃","wĕ⁠lò֥ʼ şĕ̌marĕţė֖m mişĕ̌me֣reţ qádáşá֑̌⁠y wa⁠ţĕ̇şîym֗ẇ⁠n lĕ⁠şò̌mĕré֧y mişĕ̌marĕţi֛̇⁠y bĕ̇⁠miqĕdá̇şǐ֖⁠y lá⁠keֽm׃"],[44,9,"כֹּה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ כָּל־בֶּן־נֵכָ֗ר עֶ֤רֶל לֵב֙ וְ⁠עֶ֣רֶל בָּשָׂ֔ר לֹ֥א יָב֖וֹא אֶל־מִקְדָּשִׁ֑⁠י לְ⁠כָל־בֶּן־נֵכָ֔ר אֲשֶׁ֕ר בְּ⁠ת֖וֹךְ בְּנֵ֥י יִשְׂרָאֵֽל׃","kò̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ ká̇l-bėn-néká֗r ʻe֤rel léb֙ wĕ⁠ʻe֣rel bá̇şá̂֔r lò֥ʼ yáb֖wòʼ ʼel-miqĕdá̇şǐ֑⁠y lĕ⁠kál-bėn-néká֔r ʼàşě֕r bĕ̇⁠ţ֖wòkĕ bĕ̇né֥y yişĕ̂ráʼéֽl׃"],[44,10,"כִּ֣י אִם־הַ⁠לְוִיִּ֗ם אֲשֶׁ֤ר רָֽחֲקוּ֙ מֵֽ⁠עָלַ֔⁠י בִּ⁠תְע֤וֹת יִשְׂרָאֵל֙ אֲשֶׁ֣ר תָּע֣וּ מֵֽ⁠עָלַ֔⁠י אַחֲרֵ֖י גִּלּֽוּלֵי⁠הֶ֑ם וְ⁠נָשְׂא֖וּ עֲוֺנָֽ⁠ם׃","ki֣̇y ʼim-ha⁠lĕwiyi̇֗m ʼàşě֤r ráֽẖàqẇ֙ méֽ⁠ʻála֔⁠y bi̇⁠ţĕʻ֤wòţ yişĕ̂ráʼél֙ ʼàşě֣r ţá̇ʻ֣ẇ méֽ⁠ʻála֔⁠y ʼaẖàré֖y gi̇lֽ̇ẇléy⁠he֑m wĕ⁠náşĕ̂ʼ֖ẇ ʻàwֺnáֽ⁠m׃"],[44,11,"וְ⁠הָי֤וּ בְ⁠מִקְדָּשִׁ⁠י֙ מְשָׁ֣רְתִ֔ים פְּקֻדּוֹת֙ אֶל־שַׁעֲרֵ֣י הַ⁠בַּ֔יִת וּֽ⁠מְשָׁרְתִ֖ים אֶת־הַ⁠בָּ֑יִת הֵ֠מָּה יִשְׁחֲט֨וּ אֶת־הָ⁠עֹלָ֤ה וְ⁠אֶת־הַ⁠זֶּ֨בַח֙ לָ⁠עָ֔ם וְ⁠הֵ֛מָּה יַעַמְד֥וּ לִ⁠פְנֵי⁠הֶ֖ם לְ⁠שָֽׁרְתָֽ⁠ם׃","wĕ⁠háy֤ẇ bĕ⁠miqĕdá̇şǐ⁠y֙ mĕşá֣̌rĕţi֔ym pĕ̇quḋwòţ֙ ʼel-şǎʻàré֣y ha⁠bȧ֔yiţ ẇֽ⁠mĕşá̌rĕţi֖ym ʼeţ-ha⁠bá֑̇yiţ hé֠má̇h yişĕ̌ẖàt֨ẇ ʼeţ-há⁠ʻòlá֤h wĕ⁠ʼeţ-ha⁠zė֨baẖ֙ lá⁠ʻá֔m wĕ⁠hé֛má̇h yaʻamĕd֥ẇ li⁠pĕnéy⁠he֖m lĕ⁠şáֽ̌rĕţáֽ⁠m׃"],[44,12,"יַ֗עַן אֲשֶׁ֨ר יְשָׁרְת֤וּ אוֹתָ⁠ם֙ לִ⁠פְנֵ֣י גִלּֽוּלֵי⁠הֶ֔ם וְ⁠הָי֥וּ לְ⁠בֵֽית־יִשְׂרָאֵ֖ל לְ⁠מִכְשׁ֣וֹל עָוֺ֑ן עַל־כֵּן֩ נָשָׂ֨אתִי יָדִ֜⁠י עֲלֵי⁠הֶ֗ם נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה וְ⁠נָשְׂא֖וּ עֲוֺנָֽ⁠ם׃","ya֗ʻan ʼàşě֨r yĕşá̌rĕţ֤ẇ ʼwòţá⁠m֙ li⁠pĕné֣y gilֽ̇ẇléy⁠he֔m wĕ⁠háy֥ẇ lĕ⁠béֽyţ-yişĕ̂ráʼé֖l lĕ⁠mikĕş֣̌wòl ʻáwֺ֑n ʻal-ké̇n֩ náşá̂֨ʼţiy yádi֜⁠y ʻàléy⁠he֗m nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h wĕ⁠náşĕ̂ʼ֖ẇ ʻàwֺnáֽ⁠m׃"],[44,13,"וְ⁠לֹֽא־יִגְּשׁ֤וּ אֵלַ⁠י֙ לְ⁠כַהֵ֣ן לִ֔⁠י וְ⁠לָ⁠גֶ֨שֶׁת֙ עַל־כָּל־קָ֣דָשַׁ֔⁠י אֶל־קָדְשֵׁ֖י הַ⁠קְּדָשִׁ֑ים וְ⁠נָֽשְׂאוּ֙ כְּלִמָּתָ֔⁠ם וְ⁠תוֹעֲבוֹתָ֖⁠ם אֲשֶׁ֥ר עָשֽׂוּ׃","wĕ⁠lòֽʼ-yigĕ̇ş֤̌ẇ ʼéla⁠y֙ lĕ⁠kahé֣n li֔⁠y wĕ⁠lá⁠ge֨şěţ֙ ʻal-ká̇l-qá֣dáşǎ֔⁠y ʼel-qádĕşé֖̌y ha⁠qĕ̇dáşǐ֑ym wĕ⁠náֽşĕ̂ʼẇ֙ kĕ̇limá̇ţá֔⁠m wĕ⁠ţwòʻàbwòţá֖⁠m ʼàşě֥r ʻáşֽ̂ẇ׃"],[44,14,"וְ⁠נָתַתִּ֣י אוֹתָ֔⁠ם שֹׁמְרֵ֖י מִשְׁמֶ֣רֶת הַ⁠בָּ֑יִת לְ⁠כֹל֙ עֲבֹ֣דָת֔⁠וֹ וּ⁠לְ⁠כֹ֛ל אֲשֶׁ֥ר יֵעָשֶׂ֖ה בּֽ⁠וֹ׃פ","wĕ⁠náţaţi֣̇y ʼwòţá֔⁠m şò̌mĕré֖y mişĕ̌me֣reţ ha⁠bá֑̇yiţ lĕ⁠kòl֙ ʻàbò֣dáţ֔⁠wò ẇ⁠lĕ⁠kò֛l ʼàşě֥r yéʻáşê֖h ḃֽ⁠wò׃p"],[44,15,"וְ⁠הַ⁠כֹּהֲנִ֨ים הַ⁠לְוִיִּ֜ם בְּנֵ֣י צָד֗וֹק אֲשֶׁ֨ר שָׁמְר֜וּ אֶת־מִשְׁמֶ֤רֶת מִקְדָּשִׁ⁠י֙ בִּ⁠תְע֤וֹת בְּנֵֽי־יִשְׂרָאֵל֙ מֵֽ⁠עָלַ֔⁠י הֵ֛מָּה יִקְרְב֥וּ אֵלַ֖⁠י לְ⁠שָֽׁרְתֵ֑⁠נִי וְ⁠עָמְד֣וּ לְ⁠פָנַ֗⁠י לְ⁠הַקְרִ֥יב לִ⁠י֙ חֵ֣לֶב וָ⁠דָ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wĕ⁠ha⁠kò̇hàni֨ym ha⁠lĕwiyi̇֜m bĕ̇né֣y ẕád֗wòq ʼàşě֨r şá̌mĕr֜ẇ ʼeţ-mişĕ̌me֤reţ miqĕdá̇şǐ⁠y֙ bi̇⁠ţĕʻ֤wòţ bĕ̇néֽy-yişĕ̂ráʼél֙ méֽ⁠ʻála֔⁠y hé֛má̇h yiqĕrĕb֥ẇ ʼéla֖⁠y lĕ⁠şáֽ̌rĕţé֑⁠niy wĕ⁠ʻámĕd֣ẇ lĕ⁠pána֗⁠y lĕ⁠haqĕri֥yb li⁠y֙ ẖé֣leb wá⁠dá֔m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[44,16,"הֵ֜מָּה יָבֹ֣אוּ אֶל־מִקְדָּשִׁ֗⁠י וְ⁠הֵ֛מָּה יִקְרְב֥וּ אֶל־שֻׁלְחָנִ֖⁠י לְ⁠שָׁרְתֵ֑⁠נִי וְ⁠שָׁמְר֖וּ אֶת־מִשְׁמַרְתִּֽ⁠י׃","hé֜má̇h yábò֣ʼẇ ʼel-miqĕdá̇şǐ֗⁠y wĕ⁠hé֛má̇h yiqĕrĕb֥ẇ ʼel-şǔlĕẖáni֖⁠y lĕ⁠şá̌rĕţé֑⁠niy wĕ⁠şá̌mĕr֖ẇ ʼeţ-mişĕ̌marĕţiֽ̇⁠y׃"],[44,17,"וְ⁠הָיָ֗ה בְּ⁠בוֹאָ⁠ם֙ אֶֽל־שַׁעֲרֵי֙ הֶ⁠חָצֵ֣ר הַ⁠פְּנִימִ֔ית בִּגְדֵ֥י פִשְׁתִּ֖ים יִלְבָּ֑שׁוּ וְ⁠לֹֽא־יַעֲלֶ֤ה עֲלֵי⁠הֶם֙ צֶ֔מֶר בְּ⁠שָֽׁרְתָ֗⁠ם בְּ⁠שַׁעֲרֵ֛י הֶ⁠חָצֵ֥ר הַ⁠פְּנִימִ֖ית וָ⁠בָֽיְתָ⁠ה׃","wĕ⁠háyá֗h bĕ̇⁠bwòʼá⁠m֙ ʼeֽl-şǎʻàréy֙ he⁠ẖáẕé֣r ha⁠pĕ̇niymi֔yţ bi̇gĕdé֥y pişĕ̌ţi֖̇ym yilĕbá֑̇ş̌ẇ wĕ⁠lòֽʼ-yaʻàle֤h ʻàléy⁠hem֙ ẕe֔mer bĕ̇⁠şáֽ̌rĕţá֗⁠m bĕ̇⁠şǎʻàré֛y he⁠ẖáẕé֥r ha⁠pĕ̇niymi֖yţ wá⁠báֽyĕţá⁠h׃"],[44,18,"פַּאֲרֵ֤י פִשְׁתִּים֙ יִהְי֣וּ עַל־רֹאשָׁ֔⁠ם וּ⁠מִכְנְסֵ֣י פִשְׁתִּ֔ים יִהְי֖וּ עַל־מָתְנֵי⁠הֶ֑ם לֹ֥א יַחְגְּר֖וּ בַּ⁠יָּֽזַע׃","pȧʼàré֤y pişĕ̌ţi̇ym֙ yihĕy֣ẇ ʻal-ròʼşá̌֔⁠m ẇ⁠mikĕnĕsé֣y pişĕ̌ţi̇֔ym yihĕy֖ẇ ʻal-máţĕnéy⁠he֑m lò֥ʼ yaẖĕgĕ̇r֖ẇ bȧ⁠yáֽ̇zaʻ׃"],[44,19,"וּ֠⁠בְ⁠צֵאתָ⁠ם אֶל־הֶ⁠חָצֵ֨ר הַ⁠חִיצוֹנָ֜ה אֶל־הֶ⁠חָצֵ֣ר הַ⁠חִיצוֹנָה֮ אֶל־הָ⁠עָם֒ יִפְשְׁט֣וּ אֶת־בִּגְדֵי⁠הֶ֗ם אֲשֶׁר־הֵ֨מָּה֙ מְשָׁרְתִ֣ם בָּ֔⁠ם וְ⁠הִנִּ֥יחוּ אוֹתָ֖⁠ם בְּ⁠לִֽשְׁכֹ֣ת הַ⁠קֹּ֑דֶשׁ וְ⁠לָֽבְשׁוּ֙ בְּגָדִ֣ים אֲחֵרִ֔ים וְ⁠לֹֽא־יְקַדְּשׁ֥וּ אֶת־הָ⁠עָ֖ם בְּ⁠בִגְדֵי⁠הֶֽם׃","ẇ֠⁠bĕ⁠ẕéʼţá⁠m ʼel-he⁠ẖáẕé֨r ha⁠ẖiyẕwòná֜h ʼel-he⁠ẖáẕé֣r ha⁠ẖiyẕwònáh֮ ʼel-há⁠ʻám֒ yipĕşĕ̌t֣ẇ ʼeţ-bi̇gĕdéy⁠he֗m ʼàşěr-hé֨má̇h֙ mĕşá̌rĕţi֣m bá̇֔⁠m wĕ⁠hini֥̇yẖẇ ʼwòţá֖⁠m bĕ̇⁠liֽşĕ̌kò֣ţ ha⁠qò֑̇deş̌ wĕ⁠láֽbĕş̌ẇ֙ bĕ̇gádi֣ym ʼàẖéri֔ym wĕ⁠lòֽʼ-yĕqadĕ̇ş֥̌ẇ ʼeţ-há⁠ʻá֖m bĕ̇⁠bigĕdéy⁠heֽm׃"],[44,20,"וְ⁠רֹאשָׁ⁠ם֙ לֹ֣א יְגַלֵּ֔חוּ וּ⁠פֶ֖רַע לֹ֣א יְשַׁלֵּ֑חוּ כָּס֥וֹם יִכְסְמ֖וּ אֶת־רָאשֵׁי⁠הֶֽם׃","wĕ⁠ròʼşá̌⁠m֙ lò֣ʼ yĕgalé̇֔ẖẇ ẇ⁠pe֖raʻ lò֣ʼ yĕşǎlé֑̇ẖẇ ká̇s֥wòm yikĕsĕm֖ẇ ʼeţ-ráʼşé̌y⁠heֽm׃"],[44,21,"וְ⁠יַ֥יִן לֹֽא־יִשְׁתּ֖וּ כָּל־כֹּהֵ֑ן בְּ⁠בוֹאָ֖⁠ם אֶל־הֶ⁠חָצֵ֥ר הַ⁠פְּנִימִֽית׃","wĕ⁠ya֥yin lòֽʼ-yişĕ̌ţ֖̇ẇ ká̇l-kò̇hé֑n bĕ̇⁠bwòʼá֖⁠m ʼel-he⁠ẖáẕé֥r ha⁠pĕ̇niymiֽyţ׃"],[44,22,"וְ⁠אַלְמָנָה֙ וּ⁠גְרוּשָׁ֔ה לֹֽא־יִקְח֥וּ לָ⁠הֶ֖ם לְ⁠נָשִׁ֑ים כִּ֣י אִם־בְּתוּלֹ֗ת מִ⁠זֶּ֨רַע֙ בֵּ֣ית יִשְׂרָאֵ֔ל וְ⁠הָֽ⁠אַלְמָנָה֙ אֲשֶׁ֣ר תִּֽהְיֶ֣ה אַלְמָנָ֔ה מִ⁠כֹּהֵ֖ן יִקָּֽחוּ׃","wĕ⁠ʼalĕmánáh֙ ẇ⁠gĕrẇşá̌֔h lòֽʼ-yiqĕẖ֥ẇ lá⁠he֖m lĕ⁠náşǐ֑ym ki֣̇y ʼim-bĕ̇ţẇlò֗ţ mi⁠zė֨raʻ֙ bé֣̇yţ yişĕ̂ráʼé֔l wĕ⁠háֽ⁠ʼalĕmánáh֙ ʼàşě֣r ţiֽ̇hĕye֣h ʼalĕmáná֔h mi⁠kò̇hé֖n yiqáֽ̇ẖẇ׃"],[44,23,"וְ⁠אֶת־עַמִּ֣⁠י יוֹר֔וּ בֵּ֥ין קֹ֖דֶשׁ לְ⁠חֹ֑ל וּ⁠בֵין־טָמֵ֥א לְ⁠טָה֖וֹר יוֹדִעֻֽ⁠ם׃","wĕ⁠ʼeţ-ʻami֣̇⁠y ywòr֔ẇ bé֥̇yn qò֖deş̌ lĕ⁠ẖò֑l ẇ⁠béyn-támé֥ʼ lĕ⁠táh֖wòr ywòdiʻuֽ⁠m׃"],[44,24,"וְ⁠עַל־רִ֗יב הֵ֚מָּה יַעַמְד֣וּ ל⁠שפט בְּ⁠מִשְׁפָּטַ֖⁠י ו⁠שפט⁠הו וְ⁠אֶת־תּוֹרֹתַ֤⁠י וְ⁠אֶת־חֻקֹּתַ⁠י֙ בְּ⁠כָל־מוֹעֲדַ֣⁠י יִשְׁמֹ֔רוּ וְ⁠אֶת־שַׁבְּתוֹתַ֖⁠י יְקַדֵּֽשׁוּ׃","wĕ⁠ʻal-ri֗yb hé֚má̇h yaʻamĕd֣ẇ l⁠şpt bĕ̇⁠mişĕ̌pá̇ta֖⁠y w⁠şpt⁠hw wĕ⁠ʼeţ-ţ̇wòròţa֤⁠y wĕ⁠ʼeţ-ẖuqò̇ţa⁠y֙ bĕ̇⁠kál-mwòʻàda֣⁠y yişĕ̌mò֔rẇ wĕ⁠ʼeţ-şǎbĕ̇ţwòţa֖⁠y yĕqadéֽ̇ş̌ẇ׃"],[44,25,"וְ⁠אֶל־מֵ֣ת אָדָ֔ם לֹ֥א יָב֖וֹא לְ⁠טָמְאָ֑ה כִּ֣י אִם־לְ⁠אָ֡ב וּ֠⁠לְ⁠אֵם וּ⁠לְ⁠בֵ֨ן וּ⁠לְ⁠בַ֜ת לְ⁠אָ֗ח וּ⁠לְ⁠אָח֛וֹת אֲשֶֽׁר־לֹא־הָיְתָ֥ה לְ⁠אִ֖ישׁ יִטַּמָּֽאוּ׃","wĕ⁠ʼel-mé֣ţ ʼádá֔m lò֥ʼ yáb֖wòʼ lĕ⁠támĕʼá֑h ki֣̇y ʼim-lĕ⁠ʼá֡b ẇ֠⁠lĕ⁠ʼém ẇ⁠lĕ⁠bé֨n ẇ⁠lĕ⁠ba֜ţ lĕ⁠ʼá֗ẖ ẇ⁠lĕ⁠ʼáẖ֛wòţ ʼàşěֽr-lòʼ-háyĕţá֥h lĕ⁠ʼi֖yş̌ yitȧmáֽ̇ʼẇ׃"],[44,26,"וְ⁠אַחֲרֵ֖י טָֽהֳרָת֑⁠וֹ שִׁבְעַ֥ת יָמִ֖ים יִסְפְּרוּ־לֽ⁠וֹ׃","wĕ⁠ʼaẖàré֖y táֽhoráţ֑⁠wò şǐbĕʻa֥ţ yámi֖ym yisĕpĕ̇rẇ-lֽ⁠wò׃"],[44,27,"וּ⁠בְ⁠יוֹם֩ בֹּא֨⁠וֹ אֶל־הַ⁠קֹּ֜דֶשׁ אֶל־הֶ⁠חָצֵ֤ר הַ⁠פְּנִימִית֙ לְ⁠שָׁרֵ֣ת בַּ⁠קֹּ֔דֶשׁ יַקְרִ֖יב חַטָּאת֑⁠וֹ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","ẇ⁠bĕ⁠ywòm֩ bò̇ʼ֨⁠wò ʼel-ha⁠qò̇֜deş̌ ʼel-he⁠ẖáẕé֤r ha⁠pĕ̇niymiyţ֙ lĕ⁠şá̌ré֣ţ bȧ⁠qò̇֔deş̌ yaqĕri֖yb ẖatá̇ʼţ֑⁠wò nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[44,28,"וְ⁠הָיְתָ֤ה לָ⁠הֶם֙ לְֽ⁠נַחֲלָ֔ה אֲנִ֖י נַֽחֲלָתָ֑⁠ם וַ⁠אֲחֻזָּ֗ה לֹֽא־תִתְּנ֤וּ לָ⁠הֶם֙ בְּ⁠יִשְׂרָאֵ֔ל אֲנִ֖י אֲחֻזָּתָֽ⁠ם׃","wĕ⁠háyĕţá֤h lá⁠hem֙ lĕֽ⁠naẖàlá֔h ʼàni֖y naֽẖàláţá֑⁠m wa⁠ʼàẖuzá̇֗h lòֽʼ-ţiţĕ̇n֤ẇ lá⁠hem֙ bĕ̇⁠yişĕ̂ráʼé֔l ʼàni֖y ʼàẖuzá̇ţáֽ⁠m׃"],[44,29,"הַ⁠מִּנְחָה֙ וְ⁠הַ⁠חַטָּ֣את וְ⁠הָ⁠אָשָׁ֔ם הֵ֖מָּה יֹֽאכְל֑וּ⁠ם וְ⁠כָל־חֵ֥רֶם בְּ⁠יִשְׂרָאֵ֖ל לָ⁠הֶ֥ם יִהְיֶֽה׃","ha⁠mi̇nĕẖáh֙ wĕ⁠ha⁠ẖatá֣̇ʼţ wĕ⁠há⁠ʼáşá̌֔m hé֖má̇h yòֽʼkĕl֑ẇ⁠m wĕ⁠kál-ẖé֥rem bĕ̇⁠yişĕ̂ráʼé֖l lá⁠he֥m yihĕyeֽh׃"],[44,30,"וְ⁠רֵאשִׁית֩ כָּל־בִּכּ֨וּרֵי כֹ֜ל וְ⁠כָל־תְּר֣וּמַת כֹּ֗ל מִ⁠כֹּל֙ תְּרוּמ֣וֹתֵי⁠כֶ֔ם לַ⁠כֹּהֲנִ֖ים יִֽהְיֶ֑ה וְ⁠רֵאשִׁ֤ית עֲרִסֽוֹתֵי⁠כֶם֙ תִּתְּנ֣וּ לַ⁠כֹּהֵ֔ן לְ⁠הָנִ֥יחַ בְּרָכָ֖ה אֶל־בֵּיתֶֽ⁠ךָ׃","wĕ⁠réʼşǐyţ֩ ká̇l-bi̇k̇֨ẇréy kò֜l wĕ⁠kál-ţĕ̇r֣ẇmaţ kò̇֗l mi⁠kò̇l֙ ţĕ̇rẇm֣wòţéy⁠ke֔m la⁠kò̇hàni֖ym yiֽhĕye֑h wĕ⁠réʼşǐ֤yţ ʻàrisֽwòţéy⁠kem֙ ţi̇ţĕ̇n֣ẇ la⁠kò̇hé֔n lĕ⁠háni֥yẖa bĕ̇ráká֖h ʼel-bé̇yţeֽ⁠ká׃"],[44,31,"כָּל־נְבֵלָה֙ וּ⁠טְרֵפָ֔ה מִן־הָ⁠ע֖וֹף וּ⁠מִן־הַ⁠בְּהֵמָ֑ה לֹ֥א יֹאכְל֖וּ הַ⁠כֹּהֲנִֽים׃פ","ká̇l-nĕbéláh֙ ẇ⁠tĕrépá֔h min-há⁠ʻ֖wòp ẇ⁠min-ha⁠bĕ̇hémá֑h lò֥ʼ yòʼkĕl֖ẇ ha⁠kò̇hàniֽym׃p"],[45,1,"וּ⁠בְ⁠הַפִּֽילְ⁠כֶ֨ם אֶת־הָ⁠אָ֜רֶץ בְּ⁠נַחֲלָ֗ה תָּרִימוּ֩ תְרוּמָ֨ה לַ⁠יהוָ֥ה ׀ קֹדֶשׁ֮ מִן־הָ⁠אָרֶץ֒ אֹ֗רֶךְ חֲמִשָּׁ֨ה וְ⁠עֶשְׂרִ֥ים אֶ֨לֶף֙ אֹ֔רֶךְ וְ⁠רֹ֖חַב עֲשָׂ֣רָה אָ֑לֶף קֹדֶשׁ־ה֥וּא בְ⁠כָל־גְּבוּלָ֖⁠הּ סָבִֽיב׃","ẇ⁠bĕ⁠hapiֽ̇ylĕ⁠ke֨m ʼeţ-há⁠ʼá֜reẕ bĕ̇⁠naẖàlá֗h ţá̇riymẇ֩ ţĕrẇmá֨h la⁠yhwá֥h ׀ qòdeş֮̌ min-há⁠ʼáreẕ֒ ʼò֗rekĕ ẖàmişá̇̌֨h wĕ⁠ʻeşĕ̂ri֥ym ʼe֨lep֙ ʼò֔rekĕ wĕ⁠rò֖ẖab ʻàşá֣̂ráh ʼá֑lep qòdeş̌-h֥ẇʼ bĕ⁠kál-gĕ̇bẇlá֖⁠ḣ sábiֽyb׃"],[45,2,"יִהְיֶ֤ה מִ⁠זֶּה֙ אֶל־הַ⁠קֹּ֔דֶשׁ חֲמֵ֥שׁ מֵא֛וֹת בַּ⁠חֲמֵ֥שׁ מֵא֖וֹת מְרֻבָּ֣ע סָבִ֑יב וַ⁠חֲמִשִּׁ֣ים אַמָּ֔ה מִגְרָ֥שׁ ל֖⁠וֹ סָבִֽיב׃","yihĕye֤h mi⁠zėh֙ ʼel-ha⁠qò̇֔deş̌ ẖàmé֥ş̌ méʼ֛wòţ bȧ⁠ẖàmé֥ş̌ méʼ֖wòţ mĕrubá֣̇ʻ sábi֑yb wa⁠ẖàmişi֣̇̌ym ʼamá̇֔h migĕrá֥ş̌ l֖⁠wò sábiֽyb׃"],[45,3,"וּ⁠מִן־הַ⁠מִּדָּ֤ה הַ⁠זֹּאת֙ תָּמ֔וֹד אֹ֗רֶךְ חמש וְ⁠עֶשְׂרִים֙ אֶ֔לֶף וְ⁠רֹ֖חַב עֲשֶׂ֣רֶת אֲלָפִ֑ים וּ⁠בֽ⁠וֹ־יִהְיֶ֥ה הַ⁠מִּקְדָּ֖שׁ קֹ֥דֶשׁ קָדָשִֽׁים׃","ẇ⁠min-ha⁠mi̇dá֤̇h ha⁠zò̇ʼţ֙ ţá̇m֔wòd ʼò֗rekĕ ẖmş wĕ⁠ʻeşĕ̂riym֙ ʼe֔lep wĕ⁠rò֖ẖab ʻàşê֣reţ ʼàlápi֑ym ẇ⁠bֽ⁠wò-yihĕye֥h ha⁠mi̇qĕdá֖̇ş̌ qò֥deş̌ qádáşǐֽym׃"],[45,4,"קֹ֣דֶשׁ מִן־הָ⁠אָ֜רֶץ ה֗וּא לַ⁠כֹּ֨הֲנִ֜ים מְשָׁרְתֵ֤י הַ⁠מִּקְדָּשׁ֙ יִֽהְיֶ֔ה הַ⁠קְּרֵבִ֖ים לְ⁠שָׁרֵ֣ת אֶת־יְהוָ֑ה וְ⁠הָיָ֨ה לָ⁠הֶ֤ם מָקוֹם֙ לְ⁠בָ֣תִּ֔ים וּ⁠מִקְדָּ֖שׁ לַ⁠מִּקְדָּֽשׁ׃","qò֣deş̌ min-há⁠ʼá֜reẕ h֗ẇʼ la⁠kò̇֨hàni֜ym mĕşá̌rĕţé֤y ha⁠mi̇qĕdá̇ş̌֙ yiֽhĕye֔h ha⁠qĕ̇rébi֖ym lĕ⁠şá̌ré֣ţ ʼeţ-yĕhwá֑h wĕ⁠háyá֨h lá⁠he֤m máqwòm֙ lĕ⁠bá֣ţi̇֔ym ẇ⁠miqĕdá֖̇ş̌ la⁠mi̇qĕdáֽ̇ş̌׃"],[45,5,"וַ⁠חֲמִשָּׁ֨ה וְ⁠עֶשְׂרִ֥ים אֶ֨לֶף֙ אֹ֔רֶךְ וַ⁠עֲשֶׂ֥רֶת אֲלָפִ֖ים רֹ֑חַב יהיה לַ⁠לְוִיִּם֩ מְשָׁרְתֵ֨י הַ⁠בַּ֧יִת לָ⁠הֶ֛ם לַ⁠אֲחֻזָּ֖ה עֶשְׂרִ֥ים לְשָׁכֹֽת׃","wa⁠ẖàmişá̇̌֨h wĕ⁠ʻeşĕ̂ri֥ym ʼe֨lep֙ ʼò֔rekĕ wa⁠ʻàşê֥reţ ʼàlápi֖ym rò֑ẖab yhyh la⁠lĕwiyi̇m֩ mĕşá̌rĕţé֨y ha⁠bȧ֧yiţ lá⁠he֛m la⁠ʼàẖuzá֖̇h ʻeşĕ̂ri֥ym lĕşá̌kòֽţ׃"],[45,6,"וַ⁠אֲחֻזַּ֨ת הָ⁠עִ֜יר תִּתְּנ֗וּ חֲמֵ֤שֶׁת אֲלָפִים֙ רֹ֔חַב וְ⁠אֹ֗רֶךְ חֲמִשָּׁ֤ה וְ⁠עֶשְׂרִים֙ אֶ֔לֶף לְ⁠עֻמַּ֖ת תְּרוּמַ֣ת הַ⁠קֹּ֑דֶשׁ לְ⁠כָל־בֵּ֥ית יִשְׂרָאֵ֖ל יִהְיֶֽה׃","wa⁠ʼàẖuzȧ֨ţ há⁠ʻi֜yr ţi̇ţĕ̇n֗ẇ ẖàmé֤şěţ ʼàlápiym֙ rò֔ẖab wĕ⁠ʼò֗rekĕ ẖàmişá֤̇̌h wĕ⁠ʻeşĕ̂riym֙ ʼe֔lep lĕ⁠ʻumȧ֖ţ ţĕ̇rẇma֣ţ ha⁠qò֑̇deş̌ lĕ⁠kál-bé֥̇yţ yişĕ̂ráʼé֖l yihĕyeֽh׃"],[45,7,"וְ⁠לַ⁠נָּשִׂ֡יא מִ⁠זֶּ֣ה וּ⁠מִ⁠זֶּה֩ לִ⁠תְרוּמַ֨ת הַ⁠קֹּ֜דֶשׁ וְ⁠לַ⁠אֲחֻזַּ֣ת הָ⁠עִ֗יר אֶל־פְּנֵ֤י תְרֽוּמַת־הַ⁠קֹּ֨דֶשׁ֙ וְ⁠אֶל־פְּנֵי֙ אֲחֻזַּ֣ת הָ⁠עִ֔יר מִ⁠פְּאַת־יָ֣ם יָ֔מָּ⁠ה וּ⁠מִ⁠פְּאַת־קֵ֖דְמָ⁠ה קָדִ֑ימָ⁠ה וְ⁠אֹ֗רֶךְ לְ⁠עֻמּוֹת֙ אַחַ֣ד הַ⁠חֲלָקִ֔ים מִ⁠גְּב֥וּל יָ֖ם אֶל־גְּב֥וּל קָדִֽימָ⁠ה׃","wĕ⁠la⁠ná̇şî֡yʼ mi⁠zė֣h ẇ⁠mi⁠zėh֩ li⁠ţĕrẇma֨ţ ha⁠qò̇֜deş̌ wĕ⁠la⁠ʼàẖuzȧ֣ţ há⁠ʻi֗yr ʼel-pĕ̇né֤y ţĕrֽẇmaţ-ha⁠qò̇֨deş̌֙ wĕ⁠ʼel-pĕ̇néy֙ ʼàẖuzȧ֣ţ há⁠ʻi֔yr mi⁠pĕ̇ʼaţ-yá֣m yá֔má̇⁠h ẇ⁠mi⁠pĕ̇ʼaţ-qé֖dĕmá⁠h qádi֑ymá⁠h wĕ⁠ʼò֗rekĕ lĕ⁠ʻuṁwòţ֙ ʼaẖa֣d ha⁠ẖàláqi֔ym mi⁠gĕ̇b֥ẇl yá֖m ʼel-gĕ̇b֥ẇl qádiֽymá⁠h׃"],[45,8,"לָ⁠אָ֛רֶץ יִֽהְיֶה־לּ֥⁠וֹ לַֽ⁠אֲחֻזָּ֖ה בְּ⁠יִשְׂרָאֵ֑ל וְ⁠לֹא־יוֹנ֨וּ ע֤וֹד נְשִׂיאַ⁠י֙ אֶת־עַמִּ֔⁠י וְ⁠הָ⁠אָ֛רֶץ יִתְּנ֥וּ לְ⁠בֵֽית־יִשְׂרָאֵ֖ל לְ⁠שִׁבְטֵי⁠הֶֽם׃ס","lá⁠ʼá֛reẕ yiֽhĕyeh-l֥̇⁠wò laֽ⁠ʼàẖuzá֖̇h bĕ̇⁠yişĕ̂ráʼé֑l wĕ⁠lòʼ-ywòn֨ẇ ʻ֤wòd nĕşîyʼa⁠y֙ ʼeţ-ʻami̇֔⁠y wĕ⁠há⁠ʼá֛reẕ yiţĕ̇n֥ẇ lĕ⁠béֽyţ-yişĕ̂ráʼé֖l lĕ⁠şǐbĕtéy⁠heֽm׃s"],[45,9,"כֹּֽה־אָמַ֞ר אֲדֹנָ֣⁠י יְהוִ֗ה רַב־לָ⁠כֶם֙ נְשִׂיאֵ֣י יִשְׂרָאֵ֔ל חָמָ֤ס וָ⁠שֹׁד֙ הָסִ֔ירוּ וּ⁠מִשְׁפָּ֥ט וּ⁠צְדָקָ֖ה עֲשׂ֑וּ הָרִ֤ימוּ גְרֻשֹֽׁתֵי⁠כֶם֙ מֵ⁠עַ֣ל עַמִּ֔⁠י נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","kòֽ̇h-ʼáma֞r ʼàdòná֣⁠y yĕhwi֗h rab-lá⁠kem֙ nĕşîyʼé֣y yişĕ̂ráʼé֔l ẖámá֤s wá⁠şò̌d֙ hási֔yrẇ ẇ⁠mişĕ̌pá֥̇t ẇ⁠ẕĕdáqá֖h ʻàş֑̂ẇ hári֤ymẇ gĕruşòֽ̌ţéy⁠kem֙ mé⁠ʻa֣l ʻami̇֔⁠y nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[45,10,"מֹֽאזְנֵי־צֶ֧דֶק וְ⁠אֵֽיפַת־צֶ֛דֶק וּ⁠בַת־צֶ֖דֶק יְהִ֥י לָ⁠כֶֽם׃","mòֽʼzĕnéy-ẕe֧deq wĕ⁠ʼéֽypaţ-ẕe֛deq ẇ⁠baţ-ẕe֖deq yĕhi֥y lá⁠keֽm׃"],[45,11,"הָ⁠אֵיפָ֣ה וְ⁠הַ⁠בַּ֗ת תֹּ֤כֶן אֶחָד֙ יִֽהְיֶ֔ה לָ⁠שֵׂ֕את מַעְשַׂ֥ר הַ⁠חֹ֖מֶר הַ⁠בָּ֑ת וַ⁠עֲשִׂירִ֤ת הַ⁠חֹ֨מֶר֙ הָֽ⁠אֵיפָ֔ה אֶל־הַ⁠חֹ֖מֶר יִהְיֶ֥ה מַתְכֻּנְתּֽ⁠וֹ׃","há⁠ʼéypá֣h wĕ⁠ha⁠bȧ֗ţ ţò֤̇ken ʼeẖád֙ yiֽhĕye֔h lá⁠şé̂֕ʼţ maʻĕşâ֥r ha⁠ẖò֖mer ha⁠bá֑̇ţ wa⁠ʻàşîyri֤ţ ha⁠ẖò֨mer֙ háֽ⁠ʼéypá֔h ʼel-ha⁠ẖò֖mer yihĕye֥h maţĕku̇nĕţֽ̇⁠wò׃"],[45,12,"וְ⁠הַ⁠שֶּׁ֖קֶל עֶשְׂרִ֣ים גֵּרָ֑ה עֶשְׂרִ֨ים שְׁקָלִ֜ים חֲמִשָּׁ֧ה וְ⁠עֶשְׂרִ֣ים שְׁקָלִ֗ים עֲשָׂרָ֤ה וַ⁠חֲמִשָּׁה֙ שֶׁ֔קֶל הַ⁠מָּנֶ֖ה יִֽהְיֶ֥ה לָ⁠כֶֽם׃","wĕ⁠ha⁠şė֖̌qel ʻeşĕ̂ri֣ym gé̇rá֑h ʻeşĕ̂ri֨ym şĕ̌qáli֜ym ẖàmişá֧̇̌h wĕ⁠ʻeşĕ̂ri֣ym şĕ̌qáli֗ym ʻàşá̂rá֤h wa⁠ẖàmişá̇̌h֙ şě֔qel ha⁠má̇ne֖h yiֽhĕye֥h lá⁠keֽm׃"],[45,13,"זֹ֥את הַ⁠תְּרוּמָ֖ה אֲשֶׁ֣ר תָּרִ֑ימוּ שִׁשִּׁ֤ית הָֽ⁠אֵיפָה֙ מֵ⁠חֹ֣מֶר הַֽ⁠חִטִּ֔ים וְ⁠שִׁשִּׁיתֶם֙ הָֽ⁠אֵיפָ֔ה מֵ⁠חֹ֖מֶר הַ⁠שְּׂעֹרִֽים׃","zò֥ʼţ ha⁠ţĕ̇rẇmá֖h ʼàşě֣r ţá̇ri֑ymẇ şǐşi֤̇̌yţ háֽ⁠ʼéypáh֙ mé⁠ẖò֣mer haֽ⁠ẖiti̇֔ym wĕ⁠şǐşi̇̌yţem֙ háֽ⁠ʼéypá֔h mé⁠ẖò֖mer ha⁠şĕ̇̂ʻòriֽym׃"],[45,14,"וְ⁠חֹ֨ק הַ⁠שֶּׁ֜מֶן הַ⁠בַּ֣ת הַ⁠שֶּׁ֗מֶן מַעְשַׂ֤ר הַ⁠בַּת֙ מִן־הַ⁠כֹּ֔ר עֲשֶׂ֥רֶת הַ⁠בַּתִּ֖ים חֹ֑מֶר כִּֽי־עֲשֶׂ֥רֶת הַ⁠בַּתִּ֖ים חֹֽמֶר׃","wĕ⁠ẖò֨q ha⁠şė̌֜men ha⁠bȧ֣ţ ha⁠şė̌֗men maʻĕşâ֤r ha⁠bȧţ֙ min-ha⁠kò̇֔r ʻàşê֥reţ ha⁠bȧţi֖̇ym ẖò֑mer kiֽ̇y-ʻàşê֥reţ ha⁠bȧţi֖̇ym ẖòֽmer׃"],[45,15,"וְ⁠שֶׂה־אַחַ֨ת מִן־הַ⁠צֹּ֤אן מִן־הַ⁠מָּאתַ֨יִם֙ מִ⁠מַּשְׁקֵ֣ה יִשְׂרָאֵ֔ל לְ⁠מִנְחָ֖ה וּ⁠לְ⁠עוֹלָ֣ה וְ⁠לִ⁠שְׁלָמִ֑ים לְ⁠כַפֵּ֣ר עֲלֵי⁠הֶ֔ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wĕ⁠şêh-ʼaẖa֨ţ min-ha⁠ẕò֤̇ʼn min-ha⁠má̇ʼţa֨yim֙ mi⁠mȧşĕ̌qé֣h yişĕ̂ráʼé֔l lĕ⁠minĕẖá֖h ẇ⁠lĕ⁠ʻwòlá֣h wĕ⁠li⁠şĕ̌lámi֑ym lĕ⁠kapé֣̇r ʻàléy⁠he֔m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[45,16,"כֹּ֚ל הָ⁠עָ֣ם הָ⁠אָ֔רֶץ יִהְי֖וּ אֶל־הַ⁠תְּרוּמָ֣ה הַ⁠זֹּ֑את לַ⁠נָּשִׂ֖יא בְּ⁠יִשְׂרָאֵֽל׃","kò֚̇l há⁠ʻá֣m há⁠ʼá֔reẕ yihĕy֖ẇ ʼel-ha⁠ţĕ̇rẇmá֣h ha⁠zò֑̇ʼţ la⁠ná̇şî֖yʼ bĕ̇⁠yişĕ̂ráʼéֽl׃"],[45,17,"וְ⁠עַֽל־הַ⁠נָּשִׂ֣יא יִהְיֶ֗ה הָ⁠עוֹל֣וֹת וְ⁠הַ⁠מִּנְחָה֮ וְ⁠הַ⁠נֵּסֶךְ֒ בַּ⁠חַגִּ֤ים וּ⁠בֶ⁠חֳדָשִׁים֙ וּ⁠בַ⁠שַּׁבָּת֔וֹת בְּ⁠כָֽל־מוֹעֲדֵ֖י בֵּ֣ית יִשְׂרָאֵ֑ל הֽוּא־יַעֲשֶׂ֞ה אֶת־הַ⁠חַטָּ֣את וְ⁠אֶת־הַ⁠מִּנְחָ֗ה וְ⁠אֶת־הָֽ⁠עוֹלָה֙ וְ⁠אֶת־הַ⁠שְּׁלָמִ֔ים לְ⁠כַפֵּ֖ר בְּעַ֥ד בֵּֽית־יִשְׂרָאֵֽל׃ס","wĕ⁠ʻaֽl-ha⁠ná̇şî֣yʼ yihĕye֗h há⁠ʻwòl֣wòţ wĕ⁠ha⁠mi̇nĕẖáh֮ wĕ⁠ha⁠né̇sekĕ֒ bȧ⁠ẖagi֤̇ym ẇ⁠be⁠ẖodáşǐym֙ ẇ⁠ba⁠şȧ̌bá̇ţ֔wòţ bĕ̇⁠káֽl-mwòʻàdé֖y bé֣̇yţ yişĕ̂ráʼé֑l hֽẇʼ-yaʻàşê֞h ʼeţ-ha⁠ẖatá֣̇ʼţ wĕ⁠ʼeţ-ha⁠mi̇nĕẖá֗h wĕ⁠ʼeţ-háֽ⁠ʻwòláh֙ wĕ⁠ʼeţ-ha⁠şĕ̇̌lámi֔ym lĕ⁠kapé֖̇r bĕ̇ʻa֥d béֽ̇yţ-yişĕ̂ráʼéֽl׃s"],[45,18,"כֹּה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ בָּֽ⁠רִאשׁוֹן֙ בְּ⁠אֶחָ֣ד לַ⁠חֹ֔דֶשׁ תִּקַּ֥ח פַּר־בֶּן־בָּקָ֖ר תָּמִ֑ים וְ⁠חִטֵּאתָ֖ אֶת־הַ⁠מִּקְדָּֽשׁ׃","kò̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ báֽ̇⁠riʼş̌wòn֙ bĕ̇⁠ʼeẖá֣d la⁠ẖò֔deş̌ ţi̇qȧ֥ẖ pȧr-bėn-bá̇qá֖r ţá̇mi֑ym wĕ⁠ẖité̇ʼţá֖ ʼeţ-ha⁠mi̇qĕdáֽ̇ş̌׃"],[45,19,"וְ⁠לָקַ֨ח הַ⁠כֹּהֵ֜ן מִ⁠דַּ֣ם הַ⁠חַטָּ֗את וְ⁠נָתַן֙ אֶל־מְזוּזַ֣ת הַ⁠בַּ֔יִת וְ⁠אֶל־אַרְבַּ֛ע פִּנּ֥וֹת הָ⁠עֲזָרָ֖ה לַ⁠מִּזְבֵּ֑חַ וְ⁠עַ֨ל־מְזוּזַ֔ת שַׁ֖עַר הֶ⁠חָצֵ֥ר הַ⁠פְּנִימִֽית׃","wĕ⁠láqa֨ẖ ha⁠kò̇hé֜n mi⁠dȧ֣m ha⁠ẖatá̇֗ʼţ wĕ⁠náţan֙ ʼel-mĕzẇza֣ţ ha⁠bȧ֔yiţ wĕ⁠ʼel-ʼarĕbȧ֛ʻ pi̇ṅ֥wòţ há⁠ʻàzárá֖h la⁠mi̇zĕbé֑̇ẖa wĕ⁠ʻa֨l-mĕzẇza֔ţ şǎ֖ʻar he⁠ẖáẕé֥r ha⁠pĕ̇niymiֽyţ׃"],[45,20,"וְ⁠כֵ֤ן תַּֽעֲשֶׂה֙ בְּ⁠שִׁבְעָ֣ה בַ⁠חֹ֔דֶשׁ מֵ⁠אִ֥ישׁ שֹׁגֶ֖ה וּ⁠מִ⁠פֶּ֑תִי וְ⁠כִפַּרְתֶּ֖ם אֶת־הַ⁠בָּֽיִת׃","wĕ⁠ké֤n ţȧֽʻàşêh֙ bĕ̇⁠şǐbĕʻá֣h ba⁠ẖò֔deş̌ mé⁠ʼi֥yş̌ şò̌ge֖h ẇ⁠mi⁠pė֑ţiy wĕ⁠kipȧrĕţė֖m ʼeţ-ha⁠báֽ̇yiţ׃"],[45,21,"בָּ֠⁠רִאשׁוֹן בְּ⁠אַרְבָּעָ֨ה עָשָׂ֥ר יוֹם֙ לַ⁠חֹ֔דֶשׁ יִהְיֶ֥ה לָ⁠כֶ֖ם הַ⁠פָּ֑סַח חָ֕ג שְׁבֻע֣וֹת יָמִ֔ים מַצּ֖וֹת יֵאָכֵֽל׃","bá̇֠⁠riʼş̌wòn bĕ̇⁠ʼarĕbá̇ʻá֨h ʻáşá֥̂r ywòm֙ la⁠ẖò֔deş̌ yihĕye֥h lá⁠ke֖m ha⁠pá֑̇saẖ ẖá֕g şĕ̌buʻ֣wòţ yámi֔ym maẕ֖̇wòţ yéʼákéֽl׃"],[45,22,"וְ⁠עָשָׂ֤ה הַ⁠נָּשִׂיא֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא בַּעֲד֕⁠וֹ וּ⁠בְעַ֖ד כָּל־עַ֣ם הָ⁠אָ֑רֶץ פַּ֖ר חַטָּֽאת׃","wĕ⁠ʻáşá֤̂h ha⁠ná̇şîyʼ֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ bȧʻàd֕⁠wò ẇ⁠bĕʻa֖d ká̇l-ʻa֣m há⁠ʼá֑reẕ pȧ֖r ẖatáֽ̇ʼţ׃"],[45,23,"וְ⁠שִׁבְעַ֨ת יְמֵֽי־הֶ⁠חָ֜ג יַעֲשֶׂ֧ה עוֹלָ֣ה לַֽ⁠יהוָ֗ה שִׁבְעַ֣ת פָּ֠רִים וְ⁠שִׁבְעַ֨ת אֵילִ֤ים תְּמִימִם֙ לַ⁠יּ֔וֹם שִׁבְעַ֖ת הַ⁠יָּמִ֑ים וְ⁠חַטָּ֕את שְׂעִ֥יר עִזִּ֖ים לַ⁠יּֽוֹם׃","wĕ⁠şǐbĕʻa֨ţ yĕméֽy-he⁠ẖá֜g yaʻàşê֧h ʻwòlá֣h laֽ⁠yhwá֗h şǐbĕʻa֣ţ pá̇֠riym wĕ⁠şǐbĕʻa֨ţ ʼéyli֤ym ţĕ̇miymim֙ la⁠ẏ֔wòm şǐbĕʻa֖ţ ha⁠yá̇mi֑ym wĕ⁠ẖatá̇֕ʼţ şĕ̂ʻi֥yr ʻizi֖̇ym la⁠ẏֽwòm׃"],[45,24,"וּ⁠מִנְחָ֗ה אֵיפָ֥ה לַ⁠פָּ֛ר וְ⁠אֵיפָ֥ה לָ⁠אַ֖יִל יַֽעֲשֶׂ֑ה וְ⁠שֶׁ֖מֶן הִ֥ין לָ⁠אֵיפָֽה׃","ẇ⁠minĕẖá֗h ʼéypá֥h la⁠pá֛̇r wĕ⁠ʼéypá֥h lá⁠ʼa֖yil yaֽʻàşê֑h wĕ⁠şě֖men hi֥yn lá⁠ʼéypáֽh׃"],[45,25,"בַּ⁠שְּׁבִיעִ֡י בַּ⁠חֲמִשָּׁה֩ עָשָׂ֨ר י֤וֹם לַ⁠חֹ֨דֶשׁ֙ בֶּ⁠חָ֔ג יַעֲשֶׂ֥ה כָ⁠אֵ֖לֶּה שִׁבְעַ֣ת הַ⁠יָּמִ֑ים כַּֽ⁠חַטָּאת֙ כָּ⁠עֹלָ֔ה וְ⁠כַ⁠מִּנְחָ֖ה וְ⁠כַ⁠שָּֽׁמֶן׃ס","bȧ⁠şĕ̇̌biyʻi֡y bȧ⁠ẖàmişá̇̌h֩ ʻáşá̂֨r y֤wòm la⁠ẖò֨deş̌֙ bė⁠ẖá֔g yaʻàşê֥h ká⁠ʼé֖lėh şǐbĕʻa֣ţ ha⁠yá̇mi֑ym kȧֽ⁠ẖatá̇ʼţ֙ ká̇⁠ʻòlá֔h wĕ⁠ka⁠mi̇nĕẖá֖h wĕ⁠ka⁠şáֽ̇̌men׃s"],[46,1,"כֹּֽה־אָמַר֮ אֲדֹנָ֣⁠י יְהוִה֒ שַׁ֜עַר הֶ⁠חָצֵ֤ר הַ⁠פְּנִימִית֙ הַ⁠פֹּנֶ֣ה קָדִ֔ים יִהְיֶ֣ה סָג֔וּר שֵׁ֖שֶׁת יְמֵ֣י הַֽ⁠מַּעֲשֶׂ֑ה וּ⁠בְ⁠י֤וֹם הַ⁠שַּׁבָּת֙ יִפָּתֵ֔חַ וּ⁠בְ⁠י֥וֹם הַ⁠חֹ֖דֶשׁ יִפָּתֵֽחַ׃","kòֽ̇h-ʼámar֮ ʼàdòná֣⁠y yĕhwih֒ şǎ֜ʻar he⁠ẖáẕé֤r ha⁠pĕ̇niymiyţ֙ ha⁠pò̇ne֣h qádi֔ym yihĕye֣h ság֔ẇr şé֖̌şěţ yĕmé֣y haֽ⁠mȧʻàşê֑h ẇ⁠bĕ⁠y֤wòm ha⁠şȧ̌bá̇ţ֙ yipá̇ţé֔ẖa ẇ⁠bĕ⁠y֥wòm ha⁠ẖò֖deş̌ yipá̇ţéֽẖa׃"],[46,2,"וּ⁠בָ֣א הַ⁠נָּשִׂ֡יא דֶּרֶךְ֩ אוּלָ֨ם הַ⁠שַּׁ֜עַר מִ⁠ח֗וּץ וְ⁠עָמַד֙ עַל־מְזוּזַ֣ת הַ⁠שַּׁ֔עַר וְ⁠עָשׂ֣וּ הַ⁠כֹּהֲנִ֗ים אֶת־עֽוֹלָת⁠וֹ֙ וְ⁠אֶת־שְׁלָמָ֔י⁠ו וְ⁠הִֽשְׁתַּחֲוָ֛ה עַל־מִפְתַּ֥ן הַ⁠שַּׁ֖עַר וְ⁠יָצָ֑א וְ⁠הַ⁠שַּׁ֥עַר לֹֽא־יִסָּגֵ֖ר עַד־הָ⁠עָֽרֶב׃","ẇ⁠bá֣ʼ ha⁠ná̇şî֡yʼ dėrekĕ֩ ʼẇlá֨m ha⁠şȧ̌֜ʻar mi⁠ẖ֗ẇẕ wĕ⁠ʻámad֙ ʻal-mĕzẇza֣ţ ha⁠şȧ̌֔ʻar wĕ⁠ʻáş֣̂ẇ ha⁠kò̇hàni֗ym ʼeţ-ʻֽwòláţ⁠wò֙ wĕ⁠ʼeţ-şĕ̌lámá֔y⁠w wĕ⁠hiֽşĕ̌ţȧẖàwá֛h ʻal-mipĕţȧ֥n ha⁠şȧ֖̌ʻar wĕ⁠yáẕá֑ʼ wĕ⁠ha⁠şȧ֥̌ʻar lòֽʼ-yisá̇gé֖r ʻad-há⁠ʻáֽreb׃"],[46,3,"וְ⁠הִשְׁתַּחֲו֣וּ עַם־הָ⁠אָ֗רֶץ פֶּ֚תַח הַ⁠שַּׁ֣עַר הַ⁠ה֔וּא בַּ⁠שַּׁבָּת֖וֹת וּ⁠בֶ⁠חֳדָשִׁ֑ים לִ⁠פְנֵ֖י יְהוָֽה׃","wĕ⁠hişĕ̌ţȧẖàw֣ẇ ʻam-há⁠ʼá֗reẕ pė֚ţaẖ ha⁠şȧ֣̌ʻar ha⁠h֔ẇʼ bȧ⁠şȧ̌bá̇ţ֖wòţ ẇ⁠be⁠ẖodáşǐ֑ym li⁠pĕné֖y yĕhwáֽh׃"],[46,4,"וְ⁠הָ֣⁠עֹלָ֔ה אֲשֶׁר־יַקְרִ֥ב הַ⁠נָּשִׂ֖יא לַֽ⁠יהוָ֑ה בְּ⁠י֣וֹם הַ⁠שַּׁבָּ֗ת שִׁשָּׁ֧ה כְבָשִׂ֛ים תְּמִימִ֖ם וְ⁠אַ֥יִל תָּמִֽים׃","wĕ⁠há֣⁠ʻòlá֔h ʼàşěr-yaqĕri֥b ha⁠ná̇şî֖yʼ laֽ⁠yhwá֑h bĕ̇⁠y֣wòm ha⁠şȧ̌bá̇֗ţ şǐşá֧̇̌h kĕbáşî֛ym ţĕ̇miymi֖m wĕ⁠ʼa֥yil ţá̇miֽym׃"],[46,5,"וּ⁠מִנְחָה֙ אֵיפָ֣ה לָ⁠אַ֔יִל וְ⁠לַ⁠כְּבָשִׂ֥ים מִנְחָ֖ה מַתַּ֣ת יָד֑⁠וֹ וְ⁠שֶׁ֖מֶן הִ֥ין לָ⁠אֵיפָֽה׃","ẇ⁠minĕẖáh֙ ʼéypá֣h lá⁠ʼa֔yil wĕ⁠la⁠kĕ̇báşî֥ym minĕẖá֖h maţȧ֣ţ yád֑⁠wò wĕ⁠şě֖men hi֥yn lá⁠ʼéypáֽh׃"],[46,6,"וּ⁠בְ⁠י֣וֹם הַ⁠חֹ֔דֶשׁ פַּ֥ר בֶּן־בָּקָ֖ר תְּמִימִ֑ם וְ⁠שֵׁ֧שֶׁת כְּבָשִׂ֛ם וָ⁠אַ֖יִל תְּמִימִ֥ם יִהְיֽוּ׃","ẇ⁠bĕ⁠y֣wòm ha⁠ẖò֔deş̌ pȧ֥r bėn-bá̇qá֖r ţĕ̇miymi֑m wĕ⁠şé֧̌şěţ kĕ̇báşî֛m wá⁠ʼa֖yil ţĕ̇miymi֥m yihĕyֽẇ׃"],[46,7,"וְ⁠אֵיפָ֨ה לַ⁠פָּ֜ר וְ⁠אֵיפָ֤ה לָ⁠אַ֨יִל֙ יַעֲשֶׂ֣ה מִנְחָ֔ה וְ⁠לַ֨⁠כְּבָשִׂ֔ים כַּ⁠אֲשֶׁ֥ר תַּשִּׂ֖יג יָד֑⁠וֹ וְ⁠שֶׁ֖מֶן הִ֥ין לָ⁠אֵיפָֽה׃","wĕ⁠ʼéypá֨h la⁠pá̇֜r wĕ⁠ʼéypá֤h lá⁠ʼa֨yil֙ yaʻàşê֣h minĕẖá֔h wĕ⁠la֨⁠kĕ̇báşî֔ym kȧ⁠ʼàşě֥r ţȧşi֖̇̂yg yád֑⁠wò wĕ⁠şě֖men hi֥yn lá⁠ʼéypáֽh׃"],[46,8,"וּ⁠בְ⁠ב֖וֹא הַ⁠נָּשִׂ֑יא דֶּ֣רֶךְ אוּלָ֤ם הַ⁠שַּׁ֨עַר֙ יָב֔וֹא וּ⁠בְ⁠דַרְכּ֖⁠וֹ יֵצֵֽא׃","ẇ⁠bĕ⁠b֖wòʼ ha⁠ná̇şî֑yʼ dė֣rekĕ ʼẇlá֤m ha⁠şȧ̌֨ʻar֙ yáb֔wòʼ ẇ⁠bĕ⁠darĕk֖̇⁠wò yéẕéֽʼ׃"],[46,9,"וּ⁠בְ⁠ב֨וֹא עַם־הָ⁠אָ֜רֶץ לִ⁠פְנֵ֣י יְהוָה֮ בַּ⁠מּֽוֹעֲדִים֒ הַ⁠בָּ֡א דֶּרֶךְ־שַׁ֨עַר צָפ֜וֹן לְ⁠הִֽשְׁתַּחֲוֺ֗ת יֵצֵא֙ דֶּרֶךְ־שַׁ֣עַר נֶ֔גֶב וְ⁠הַ⁠בָּא֙ דֶּרֶךְ־שַׁ֣עַר נֶ֔גֶב יֵצֵ֖א דֶּרֶךְ־שַׁ֣עַר צָפ֑וֹנָ⁠ה לֹ֣א יָשׁ֗וּב דֶּ֤רֶךְ הַ⁠שַּׁ֨עַר֙ אֲשֶׁר־בָּ֣א ב֔⁠וֹ כִּ֥י נִכְח֖⁠וֹ יצאו׃","ẇ⁠bĕ⁠b֨wòʼ ʻam-há⁠ʼá֜reẕ li⁠pĕné֣y yĕhwáh֮ bȧ⁠ṁֽwòʻàdiym֒ ha⁠bá̇֡ʼ dėrekĕ-şǎ֨ʻar ẕáp֜wòn lĕ⁠hiֽşĕ̌ţȧẖàwֺ֗ţ yéẕéʼ֙ dėrekĕ-şǎ֣ʻar ne֔geb wĕ⁠ha⁠bá̇ʼ֙ dėrekĕ-şǎ֣ʻar ne֔geb yéẕé֖ʼ dėrekĕ-şǎ֣ʻar ẕáp֑wòná⁠h lò֣ʼ yáş̌֗ẇb dė֤rekĕ ha⁠şȧ̌֨ʻar֙ ʼàşěr-bá֣̇ʼ b֔⁠wò ki֥̇y nikĕẖ֖⁠wò yẕʼw׃"],[46,10,"וְֽ⁠הַ⁠נָּשִׂ֑יא בְּ⁠תוֹכָ֤⁠ם בְּ⁠בוֹאָ⁠ם֙ יָב֔וֹא וּ⁠בְ⁠צֵאתָ֖⁠ם יֵצֵֽאוּ׃","wĕֽ⁠ha⁠ná̇şî֑yʼ bĕ̇⁠ţwòká֤⁠m bĕ̇⁠bwòʼá⁠m֙ yáb֔wòʼ ẇ⁠bĕ⁠ẕéʼţá֖⁠m yéẕéֽʼẇ׃"],[46,11,"וּ⁠בַ⁠חַגִּ֣ים וּ⁠בַ⁠מּוֹעֲדִ֗ים תִּהְיֶ֤ה הַ⁠מִּנְחָה֙ אֵיפָ֤ה לַ⁠פָּר֙ וְ⁠אֵיפָ֣ה לָ⁠אַ֔יִל וְ⁠לַ⁠כְּבָשִׂ֖ים מַתַּ֣ת יָד֑⁠וֹ וְ⁠שֶׁ֖מֶן הִ֥ין לָ⁠אֵיפָֽה׃ס","ẇ⁠ba⁠ẖagi֣̇ym ẇ⁠ba⁠ṁwòʻàdi֗ym ţi̇hĕye֤h ha⁠mi̇nĕẖáh֙ ʼéypá֤h la⁠pá̇r֙ wĕ⁠ʼéypá֣h lá⁠ʼa֔yil wĕ⁠la⁠kĕ̇báşî֖ym maţȧ֣ţ yád֑⁠wò wĕ⁠şě֖men hi֥yn lá⁠ʼéypáֽh׃s"],[46,12,"וְ⁠כִֽי־יַעֲשֶׂה֩ הַ⁠נָּשִׂ֨יא נְדָבָ֜ה עוֹלָ֣ה אֽוֹ־שְׁלָמִים֮ נְדָבָ֣ה לַֽ⁠יהוָה֒ וּ⁠פָ֣תַֽח ל֗⁠וֹ אֶת הַ⁠שַּׁ֨עַר֙ הַ⁠פֹּנֶ֣ה קָדִ֔ים וְ⁠עָשָׂ֤ה אֶת־עֹֽלָת⁠וֹ֙ וְ⁠אֶת־שְׁלָמָ֔י⁠ו כַּ⁠אֲשֶׁ֥ר יַעֲשֶׂ֖ה בְּ⁠י֣וֹם הַ⁠שַּׁבָּ֑ת וְ⁠יָצָ֛א וְ⁠סָגַ֥ר אֶת־הַ⁠שַּׁ֖עַר אַחֲרֵ֥י צֵאתֽ⁠וֹ׃","wĕ⁠kiֽy-yaʻàşêh֩ ha⁠ná̇şî֨yʼ nĕdábá֜h ʻwòlá֣h ʼֽwò-şĕ̌lámiym֮ nĕdábá֣h laֽ⁠yhwáh֒ ẇ⁠pá֣ţaֽẖ l֗⁠wò ʼeţ ha⁠şȧ̌֨ʻar֙ ha⁠pò̇ne֣h qádi֔ym wĕ⁠ʻáşá֤̂h ʼeţ-ʻòֽláţ⁠wò֙ wĕ⁠ʼeţ-şĕ̌lámá֔y⁠w kȧ⁠ʼàşě֥r yaʻàşê֖h bĕ̇⁠y֣wòm ha⁠şȧ̌bá֑̇ţ wĕ⁠yáẕá֛ʼ wĕ⁠sága֥r ʼeţ-ha⁠şȧ֖̌ʻar ʼaẖàré֥y ẕéʼţֽ⁠wò׃"],[46,13,"וְ⁠כֶ֨בֶשׂ בֶּן־שְׁנָת֜⁠וֹ תָּמִ֗ים תַּעֲשֶׂ֥ה עוֹלָ֛ה לַ⁠יּ֖וֹם לַֽ⁠יהֹוָ֑ה בַּ⁠בֹּ֥קֶר בַּ⁠בֹּ֖קֶר תַּעֲשֶׂ֥ה אֹתֽ⁠וֹ׃","wĕ⁠ke֨beş̂ bėn-şĕ̌náţ֜⁠wò ţá̇mi֗ym ţȧʻàşê֥h ʻwòlá֛h la⁠ẏ֖wòm laֽ⁠yhòwá֑h bȧ⁠bò֥̇qer bȧ⁠bò֖̇qer ţȧʻàşê֥h ʼòţֽ⁠wò׃"],[46,14,"וּ⁠מִנְחָה֩ תַעֲשֶׂ֨ה עָלָ֜י⁠ו בַּ⁠בֹּ֤קֶר בַּ⁠בֹּ֨קֶר֙ שִׁשִּׁ֣ית הָֽ⁠אֵיפָ֔ה וְ⁠שֶׁ֛מֶן שְׁלִישִׁ֥ית הַ⁠הִ֖ין לָ⁠רֹ֣ס אֶת־הַ⁠סֹּ֑לֶת מִנְחָה֙ לַֽ⁠יהוָ֔ה חֻקּ֥וֹת עוֹלָ֖ם תָּמִֽיד׃","ẇ⁠minĕẖáh֩ ţaʻàşê֨h ʻálá֜y⁠w bȧ⁠bò֤̇qer bȧ⁠bò̇֨qer֙ şǐşi֣̇̌yţ háֽ⁠ʼéypá֔h wĕ⁠şě֛men şĕ̌liyşǐ֥yţ ha⁠hi֖yn lá⁠rò֣s ʼeţ-ha⁠sò֑̇leţ minĕẖáh֙ laֽ⁠yhwá֔h ẖuq֥̇wòţ ʻwòlá֖m ţá̇miֽyd׃"],[46,15,"ו⁠עשו אֶת־הַ⁠כֶּ֧בֶשׂ וְ⁠אֶת־הַ⁠מִּנְחָ֛ה וְ⁠אֶת־הַ⁠שֶּׁ֖מֶן בַּ⁠בֹּ֣קֶר בַּ⁠בֹּ֑קֶר עוֹלַ֖ת תָּמִֽיד׃פ","w⁠ʻşw ʼeţ-ha⁠kė֧beş̂ wĕ⁠ʼeţ-ha⁠mi̇nĕẖá֛h wĕ⁠ʼeţ-ha⁠şė֖̌men bȧ⁠bò֣̇qer bȧ⁠bò֑̇qer ʻwòla֖ţ ţá̇miֽyd׃p"],[46,16,"כֹּה־אָמַ֞ר אֲדֹנָ֣⁠י יְהֹוִ֗ה כִּֽי־יִתֵּ֨ן הַ⁠נָּשִׂ֤יא מַתָּנָה֙ לְ⁠אִ֣ישׁ מִ⁠בָּנָ֔י⁠ו נַחֲלָת֥⁠וֹ הִ֖יא לְ⁠בָנָ֣י⁠ו תִּֽהְיֶ֑ה אֲחֻזָּתָ֥⁠ם הִ֖יא בְּ⁠נַחֲלָֽה׃","kò̇h-ʼáma֞r ʼàdòná֣⁠y yĕhòwi֗h kiֽ̇y-yiţé̇֨n ha⁠ná̇şî֤yʼ maţá̇náh֙ lĕ⁠ʼi֣yş̌ mi⁠bá̇ná֔y⁠w naẖàláţ֥⁠wò hi֖yʼ lĕ⁠báná֣y⁠w ţiֽ̇hĕye֑h ʼàẖuzá̇ţá֥⁠m hi֖yʼ bĕ̇⁠naẖàláֽh׃"],[46,17,"וְ⁠כִֽי־יִתֵּ֨ן מַתָּנָ֜ה מִ⁠נַּחֲלָת֗⁠וֹ לְ⁠אַחַד֙ מֵֽ⁠עֲבָדָ֔י⁠ו וְ⁠הָ֤יְתָה לּ⁠וֹ֙ עַד־שְׁנַ֣ת הַ⁠דְּר֔וֹר וְ⁠שָׁבַ֖ת לַ⁠נָּשִׂ֑יא אַ֚ךְ נַחֲלָת֔⁠וֹ בָּנָ֖י⁠ו לָ⁠הֶ֥ם תִּהְיֶֽה׃","wĕ⁠kiֽy-yiţé̇֨n maţá̇ná֜h mi⁠nȧẖàláţ֗⁠wò lĕ⁠ʼaẖad֙ méֽ⁠ʻàbádá֔y⁠w wĕ⁠há֤yĕţáh l̇⁠wò֙ ʻad-şĕ̌na֣ţ ha⁠dĕ̇r֔wòr wĕ⁠şá̌ba֖ţ la⁠ná̇şî֑yʼ ʼa֚kĕ naẖàláţ֔⁠wò bá̇ná֖y⁠w lá⁠he֥m ţi̇hĕyeֽh׃"],[46,18,"וְ⁠לֹא־יִקַּ֨ח הַ⁠נָּשִׂ֜יא מִ⁠נַּחֲלַ֣ת הָ⁠עָ֗ם לְ⁠הֽוֹנֹתָ⁠ם֙ מֵ⁠אֲחֻזָּתָ֔⁠ם מֵ⁠אֲחֻזָּת֖⁠וֹ יַנְחִ֣ל אֶת־בָּנָ֑י⁠ו לְמַ֨עַן֙ אֲשֶׁ֣ר לֹֽא־יָפֻ֣צוּ עַמִּ֔⁠י אִ֖ישׁ מֵ⁠אֲחֻזָּתֽ⁠וֹ׃","wĕ⁠lòʼ-yiqȧ֨ẖ ha⁠ná̇şî֜yʼ mi⁠nȧẖàla֣ţ há⁠ʻá֗m lĕ⁠hֽwònòţá⁠m֙ mé⁠ʼàẖuzá̇ţá֔⁠m mé⁠ʼàẖuzá̇ţ֖⁠wò yanĕẖi֣l ʼeţ-bá̇ná֑y⁠w lĕma֨ʻan֙ ʼàşě֣r lòֽʼ-yápu֣ẕẇ ʻami̇֔⁠y ʼi֖yş̌ mé⁠ʼàẖuzá̇ţֽ⁠wò׃"],[46,19,"וַ⁠יְבִיאֵ֣⁠נִי בַ⁠מָּבוֹא֮ אֲשֶׁ֣ר עַל־כֶּ֣תֶף הַ⁠שַּׁעַר֒ אֶל־הַ⁠לִּשְׁכ֤וֹת הַ⁠קֹּ֨דֶשׁ֙ אֶל־הַ⁠כֹּ֣הֲנִ֔ים הַ⁠פֹּנ֖וֹת צָפ֑וֹנָ⁠ה וְ⁠הִנֵּה־שָׁ֣ם מָק֔וֹם בירכתם יָֽמָּ⁠ה׃ס","wa⁠yĕbiyʼé֣⁠niy ba⁠má̇bwòʼ֮ ʼàşě֣r ʻal-kė֣ţep ha⁠şȧ̌ʻar֒ ʼel-ha⁠li̇şĕ̌k֤wòţ ha⁠qò̇֨deş̌֙ ʼel-ha⁠kò֣̇hàni֔ym ha⁠pò̇n֖wòţ ẕáp֑wòná⁠h wĕ⁠hiné̇h-şá֣̌m máq֔wòm byrkţm yáֽmá̇⁠h׃s"],[46,20,"וַ⁠יֹּ֣אמֶר אֵלַ֔⁠י זֶ֣ה הַ⁠מָּק֗וֹם אֲשֶׁ֤ר יְבַשְּׁלוּ־שָׁם֙ הַ⁠כֹּ֣הֲנִ֔ים אֶת־הָ⁠אָשָׁ֖ם וְ⁠אֶת־הַ⁠חַטָּ֑את אֲשֶׁ֤ר יֹאפוּ֙ אֶת־הַ⁠מִּנְחָ֔ה לְ⁠בִלְתִּ֥י הוֹצִ֛יא אֶל־הֶ⁠חָצֵ֥ר הַ⁠חִֽיצוֹנָ֖ה לְ⁠קַדֵּ֥שׁ אֶת־הָ⁠עָֽם׃","wa⁠yò֣̇ʼmer ʼéla֔⁠y ze֣h ha⁠má̇q֗wòm ʼàşě֤r yĕbaşĕ̇̌lẇ-şá̌m֙ ha⁠kò֣̇hàni֔ym ʼeţ-há⁠ʼáşá֖̌m wĕ⁠ʼeţ-ha⁠ẖatá֑̇ʼţ ʼàşě֤r yòʼpẇ֙ ʼeţ-ha⁠mi̇nĕẖá֔h lĕ⁠bilĕţi֥̇y hwòẕi֛yʼ ʼel-he⁠ẖáẕé֥r ha⁠ẖiֽyẕwòná֖h lĕ⁠qadé֥̇ş̌ ʼeţ-há⁠ʻáֽm׃"],[46,21,"וַ⁠יּוֹצִיאֵ֗⁠נִי אֶל־הֶֽ⁠חָצֵר֙ הַ⁠חִ֣יצֹנָ֔ה וַ⁠יַּ֣עֲבִירֵ֔⁠נִי אֶל־אַרְבַּ֖עַת מִקְצוֹעֵ֣י הֶ⁠חָצֵ֑ר וְ⁠הִנֵּ֤ה חָצֵר֙ בְּ⁠מִקְצֹ֣עַ הֶ⁠חָצֵ֔ר חָצֵ֖ר בְּ⁠מִקְצֹ֥עַ הֶ⁠חָצֵֽר׃","wa⁠ẏwòẕiyʼé֗⁠niy ʼel-heֽ⁠ẖáẕér֙ ha⁠ẖi֣yẕòná֔h wa⁠yȧ֣ʻàbiyré֔⁠niy ʼel-ʼarĕbȧ֖ʻaţ miqĕẕwòʻé֣y he⁠ẖáẕé֑r wĕ⁠hiné֤̇h ẖáẕér֙ bĕ̇⁠miqĕẕò֣ʻa he⁠ẖáẕé֔r ẖáẕé֖r bĕ̇⁠miqĕẕò֥ʻa he⁠ẖáẕéֽr׃"],[46,22,"בְּ⁠אַרְבַּ֜עַת מִקְצֹע֤וֹת הֶֽ⁠חָצֵר֙ חֲצֵר֣וֹת קְטֻר֔וֹת אַרְבָּעִ֣ים אֹ֔רֶךְ וּ⁠שְׁלֹשִׁ֖ים רֹ֑חַב מִדָּ֣ה אַחַ֔ת לְ⁠אַרְבַּעְתָּ֖⁠ם מְׄהֻׄקְׄצָׄעֽׄוֹׄתׄ׃","bĕ̇⁠ʼarĕbȧ֜ʻaţ miqĕẕòʻ֤wòţ heֽ⁠ẖáẕér֙ ẖàẕér֣wòţ qĕtur֔wòţ ʼarĕbá̇ʻi֣ym ʼò֔rekĕ ẇ⁠şĕ̌lòşǐ֖ym rò֑ẖab midá֣̇h ʼaẖa֔ţ lĕ⁠ʼarĕbȧʻĕţá֖̇⁠m mĕׄhuׄqĕׄẕáׄʻֽׄwòׄţׄ׃"],[46,23,"וְ⁠ט֨וּר סָבִ֥יב בָּ⁠הֶ֛ם סָבִ֖יב לְ⁠אַרְבַּעְתָּ֑⁠ם וּ⁠מְבַשְּׁל֣וֹת עָשׂ֔וּי מִ⁠תַּ֥חַת הַ⁠טִּיר֖וֹת סָבִֽיב׃","wĕ⁠t֨ẇr sábi֥yb bá̇⁠he֛m sábi֖yb lĕ⁠ʼarĕbȧʻĕţá֑̇⁠m ẇ⁠mĕbaşĕ̇̌l֣wòţ ʻáş̂֔ẇy mi⁠ţȧ֥ẖaţ ha⁠ti̇yr֖wòţ sábiֽyb׃"],[46,24,"וַ⁠יֹּ֖אמֶר אֵלָ֑⁠י אֵ֚לֶּה בֵּ֣ית הַֽ⁠מְבַשְּׁלִ֔ים אֲשֶׁ֧ר יְבַשְּׁלוּ־שָׁ֛ם מְשָׁרְתֵ֥י הַ⁠בַּ֖יִת אֶת־זֶ֥בַח הָ⁠עָֽם׃","wa⁠yò֖̇ʼmer ʼélá֑⁠y ʼé֚lėh bé֣̇yţ haֽ⁠mĕbaşĕ̇̌li֔ym ʼàşě֧r yĕbaşĕ̇̌lẇ-şá֛̌m mĕşá̌rĕţé֥y ha⁠bȧ֖yiţ ʼeţ-ze֥baẖ há⁠ʻáֽm׃"],[47,1,"וַ⁠יְשִׁבֵ⁠נִי֮ אֶל־פֶּ֣תַח הַ⁠בַּיִת֒ וְ⁠הִנֵּה־מַ֣יִם יֹצְאִ֗ים מִ⁠תַּ֨חַת מִפְתַּ֤ן הַ⁠בַּ֨יִת֙ קָדִ֔ימָ⁠ה כִּֽי־פְנֵ֥י הַ⁠בַּ֖יִת קָדִ֑ים וְ⁠הַ⁠מַּ֣יִם יֹרְדִ֗ים מִ⁠תַּ֜חַת מִ⁠כֶּ֤תֶף הַ⁠בַּ֨יִת֙ הַ⁠יְמָנִ֔ית מִ⁠נֶּ֖גֶב לַ⁠מִּזְבֵּֽחַ׃","wa⁠yĕşǐbé⁠niy֮ ʼel-pė֣ţaẖ ha⁠bȧyiţ֒ wĕ⁠hiné̇h-ma֣yim yòẕĕʼi֗ym mi⁠ţȧ֨ẖaţ mipĕţȧ֤n ha⁠bȧ֨yiţ֙ qádi֔ymá⁠h kiֽ̇y-pĕné֥y ha⁠bȧ֖yiţ qádi֑ym wĕ⁠ha⁠mȧ֣yim yòrĕdi֗ym mi⁠ţȧ֜ẖaţ mi⁠kė֤ţep ha⁠bȧ֨yiţ֙ ha⁠yĕmáni֔yţ mi⁠nė֖geb la⁠mi̇zĕbéֽ̇ẖa׃"],[47,2,"וַ⁠יּוֹצִאֵ⁠נִי֮ דֶּֽרֶךְ־שַׁ֣עַר צָפוֹנָ⁠ה֒ וַ⁠יְסִבֵּ֨⁠נִי֙ דֶּ֣רֶךְ ח֔וּץ אֶל־שַׁ֣עַר הַ⁠ח֔וּץ דֶּ֖רֶךְ הַ⁠פּוֹנֶ֣ה קָדִ֑ים וְ⁠הִנֵּה־מַ֣יִם מְפַכִּ֔ים מִן־הַ⁠כָּתֵ֖ף הַ⁠יְמָנִֽית׃","wa⁠ẏwòẕiʼé⁠niy֮ dėֽrekĕ-şǎ֣ʻar ẕápwòná⁠h֒ wa⁠yĕsibé̇֨⁠niy֙ dė֣rekĕ ẖ֔ẇẕ ʼel-şǎ֣ʻar ha⁠ẖ֔ẇẕ dė֖rekĕ ha⁠ṗwòne֣h qádi֑ym wĕ⁠hiné̇h-ma֣yim mĕpaki̇֔ym min-ha⁠ká̇ţé֖p ha⁠yĕmániֽyţ׃"],[47,3,"בְּ⁠צֵאת־הָ⁠אִ֥ישׁ קָדִ֖ים וְ⁠קָ֣ו בְּ⁠יָד֑⁠וֹ וַ⁠יָּ֤מָד אֶ֨לֶף֙ בָּֽ⁠אַמָּ֔ה וַ⁠יַּעֲבִרֵ֥⁠נִי בַ⁠מַּ֖יִם מֵ֥י אָפְסָֽיִם׃","bĕ̇⁠ẕéʼţ-há⁠ʼi֥yş̌ qádi֖ym wĕ⁠qá֣w bĕ̇⁠yád֑⁠wò wa⁠yá֤̇mád ʼe֨lep֙ báֽ̇⁠ʼamá̇֔h wa⁠yȧʻàbiré֥⁠niy ba⁠mȧ֖yim mé֥y ʼápĕsáֽyim׃"],[47,4,"וַ⁠יָּ֣מָד אֶ֔לֶף וַ⁠יַּעֲבִרֵ֥⁠נִי בַ⁠מַּ֖יִם מַ֣יִם בִּרְכָּ֑יִם וַ⁠יָּ֣מָד אֶ֔לֶף וַ⁠יַּעֲבִרֵ֖⁠נִי מֵ֥י מָתְנָֽיִם׃","wa⁠yá֣̇mád ʼe֔lep wa⁠yȧʻàbiré֥⁠niy ba⁠mȧ֖yim ma֣yim bi̇rĕká֑̇yim wa⁠yá֣̇mád ʼe֔lep wa⁠yȧʻàbiré֖⁠niy mé֥y máţĕnáֽyim׃"],[47,5,"וַ⁠יָּ֣מָד אֶ֔לֶף נַ֕חַל אֲשֶׁ֥ר לֹֽא־אוּכַ֖ל לַ⁠עֲבֹ֑ר כִּֽי־גָא֤וּ הַ⁠מַּ֨יִם֙ מֵ֣י שָׂ֔חוּ נַ֖חַל אֲשֶׁ֥ר לֹֽא־יֵעָבֵֽר׃","wa⁠yá֣̇mád ʼe֔lep na֕ẖal ʼàşě֥r lòֽʼ-ʼẇka֖l la⁠ʻàbò֑r kiֽ̇y-gáʼ֤ẇ ha⁠mȧ֨yim֙ mé֣y şá̂֔ẖẇ na֖ẖal ʼàşě֥r lòֽʼ-yéʻábéֽr׃"],[47,6,"וַ⁠יֹּ֥אמֶר אֵלַ֖⁠י הֲ⁠רָאִ֣יתָ בֶן־אָדָ֑ם וַ⁠יּוֹלִכֵ֥⁠נִי וַ⁠יְשִׁבֵ֖⁠נִי שְׂפַ֥ת הַ⁠נָּֽחַל׃","wa⁠yò֥̇ʼmer ʼéla֖⁠y hà⁠ráʼi֣yţá ben-ʼádá֑m wa⁠ẏwòliké֥⁠niy wa⁠yĕşǐbé֖⁠niy şĕ̂pa֥ţ ha⁠náֽ̇ẖal׃"],[47,7,"בְּ⁠שׁוּבֵ֕⁠נִי וְ⁠הִנֵּה֙ אֶל־שְׂפַ֣ת הַ⁠נַּ֔חַל עֵ֖ץ רַ֣ב מְאֹ֑ד מִ⁠זֶּ֖ה וּ⁠מִ⁠זֶּֽה׃","bĕ̇⁠ş̌ẇbé֕⁠niy wĕ⁠hiné̇h֙ ʼel-şĕ̂pa֣ţ ha⁠nȧ֔ẖal ʻé֖ẕ ra֣b mĕʼò֑d mi⁠zė֖h ẇ⁠mi⁠zėֽh׃"],[47,8,"וַ⁠יֹּ֣אמֶר אֵלַ֗⁠י הַ⁠מַּ֤יִם הָ⁠אֵ֨לֶּה֙ יוֹצְאִ֗ים אֶל־הַ⁠גְּלִילָה֙ הַ⁠קַּדְמוֹנָ֔ה וְ⁠יָרְד֖וּ עַל־הָֽ⁠עֲרָבָ֑ה וּ⁠בָ֣אוּ הַ⁠יָּ֔מָּ⁠ה אֶל־הַ⁠יָּ֥מָּ⁠ה הַ⁠מּֽוּצָאִ֖ים ו⁠נרפאו הַ⁠מָּֽיִם׃","wa⁠yò֣̇ʼmer ʼéla֗⁠y ha⁠mȧ֤yim há⁠ʼé֨lėh֙ ywòẕĕʼi֗ym ʼel-ha⁠gĕ̇liyláh֙ ha⁠qȧdĕmwòná֔h wĕ⁠yárĕd֖ẇ ʻal-háֽ⁠ʻàrábá֑h ẇ⁠bá֣ʼẇ ha⁠yá̇֔má̇⁠h ʼel-ha⁠yá֥̇má̇⁠h ha⁠ṁֽẇẕáʼi֖ym w⁠nrpʼw ha⁠máֽ̇yim׃"],[47,9,"וְ⁠הָיָ֣ה כָל־נֶ֣פֶשׁ חַיָּ֣ה ׀ אֲֽשֶׁר־יִשְׁרֹ֡ץ אֶ֣ל כָּל־אֲשֶׁר֩ יָב֨וֹא שָׁ֤ם נַחֲלַ֨יִם֙ יִֽחְיֶ֔ה וְ⁠הָיָ֥ה הַ⁠דָּגָ֖ה רַבָּ֣ה מְאֹ֑ד כִּי֩ בָ֨אוּ שָׁ֜מָּ⁠ה הַ⁠מַּ֣יִם הָ⁠אֵ֗לֶּה וְ⁠יֵרָֽפְאוּ֙ וָ⁠חָ֔י כֹּ֛ל אֲשֶׁר־יָ֥בוֹא שָׁ֖מָּ⁠ה הַ⁠נָּֽחַל׃","wĕ⁠háyá֣h kál-ne֣peş̌ ẖayá֣̇h ׀ ʼàֽşěr-yişĕ̌rò֡ẕ ʼe֣l ká̇l-ʼàşěr֩ yáb֨wòʼ şá֤̌m naẖàla֨yim֙ yiֽẖĕye֔h wĕ⁠háyá֥h ha⁠dá̇gá֖h rabá֣̇h mĕʼò֑d ki̇y֩ bá֨ʼẇ şá̌֜má̇⁠h ha⁠mȧ֣yim há⁠ʼé֗lėh wĕ⁠yéráֽpĕʼẇ֙ wá⁠ẖá֔y kò֛̇l ʼàşěr-yá֥bwòʼ şá֖̌má̇⁠h ha⁠náֽ̇ẖal׃"],[47,10,"וְ⁠הָיָה֩ יעמדו עָלָ֜י⁠ו דַּוָּגִ֗ים מֵ⁠עֵ֥ין גֶּ֨דִי֙ וְ⁠עַד־עֵ֣ין עֶגְלַ֔יִם מִשְׁט֥וֹחַ לַֽ⁠חֲרָמִ֖ים יִהְי֑וּ לְ⁠מִינָ⁠ה֙ תִּהְיֶ֣ה דְגָתָ֔⁠ם כִּ⁠דְגַ֛ת הַ⁠יָּ֥ם הַ⁠גָּד֖וֹל רַבָּ֥ה מְאֹֽד׃","wĕ⁠háyáh֩ yʻmdw ʻálá֜y⁠w dȧwá̇gi֗ym mé⁠ʻé֥yn gė֨diy֙ wĕ⁠ʻad-ʻé֣yn ʻegĕla֔yim mişĕ̌t֥wòẖa laֽ⁠ẖàrámi֖ym yihĕy֑ẇ lĕ⁠miyná⁠h֙ ţi̇hĕye֣h dĕgáţá֔⁠m ki̇⁠dĕga֛ţ ha⁠yá֥̇m ha⁠gá̇d֖wòl rabá֥̇h mĕʼòֽd׃"],[47,11,"בצאת⁠ו וּ⁠גְבָאָ֛י⁠ו וְ⁠לֹ֥א יֵרָפְא֖וּ לְ⁠מֶ֥לַח נִתָּֽנוּ׃","bẕʼţ⁠w ẇ⁠gĕbáʼá֛y⁠w wĕ⁠lò֥ʼ yérápĕʼ֖ẇ lĕ⁠me֥laẖ niţáֽ̇nẇ׃"],[47,12,"וְ⁠עַל־הַ⁠נַּ֣חַל יַעֲלֶ֣ה עַל־שְׂפָת֣⁠וֹ מִ⁠זֶּ֣ה ׀ וּ⁠מִ⁠זֶּ֣ה ׀ כָּל־עֵֽץ־מַ֠אֲכָל לֹא־יִבּ֨וֹל עָלֵ֜⁠הוּ וְ⁠לֹֽא־יִתֹּ֣ם פִּרְי֗⁠וֹ לָֽ⁠חֳדָשָׁי⁠ו֙ יְבַכֵּ֔ר כִּ֣י מֵימָ֔י⁠ו מִן־הַ⁠מִּקְדָּ֖שׁ הֵ֣מָּה יֽוֹצְאִ֑ים ו⁠היו פִרְי⁠וֹ֙ לְ⁠מַֽאֲכָ֔ל וְ⁠עָלֵ֖⁠הוּ לִ⁠תְרוּפָֽה׃ס","wĕ⁠ʻal-ha⁠nȧ֣ẖal yaʻàle֣h ʻal-şĕ̂páţ֣⁠wò mi⁠zė֣h ׀ ẇ⁠mi⁠zė֣h ׀ ká̇l-ʻéֽẕ-ma֠ʼàkál lòʼ-yiḃ֨wòl ʻálé֜⁠hẇ wĕ⁠lòֽʼ-yiţò֣̇m pi̇rĕy֗⁠wò láֽ⁠ẖodáşá̌y⁠w֙ yĕbaké̇֔r ki֣̇y méymá֔y⁠w min-ha⁠mi̇qĕdá֖̇ş̌ hé֣má̇h yֽwòẕĕʼi֑ym w⁠hyw pirĕy⁠wò֙ lĕ⁠maֽʼàká֔l wĕ⁠ʻálé֖⁠hẇ li⁠ţĕrẇpáֽh׃s"],[47,13,"כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה גֵּ֤ה גְבוּל֙ אֲשֶׁ֣ר תִּתְנַחֲל֣וּ אֶת־הָ⁠אָ֔רֶץ לִ⁠שְׁנֵ֥י עָשָׂ֖ר שִׁבְטֵ֣י יִשְׂרָאֵ֑ל יוֹסֵ֖ף חֲבָלִֽים׃","kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h gé֤̇h gĕbẇl֙ ʼàşě֣r ţi̇ţĕnaẖàl֣ẇ ʼeţ-há⁠ʼá֔reẕ li⁠şĕ̌né֥y ʻáşá֖̂r şǐbĕté֣y yişĕ̂ráʼé֑l ywòsé֖p ẖàbáliֽym׃"],[47,14,"וּ⁠נְחַלְתֶּ֤ם אוֹתָ⁠הּ֙ אִ֣ישׁ כְּ⁠אָחִ֔י⁠ו אֲשֶׁ֤ר נָשָׂ֨אתִי֙ אֶת־יָדִ֔⁠י לְ⁠תִתָּ֖⁠הּ לַ⁠אֲבֹֽתֵי⁠כֶ֑ם וְ⁠נָ֨פְלָ֜ה הָ⁠אָ֧רֶץ הַ⁠זֹּ֛את לָ⁠כֶ֖ם בְּ⁠נַחֲלָֽה׃","ẇ⁠nĕẖalĕţė֤m ʼwòţá⁠ḣ֙ ʼi֣yş̌ kĕ̇⁠ʼáẖi֔y⁠w ʼàşě֤r náşá̂֨ʼţiy֙ ʼeţ-yádi֔⁠y lĕ⁠ţiţá֖̇⁠ḣ la⁠ʼàbòֽţéy⁠ke֑m wĕ⁠ná֨pĕlá֜h há⁠ʼá֧reẕ ha⁠zò֛̇ʼţ lá⁠ke֖m bĕ̇⁠naẖàláֽh׃"],[47,15,"וְ⁠זֶ֖ה גְּב֣וּל הָ⁠אָ֑רֶץ לִ⁠פְאַ֨ת צָפ֜וֹנָ⁠ה מִן־הַ⁠יָּ֧ם הַ⁠גָּד֛וֹל הַ⁠דֶּ֥רֶךְ חֶתְלֹ֖ן לְב֥וֹא צְדָֽדָ⁠ה׃","wĕ⁠ze֖h gĕ̇b֣ẇl há⁠ʼá֑reẕ li⁠pĕʼa֨ţ ẕáp֜wòná⁠h min-ha⁠yá֧̇m ha⁠gá̇d֛wòl ha⁠dė֥rekĕ ẖeţĕlò֖n lĕb֥wòʼ ẕĕdáֽdá⁠h׃"],[47,16,"חֲמָ֤ת ׀ בֵּר֨וֹתָה֙ סִבְרַ֔יִם אֲשֶׁר֙ בֵּין־גְּב֣וּל דַּמֶּ֔שֶׂק וּ⁠בֵ֖ין גְּב֣וּל חֲמָ֑ת חָצֵר֙ הַתִּיכ֔וֹן אֲשֶׁ֖ר אֶל־גְּב֥וּל חַוְרָֽן׃","ẖàmá֤ţ ׀ bé̇r֨wòţáh֙ sibĕra֔yim ʼàşěr֙ bé̇yn-gĕ̇b֣ẇl dȧmė֔şêq ẇ⁠bé֖yn gĕ̇b֣ẇl ẖàmá֑ţ ẖáẕér֙ haţi̇yk֔wòn ʼàşě֖r ʼel-gĕ̇b֥ẇl ẖawĕráֽn׃"],[47,17,"וְ⁠הָיָ֨ה גְב֜וּל מִן־הַ⁠יָּ֗ם חֲצַ֤ר עֵינוֹן֙ גְּב֣וּל דַּמֶּ֔שֶׂק וְ⁠צָפ֥וֹן ׀ צָפ֖וֹנָ⁠ה וּ⁠גְב֣וּל חֲמָ֑ת וְ⁠אֵ֖ת פְּאַ֥ת צָפֽוֹן׃","wĕ⁠háyá֨h gĕb֜ẇl min-ha⁠yá̇֗m ẖàẕa֤r ʻéynwòn֙ gĕ̇b֣ẇl dȧmė֔şêq wĕ⁠ẕáp֥wòn ׀ ẕáp֖wòná⁠h ẇ⁠gĕb֣ẇl ẖàmá֑ţ wĕ⁠ʼé֖ţ pĕ̇ʼa֥ţ ẕápֽwòn׃"],[47,18,"וּ⁠פְאַ֣ת קָדִ֡ים מִ⁠בֵּ֣ין חַוְרָ֣ן וּ⁠מִ⁠בֵּין־דַּמֶּשֶׂק֩ וּ⁠מִ⁠בֵּ֨ין הַ⁠גִּלְעָ֜ד וּ⁠מִ⁠בֵּ֨ין אֶ֤רֶץ יִשְׂרָאֵל֙ הַ⁠יַּרְדֵּ֔ן מִ⁠גְּב֛וּל עַל־הַ⁠יָּ֥ם הַ⁠קַּדְמוֹנִ֖י תָּמֹ֑דּוּ וְ⁠אֵ֖ת פְּאַ֥ת קָדִֽימָ⁠ה׃","ẇ⁠pĕʼa֣ţ qádi֡ym mi⁠bé֣̇yn ẖawĕrá֣n ẇ⁠mi⁠bé̇yn-dȧmėşêq֩ ẇ⁠mi⁠bé̇֨yn ha⁠gi̇lĕʻá֜d ẇ⁠mi⁠bé̇֨yn ʼe֤reẕ yişĕ̂ráʼél֙ ha⁠yȧrĕdé̇֔n mi⁠gĕ̇b֛ẇl ʻal-ha⁠yá֥̇m ha⁠qȧdĕmwòni֖y ţá̇mò֑ḋẇ wĕ⁠ʼé֖ţ pĕ̇ʼa֥ţ qádiֽymá⁠h׃"],[47,19,"וּ⁠פְאַת֙ נֶ֣גֶב תֵּימָ֔נָ⁠ה מִ⁠תָּמָ֗ר עַד־מֵי֙ מְרִיב֣וֹת קָדֵ֔שׁ נַחֲלָ֖ה אֶל־הַ⁠יָּ֣ם הַ⁠גָּד֑וֹל וְ⁠אֵ֥ת פְּאַת־תֵּימָ֖נָ⁠ה נֶֽגְבָּ⁠ה׃","ẇ⁠pĕʼaţ֙ ne֣geb ţé̇ymá֔ná⁠h mi⁠ţá̇má֗r ʻad-méy֙ mĕriyb֣wòţ qádé֔ş̌ naẖàlá֖h ʼel-ha⁠yá֣̇m ha⁠gá̇d֑wòl wĕ⁠ʼé֥ţ pĕ̇ʼaţ-ţé̇ymá֖ná⁠h neֽgĕbá̇⁠h׃"],[47,20,"וּ⁠פְאַת־יָם֙ הַ⁠יָּ֣ם הַ⁠גָּד֔וֹל מִ⁠גְּב֕וּל עַד־נֹ֖כַח לְב֣וֹא חֲמָ֑ת זֹ֖את פְּאַת־יָֽם׃","ẇ⁠pĕʼaţ-yám֙ ha⁠yá֣̇m ha⁠gá̇d֔wòl mi⁠gĕ̇b֕ẇl ʻad-nò֖kaẖ lĕb֣wòʼ ẖàmá֑ţ zò֖ʼţ pĕ̇ʼaţ-yáֽm׃"],[47,21,"וְ⁠חִלַּקְתֶּ֞ם אֶת־הָ⁠אָ֧רֶץ הַ⁠זֹּ֛את לָ⁠כֶ֖ם לְ⁠שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠ẖilȧqĕţė֞m ʼeţ-há⁠ʼá֧reẕ ha⁠zò֛̇ʼţ lá⁠ke֖m lĕ⁠şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[47,22,"וְ⁠הָיָ֗ה תַּפִּ֣לוּ אוֹתָ⁠הּ֮ בְּ⁠נַחֲלָה֒ לָ⁠כֶ֗ם וּ⁠לְ⁠הַ⁠גֵּרִים֙ הַ⁠גָּרִ֣ים בְּ⁠תוֹכְ⁠כֶ֔ם אֲשֶׁר־הוֹלִ֥דוּ בָנִ֖ים בְּ⁠תֽוֹכְ⁠כֶ֑ם וְ⁠הָי֣וּ לָ⁠כֶ֗ם כְּ⁠אֶזְרָח֙ בִּ⁠בְנֵ֣י יִשְׂרָאֵ֔ל אִתְּ⁠כֶם֙ יִפְּל֣וּ בְ⁠נַחֲלָ֔ה בְּ⁠ת֖וֹךְ שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠háyá֗h ţȧpi֣̇lẇ ʼwòţá⁠ḣ֮ bĕ̇⁠naẖàláh֒ lá⁠ke֗m ẇ⁠lĕ⁠ha⁠gé̇riym֙ ha⁠gá̇ri֣ym bĕ̇⁠ţwòkĕ⁠ke֔m ʼàşěr-hwòli֥dẇ báni֖ym bĕ̇⁠ţֽwòkĕ⁠ke֑m wĕ⁠háy֣ẇ lá⁠ke֗m kĕ̇⁠ʼezĕráẖ֙ bi̇⁠bĕné֣y yişĕ̂ráʼé֔l ʼiţĕ̇⁠kem֙ yipĕ̇l֣ẇ bĕ⁠naẖàlá֔h bĕ̇⁠ţ֖wòkĕ şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[47,23,"וְ⁠הָיָ֣ה בַ⁠שֵּׁ֔בֶט אֲשֶׁר־גָּ֥ר הַ⁠גֵּ֖ר אִתּ֑⁠וֹ שָׁ֚ם תִּתְּנ֣וּ נַחֲלָת֔⁠וֹ נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃ס","wĕ⁠háyá֣h ba⁠şé̇̌֔bet ʼàşěr-gá֥̇r ha⁠gé֖̇r ʼiţ֑̇⁠wò şá֚̌m ţi̇ţĕ̇n֣ẇ naẖàláţ֔⁠wò nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃s"],[48,1,"וְ⁠אֵ֖לֶּה שְׁמ֣וֹת הַ⁠שְּׁבָטִ֑ים מִ⁠קְצֵ֣ה צָפ֡וֹנָ⁠ה אֶל־יַ֣ד דֶּֽרֶךְ־חֶתְלֹ֣ן ׀ לְֽבוֹא־חֲמָ֡ת חֲצַ֣ר עֵינָן֩ גְּב֨וּל דַּמֶּ֤שֶׂק צָפ֨וֹנָ⁠ה֙ אֶל־יַ֣ד חֲמָ֔ת וְ⁠הָיוּ־ל֧⁠וֹ פְאַת־קָדִ֛ים הַ⁠יָּ֖ם דָּ֥ן אֶחָֽד׃","wĕ⁠ʼé֖lėh şĕ̌m֣wòţ ha⁠şĕ̇̌báti֑ym mi⁠qĕẕé֣h ẕáp֡wòná⁠h ʼel-ya֣d dėֽrekĕ-ẖeţĕlò֣n ׀ lĕֽbwòʼ-ẖàmá֡ţ ẖàẕa֣r ʻéynán֩ gĕ̇b֨ẇl dȧmė֤şêq ẕáp֨wòná⁠h֙ ʼel-ya֣d ẖàmá֔ţ wĕ⁠háyẇ-l֧⁠wò pĕʼaţ-qádi֛ym ha⁠yá֖̇m dá֥̇n ʼeẖáֽd׃"],[48,2,"וְ⁠עַ֣ל ׀ גְּב֣וּל דָּ֗ן מִ⁠פְּאַ֥ת קָדִ֛ים עַד־פְּאַת־יָ֖מָּ⁠ה אָשֵׁ֥ר אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl dá̇֗n mi⁠pĕ̇ʼa֥ţ qádi֛ym ʻad-pĕ̇ʼaţ-yá֖má̇⁠h ʼáşé֥̌r ʼeẖáֽd׃"],[48,3,"וְ⁠עַ֣ל ׀ גְּב֣וּל אָשֵׁ֗ר מִ⁠פְּאַ֥ת קָדִ֛ימָ⁠ה וְ⁠עַד־פְּאַת־יָ֖מָּ⁠ה נַפְתָּלִ֥י אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl ʼáşé̌֗r mi⁠pĕ̇ʼa֥ţ qádi֛ymá⁠h wĕ⁠ʻad-pĕ̇ʼaţ-yá֖má̇⁠h napĕţá̇li֥y ʼeẖáֽd׃"],[48,4,"וְ⁠עַ֣ל ׀ גְּב֣וּל נַפְתָּלִ֗י מִ⁠פְּאַ֥ת קָדִ֛מָ⁠ה עַד־פְּאַת־יָ֖מָּ⁠ה מְנַשֶּׁ֥ה אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl napĕţá̇li֗y mi⁠pĕ̇ʼa֥ţ qádi֛má⁠h ʻad-pĕ̇ʼaţ-yá֖má̇⁠h mĕnaşė֥̌h ʼeẖáֽd׃"],[48,5,"וְ⁠עַ֣ל ׀ גְּב֣וּל מְנַשֶּׁ֗ה מִ⁠פְּאַ֥ת קָדִ֛מָ⁠ה עַד־פְּאַת־יָ֖מָּ⁠ה אֶפְרַ֥יִם אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl mĕnaşė̌֗h mi⁠pĕ̇ʼa֥ţ qádi֛má⁠h ʻad-pĕ̇ʼaţ-yá֖má̇⁠h ʼepĕra֥yim ʼeẖáֽd׃"],[48,6,"וְ⁠עַ֣ל ׀ גְּב֣וּל אֶפְרַ֗יִם מִ⁠פְּאַ֥ת קָדִ֛ים וְ⁠עַד־פְּאַת־יָ֖מָּ⁠ה רְאוּבֵ֥ן אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl ʼepĕra֗yim mi⁠pĕ̇ʼa֥ţ qádi֛ym wĕ⁠ʻad-pĕ̇ʼaţ-yá֖má̇⁠h rĕʼẇbé֥n ʼeẖáֽd׃"],[48,7,"וְ⁠עַ֣ל ׀ גְּב֣וּל רְאוּבֵ֗ן מִ⁠פְּאַ֥ת קָדִ֛ים עַד־פְּאַת־יָ֖מָּ⁠ה יְהוּדָ֥ה אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl rĕʼẇbé֗n mi⁠pĕ̇ʼa֥ţ qádi֛ym ʻad-pĕ̇ʼaţ-yá֖má̇⁠h yĕhẇdá֥h ʼeẖáֽd׃"],[48,8,"וְ⁠עַל֙ גְּב֣וּל יְהוּדָ֔ה מִ⁠פְּאַ֥ת קָדִ֖ים עַד־פְּאַת־יָ֑מָּ⁠ה תִּהְיֶ֣ה הַ⁠תְּרוּמָ֣ה אֲֽשֶׁר־תָּרִ֡ימוּ חֲמִשָּׁה֩ וְ⁠עֶשְׂרִ֨ים אֶ֜לֶף רֹ֗חַב וְ⁠אֹ֜רֶךְ כְּ⁠אַחַ֤ד הַ⁠חֲלָקִים֙ מִ⁠פְּאַ֤ת קָדִ֨ימָ⁠ה֙ עַד־פְּאַת־יָ֔מָּ⁠ה וְ⁠הָיָ֥ה הַ⁠מִּקְדָּ֖שׁ בְּ⁠תוֹכֽ⁠וֹ׃","wĕ⁠ʻal֙ gĕ̇b֣ẇl yĕhẇdá֔h mi⁠pĕ̇ʼa֥ţ qádi֖ym ʻad-pĕ̇ʼaţ-yá֑má̇⁠h ţi̇hĕye֣h ha⁠ţĕ̇rẇmá֣h ʼàֽşěr-ţá̇ri֡ymẇ ẖàmişá̇̌h֩ wĕ⁠ʻeşĕ̂ri֨ym ʼe֜lep rò֗ẖab wĕ⁠ʼò֜rekĕ kĕ̇⁠ʼaẖa֤d ha⁠ẖàláqiym֙ mi⁠pĕ̇ʼa֤ţ qádi֨ymá⁠h֙ ʻad-pĕ̇ʼaţ-yá֔má̇⁠h wĕ⁠háyá֥h ha⁠mi̇qĕdá֖̇ş̌ bĕ̇⁠ţwòkֽ⁠wò׃"],[48,9,"הַ⁠תְּרוּמָ֕ה אֲשֶׁ֥ר תָּרִ֖ימוּ לַֽ⁠יהוָ֑ה אֹ֗רֶךְ חֲמִשָּׁ֤ה וְ⁠עֶשְׂרִים֙ אֶ֔לֶף וְ⁠רֹ֖חַב עֲשֶׂ֥רֶת אֲלָפִֽים׃","ha⁠ţĕ̇rẇmá֕h ʼàşě֥r ţá̇ri֖ymẇ laֽ⁠yhwá֑h ʼò֗rekĕ ẖàmişá֤̇̌h wĕ⁠ʻeşĕ̂riym֙ ʼe֔lep wĕ⁠rò֖ẖab ʻàşê֥reţ ʼàlápiֽym׃"],[48,10,"וּ֠⁠לְ⁠אֵ֜לֶּה תִּהְיֶ֣ה תְרֽוּמַת־הַ⁠קֹּדֶשׁ֮ לַ⁠כֹּֽהֲנִים֒ צָפ֜וֹנָ⁠ה חֲמִשָּׁ֧ה וְ⁠עֶשְׂרִ֣ים אֶ֗לֶף וְ⁠יָ֨מָּ⁠ה֙ רֹ֚חַב עֲשֶׂ֣רֶת אֲלָפִ֔ים וְ⁠קָדִ֗ימָ⁠ה רֹ֚חַב עֲשֶׂ֣רֶת אֲלָפִ֔ים וְ⁠נֶ֕גְבָּ⁠ה אֹ֕רֶךְ חֲמִשָּׁ֥ה וְ⁠עֶשְׂרִ֖ים אָ֑לֶף וְ⁠הָיָ֥ה מִקְדַּשׁ־יְהוָ֖ה בְּ⁠תוֹכֽ⁠וֹ׃","ẇ֠⁠lĕ⁠ʼé֜lėh ţi̇hĕye֣h ţĕrֽẇmaţ-ha⁠qò̇deş֮̌ la⁠kòֽ̇hàniym֒ ẕáp֜wòná⁠h ẖàmişá֧̇̌h wĕ⁠ʻeşĕ̂ri֣ym ʼe֗lep wĕ⁠yá֨má̇⁠h֙ rò֚ẖab ʻàşê֣reţ ʼàlápi֔ym wĕ⁠qádi֗ymá⁠h rò֚ẖab ʻàşê֣reţ ʼàlápi֔ym wĕ⁠ne֕gĕbá̇⁠h ʼò֕rekĕ ẖàmişá֥̇̌h wĕ⁠ʻeşĕ̂ri֖ym ʼá֑lep wĕ⁠háyá֥h miqĕdȧş̌-yĕhwá֖h bĕ̇⁠ţwòkֽ⁠wò׃"],[48,11,"לַ⁠כֹּהֲנִ֤ים הַֽ⁠מְקֻדָּשׁ֙ מִ⁠בְּנֵ֣י צָד֔וֹק אֲשֶׁ֥ר שָׁמְר֖וּ מִשְׁמַרְתִּ֑⁠י אֲשֶׁ֣ר לֹֽא־תָע֗וּ בִּ⁠תְעוֹת֙ בְּנֵ֣י יִשְׂרָאֵ֔ל כַּ⁠אֲשֶׁ֥ר תָּע֖וּ הַ⁠לְוִיִּֽם׃ס","la⁠kò̇hàni֤ym haֽ⁠mĕqudá̇ş̌֙ mi⁠bĕ̇né֣y ẕád֔wòq ʼàşě֥r şá̌mĕr֖ẇ mişĕ̌marĕţi֑̇⁠y ʼàşě֣r lòֽʼ-ţáʻ֗ẇ bi̇⁠ţĕʻwòţ֙ bĕ̇né֣y yişĕ̂ráʼé֔l kȧ⁠ʼàşě֥r ţá̇ʻ֖ẇ ha⁠lĕwiyiֽ̇m׃s"],[48,12,"וְ⁠הָיְתָ֨ה לָ⁠הֶ֧ם תְּרוּמִיָּ֛ה מִ⁠תְּרוּמַ֥ת הָ⁠אָ֖רֶץ קֹ֣דֶשׁ קָדָשִׁ֑ים אֶל־גְּב֖וּל הַ⁠לְוִיִּֽם׃","wĕ⁠háyĕţá֨h lá⁠he֧m ţĕ̇rẇmiyá֛̇h mi⁠ţĕ̇rẇma֥ţ há⁠ʼá֖reẕ qò֣deş̌ qádáşǐ֑ym ʼel-gĕ̇b֖ẇl ha⁠lĕwiyiֽ̇m׃"],[48,13,"וְ⁠הַ⁠לְוִיִּ֗ם לְ⁠עֻמַּת֙ גְּב֣וּל הַ⁠כֹּהֲנִ֔ים חֲמִשָּׁ֨ה וְ⁠עֶשְׂרִ֥ים אֶ֨לֶף֙ אֹ֔רֶךְ וְ⁠רֹ֖חַב עֲשֶׂ֣רֶת אֲלָפִ֑ים כָּל־אֹ֗רֶךְ חֲמִשָּׁ֤ה וְ⁠עֶשְׂרִים֙ אֶ֔לֶף וְ⁠רֹ֖חַב עֲשֶׂ֥רֶת אֲלָפִֽים׃","wĕ⁠ha⁠lĕwiyi̇֗m lĕ⁠ʻumȧţ֙ gĕ̇b֣ẇl ha⁠kò̇hàni֔ym ẖàmişá̇̌֨h wĕ⁠ʻeşĕ̂ri֥ym ʼe֨lep֙ ʼò֔rekĕ wĕ⁠rò֖ẖab ʻàşê֣reţ ʼàlápi֑ym ká̇l-ʼò֗rekĕ ẖàmişá֤̇̌h wĕ⁠ʻeşĕ̂riym֙ ʼe֔lep wĕ⁠rò֖ẖab ʻàşê֥reţ ʼàlápiֽym׃"],[48,14,"וְ⁠לֹא־יִמְכְּר֣וּ מִמֶּ֗⁠נּוּ וְ⁠לֹ֥א יָמֵ֛ר וְ⁠לֹ֥א יעבור רֵאשִׁ֣ית הָ⁠אָ֑רֶץ כִּי־קֹ֖דֶשׁ לַ⁠יהוָֽה׃","wĕ⁠lòʼ-yimĕkĕ̇r֣ẇ mimė֗⁠ṅẇ wĕ⁠lò֥ʼ yámé֛r wĕ⁠lò֥ʼ yʻbwr réʼşǐ֣yţ há⁠ʼá֑reẕ ki̇y-qò֖deş̌ la⁠yhwáֽh׃"],[48,15,"וַ⁠חֲמֵ֨שֶׁת אֲלָפִ֜ים הַ⁠נּוֹתָ֣ר בָּ⁠רֹ֗חַב עַל־פְּנֵ֨י חֲמִשָּׁ֤ה וְ⁠עֶשְׂרִים֙ אֶ֔לֶף חֹֽל־ה֣וּא לָ⁠עִ֔יר לְ⁠מוֹשָׁ֖ב וּ⁠לְ⁠מִגְרָ֑שׁ וְ⁠הָיְתָ֥ה הָ⁠עִ֖יר ב⁠תוכ⁠ה׃","wa⁠ẖàmé֨şěţ ʼàlápi֜ym ha⁠ṅwòţá֣r bá̇⁠rò֗ẖab ʻal-pĕ̇né֨y ẖàmişá֤̇̌h wĕ⁠ʻeşĕ̂riym֙ ʼe֔lep ẖòֽl-h֣ẇʼ lá⁠ʻi֔yr lĕ⁠mwòşá֖̌b ẇ⁠lĕ⁠migĕrá֑ş̌ wĕ⁠háyĕţá֥h há⁠ʻi֖yr b⁠ţwk⁠h׃"],[48,16,"וְ⁠אֵלֶּה֮ מִדּוֹתֶי⁠הָ֒ פְּאַ֣ת צָפ֗וֹן חֲמֵ֤שׁ מֵאוֹת֙ וְ⁠אַרְבַּ֣עַת אֲלָפִ֔ים וּ⁠פְאַת־נֶ֕גֶב חֲמֵ֥שׁ חמש מֵא֖וֹת וְ⁠אַרְבַּ֣עַת אֲלָפִ֑ים וּ⁠מִ⁠פְּאַ֣ת קָדִ֗ים חֲמֵ֤שׁ מֵאוֹת֙ וְ⁠אַרְבַּ֣עַת אֲלָפִ֔ים וּ⁠פְאַת־יָ֕מָּ⁠ה חֲמֵ֥שׁ מֵא֖וֹת וְ⁠אַרְבַּ֥עַת אֲלָפִֽים׃","wĕ⁠ʼélėh֮ miḋwòţey⁠há֒ pĕ̇ʼa֣ţ ẕáp֗wòn ẖàmé֤ş̌ méʼwòţ֙ wĕ⁠ʼarĕbȧ֣ʻaţ ʼàlápi֔ym ẇ⁠pĕʼaţ-ne֕geb ẖàmé֥ş̌ ẖmş méʼ֖wòţ wĕ⁠ʼarĕbȧ֣ʻaţ ʼàlápi֑ym ẇ⁠mi⁠pĕ̇ʼa֣ţ qádi֗ym ẖàmé֤ş̌ méʼwòţ֙ wĕ⁠ʼarĕbȧ֣ʻaţ ʼàlápi֔ym ẇ⁠pĕʼaţ-yá֕má̇⁠h ẖàmé֥ş̌ méʼ֖wòţ wĕ⁠ʼarĕbȧ֥ʻaţ ʼàlápiֽym׃"],[48,17,"וְ⁠הָיָ֣ה מִגְרָשׁ֮ לָ⁠עִיר֒ צָפ֨וֹנָ⁠ה֙ חֲמִשִּׁ֣ים וּ⁠מָאתַ֔יִם וְ⁠נֶ֖גְבָּ⁠ה חֲמִשִּׁ֣ים וּ⁠מָאתָ֑יִם וְ⁠קָדִ֨ימָ⁠ה֙ חֲמִשִּׁ֣ים וּ⁠מָאתַ֔יִם וְ⁠יָ֖מָּ⁠ה חֲמִשִּׁ֥ים וּ⁠מָאתָֽיִם׃","wĕ⁠háyá֣h migĕráş֮̌ lá⁠ʻiyr֒ ẕáp֨wòná⁠h֙ ẖàmişi֣̇̌ym ẇ⁠máʼţa֔yim wĕ⁠ne֖gĕbá̇⁠h ẖàmişi֣̇̌ym ẇ⁠máʼţá֑yim wĕ⁠qádi֨ymá⁠h֙ ẖàmişi֣̇̌ym ẇ⁠máʼţa֔yim wĕ⁠yá֖má̇⁠h ẖàmişi֥̇̌ym ẇ⁠máʼţáֽyim׃"],[48,18,"וְ⁠הַ⁠נּוֹתָ֨ר בָּ⁠אֹ֜רֶךְ לְ⁠עֻמַּ֣ת ׀ תְּרוּמַ֣ת הַ⁠קֹּ֗דֶשׁ עֲשֶׂ֨רֶת אֲלָפִ֤ים קָדִ֨ימָ⁠ה֙ וַ⁠עֲשֶׂ֤רֶת אֲלָפִים֙ יָ֔מָּ⁠ה וְ⁠הָיָ֕ה לְ⁠עֻמַּ֖ת תְּרוּמַ֣ת הַ⁠קֹּ֑דֶשׁ וְ⁠הָיְתָ֤ה תבואת⁠ה לְ⁠לֶ֔חֶם לְ⁠עֹבְדֵ֖י הָ⁠עִֽיר׃","wĕ⁠ha⁠ṅwòţá֨r bá̇⁠ʼò֜rekĕ lĕ⁠ʻumȧ֣ţ ׀ ţĕ̇rẇma֣ţ ha⁠qò̇֗deş̌ ʻàşê֨reţ ʼàlápi֤ym qádi֨ymá⁠h֙ wa⁠ʻàşê֤reţ ʼàlápiym֙ yá֔má̇⁠h wĕ⁠háyá֕h lĕ⁠ʻumȧ֖ţ ţĕ̇rẇma֣ţ ha⁠qò֑̇deş̌ wĕ⁠háyĕţá֤h ţbwʼţ⁠h lĕ⁠le֔ẖem lĕ⁠ʻòbĕdé֖y há⁠ʻiֽyr׃"],[48,19,"וְ⁠הָ⁠עֹבֵ֖ד הָ⁠עִ֑יר יַעַבְד֕וּ⁠הוּ מִ⁠כֹּ֖ל שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","wĕ⁠há⁠ʻòbé֖d há⁠ʻi֑yr yaʻabĕd֕ẇ⁠hẇ mi⁠kò֖̇l şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[48,20,"כָּל־הַ⁠תְּרוּמָ֗ה חֲמִשָּׁ֤ה וְ⁠עֶשְׂרִים֙ אֶ֔לֶף בַּ⁠חֲמִשָּׁ֥ה וְ⁠עֶשְׂרִ֖ים אָ֑לֶף רְבִיעִ֗ית תָּרִ֨ימוּ֙ אֶת־תְּרוּמַ֣ת הַ⁠קֹּ֔דֶשׁ אֶל־אֲחֻזַּ֖ת הָ⁠עִֽיר׃","ká̇l-ha⁠ţĕ̇rẇmá֗h ẖàmişá֤̇̌h wĕ⁠ʻeşĕ̂riym֙ ʼe֔lep bȧ⁠ẖàmişá֥̇̌h wĕ⁠ʻeşĕ̂ri֖ym ʼá֑lep rĕbiyʻi֗yţ ţá̇ri֨ymẇ֙ ʼeţ-ţĕ̇rẇma֣ţ ha⁠qò̇֔deş̌ ʼel-ʼàẖuzȧ֖ţ há⁠ʻiֽyr׃"],[48,21,"וְ⁠הַ⁠נּוֹתָ֣ר לַ⁠נָּשִׂ֣יא מִ⁠זֶּ֣ה ׀ וּ⁠מִ⁠זֶּ֣ה ׀ לִ⁠תְרֽוּמַת־הַ⁠קֹּ֣דֶשׁ וְ⁠לַ⁠אֲחֻזַּ֪ת הָ⁠עִ֟יר אֶל־פְּנֵ֣י חֲמִשָּׁה֩ וְ⁠עֶשְׂרִ֨ים אֶ֥לֶף ׀ תְּרוּמָה֮ עַד־גְּב֣וּל קָדִימָ⁠ה֒ וְ⁠יָ֗מָּ⁠ה עַל־פְּ֠נֵי חֲמִשָּׁ֨ה וְ⁠עֶשְׂרִ֥ים אֶ֨לֶף֙ עַל־גְּב֣וּל יָ֔מָּ⁠ה לְ⁠עֻמַּ֥ת חֲלָקִ֖ים לַ⁠נָּשִׂ֑יא וְ⁠הָֽיְתָה֙ תְּרוּמַ֣ת הַ⁠קֹּ֔דֶשׁ וּ⁠מִקְדַּ֥שׁ הַ⁠בַּ֖יִת ב⁠תוכ⁠ה׃","wĕ⁠ha⁠ṅwòţá֣r la⁠ná̇şî֣yʼ mi⁠zė֣h ׀ ẇ⁠mi⁠zė֣h ׀ li⁠ţĕrֽẇmaţ-ha⁠qò֣̇deş̌ wĕ⁠la⁠ʼàẖuzȧ֪ţ há⁠ʻi֟yr ʼel-pĕ̇né֣y ẖàmişá̇̌h֩ wĕ⁠ʻeşĕ̂ri֨ym ʼe֥lep ׀ ţĕ̇rẇmáh֮ ʻad-gĕ̇b֣ẇl qádiymá⁠h֒ wĕ⁠yá֗má̇⁠h ʻal-pĕ̇֠néy ẖàmişá̇̌֨h wĕ⁠ʻeşĕ̂ri֥ym ʼe֨lep֙ ʻal-gĕ̇b֣ẇl yá֔má̇⁠h lĕ⁠ʻumȧ֥ţ ẖàláqi֖ym la⁠ná̇şî֑yʼ wĕ⁠háֽyĕţáh֙ ţĕ̇rẇma֣ţ ha⁠qò̇֔deş̌ ẇ⁠miqĕdȧ֥ş̌ ha⁠bȧ֖yiţ b⁠ţwk⁠h׃"],[48,22,"וּ⁠מֵ⁠אֲחֻזַּ֤ת הַ⁠לְוִיִּם֙ וּ⁠מֵ⁠אֲחֻזַּ֣ת הָ⁠עִ֔יר בְּ⁠ת֛וֹךְ אֲשֶׁ֥ר לַ⁠נָּשִׂ֖יא יִֽהְיֶ֑ה בֵּ֣ין ׀ גְּב֣וּל יְהוּדָ֗ה וּ⁠בֵין֙ גְּב֣וּל בִּנְיָמִ֔ן לַ⁠נָּשִׂ֖יא יִהְיֶֽה׃","ẇ⁠mé⁠ʼàẖuzȧ֤ţ ha⁠lĕwiyi̇m֙ ẇ⁠mé⁠ʼàẖuzȧ֣ţ há⁠ʻi֔yr bĕ̇⁠ţ֛wòkĕ ʼàşě֥r la⁠ná̇şî֖yʼ yiֽhĕye֑h bé֣̇yn ׀ gĕ̇b֣ẇl yĕhẇdá֗h ẇ⁠béyn֙ gĕ̇b֣ẇl bi̇nĕyámi֔n la⁠ná̇şî֖yʼ yihĕyeֽh׃"],[48,23,"וְ⁠יֶ֖תֶר הַ⁠שְּׁבָטִ֑ים מִ⁠פְּאַ֥ת קָדִ֛ימָ⁠ה עַד־פְּאַת־יָ֖מָּ⁠ה בִּנְיָמִ֥ן אֶחָֽד׃","wĕ⁠ye֖ţer ha⁠şĕ̇̌báti֑ym mi⁠pĕ̇ʼa֥ţ qádi֛ymá⁠h ʻad-pĕ̇ʼaţ-yá֖má̇⁠h bi̇nĕyámi֥n ʼeẖáֽd׃"],[48,24,"וְ⁠עַ֣ל ׀ גְּב֣וּל בִּנְיָמִ֗ן מִ⁠פְּאַ֥ת קָדִ֛ימָ⁠ה עַד־פְּאַת־יָ֖מָּ⁠ה שִׁמְע֥וֹן אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl bi̇nĕyámi֗n mi⁠pĕ̇ʼa֥ţ qádi֛ymá⁠h ʻad-pĕ̇ʼaţ-yá֖má̇⁠h şǐmĕʻ֥wòn ʼeẖáֽd׃"],[48,25,"וְ⁠עַ֣ל ׀ גְּב֣וּל שִׁמְע֗וֹן מִ⁠פְּאַ֥ת קָדִ֛ימָ⁠ה עַד־פְּאַת־יָ֖מָּ⁠ה יִשָׂשכָ֥ר אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl şǐmĕʻ֗wòn mi⁠pĕ̇ʼa֥ţ qádi֛ymá⁠h ʻad-pĕ̇ʼaţ-yá֖má̇⁠h yişá̂şká֥r ʼeẖáֽd׃"],[48,26,"וְ⁠עַ֣ל ׀ גְּב֣וּל יִשָׂשכָ֗ר מִ⁠פְּאַ֥ת קָדִ֛ימָ⁠ה עַד־פְּאַת־יָ֖מָּ⁠ה זְבוּלֻ֥ן אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl yişá̂şká֗r mi⁠pĕ̇ʼa֥ţ qádi֛ymá⁠h ʻad-pĕ̇ʼaţ-yá֖má̇⁠h zĕbẇlu֥n ʼeẖáֽd׃"],[48,27,"וְ⁠עַ֣ל ׀ גְּב֣וּל זְבוּלֻ֗ן מִ⁠פְּאַ֥ת קָדִ֛מָ⁠ה עַד־פְּאַת־יָ֖מָּ⁠ה גָּ֥ד אֶחָֽד׃","wĕ⁠ʻa֣l ׀ gĕ̇b֣ẇl zĕbẇlu֗n mi⁠pĕ̇ʼa֥ţ qádi֛má⁠h ʻad-pĕ̇ʼaţ-yá֖má̇⁠h gá֥̇d ʼeẖáֽd׃"],[48,28,"וְ⁠עַל֙ גְּב֣וּל גָּ֔ד אֶל־פְּאַ֖ת נֶ֣גֶב תֵּימָ֑נָ⁠ה וְ⁠הָיָ֨ה גְב֜וּל מִ⁠תָּמָ֗ר מֵ֚י מְרִיבַ֣ת קָדֵ֔שׁ נַחֲלָ֖ה עַל־הַ⁠יָּ֥ם הַ⁠גָּדֽוֹל׃","wĕ⁠ʻal֙ gĕ̇b֣ẇl gá̇֔d ʼel-pĕ̇ʼa֖ţ ne֣geb ţé̇ymá֑ná⁠h wĕ⁠háyá֨h gĕb֜ẇl mi⁠ţá̇má֗r mé֚y mĕriyba֣ţ qádé֔ş̌ naẖàlá֖h ʻal-ha⁠yá֥̇m ha⁠gá̇dֽwòl׃"],[48,29,"זֹ֥את הָ⁠אָ֛רֶץ אֲשֶׁר־תַּפִּ֥ילוּ מִֽ⁠נַּחֲלָ֖ה לְ⁠שִׁבְטֵ֣י יִשְׂרָאֵ֑ל וְ⁠אֵ֨לֶּה֙ מַחְלְקוֹתָ֔⁠ם נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃פ","zò֥ʼţ há⁠ʼá֛reẕ ʼàşěr-ţȧpi֥̇ylẇ miֽ⁠nȧẖàlá֖h lĕ⁠şǐbĕté֣y yişĕ̂ráʼé֑l wĕ⁠ʼé֨lėh֙ maẖĕlĕqwòţá֔⁠m nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃p"],[48,30,"וְ⁠אֵ֖לֶּה תּוֹצְאֹ֣ת הָ⁠עִ֑יר מִ⁠פְּאַ֣ת צָפ֔וֹן חֲמֵ֥שׁ מֵא֛וֹת וְ⁠אַרְבַּ֥עַת אֲלָפִ֖ים מִדָּֽה׃","wĕ⁠ʼé֖lėh ţ̇wòẕĕʼò֣ţ há⁠ʻi֑yr mi⁠pĕ̇ʼa֣ţ ẕáp֔wòn ẖàmé֥ş̌ méʼ֛wòţ wĕ⁠ʼarĕbȧ֥ʻaţ ʼàlápi֖ym midáֽ̇h׃"],[48,31,"וְ⁠שַׁעֲרֵ֣י הָ⁠עִ֗יר עַל־שְׁמוֹת֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל שְׁעָרִ֥ים שְׁלוֹשָׁ֖ה צָפ֑וֹנָ⁠ה שַׁ֣עַר רְאוּבֵ֞ן אֶחָ֗ד שַׁ֤עַר יְהוּדָה֙ אֶחָ֔ד שַׁ֥עַר לֵוִ֖י אֶחָֽד׃","wĕ⁠şǎʻàré֣y há⁠ʻi֗yr ʻal-şĕ̌mwòţ֙ şǐbĕté֣y yişĕ̂ráʼé֔l şĕ̌ʻári֥ym şĕ̌lwòşá֖̌h ẕáp֑wòná⁠h şǎ֣ʻar rĕʼẇbé֞n ʼeẖá֗d şǎ֤ʻar yĕhẇdáh֙ ʼeẖá֔d şǎ֥ʻar léwi֖y ʼeẖáֽd׃"],[48,32,"וְ⁠אֶל־פְּאַ֣ת קָדִ֗ימָ⁠ה חֲמֵ֤שׁ מֵאוֹת֙ וְ⁠אַרְבַּ֣עַת אֲלָפִ֔ים וּ⁠שְׁעָרִ֖ים שְׁלֹשָׁ֑ה וְ⁠שַׁ֨עַר יוֹסֵ֜ף אֶחָ֗ד שַׁ֤עַר בִּנְיָמִן֙ אֶחָ֔ד שַׁ֥עַר דָּ֖ן אֶחָֽד׃","wĕ⁠ʼel-pĕ̇ʼa֣ţ qádi֗ymá⁠h ẖàmé֤ş̌ méʼwòţ֙ wĕ⁠ʼarĕbȧ֣ʻaţ ʼàlápi֔ym ẇ⁠şĕ̌ʻári֖ym şĕ̌lòşá֑̌h wĕ⁠şǎ֨ʻar ywòsé֜p ʼeẖá֗d şǎ֤ʻar bi̇nĕyámin֙ ʼeẖá֔d şǎ֥ʻar dá֖̇n ʼeẖáֽd׃"],[48,33,"וּ⁠פְאַת־נֶ֗גְבָּ⁠ה חֲמֵ֨שׁ מֵא֜וֹת וְ⁠אַרְבַּ֤עַת אֲלָפִים֙ מִדָּ֔ה וּ⁠שְׁעָרִ֖ים שְׁלֹשָׁ֑ה שַׁ֣עַר שִׁמְע֞וֹן אֶחָ֗ד שַׁ֤עַר יִשָּׂשכָר֙ אֶחָ֔ד שַׁ֥עַר זְבוּלֻ֖ן אֶחָֽד׃","ẇ⁠pĕʼaţ-ne֗gĕbá̇⁠h ẖàmé֨ş̌ méʼ֜wòţ wĕ⁠ʼarĕbȧ֤ʻaţ ʼàlápiym֙ midá̇֔h ẇ⁠şĕ̌ʻári֖ym şĕ̌lòşá֑̌h şǎ֣ʻar şǐmĕʻ֞wòn ʼeẖá֗d şǎ֤ʻar yişá̇̂şkár֙ ʼeẖá֔d şǎ֥ʻar zĕbẇlu֖n ʼeẖáֽd׃"],[48,34,"פְּאַת־יָ֗מָּ⁠ה חֲמֵ֤שׁ מֵאוֹת֙ וְ⁠אַרְבַּ֣עַת אֲלָפִ֔ים שַֽׁעֲרֵי⁠הֶ֖ם שְׁלֹשָׁ֑ה שַׁ֣עַר גָּ֞ד אֶחָ֗ד שַׁ֤עַר אָשֵׁר֙ אֶחָ֔ד שַׁ֥עַר נַפְתָּלִ֖י אֶחָֽד׃","pĕ̇ʼaţ-yá֗má̇⁠h ẖàmé֤ş̌ méʼwòţ֙ wĕ⁠ʼarĕbȧ֣ʻaţ ʼàlápi֔ym şǎֽʻàréy⁠he֖m şĕ̌lòşá֑̌h şǎ֣ʻar gá̇֞d ʼeẖá֗d şǎ֤ʻar ʼáşé̌r֙ ʼeẖá֔d şǎ֥ʻar napĕţá̇li֖y ʼeẖáֽd׃"],[48,35,"סָבִ֕יב שְׁמֹנָ֥ה עָשָׂ֖ר אָ֑לֶף וְ⁠שֵׁם־הָ⁠עִ֥יר מִ⁠יּ֖וֹם יְהוָ֥ה ׀ שָֽׁמָּ⁠ה׃","sábi֕yb şĕ̌mòná֥h ʻáşá֖̂r ʼá֑lep wĕ⁠şé̌m-há⁠ʻi֥yr mi⁠ẏ֖wòm yĕhwá֥h ׀ şáֽ̌má̇⁠h׃"]]}};